INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'În Numele lui Allah Cel Milostiv [Ar-Rahman], Îndurător [Ar-Rahim],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, '[Toată] Lauda [I se cuvine] lui Allah, Stăpânitorul lumilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Cel Milostiv, Îndurător,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'Suveranul Zilei Judecății.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'Numai pe Tine Te adorăm, numai la Tine cerem ajutor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Călăuzește-ne pe noi către Calea cea Dreaptă[1],', '[1] Islamul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'Calea celor asupra cărora Tu ai revărsat Îndurarea Ta, nu a celor pe care Tu Te-ai mâniat, și nici a celor care au rătăcit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Alif, Lam, Mim[1]', '[1] Acestea se află printre cele 14 litere de deschidere ce apar în diverse combinații la începutul a 29 de capitole din Coran. Deși s-au făcut multe speculații cu privire la semnificația lor, de fapt Allah nu a revelat nimănui înțelesul lor.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Aceasta este Cartea[2] despre care nu există nicio îndoială; Ea este Călăuză pentru cei pioși [care au frică de Allah și Îl iubesc, efectuând fapte bune],', '[2] Cartea este deseori folosită cu sensul de Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'Care cred în cele nevăzute și îndeplinesc Rugăciunea și fac milostenie din ceea ce le-am dăruit Noi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'Și care cred în ceea ce ți-a fost revelat ție [o, Mohammed] și în ceea ce a fost revelat înaintea ta și care cred în Viața de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Aceia sunt călăuziți de Domnul lor și aceia sunt învingători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Cu adevărat, pentru cei care nu cred e totuna de-i previi sau nu-i previi; ei tot nu cred[3]', '[3] Sunt avuți în vedere ipocriții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Allah a zăvorât inimile și urechile lor, iar peste ochii lor este un văl. Și ei vor avea [parte de] o pedeapsă mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'Și printre oameni sunt unii care spun: „Noi credem în Allah și în Ziua de Apoi”, dar ei nu sunt credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'Ei [se gândesc] să-L înșele pe Allah și pe cei care cred, dar nu se înșeală decât pe ei înșiși, și nu își dau seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'În inimile lor este o boală[4], iar Allah le va spori boala și vor avea parte de o pedeapsă dureroasă pentru că ei obișnuiau să mintă.', '[4] „Boala” menționată aici include îndoială, ipocrizie, aroganță și necredință');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Iar dacă li se spune: „Nu faceți stricăciune pe pământ!”, ei zic: „Dar noi suntem făcători de bine”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Cu adevărat, ei sunt cei făcători de stricăciune, dar nu-și dau seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Iar atunci când li se spune: „Credeți, așa cum au crezut oamenii!”, ei zic: „Să credem precum au crezut cei fără de minte?”. Cu adevărat ei sunt cei fără de minte, dar nu știu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'Iar atunci când se întâlnesc cu cei care au crezut, ei spun: „Noi credem.”, însă când rămân singuri cu Șeitanii[5] lor, spun: „Noi suntem cu voi, doar ne batem joc”.', '[5] „Căpeteniile lor”, dar și „semenii lor întru rău”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, '[Dar] Allah îi ridiculizează și le prelungește fărădelegea [în timp ce] ei rătăcesc în neștire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'Aceia sunt cei care au schimbat calea cea dreaptă cu rătăcirea, dar negoțul lor nu le-a adus câștig și ei nu au fost călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Exemplul lor este precum al celui care a aprins un foc, dar când a luminat ceea ce se afla în jurul lui, Allah le-a luat lumina[6] și i-a lăsat în întuneric, iar ei nu mai văd nimic.', '[6] Cineva aprinde focul pentru o singură persoană, iar lumina se revarsă asupra tuturor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, '[Ei sunt] surzi, muți, orbi și nu se întorc [la Calea cea Dreaptă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Sau [sunt] precum o ploaie puternică ce cade din cer însoțită de întuneric, tunet și fulger. Ei își pun degetele în urechi din pricina trăsnetelor, de frica morții, dar Allah îi împresoară pe necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Fulgerul aproape că le răpește văzul. De fiecare dată când le luminează [calea], ei înaintează, dar când se lasă întunericul, se opresc. Iar dacă Allah ar fi Vrut, le-ar fi luat auzul și văzul. Cu adevărat Allah este peste toate cu Putere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'O, voi oameni, slăviți-L pe Domnul vostru, care v-a creat pe voi și pe cei de dinaintea voastră, pentru ca voi să aveți frică [de El].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, '[Cel] care a făcut Pământul un pat[7] și Cerul o zidire și a pogorât din Cer ploaie și a scos prin ea fructe drept hrană pentru voi. Așadar, nu-i faceți lui Allah parteneri în timp ce voi știți [toate acestea]!', '[7] Loc de odihnă stabil');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'Iar dacă vă îndoiți de cele pe care i le-am revelat robului Nostru [Mohammed], aduceți o Sură asemănătoare și chemați-vă martorii [susținătorii] cei în afară de Allah, dacă sunteți sinceri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Și dacă nu o faceți - și nu o veți putea face - atunci feriți-vă de Focul care mistuie oamenii și pietrele, pregătit pentru necredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'Și spune-le celor care cred și fac fapte bune că ei vor avea Grădini [în Paradis] pe sub care curg râuri! De câte ori vor primi din ele un rod, ca hrană, vor zice: „Acestea sunt cele pe care le-am primit și mai înainte!”, căci li s-au dat [lor și altele] asemănătoare cu ele. Și ei vor avea în ele soții curate și în ele veșnic vor fi sălășluitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Cu adevărat Allah nu se sfiește să dea ca exemplu un țânțar sau ceva deasupra lui[8]. Iar cei care au crezut știu că este adevărul de la Domnul lor. Cât despre cei care nu cred, ei spun: „Ce a vrut Allah cu acest exemplu?”. Prin el, îi rătăcește pe mulți și îi călăuzește pe mulți, dar nu îi rătăcește decât numai pe cei nelegiuiți.', '[8] Literar „deasupra lui” adică mult mai mic.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, 'Care încalcă legământul cu Allah, după încheierea lui, și despart ceea ce Allah a Poruncit să fie împreună și fac stricăciune pe Pământ. Ei sunt cei care pierd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Cum de nu credeți în Allah când ați fost fără viață și El v-a dat viață, apoi El vă va face să muriți, apoi vă va învia și apoi la El vă veți întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'El este Acela care a creat pentru voi toate câte sunt pe Pământ, apoi S-a înălțat la Cer [Allah se află deasupra creației] și a făcut cele șapte Ceruri și El este Știutorul tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'Și [spune, o, Mohammed] atunci când Stăpânul tău le-a zis Îngerilor: „Cu adevărat voi pune pe Pământ un succesor [khalifa]”, ei i-au răspuns: „Vei pune pe cineva care să facă stricăciune pe el și să pricinuiască vărsare de sânge, când noi îți aducem Slavă Ție și pe Tine Te adorăm cu sfințenie?” Și [Allah] a zis: „Eu Știu ceea ce voi nu știți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'Și l-a învățat pe Adam numele tuturor lucrurilor. Apoi le-a arătat Îngerilor și le-a zis: „Vestiți-Mi Mie numele acestora, dacă voi sunteți sinceri!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, 'Ei au răspuns: „Mărire Ție! Noi nu știm decât despre ceea ce Tu ne-ai învățat, căci Tu ești Al-Alim [Atoateștiutorul], Al-Hakim [Înțeleptul]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, 'El a spus: „O, Adam, vestește-le numele lor!” Și după ce le-a vestit numele lor, El a spus: „Nu v-am spus că Eu le Știu pe cele nevăzute din Ceruri și de pe Pământ? Și Eu Știu ceea ce dezvăluiți și ceea ce ascundeți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'Și [spune] atunci când le-am spus Îngerilor: „Prosternați-vă dinaintea lui Adam!” Și s-au prosternat, cu excepția lui Iblis[9], care s-a împotrivit, a fost arogant și a devenit unul dintre necredincioși.', '[9] Nume propriu al diavolului, conducătorul lor, unul dintre djinni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'Și Noi am spus: „O, Adam, sălășluiește tu împreună cu soața ta în Paradis! Mâncați din el pe îndestulate, ori de unde voiți, dar să nu vă apropiați de acest pom, pentru ca să nu fiți dintre cei nedrepți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Dar Şeitan i-a ademenit [să mănânce] din el și i-a scos pe ei de unde se aflau[10]. Și le-am zis lor: „Coborâți și dușmani vă veți fi unul altuia [diavolul vouă și voi lui]! Și veți avea pe Pământ un sălaș și provizii pentru un timp!”', '[10] Din condiția în care se aflau');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'Apoi Adam a primit de la Domnul său cuvinte[11] și El i-a acceptat căința. Cu adevărat El este At-Tauuab [Iertător], Ar-Rahim [Îndurător].', '[11] Allah l-a învățat pe Adam cuvinte cu care să se roage pentru a se căi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Noi am zis: „Coborâți [din Rai] cu toții și când va veni la voi o Călăuzire[12] de la Mine, cei care vor urma Călăuzirea Mea nu vor avea [motive de] temeri și nici nu se vor întrista.', '[12] Un Trimis al meu pentru a vă transmite credința în Allah și a vă călăuzi pe Calea cea Dreaptă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'Iar aceia care nu cred și nu acceptă semnele Noastre, aceia vor fi părtașii Focului și în el se vor afla veșnic.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'O, voi Fii ai lui Israel, aduceți-vă aminte de binele pe care vi l-am făcut și țineți-vă legământul făcut Mie, iar Eu îmi voi ține legământul făcut vouă și aveți frică [doar] față de Mine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'Credeți în ceea ce v-am trimis, confirmând ceea ce voi aveți [deja] și nu fiți primii care nu cred în el. Și nu vindeți semnele Mele pentru un preț mic și aveți frică [doar] față de Mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'Și nu amestecați adevărul cu minciuna și nu ascundeți adevărul, când voi [îl] știți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'Efectuați Rugăciunea, oferiți Zakat[13] și plecați-vă împreună cu cei care se pleacă!', '[13] O plată anuală făcută pentru beneficiul comunității musulmane (vezi 9:60) obligatorie pentru musulmanii înstăriți. Rugăciunea și Zakat-ul fac parte din stâlpii Islamului.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'Voi le porunciți oamenilor dreptatea, dar uitați de voi înșivă, cu toate că voi citiți Scriptura? Voi nu pricepeți?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Și căutați ajutor prin răbdare și Rugăciune! Într-adevăr ea este grea, însă nu pentru cei care I se supun [lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, 'Care cred că Îl vor întâlni pe Domnul lor și care cred că la El se vor întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'O, voi, Fii ai lui Israel, aduceți-vă aminte de binele pe care vi l-am făcut și că Eu v-am preferat înaintea lumilor [popoarelor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'Și fiți cu frică de o Zi în care niciun suflet nu va putea face nimic pentru alt suflet și nu se va primi nicio mijlocire de la el, nici nu se va lua de la el schimb și nici nu vor putea fi ele ajutate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, '[Și aduceți-vă aminte] când Noi v-am salvat [pe strămoșii voștri] de poporul lui Faraon, care v-a supus la chinuri groaznice, omorându-vă copiii [nou-născuți] și cruțând viața femeilor voastre! În aceasta a fost o mare încercare de la Domnul vostru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'Și [aduceți-vă aminte] când Noi am despărțit marea pentru voi și v-am salvat pe voi și am înecat neamul lui Faraon, în timp ce voi priveați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'Și [aduceți-vă aminte] când Ne-am înțeles cu Moise pentru patruzeci de nopți[14], iar voi ați ales vițelul [pentru a-l adora], în lipsa lui [Moise] și ați fost voi nelegiuiți.', '[14] Să-i pogoare Allah Tora');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Apoi v-am iertat pe voi, după aceea, poate că veți fi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, 'Și [aduceți-vă aminte] când Noi i-am dat lui Moise Scriptura și Legea[15] pentru ca voi să fiți călăuziți.', '[15] Diferențierea dintre adevăr și minciună. „Scriptura și Legea” se referă la Tora');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'Și [aduceți-vă aminte] când Moise i-a spus poporului său: „O, neam al meu, cu adevărat ați fost nedrepți cu voi înșivă prin adorarea vițelului. Deci cereți iertare Creatorului vostru și răpuneți-vă unii pe alții [pe cei vinovați dintre voi]. Aceasta este mai bine pentru voi la Creatorul vostru, iar El v-a acceptat căința, căci El este At-Tauuab [Iertător], Ar-Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'Și [aduceți-vă aminte] când ați spus: „O, Moise! Nu te vom crede până când nu-L vom vedea pe Allah deslușit. Și trăsnetul v-a ucis în timp ce voi priveați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Apoi v-am înviat după ce ați murit, poate că veți fi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'Și am făcut să vă umbrească nori și v-am trimis mana și prepelițe [spunând:] „Mâncați din bunătățile pe care vi le-am dăruit!” Iar ei nu au fost nedrepți cu Noi, ci [doar] față de ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'Și [aduceți-vă aminte] când Noi am spus: „Intrați în această cetate [Ierusalim] și mâncați [din bunătățile ei] oriunde veți dori și intrați pe poartă cu smerenie și spuneți: „Ușurează-ne nouă greutățile [păcatele]”, iar Noi vă vom ierta păcatele și le vom înmulți [răsplata] celor care fac bine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Dar cei nedrepți au schimbat [cuvintele] cu altele decât cele care li s-au poruncit și am trimis asupra celor care au fost nedrepți, pedeapsă din Cer, pentru că ei au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'Și [aduceți-vă aminte] când Moise a cerut apă pentru poporul său și i-am spus: „Lovește stânca cu toiagul tău!” Și au țâșnit din ea douăsprezece izvoare și fiecare popor și-a cunoscut locul său de băut. „Mâncați și beți din proviziile lui Allah și nu faceți rău pe Pământ!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'Și [aduceți-vă aminte] când ați spus voi: „O, Moise! Nu vom putea îndura un singur fel de mâncare! Roagă-te la Domnul tău să scoată pentru noi din ceea ce dă pământul, din [roadele lui]: ierburi verzi, castraveți, usturoi, linte și ceapă!” A zis el: „Vreți să schimbați ce este mai bun cu ceea ce este mai rău? Mergeți în [orice altă] cetate și veți avea ceea ce ați cerut!” Și a căzut asupra lor umilință și sărăcie și s-au întors însoțiți de mânia lui Allah. Aceasta pentru că ei nu au crezut [în mod repetat] în semnele lui Allah și i-au ucis pe Profeți pe nedrept. Aceasta pentru că ei nu au ascultat și nu au respectat [în mod repetat] legile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Cu adevărat, cei care au crezut și cei care erau evrei sau creștini sau sabeeni [înainte de profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)], cei care au crezut în Allah și în Ziua Judecății și au făcut bine, vor avea răsplata lor de la Domnul lor și nu se vor teme și nici nu se vor mâhni[16].', '[16] Allah nu va accepta nicio altă religie după venirea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) așa cum este menționat în 3:85');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, 'Și [aduceți-vă aminte] când Noi am încheiat legământul cu voi [O, Fii ai lui Israel, pentru ca voi să dați ascultare Torei] și am ridicat deasupra voastră muntele [spunând]: „Țineți ceea ce v-am dat cu tărie și amintiți-vă ceea ce este într-aceea, poate că veți fi cu frică.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Apoi v-ați îndepărtat după aceea și dacă nu ar fi fost Binecuvântarea lui Allah și Îndurarea Lui asupra voastră, ați fi fost printre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Și voi ați știut ce au pățit aceia dintre voi care au nerespectat Sabatul și le-am spus: „Fiți maimuțe disprețuite!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'Și am făcut-o o pedeapsă pentru cei din vremea lor și pentru cei de după ei și o lecție pentru cei ce au frică de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'Și [aduceți-vă aminte] când Moise i-a spus poporului său: „Cu adevărat, Allah vă poruncește să sacrificați o vacă!” Și ei au răspuns: „Ne iei în derâdere?” Iar el le-a răspuns: „Caut refugiu la Allah pentru a nu fi dintre cei ignoranți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, 'Ei au spus: „Roagă-te pentru noi Domnului tău să ne arate limpede cum să fie!” [Moise] a răspuns: „[Allah] spune «Să fie o vacă nici prea bătrână, nici prea tânără, ci de vârstă mijlocie» și faceți ce vi se poruncește!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, 'Ei au spus: „Roagă-te pentru noi Domnului tău să ne arate limpede culoarea ei!” A răspuns: „El spune «Să fie o vacă de culoare galben strălucitor, plăcută la privire.»”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, 'Ei au spus: „Roagă-te pentru noi Domnului tău să ne arate care să fie ea, căci pentru noi vacile sunt la fel. Și cu adevărat dacă Allah va Voi, vom fi călăuziți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, 'El a spus: „El zice «Să nu fie o vacă ce ară pământul și adapă semănăturile, ci una sănătoasă, fără nicio pată pe ea.»” Ei au spus: „Acum ai adus adevărul!” Și au sacrificat-o, dar puțin a lipsit să nu o facă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'Și [aduceți-vă aminte] când ați omorât un suflet și v-ați învinuit unii pe alții, dar Allah a scos la iveală ceea ce voi țineați ascuns!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, 'Și Noi am spus: „Loviți-l pe el [pe cel omorât] cu o bucată din ea!”[17] Așa Allah îi va readuce la viață pe cei morți și El vă arată semnele Sale, poate că astfel o să pricepeți.', '[17] Din vacă. Apoi Allah l-a readus la viață pe om, care le-a spus cine l-a omorât.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'După acea inimile voastre s-au întărit asemenea pietrelor și poate și mai tare. Pentru că, într-adevăr, sunt pietre din care țâșnesc râuri, iar altele se despică și iese din ele apă și sunt altele ce se prăbușesc de frica lui Allah. Iar Allah Știe ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Sperați voi [o, credincioșilor] ca ei să creadă cu voi, când o parte dintre ei au auzit Cuvântul lui Allah [Tora] și apoi l-au răstălmăcit, după ce l-au priceput, cu buna lor știință?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Și când se întâlnesc cu cei care cred, ei spun: „Noi credem!” Dar când rămân numai între ei, spun: „Voi le vorbiți despre ceea ce Allah v-a revelat pentru ca ei să se certe cu voi pentru aceasta dinaintea Domnului vostru?” Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'Nu știu ei că Allah Știe atât ceea ce ei ascund, cât și ceea ce ei rostesc cu glas tare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'Și printre ei sunt neînvățați care nu cunosc Scriptura, ci au doar năluciri, și ei doar bănuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'Dar vai[18] acelora care scriu Scriptura cu mâinile lor și apoi spun „Aceasta este de la Allah!”, pentru a obține un preț mic! Vai pentru ceea ce mâinile lor au scris și vai lor pentru ceea ce câștigă!', '[18] Moarte și distrugere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, 'Iar ei spun: „Nu ne va atinge Focul decât câteva zile numărate!” Spune-le: „Aveți un legământ cu Allah? Pentru că Allah nu Își va încălca niciodată legământul! Sau voi spuneți despre Allah ceea ce nu știți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, 'Dar nu! Aceia care au săvârșit un păcat și pe care i-a împresurat păcatul, aceia sunt oaspeții Focului și ei în el vor rămâne veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'Dar cei care cred și fac fapte bune vor fi oaspeții Raiului și vor rămâne în el pentru totdeauna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'Și [aduceți-vă aminte] când Noi am făcut legământ cu Fiii lui Israel: „Să nu-L adorați decât pe Allah și cu părinții voștri să vă purtați bine, la fel și cu rudele, cu orfanii și cu sărmanii! Și vorbiți-le oamenilor în mod frumos, îndepliniți Rugăciunea și oferiți Dania anuală obligatorie!” Apoi voi ați renunțat, cu excepția unora dintre voi, și v-ați abătut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'Și [aduceți-vă aminte] când Noi am făcut legământ cu voi [spunând] „Să nu vărsați sângele vostru și să nu vă alungați unii pe alții din casele voastre.” Atunci ați încuviințat aceasta și voi puteți fi martori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Apoi voi înșivă v-ați omorât unul pe celălalt și ați alungat o parte dintre voi din casele lor, întrajutorându-vă împotriva lor în păcate și dușmănie. Iar dacă ei au venit captivi la voi, i-ați răscumpărat, deși alungarea lor v-a fost interzisă. Oare voi credeți numai într-o parte a Scripturii și respingeți o altă parte? Atunci care va fi răsplata acelora dintre voi care fac aceasta, decât rușinea în această viață și supunerea lor la cele mai cumplite chinuri în Ziua Învierii? Allah nu este fără băgare de seamă la ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'Ei sunt cei care au preferat Viața lumească în locul Vieții de Apoi, iar pedeapsa lor nu le va fi ușurată și nici nu vor fi ajutați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'Și, cu adevărat, Noi i-am dăruit lui Moise Scriptura [Tora] și am trimis după el și alți Mesageri. Și i-am dăruit lui Iisus, fiul Mariei, dovezi clare și l-am întărit pe el cu Duhul Sfânt [Îngerul Gavriil]. Însă de fiecare dată când a venit la voi [o, Fii ai lui Israel,] un Mesager cu ceea ce nu le plăcea sufletelor voastre, ați devenit aroganți? Și pe o parte dintre Mesageri i-ați învinuit de minciună, iar pe o altă parte i-ați omorât.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, 'Și ei au spus: „Inimile noastre sunt învăluite.”[19] Dar [de fapt] Allah i-a blestemat pentru necredința lor și ei doar puțin cred.', '[19] Acoperite sau închise și nu pot primi Cuvintele lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'Și când a venit la ei o Carte [Coranul] de la Allah, confirmând-o pe cea pe care o aveau ei - deși înainte se rugau pentru o victorie împotriva celor care nu credeau -, dar [atunci] când le-a venit ceea ce ei știau, nu au crezut; astfel că blestemul lui Allah va fi asupra celor care nu cred!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'Pe nimica toată și-au vândut sufletele lor – tăgăduind ceea ce Allah a pogorât, cu pizmă pentru ceea ce pogoară Allah cu Harul Lui acelora dintre robii Săi pe care El îi Voiește. Și au avut ei parte de mânie peste mânie. Iar necredincioșii au parte de chinuri umilitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'Și când li se spune lor: „Credeți în ceea ce a trimis Allah!”, ei spun: „Noi credem [doar] în ceea ce ne-a fost trimis nouă!” Și ei nu cred în ceea ce a venit mai apoi, deși este Adevărul ce confirmă ceea ce ei știau! Spune: „Și de ce i-ați omorât pe Profeții lui Allah de mai înainte, dacă ați fost [cu adevărat] dreptcredincioși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'Și într-adevăr Moise v-a adus dovezi clare, dar după aceea voi ați ales vițelul [în adorare] și ați fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'Și [aduceți-vă aminte] când am încheiat legământul cu voi și am ridicat deasupra voastră muntele [spunând]: „Țineți ceea ce v-am dat, cu tărie, și ascultați!” Ei au răspuns: „Am auzit, dar nu ne supunem!” Și au fost adăpate inimile lor cu vițelul pentru necredința lor. Spune: „Ce lucru josnic vă poruncește credința voastră, dacă voi sunteți credincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'Spune [o, Mohammed]: „Dacă casa din Viața de Apoi la Allah este numai pentru voi și nu și pentru alți oameni, atunci doriți-vă moartea, dacă sunteți cinstiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'Dar ei nu și-o vor dori niciodată, din pricina celor săvârșite cu mâinile lor. Iar Allah este Știutor al nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'Și cu siguranță îi vei găsi pe ei cei mai lacomi de viață dintre oameni – și mai mult chiar decât păgânii [politeiștii]. Fiecare dintre ei ar vrea să i se dea să trăiască o mie de ani, dar nu se va găsi izbăvitor de chinuri pentru el, nici de va trăi atât de mult, căci Allah Vede ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'Spune: „Cine este dușmanul lui Gavriil?” – cel care ți-a pogorât [Coranul] în inima ta [o, Mohammed], cu Îngăduința lui Allah, confirmând ceea ce era înaintea lui, drept călăuzire și bunăvestire pentru credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Cel care este dușmanul lui Allah, al Îngerilor și al Mesagerilor Săi, al lui Gavriil și al lui Mihail – atunci cu adevărat [să știe că], Allah este dușmanul necredincioșilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'Ți-am revelat ție Versete [care sunt] dovezi clare și nu le-ar nega nimeni decât cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Nu este [adevărat] că de fiecare dată când ei au făcut un legământ o parte dintre ei s-au lepădat? Dar [de fapt], cei mai mulți dintre ei nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, 'Și când a venit la ei un Mesager al lui Allah, confirmând ceea ce ei aveau, o parte dintre cei care aveau Scriptura au aruncat Cartea lui Allah [Tora] în spatele lor, ca și cum ei nu ar fi știut [ceea ce conținea],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'Și ei au urmat [de fapt] ceea ce șeitanii au născocit în timpul împărăției lui Solomon. Dar nu a fost Solomon cel necredincios, ci șeitanii au fost necredincioși. Ei i-au învățat pe oameni vrăjitoria și ceea ce le-a fost trimis celor doi Îngeri din Babel, Harut și Marut. Dar ei [cei doi Îngeri] nu învățau pe nimeni înainte de a-i spune: „Noi suntem o ispită, deci nu fi necredincios!”[20] Și au învățat de la ei doi [chiar și] cum să dezbine un bărbat și soția lui. Însă ei nu puteau să facă rău nimănui, fără permisiunea lui Allah. Ei [oamenii] au învățat ceea ce le aduce rău și nu le folosește și totuși [Fiii lui Israel] au știut că cei care vor dobândi aceasta nu vor avea parte în Viața de Apoi. Ce lucru de nimic au dobândit în schimbul vinderii sufletelor lor! Dacă ei ar fi știut!', '[20] Ei îi avertizau pe oameni să nu folosească în mod greșit ceea ce îi învățau');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'Dacă ei ar fi crezut şi ar fi fost cu frică de Allah, atunci ar fi primit răsplată mai bună de la Allah. O, de-ar fi ştiut!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'O, voi, cei care aţi crezut, nu spuneți „Ra’i-na”, ci spuneți „Undzurna”[21] și fiţi ascultători, căci pentru necredincioşi osândă dureroasă va fi!', '[21] Cuvântul „Ra’i-na” înseamnă în limba arabă „ia-ne pe noi în considerare”, cu alte cuvinte „acordă-ne timp pentru a te auzi și ascultă-ne”. Evreii obișnuiau să folosească același cuvânt cu înțelesul unei insulte. Astfel că li s-a ordonat credincioșilor să evite acest cuvânt și să folosească în loc cuvântul „Undzurna” (așteaptă-ne, pentru ca noi să înțelegem).');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Nu vor cei care nu cred dintre oamenii Scripturii [evreii și creștinii], nici politeiştii, să se pogoare asupra voastră binele de la Domnul vostru, dar Allah alege pentru Îndurarea Sa pe cine Dorește El, căci Allah este Stăpânul Harului nemărginit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Noi nu anulăm un Verset sau îl facem uitat, decât pentru a aduce altul mai bun decât el sau asemenea lui. Nu știi că Allah este cu Putere peste toate?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Nu ai ştiut că a lui Allah este Împărăţia Cerurilor şi a Pământului şi că nu aveţi, alt ocrotitor şi sprijinitor în afară de Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Sau vreți să-i cereţi Mesagerului vostru, aşa cum i s-a cerut lui Moise mai înainte? Şi cel care schimbă credința cu necredință, acela se abate de la drumul cel drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Mulți din neamul Scripturii și-ar dori să vă facă din nou necredincioşi, după ce ați crezut, din pricina invidiei din sufletele lor, după ce li s-a arătat adevărul. Iertaţi şi nu luați în seamă, până ce va veni Allah cu Porunca Sa. Cu adevărat Allah este cu Putere peste toate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'Efectuați Rugăciunea şi oferiți Zakah [caritatea anuală obligatorie], căci binele pe care vi-l dăruiți vouă înşivă, îl veţi găsi la Allah. Cu adevărat Allah Vede bine ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, 'Și au spus: „Nu vor intra în Rai decât cei care sunt evrei sau creştini!” Acestea sunt doar dorinţele lor. Răspunde-le: „Aduceţi dovada voastră dacă aveţi dreptate!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, 'Ba nu! Cel care s-a supus lui Allah şi face bine, va avea răsplata sa de la Domnul lui! Ei nu vor avea motive de a se teme şi nici nu vor fi mâhniți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'Evreii spun: „Creştinii nu au niciun temei!” Şi creştinii spun: „Evreii nu au niciun temei!” deși ei citesc Scriptura[22]. Astfel spun şi cei care nu au ştiinţă [politeiștii], asemenea vorbelor lor. Dar Allah va judeca în Ziua Învierii în cele asupra cărora au păreri diferite.', '[22] Evreii citesc Tora care îl vestea pe Iisus, iar creştinii citesc Evanghelia care confirma mesajul lui Moise');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Şi cine este mai nedrept decât acela care a oprit ca în moscheile lui Allah să se rostească Numele Lui şi s-a luptat să le distrugă? Aceştia nu se cuvine să intre în ele decât cu frică. Ei vor avea în această lume parte de rușine şi în Lumea de Apoi o pedeapsă mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'Ale lui Allah sunt Răsăritul şi Apusul şi ori încotro vă veţi întoarce, acolo este Faţa lui Allah. Cu adevărat Allah este Uasi‘ [Cel cu Har Nemărginit], ‘Alim [Atoateștiutor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, 'Ei au spus: „Allah şi-a luat un fiu.” Slavă Lui! Dimpotrivă, ale Lui sunt cele din Ceruri şi de pe Pământ! Toate Îi sunt ascultătoare Lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, 'Făcătorul Cerurilor şi al Pământului. Atunci când hotărăşte un lucru, El doar spune: „Fii” şi acesta este!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'Cei care nu știu spun: „De ce nu vorbește Allah cu noi sau de ne-ar trimite vreun semn?» Așa au spus şi cei de dinaintea lor, cuvinte semănând cu ale lor. Inimile lor seamănă. Noi am adus semne limpezi pentru cei care vor să creadă neclintit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Cu adevărat Noi te-am trimis [o, Mohammed,] cu Adevărul, ca bun vestitor şi prevenitor, dar tu nu vei fi întrebat despre oaspeții Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Evreii și creștinii nu te vor accepta până când nu le vei urma credinţa lor. Spune: „Călăuzirea lui Allah este [singura] Călăuzire adevărată!” Dacă le vei urma dorinţele, după Ştiinţa pe care ai primit-o, nu vei avea nici ocrotitor, nici ajutor la Allah!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Aceia cărora le-am dat Cartea o vor recita aşa cum trebuie să fie recitată. Ei sunt cei care cred în ea, iar cei care nu cred în ea, aceia sunt pierzători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'O, Fii ai lui Israel, aduceţi-vă aminte de binele pe care vi l-am făcut şi că Eu v-am preferat înaintea lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'Și fiți cu frică de o Zi în care niciun suflet nu va putea face nimic pentru alt suflet, nu se va lua de la el compensație, și nici nu se va primi nicio mijlocire de la el, și nici nu va putea fi el ajutat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'Şi [luați aminte] când Avraam a fost încercat de Domnul său cu cuvinte [porunci] şi le-a împlinit. [Allah] a spus: „Eu te voi face conducător peste oameni.” [Avraam] a întrebat: „Şi pe urmașii mei?” [Allah] i-a răspuns: „Legământul Meu nu-i priveşte pe cei nelegiuiţi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'Şi [spune] când am făcut Noi Casa [Kaʻbah] un loc de revenire pentru oameni şi un refugiu. Și luați [o, credincioșilor] locul lui Avraam drept loc de Rugăciune. Și am încheiat un legământ cu Avraam şi Ismail [spunând]: „Curăţaţi Casa Mea pentru cei care fac tauaf[23] şi pentru cei care se retrag pioşi în ea şi pentru cei care fac Rugăciunea şi se prosternează!”', '[23] O formă de adorare specifică reprezentând înconjurarea Kabei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'Şi [spune] când Avraam a spus: „Doamne, fă-l un oraş al păcii şi hrăneşte poporul lui cu roade, pe aceia dintre ei care cred în Allah şi în Ziua Judecății!” [Allah] a Spus: „Iar cel care nu va crede, va avea parte de bucurie pentru puţin timp[24], apoi îl voi supune la chinurile Iadului și ce soartă cumplită va avea!”', '[24] În timpul vieții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'Şi [spune] când Avraam a ridicat temeliile Casei și Ismail [spunând]: „Doamne, primeşte [acest lucru] de la noi! Cu adevărat Tu eşti As-Samiʻ [Cel care Aude totul], Al-‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, 'Doamne, fă-ne pe noi musulmani [supuşi Ţie] şi fă dintre urmaşii noştri o comunitate musulmană [supusă Ţie]! Şi arată-ne ritualurile [de la Hajj și Umrah] şi ne iartă pre noi. Cu adevărat Tu eşti At-Tauuab [Iertător], Ar-Rahim [Îndurător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'Doamne, trimite-le lor un Mesager dintre ei, care să le recite Versetele Tale şi să îi înveţe Cartea şi Înţelepciunea şi să îi purifice pe ei. Cu adevărat, Tu eşti Al-Aziz [Atotputernic], Al-Hakim [Înțelept]!»', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Şi cine este împotriva religiei lui Avraam, în afară de cel care se nesocoteşte pe sine însuşi? Noi l-am ales pe el în această lume şi, cu adevărat, el se va afla în Lumea de Apoi printre cei drepţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'Când i-a zis Domnul său: „Supune-te!”, el a răspuns: „M-am supus [acceptând Islamul] Stăpânului lumilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'Şi Avraam și-a îndemnat fiii [să facă la fel], şi asemenea şi Iacob, [spunând]: „O, fiii mei, cu adevărat Allah a ales pentru voi această religie, așadar, să nu muriţi altfel decât musulmani!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Sau aţi fost voi martori când a venit moartea la Iacob, atunci când și-a întrebat fiii: „Pe cine veţi adora după moartea mea?” Ei au răspuns: „Îl vom adora pe Domnul tău şi pe Domnul părinţilor tăi Avraam, Ismail şi Isaac, pe Domnul cel Unic. Noi numai Lui îi vom fi supuşi [musulmani].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Acest neam a trecut. El va avea ceea ce şi-a agonisit, iar voi veţi avea ceea ce v-aţi agonisit, iar voi nu veţi fi întrebaţi pentru ceea ce au făcut ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, 'Şi au spus: „Fiţi evrei sau creştini şi sunteţi pe calea cea bună” Spune: „Dimpotrivă, noi urmăm religia lui Avraam, cel întru dreptate și care nu a fost dintre politeişti!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, 'Spuneţi [o, credincioșilor]: „Noi credem în Allah şi în ceea ce ne-a fost trimis nouă şi ceea ce i-a fost trimis lui Avraam, lui Ismail, lui Isaac, lui Iacob şi Urmașilor [al-Asbat][25] și în ceea ce le-a fost dat lui Moise şi lui Iisus şi în ceea ce le-a fost dat Profeţilor de către Domnul lor. Noi nu facem nicio deosebire între ei! Noi Lui Îi suntem supuşi [musulmani]!»', '[25] Cele douăsprezece triburi ale lui Israel descendente de la Iacob');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Dacă ei cred în ceea ce credeţi voi, atunci ei vor fi pe calea cea bună călăuziți, dar dacă ei se vor abate, vor fi într-o disensiune, iar Allah te va ajuta împotriva lor, căci El este As-Samiʻ [Cel care Aude totul], Al-‘Alim [Atoateștiutorul]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, '[Și spuneți: „Aceasta este] religia lui Allah! Şi cine este mai bun decât Allah în rânduirea religiei? Noi Lui Îi suntem slujitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, 'Spune [o, Mohammed]: „Vă certați cu noi în legătură cu Allah când El este Domnul nostru şi Domnul vostru? Faptele noastre sunt ale noastre, iar faptele voastre sunt ale voastre. Noi numai Lui Îi suntem devotaţi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Sau vreți să spuneți că Avraam, Ismail, Isaac, Iacob şi urmașii lor au fost evrei sau creştini? Spune: „Voi sunteţi mai ştiutori sau Allah? Şi cine este mai nelegiuit decât acela care ascunde mărturia[26] ce o are de la Allah?” Și Allah nu este neștiutor a ceea ce faceţi voi.', '[26] Mărturiile din Scripturile anterioare ce confirmă religia lui Allah (Islamul) și venirea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Acest neam a trecut. El va avea ceea ce şi-a agonisit, iar voi veţi avea ceea ce v-aţi agonisit, iar voi nu veţi fi întrebaţi pentru ceea ce au făcut ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'Oamenii nechibzuiți vor spune: „Ce i-a îndepărtat de la Qibla[27] lor pe care o avuseseră mai înainte[28]?” Spune: „Ale lui Allah sunt Răsăritul şi Apusul. El îl călăuzeşte pe acela pe care Voieşte El pe calea cea dreaptă.”', '[27] Direcţia înspre care se îndreaptă musulmanii în timpul Rugăciunii
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'Astfel Noi am făcut din voi o comunitate moderată [dreaptă], pentru ca voi să fiţi martori în legătură cu oamenii şi pentru ca Profetul să fie martor în legătură cu voi. Şi nu am schimbat Qibla pe care ai avut-o decât pentru a-l şti pe cel care-l urmează pe Profet şi pe cel care se întoarce pe călcâiele sale. Cu adevărat, va fi lucru greu, mai puţin pentru cei pe care i-a călăuzit Allah. Iar Allah nu va lăsa niciodată să fie în deşert credința voastră [rugăciunile voastre anterioare]. Cu adevărat Allah este faţă de oameni Ar-Ra’uf [Cel plin de compasiune], Ar-Rahim [ Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Într-adevăr Noi am văzut îndreptarea feţei tale [o, Mohammed] către Cer și, cu siguranță, te vom îndrepta către o Qibla care îţi va plăcea. Aşadar, îndreaptă-ţi faţa către al-Masjid al-Haram[29]. Şi oriunde aţi fi [credincioșilor] îndreptaţi-vă feţele voastre către ea [în Rugăciune]! Iar cei cărora le-a fost dată Scriptura [evreilor și creștinilor] ştiu că acesta este adevărul de la Domnul lor. Şi Allah nu este neștiutor a ceea ce fac ei.', '[29] Moscheea cea Sfântă din Mecca, unde se află Ka’bah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, 'Dacă tu ai aduce celor cărora li s-a dat Scriptura toate semnele, ei nu ar urma Qibla ta şi nici tu nu ai urma Qibla lor. Şi nici nu ar urma unii Qibla altora. Iar dacă tu ai urma dorințele lor, după ştiinţa ce ai primit-o, atunci tu ai fi dintre nelegiuiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Cei cărora le-am dat Scriptura, îl cunosc [pe Mohammed] aşa cum își cunosc fiii. Dar cu adevărat o parte dintre ei ascund adevărul, cu toate că îl cunosc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Adevărul este de la Domnul tău. Deci nu fi dintre aceia care se îndoiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'Fiecare [în religie] are o direcţie înspre care se îndreaptă [în Rugăciune]. Voi însă întreceţi-vă la faptele bune. Oriunde v-aţi afla, Allah vă va aduce pe toţi [la judecată], căci Allah este peste toate cu Putere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'Şi de oriunde ai pleca [pentru Rugăciune, o, Mohammed,] îndreaptă-ţi faţa către al-Masjid al-Haram. Cu adevărat, este Adevărul de la Domnul tău și Allah nu este neștiutor a ceea ce voi faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'Şi de oriunde ai pleca [pentru Rugăciune], îndreaptă-ţi faţa către al-Masjid al-Haram. Oriunde v-aţi afla, îndreptaţi-vă feţele către ea, pentru ca oamenii să nu aibă un motiv împotriva voastră, cu excepția celor care sunt nelegiuiţi. Şi nu vă temeţi de ei, ci temeţi-vă numai de Mine, pentru ca Eu să Îmi împlinesc Harul Meu asupra voastră şi poate că veţi fi bine călăuziţi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'Așa cum Noi v-am trimis un Mesager dintre voi, care să vă citească Versetele Noastre, să vă purifice şi să vă înveţe Cartea şi Înţelepciunea[30] şi să vă înveţe ceea ce nu ştiaţi!', '[30] Înțelepciunea transmisă de către profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) este Sunnah (Tradițiile) lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Pomeniţi-Mă pe Mine şi o să vă pomenesc și Eu! Şi fiţi recunoscători față de Mine și nu fiţi fără credinţă faţă de Mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'O, voi, cei care credeţi! Căutaţi ajutor întru răbdare şi Rugăciune. Cu adevărat Allah este cu cei răbdători!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'Nu spuneţi despre cei care sunt ucişi pe calea lui Allah: „Ei sunt morţi.” Dimpotrivă ei sunt vii, dar voi nu vă daţi seama!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'Și, cu siguranță, vă vom încerca cu puţină spaimă, foamete, pierderea bunurilor, vieților și a roadelor, dar binevesteşte celor răbdători,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'Care, dacă s-a abătut asupra lor vreo nenorocire, spun: „Cu adevărat noi suntem ai lui Allah şi la El ne vom întoarce.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'Aceia sunt cei peste care se pogoară Binecuvântarea şi Îndurarea Domnului lor și aceia sunt cei călăuziţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, 'Cu adevărat As-Safa şi Al-Marua[31] sunt dintre rânduielile lui Allah. Iar cel care face Hajj [Pelerinajul mare] la Casă sau Umrah [Pelerinajul mic] - nu comite niciun păcat dacă merge între ele[32]. Iar acela care de bunăvoie face bine – atunci cu adevărat, Allah este Șakir [Mulțumitor], ‘Alim [Atoateștiutor].', '[31] Locuri destinate ritualurilor de Hajj și Umrah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'Cu adevărat, cei care ascund semnele limpezi şi Călăuzirea, pe care Noi le-am trimis, după ce le-am făcut clare în Scriptură, vor fi blestemați de Allah şi blestemați de cei care blesteamă[33],', '[33] Dintre Îngeri și credincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'Cu excepția celor care se căiesc, se îndreaptă şi dezvăluie [adevărul]. Pe aceia îi voi ierta, căci Eu sunt At-Tauuab [Iertător], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Cu adevărat, cei care nu cred şi mor necredincioşi - peste aceia se va abate blestemul lui Allah, al Îngerilor şi al tuturor oamenilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'Și vor rămâne veşnic în el [în Iad]. Pedeapsa nu le va fi uşurată, şi nici nu vor fi păsuiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'Și Domnul vostru este un Domn Unic. Nu există altă divinitate în afară de El, Ar-Rahman [Cel Milostiv], Ar-Rahim [ Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'Cu adevărat, în facerea Cerurilor şi a Pământului, în schimbarea nopţii şi zilei, în corăbiile care plutesc pe mări cu ceea ce le foloseşte oamenilor, în apa trimisă de Allah din Cer, cu care a înviat Pământul, după ce a fost mort, şi a răspândit pe el vietăţile, în schimbarea vânturilor şi norilor supuşi dintre Cer şi Pământ sunt semne pentru nişte oameni care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'Dar printre oameni sunt unii care Îi fac semeni lui Allah, iubindu-i așa cum Îl iubesc pe Allah. Dar cei care cred sunt mai stăruitori în iubirea pentru Allah. Şi dacă cei care sunt nelegiuiţi s-ar gândi [la aceasta], când vor vedea pedeapsa, [ar fi siguri] că toată Puterea este a lui Allah şi că Allah este aspru la pedeapsă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'Atunci când cei care sunt urmaţi se vor lepăda de aceia care urmează şi vor vedea [cu toții] pedeapsa şi se vor rupe legăturile între ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'Cei care i-au urmat vor spune: „O, de-ar fi pentru noi întoarcere [la viaţa lumească] pentru ca noi să ne lepădăm de ei, aşa cum ei s-au lepădat de noi.” Astfel le va arăta Allah faptele lor ca regrete [revărsate] asupra lor. Dar ei nu vor mai putea ieşi afară din Foc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'O, oameni, mâncaţi din ceea ce se află pe Pământ şi este îngăduit şi bun şi nu urmaţi paşii lui Şeitan. Cu adevărat el vă este duşman mărturisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'El vă porunceşte numai răul şi ticăloşia şi să spuneţi despre Allah ceea ce nu ştiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'Iar atunci când li se spune: „Urmaţi ceea ce a trimis Allah!”, ei spun: „Dimpotrivă noi urmăm ce au urmat și părinţii noştri.” Chiar dacă părinţii lor au fost neştiutori şi nu au fost călăuziţi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Exemplul celor care nu cred este precum cel care strigă la ceea ce nu aude decât o chemare şi o strigare - [pentru că ei sunt] surzi, muţi, orbi - și ei nu pricep!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'O, voi cei care credeţi! Mâncaţi din bunătăţile pe care Noi vi le-am dăruit şi fiți recunoscători lui Allah dacă numai pe El voi Îl adoraţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'El v-a oprit vouă doar mortăciunea[34], sângele, carnea de porc şi ceea ce a fost menit altcuiva decât lui Allah. Dar cel care este forțat, fără să poftească şi fără să întreacă măsura, acela nu va avea păcat. Cu adevărat Allah este Al-Ghafur [Iertător], Ar-Rahim [ Îndurător].', '[34] Animalele care nu au fost sacrificate său vânate în mod special pentru mâncare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'Cu adevărat, cei care ascund ceea ce a pogorât Allah din Scriptură şi obţin prin aceasta un preţ de nimic, nu înghit în burţile lor decât Focul. Şi Allah nu le va Vorbi în Ziua Învierii şi nu-i va purifica. Și ei vor primi o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'Aceştia sunt cei care au schimbat Calea cea Dreaptă cu rătăcirea şi iertarea cu pedeapsa. Şi cât vor avea de îndurat în Foc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, 'Şi aceasta pentru că Allah a pogorât Cartea cu Adevărul. Cu adevărat, cei care sunt în neînţelegere asupra Cărţii se află departe, în dezbinare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Cuvioşia nu stă în a vă întoarce feţele înspre Răsărit sau înspre Apus, ci cuvioşia [adevărată] se află în cei care cred în Allah şi în Ziua Judecății, în Îngeri, în Carte şi în Profeţi, care dau din averea lor, în pofida iubirii pentru ea, rudelor, orfanilor, sărmanilor, călătorului, celui care cere [ajutor] și pentru eliberarea sclavilor, în cei care îndeplinesc Rugăciunea și dau Zakat, care îşi ţin legământul atunci când s-au legat, în cei care sunt răbdători la nenorocire, la rău şi în momentele de primejdie. Aceştia sunt cei drepţi, aceştia sunt cei evlavioşi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'O, voi cei care credeţi, v-a fost prescris talionul pentru cei ucişi: liber pentru liber, sclav pentru sclav, femeie pentru femeie. Dar cel care îl iartă pe ucigașul fratelui său [de la a fi ucis], ar trebui să primească o plată potrivită și să fie tratat cu bunăvoință [din partea lui]. Aceasta este o uşurare de la Domnul vostru şi o Îndurare. Iar cel care încalcă legea după aceea va avea parte de pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, 'Şi aveţi în talion [salvarea de] viaţă, o, voi cei dăruiţi cu minte, poate că o să deveniți dreptcredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Vi s-a prescris vouă atunci când vine la unul dintre voi moartea şi lasă în urma lui avere, [să facă] testamentul în favoarea părinţilor săi şi a rudelor celor mai apropiate, așa cum este acceptabil, ca o datorie pentru cei care sunt dreptcredincioși[35].', '[35] Această lege a fost abrogată de revelarea din Surat an-Nisa’ care stipulează împărțirea obligatorie pentru părinți și rude apropiate. Cei care, conform legii, nu moștenesc, pot fi menționați în testament. A se vedea 4:11-12.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Însă acela care-l schimbă [testamentul] după ce l-a auzit - păcatul este numai al acelora care îl schimbă. Cu adevărat, Allah este Samiʻ [Cel care Aude totul], ‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Iar cine se teme că un testator s-a îndepărtat de lege sau a săvârşit un păcat şi face împăcare între ei, acela nu va avea niciun păcat. Cu adevărat, Allah este Al-Ghafur [Iertător], Ar-Rahim [ Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'O, voi cei care credeţi, v-a fost poruncit vouă Postul, aşa cum le-a fost prescris şi celor dinaintea voastră, poate că veţi fi dintre cei dreptcredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, '[Postul] pentru puţine zile[36]. Dar cel dintre voi care este bolnav sau călătorește, [va posti] un număr egal de alte zile. Aceia care sunt în stare [să postească, dar cu greutate] să dea în compensare hrană pentru un sărman. Iar cei care de bunăvoie vor da şi mai mult, binele va fi pentru ei. Dar să postiţi este mai bine pentru voi, dacă voi ați pricepe!', '[36] Zilele lunii Ramadan');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, 'Luna Ramadan [este aceea] în care a fost trimis Coranul, drept călăuză pentru oameni, dovezi limpezi pentru drumul cel drept şi Îndreptar. Şi oricare dintre voi care vede [luna nouă la începutul] lunii, să o ţină ca Post, iar cel care este bolnav sau călătorește, [să postească] un număr egal de alte zile. Allah vă dorește uşurarea, nu împovărarea, şi să împliniţi acest număr [de zile de Post] şi să-L preamăriţi pe Allah, pentru că v-a călăuzit pe calea cea bună. Poate că veţi fi recunoscători!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'Şi dacă te vor întreba robii Mei despre Mine [spune-le, o, Mohammed]: „Cu adevărat Eu sunt aproape, răspund rugii celor care Mă cheamă, atunci când Mă cheamă, dar şi ei să-Mi răspundă [prin ascultare] şi să creadă în Mine. Poate că ei vor fi bine călăuziţi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Vi s-a permis în noaptea Postului relațiile intime cu soțiile voastre. Ele vă sunt vouă veşmânt, iar voi le sunteţi veşmânt lor. Allah Știa că voi vă vicleniţi[37], dar El v-a acceptat căinţa şi v-a iertat. Acum puteți avea relații intime cu ele şi căutaţi să împliniţi ceea ce v-a prescris Allah! Mâncaţi şi beţi până când puteţi să deosebiţi firul alb de firul negru, la revărsatul zorilor! Apoi ţineţi Postul până când vine noaptea [apusul Soarelui] şi să nu aveți relații intime cu ele în timp ce staţi retraşi în moschei! Acestea sunt limitele lui Allah şi nu vă apropiaţi de ele. Astfel, Allah face clare Versetele Sale oamenilor. Poate că ei vor fi cu frică!', '[37] Înainte de această revelație, relațiile intime nu erau permise în nopțile ce precedau zilele de post. Unii nu reușeau să-și înfrâneze această dorință, dar ei nu Îl puteau păcăli pe Allah.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Nu vă luaţi unii altora averile pe nedrept şi nu-i ademeniţi cu ele pe conducători [pe judecători oferindu-le mită], [pentru ca ei să vă ajute] ca să mâncaţi o parte din averile oamenilor pe nedrept şi cu bună ştiinţă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, 'Te vor întreba [o, Mohammed] despre lunile noi. Spune: „Ele măsoară timpul pentru oameni şi pentru Hajj [pelerinaj].” Cuvioșenia nu este să intrați în case prin spatele lor, ci cuvioșenia este a aceluia care are frică de Allah. Şi intraţi în case prin uşile lor! Şi fiţi cu frică de Allah, poate că voi veţi izbândi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'Luptaţi pe calea lui Allah cu cei care luptă împotriva voastră, dar nu încălcați legea. Cu adevărat Allah nu îi iubește pe cei care încalcă legea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'Omorâţi-i unde-i prindeţi şi alungaţi-i de acolo de unde v-au alungat! Iar fitnah[38] e mai rea decât omorul. Dar nu luptaţi împotriva lor în al-Masjid al-Haram, decât dacă ei se luptă cu voi în ea. Iar dacă ei luptă împotriva voastră, omorâţi-i. Aceasta este răsplata necredincioșilor.', '[38] Necredința și impunerea ei asupra altora');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Dacă, însă, ei se opresc, atunci Allah este Al-Ghafur [Iertător], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'Luptaţi-vă cu ei până ce nu va mai fi fitnah și [până când] credinţa va fi numai în Allah! Dar dacă ei se opresc, atunci nu mai există agresiune [asalt], decât împotriva celor nelegiuiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Luna cea sacră este pentru luna cea sacră[39] şi în toate lunile sfinte se aplică talionul. Aşadar, celui care v-a atacat răspundeţi-i întocmai aşa cum v-a atacat el! Şi fiţi cu frică de Allah! Şi să ştiţi că Allah este cu cei care se tem de El!', '[39] Lunile sacre sunt Dhul-Qa’dah, Dhul-Hija, Muharam și Rajab');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'Dăruiţi pe calea lui Allah și nu vă aruncaţi cu propriile voastre mâini pradă pieirii! Şi faceţi bine, căci Allah îi Iubeşte pe binefăcători!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Împliniți Hajj-ul şi ‘Umrah pentru Allah, dar dacă sunteţi împiedicaţi, aduceţi ca ofrandă ce animale de sacrificat puteţi. Şi nu vă tundeţi capetele voastre înainte ca ofranda să ajungă la locul său de înjunghiere. Cel dintre voi care este bolnav sau are o suferință la cap [şi trebuie să se tundă], trebuie să se răscumpere printr-un post sau printr-o pomană[40] sau printr-o jertfă[41]. Dacă v-aţi regăsit liniştea, oricine dorește sa îndeplinească ‘Umrah [în timpul lunilor de Hajj[42]], urmată de Hajj, [sa aducă] o jertfă pe care o poate obține ușor din animalele de sacrificat. Cel care nu are mijloace [nu își permite un astfel de animal] trebuie să postească trei zile în Hajj şi încă şapte, după ce v-aţi întors [acasă]. Astfel sunt zece zile [complete]. Aceasta este prescris pentru cel a cărui familie nu este în împrejurimile Moscheii Al-Haram. Şi fiţi cu frică de Allah şi să ştiţi că Allah este aspru în pedeapsă!', '[40] Să hrănească șase persoane nevoiașe
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Pelerinajul are loc în lunile cunoscute, astfel că celui care s-a decis să facă Pelerinajul în aceste luni îi sunt oprite în timpul Pelerinajului relațiile intime, nesupunerea şi cearta. Şi binele pe care îl faceţi, Allah îl Știe. Luaţi cu voi provizie, dar cea mai bună provizie este frica de Allah! Şi să fiţi cu frică de Mine, voi cei care aveţi minte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, 'Nu este un păcat pentru voi să căutaţi un câştig[43] de la Domnul vostru [în timpul Hajj-ului]. Dar când plecați de pe Arafat, pomeniţi-L pe Allah la Al Maş’ar al-Haram[44]. Și pomeniţi-L pe El, aşa cum El v-a călăuzit bine, pentru că, cu adevărat, înainte aţi fost dintre cei rătăciţi!', '[43] Profit din comerț sau afaceri
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, 'Apoi plecați din locul din care [toți] oamenii pleacă şi cereţi iertare de la Allah. Cu adevărat Allah este Al-Ghafur [Iertător], Ar-Rahim [ Îndurător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'Şi dacă aţi îndeplinit ritualurile voastre, pomeniţi-L pe Allah, aşa cum îi pomeniţi pe părinţii voştri, ba chiar şi mai mult. Dar sunt printre oameni unii care spun: „Doamne, dă-ne nouă [bine] în lumea aceasta!”, însă aceştia nu vor avea parte în Lumea de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'Şi printre ei sunt unii care spun: „Doamne, fă-ne nouă parte bună în această lume şi parte bună în Lumea de Apoi şi apără-ne pe noi de chinurile Focului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'Aceia vor avea parte de ceea ce au agonisit, căci Allah este grabnic la socoteală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'Pomeniţi-L pe Allah în zile [specifice] numărate. Iar cel care își grăbeşte [plecarea] în două zile – nu are niciun păcat, iar cel care o va amâna, nu are niciun păcat – pentru cel care are frică de Allah. Şi fiţi cu frică de Allah şi să ştiţi că la El vă veţi aduna!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'Printre oameni este cel ale căror vorbe îţi plac în această lume şi care Îl ia pe Allah drept martor pentru ceea ce este în inima sa, în vreme ce el este cel mai înverșunat la gâlceavă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Şi de îndată ce pleacă, străbate pământul, căutând să semene stricăciune şi să distrugă lanurile şi animalele. Allah însă nu iubeşte stricăciunea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'Iar dacă i se spune: „Fii cu frică de Allah”, mândria îl împinge la păcat. Însă Iadul va fi de ajuns pentru el şi ce loc rău de odihnă este acesta!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'Şi printre oameni este acela care se vinde pe sine căutând Mulţumirea lui Allah. Şi Allah este Milostiv cu robii [Săi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'O, voi, cei care credeţi! Intraţi în Islam pe deplin şi nu urmaţi paşii lui Şeitan. Cu adevărat el vă este duşman învederat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'Iar dacă vă veţi mai abate, după ce v-au venit dovezile cele limpezi, atunci să ştiţi că Allah este Aziz [Atotputernic], Hakim [Înțelept]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Ei aşteaptă ca Allah să vină la ei în umbre de Nori şi Îngerii [la fel], şi ca soarta să le fie hotărâtă [atunci]? Şi la Allah se întorc [toate] lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Întreabă-i pe Fiii lui Israel cât de multe dovezi limpezi le-am trimis Noi. Dar cel care schimbă binefacerea lui Allah [pentru necredință], după ce ea a venit la el, atunci, cu adevărat, Allah este aspru la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Frumoasă le este necredincioșilor viața acestei lumi şi-i iau în derâdere pe cei care cred. Însă cei care se tem de Allah sunt mai presus decât ei în Ziua Învierii. Și Allah împarte Harul Său celor pe care El îi vrea, fără măsură.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'Oamenii au avut o singură religie [înainte de rătăcirea lor]; apoi Allah i-a trimis pe Profeți, drept vestitori şi prevenitori, şi a trimis împreună cu ei Scriptura cu Adevărul, pentru a judeca între oameni acolo unde ei aveau dispute. Și s-au certat asupra ei doar cei care au primit-o – după ce le-au fost aduse dovezi limpezi - din pricina pizmuirii lor. Apoi Allah i-a călăuzit pe cei care au crezut către Adevărul asupra căruia ceilalți s-au certat, prin Permisiunea Sa. Iar Allah călăuzește pe cine Voiește pe calea cea dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Sau credeți că veţi intra în Rai înainte de a se fi abătut asupra voastră [încercări] asemenea celor care s-au abătut asupra celora dinaintea voastră? Ei au fost loviți de sărăcie și nenorociri şi au fost zgâlţâiţi până într-atât încât a zis Trimisul [lor] şi cei care au crezut împreună cu el: „Când vine Ajutorul lui Allah?” Cu siguranță, Ajutorul lui Allah este aproape!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, 'Te întreabă [o, Mohammed] ce să cheltuiască. Spune-le: „Ceea ce cheltuiţi voi din bunuri trebuie să fie pentru părinţi, pentru rude, pentru orfani, sărmani şi călători. Şi orice bine pe care îl faceţi – cu adevărat, Allah este ‘Alim [Atoatecunoscător] cu privire la el.»', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'V-a fost prescrisă lupta, chiar dacă ea vă este neplăcută. Dar se poate ca voi să urâţi un lucru care este bun pentru voi şi să iubiţi un lucru care este rău pentru voi. Dar Allah Știe, în vreme ce voi nu ştiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'Te întreabă despre luna cea sfântă şi lupta în timpul ei. Spune: „Lupta într-însa e mare [păcat], dar împiedicarea de la calea lui Allah, necredința în El şi [împiedicarea accesului la] Moscheea Al-Haram, precum şi alungarea neamului său din ea sunt [un rău] mai mare înaintea lui Allah. Iar fitnah [necredința și impunerea ei celorlalți] este mai gravă decât omorul.” Și ei vor continua să lupte împotriva voastră până când veți lăsa credinţa voastră, dacă le va fi cu putinţă. Iar acela dintre voi care își va lăsa credinţa şi va muri în necredinţă, faptele lui vor fi în zadar în această lume, cât şi în Lumea de Apoi și aceştia sunt oaspeţii Focului şi în el vor rămâne veşnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'Cu adevărat cei care au crezut și cei care au emigrat şi s-au luptat pe calea lui Allah, să nădăjduiască în Mila lui Allah, căci Allah este Al-Ghafur [Iertător], Ar-Rahim [ Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'Ei te întreabă [o, Mohammed] despre vin[45] şi despre jocurile de noroc. Spune: „În ele este mare păcat şi [totuși] sunt şi unele beneficii pentru oameni, dar păcatul este mai mare decât folosul.” Și te întreabă ce trebuie să cheltuiască [pentru milostenie]. Spune: „Ceea ce vă prisoseşte!” Astfel, Allah vă face clare Versetele Sale; poate că voi o să cugetaţi', '[45] Cuvântul „khamr” (vin) include toate băuturile alcoolice şi drogurile. Interzicerea finală este dată în 5:90-91.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'La această lume şi asupra Lumii de Apoi. Şi ei te întreabă despre orfani. Spune: „A-i ajuta este cel mai bine, iar dacă vă amestecaţi treburile împreună, atunci sunt fraţii voştri.” Și Allah Știe să-l deosebească pe cel nelegiuit de cel care face bine. Şi dacă ar Vrea Allah, ar putea să vă copleşească cu greutăţile. Cu adevărat Allah este Al-Aziz [Atotputernic], Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'Nu vă însuraţi cu politeiste înainte ca ele să creadă[46]. Pentru că o sclavă credincioasă este mai bună decât o politeistă, chiar dacă ea vă place. Şi nu-i căsătoriți pe cei politeişti [cu femeile voastre] înainte ca ei să creadă, căci un sclav credincios este mai bun decât un politeist, chiar dacă el vă place. Aceştia [vă] cheamă la Foc, dar Allah cheamă la Rai şi la iertare, prin Graţia Sa. El le arată limpede Versetele Sale oamenilor, pentru ca ei să-şi aducă aminte.', '[46] Şi să Îl adore numai pe Unicul Dumnezeu');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'Te întreabă despre menstruaţie. Spune: „Acesta este un rău, așadar stați departe de soțiile voastre[47] în timpul menstruației. Și nu vă apropiați de ele până când nu vor fi pure. Iar atunci când se vor fi purificat[48], atunci mergeți la ele aşa cum v-a Poruncit Allah. Cu adevărat Allah îi Iubeşte pe cei care se căiesc şi îi Iubeşte pe cei care se purifică.', '[47] Abțineți-vă de la relațiile intime
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Soţiile voastre sunt ogor pentru voi, așadar veniţi la ogorul vostru cum doriți, și pregătiţi [fapte bune] pentru sufletele voastre mai înainte. Și fiţi cu teamă de Allah şi să ştiţi că Îl veţi întâlni! Şi dă-le vești bune credincioşilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'Şi nu folosiţi [jurămintele voastre în] Numele lui Allah ca un motiv pentru a vă sustrage de la a fi pioși și cu teamă de Allah și a aduce pace între oameni. Şi Allah este As-Sami [Cel care Aude totul], Al-Alim [Atoateștiutorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Allah nu vă cere socoteală pentru vorbele neintenționate din jurămintele voastre, ci El vă cere socoteală pentru ceea ce inimile voastre au dobândit. Şi Allah este Al-Ghafur [Iertător], Al-Halim [ Îngăduitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Pentru cei care jură să nu mai aibă relații intime cu soțiile lor este [stabilit] un timp de așteptare de patru luni. Dar dacă ei se răzgândesc, atunci, cu adevărat, Allah este Al-Ghafur [Iertător], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'Însă dacă au hotărât divorţul, atunci, cu adevărat, Allah este As-Sami’ [Cel care Aude] și Al-Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Femeile divorţate trebuie să aştepte[49] trei menstruaţii şi nu le este îngăduit să ascundă ce a făcut Allah în pântecele lor, dacă ele cred în Allah şi în Ziua Judecății. Iar soții lor sunt mai îndreptăţiţi să le aducă înapoi [în acest timp], dacă vor să se împace[50]. Ele au drepturi egale cu obligaţiile lor, după cuviinţă[51]. Dar bărbaţii [soții] au o treaptă peste ele [în responsabilitate și autoritate]. Şi Allah este Al-Aziz [Atotputernic], Al-Hakim [Înțelept].', '[49] Să nu se căsătorească
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Divorţul este [permis] de două ori, după care, fie să o țină în bună înţelegere, fie să o lase liberă, cu bunătate. Şi nu vă este permis să luaţi înapoi nimic din ceea ce le-aţi dăruit lor, decât dacă ambele părţi se tem că nu vor putea să respecte poruncile lui Allah[52]. Iar dacă vă temeţi că nu veţi putea respecta poruncile lui Allah, atunci nu este niciun păcat ca ea să se răscumpere. Acestea sunt poruncile lui Allah şi nu le încălcaţi! Cei care încalcă poruncile lui Allah sunt nelegiuiţi!', '[52] Să se comporte potrivit unul cu celălalt');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'Dacă [soţul] divorţează de ea [a treia oară], ea nu-i mai este permisă lui după aceasta decât după ce ea se căsătoreşte cu un alt bărbat[53]. Iar dacă acesta divorţează de ea [sau moare], nu mai este niciun păcat pentru ca ei să se întoarcă unul la celălalt[54], dacă ei cred că pot să respecte poruncile lui Allah. Acestea sunt poruncile lui Allah, pe care Le face clare pentru oamenii ce pricep.', '[53] Cu intenția unei căsătorii permanente și nu pentru a se putea întoarce la soțul anterior
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Iar dacă divorţaţi de femei şi ele aproape împlinesc timpul lor, atunci, fie luaţi-le înapoi cu bunătate, fie daţi-le drumul cu bunătate. Dar nu le luaţi înapoi pentru a le face rău sau pentru a dobândi un folos necuvenit. Cel care face aceasta îşi pricinuieşte un rău lui însuşi. Şi nu luaţi Versetele lui Allah în derâdere şi aduceţi-vă aminte de Harul lui Allah asupra voastră atunci când v-a revelat Cartea [Coranul] şi Înţelepciunea [Sunnah Profetului (pacea și binecuvântarea lui Allah fie asupra sa)] prin care v-a instruit! Şi fiţi cu frică de Allah şi să ştiţi că Allah este Știutorul tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'Iar dacă divorţaţi de femei[55] şi ele împlinesc timpul lor, nu le împiedicaţi să se întoarcă la soţii lor [foștii], dacă ambele părți se înțeleg după cuviință. Aceasta le este povățuit acelora dintre voi care cred în Allah şi în Ziua de Apoi. Acest lucru este mai potrivit şi mai curat pentru voi, și Allah Știe, iar voi nu ştiţi.', '[55] Pentru prima sau a doua oară');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'Mamele [divorţate] îi pot alăpta pe copiii lor doi ani încheiaţi, pentru cei care doresc să se împlinească timpul alăptării, iar tatălui îi revine datoria de a le asigura întreţinerea şi îmbrăcămintea după cuviinţă. Nici unui suflet nu i se impune decât atât cât îi stă în putinţă. Nici mamei nu i se poate face rău prin intermediul copilul ei și, de asemenea, nici tatălui. Asemenea şi pentru moştenitor [moştenitorul tatălui]. Iar dacă amândoi [părinţii] se învoiesc la înţărcare, după ce se sfătuiesc, nu vor avea păcat. Iar dacă doriți să luaţi o doică pentru copiii voştri, atunci nu veţi avea niciun păcat, cu condiția să plătiţi ceea ce aveţi de dat, după cuviinţă. Şi să fiţi cu frică de Allah şi să ştiţi că Allah este Basir [Atoatevăzător] a ceea ce faceți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'Aceia dintre voi care mor şi lasă după ei soţii, ele trebuie să aştepte[56] patru luni şi zece [zile]. După ce au împlinit timpul lor, nu mai e niciun păcat pentru voi pentru ceea ce fac ele cu sine, după cuviinţă[57]. Şi Allah este Khabir [Bineștiutor] a ceea ce faceți.', '[56] Să se abțină de la căsătorie
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'Voi nu aveți nicio vină, dacă [în acest timp] le daţi de înţeles [indirect] femeilor că le cereţi în căsătorie sau doar dacă aveți acest gând. Allah Știe că voi vă gândiţi la ele. Dar nu le faceţi promisiuni într-ascuns, în afară de a le spune vorbe cuviincioase. Şi nu mărturisiți intenţia căsătoriei înainte de trecerea timpului stabilit! Și să ştiţi că Allah Știe ce se află în sufletele voastre şi fiţi prevăzători faţă de El, iar Allah este Al-Ghafur [Iertător], Al-Halim [Blând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Nu este niciun păcat pentru voi dacă divorţaţi de femei înainte de a le atinge[58] sau înainte de a le stabili zestrea[59] . Dar dăruiţi-le lor [drept cadou] - cel înstărit după putinţa sa, iar cel sărac după putinţa sa – anumite bunuri, de care ele să se bucure, după cuviinţă! Aceasta este o datorie pentru cei care fac bine.', '[58] Căsătoria nu a fost consumată
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'Însă dacă divorţaţi de ele înainte de a le atinge, dar după ce le-aţi hotărât zestrea, atunci [dați-le] jumătate din ce aţi stabilit, cu excepţia situaţiei în care ele renunță la aceasta sau cel în mâinile căruia se află contractul de căsătorie renunţă. Iar renunţarea este mai aproape de pietate. Şi nu uitaţi binele dintre voi, cu adevărat Allah este Basir [Atoatevăzător] a tot ceea ce voi faceți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Efectuați Rugăciunile [obligatorii] cu sârguință, [în special] Rugăciunea de la mijloc [Asr]! Şi staţi în picioare dinaintea lui Allah, cu supunere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'De vă temeţi [de ceva, atunci rugați-vă] mergând pe jos sau călare, dar când sunteţi iarăşi în siguranţă, pomeniţi-L pe Allah [în Rugăciune], aşa cum El v-a învăţat ceea ce voi nu ştiaţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'Aceia dintre voi care mor şi lasă după ei soţii [să lase] o îndemnare pentru soţiile lor: întreţinerea pentru un an, fără scoaterea din casă. Dacă ele pleacă [de bunăvoie], voi nu aveţi niciun păcat pentru ceea ce fac ele cu ele însele, după cuviinţă[60]. Allah este Al-Aziz [Atotputernic], Al-Hakim [Înțelept].', '[60] Această directivă a fost abrogată de cele revelate în 2:234 și 4:12');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'Celor divorţate să le fie dăruite provizii după cuviinţă. Aceasta este o obligaţie pentru cei dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'Astfel Allah face clare Versetele Sale, pentru ca voi să pricepeţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Nu i-ai văzut pe aceia care și-au părăsit casele cu miile de teama morţii? Allah le-a spus: „Muriţi!”; dar apoi i-a readus la viaţă. Allah este Mărinimos cu oamenii, dar cei mai mulţi sunt nerecunoscători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'Aşadar, luptaţi pe calea lui Allah şi să ştiţi că Allah este As-Sami [Cel care Aude totul], Al-Alim [Atoateștiutorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Cine este acela care Îi dă lui Allah un împrumut bun pentru ca El să îl înmulţească [în Viaţa de Apoi] de mai multe ori? Allah este Cel care micșorează sau mărește [ Darul Său] şi la El vă veţi întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Nu ai văzut tu adunarea Fiilor lui Israel, când după [timpul lui] Moise i-au spus unuia dintre Profeţii lor: „Trimite-ne un rege și noi vom lupta pe calea lui Allah”? El le-a zis: „S-ar putea să nu luptaţi voi, după ce vi s-a poruncit lupta?” I-au răspuns: „De ce să nu luptăm noi pe calea lui Allah, când noi am fost alungaţi din casele noastre și de lângă copiii noştri?” Dar când le-a fost poruncită lupta, ei au întors spatele, în afară de puţini dintre ei. Însă Allah îi Ştie bine pe cei nelegiuiţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, 'Şi le-a zis Profetul lor: „Cu adevărat Allah vi l-a trimis vouă pe Talut ca rege!” Au răspuns: „Cum să conducă el peste noi, când noi suntem mai vrednici de domnie decât el? Şi el nu a fost dăruit nici cu bogăţie din belşug.” El le-a zis: „Cu adevărat Allah l-a ales pe el peste voi şi i-a dăruit știință şi putere fizică din abundență!” Iar Allah dă stăpânirea Lui cui Voieşte El, căci Allah este Uasi [Cel cu Har Nemărginit], Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, 'Şi Profetul lor le-a zis: „Cu adevărat un semn al stăpânirii sale este faptul că va veni la voi cu chivotul în care se află liniște de la Domnul vostru și rămăşiţe lăsate de neamul lui Moise şi neamul lui Harun [Aaron], purtat de Îngeri. În aceasta este un semn pentru voi, dacă sunteţi credincioşi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'Şi când Talut a plecat cu soldații lui, el a zis: „Cu adevărat, Allah vă va încerca cu un râu, iar cel care va bea din el nu va mai fi de partea mea, iar cel care nu va gusta din el va fi de partea mea, cu excepția celor care vor bea o sorbitură cu căuşul palmei lor.” Dar ei au băut din el, cu excepția a puţini dintre ei. Apoi după ce l-au trecut împreună cu cei care au crezut cu el, ei au spus: „Astăzi nu avem putere faţă de Jalut [Goliat] şi de soldații săi!” Dar cei care erau convinşi că Îl vor întâlni pe Allah au spus: „De câte ori o armată mai puţin numeroasă a învins o armată mai mare cu Voia lui Allah, căci Allah este cu cei răbdători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'Şi când au ieşit înaintea lui Jalut şi a soldaților săi, ei au spus: „Doamne, revarsă asupra noastră răbdare, întăreşte picioarele noastre şi ajută-ne pe noi să înfrângem acest popor de necredincioşi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'Şi i-au înfrânt cu permisiunea lui Allah, iar Dauud [David] l-a omorât pe Jalut și Allah i-a dăruit [lui Dauud] cârmuirea şi înţelepciunea [Profeția] şi l-a învăţat ceea ce a dorit El. Şi dacă Allah nu i-ar ţine pe oameni în frâu, unul prin altul, pământul ar fi corupt. Dar Allah este Darnic cu toate lumile!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'Acestea sunt Versetele lui Allah pe care Noi ți le recităm [o, Mohammed] întru adevăr. Şi cu adevărat tu eşti unul dintre Mesageri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'Dintre aceşti Mesageri - Noi i-am pus pe unii înaintea altora. Unora dintre ei Allah le-a Vorbit [Moise] și pe alţii i-a ridicat mai sus cu câteva trepte. I-am dat lui Iisus, fiul Mariei, dovezi clare şi l-am întărit pe el prin Duhul Sfânt [Îngerul Gavriil]. Şi de-ar fi Voit Allah, cei de după ei [de după Profeţi] nu s-ar fi războit unul cu celălalt în urma dovezilor clare pe care le-au avut. Dar ei s-au dezbinat, și unii dintre ei au crezut, iar alţii dintre ei nu au crezut. Şi de-ar fi Voit Allah, ei nu s-ar fi războit unul cu celălalt, dar Allah Face ceea ce Voieşte El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'O, voi cei care credeţi! Daţi [milostenie] din ceea ce v-am dăruit Noi înainte de a veni o Zi în care nu va mai fi de folos nici negoţ [posibilitate de răscumpărare], nici legătură de prietenie şi nici mijlocire! Iar necredincioşii sunt nelegiuiţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Allah! Nu există altă divinitate în afară de El, Al-Hayy [Cel Viu], Al-Qayum [Veșnicul]! Nici aţipirea, nici somnul nu-L cuprind! Ale Lui sunt cele din Ceruri şi de pe Pământ! Cine este acela care ar putea mijloci la El fără de îngăduinţa Lui? El le Știe pe cele de dinaintea lor şi pe cele de după ei[61]. Şi ei nu pricep nimic din Știinţa Sa în afară de ceea ce El Voieşte. Scaunul[62] Lui se întinde peste Ceruri şi peste Pământ şi păzirea lor nu-I este grea. El este Al-Aliy [Preaînaltul], Al-Azim [Mărețul]!', '[61] Știința lui Allah cuprinde toate aspectele creației Sale în trecut, prezent și viitor
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, 'Nu există silire la credinţă! Deosebirea dintre calea cea dreaptă şi rătăcire este deslușită, iar cel care se leapădă de Taghut[63] şi crede în Allah s-a prins de cea mai trainică toartă [Islamul], care nu se sparge niciodată. Şi Allah este Sami [Cel Care Aude totul], Alim [Atoateștiutor].', '[63] Obiectele false de adorare precum idoli, spirite, oameni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Allah este Ocrotitorul celor care cred; El îi scoate din întuneric la Lumină, dar cei care nu cred au ca și ocrotitori Taghuţii, care-i scot de la Lumină la întuneric[64]. Aceştia sunt oaspeţii Focului şi în el vor rămâne veşnic.', '[64] Lumina adevărului este una singură, în timp ce întunericul necredinței, îndoielii și greșelilor este numeros');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Oare nu l-ai văzut pe acela care s-a certat cu Avraam în legătură cu existenţa Domnului său, după ce Allah i-a dat stăpânirea? Atunci când a zis Avraam: „Domnul meu este Cel care Dă viaţă şi Ia viaţa.” El a spus: „Şi eu pot să dau viaţă şi să iau viaţa!” Atunci Avraam a spus: „Allah Face ca Soarele să vină de la Răsărit, deci fă-l tu să vină de la Apus!” Iar necredinciosul a rămas descumpănit [de uimire], căci Allah nu-i călăuzeşte pe cei nelegiuiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Sau ca acela care a trecut pe lângă o cetate în ruine şi a întrebat: „Cum o va readuce Allah la viaţă după moartea ei?” Allah l-a lăsat atunci pe el fără viaţă o sută de ani, apoi l-a înviat şi i-a zis: „Cât ai stat tu [aşa]?” I-a răspuns: „Am rămas o zi sau o parte dintr-o zi.” El i-a spus: „Dimpotrivă ai stat o sută de ani şi uită-te la mâncarea ta şi băutura ta! Nu s-au stricat! Şi uită-te la asinul tău! Şi te Vom face pe tine un semn pentru oameni. Uită-te la aceste oase [ale asinului] cum le îmbinăm şi apoi le îmbrăcăm cu carne!” Şi când i s-a arătat lui desluşit aceasta, a zis: „Eu ştiu că Allah este peste toate Atotputernic!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'Şi [adu-ţi aminte când] Avraam a spus: „Doamne, arată-mi cum îi readuci la viaţă pe cei morţi?” [Allah] i-a Răspuns: „Tot nu crezi?” El a spus: „Ba da! Dar numai să se liniştească inima mea!” [Allah] i-a Spus atunci: „Ia patru păsări şi taie-le mărunt. Apoi [după ce le-ai tăiat] pune pe fiecare munte o bucată din ele, apoi cheamă-le şi ele vor veni la tine în grabă. Şi să ştii că Allah este Aziz [Atotputernic], Hakim [Înțelept]!»', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Pilda celor care dau [din] averea lor pe calea lui Allah este ca un grăunte care face şapte spice şi în fiecare spic sunt o sută de grăunţe. Iar Allah Înmulţeşte [răsplata] celui care Voieşte El. Allah este Uasi [Cel cu Har Nemărginit] Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Cei care dau [din] averea lor pe calea lui Allah şi apoi nu se laudă şi nici nu necăjesc [pe cel căruia i-au oferit], aceia au răsplată de la Domnul lor şi teamă pentru ei nu va fi şi nici nu vor cunoaşte ei mâhnirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'O vorbă cuviincioasă şi de iertare este mai bună decât o milostenie după care urmează necăjirea. Iar Allah este Ghani [Înstărit Îndeajuns], Halim [Blând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'O, voi, cei care credeţi! Nu faceţi deşarte milosteniile voastre prin pomenirea lor şi prin necăjire, precum cel care cheltuieşte din averea lui de ochii lumii, fără să creadă în Allah şi în Ziua Judecății. Exemplul lui este precum al unei stânci acoperite de praf peste care vine o ploaie abundentă şi o lasă goală. Ei nu au niciun folos din ceea ce au dobândit. Allah nu-i călăuzeşte pe cei necredincioşi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Și exemplul celor care cheltuiesc [din] averea lor căutând Mulţumirea lui Allah și răsplată, este precum exemplul unei grădini de pe o colină peste care vine o ploaie abundentă şi dă roade de două ori mai multe. Și [chiar] dacă nu vine peste ea ploaie, atunci [îi este suficientă] doar o roureală. Allah Vede tot ceea ce voi făptuiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Doreşte vreunul dintre voi să aibă o grădină de curmali şi viţă de vie pe sub care să curgă pâraie, cu tot felul de roade în ea? În vreme ce îl ajunge pe el bătrâneţea și are copii mici şi ea să fie lovită de o vijelie cu foc și mistuită. Astfel vă arată Allah Versetele [Sale], poate că voi o să cugetaţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'O, voi, cei care credeţi! Faceţi milostenie din lucrurile bune pe care le-aţi dobândit şi din cele pe care le-am făcut să crească pentru voi din pământ. Și nu vă întoarceţi înspre lucrurile rele ca să faceţi din ele milostenie, când nici voi înşivă nu le-aţi primi decât dacă aţi fi cu ochii închişi! Şi să ştiţi că Allah este Ghani [Înstărit Îndeajuns], Hamid [Demn de Laudă]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Şeitan vă ameninţă cu sărăcia şi vă porunceşte lucruri urâte, în timp ce Allah vă promite Iertare şi Mărinimie. Și Allah este Uasi [Cel cu Har Nemărginit], Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'El oferă înţelepciune cui Doreşte El, iar cel care a fost dăruit cu înţelepciune, a fost dăruit cu un mare bine. Dar nu își vor aminti decât cei ageri la minte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'Și ceea ce daţi ca milostenie şi jurămintele prin care vă legaţi – cu adevărat Allah le Știe. Iar cei nelegiuiţi nu vor avea pe nimeni ca sprijinitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Dacă mărturisiți milosteniile făcute, ele sunt binefaceri, dar dacă nu le faceţi cunoscute şi le daţi săracilor, atunci va fi și mai bine pentru voi şi [ele] vă vor ispăşi o parte dintre păcatele voastre, căci Allah este Bineştiutor a ceea ce faceţi voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Nu este responsabilitatea ta [o, Mohammed,] călăuzirea lor, căci Allah călăuzeşte pe cine Voieşte El. Și orice bunuri dați este pentru sufletele voastre și voi nu daţi decât căutând Mulțumirea lui Allah. Şi pentru toate bunurile[65] pe care le dăruiţi veţi fi răsplătiţi și voi nu veţi fi nedreptăţiţi.', '[65] Avere, proprietate, resurse, timp, efort, etc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, '[Milostenia este] pentru cei nevoiaşi, care sunt restricționați pe Calea lui Allah şi care nu pot umbla prin lume [pentru comerț]! Cel neştiutor i-ar putea considera a fi înstăriţi din cauza pioşeniei lor, dar îi vei cunoaşte după semnul lor. Ei nu cer deloc de la oameni. Şi orice bine pe care îl dăruiţi – cu adevărat Allah îl Știe, căci El este Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Cei care dăruiesc din bunurile lor [pe Calea lui Allah] noaptea şi ziua, în secret şi public, vor avea răsplata lor la Domnul lor. Și ei nu se vor teme şi nici nu vor fi necăjiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Cei care mănâncă din dobândă nu vor putea sta în picioare [în Ziua Învierii] decât aşa cum stă unul bătut îngrozitor de Șeitan [şi lovit de nebunie]. Și aceasta pentru că ei spun: „Comerțul este precum camăta.” Dar Allah a permis comerțul, însă a interzis dobânda. Cei care primesc o avertizare de la Domnul lor şi se opresc, au [iertare] pentru ceea ce au făcut în trecut şi lucrul lor este la Allah, dar cei care continuă vor fi oaspeţii Focului şi ei în el vor rămâne veşnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Allah distruge camăta şi sporeşte milosteniile. Allah nu-l iubeşte pe necredinciosul păcătos!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'Cu adevărat cei care cred şi fac fapte bune, îndeplinesc Rugăciunea şi oferă Zakat-ul, vor avea răsplata lor de la Domnul lor şi nu se vor teme şi nici nu vor fi necăjiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'O, voi, cei care credeţi! Fiţi cu frică de Allah şi lipsiţi-vă de restul de dobândă ce v-a mai rămas, dacă sunteţi credincioşi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Dacă nu o veţi face, vi se vesteşte război din partea lui Allah şi a Mesagerului Său. Însă dacă vă veţi căi, veţi avea banii voştri. Nu nedreptăţiţi şi nu veţi fi nedreptăţiţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'Iar celui care este strâmtorat să i se dea o amânare până îi va fi uşor. Dar dacă o faceţi [din partea voastră] milostenie e şi mai bine pentru voi, dacă voi ați şti!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'Şi fiţi cu frică de Ziua în care vă veţi întoarce la Allah, atunci când fiecare suflet va fi răsplătit după ceea ce a agonisit, iar ei nu vor fi nedreptăţiţi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'O, voi, cei care credeţi! Dacă voi contractaţi o datorie pentru un anumit timp, atunci să o scrieți! Şi un scrib să scrie cu dreptate între voi. Scribul nu are voie să refuze a scrie, aşa cum l-a învăţat Allah. Aşadar, el trebuie să scrie aşa cum îi dictează datornicul. Și să fie cu frică de Allah, Stăpânul său, şi să nu micşoreze [valoarea datoriei] cu nimic! Dar dacă datornicul este fără judecată sau slab sau nu poate dicta el, atunci să dicteze tutorele său, cu dreptate. Şi luaţi drept martori doi dintre bărbaţii voştri, iar dacă nu sunt doi bărbaţi, [luaţi] un bărbat şi două femei, dintre aceia pe care îi acceptaţi ca martori, astfel încât, dacă va greşi una dintre ele, să-şi amintească una celeilalte! Martorii nu au voie să se împotrivească, dacă sunt chemaţi. Şi să nu vă fie greu să însemnaţi datoria, mică sau mare, împreună cu termenul ei! Aşa este mai drept pentru voi faţă de Allah şi o dovadă mai puternică şi cu mai multe șanse de a preveni îndoiala dintre voi, cu excepția unei tranzacții imediate pe care o conveniți între voi. Atunci nu este niciun păcat dacă nu o scrieți, dar luaţi martori, atunci când încheiați un contract între voi! Dar să nu fie păgubit niciun scrib sau martor, căci de veţi face [aceasta] înseamnă că ticăloşia este în voi! Şi fiţi cu frică de Allah şi Allah vă învaţă, căci Allah Știe toate lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Şi dacă sunteţi într-o călătorie şi nu găsiţi un scrib, atunci un zălog primit [este de ajuns]. Iar dacă aveţi încredere unul în altul, atunci să înapoieze lucrul întrebuinţat cel căruia i s-a încredinţat şi să se teamă de Allah, Domnul său! Să nu ascundeţi mărturia; cel care ascunde are o inimă păcătoasă şi Allah este Alim [Atoateștiutor] al celor pe care voi le făptuiţi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'Ale lui Allah sunt toate din Ceruri şi de pe Pământ. Şi dacă arătaţi sau ascundeţi ceea ce este în sufletele voastre, Allah vă va cere socoteală pentru acest lucru. Apoi El îl va Ierta pe cel care El va Voi şi îl va chinui pe cel care El va Voi. Allah este cu Putere peste toate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Mesagerul a crezut în ceea ce i-a fost pogorât de la Domnul său, de asemenea şi dreptcredincioşii. Fiecare dintre ei a crezut în Allah, în Îngerii Lui, în Scripturile Lui şi în Mesagerii Lui [spunând]: „Noi nu facem nicio deosebire între vreunul dintre Mesagerii Săi. Şi ei au spus: „Noi auzim şi ne supunem! [Căutăm] Iertarea Ta, Doamne, şi la Tine este întoarcerea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Allah nu-i impune niciunui suflet decât ceea ce este în putinţa lui. El va avea ca răsplată ceea ce a dobândit [în urma faptelor bune] şi împotriva lui ceea ce a dobândit [drept urmare a faptelor rele]. „Doamne, nu ne pedepsi pe noi, dacă am uitat sau am greşit. Doamne, nu ne împovăra pe noi cu greutate, aşa cum i-ai împovărat pe cei dinaintea noastră. Doamne, nu ne împovăra pe noi cu ceea ce nu putem îndura. Şi fii Îngăduitor cu noi, Iartă-ne şi fii Milostiv! Tu eşti Ocrotitorul nostru, ajută-ne pe noi să izbândim asupra necredincioşilor!”[66]', '[66] Allah încheie această sură cu instrucțiuni pentru robii Săi despre cum să I se roage Lui, la fel cum i-a învățat în Surat al-Fatihah cum să Îl preamărească și să se roage pentru călăuzire');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Alif, Lam, Mim.[1]', '[1] A se vedea nota 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Allah! Nu există altă divinitate în afară de El, Al-Hayy [Cel Viu], Al-Qayum [Cel Veșnic]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'El ți-a pogorât [o, Mohammed] Cartea cu Adevărul, confirmându-le pe cele de dinaintea ei. El a pogorât Tora și Evanghelia,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, 'Mai înainte, drept călăuză pentru oameni și El a pogorât Îndreptarul [Coranul]. Cu adevărat, cei care nu cred în Versetele lui Allah vor avea parte de chin aspru. Allah este Aziz [Atotputernic] și Dătător de pedeapsă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Cu adevărat, lui Allah nu-I este nimic ascuns, nici de pe Pământ, nici în Cer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'El este Cel care vă formează în utere așa cum Voiește El. Nu există altă divinitate în afară de El, Al-Aziz [Atotputernicul], Al-Hakim [Înțeleptul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'El este Cel care ți-a pogorât Cartea [o, Mohammed]. În ea sunt Versete clare - ele sunt temeiurile Cărții - și altele nedeslușite[2]. Cei în ale căror inimi se află rătăcire [de la adevăr] vor urma ce este nedeslușit, căutând vrajbă și în căutarea tâlcuirii lor. Dar nu cunoaște tâlcuirea lor [cea adevărată] decât Allah. Iar cei care sunt înrădăcinați în știință spun: „Noi credem în ea; toate sunt de la Domnul nostru!”. Dar nu cugetă astfel decât cei dăruiți cu judecată,', '[2] Cele care sunt precizate într-un mod deschis la mai multe interpretări sau al căror înțeles este cunoscut doar de către Allah, precum literele de deschidere de la anumite capitole');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, '[Care spun] „Doamne! Nu duce în rătăcire inimile noastre, după ce Tu ne-ai călăuzit și dă-ne nouă Îndurarea Ta, căci Tu ești Al-Uahab [Cel Darnic]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'Doamne! Tu îi vei aduna pe oameni într-o Zi despre care nu există nicio îndoială. Cu adevărat, Allah nu-și încalcă Promisiunea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Cu adevărat, acelora care nu cred, niciodată nu le vor fi de ajutor nici averile lor și nici copiii lor la Allah. Aceștia vor fi vreascuri pentru Foc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, '[Aceștia sunt] asemenea poporului lui Faraon și a celor de dinaintea lui. Ei au negat semnele Noastre, iar Allah i-a nimicit pentru păcatele lor. Și Allah este aspru în pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Spune-le celor care nu cred: „Veți fi biruiți [curând] și veți fi adunați spre Iad și ce loc de odihnă groaznic veți avea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'Ați avut deja un semn în cele două armate ce s-au întâlnit [în Bătălia de la Badr]: o armată care lupta pe calea lui Allah și o alta a necredincioșilor, [pe] care i-au văzut de două ori mai mulți decât ei, cu proprii lor ochi[3]. Dar Allah îl întărește cu Ajutorul Său pe cine Dorește El! În aceasta este o pildă pentru cei care au ochi să vadă!', '[3] Credincioșii au văzut că necredincioșii erau de două ori numărul lor înainte de Bătălia de la Badr, dar de fapt aceștia erau de trei ori mai numeroși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'Frumoasă a fost făcută să pară în ochii oamenilor dragostea pentru cele râvnite - femeile, copiii, multe grămezi de aur și argint, caii de rasă aleasă, animalele și ogoarele. Acestea sunt plăcerea vieții pământești, dar la Allah este buna întoarcere [Paradisul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'Spune: „Să vă vestesc [ceva] mai bun decât acestea? Aceia care sunt cu frică au de la Domnul lor grădini pe sub care curg râuri, în care vor avea veșnic sălaș, și soții curate și mulțumirea lui Allah, căci Allah este Basir [Cel care îi Vede Bine] pe robii Săi,”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'Care zic: „Doamne, cu adevărat noi credem, așadar iartă-ne păcatele noastre și ferește-ne pe noi de chinurile Focului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, '[Aceștia sunt] cei răbdători, cei sinceri, cei ascultători, cei care dau milostenie, și cei care cer iertare înainte de revărsatul zorilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Allah mărturisește că nu există altă divinitate în afară de El și [la fel și] Îngerii și cei înzestrați cu știință [mărturisesc] cu dreptate că: Nu există altă divinitate afară de El, Al-Aziz [Atotputernicul], Al-Hakim [Înțeleptul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Cu adevărat [unica] religie acceptată de Allah este Islamul și nu au fost deosebiri între cei cărora le-a fost dată Scriptura decât după ce a ajuns la ei știința, din cauza pizmei lor. Iar cel care nu crede în Versetele lui Allah [să știe că], cu adevărat Allah este grabnic la socoteală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Dacă ei ți se împotrivesc, spune-le: „M-am supus lui Allah [am acceptat Islamul] și [la fel și] cei care mă urmează!” Și spune-le celor care au primit Scriptura și celor fără de știință[4]: „V-ați supus lui Allah?” Și dacă s-au supus [acceptând Islamul], aceștia sunt bine călăuziți, dar dacă ei nu doresc, atunci responsabilitatea ta este doar transmiterea [Mesajului]. Și Allah este Basir [Cel care îi Vede Bine] pe robii Săi.', '[4] Păgânii care nu au primit nicio Scriptură');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Cei care nu cred în semnele lui Allah și-i omoară pe Profeți pe nedrept și-i omoară pe aceia dintre oameni care poruncesc dreptatea - acelora vestește-le o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'Aceia sunt cei ale căror fapte sunt lipsite de valoare în această viață cât și în Viața de Apoi și ei nu vor avea sprijinitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Oare nu i-ai văzut [o, Mohammed] pe aceia cărora li s-a dat o parte din Scriptură? Ei sunt chemați la Scriptura lui Allah pentru a judeca între ei, dar unii dintre ei întorc spatele și nu acceptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'Aceasta pentru că ei spun: „Focul nu ne va atinge decât numai [câteva] zile numărate!” Și [aceasta pentru că] i-a înșelat în credința lor ceea ce ei au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'Deci cum va fi, când Noi îi vom aduna, într-o Zi în legătură cu care nu este nicio îndoială? Și fiecare suflet va fi răsplătit după ceea ce a agonisit și când ei nu vor fi nedreptăți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, 'Spune: „O, Allah, Stăpân al Stăpânirii! Tu dai stăpânirea aceluia care Voiești și iei stăpânirea de la cel care Voiești. Tu îl cinstești pe cel care Voiești și îl umilești pe cel care Voiești. În Mâna[5] Ta se află [tot] binele. Cu adevărat, Tu ești Qadir [Cel cu Putere peste toate].', '[5] Allah spune în Coran că El are anumite atribute precum Auz, Văz, Mâini, Față, Milă, a se mânia, a veni, a cuprinde, a fi Înălțat deasupra Tronului etc, dar El se disociază de limitările atributelor umane sau de imaginația umană. Credința islamică corectă cere credința în existența acestor Atribute deoarece Allah le-a descris fără a le da un înțeles alegoric sau fără a explica cum ar putea fi o anumită calitate (deși aceasta este cunoscută doar de Allah) și fără a le compara cu creația sau fără a nega că El ar putea avea o asemenea calitate. Atributele Lui I se cuvin numai Lui, Unicul și „Nu este nimic asemenea Lui”. (42:11)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Tu faci să intre noaptea în zi, și Tu faci să intre ziua în noapte; Tu faci să se ivească viul din mort și faci să se ivească mortul din viu. Și Tu îl dăruiești [cu cele necesare traiului] pe cel care Dorești Tu, fără a ține socoteală [fără limită].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'Dreptcredincioșii să nu-i ia pe necredincioși drept aliați în locul dreptcredincioșilor. Cel care face aceasta nu va mai avea legătură cu Allah, cu excepția situației în care căutați o pavăză să vă feriți de ei. Dar Allah vă avertizează asupra [pedepsei] Lui și la Allah este întoarcerea [finală].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'Spune: „Dacă țineți ascuns ceea ce se află în piepturile voastre sau le faceți cunoscute, Allah le știe. El știe tot ce se află în Ceruri și tot ceea ce se află pe Pământ. Și Allah este Qadir [Cel cu Putere peste toate].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'În ziua în care fiecare suflet va vedea [în față] binele ce l-a făcut și răul ce l-a făcut, își va dori ca între el și acesta [răul] să fie o mare distanță. Allah vă avertizează asupra [pedepsei] Lui. Allah este Ra’uf [Iertător] cu robii [Săi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'Spune [o, Mohammed]: „Dacă Îl iubiți pe Allah, urmați-mă pe mine și Allah vă va iubi și vă va ierta păcatele. Și Allah este Ghafur [Iertător], Rahim [Îndurător]!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'Spune: „Ascultați-L pe Allah și pe Mesager [profetul Mohammed], dar dacă vă întoarceți spatele, atunci cu adevărat Allah nu-i iubește pe necredincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Cu adevărat, Allah i-a ales pe Adam, Noe, familia lui Avraam și familia lui Imran[6] peste toate lumile -', '[6] Imran este tatăl Fecioarei Maria, mama lui Iisus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'Ca descendenți unii din alții. Allah este Sami [Cel care Aude Totul], Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, '[Spune, o, Mohammed] când soția lui Imran a spus: „Doamne, Îți făgăduiesc Ție ceea ce se află în pântecul meu, devotat numai Ție! Primește-l de la mine. Tu ești As-Sami [Cel care Aude Totul], Al-Alim [Atoateștiutorul]. ”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'Dar când a născut, a spus: „Doamne, am născut o copilă.” Dar Allah știa bine ceea ce născuse ea și un băiat nu este precum o copilă. „Eu i-am pus numele Maria și caut refugiu la Tine pentru ea și pentru descendenții ei, împotriva lui șeitan cel izgonit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Domnul ei a acceptat-o cu bună primire și a lăsat-o să crească cu bună creștere și i-a încredințat-o lui Zaharia[7]. De fiecare dată când intra Zaharia la ea în templu, vedea lângă ea mâncare. El a întrebat-o: „O, Maria, de unde ai aceasta?” Iar ea îi răspundea: „Ea este de la Allah. Cu adevărat, Allah îl hrănește pe cel pe care El voiește, fără socoteală!”', '[7] Tatăl lui Ioan Botezătorul (în arabă Yahya)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'Atunci, Zaharia s-a rugat Domnului său, spunând: „Doamne, dăruiește-mi mie de la Tine un copil bun, căci Tu ești Sami [Cel care Aude] ruga.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'Atunci, l-au chemat Îngerii, în vreme ce el se ruga, stând în picioare, în Al-Mihrab [loc destinat rugăciunii], [spunându-i]: „Cu adevărat, Allah ți-l vestește pe Yahya, care va adeveri un Cuvânt[8] al lui Allah și [care va fi] un bărbat nobil, neprihănit, un Profet dintre cei evlavioși”.', '[8] Referindu-se la profetul Iisus (pacea fie asupra sa), care a fost conceput doar prin Porunca lui Allah – cuvântul „Fii”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, 'El a spus: „Doamne, cum să am eu un băiat, când m-au ajuns bătrânețile, iar soția mea nu mai poate face copii?” Iar [Allah] i-a răspuns: „Așa este Allah; El Face ceea ce Voiește!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, 'El a spus: „Doamne, dă-mi mie un semn.” El i-a răspuns: „Semnul tău va fi că nu vei putea vorbi cu oamenii, timp de trei zile, decât prin semne! Și pomenește-L pe Domnul tău des și laudă-L pe El seara și dimineața!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'Și [spune] când Îngerii au spus: „O, Maria! Allah te-a ales și te-a făcut pură și te-a ales peste femeile lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, 'O, Maria! Fii cu ascultare față de Domnul tău, prosternează-te și pleacă-te, rugându-te împreună cu cei ce se pleacă [în rugăciune]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'Acestea sunt dintre veștile necunoscutului pe care Noi ți le revelăm ție [o, Mohammed]. Tu nu ai fost lângă ei, când ei au aruncat calemurile lor[9] [pentru a hotărî] care dintre ei să o aibă în grijă pe Maria și nu ai fost lângă ei nici când ei au dezbătut.', '[9] Au tras la sorți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'Și [spune] când Îngerii au spus: „O, Maria! Allah îți vestește un Cuvânt[10] din partea Lui: numele lui va fi Mesia, Iisus, fiul Mariei, măreț în această lume precum și în lumea de Apoi și unul dintre cei mai apropiați [de Allah].', '[10] A se vedea nota 3:39');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, 'El le va vorbi oamenilor din pruncie și când va fi un bărbat adult[11] și va fi dintre cei dreptcredincioși”.', '[11] 30-50 de ani');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, 'Ea a spus: „Doamne, cum să am un copil fără să mă fi atins un bărbat?” [Îngerul] i-a răspuns: „Așa este Allah; El face ceea ce voiește.” Când El hotărăște un lucru, El Spune doar „Fii” și el este de îndată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, 'Și El îl va învăța scrierea și înțelepciunea[12], Tora și Evanghelia.', '[12] Învățăturile profeților');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'Și trimis la fiii lui Israel [le va spune]: „Cu adevărat, eu vin la voi cu semne de la Domnul vostru. Eu plămădesc pentru voi din lut un chip de pasăre și suflu asupra sa și se va transforma într-o pasăre vie, cu Voia lui Allah. Și-i voi vindeca pe orb și pe lepros, și-i voi învia pe morți, cu Voia lui Allah. Eu vă voi vesti ceea ce mâncați și ceea ce păstrați în casele voastre. În aceasta este un semn pentru voi, dacă voi sunteți credincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'Și [eu am venit] pentru a întări ceea ce a fost revelat în Tora mai înainte de mine și vă voi permite o parte din cele ce v-au fost interzise. Și eu am venit la voi cu un Semn de la Domnul vostru, deci fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Cu adevărat, Allah este Stăpânul meu și Stăpânul vostru, așadar, adorați-L pe El! Aceasta este Calea cea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'Dar când Iisus a simțit necredința lor, le-a zis: „Cine sunt sprijinitorii mei [în chemarea] la Allah?” Apostolii au răspuns: „Noi suntem sprijinitorii [religiei] lui Allah! Noi credem în Allah și mărturisim că suntem supuși [lui Allah] musulmani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, 'Doamne, noi credem în ceea ce Tu ai pogorât și-l urmăm pe Mesager [Iisus], deci scrie-ne pe noi printre cei care fac mărturie [cu privire la adevăr]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'Și ei [necredincioșii] au plănuit, dar și Allah a plănuit. Și Allah este Cel mai bun dintre plănuitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, '[Spune] când Allah a spus: „O, Iisus! Eu te voi înălța la Mine, te voi mântui de cei care nu cred și îi voi pune pe cei care te-au urmat [în adorarea lui Allah Unicul] deasupra celor care nu cred până în Ziua Învierii. Apoi la Mine va fi întoarcerea voastră și Eu voi judeca asupra celor în care voi nu vă înțelegeți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Cât despre cei care nu au crezut, pe ei îi voi supune la o pedeapsă severă atât în această lume, cât și în Lumea de Apoi și ei nu vor avea pe nimeni să-i ajute.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'Cât despre cei care cred și săvârșesc fapte bune, El le va da răsplata meritată și Allah nu-i iubește pe cei nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Acestea ți le recităm ție [o, Mohammed] din versete [noastre] și Mesajul[13] clar [și înțelept]', '[13] Coranul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Cu adevărat, exemplul lui Iisus la Allah este asemenea celui al lui Adam. El l-a creat din lut, apoi El i-a spus: „Fii” și el a fost.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Adevărul este de la Domnul tău, așadar nu fi dintre aceia care se îndoiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'Acelora care se contrazic cu tine [o, Mohammed], în privința lui [Iisus], după ce ai primit știința, spune-le: „Veniți, să-i chemăm pe fii noștri și pe fii voștri, pe femeile noastre și pe femeile voastre, pe noi înșine și pe voi înșivă, apoi să ne rugăm [împreună] și să chemăm blestemul lui Allah asupra celor [dintre noi] care mint.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'Cu adevărat, aceasta este povestea cea adevărată. Și nu există altă divinitate în afară de Allah. Și cu adevărat Allah este Al-Aziz [Puternic], Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'Iar dacă ei întorc spatele, atunci cu adevărat Allah este Alim [Atoateștiutor] cu cei care seamănă stricăciune!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'Spune: „O, voi oameni ai Scripturii, veniți la un cuvânt comun între noi și voi - că nu-L vom adora decât pe Allah și că nu-I vom face asociați, și că nu ne vom lua unii pe alții drept dumnezei în locul lui Allah.” Dar dacă ei vor întoarce spatele, spuneți-[le]: „Mărturisiți [cel puțin] că noi suntem musulmani [supuși lui Allah]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'O, voi oameni ai Scripturii, de ce vă contraziceți asupra lui Avraam, când Tora și Evanghelia nu au fost revelate decât după el? Voi nu aveți judecată?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Voi sunteți aceia care ați avut dispute asupra lucrurilor despre care ați avut știință, dar de ce stârniți dispute asupra lucrurilor despre care nu aveți știință? Și Allah Știe, în vreme ce voi nu știți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'Avraam nu a fost nici evreu, nici creștin, ci a fost credincios adevărat și musulman [supus lui Allah]. Și el nu a fost dintre politeiști[14].', '[14] Cei care îi fac asociați lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'Cu adevărat, cei mai vrednici de Avraam dintre oameni sunt cei care l-au urmat pe el [în supunerea față de Allah] și pe acest Profet [Mohammed] și cei care cred [în acest mesaj]. Iar Allah este Ocrotitorul credincioșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'O parte dintre oamenii Scripturii ar fi vrut să vă pricinuiască rătăcirea, dar ei nu-și pricinuiesc decât lor înșiși rătăcire și nu își dau seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'O, oameni ai Scripturii, de ce nu credeți în versetele lui Allah, când voi sunteți martori [că ele sunt adevărate]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'O, oameni ai Scripturii, de ce amestecați adevărul cu falsitatea și ascundeți adevărul deși voi îl cunoașteți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Și o parte dintre oamenii Scripturii [evreii] [își] spun [unii altora]: „Credeți în ceea ce le-a fost revelat credincioșilor la începutul zilei și lepădați-vă de aceasta la sfârșitul ei; poate că ei se vor întoarce [la vechea lor religie],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, '[Oamenii Cărți spun semenilor lor:] Și nu aveți încredere decât în cei care vă urmează religia voastră.” Spune: „Cu adevărat, [Adevărata] Călăuzire este Călăuzirea lui Allah. [Vă este teamă] ca nu cumva unii să primească [știința] așa cum vi s-a dat vouă sau că aceștia ar putea să aducă vorba împotriva voastră la Domnul vostru?”. Spune[-le] lor: „Cu adevărat Harul este în Mâna lui Allah; El îl dăruiește aceluia care Voiește El. Allah este Uasi [Cel Cu Har Nemărginit], Alim [Atoateștiutor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Allah alege pentru Îndurarea Sa pe acela care Voiește El, căci Allah este Cel cu Har nemărginit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Printre oamenii Scripturii sunt unii [evreii] care, dacă le-ai încredința o cantitate mare [de avere], ți-o vor returna, dar printre ei sunt și alții care, dacă le-ai încredința o [singură] monedă de argint, nu ți-o vor returna decât dacă tu insiști fără încetare. Pentru că ei zic: „Noi nu avem îndatoriri față de acești neînvățați.”[15] Și ei spun minciuni împotriva lui Allah deși aceștia cunosc adevărul.', '[15] Evreii nu considerau mințirea sau înșelarea unui politeist sau a unui ne-evreu a fi păcate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Dimpotrivă, cei care-și țin făgăduința și au frică de Allah, [aceia trebuie să știe că] Allah îi iubește pe cei care se tem de El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Însă aceia care-și vând făgăduința dată lui Allah și jurămintele lor pe un preț de nimic nu vor avea parte în Viața de Apoi. Și Allah nu le va Vorbi lor, nici nu-Și va îndrepta Privirea spre ei în Ziua Învierii și nici nu-i va purifica. Și vor avea ei parte de o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Cu adevărat, printre ei sunt unii [evreii] care modifică Scriptura [Tora] cu limbile lor, pentru ca voi să credeți că [aceasta] este din Scriptură, însă aceasta nu este din Scriptură și ei spun: „Aceasta este de la Allah”, dar nu este de la Allah. Ei spun minciuni împotriva lui Allah deși aceștia cunosc adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Nu i se cuvine unui om căruia Allah i-a dăruit Scriptura[16], autoritatea și Profeția să le spună apoi oamenilor: „Fiți adoratorii mei și nu ai lui Allah”, ci [se cuvine să spună]: „Fiți supuși Domnului [și învățători pioși], întrucât voi ați învățat [pe alții] Scriptura și ați învățat și voi [din ea]".', '[16] Sau în cazul profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) „Cartea” (Coranul)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Și nici nu v-ar putea porunci să-i luați pe Îngeri și pe Profeți drept Domni. Oare ar putea să vă poruncească necredința după ce ați fost musulmani [supuși ai lui Allah]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'Și [aduceți-vă aminte, o, Oameni ai Cărții] când Allah a încheiat un legământ cu Profeții, [spunându-le]: „Vă dau vouă Scriptura și Înțelepciunea. Apoi, dacă va veni la voi un Mesager pentru a întări ceea ce aveți, voi trebuie să credeți în el și să-l sprijiniți!” [Allah] a spus: „Consimțiți voi și acceptați această învoială cu Mine?” Ei au răspuns: „Consimțim!” Atunci a zis Allah: „Atunci mărturisiți, iar Eu Mă aflu împreună cu voi printre cei care mărturisesc!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'Și oricine va respinge după aceasta - aceia sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Doresc ei o altă religie decât Religia lui Allah, din moment ce Lui I s-au supus toate din Ceruri și de pe Pământ, de voie ori de nevoie și la El se întorc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, 'Spune, [o, Mohammed]: „Noi credem în Allah, în ceea ce ne-a pogorât nouă și în ceea ce i-a fost pogorât lui Avraam, lui Ismail, lui Isaac, lui Iacob și Descendenților [al-Asbat], precum și în ce i-a fost pogorât lui Moise, lui Iisus și tuturor Profeților de către Domnul lor. Noi nu facem nicio deosebire între ei și noi suntem musulmani [Îi suntem supuși Lui]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'Acela care își dorește altă religie decât Islamul, nu-i va fi acceptată, și el se va afla în Lumea de Apoi printre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'Cum să călăuzească Allah un popor care a refuzat credința, după ce a crezut și după ce a mărturisit că Mesagerul este adevărat și după ce i-au venit semnele limpezi? Allah nu-i călăuzește pe oamenii nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'Răsplata acestora este blestemul lui Allah, al Îngerilor și al tuturor oamenilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'În veci vor rămâne în el [în Iad], iar pedeapsa lor nu va fi ușurată și nici răgaz nu li se va da,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Cu excepția celor care se căiesc după aceea și se îndreaptă. Cu adevărat Allah este Al-Ghafur [Iertător], Al-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'Cu adevărat acelora care nu mai cred după ce [mai înainte] crezuseră, iar apoi sporesc necredința lor – căința lor nu le va fi primită și aceia sunt cei rătăciți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Cu adevărat, cei care nu cred și mor necredincioși - nu se va primi niciodată de la vreunul dintre ei nici chiar întregul pământ în aur, chiar dacă ei ar voi să se răscumpere cu el. Aceia vor avea parte de pedeapsă dureroasă și ei nu vor avea pe nimeni să-i ajute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Nu veți primi răsplata bună[17] până când nu veți face daruri din ceea ce vă este drag. Și Allah Știe tot ceea ce voi dăruiți.', '[17] Un alt înțeles este „Nu veți obține evlavia adevărată”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'Toate mâncărurile le-au fost permise Fiilor lui Israel, în afară de ceea ce Israel [Iacob] însuși și-a oprit, înainte ca Tora să fi fost trimisă. Spune-le [o, Mohammed]: „Aduceți Tora și citiți-o, dacă ceea ce spuneți voi este adevărat!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'Și cei care, după toate acestea, născocesc minciuni despre Allah, ei sunt cu adevărat nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'Spune: „Allah a spus Adevărul! Urmați, așadar, religia lui Avraam cel drept întru credință, care nu a fost dintre politeiști.”[18]', '[18] A se vedea nota 3:67');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Cu adevărat, Cea dintâi Casă [pentru adorarea lui Allah] ridicată pentru oameni este aceea din Bakka [Mecca], cea binecuvântată și călăuzire pentru toate lumile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'În ea sunt semne limpezi, [precum] locul unde a stat Avraam, iar acela care intră în ea este în siguranță. Și este o datorie a oamenilor față de Allah [să împlinească] Pelerinajul la această Casă, dacă au mijloacele necesare. Cât despre cei care nu cred [refuză], Allah nu are nevoie de aceste lumi[19].', '[19] El nu are nevoie de adorarea robilor Săi, ei sunt cei care au nevoie de El');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, 'Spune: „O, oameni ai Scripturii, de ce nu credeți în Versetele lui Allah în timp ce Allah este Martor la ceea ce faceți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'Spune: „O, oameni ai Scripturii, de ce îi abateți pe cei care cred de la calea lui Allah dorind a o face să pară greșită în timp ce voi sunteți martori [la adevăr]?” Iar Allah Știe ceea ce faceți voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'O, voi cei care credeți! Dacă voi urmați o parte dintre aceia cărora li s-a dăruit Scriptura, aceasta v-ar face să întoarceți spatele după ce ați crezut, făcându-vă din nou necredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'Și cum ați putea voi să nu credeți când vi se recită Versetele lui Allah și printre voi se află Mesagerul Lui? Iar cel care se va ține neclintit de Allah[20], va fi călăuzit pe un drum drept.', '[20] Respectând Poruncile Lui, având încredere în El');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'O, voi cei care credeți! Fiți cu frică de Allah, așa cum se cuvine să fie frica de El și nu muriți decât ca musulmani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Și țineți-vă cu toții strâns de Frânghia[21] lui Allah și nu vă scindați! Și aduceți-vă aminte de Îndurarea lui Allah pentru voi, când ați fost dușmani [înainte de Islam] iar El a făcut pace între inimile voastre [la primirea Islamului] și ați devenit, prin Harul Lui, frați. Și ați fost pe marginea prăpastiei Focului, iar El v-a salvat de la el. Așa vă face Allah clare Versetele Sale, pentru ca voi să fiți bine călăuziți.', '[21] Referindu-se fie la Legământul Lui, fie la Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'Să se facă din voi o comunitate care să cheme la tot ceea ce este bun, să poruncească ceea ce este drept și să interzică ceea ce este nedrept[22]! Aceștia sunt cei care izbândesc.', '[22] Conform legilor lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'Și nu fiți asemenea celor care s-au scindat și au avut neînțelegeri după ce le-au venit dovezile clare! Aceștia vor avea parte de o pedeapsă cumplită!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'În acea Zi[23] [unele] chipuri se vor lumina, iar [alte] chipuri se vor întuneca. Acelora cu chipurile întunecate [li se va spune]: „V-ați lepădat de credință, după ce ați fost credincioși? Gustați atunci pedeapsa pentru necredința voastră!”.', '[23] Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'Cât despre cei cu chipurile luminoase, ei se vor afla sub Îndurarea lui Allah [Paradis]. În ea vor sălășlui în veci.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'Acestea sunt Versetele lui Allah. Noi ți le recităm ție [o, Mohammed], întru adevăr și Allah nu voiește nedreptățirea lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'Ale lui Allah sunt cele din Ceruri și de pe Pământ și la Allah se întorc toate lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Sunteți cea mai bună comunitate care s-a făcut [drept exemplu] pentru oameni. Voi porunciți ceea ce este drept și interziceți ceea ce este nedrept și credeți în Allah. Dacă oamenii Scripturii ar fi crezut, ar fi fost bine pentru ei. Printre ei sunt și credincioși, dar cei mai mulți dintre ei sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Ei nu vă vor face rău decât numai puțin [cu vorba]. Iar dacă se vor lupta cu voi, vă vor întoarce spatele [fugind] și nu vor fi ajutați [de nimeni].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'Ei sunt umiliți [de Allah], oriunde se află, în afară de [situația în care] vor fi ajutați de un legământ cu Allah sau de un legământ cu oamenii [musulmanii]. Ei și-au atras mânia lui Allah și umilința cade asupra lor și aceasta pentru că nu au crezut în Versetele lui Allah și i-au omorât pe Profeți pe nedrept. Aceasta pentru că nu au ascultat și s-au răzvrătit [împotriva lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Dar nu toți sunt la fel. Se află printre oamenii Scripturii o comunitate[24] dreaptă, care recită Versetele lui Allah în timp de noapte și se prosternează [rugându-se].', '[24] Dintre cei care au acceptat Islamul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Ei cred în Allah și în Ziua de Apoi, poruncesc ceea ce este drept și interzic ceea ce este nedrept și se grăbesc la faptele bune; aceștia sunt printre cei dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Și orice bine pe care îl fac – acesta nu le poate fi negat. Și Allah îi Știe bine pe cei dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Cu adevărat, cei care nu au crezut - nici averile lor, nici copiii lor nu le vor fi de niciun folos la Allah. Aceștia sunt oaspeții Focului și în el vor sălășlui veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Exemplul a ceea ce cheltuiesc ei în această viață seamănă cu un vânt care aduce frig tăios, ce se abate peste culturile unor oameni, care au fost nedrepți cu ei înșiși [au păcătuit] și le distruge. Iar Allah nu i-a nedreptățit, ci ei înșiși s-au nedreptățit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'O, voi cei care credeți, nu luați prieteni de încredere dintre cei ce nu sunt ai voștri [credincioși], căci ei nu vor înceta să vă prejudicieze. Ei vă doresc greutăți. Ura se ivește din gurile lor, dar ceea ce ascund piepturile lor este și mai mare. Noi v-am arătat vouă semnele limpezi, dacă voi puteți pricepe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'Iată că voi îi iubiți pe ei, dar ei nu vă iubesc pe voi, în vreme ce voi credeți în toată Scriptura [revelată înainte de Coran și nealterată]. Iar când se întâlnesc cu voi, ei spun: „Noi credem”, dar când rămân singuri, își mușcă vârfurile degetelor de ciudă împotriva voastră. Spune: „Pieriți cu ciuda voastră. Cu adevărat, Allah Știe prea bine ce se află în piepturi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Dacă voi aveți parte de ceva bun, ei sunt mâhniți, dar dacă vi se întâmplă ceva rău, ei se bucură de aceasta. Însă dacă veți fi cu răbdare și vă veți teme de Allah, viclenia lor nu vă va pricinui nimic rău. Cu adevărat, Allah cuprinde cu Știința Sa ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'Și [adu-ți aminte, o, Mohammed] când ai plecat dimineața de la familia ta, pentru a stabili credincioșilor locurile de luptă [la Uhud]! Allah este Sami [Cel care Aude Totul], Alim [Atotcunoscător] -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, '[Adu-ți aminte, o, Mohammed] când două armate de-ale voastre erau pe punctul a-și pierde curajul, dar Allah a fost Ocrotitorul lor; pe Allah trebuie să se bizuie credincioșii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Allah v-a făcut învingători la Badr[25] când voi erați slabi [puțini la număr]. Deci fiți cu frică de Allah și poate că voi o să fiți mulțumitori!', '[25] Bătălia de la Badr din anul 2 D.H (624), prima confruntare dintre Profet (pacea și binecuvântarea lui Allah fie asupra sa) cu păgânii din Mecca, în care musulmanii, deși în număr mic și slab înarmați au ieșit victorioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, '[Și adu-ți aminte], când tu le-ai spus credincioșilor: „Nu este suficient pentru voi ca Domnul vostru să vă ajute cu trei mii de Îngeri pogorâți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Ba da! Dacă aveți răbdare și frică de Allah, atunci când [dușmanii] se năpustesc asupra voastră, Domnul vostru vă va susține cu cinci mii de Îngeri înzestrați cu semne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'Și Allah nu a făcut-o decât [un semn de] veste bună și pentru ca inimile voastre să se liniștească prin aceasta. Victoria nu poate veni decât de la Allah Al-’Aziz [Puternicul], Al-Hakim [Înțeleptul];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'Pentru a nimici o parte dintre necredincioși sau pentru a-i supune prin umilire, astfel încât să se întoarcă dezamăgiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'Nu decizi tu [o, Mohammed, ci Allah,] dacă El, fie primește căința lor, fie că îi pedepsește, pentru că ei sunt într-adevăr nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'Ale lui Allah sunt toate cele din Ceruri și de pe Pământ; El iartă pe cine Voiește și pedepsește pe cine Voiește. Căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'O, voi cei care credeți, nu luați camătă dublată și înmulțită fără măsură, ci fiți cu frică de Allah, ca să izbândiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'Și fiți cu teamă de Focul cel pregătit pentru necredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'Și fiți supuși față de Allah și față de Mesager, ca să fiți iertați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, 'Și grăbiți-vă spre iertarea Domnului vostru și spre o grădină [Rai] întinsă cât Cerurile și Pământul, pregătită pentru cei evlavioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, 'Care cheltuiesc [pentru Allah] atât atunci când au parte de belșug, cât și atunci când sunt la necaz, care-și stăpânesc mânia și care iartă oamenilor, căci Allah îi Iubește pe cei care împlinesc fapte bune;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, 'Și pe cei care, dacă au săvârșit o faptă josnică sau au fost nedrepți cu propriile lor suflete, își aduc aminte de Allah și Îi cer iertare pentru păcatele lor - și cine poate ierta păcatele decât Allah? - și care nu persistă cu bună știință în ceea ce săvârșesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'Răsplata acestora va fi iertarea Domnului lor și Grădini pe sub care curg râuri [în Paradis] și în ele vor avea sălaș veșnic. Și ce minunată este răsplata pentru cei care fac bine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Înainte de voi, au fost situații asemănătoare [ca ale voastre], așa că umblați prin lume și vedeți care-i sfârșitul mincinoșilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'Aceasta [Coranul] este deslușire pentru oameni, călăuzire și îndemn pentru cei cu frică de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'Nu fiți slabi și nici întristați, căci voi veți fi cei biruitori, dacă sunteți credincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Dacă v-a atins o rană, și ceilalți oameni [adversarii voștri] au primit răni asemenea ei. Astfel schimbăm Noi aceste zile [de condiții diferite] între oameni, pentru ca Allah să-i cunoască pe cei care cred și să aleagă dintre voi martiri. Allah nu-i iubește pe cei nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'Și pentru ca Allah să-i purifice pe credincioși [prin încercări] și să-i pedepsească pe cei necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Sau ați crezut voi că veți intra în Rai fără ca Allah să-i vădească pe cei dintre voi care au luptat pentru El și să-i vădească pe cei care au fost statornici?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Bineînțeles, voi v-ați dorit moartea [martiriu] înainte de a o întâlni și ați văzut-o acum [înaintea voastră] în timp ce ați privit [la ea cu ochii voștri][26].', '[26] Când ați văzut în jurul vostru semeni uciși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Și Mohammed nu este decât un Mesager. [Alți] Mesageri au mai fost înainte de el. Dacă el ar muri sau ar fi ucis, v-ați întoarce voi pe călcâiele voastre [în necredință]? Cel care s-ar întoarce pe călcâiele lui nu I-ar aduce nicio stricăciune lui Allah. Și Allah îi va răsplăti pe cei mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Niciun suflet nu poate muri fără de Voia lui Allah, după sorocul scris. Cel care vrea răsplata în această lume, Noi i-o vom da în ea, iar cel care vrea răsplata în Lumea de Apoi, Noi i-o vom da în ea și Noi îi vom răsplăti pe cei mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'Și câți Profeți au luptat - și laolaltă cu ei nenumărați învățați evlavioși - și nu și-au pierdut ei siguranța în fața loviturilor pe care le-au primit pe Calea lui Allah! Și nici nu au fost slăbiți și nici nu au cedat! Și Allah îi Iubește pe cei statornici [și răbdători]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Și ei n-au avut alt cuvânt decât să spună: „Doamne, iartă-ne păcatele noastre și silnicia din purtarea noastră, întărește-ne picioarele noastre și ajută-ne pe noi să-i înfrângem pe cei necredincioși!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Și Allah le-a dăruit răsplată în această lume și bună răsplată în Lumea de Apoi, căci Allah îi Iubește pe cei care fac bine [Al-Muhsinin].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'O, voi cei care credeți! Dacă vă veți supune celor necredincioși, ei vă vor face să vă întoarceți pe călcâiele voastre și veți redeveni pierduți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Însă Allah este Protectorul vostru și El este Cel mai bun dintre sprijinitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'Noi vom semăna spaimă în inimile celor necredincioși pentru că I-au asociat lui Allah [idoli], fără ca El să fi trimis nicio dovadă pentru aceasta. Iar sălașul lor va fi Focul, și ce rău sălaș va fi pentru cei nedrepți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Allah și-a ținut făgăduința Sa față de voi atunci când, cu permisiunea Lui, i-ați nimicit [pe dușmani] până ce v-ați pierdut curajul și v-ați împotrivit unii altora asupra poruncii [date de Profet (pacea și binecuvântarea lui Allah fie asupra sa)] și nu ați mai ascultat după ce El v-a arătat [biruința] pe care o iubeați[27]. Printre voi sunt unii care doresc această lume și printre voi sunt alții care doresc Lumea de Apoi. După aceea, El v-a făcut să dați înapoi în fața lor[28], pentru a vă încerca. Însă El v-a iertat deja, căci Allah este plin de Har cu dreptcredincioșii[29].', '[27] Prada de război
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, '[Aduceți-vă aminte] când [fugind] ați urcat [muntele], fără să vă uitați la cineva, în timp ce în urma voastră, Mesagerul vă chema [să vă întoarceți]. Atunci Allah v-a răsplătit cu suferință după suferință, ca să nu fiți mâhniți pentru ceea ce ați pierdut [prada de război] și pentru ceea ce v-a lovit [vătămare și moarte]. Allah este Khabir [Bineștiutor] a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Apoi, după suferință, El a pogorât asupra voastră liniște [sub formă de] somn, învăluind o parte dintre voi, în timp ce o altă parte a fost cuprinsă de griji, gândind lucruri neadevărate despre Allah – gânduri de ignoranță, spunând: „Trebuia să fi făcut noi ceva în această chestiune?” Spune: „Cu adevărat, această chestiune este în întregime a lui Allah”. Ei ascundeau în sufletele lor ceea ce nu îți arătau ție, spunând: „Dacă noi am fi putut face ceva în chestiunea aceasta, [unii dintre noi] nu am fi fost omorâți aici”. Spune: „Chiar dacă voi ați fi fost în casele voastre, acelora cărora le era scris să fie uciși ar fi ieșit la locurile morții lor!”. Dar [toate acestea au fost] pentru că Allah a Voit să testeze ceea ce se afla în piepturile voastre și să purifice ceea ce se afla în inimile voastre. Dar Allah este Știutor a ceea ce se află în piepturi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'Cu adevărat, pe aceia dintre voi care au întors spatele în ziua când s-au întâlnit cele două oștiri [la Uhud], numai Șeitan i-a făcut să se poticnească pentru unele [fapte rele] pe care le-au agonisit. Dar Allah i-a iertat deja, căci Allah este Ghafur [Iertător], Halim [Blând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'O, voi cei care credeți! Nu fiți asemeni celor care au tăgăduit și au spus despre frații lor care umblă pământul [pentru negoț] sau purced la luptă: „Dacă ei ar fi fost cu noi, ei nu ar fi murit sau nu ar fi fost omorâți”. Allah face aceasta [înțelegere greșită] un regret în inimile lor. Și Allah este Cel care Dă viață și moarte, și Allah este Basir [Cel care Vede toate] a ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'Și dacă veți fi omorâți pe Calea lui Allah sau veți muri, atunci Iertarea și Îndurarea lui Allah sunt mai bune decât ceea ce ei agonisesc [în această lume].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'Și dacă veți muri sau veți fi uciși, la Allah vă veți aduna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, 'Și datorită Îndurării lui Allah, tu, [o, Mohammed], ai fost așa de blând cu ei! Iar de ai fi fost aspru [în vorbire] și crud la inimă, ei ar fi fugit din preajma ta. Deci iartă-i și roagă-te [lui Allah] pentru iertarea lor și sfătuiește-te cu ei asupra treburilor. Dar când ai luat o hotărâre, încrede-te în Allah. Cu adevărat, Allah îi Iubește pe cei care se încred [în El].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Dacă Allah vă va ajuta, nimeni nu vă va putea învinge, dar dacă El vă va părăsi, cine este acela care ar putea să vă ajute după El? În Allah trebuie să se încreadă dreptcredincioșii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Nu este [potrivit] pentru un Profet să se comporte necinstit [în ceea ce privește prada de război]. Iar acela care trădează [luând în mod necinstit], va veni cu ce a luat în Ziua de Apoi. Atunci fiecare suflet va primi [pe de-a-ntregul] răsplata câștigată. Și lor nu li se va face nedreptate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Este cel care a căutat mulțumirea lui Allah la fel ca cel care și-a atras mânia lui Allah și al cărui sălaș va fi Focul? Și ce neplăcută menire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Ei sunt [pe] trepte [diferite] la [răsplata lui] Allah și Allah Vede bine ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Cu adevărat Allah și-a arătat Bunăvoința față de credincioși, trimițându-le un Mesager dintre ei, care să le recite Versetele Sale, să-i purifice și să-i învețe Cartea [Coranul] și Înțelepciunea, chiar dacă au fost mai înainte în rătăcire învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'De ce atunci când o [singură] nenorocire v-a lovit [la Bătălia de la Uhud], deși voi ați lovit [dușmanul în Bătălia de la Badr] de două ori pe-atât, ați spus: „De unde a venit aceasta?”. Spune: „A venit de la voi [din cauza păcatelor voastre]!”. Cu adevărat Allah are Putere peste toate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'Și ceea ce a venit peste voi în ziua când cele două armate s-au întâlnit [la Uhud], a fost cu Voia lui Allah, pentru ca El să-i facă cunoscuți pe [adevărații] credincioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'Și să-i deosebească pe cei care erau ipocriți. [Pentru aceasta] li s-a spus lor: „Veniți și luptați pe Calea lui Allah sau [cel puțin] apărați!”. Ei au răspuns: „Dacă am fi știut că va fi o luptă, v-am fi urmat.” În acea zi ei erau mai aproape de necredință decât de credință, spunând cu gurile lor ceea ce nu era în sufletele lor. Dar Allah Știa prea bine ceea ce ei ascundeau -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, 'Cei care au spus despre frații lor în timp ce stăteau [în casele lor][30]: „Dacă ne-ar fi ascultat, ei n-ar fi fost omorâți”. Spune-le: „Atunci țineți moartea departe de voi, dacă voi spuneți adevărul!”', '[30] Ipocriții menționați în versetul 167');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Și niciodată să nu crezi că cei care au fost uciși pe Calea lui Allah [martirii] sunt morți! Dimpotrivă, ei sunt vii la Domnul lor și sunt bine dăruiți [din roadele Raiului],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Și se bucură de Binefacerea pe care Allah le-a dăruit-o și primesc vești bune despre cei rămași în urma lor și nu li s-au alăturat încă [și care urmează să fie martiri] - că ei nu se vor teme și nici nu vor fi mâhniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'Li se aduc lor vești bune despre Binefacerea lui Allah și Harul Său, precum și despre aceea că Allah nu lasă să se piardă răsplata credincioșilor -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, 'Acei [credincioși] care au răspuns chemării lui Allah și a Mesagerului, după ce au fost loviți. Aceia dintre ei care au făcut bine și au fost cu frică [de Allah] vor avea mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, 'Acelora cărora oamenii [ipocriții] le-au spus: „Cu adevărat, oamenii s-au adunat împotriva voastră, deci temeți-vă de ei!”. Dar aceasta le-a sporit credința și au spus: „Ajutorul lui Allah ne este suficient și El este Cel mai Bun Ocrotitor al nostru!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'Și ei s-au întors cu Binefacerea lui Allah și Harul Său, fără să-i fi atins niciun rău. Ei au căutat Mulțumirea lui Allah, căci Allah este Dătător de Har nemăsurat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'Doar Șeitan este cel care vă îndeamnă să vă temeți de părtașii săi, dar voi să nu vă temeți de ei, ci temeți-vă de Mine, dacă sunteți credincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Și să nu te mâhnească aceia care se grăbesc la necredință! Ei doară nu-i pot strica întru nimic lui Allah. Allah nu voiește să le facă lor parte în Lumea de Apoi, ci pentru ei este mare chin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'Cu adevărat, aceia care cumpără [schimbă] necredința în locul credinței, nu-I pot aduce niciun rău lui Allah, iar pentru ei va fi chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Și să nu creadă necredincioșii că răgazul pe care li-l dăm este mai bun pentru ei. Noi avem îndelungă răbdare cu ei pentru ca păcatele lor să se înmulțească. Iar ei vor avea parte de pedeapsă umilitoare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'Allah nu-i va lăsa pe credincioși în starea în care sunteți [acum], decât până când îl va despărți pe cel rău de cel bun. Și nici nu vă va dezvălui vouă Allah Tainele celor nevăzute, ci Allah alege [pentru aceasta] dintre Mesagerii Lui pe cine Voiește El. Credeți, așadar, în Allah și în Trimișii Săi! Și dacă veți crede și veți fi cu frică, veți avea parte de răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Să nu creadă aceia care sunt zgârciți cu ceea ce Allah le-a dăruit din Harul Său că aceasta este mai bine pentru ei! Dimpotrivă, aceasta este mai rău pentru ei. În Ziua de Apoi gâturile lor vor fi încolăcite cu cele cu care au fost zgârciți. Și a lui Allah este Moștenirea Cerurilor și a Pământului. Cu adevărat, Allah este Khabir [Bineștiutor] al celor pe care le împliniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Allah a Auzit vorbele acelora [dintre evrei] care au spus: „Allah este sărac, iar noi suntem bogați.” Vom scrie ceea ce au spus ei, precum și omorârea de către ei a Profeților pe nedrept și Noi le vom spune: „Gustați pedeapsa Focului Arzător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'Aceasta este pentru ceea ce au săvârșit mâinile voastre mai înainte, pentru că Allah nu este nedrept cu robii [Săi].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, '[Ei sunt] cei care au spus: „Cu adevărat, Allah ne-a poruncit să nu credem în niciun Mesager până când el nu va aduce o jertfă pe care s-o mistuie focul [din Ceruri].” Spune-le: „V-au venit înainte de mine Mesageri cu dovezi clare și cu ceea ce ați zis voi. De ce i-ați omorât, dacă sunteți sinceri?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'Atunci dacă ei te vor socoti mincinos [o, Mohammed] - și alți Trimiși dinaintea ta au fost socotiți mincinoși, [deși] au venit cu dovezi clare, cu Psalmi și cu Scriptura cea Luminoasă[31].', '[31] Cea neschimbată, Tora și Evanghelia originală, care au fost revelate de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Fiecare suflet va gusta moartea, desigur voi veți primi [întreaga] voastră răsplată în Ziua Învierii! Cel care va fi îndepărtat de Foc și adus în Rai va fi izbânditor. Viața aceasta nu este decât plăcere amăgitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'Cu siguranță, veți fi încercați [în privința] bunurilor voastre și [în privința] sufletelor voastre. Și cu siguranță, veți auzi de la cei cărora le-a fost dăruită Scriptura înaintea voastră și de la cei care îi fac asociați lui Allah multe jigniri. Dar dacă sunteți răbdători și aveți frică de Allah - cu siguranță, acesta este unul dintre lucrurile cele mai de preț', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'Și [spune, o, Mohammed] când Allah a făcut un legământ cu aceia cărora le-a fost dăruită Scriptura, [spunând]: „Trebuie să o faceți cunoscută oamenilor și să nu o ascundeți!”. Dar ei au aruncat-o în spatele lor și au vândut-o pe un preț de nimic. Ce rău negoț au făcut!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Nu te gândi niciodată că cei care se bucură de ceea ce au făcut și cei cărora le place să fie lăudați pentru ceea ce nu au făcut – nu te gândi niciodată că ei vor fi salvați de pedeapsă, căci ei vor avea o pedeapsă chinuitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'A lui Allah este Împărăția Cerurilor și a Pământului și El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'Cu adevărat, în crearea Cerurilor și a Pământului și în schimbarea nopții și a zilei sunt semne pentru cei dăruiți cu minte -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, 'Care Îl pomenesc pe Allah, stând [în picioare], șezând [jos] sau pe o parte și cugetă la facerea Cerurilor și a Pământului, [spunând]: „Doamne, Tu n-ai făcut acestea în zadar! Slavă Ție! Apără-ne pe noi de pedeapsa Focului!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, 'Doamne! Cu adevărat, pe acela pe care îl faci să intre în Foc - Tu îl acoperi de rușine, iar pentru cei nelegiuiți nu este cine să-i ajute!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'Doamne! Cu adevărat, noi am auzit un vestitor [profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)] chemând la credință [spunând]: „Credeți în Domnul vostru!” Și noi am crezut. Doamne, iartă-ne păcatele noastre, șterge faptele noastre rele și ia-ne sufletele împreună cu cei evlavioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'Doamne! Dă-ne nouă ceea ce ne-ai făgăduit prin Mesagerii Tăi și nu ne acoperi pe noi de rușine în Ziua Învierii, căci Tu nu-ți încalci Făgăduința!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'Iar Domnul lor le-a răspuns: „Eu nu las să se piardă nicio faptă împlinită de vreunul dintre voi, bărbat sau femeie, deopotrivă unul cu altul! Iar pe cei care au emigrat, care au fost alungați din casele lor, care au fost răniți pe calea Mea, care au luptat și au fost omorâți – cu siguranță le voi șterge faptele rele și cu siguranță îi voi primi în Grădini pe sub care curg râuri, drept răsplată din partea lui Allah. La Allah se află cea mai bună răsplată!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Să nu te înșele peregrinatul prin țări al celor care nu sunt credincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, '[Este doar o] puțină plăcere [în lumea aceasta] și apoi refugiul lor este Focul! Și ce pat rău este acesta!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Cât despre aceia care au frică de Domnul lor, ei vor avea Grădini pe sub care curg râuri, în care vor sălășlui veșnic, drept loc de primire de la Allah. Și, ceea ce este la Allah, este mai bun pentru cei pioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Și cu adevărat, printre oamenii Scripturii sunt unii care cred în Allah și în ceea ce vi s-a trimis vouă și în ceea ce li s-a trimis lor, smeriți înaintea lui Allah. Ei nu vând Versetele lui Allah pe un preț de nimic. Aceia vor avea răsplată de la Domnul lor. Cu adevărat, Allah este grabnic la socoteală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'O, voi cei care credeți! Fiți răbdători[32] și îndemnați la răbdare, fiți statornici și fiți cu frică de Allah, pentru ca să aveți parte de izbândă!', '[32] În religia voastră și în fața dușmanilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'O, voi oameni! Fiți cu frică de Domnul vostru care v-a făcut dintr-un singur suflet și a făcut din acesta perechea lui și a răspândit din cele două [ființe] mulți bărbați și femei. Și fiți cu frică de Allah, în Numele Căruia cereți unul pentru celălalt și [fiți cu frică de ruperea] legăturilor de rudenie. Cu adevărat Allah este Raqib [Veghetor] peste voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'Și dați-le orfanilor bunurile lor și nu-l schimbați pe cel rău [din lucrurile voastre] cu cel bun [de-al lor]. Și nu le luați bunurile lor ca fiind ale voastre. Cu adevărat, aceasta este un păcat mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Iar dacă vă este teamă că veți fi nedrepți cu fetele orfane, luați de soții pe acelea care vă plac dintre femei, două, trei sau patru. Dar dacă vă temeți că nu veți fi drepți, atunci [căsătoriți-vă doar] cu una sau [luați] dintre cele care se află sub stăpânirea mâinii voastre drepte [sclavele voastre]. Aceasta este mai bine pentru voi pentru a nu fi nedrepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'Și dați femeilor [la căsătorie] darurile[1] lor [nupțiale] de bunăvoie. Dar dacă ele se lipsesc de ceva fără a fi silite, atunci cheltuiți-le după cum doriți, cu plăcere[2].', '[1] Darul nupțial obligatoriu, mahr
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'Și nu încredințați celor nepricepuți averile voastre, pe care Allah le-a făcut pentru voi mijloc de trai, ci hrăniți-i din ele, îmbrăcați-i și spuneți-le lor vorbe cuviincioase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'Și încercați-i pe orfani [în abilitățile lor] până când ajung la vârsta căsătoriei. Atunci, dacă considerați că au judecată sănătoasă, încredințați-le bunurile lor! Nu le cheltuiți cu nechibzuință și grabă, înainte ca ei să crească! Iar cel care este tutore și este înstărit, să fie cumpătat, iar cel care este sărac să cheltuiască după cuviință [ceea ce este acceptat]. Iar atunci când le încredințați bunurile lor, să fie de față martori, iar Allah este de ajuns pentru a ține socoteala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'Bărbaților le revine o parte din ceea ce au lăsat în urmă părinții și rudele apropiate, iar femeilor le revine o parte din ceea ce au lăsat în urmă părinții și rudele apropiate, puțin sau mult - [le revine] o parte anumită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'Iar dacă [alte] rude sau orfani sunt prezenți la împărțirea bunurilor, atunci, oferiți-le lor ceva [din moștenire] și spuneți-le vorbe cuviincioase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'Iar acei [executori și tutori] să se teamă [de nedreptate] ca și cum ei [înșiși] ar fi lăsat în urma lor descendenți slabi[3] și sunt îngrijorați pentru ei. Să fie cu frică de Allah și să spună vorbe bine chibzuite!', '[3] Copii mici');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Cu adevărat, cei care folosesc bunurile orfanilor în mod nedrept vor mânca în pântecele lor foc. Și ei vor arde în Iad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, 'Allah vă poruncește în privința [moștenirii] copiilor voștri: un fiu are [o parte egală] cu partea a două fiice. Dacă sunt [doar] fete, mai mult decât două, ele primesc două treimi din moștenire. Dacă este una singură, ea primește jumătate. Cât despre părinții lui, fiecare dintre ei primește a șasea parte din moștenire, dacă el are copii. Dacă însă nu are copii și îl moștenesc [doar] părinții lui, atunci mama sa are dreptul la o treime. Iar dacă el are frați, atunci mama lui primești a șasea parte, după testament și plata datoriilor. Voi nu știți dacă părinții voștri sau fiii voștri vă sunt mai folositori. [Aceasta este] o poruncă de la Allah, căci Allah este ‘Alim [Atoateștiutor] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'Vouă vă revine jumătate din ceea ce lasă după ele soțiile voastre, dacă ele nu au niciun copil. Dar dacă ele au vreun copil, vă revine un sfert din ceea ce lasă în urma lor, după testament sau plata datoriilor. Iar lor [soțiilor] le revine un sfert din ceea ce lăsați voi [moștenire], dacă nu aveți niciun copil. Dar dacă aveți vreun copil, lor le revine a opta parte din ceea ce lăsați, după testament sau plata datoriilor. Dacă un bărbat sau o femeie moare fără a avea niciun moștenitor direct, dar are un frate sau o soră, fiecăruia dintre cei doi le revine a șasea parte. Dacă ei însă sunt mai mulți de doi, atunci ei toți sunt părtași la o treime[4], după testament sau plata datoriilor, fără prejudicierea [vreunuia][5]. [Aceasta este] Porunca lui Allah, iar Allah este ‘Alim, [Atoateștiutor] și Halim [Blând].', '[4] Împărțite egal între bărbați și femei
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'Acestea sunt Legile lui Allah, iar cel care Îl ascultă pe Allah și pe Trimisul Său, [Allah] îl va face să intre în Grădini pe sub care curg râuri, pentru a rămâne veșnic în ele, iar aceasta este mare izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'Însă pe acela care nu este supus lui Allah și Trimisului Său și încalcă Legile Lui, [Allah] îl va face să intre în Foc, rămânând veșnic în el și el va avea parte de chinuri înjositoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'Împotriva acelora dintre femei care comit acte imorale [relații sexuale nepermise] - aduceți patru [martori] dintre voi. Iar dacă mărturisesc[6], atunci țineți-le închise în case până când mor[7] sau până când Allah va porunci pentru ele altă cale[8].', '[6] Martorii trebuie să jure că au văzut fapta în sine petrecându-se
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'Pe cei doi[9] dintre voi [bărbați sau femei] care încalcă legea [au relații intime nepermise] pedepsiți-i pe amândoi. Dar dacă ei se căiesc și se îndreaptă, atunci lăsați-i în pace. Cu adevărat Allah este Primitor al căinței și Îndurător.', '[9] Învățații nu au căzut de acord dacă „cei doi” se referă la două persoane de același sex (homosexuali) sau de sex opus. În orice caz, legile viitoare din sunnah au înlocuit-o pe aceasta.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Allah primește doar căința celor care săvârșesc rău din neștiință, dar se căiesc de îndată. Pe aceia Allah îi iartă, căci Allah este ‘Alim [Atoateștiutor] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Însă căința nu este [acceptată] pentru cei care săvârșesc fapte rele [continuu] până în clipa în care moartea vine la unul dintre ei și atunci el spune: „Cu adevărat, m-am căit acum!” Și nici pentru cei care mor necredincioși. Pentru aceia Noi am pregătit o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'O, voi cei care credeți! Nu vă este îngăduit să moșteniți femei în pofida voinței lor[10]. Și nici să le opriți să se căsătorească [din nou] cu alții, ca să le luați o parte din ce le-ați dat [ca zestre], decât dacă ele au săvârșit un păcat evident [de ex: adulter], ci purtați-vă cu ele după cuviință! Iar dacă nu vă sunt pe plac, se poate să nu vă fie pe plac un lucru pe care Allah l-a pregătit [să vă aducă] un mare bine.', '[10] Moștenitorii celui decedat nu au drept de căsătorie asupra văduvei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'Dacă vreți să schimbați o soție cu altă soție [prin divorț] și i-ați dat uneia dintre ele multe bunuri [drept cadou], nu luați nimic din ele înapoi. Ați lua înapoi în nedreptate și cu păcat învederat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'Cum să-l luați înapoi după ce v-ați bucurat împreună și ele au primit de la voi legământ solemn?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'Nu vă însurați cu femeile cu care au fost însurați părinții voștri, doar dacă s-a petrecut înainte[11]. Cu adevărat aceasta este o josnicie și un păcat cumplit! Și ce cale rea este această [căsătorie]!', '[11] Înainte de Islam. După ce această lege a fost revelată de Allah, bărbații au fost nevoiți să elibereze acele femei nepermise pentru ei (e.g. mama vitregă, una dintre două surori sau alte soții peste limita de patru). Aceeași obligație se aplică și celor care au acceptat Islamul.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Vă sunt interzise [pentru căsătorie] mamele voastre, fiicele voastre, surorile voastre, mătușile voastre după tată, mătușile voastre după mamă, fiicele fratelui, fiicele surorii, doicile voastre care v-au alăptat, surorile voastre după doică, mamele nevestelor voastre, fiicele vitrege aflate sub tutela voastră, [născute] de la femeile voastre, la care ați intrat[12]. Dar dacă nu ați intrat încă la ele, atunci nu este păcat pentru voi. De asemenea [vă sunt interzise] nevestele fiilor voștri din mădularele voastre, precum și două surori în același timp, doar dacă s-a petrecut mai înainte. Cu adevărat, Allah este Ghafur [Iertător] și Rahim [Îndurător].', '[12] S-a consumat căsătoria');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'Și [asemenea, vă sunt interzise] toate femeile căsătorite, în afară de acelea care se află sub stăpânirea dreptei voastre[13]. Aceasta este Porunca lui Allah pentru voi! Și vă este îngăduit în afară de acestea, să căutați [soții], după averile voastre, dorindu-vă castitatea și nu relațiile sexuale nepermise. Acelora cu care vă bucurați, [căsătorindu-vă cu ele], dați-le zestrea lor, ca o datorie. Și nu este niciun păcat pentru voi, dacă ați încheiat un legământ între voi, după stabilirea zestrei, căci Allah este ‘Alim [Atoateștiutor] și Hakim [Înțelept].', '[13] Sclave sau captive de război care aveau soți politeiști');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'Acela dintre voi care nu are mijloace necesare să se însoare cu femei libere și credincioase poate [să se căsătorească cu una] din fetele voastre credincioase aflate sub dreapta voastră. Allah Știe prea bine credința voastră. Voi [credincioșii] sunteți uni din alții [dintre ai voștri, de aceeași religie]. Luați-le de neveste cu voia stăpânilor lor și dați-le zestrea lor, după cuviință. Ele [ar trebui] să fie caste, să nu aibă relații sexuale nepermise sau ibovnici. Iar dacă s-au măritat și apoi fac adulter, atunci ele să primească jumătate din pedeapsa cuvenită femeilor libere [necăsătorite]. Aceasta este îngăduită pentru acela care se teme de păcat. Dar să fiți răbdători e și mai bine pentru voi, căci Allah este Ghafur [Iertător] și Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Allah Voiește să vă facă vouă clare [cele permise de cele nepermise] și să vă arate practicile [bune] ale celor de dinaintea voastră [cei bine călăuziți] și să vă accepte căința. Allah este ‘Alim [Atoateștiutor] și Hakim [Înțelept]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Și Allah Voiește să vă accepte căința, dar cei care își urmează poftele lor, doresc ca voi să vă abateți cât mai mult [de la El].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Allah Voiește să vă ușureze [dificultățile] căci omul a fost creat slab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'O, voi cei care credeți! Nu consumați bunurile altora în mod nedrept, doar dacă este un negoț [legal], despre care sunteți de acord! Și nu vă ucideți [unul pe celălalt]! Cu adevărat, Allah este cu voi Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Iar pe cel care săvârșește aceasta în mod nedrept și ostil - Noi îl vom face să ardă în Foc. Și pentru Allah aceasta este un lucru ușor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Dacă vă veți feri de păcatele mari, care vă sunt interzise, vă vom ierta pentru păcatele mici și vă vom lăsa să intrați într-un loc nobil [în Paradis].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'Nu râvniți la ceea ce Allah a dăruit [cu Harul Său] unora dintre voi mai mult decât altora. Bărbații vor avea parte de ceea ce au agonisit și femeile vor avea parte de ceea ce au agonisit. Deci rugați-vă lui Allah pentru Harul Său. Cu adevărat, Allah le Știe pe toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'Tuturor le-am dat moștenitori pentru ceea ce lasă părinții și rudele apropiate. Și acelora cu care ați împreunat mâinile voastre drepte [în frăție], dați-le partea lor [din moștenire], căci Allah este la toate Martor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Bărbații sunt protectorii [și susținătorii] femeilor,[14] datorită [dreptului] pe care Allah l-a dăruit unora față de ceilalți și datorită cheltuielilor [pentru întreținerea familiei] pe care le fac din bunurile lor. Iar femeile evlavioase sunt ascultătoare și păzitoare [ale celor care trebuie păzite] în absența [soților lor], pe care și Allah le Păzește[15]. Pe acele [soții] de a căror neascultare vă temeți, sfătuiți-le [prima dată], părăsiți-le în paturi [dacă continuă] și loviți-le [ușor, în final, dacă ele tot continuă][16]! Dar dacă ele vă ascultă [din nou], atunci nu mai căutați pricină împotriva lor. Allah este ''Aliyy [Cel mai Înalt] și Kabir [Măreț].', '[14] Se aplică în principal relației dintre soț și soție
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'Dacă vă este frică de o neînțelegere între ei doi [cei doi soți], atunci trimiteți un arbitru din neamul lui și un arbitru din neamul ei. Dacă voiesc ei [arbitrii] împăcarea, Allah va readuce înțelegerea între ei [cei doi soți]. Cu adevărat, Allah este ''Alim [Atoateștiutor], [Bineștiutor] Khabir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'Adorați-L pe Allah și nu-I asociați Lui nimic! Purtați-vă bine cu părinții, cu rudele, cu orfanii, cu sărmanii, cu vecinul apropiat[17] și cu vecinul îndepărtat, cu companionul de alături[18], cu călătorul de pe drum și cu cei stăpâniți de mâinile voastre drepte, căci Allah nu-l iubește pe cel trufaș și lăudăros!', '[17] Apropiat prin vecinătate și prin înrudire
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'Celor care sunt zgârciți și-i îndeamnă pe oameni la zgârcenie și ascund ceea ce le-a dăruit Allah din Harul Său - le-am pregătit necredincioșilor pedeapsă umilitoare -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'Și celor care își cheltuiesc banii [fac milostenie] pentru a fi văzuți de către oameni și nu cred în Allah și nici în Ziua de Apoi. Iar acela căruia Șeitan îi este tovarăș – rău tovarăș are el!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'Și ce vină li s-ar putea aduce, dacă ar crede în Allah și în Ziua de Apoi și ar face milostenii din ceea ce le-a dăruit Allah? Allah este ‘Alim [Atoateștiutor] cu privire la ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Cu adevărat, Allah nu este nedrept [față de nimeni], nici cât greutatea unui atom; dacă este o faptă bună, El o înmulțește și dă din partea Sa răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'Și cum va fi când vom aduce din fiecare popor un martor și te vom aduce pe tine, [o, Mohammed], martor împotriva acestor [popoare][19]?', '[19] Împotriva necredincioșilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'În Ziua aceea, cei care nu au crezut și nu l-au ascultat pe Trimis vor dori să fie acoperiți de pământ. Și ei nu vor putea să ascundă de Allah niciun cuvânt!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'O, voi cei care credeți! Nu vă apropiați de Rugăciune [As-Salat] atunci când sunteți beți[20], ca să știți ce spuneți [lui Allah], nici atunci când sunteți în stare de janabah[21] - cu excepția celor care trec [printr-un loc de rugăciune] - până ce nu vă veți curăța [întreg corpul]! Iar dacă sunteți bolnavi sau în călătorie, ori dacă unul dintre voi se întoarce din locul unde și-a făcut nevoile, sau ați atins femeile[22] și nu găsiți apă, atunci căutați pământ curat și treceți-vă palmele peste fețe și peste mâini. Cu adevărat, Allah este ‘Afuuu [Îngăduitor] și Ghafur [Iertător].', '[20] Consumarea băuturilor alcoolice și a narcoticelor a fost interzisă mai târziu în mod complet. A se vedea 5:90-91.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Nu i-ai văzut [o, Mohammed] pe aceia cărora li s-a dat o parte din Scriptură, cum cumpără rătăcirea și cum doresc ca și voi să rătăciți de la drumul [drept]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Însă Allah îi Știe cel mai bine pe dușmanii voștri și Allah este de ajuns ca Ocrotitor și Allah este de ajuns ca Ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Printre evrei, sunt unii care schimbă sensurile cuvintelor și spun: „Auzim și nu ascultăm!" și „Auzi, dar nu asculta!” Și „Ra''i-na!”[23], stâlcindu-și limbile lor și vătămând religia. Și dacă ar fi spus [în schimb]: „Auzim și ne supunem!” și „Dă-ne un răgaz [ca să înțelegem]!”, ar fi fost mai bine pentru ei și mai drept. Dar Allah i-a blestemat din cauza necredinței lor și nu cred decât puțini [dintre ei][24].', '[23] A se vedea nota 2:104
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'O, voi cei cărora vi s-a dăruit Scriptura, credeți în ceea ce am pogorât Noi [lui Mohammed], întărind ceea ce voi aveați deja, înainte ca Noi să mutilăm chipuri și să le întoarcem pe dosurile lor sau să-i blestemăm așa cum i-am blestemat și pe cei care nu au respectat Sabatul[25]. Iar Porunca lui Allah este întotdeauna împlinită!', '[25] A se vedea 7:163-166');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Cu adevărat, Allah nu iartă să I se facă asociați, dar iartă ce este mai puțin de atât oricui voiește. Iar cel care îi face asociați lui Allah, a făcut un mare păcat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Nu i-ai văzut pe cei care se laudă că sunt puri? Însă numai Allah este Cel care purifică pe cine Voiește El și ei nu vor fi nedreptățiți [la răsplată] nici cât un firicel [din scobitura sâmburelui de curmală].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Privește cum născocesc ei minciuni despre Allah! Și acesta este îndeajuns un păcat evident.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Nu i-ai văzut pe cei cărora le-a fost dată o parte din Scriptură? Ei cred în Jibt [superstiții] și în Taghut [obiecte false de adorare] și spun despre necredincioși: „Aceștia sunt mai bine călăuziți decât credincioșii pe drumul [cel drept]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'Aceștia sunt cei pe care Allah i-a blestemat, iar celui pe care Allah l-a blestemat nu-i vei afla niciodată ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Sau au ei o parte din stăpânire? Dacă [ar fi așa], ei nu le-ar da oamenilor nici măcar cât un firicel de pe sâmburele de curmală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'Sau îi invidiază ei pe oameni pentru ceea ce El le-a dat cu Harul Său? Dar Noi i-am dat deja poporului lui Avraam Scriptura și Înțelepciunea[26] și le-am dat lor o mare împărăție![27]', '[26] Învățăturile profetice
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Și printre ei au fost unii care au crezut în el[28] și alții care s-au lepădat de el. Și focul Iadului le va fi de ajuns.', '[28] În ceea ce le-a fost dat lor. Este interpretat de asemenea „în el, adică profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)”.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Cei ce nu cred în Versetele Noastre - îi vom lăsa să ardă în Foc. De fiecare dată când pieile lor se vor coace, le vom schimba cu alte piei, ca să guste chinul! Allah este ‘Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'Însă pe cei care cred și săvârșesc fapte bune îi vom primi în grădini pe sub care curg râuri. În ele vor fi veșnic sălășluitori și vor avea în ele soațe purificate. Și îi vom primi pe ei la umbră deasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'Cu adevărat, Allah vă poruncește să dați înapoi stăpânilor lor lucrurile încredințate și atunci când judecați între oameni, să judecați cu dreptate! Cât de minunat este acest lucru la care vă învață Allah! Allah este Sami'' [Cel care Aude Totul] și Basir [Cel care Vede Totul]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'O, voi cei care credeți! Fiți cu supunere față de Allah și ascultați-l pe Trimisul Său și pe cei cu autoritate dintre voi. Dacă aveți neînțelegeri într-o chestiune, aduceți-o [pentru judecare] la Allah și la Trimis[29], dacă voi credeți în Allah și în Ziua de Apoi! Aceasta este cea mai bună cale și cu cele mai bune urmări.', '[29] La Coran și la Sunnah profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Nu i-ai văzut pe cei care pretind că ei cred în ceea ce ți-a fost trimis ție [o, Mohammed] și în ceea ce a fost trimis mai înainte de tine? Ei voiesc să-l ia ca judecător pe Taghut, deși li s-a poruncit să nu creadă în el. Dar Șeitan voiește să-i împingă pe ei în lungă rătăcire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'Iar atunci când li se spune: „Veniți spre ceea ce a trimis Allah și spre Trimis!”, îi vei vedea pe ipocriți cum se întorc, îndepărtându-se de tine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'Însă cum va fi atunci când îi va lovi o nenorocire pentru ceea ce au făcut mai înainte mâinile lor și atunci ei vor veni spre tine jurând pe Allah: „Noi nu am vrut decât bine și împăcare!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'Aceștia sunt cei despre care Allah Știe ce se află în inimile lor, îndepărtează-te așadar de ei[30], dar povățuiește-i și spune-le vorbe convingătoare.', '[30] Nu fi violent cu ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'Și Noi nu am trimis niciun Trimis, decât pentru a i se da ascultare, cu Voia lui Allah. Și dacă, după ce au fost nedrepți cu propriile lor suflete, vor veni ei la tine [o, Mohammed] și se vor ruga pentru Iertarea lui Allah, iar Trimisul s-a rugat pentru iertarea lor, îl vor afla pe Allah Tauuab [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'Însă, nu! [Jur] pe Domnul tău! Nu vor crede ei [cu adevărat] până ce nu te vor lua pe tine [o, Mohammed] ca judecător pentru disputele lor și apoi nu vor găsi în sufletele lor niciun disconfort față de ceea ce tu ai hotărât și până ce nu se vor supune cu desăvârșită supunere [hotărârii tale].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'Iar dacă Noi le-am fi poruncit: „Omorâți-vă pe voi înșivă! [cei nevinovați să-i omoare pe cei vinovați] ” sau „Plecați din casele voastre!”, nu ar fi făcut-o decât puțini dintre ei. Dar dacă ei ar fi făcut ceea ce au fost instruiți, ar fi fost mai bine pentru ei și ar fi fost mai statornică [credința lor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'Și atunci Noi le-am fi dat din partea Noastră răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'Și i-am fi călăuzit Noi pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Cei care se supun lui Allah și Trimisului vor fi împreună cu cei pe care Allah i-a binecuvântat cu Harul Său, dintre Profeți, adevărații evlavioși, martiri și cei pioși. Și ce buni companioni sunt aceștia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'Acesta este Harul lui Allah, iar Allah este de ajuns ca ‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'O, voi cei care credeți! Fiți prudenți și porniți [la luptă] în grupuri sau porniți [la luptă] cu toții deodată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'Și cu adevărat, printre voi este și acela care rămâne în urmă [atunci când se pornește la luptă] și dacă asupra voastră se abate o nenorocire, el spune: „Allah s-a îndurat de mine cu Harul Lui, căci nu am fost împreună cu ei!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'Dar dacă asupra voastră coboară Harul lui Allah, atunci, cu siguranță el va spune, ca și când între voi și el nu ar fi fost nicio prietenie: „Ce păcat că nu am fost împreună cu ei, căci aș fi câștigat o răsplată mare[31]!”.', '[31] Prada de război. Deși s-au prefăcut că sunt prietenii credincioșilor în sprijinirea Religiei lui Allah, ipocriții nu au dorit să lupte decât pentru câștiguri materiale.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, 'Să lupte pe calea lui Allah cei care dau viața lumească de acum pentru Viața de Apoi. Iar celui care luptă pe calea lui Allah, de va fi ucis sau de va învinge, Noi îi vom da mare răsplată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Și ce este cu voi de nu luptați pe calea lui Allah și pentru bărbații, femeile și copiii slabi care spun: „Doamne, scoate-ne pe noi din cetatea aceasta cu un popor asupritor și dă-ne nouă din partea Ta un ocrotitor și dă-ne nouă din partea Ta un ajutor”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'Cei care cred luptă pe calea lui Allah, iar cei care nu cred luptă pe calea lui Taghut[32]. Așadar, luptați împotriva aliaților lui Șeitan. Cu adevărat, vicleșugul lui Șeitan a fost dintotdeauna slab!', '[32] A se vedea nota 4:60');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Nu i-ai văzut pe cei cărora li s-a spus: „Rețineți-vă mâinile voastre [de la luptă][33], împliniți Rugăciunea [As-Salat] și achitați Dania [Az-Zakat]”? Dar, când li s-a poruncit lupta, dintr-o dată, o parte dintre ei s-au temut de oameni precum s-ar teme de Allah sau chiar mai mult și au spus: „Doamne, de ce ne-ai poruncit nouă lupta? De ce nu ne-ai mai lăsat un timp?” Spune: „Plăcerea acestei lumi este mică, iar Lumea de Apoi este mai bună pentru cei care se tem de Allah și [acolo] nu veți fi nedreptățiți nici cât un firicel [din sâmburele unei curmale]!”', '[33] Înainte să vină permisiunea de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, 'Oriunde ați fi, moartea vă va ajunge, chiar de-ați fi în turnuri semețe. Dar dacă au parte de bine, ei spun: „Aceasta este de la Allah!”, iar dacă îi lovește un rău, ei spun: „Aceasta este de la tine, [Mohammed]!” Spune: „Toate sunt de la Allah!". Ce se întâmplă cu acei oameni de abia înțeleg vreo vorbă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Binele de care ai parte îți vine de la Allah, iar răul care te lovește vine de la tine însuți[34] și Noi te-am trimis [o, Mohammed] drept Mesager pentru oameni. Iar Allah este suficient ca Martor!', '[34] Drept rezultat al greșelilor sau păcatelor tale, o, omule!');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Cel care i se supune Trimisului I se supune lui Allah. Dar cei care întorc spatele - Noi nu te-am trimis să fii peste ei păzitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, 'Ei spun: „ [Jurăm] supunere!”. Dar de îndată ce pleacă de la tine, o parte dintre ei își petrec noaptea gândindu-se să facă altceva decât ceea ce ai spus tu. Dar Allah scrie ceea ce ei născocesc noaptea. Lasă-i în pace și ai încredere în Allah. Și Allah este suficient ca Protector!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'Oare nu cugetă ei la Coran[35]? Dacă ar fi el de la altcineva decât de la Allah, ar găsi în el multe nepotriviri!', '[35] La sensurile și obiectivele lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'Când vine la ei ceva [o știre vestind] despre liniște sau spaimă, ei o răspândesc de îndată. Dar dacă ei ar fi împărtășit-o Trimisului sau conducătorilor lor, atunci cei care caută să fie lămuriți, ar fi aflat [adevărul]. Iar dacă nu ar fi fost Harul lui Allah și Îndurarea Lui asupra voastră, l-ați fi urmat pe Șeitan, cu excepția a puțini [dintre voi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Luptă-te pe calea lui Allah [o, Mohammed] - tu nu ești răspunzător decât pentru tine! - Și îndeamnă-i pe dreptcredincioși [să ți se alăture] poate că Allah va restrânge puterea [militară] a celor care nu cred. Iar Allah este mai Puternic în forță și mai aspru în pedeapsă[36].', '[36] Allah poate să îi învingă astfel încât să-i descurajeze pe alții în a proceda la fel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Cel care va mijloci pentru o cauză bună va avea și el o parte [de răsplată], iar cel care mijlocește pentru o cauză rea va avea și el o parte [de răspundere]. Iar Allah este Al-Muqit [cu Putere] peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Iar atunci când sunteți întâmpinați cu un salut, răspundeți cu unul și mai frumos decât el sau [cel puțin] răspundeți. Cu adevărat, Allah este Hasib [Socotitor] al tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Allah! Nu există altă divinitate în afară de El! El vă va aduna cu siguranță în Ziua Învierii, asupra căreia nu este nicio îndoială. Și cine este mai adevărat decât Allah în ceea ce El Spune?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'De ce sunteți despărțiți în două grupuri în privința ipocriților[37] în timp ce Allah i-a întors [la necredință] pentru ceea ce au dobândit[38]? Vreți să îi călăuziți pe cei pe care Allah i-a împins la rătăcire? Iar pe cel pe care Allah l-a dus la rătăcire nu îi poți găsi o cale [către călăuzire]!', '[37] Despărțiți din două puncte de vedere – dacă ar trebui sau nu să se lupte împotriva lor sau să fie omorâți
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'Ei ar vrea ca voi să nu credeți, așa cum nici ei nu cred, astfel încât să fiți la fel. Așadar nu vă luați dintre ei aliați, până ce ei nu vor emigra pentru Allah! Dar dacă ei întorc spatele [refuză], prindeți-i și omorâți-i, oriunde îi veți găsi și nu vă luați dintre ei niciun aliat sau ajutor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Cu excepția celor care caută refugiu la un popor cu care voi aveți un legământ sau care vin la voi cu piepturile prea strânse pentru a mai lupta împotriva voastră sau împotriva poporului lor. Iar dacă ar fi Voit Allah, le-ar fi dat putere asupra voastră, iar ei s-ar fi luptat cu voi. Dar dacă se depărtează de voi și nu luptă împotriva voastră și vă oferă pace, atunci, la Allah, nu mai aveți motiv [permisiunea] de a lupta împotriva lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'Îi veți găsi pe alții care ar dori să obțină siguranța din partea voastră și să obțină siguranța și din partea poporului lor. De fiecare dată când vor fi îndemnați la [ispita] necredinței, ei se vor lăsa împinși spre ea. Așadar, dacă nu vor sta departe de voi și nu vă vor arăta pace și nu vor opri mâinile lor [de la lupta împotriva voastră], atunci prindeți-i și omorâți-i, oriunde i-ați afla! Asupra acestora Noi vă dăm dovadă [și o permisiune] sigură.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'Nu se cade ca un dreptcredincios să omoare un alt dreptcredincios, decât [dacă aceasta se întâmplă] din greșeală. Iar cel care omoară un dreptcredincios din greșeală, [trebuie] să elibereze un sclav credincios și să dea o plată de răscumpărare[39] [diyah] familiei [celui ucis], în afara [situației în care aceasta îl iartă], în semn de milostenie. Dacă [cel ucis] este dintr-un popor dușman vouă și este dreptcredincios, atunci trebuie [doar] să elibereze un sclav credincios. Dacă este însă dintr-un popor cu care aveți legământ, atunci trebuie să dea o plată de răscumpărare familiei lui și să elibereze un sclav credincios. Cel care nu găsește [robul sau nu își permite să cumpere unul pentru eliberare] – atunci să postească [în loc] două luni, una după alta[40], căutând ca Allah să îi accepte căința[41]. Allah este ''Alim [Atoateștiutor] și Hakim [Înțelept].', '[39] Prețul sângelui, care constă într-o sută de cămile de vârste diferite
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'Dar cel care omoară intenționat un dreptcredincios, răsplata îi va fi Iadul, în care va rămâne veșnic, iar Allah se va mânia pe el, îl va blestema și-i va pregăti lui chin mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'O, voi cei care credeți! Atunci când porniți [la luptă] pe calea lui Allah, cercetați și nu îi spuneți celui care vă dă binețe [As-salamu ’alaikum]: „Tu nu ești credincios!”[42], râvnind la bunurile acestei vieți lumești, căci Allah are prăzi multe. Așa ați fost voi mai înainte, dar Allah v-a binecuvântat cu Harul Lui, deci cercetați. Cu adevărat Allah este Bineștiutor a ceea ce faceți voi!', '[42] Nu presupuneți că el se preface a fi musulman doar pentru a se salva, pentru că se poate ca el să fie sincer în credință');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Nu sunt egali dreptcredincioșii care rămân în casele lor – cu excepția celor bolnavi - cu mujahidin [cei care luptă pe calea lui Allah], cu bunurile și cu sufletele lor. Allah i-a înălțat pe cei care luptă cu bunurile și cu sufletele lor peste cei care rămân în casele lor, în trepte. Tuturor [amândurora] Allah le-a făgăduit cea mai bună răsplată, dar Allah i-a favorizat pe cei care luptă peste cei care rămân în casele lor cu o răsplată mai mare -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'Trepte [ale unei poziții înalte] din partea Sa, cu Iertare și Îndurare, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Cu adevărat, când Îngerii iau sufletele celor care au fost nedrepți cu ei înșiși[43], le spun lor: „În ce condiție v-ați aflat?” Ei vor răspunde: „Noi am fost asupriți.” Atunci [Îngerii] vor spune: „Nu a fost pământul lui Allah destul de larg pentru ca voi să plecați în lume?” Adăpostul acestora este Iadul - și ce soartă rea.', '[43] Prin a prefera să stea printre necredincioși, într-un mediu în care un musulman nu își poate practica religia în mod liber, deși are mijloacele pentru a emigra');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Cu excepția celor asupriți dintre bărbați, femei și copii, care nu sunt în stare să se descurce și nu găsesc nicio cale[44],', '[44] Sunt împiedicați de circumstanțe dincolo de controlul lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Pe aceștia poate că Allah o să-i ierte, căci Allah este ‘Afuuu [Îndurător], Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Și cine emigrează pentru cauza lui Allah, va găsi pe pământ multe locuri [de adăpost] și bogăție. Și cel care își lasă casa[45] ca să purceadă către Allah și Mesagerul Său[46] și apoi îl va ajunge moartea, răsplata lui se află la Allah, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '[45] Din Mecca
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Și când călătoriți pe pământ, nu va fi niciun păcat pentru voi dacă veți scurta Rugăciunea[47] [As-Salat], [mai ales] dacă vă temeți că cei care nu cred vă vor face rău [sau vă vor ataca]. Cu adevărat, necredincioșii vă sunt dușmani învederați.', '[47] Cele patru rak’ah sunt scurtate la două rak’ah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Iar atunci când tu te vei afla printre ei și îi vei conduce în Rugăciune[48] [As-Salat], o parte dintre ei să se ridice împreună cu tine [în Rugăciune] și să-și păstreze armele. Apoi, după prosternare, să treacă în spatele tău și să vină celălalt grup, care [încă] nu a făcut Rugăciunea și să facă Rugăciunea împreună cu tine, dar să fie precauți și să-și țină armele. Cei care nu cred și-ar dori ca voi să vă neglijați armele și lucrurile voastre, pentru ca să se năpustească asupra voastră dintr-o dată. Nu săvârșiți niciun păcat dacă, stânjeniți de ploaie sau de boală, vă puneți armele jos, dar fiți precauți. Cu adevărat, Allah a pregătit pentru necredincioși o pedeapsă înjositoare.', '[48] În timp de teamă pe câmpul de luptă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'Dacă ați împlinit Rugăciunea [As-Salat], pomeniți Numele lui Allah, stând în picioare, așezați sau întinși pe o parte. Dar când sunteți în pace, atunci împliniți Rugăciunea [As-Salat] [în întregime]. Cu adevărat, Rugăciunea [As-Salat] a fost stabilită pentru dreptcredincioși la timpuri hotărâte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'Nu slăbiți urmărirea dușmanilor. Dacă suferiți – și ei suferă la fel cum suferiți și voi, dar voi sperați de la Allah ceea ce ei nu speră. Și Allah este Alim[Atoateștiutor], [și] Hakim[ Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Cu adevărat, Noi ți-am trimis ție [o, Mohammed] Cartea cu Adevărul, ca să judeci între oameni așa cum ți-a arătat Allah. Și nu fi un apărător pentru cei necinstiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'Și cere-I iertare lui Allah, căci Allah este Ghafur [Iertător], [și] Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'Și nu te certa în folosul celor care sunt necinstiți cu ei înșiși. Cu adevărat, Allah nu-l iubește pe cel care este necinstit și păcătos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'Ei ascund [intențiile și faptele lor rele] de oameni, dar nu [le] pot ascunde de Allah, căci El este cu ei [știind] atunci când născocesc în timpul nopții vorbe ce Lui nu-I plac. Allah este Știutor a toate câte fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'Iată că voi le-ați luat apărarea în această lume. Dar cine le va lua apărarea înaintea lui Allah în Ziua Învierii sau cine le va fi lor ocrotitor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Și cel care săvârșește un rău sau este nedrept cu sine însuși, iar apoi se roagă lui Allah de iertare, Îl va găsi pe Allah Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Iar cel care dobândește [face] un păcat, îl dobândește numai împotriva sa, iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Dar cel care dobândește o greșeală sau un păcat și apoi îl pune pe seama unui nevinovat, s-a încărcat cu nedreptate și cu păcat vădit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Dacă nu ar fi fost Harul lui Allah asupra ta, [o, Mohammed] și Îndurarea Lui, o parte dintre ei te-ar fi împins să rătăcești [drumul]. Dar ei nu se împing la rătăcire decât pe ei înșiși și nu vor putea să-ți facă niciun rău. Iar Allah a pogorât asupra ta Cartea și Înțelepciunea și te-a învățat ceea ce nu știai. Și Harul lui Allah asupra ta a fost nemăsurat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'Nu este nimic bun în cea mai mare parte a vorbelor lor tainice, cu excepția celor care poruncesc milostenia, fapta bună și împăcarea între oameni. Iar cel care face aceasta, căutând Mulțumirea lui Allah – lui îi vom dărui mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'Și cel care i se împotrivește Trimisului, după ce i s-a arătat calea cea dreaptă și urmează un alt drum decât cel al dreptcredincioșilor, îi vom da Noi ce a luat[49] și îl vom lăsa să ardă în Iad. Și ce rea menire [este aceasta]!', '[49] Îl vom face responsabil pentru alegerea sa');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Cu adevărat, Allah nu iartă să I se facă semeni, dar iartă orice, în afară de aceasta, celui care Voiește El. Cel care Îi face lui Allah semeni, a rătăcit [pe un drum rău]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'Ei nu cheamă [și nu adoră] în locul Lui decât [zeități] femei și nu cheamă [și nu adoră de fapt] decât un Șeitan răzvrătit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Pe care Allah l-a blestemat, iar el a spus: „Cu siguranță voi lua dintre robii Tăi o anumită parte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'Și îi voi duce întru rătăcire, le voi da speranțe deșarte, le voi porunci să taie urechile animalelor[50] și le voi porunci să schimbe creația lui Allah”. Iar cel care îl ia pe Șeitan ca aliat, în locul lui Allah, va avea parte de pierdere vădită.', '[50] Vaci, cămile și oi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'El [Șeitan] le face promisiuni și le dă speranțe amăgitoare, dar Șeitan nu le promite decât amăgiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'Adăpostul acestora va fi Iadul și nu vor găsi scăpare de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'Dar pe cei care cred și împlinesc fapte bune - îi vom primi în Grădini pe sub care curg râuri, în care vor rămâne veșnic. Promisiunea lui Allah este adevăr și cine spune vorbe mai adevărate decât Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, '[Raiul] nu este [obținut] după dorințele voastre, nici după dorințele oamenilor Scripturii. Cine face un rău va fi răsplătit pentru el și nu va găsi în afara lui Allah niciun aliat și niciun ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'Iar cel care face fapte bune, bărbat sau femeie – credincios fiind – aceia vor intra în Rai și nu vor fi nedreptățiți nici cât un firicel de pe sâmburele unei curmale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'Și cine este mai bun în religie decât cel care I se supune lui Allah în timp ce împlinește fapte bune și urmează religia lui Avraam cel drept întru credință? Și Allah l-a luat pe Avraam ca prieten apropiat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'Ale lui Allah sunt cele din Ceruri și cele de pe Pământ. Și Allah este Cuprinzător al tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Ei îți cer sfatul [o, Mohammed] în privința femeilor. Spune: „Allah vă stabilește reguli în privința lor și [despre ce] vă este vestit în Carte despre orfelinele cărora nu le dați ceea ce le-a fost prescris[51] și pe care vreți [totuși] să le luați în căsătorie, precum și despre copiii asupriți, și să fiți cu dreptate față de orfani, căci Allah este Știutor al binelui pe care voi îl faceți!', '[51] În general drepturile lor și specific mahr-ul lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Dacă o femeie se teme de nepăsarea sau îndepărtarea soțului ei, atunci ei nu vor avea niciun păcat dacă ajung la o împăcare, căci împăcarea este mai bună. Iar în sufletele [oamenilor] este zgârcenie[52]. Dar, dacă faceți fapte bune și vă temeți de Allah, atunci cu adevărat, Allah este Khabir [Bineștiutor] a ceea ce faceți voi.', '[52] Căutându-și propriile interese');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Nu veți putea să vă purtați la fel cu [toate] soțiile, chiar dacă ați voi cu tot dinadinsul. Dar nu înclinați complet [către vreuna dintre ele], lăsând-o [pe cealaltă] ca atârnată[53]. Dar dacă vă îndreptați și aveți frică de Allah, atunci Allah este Ghafur [Iertător], Rahim [Îndurător].', '[53] Nici divorțată, nici primind drepturile unei căsătorii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'Iar dacă cei doi se despart [prin divorț], atunci Allah îi va înzestra pe amândoi din Bogăția Sa. Și Allah este Uasi'' [Cel cu Har Nemărginit] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'Ale lui Allah sunt toate cele din Ceruri și de pe Pământ. Noi le-am poruncit celor cărora le-a fost dată Scriptura înaintea voastră, precum și vouă să aveți frică de Allah, dar dacă voi nu credeți, atunci ale lui Allah sunt toate cele din Ceruri și de pe Pământ. Și Allah este Ghaniyy [Înstărit] [și] Hamid [Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'Ale lui Allah sunt toate cele din Ceruri și de pe Pământ. Și Allah este de ajuns ca Uakil [Ocrotitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'Dacă El ar Voi, v-ar lua, o, oameni, și ar aduce alții [în locul vostru], căci Allah are Putere să facă aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Cel care dorește răsplata acestei lumi, atunci la Allah se află răsplata și pentru această lume și pentru Lumea de Apoi. Și Allah este Sami'' [Cel care Aude Totul] și Basir [Cel care Vede Totul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'O, voi cei care credeți, fiți făptuitori neclintiți ai dreptății, martori înaintea lui Allah, chiar și împotriva voastră, a părinților și rudelor voastre, fie bogat sau sărac, căci Allah este mai îndreptățit în ceea ce îi privește pe ei[54]! Nu urmați dorința [personală], ca să nu vă abateți de la dreptate. Iar dacă vă schimbați mărturia sau refuzați [să o faceți], [să știți că] Allah este Khabir [Bineștiutor] a ceea ce faceți!', '[54] Are mai multă știință cu privire la ce este mai bun pentru ei. Așadar faceți ceea ce El v-a spus și fiți sinceri în mărturie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'O, voi cei care credeți, credeți[55] în Allah și în Trimisul Său, în Cartea pe care a pogorât-o asupra Trimisului Său și în Scriptura pe care a pogorât-o înainte. Iar cel care nu crede în Allah, în Îngerii Săi, în Cărțile Sale, în Trimișii Săi și în Ziua de Apoi, pribegește în cea mai îndepărtată rătăcire.', '[55] Reînnoiți, confirmați și aderați la credința voastră');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'Cu adevărat, pe cei care cred, apoi nu mai cred, apoi cred din nou, apoi iar nu mai cred, apoi sporesc în necredință, Allah nu-i va ierta și nu-i va călăuzi pe o cale [dreaptă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'Vestește-le ipocriților că ei vor avea parte de o pedeapsă dureroasă;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, 'Cei care îi iau pe necredincioși aliați în locul credincioșilor, oare aceștia caută onoare [și putere] la ei? Ci, cu adevărat, Onoarea se află numai la Allah, în întregime.[56]', '[56] Fiind sursa Puterii și Onoarei depline, Allah le oferă celor cărora El Voiește');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'El v-a pogorât deja în Carte [în Coran] că atunci când veți auzi că Versetele lui Allah [care sunt recitate] sunt negate [de ei] sau luate în derâdere, să nu stați împreună cu ei până nu vor începe altă discuție. [Altfel] ați fi, cu adevărat, asemenea lor[57]. Allah îi va aduna pe fățarnici și pe necredincioși în Iad, cu toții -', '[57] În această lume, prin participarea la blasfemie și în Viața de Apoi unde veți avea aceeași pedeapsă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, 'Cei care vă așteaptă [și vă urmăresc]. Atunci, dacă aveți parte de o victorie de la Allah, ei spun: „Nu am fost și noi împreună cu voi?”. Dar dacă victoria este de partea necredincioșilor, atunci ei [le] spun: „Nu am fost noi mai tari decât voi și v-am aparat de credincioși?” Allah va judeca între voi [toți] în Ziua Învierii și niciodată Allah nu le va face necredincioșilor o cale [pentru a izbândi] asupra credincioșilor[58].', '[58] În Ziua de Apoi, dar posibil și în această lume');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Cu adevărat, ipocriții [se gândesc să] Îl înșele pe Allah, dar El întoarce înșelătoria lor [împotriva lor înșiși]. Iar când se ridică pentru Rugăciune [As-Salat], se ridică cu lene, ca să fie văzuți de oameni și nu pomenesc Numele lui Allah decât foarte puțin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Șovăind între ei [nefiind] nici de partea acestora [a credincioșilor], nici de partea acelora [a necredincioșilor]. Și pentru acela pe care Allah l-a dus în rătăcire nu îi vei găsi un drum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'O, voi cei care credeți! Nu-i luați pe necredincioși ca aliați în locul credincioșilor. Vreți să-I dați lui Allah o dovadă clară împotriva voastră?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Cu adevărat, ipocriții vor ajunge în fundul cel mai de jos al Iadului și nu vei afla niciodată ajutor pentru ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Cu excepția celor care se căiesc, se îndreaptă, se leagă cu putere de Allah și sunt sinceri în credința lor față de Allah. Aceștia vor fi împreună cu dreptcredincioșii, iar Allah le va dărui credincioșilor răsplată nemăsurată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Ce ar face Allah cu pedepsirea voastră[59], dacă voi sunteți recunoscători și credeți? Allah este Șakir [Mulțumitor] și ‘Alim [Atoateștiutor].', '[59] Ce ar câștiga');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Lui Allah nu-I place rostirea de vorbe urâte în auzul lumii, doar dacă cineva este nedreptățit. Iar Allah este Sami'' [Cel care Aude Totul], ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Dacă [în schimb] voi faceți bine pe față sau într-ascuns sau dacă iertați o faptă rea – cu adevărat Allah este ''Afuuu [Îndurător] și Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Cu adevărat, cei care nu cred în Allah și în Trimișii Săi și vor să-l separe pe Allah de Trimișii Săi și spun: „Noi credem în unii dintre ei, dar nu credem în alții” și voiesc să găsească un drum de mijloc -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'Aceia sunt cu adevărat necredincioși și Noi am pregătit pentru cei necredincioși pedeapsă rușinoasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'Dar celor care cred în Allah și în Trimișii Săi și nu fac deosebire între ei [între Trimiși], le vom dărui răsplata cuvenită lor, căci Allah este Ghafur [Iertător] și Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'Oamenii Scripturii îți cer să le pogori o Scriptură din Cer. I-au cerut și lui Moise chiar mai mult spunând: „Arată-ni-L nouă pe Allah, pe față!” Atunci i-a lovit trăsnetul pentru fapta lor rea. Apoi au luat vițelul [ca idol], cu toate că le-a venit dovadă clară. Însă Noi i-am iertat pentru aceasta și l-am dăruit pe Moise cu dovadă limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'Și Noi am ridicat deasupra lor Muntele Tor când am încheiat legământ cu ei și le-am spus: „Intrați prin poartă, prosternându-vă!”. Și le-am mai zis Noi: „Nu încălcați Sabatul!”. Și am luat de la ei legământ solemn.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Și [Noi i-am blestemat][60] din cauza încălcării legământului lor și a necredinței în Revelațiile lui Allah și a uciderii Profeților pe nedrept și a rostirii cuvintelor: „Inimile noastre sunt învelite”. Dar, Allah le-a pecetluit pentru necredința lor, astfel că ei nu cred, cu excepția a puțini dintre ei[61].', '[60] O altă interpretare este „Și [Noi am făcut anumite mâncăruri nepermise pentru ei] bazată pe versetul 160
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'Și [Noi i-am blestemat] din cauza necredinței lor și a acuzațiilor grave împotriva Mariei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'Și din cauza vorbelor lor: „Cu adevărat, noi l-am omorât pe Mesia, Iisus, fiul Mariei, Trimisul lui Allah!”, dar ei nu l-au omorât, nici nu l-au răstignit pe cruce, ci a fost făcut [altcineva] să semene cu el. Și, cu adevărat, cei care au păreri diferite în privința lui [Iisus], au îndoieli [în legătură cu moartea lui]. Ei nu au avut cunoștință sigură despre ea [moartea lui], ci urmează doar presupuneri. Cu siguranță, ei nu l-au omorât[62]', '[62] Un alt înțeles este „Și ei nu l-au omorât, fiind siguri [de identitatea lui]”, adică ei au omorât altă persoană crezând că era Iisus (pacea fie asupra sa!)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'Ci Allah l-a înălțat la El. Iar Allah este ''Aziz [Puternic] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'Nu va fi nici unul dintre oamenii Cărții care să nu creadă în el [Iisus], înaintea morții sale[63]. Iar în Ziua de Apoi, el va fi martor împotriva lor.', '[63] O altă interpretare este că „morții sale” se referă la întoarcerea lui Iisus pe pământ, sau poate însemna „moartea fiecăruia dintre oamenii Cărții”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'Și din cauza ticăloșiilor evreilor, Noi le-am oprit [anumite] mâncăruri ce le-au fost permise; și din cauza rătăcirii de către ei a multor [oameni] de la drumul lui Allah,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'Și din cauza luării de către ei a cametei, deși le-a fost interzisă; și din pricina folosirii pe nedrept a averii oamenilor. Și le-am pregătit celor necredincioși dintre ei o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Dar celor temeinici în știință dintre ei și dreptcredincioșilor care cred în ce ți-a fost trimis ție [o, Mohammed] și în ceea ce a fost trimis înainte de tine și acelora care îndeplinesc Rugăciunea [As-Salat], plătesc Dania [Az-Zakat] și cred în Allah și în Ziua de Apoi, acestora le vom Dărui Noi răsplată nemăsurată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Cu adevărat, Noi ți-am revelat ție [o, Mohammed] după cum i-am revelat și lui Noe și Profeților de după el. Și Noi le-am revelat lui Avraam, lui Ismail, lui Isaac, lui Iacob și Descendenților[64], lui Iisus, lui Iov, lui Iona, lui Aaron și lui Solomon și i-am dat lui David Psalmii.', '[64] Al-Asbat. A se vedea nota 2:136');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'Și [Noi am trimis] Trimiși despre care ți-am spus [poveștile lor] mai înainte și Mesageri despre care nu ți-am spus. Și Allah i-a Vorbit lui Moise [direct].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, '[Noi am trimis] Trimiși drept vestitori și prevenitori pentru ca oamenii să nu mai aibă niciun fel de scuză față de Allah, după Trimiși. Iar Allah este ‘Aziz [Puternic] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Dar Allah depune mărturie pentru ceea ce El ți-a pogorât. El a pogorât [Coranul] cu Știința Lui, și Îngerii [de asemenea] mărturisesc. Iar Allah este îndeajuns ca Șahid [Martor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Cu adevărat, cei care nu cred și îndepărtează [oamenii] de la drumul lui Allah, cu siguranță sunt îndelung rătăciți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Cu adevărat, cei care nu cred și fac fapte rele, Allah nu-i va ierta niciodată, nici nu-i va călăuzi pe un drum,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'Decât pe drumul Iadului, în care vor sălășlui veșnic. Iar aceasta pentru Allah este ușor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'O, voi oameni, Trimisul v-a adus vouă Adevărul de la Domnul vostru, deci credeți; este mai bine pentru voi. Dar dacă voi nu credeți, atunci, cu adevărat, ale lui Allah sunt cele din Ceruri și de pe Pământ, iar Allah este ‘Alim [Atoateștiutor] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'O, voi oameni ai Scripturii, nu exagerați în privința religiei voastre[65] și nu spuneți despre Allah decât adevărul. Cu adevărat, Mesia, Iisus, fiul Mariei, este [doar] Trimisul lui Allah și Cuvântul Său pe care El l-a transmis Mariei și un Duh [creat la un ordin] de la El. Credeți, așadar, în Allah și în Trimișii Săi. Și nu spuneți „Trei!”. Opriți-vă și aceasta va fi mai bine pentru voi. Și, cu adevărat, Allah nu este decât un Dumnezeu Unic. El este mai presus de a avea un fiu. Ale Lui sunt cele din Ceruri și de pre Pământ. Și Allah este îndeajuns ca Uakil [Ocrotitor].', '[65] Prin atribuirea de calități divine anumitor creații ale lui Allah sau prin adorarea lor în mod excesiv');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Mesia nu se va dezice niciodată de a-I fi rob lui Allah și nici Îngerii apropiați [de El]. Iar pe acela care se dezice de la slujirea Lui și este arogant, El îi va aduna la El împreună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'Cât despre cei care cred și fac fapte bune, El le va acorda răsplată din belșug, pe care o va spori cu Harul Său. Cât despre cei care refuză și sunt trufași, El le va da o pedeapsă dureroasă și nu vor afla pentru ei, în afară de Allah, Ualyy [Ocrotitor] și nici Nasir [Ajutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'O, voi oameni, v-a venit vouă Dovadă de la Domnul vostru și Noi am pogorât asupra voastră o lumină limpede[66].', '[66] Arătându-vă adevărul (Coranul)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Așadar, pe cei care cred în Allah și se țin strâns de El, îi va primi sub Îndurarea și Harul Lui, și-i va călăuzi către El pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Ei îți cer o hotărâre [verdict]. Spune: „Allah vă dă o hotărâre în privința celui fără de ascendenți și descendenți [drept moștenitori].” Dacă un bărbat s-a stins din viață și nu are niciun copil, dar are o [singură] soră, acesteia îi va reveni jumătate din ceea ce a lăsat el, iar el o moștenește [și el pe ea], dacă ea nu are niciun copil. Dar dacă sunt două surori [sau mai multe] atunci ele primesc [în mod egal] două treimi din ceea ce a lăsat el. Iar dacă sunt frați și surori, atunci bărbatului îi revine cât partea a două femei. Allah vă face [în mod] clar [Legile Lui] pentru ca voi să nu rătăciți, căci Allah este peste toate ‘Alim [Știutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'O, voi cei care credeți, îndepliniți-vă [toate] legămintele[1]. Vă este îngăduit [să mâncați carne de] șeptel, în afară de ceea ce vi s-a spus [în acest Coran]. Nu vă este îngăduit vânatul atunci când vă aflați în ihram[2]. Cu adevărat, Allah orânduiește ceea ce El Voiește.', '[1] Ce includ promisiuni, jurăminte etc
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'O, voi cei care credeți, nu încălcați Ritualurile lui Allah sau [sanctitatea] Lunii Sfinte și [nu neglijați însemnarea] animalelor de jertfă, și nici zgărzile, nu [încălcați siguranța] celor care se îndreaptă spre Casa Sfântă căutând Har și mulțumire la Domnul lor! Când ieșiți din ihram, atunci puteți vâna. Și nu lăsați ura unui popor care v-a ținut departe de Moscheea Sacră să vă facă să[-i] atacați. Și ajutați-vă în împlinirea faptelor bune și în evlavie, dar să nu vă ajutați la păcat și la nedreptate! Și fiți cu frică de Allah, căci Allah este aspru la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'Vă sunt interzise animalele moarte[3], sângele, carnea de porc, animalele asupra cărora a fost pomenit numele altcuiva decât al lui Allah [la înjunghierea lor], [animalele] omorâte prin sufocare, lovire, cădere sau împunse cu coarnele [de alt animal] și cele din care au mâncat animale sălbatice, cu excepția cazului în care voi ați înjunghiat [aceste vietăți înainte de a muri] și [va sunt interzise, de asemenea,] cele înjunghiate pe altarele de piatră[4] [ale idolilor] și cele pe care le împărțiți, prin tragere la sorți, cu săgeți. Acestea sunt pentru voi păcat. În această zi, cei care nu cred sunt deznădăjduiți [că ar mai putea să vă îndepărteze] de la religia voastră, deci, nu vă mai temeți de ei, ci temeți-vă de Mine! În această zi, am desăvârșit Religia voastră și am împlinit Harul Meu asupra voastră și am încuviințat islamul ca Religie pentru voi. Dar dacă cineva este forțat de foame [să mănânce din cele interzise], fără a fi înclinat către păcat, atunci, cu adevărat, Allah este Ghafur [Iertător], Rahim [Îndurător].', '[3] A se vedea nota 2:173
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'Ei te întreabă [o, Mohammed] ce le este permis [să mănânce]. Spune: „Vă sunt permise [toate] cele bune și cele pe care le învățați pe animalele și păsările de vânătoare [să vi le prindă], dresându-le așa cum v-a învățat Allah. Și mâncați din cele pe care ele le prind pentru voi rostind Numele lui Allah! Și fiți cu frică de Allah”. Cu adevărat, Allah socotește degrabă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'În această zi vă sunt permise vouă cele bune și mâncarea celor cărora li s-a dăruit Scriptura vă este permisă și vouă, iar mâncarea voastră le este permisă și lor. [Vă sunt permise pentru căsătorie] femeile virtuoase dintre dreptcredincioase, dar și femeile virtuoase ale celor cărora le-a fost dăruită Scriptura înaintea voastră, dacă le dați zestrea, dorindu-vă puritatea și nu preacurvia și nici luarea de ibovnice [în secret]. Iar cel care se leapădă de credință, faptele lui sunt în deșert, iar în Lumea de Apoi se va afla printre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'O, voi cei care credeți! Atunci când vă ridicați pentru Rugăciune [As-Salat], spălați-vă fețele voastre și mâinile voastre până la coate, treceți-vă mâinile voastre ude peste capetele voastre și [spălați-vă] picioarele voastre până la glezne! Dacă sunteți în stare de janabah[5], atunci purificați-vă [printr-o îmbăiere]! Dacă sunteți bolnavi, sau în călătorie, sau unul dintre voi vine de la locul unde și-a făcut nevoile, sau ați atins femeile[6] și nu găsiți apă, atunci căutați pământ curat și ștergeți-vă fețele și mâinile voastre cu el! Allah nu Voiește să vă facă vouă greutăți, ci Dorește să vă purifice și să desăvârșească Binefacerea Sa. Poate că voi veți fi mulțumitori!', '[5] A se vedea nota 4:43
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'Și aduceți-vă aminte de Harul lui Allah asupra voastră și de Legământul pe care El l-a făcut cu voi, atunci când ați spus: „Auzim și ne supunem!” Și fiți cu frică de Allah, căci Allah este ‘Alim [Bineștiutor] a ceea ce se află în piepturile voastre!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'O, voi cei care credeți, fiți statornici față de Allah, martori drepți și să nu vă împingă ura împotriva unui popor să nu fiți drepți! Fiți drepți, căci aceasta este mai aproape de evlavie! Și fiți cu frică de Allah, căci Allah este Khabir [Bineștiutor] a ceea ce faceți voi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Allah le-a promis celor care cred și împlinesc fapte bune, iertare și răsplată nemăsurată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'Cât despre cei care nu cred și țin de minciună semnele Noastre, aceia vor fi locuitorii Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'O, voi cei care credeți, aduceți-vă aminte de Binefacerile lui Allah asupra voastră atunci când un popor a voit să-și întindă mâinile spre voi [pentru a vă ataca], dar El a oprit mâinile lor de la voi. Fiți, așadar, cu frică de Allah! Și în Allah trebuie să se încreadă dreptcredincioșii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Allah a încheiat un Legământ cu Fiii lui Israel și Noi am trimis dintre ei doisprezece conducători [aleși]. Și Allah a spus: „Eu sunt cu voi! Dacă voi împliniți Rugăciunea [As-Salat], achitați Dania [Az-Zakat], credeți în Trimișii Mei și îi sprijiniți și Îi dați lui Allah un bun împrumut[7]; atunci Eu voi șterge faptele voastre rele și vă voi primi în Grădini pe sub care curg râuri. Dar acela dintre voi care se va întoarce la necredință, după aceasta, rătăcește de la drumul cel drept.”', '[7] Cheltuind pentru cauza lui Allah, căutând răsplata Lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Și pentru încălcarea Legământului lor, Noi i-am blestemat și le-am împietrit inimile. Ei răstălmăcesc Cuvintele[8] [schimbându-le sensurile] și locul lor [de drept] și au uitat o parte din ceea ce li s-a reamintit[9]. Tu nu vei înceta să descoperi înșelătoria lor, cu excepția unui mic număr dintre ei. Dar iartă-i și trece-le cu vederea [fărădelegile]. Cu adevărat, Allah îi Iubește pe cei care fac bine.', '[8] Au schimbat sensurile Cuvintelor lui Allah din Tora
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'Și am încheiat Noi legământ cu cei care spun: „Noi suntem creștini", dar ei au uitat o parte din ceea ce li s-a reamintit[10]. Așa că am stârnit Noi ură și vrajbă între ei[11] până la Ziua Învierii. Atunci le va Vesti Allah ceea ce au făcut ei.', '[10] În Evanghelie cu privire la venirea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'O, oameni ai Scripturii, a venit la voi Trimisul Nostru ca să vă arate multe lucruri din cele pe care voi le-ați ascuns din Scriptură, trecând peste multe altele[12]. V-au venit vouă o lumină și o Carte limpede [Coranul] de la Allah,', '[12] Precum păcatul vostru în acea privință');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Prin care Allah îi călăuzește pe cei care caută Mulțumirea Lui pe căile păcii[13] și îi scoate din întunecimi la lumină, prin Grația Sa, și îi călăuzește pe un drum drept.', '[13] Siguranță, bunăstare, integritate și refugiu de la Iad. Literar: „libertate de tot ce este rău”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Necredincioși sunt cei care spun că Dumnezeu este Mesia, fiul Mariei. Spune: „Cine L-ar putea împiedica pe Allah, dacă ar Voi să-l distrugă pe Mesia, fiul Mariei, și pe mama lui și pe toți cei aflați pe pământ?” Ale lui Allah sunt Împărăția Cerurilor și a Pământului, precum și ceea ce se află între ele. El Creează ceea ce El Voiește. Și Allah este Qadir [Atotputernic] peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Dar evreii și creștinii spun: „Noi suntem fiii lui Allah și cei dragi Lui”. Spune: „Atunci de ce vă pedepsește pentru păcatele voastre?” Dimpotrivă, voi sunteți făpturi omenești dintre cele pe care El le-a creat. El îl iartă pe cel pe care El voiește și îl pedepsește pe cel pe care El voiește. Ale lui Allah sunt Împărăția Cerurilor și a Pământului, precum și ceea ce se află între ele și la El este întoarcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'O, oameni ai Scripturii, l-am trimis Noi pe Trimisul Nostru [Mohammed] la voi ca să vă arate vouă [religia], la o vreme după [ceilalți] Trimiși, pentru ca voi să nu spuneți: „Nu ne-a venit nouă niciun vestitor și niciun prevenitor.” Acum v-a venit vouă vestitor și prevenitor. Și Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'Și [spune, o, Mohammed] atunci când Moise i-a spus poporului său: „O, popor al meu! Aduceți-vă aminte de Harul lui Allah asupra voastră atunci când a făcut dintre voi Profeți și v-a făcut pe voi posesori[14]. El v-a dat vouă ceea ce nu a dat niciuneia dintre lumi[de atunci]!', '[14] A tot ceea ce aveți nevoie – în mod specific cămine, soții și servitori. Sau „suverani” adică cei cu autoritate independentă.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, 'O, popor al meu, intrați în Pământul Sfânt [Palestina], pe care Allah vi l-a hărăzit și nu dați înapoi, [refuzând lupta], și să fiți astfel dintre cei pierzători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Ei au spus: „O, Moise, acolo este un popor de oameni puternici. Noi nu vom intra în el până ce ei nu vor ieși din el. Dacă vor ieși ei, atunci vom intra noi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'Au spus doi bărbați dintre cei care se temeau [să fie neascultători] și asupra cărora Allah revărsase Harul Său: „Intrați peste ei pe poartă, pentru că atunci când veți trece de ea, veți fi învingători[15]! Și în Allah încredeți-vă, dacă sunteți dreptcredincioșii!”', '[15] Dacă ascultați porunca lui Allah în a avea încredere în El, El va îndeplini promisiunea Lui față de voi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, 'Ei au răspuns: „O, Moise, cu adevărat noi nu vom intra în niciun caz, câtă vreme ei sunt acolo. Așadar du-te tu și Domnul tău și luptați. Cu adevărat noi vom ședea aici!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, 'Moise a spus: „Doamne, cu adevărat eu nu am putere [control] decât asupra mea și a fratelui meu, deci desparte-ne[16] pe noi de acest neam de nelegiuiți!”', '[16] Sau „diferențiază-ne” sau „judecă între noi și ei”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, '[Allah] i-a răspuns: „Cu adevărat, [Țara] asta le va fi oprită timp de patruzeci de ani, în care vor rătăci prin lume. Nu fi mâhnit pentru neamul acesta de nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'Și istorisește-le lor povestea celor doi fii ai lui Adam, așa cum a fost ea cu adevărat, atunci când au adus ei ofrandă [lui Allah], și a fost primită de la unul dintre ei, dar nu a fost primită de la celălalt. Și a spus [acesta din urmă]: „Te voi omorî, cu siguranță”. I-a răspuns [primul]: „Cu adevărat, Allah primește jertfa numai de la cei evlavioși [care au frică de El].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'Dacă vei ridica mâna spre mine ca să mă omori, eu nu voi ridica mâna spre tine ca să te omor, căci eu am frică de Allah, Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Cu adevărat, eu voiesc să porți păcatul meu [păcatul uciderii mele] împreună cu păcatul tău [păcatele săvârșite mai înainte] și să ajungi printre oaspeții Focului. Și aceasta este răsplata celor nelegiuiți!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'Însă sufletul său i-a permis[17] să-l ucidă pe fratele lui și l-a omorât, intrând astfel în rândul celor pierduți.', '[17] Criminalul și-a permis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Apoi Allah a trimis un corb, ca să scurme pământul, pentru a-i arăta cum să ascundă rușinea[18] fratelui său. Atunci el a spus: „Vai de mine! Oare sunt eu mai neputincios decât acest corb și nu sunt în stare să îngrop rușinea [cadavrul] fratelui meu?” Și a ajuns el astfel să se căiască.', '[18] Referindu-se la cadavru, evidența faptei sale rușinoase');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'De aceea am prescris Noi pentru Fiii lui Israel că cel care ucide un suflet nevinovat de uciderea altui suflet sau de o altă stricăciune pe pământ, este ca și când i-ar ucide pe toți oamenii, iar cel care lasă în viață un suflet este ca și cum i-ar lăsa în viață pe toți oamenii. Trimișii Noștri au venit la ei cu dovezi limpezi și totuși iată că mulți dintre ei și după [venirea Trimișilor] arată nesupunere pe Pământ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Cu adevărat, pedeapsa celor care luptă[19] împotriva lui Allah și a Trimisului Său și caută să aducă pe Pământ stricăciune este că ei vor fi omorâți sau răstigniți pe cruce sau li se vor tăia mâinile și picioarele cruciș sau vor fi alungați din țară. Aceasta va fi pentru ei rușine în lumea de acum, iar în Lumea de Apoi vor avea parte de o pedeapsă mare,', '[19] Care fac acte de violență și terorism împotriva indivizilor sau trădare și agresiune împotriva statului islamic');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'Cu excepția celor care se căiesc înainte de a-i prinde. Și să știți că Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'O, voi cei care credeți, fiți cu frică de Allah, căutați mijloacele pentru a vă apropia de El și luptați pe calea Lui. Poate că voi o să izbândiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Cu adevărat, cei care nu cred - de-ar avea ei tot ce se află pe Pământ și încă o dată pe atât, pentru a se răscumpăra cu aceasta de pedeapsa din Ziua Învierii, tot nu li se va primi lor. Și ei vor avea parte de o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Ei ar voi să iasă din Foc, dar nu vor ieși din el, căci chinul lor va fi veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, '[Cât despre] hoț și hoață, tăiați-le mâinile drept răsplată pentru ceea ce au dobândit [prin furt] și drept pedeapsă de la Allah, căci Allah este ‘Aziz [Puternic] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'Dar pe cel care se căiește în urma fărădelegilor lui și se îndreaptă, Allah îl va ierta, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Nu știi tu că a lui Allah este Împărăția Cerurilor și a Pământului? El pedepsește pe cine Voiește El și iartă pe cine Voiește El, căci Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'O, Trimisule, să nu te întristeze cei care se grăbesc spre necredință, dintre aceia care spun cu gurile lor: „Noi credem!”, dar inimile lor nu cred și nici dintre evrei. [Ei] ascultă numai de minciună și de un alt popor, ce nu a venit niciodată la tine[20]. Ei răstălmăcesc Cuvintele după ce ele au fost bine rânduite, spunând: „Dacă vi s-a dat[21] acest lucru, luați-l, iar dacă nu vi s-a dat, fiți prevăzători [și feriți-vă de el]!” Însă pe acela pe care Allah Voiește să-l ispitească[22], tu nu-l vei putea apăra. Aceștia sunt cei ale căror inimi Allah nu a Voit să le purifice, și ei vor avea parte, în această lume, de rușine, iar în Lumea de Apoi, de chin nemăsurat.', '[20] Nu au participat la adunările Profetului (pacea și binecuvântarea lui Allah fie asupra sa) sau nu au auzit cuvintele sale
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, '[Ei] ascultă numai de minciună și sunt lacomi după tot ceea ce este interzis. Dacă vor veni la tine, [o, Mohammed], atunci judecă între ei sau îndepărtează-te de ei. Dacă te vei îndepărta de ei, nu-ți vor putea face ei un rău, iar de vei judeca între ei, atunci judecă după dreptate. Cu adevărat, Allah îi iubește pe cei drepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'Dar cum îți vor cere ei să le fii judecător, când ei au Tora, în care se află judecata lui Allah? Apoi îți vor întoarce spatele [chiar] și după aceasta, dar ei nu sunt [de fapt] credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Cu adevărat, Noi am pogorât Tora, și în ea este Călăuzire și Lumină. După ea judecă Profeții cei supuși [lui Allah], pentru evrei, precum și rabinii și învățații, din ceea ce li s-a încredințat spre păstrare din Scriptura lui Allah și ei au fost martori la ea. Deci nu vă temeți de oameni, ci temeți-vă de Mine. Și nu vindeți Versetele Mele pentru un preț de nimic. Iar cei care nu judecă după ceea ce a pogorât Allah, aceia sunt necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Și Noi am prescris pentru ei, în ea: suflet pentru suflet, ochi pentru ochi, nas pentru nas, ureche pentru ureche, dinte pentru dinte și rănile după legea talionului. Dar cel care renunță la aceasta în semn de milostenie, ea va fi ispășire pentru el. Iar aceia care nu judecă după ceea ce a pogorât Allah, aceia sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'Și Noi l-am trimis, după ei[23], pe Iisus, fiul Mariei, întărind ceea ce a venit înainte de el în Tora și i-am dat lui Evanghelia, în care este Călăuzire și Lumină, confirmând ceea ce o precedase în Tora, Călăuzire și Îndemnare pentru cei evlavioși.', '[23] Urmând tradiția profeților fiilor lui Israel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'Deci să judece oamenii Evangheliei după ceea ce Allah a trimis în ea. Iar cei care nu judecă după ceea ce a pogorât Allah, aceia sunt cei păcătoși [și nesupuși].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'Iar ție, [o, Mohammed], ți-am trimis Cartea [Coranul] cu Adevărul, confirmând Scriptura de dinaintea ei și ca o Lege deasupra ei. Deci fă judecată între ei după ceea ce ți-a trimis Allah și nu urma poftele lor, îndepărtându-te de la Adevărul ce ți-a venit. Fiecăruia dintre voi Noi i-am dat o Lege și o Rânduială. Dacă ar fi Voit Allah, v-ar fi făcut o singură comunitate [unită în religie], dar El Voieşte să vă încerce în ceea ce v-a dat. Deci întreceți-vă în împlinirea de fapte bune[24]. La Allah este întoarcerea voastră, a tuturor, și El vă va înștiința despre cele asupra cărora ați avut păreri împărțite.', '[24] Ascultare față de Allah conform Coranului și Sunnah profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'Judecă [o, Mohammed] între ei după ceea ce ți-a trimis Allah și nu urma poftele lor și fii cu băgare de seamă, să nu te ispitească pentru a te îndepărta de la o parte dintre cele pe care ți le-a revelat Allah. Iar dacă ei întorc spatele - atunci să știi că Allah Voiește să-i pedepsească pentru o parte dintre păcatele lor. Și, cu adevărat, mulți dintre oameni sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Și oare este judecata din [timpul] ignoranței[25] ceea ce ei doresc? Dar cine este mai bun în judecată decât Allah, pentru un popor [de oameni] care sunt fermi în credință?', '[25] Din perioada păgână');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'O, voi cei care credeți! Nu-i luați pe evrei și pe creștini drept aliați. Ei [de fapt] sunt aliați unii cu alții. Iar cei dintre voi care le sunt aliați sunt ca și cum ar face parte dintre ei. Cu adevărat, Allah nu-i călăuzește pe calea cea bună pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'Îi vei vedea pe cei cu boală în inimi[26], grăbindu-se spre ei, spunând: „Ne e teamă că o nenorocire se va abate asupra noastră”. Dar s-ar putea ca Allah să aducă biruința sau o altă decizie de la El și atunci ei se vor căi pentru ce au ținut ascuns în sufletele lor.', '[26] Ipocrizie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'Iar cei credincioși vor spune[27] atunci: „Aceștia sunt cei care au jurat pe Allah cu cele mai puternice jurăminte că vor fi cu adevărat alături de voi?” Iată că faptele lor sunt deșarte, iar ei au devenit pierduți.', '[27] Despre ipocriți după expunerea lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'O, voi cei care credeți, acela dintre voi care renunță la Religia sa [să știe că] Allah va aduce [în locul lui] un popor [de oameni] pe care-i iubește și care-L iubesc pe El, blânzi față de dreptcredincioși și aspri cu necredincioșii, care vor lupta pe calea lui Allah și nu se vor teme de clevetirea clevetitorilor. Acesta este Harul lui Allah, pe care-l dăruiește cui Voiește El, căci Allah este Uasi’ [Cel cu Har Nemărginit] și ‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Aliații voștri sunt doar Allah, Trimisul Lui și cei care cred, cei care împlinesc Rugăciunea [As-Salat], dau Dania [Az-Zakat] și se pleacă [înaintea lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Iar cei care-i iau drept aliați pe Allah, pe Trimisul Lui și pe cei care cred [vor izbândi, căci aceasta este] tabăra lui Allah care va fi biruitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'O, voi cei care credeți, nu-i luați drept aliați pe cei care au luat religia voastră în derâdere și în bătaie de joc dintre cei cărora le-a fost trimisă Scriptura înaintea voastră, și nici dintre necredincioși. Și fiți cu frică de Allah, dacă sunteți credincioși [adevărați].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'Iar când voi chemați la Rugăciune [As-Salat], ei o iau în râs și în bătaie de joc. Aceasta pentru că ei sunt un popor care nu pricepe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'Spune: „O, voi oameni ai Scripturii! Ne urâți pentru altceva decât pentru că noi credem în Allah și în ceea ce ne-a fost trimis nouă și în ceea ce a trimis mai înainte și pentru că cei mai mulți dintre voi sunteți nelegiuiți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'Spune: „Să vă vestesc eu despre ceva și mai rău decât aceasta, drept pedeapsă de la Allah? Cei pe care Allah i-a blestemat și pe care s-a mâniat și i-a prefăcut pe unii dintre ei în maimuțe și în porci ca și cei care l-au adorat pe Taghut[28]. Aceia au un loc și mai rău și sunt mai departe de calea cea dreaptă!”.', '[28] A se vedea nota 2:256');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'Și atunci când vin la voi vă spun: „Noi credem!”. Însă ei intră cu necredință [în inimile lor] și ies cu ea, iar Allah știe prea bine ce ascund ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'Îi vei vedea pe mulți dintre ei cum se grăbesc spre păcat, spre agresiune și spre mâncarea celor interzise. Și cât de mare este răul pe care ei îl fac!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'De ce rabinii și învățații lor nu-i opresc de la rostirea vorbelor păcătoase și de la mâncarea celor oprite? Cât de ticălos este ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Și evrei spun: „Mâna lui Allah este închisă[29]!”. Închise sunt însă mâinile lor și blestemați au fost pentru ceea ce au spus. Dimpotrivă, Mâinile Lui sunt larg deschise și El dăruiește după cum Voiește. Iar ceea ce ți s-a trimis de la Domnul tău îi va face pe mulți dintre ei să sporească în fărădelege și necredință. Noi am aruncat între ei vrăjmășie și ură până în Ziua Învierii. Ori de câte ori vor aprinde ei focul războiului [împotriva ta], Allah îl va stinge. Ei caută să semene pe pământ stricăciune, însă Allah nu-i iubește pe cei care seamănă stricăciune.', '[29] Făcând aluzie la inabilitatea de a da sau la zgârcenie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'De-ar crede oamenii Scripturii și de-ar fi cu frică [de Allah], Noi le-am ierta faptele lor rele și i-am primi în Grădinile pline de tihnă și plăcere [An-Na’im].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Dacă ei ar împlini [legea din] Tora și Evanghelia și ceea ce li s-a pogorât de la Domnul lor [Coranul], atunci ei ar mânca din cele care se află deasupra lor și din cele care se află sub picioarele lor[30]. Printre ei se află un grup care merge pe o cale de mijloc, însă mulți dintre ei săvârșesc numai răutăți.', '[30] O mare abundență');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'O, Trimisule, vestește ceea ce ți-a fost trimis de la Domnul tău, iar dacă nu o faci, înseamnă că nu ai transmis Mesajul Lui. Iar Allah te va apăra de oameni. Cu adevărat Allah nu călăuzește poporul de necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'Spune: „O, oameni ai Cărții! Voi nu vă sprijiniți pe nimic, până ce nu veți împlini Tora și Evanghelia și ceea ce vi s-a trimis de către Domnul vostru [Coranul]!” Cele ce ți le-a trimis Domnul tău vor face să sporească fărădelegea și necredința multora dintre ei. Așadar nu fi mâhnit pentru cei necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Cu adevărat, cei care cred [în profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)] și cei care au fost evrei sau sabeeni sau creștini [înainte de el (pacea și binecuvântarea lui Allah fie asupra sa)] – cei [dintre ei] care vor crede în Allah și în Ziua de Apoi și vor săvârși fapte bune, nu au a se teme și nici nu vor fi mâhniți[31].', '[31] A se vedea nota 2:62');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Noi am încheiat Legământ cu Fiii lui Israel și am trimis la ei Mesageri. Dar de fiecare dată când venea la ei un Mesager cu ceea ce nu era plăcut pentru sufletele lor, pe o parte dintre ei i-au învinuit de minciună, iar pe o altă parte dintre ei i-au omorât.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, 'Și ei au crezut că nu va fi pedeapsă împotriva lor și au devenit orbi și surzi. Apoi, Allah a primit căința lor. Apoi, din nou, mulți dintre ei au devenit orbi și surzi. Însă Allah este Basir [Cel care Vede Bine] ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Necredincioși sunt cei care spun: „Dumnezeu e Mesia, fiul Mariei!” în timp ce Mesia a spus: „O, Fii ai lui Israel, adorați-L pe Allah, Domnul meu și Domnul vostru!” Cu adevărat, cel care Îi asociază lui Allah pe altcineva, Allah va face Paradisul interzis pentru el, iar adăpostul lui va fi Focul. Și pentru nelegiuiți nu va fi ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Necredincioși sunt cei care spun: „Dumnezeu este treimea din trei”[32]. Și nu este alt dumnezeu afară de Unicul Dumnezeu. Și de nu vor înceta să vorbească astfel, îi va atinge și pe cei necredincioși dintre ei pedeapsă dureroasă.', '[32] O parte din trei, referitor la conceptul trinității din Creștinism');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Și, oare, nu vin ei să se căiască la Allah și să-i ceară Lui iertare? Iar Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Mesia, fiul Mariei, nu este decât un Mesager, asemenea Mesagerilor de dinainte de el, iar mama lui este o femeie cu evlavie adevărată. Amândoi mâncau bucate [de rând][33]. Privește ce Semne evidente le trimitem Noi și apoi privește cum sunt ei îndepărtați [de la ele]!', '[33] Aceștia aveau nevoie de mâncare, demonstrând faptul că ei erau creații ale lui Allah și nu ființe divine');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'Spune: „Voiți voi să adorați în locul lui Allah pe altcineva care nu are nicio [putere de] vătămare sau folos? Allah este As-Sami'' [Cel care Aude Totul], Al-''Alim [Atoateștiutorul]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'Spune: „O, voi oameni ai Scripturii! Nu încălcați limitele în credința voastră [trecând] peste adevăr și nu urmați poftele unor oameni care înainte au fost rătăciți și care i-au dus întru rătăcire pre mulți și s-au abătut de la calea cea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'Aceia care nu au crezut dintre Fiii lui Israel au fost blestemați prin vorbele lui David și ale lui Iisus, fiul Mariei. Aceasta pentru că ei s-au răzvrătit și au încălcat poruncile [în mod frecvent].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'Ei nu s-au oprit unii pe alții de la fărădelegile pe care le-au comis. Ce fapte rele au săvârșit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'Îi vezi pe mulți dintre ei făcând alianță cu cei care nu cred! Vai de cele pe care sufletele lor le trimit înainte! Allah se mânie pe ei și în chinuri vor rămâne veșnic!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'Dacă ar crede în Allah și în Profet și în ceea ce i s-a trimis lui, nu și i-ar face aliați. Însă mulți dintre ei sunt nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'Vei găsi că evreii și cei care [Îi] fac asociați [lui Allah] sunt cei mai îndârjiți în dușmănia lor față de cei care cred, după cum vei găsi că cei mai prietenoși față de cei ce cred sunt aceia care spun: „Noi suntem creștini”. Și asta pentru că printre ei se află preoți și călugări și pentru că ei nu se fălesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, 'Iar atunci când aud ce i s-a dezvăluit Trimisului, vei vedea ochii lor cum se umplu de lacrimi la recunoașterea Adevărului. Ei spun: „Doamne, noi credem! Scrie-ne pe noi împreună cu cei care depun mărturie [în legătură cu Adevărul Coranului]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Și de ce să nu credem în Allah și în Adevărul care ne-a venit? Și noi ne dorim să ne facă Domnul nostru să intrăm [în Rai] împreună cu cei cucernici”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'Iar Allah i-a răsplătit pentru ceea ce au spus[34] cu Grădini pe sub care curg râuri și în care vor sălășlui veșnic, căci aceasta este răsplata celor care fac bine.', '[34] Acceptarea adevărului și devotamentul pentru religia lui Allah (islam)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'Cât despre cei care nu cred și țin de mincinoase Versetele Noastre, ei vor fi oaspeții Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'O, voi cei care credeți, nu opriți Bunătățile pe care Allah vi le-a îngăduit și nu încălcați [Poruncile], căci Allah nu-i iubește pe cei ce încalcă [Poruncile].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'Mâncați din ceea ce Allah v-a dăruit, ca fiind îngăduit și bun, și fiți cu frică de Allah, în Care voi credeți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Allah nu vă va mustra pentru jurămintele voastre rostite la întâmplare[35], însă vă va mustra pentru jurămintele făcute cu intenție. Ispășirea[36] pentru ele va fi hrănirea a zece sărmani cu ceea ce îi hrăniți în mod obișnuit pe cei din familia voastră, sau îmbrăcarea lor, sau eliberarea unui sclav. Cel ce nu găsește [mijloacele pentru aceasta] [trebuie] să țină Post trei zile. Aceasta este ispășirea pentru jurămintele voastre, dacă le-ați făcut. Dar păziți-vă jurămintele[37]. Astfel vă limpezește Allah Versetele Lui. Poate că veți fi mulțumitori!', '[35] Jurământul făcut doar din obiceiul vorbirii sau ceea ce spune o persoană fără intenție
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'O, voi cei care credeți, cu adevărat, vinul[38], jocurile de noroc, pietrele ridicate [idolii] și săgețile [pentru prezicere] sunt numai murdării din lucrătura lui Șeitan. Deci feriți-vă de ele ca să izbândiți.', '[38] Orice băutură alcoolică');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Șeitan dorește doar să semene dușmănie și ură între voi, prin vin și prin jocul de noroc, și să vă abată de la Pomenirea lui Allah și de la Rugăciune [As-Salat]. Oare nu vă veți opri voi [de la acestea]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'Așadar, fiți cu supunere față de Allah și fiți cu supunere față de Trimisul [Lui] și fiți prevăzători. Iar dacă vă veți abate, să știți că Trimisului Nostru nu-i rămâne decât transmiterea [Mesajului] limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'Nu este un păcat pentru cei care cred și împlinesc fapte bune, pentru ceea ce ei au gustat [în trecut], dacă ei sunt cu frică [de Allah], au crezut și au săvârșit fapte bune, și apoi [au continuat] să fie cu frică [de Allah] și să creadă, și apoi [tot astfel] au fost cu frică [de Allah] și au împlinit cele mai bune [fapte], căci Allah îi Iubește pe cei care fac bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'O, voi cei care credeți, [atunci cand voi veți fi în stare de sacralizare] Allah vă va încerca cu un vânat, pe care [l-ați putea] prinde cu mâinile voastre sau cu lăncile voastre, pentru ca Allah să îl vădeasca pe acela care se teme de El în cele nevăzute. Însă cel care după aceea încalcă rânduiala [aceasta], va avea parte de pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'O, voi cei care credeți, nu ucideți vânatul când sunteți în stare de ihram[39]. Iar acela dintre voi care îl omoară intenționat este pedepsit să dea din vite atât cât a omorât, după ce vor judeca fapta lui doi [bărbați] drepți dintre voi, ca jertfă [lui Allah] menită să ajungă [săracilor] la Al-Ka’aba, sau să ispășească, hrănind câțiva sărmani sau, în loc de aceasta, să postească, pentru ca să guste urmările faptei sale. Allah iartă ceea ce a trecut, dar pe cel care se va întoarce [la greșeală] Allah îl va pedepsi cu asprime, căci Allah este ‘Aziz [Puternic] și deținător al Puterii de a pedepsi.', '[39] A se vedea nota 5:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Vă este permis vânatul pe mare, iar mâncarea lui este pentru voi, ca și pentru călători[40], merindă, dar vă este interzis vânatul pe uscat, cât timp sunteți în stare de sacralizare [ihram]. Și fiți cu frică de Allah, căci la El vă veți aduna!', '[40] Pescuitul și mâncatul a tot ceea ce este prins din mare este permis chiar și în starea de ihram');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Allah a făcut Al-Ka''aba, Casa Sfântă, spre folosul[41] oamenilor, precum și Luna Sfântă, jertfa și zgărzile. Aceasta pentru ca voi să cunoașteți că Allah Știe tot ce este în Ceruri și pe Pământ și că El este peste toate Alim[Atoateștiutor].', '[41] Drept simbol pentru Religia lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Să știți că Allah este aspru în pedeapsă, dar că Allah este și Ghafur [Iertător], Rahim [Îndurător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Trimisului nu-i revine decât să vă vestească [Mesajul], însă Allah Știe atât ce arătați, cât și ceea ce țineți ascuns.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'Spune: „Răul și binele nu sunt egale, chiar și dacă abundența [și mulțimea] răului te-ar putea impresiona [și plăcea]!”. Deci, fiți cu frică de Allah, voi cei înțelepți, pentru ca să izbândiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'O, voi cei care credeți, nu întrebați despre lucruri care, dacă vă sunt arătate, nu v-ar plăcea! Însă, dacă întrebați despre ele în timp ce Coranul este revelat, atunci ele vă vor fi arătate. Iar Allah v-a iertat pentru ele [pentru ce a trecut], căci Allah este Ghafur [Iertător], Blând [Halim].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Au întrebat despre ele și alți oameni înaintea voastră și apoi au ajuns să nu creadă în ele[42].', '[42] Din cauză că nu au vrut să facă ceea ce le-a fost poruncit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'N-a statornicit Allah nimic despre Bahira, nici despre Sa''iba, nici despre Uasila și nici despre Ham[43]. Însă, cei care nu cred au născocit minciuni împotriva lui Allah și cei mai mulți dintre ei nu au judecată.', '[43] Categorii de cămile ce erau dedicate idolilor și eliberate pe pășuni, fără a mai fi deținute de oameni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'Și atunci când li se spune: „Veniți la ceea ce a pogorât Allah și la Trimis!”, ei spun: „Pentru noi sunt de ajuns cele cu care i-am găsit pe părinții noștri!”. Chiar dacă părinții lor nu știau nimic și nu au fost călăuziți [pe calea cea bună]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'O, voi cei care credeți, fiți cu grijă față de sufletele voastre [aceasta este o responsabilitate asupra voastră]. Cei care au rătăcit nu vă vor face rău, dacă sunteți pe calea cea bună. La Allah este întoarcerea voastră a tuturor și El vă va vesti despre ceea ce ați împlinit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'O, voi cei care credeți, dacă moartea se apropie de unul dintre voi, să fie martor între voi la facerea testamentului doi [bărbați] cinstiți din rândul vostru sau alți doi, nu din rândul vostru, dacă sunteți în călătorie prin lume și s-a abătut asupra voastră nenorocirea morții. Să îi rețineți după Rugăciune [As-Salat] și să le cereți să jure pe Allah, dacă aveți îndoieli: „Noi nu vindem această [mărturie a noastră] pentru niciun preț, chiar dacă este vorba de o rudă apropiată, și nici nu ascundem mărturia lui Allah[44]! Cu adevărat, noi am fi atunci dintre păcătoși!”.', '[44] Obținută de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'De se va descoperi că ei doi sunt vinovați de păcat [mărturie falsă], alți doi dintre cei cărora li s-a făcut nedreptate, mai cinstiți, le vor lua locul și amândoi vor jura pe Allah: „Mărturia noastră este mai îndreptățită decât mărturia celor doi și noi nu suntem nedrepți, căci atunci am fi dintre cei nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Acesta este mijlocul cel mai sigur pentru a-i îndupleca să facă mărturia după adevăr, căci se vor teme să nu vină alte jurăminte după jurămintele lor. Și fiți cu frică de Allah și luați aminte, căci Allah nu-i călăuzește pe oamenii nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, '[Luați aminte de] Ziua când Allah îi va aduna pe [toți] Mesagerii și le va spune: „Ce vi s-a răspuns [când ați vestit]?” Ei vor spune: „Noi nu avem știință! Tu ești Marele Știutor al celor neștiute!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, '[Ziua] când Allah va spune: „O, Iisus, fiu al Mariei, adu-ți aminte de Harul Meu asupra ta și asupra mamei tale, când Eu te-am sprijinit cu Duhul Sfânt [Îngerul Gavriil] și le-ai vorbit oamenilor din leagăn și când ai fost bărbat în toată firea și [adu-ți aminte] când Eu te-am învățat scrierea, înțelepciunea, Tora și Evanghelia. Și când tu ai plăsmuit din lut chipul unei păsări, cu îngăduința Mea, apoi ai suflat asupra lui și s-a făcut pasăre, cu îngăduința Mea. Și i-ai vindecat, cu îngăduința Mea, pe cel orb și pe cel lepros. Și ai înviat morții, cu îngăduința Mea. Și i-am oprit pe Fiii lui Israel de la tine[45], când tu le-ai adus dovezi clare, iar aceia dintre ei care nu au crezut au spus: „Aceasta nu este decât vrăjitorie limpede!”.', '[45] Să îl omoare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'Și [adu-ți aminte] când Eu le-am revelat apostolilor, spunând: „Credeți în Mine și în Trimisul Meu [Iisus]!”, ei au răspuns: „Noi credem, deci mărturisește că noi suntem cu desăvârșire supuși [musulmani]!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'Și [adu-ți aminte] când apostolii au spus: „O, Iisus, fiu al Mariei, poate, oare, Domnul tău să ne coboare o Masă servită din Cer[46]?” El [Iisus] le-a zis: „Fiți cu frică de Allah, dacă sunteți credincioși!”.', '[46] Aceasta este povestea Mesei de la care își trage numele acest capitol');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, 'Ei au zis: "Voim să mâncăm din ea, ca să se liniștească inimile noastre și ca să știm că tu ne-ai spus nouă numai adevărul și să fim întru aceasta printre martori".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Atunci a spus Iisus, fiul Mariei: „O, Allah, Stăpân al nostru! Coboară-ne nouă o Masă servită din Cer ca să ne fie nouă sărbătoare - pentru cel dintâi și pentru cel din urmă dintre noi - și un semn de la Tine! Și binecuvântează-ne cu cele de ospăț, căci Tu ești Cel mai Bun dintre cei care hrănesc!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Și i-a răspuns Allah: „Cu adevărat o voi coborî vouă, dar pe cel care nu va crede nici după aceasta îl voi pedepsi cu un chin cu care nu voi mai pedepsi pe nimeni din toate lumile!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'Și [luați aminte de Ziua] când Allah va spune: „O, Iisus, fiu al Mariei! Le-ai spus tu oamenilor: „Luați-mă pe mine și pe mama mea drept dumnezei în locul lui Allah?”, el Îi va răspunde: „Mărire Ție! Eu nu aș fi putut să spun ceea ce nu aveam dreptul să spun! Dacă aș fi spus, ai ști, căci Tu doară Știi ce este înăuntrul meu, pe când eu nu știu ce este înăuntrul Tău! Cu adevărat Tu ești Marele Știutor al celor neștiute”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'Eu nu le-am spus decât ceea ce mi-ai poruncit Tu: „Adorați-L pe Allah, Domnul meu și Domnul vostru!” Și am fost martor asupra lor atâta vreme cât m-am aflat printre ei. Și după ce m-ai luat la Tine, ai fost doar Tu Priveghetor peste ei, căci Tu ești Martor tuturor lucrurilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Dacă îi pedepsești, ei sunt cu adevărat robii Tăi, iar dacă îi ierți, Tu ești ‘Aziz [Puternic], Hakim [Înțelept]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Allah va spune: „Aceasta este Ziua când celor sinceri [și care cred în adevăr] le va fi de folos sinceritatea lor!”, iar ei vor avea parte de Grădini pe sub care curg râuri și veșnic vor sălășlui în ele.” Allah este Mulțumit de ei, iar ei sunt mulțumiți de El! Aceasta este [cea mai] măreață izbândă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'A lui Allah este Împărăția Cerurilor și a Pământului, precum și toate care se află în ele, căci El este cu Putere peste toate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'Laudă lui Allah, Care a creat Cerurile și Pământul și a rânduit întunericul și lumina. Cu toate acestea, cei care nu cred Îi aduc parteneri Domnului lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'El este Cel care v-a creat din lut și apoi a hotărât un termen[1] și un timp stabilit [cunoscut] la El[2]. Dar cu toate acestea, voi vă îndoiți!', '[1] Un timp specificat pentru moarte
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Și El este Allah [Unicul Dumnezeu] în Ceruri și pe Pământ. El Știe ceea ce voi tăinuiți și ceea ce voi rostiți, după cum Știe și ceea ce agonisiți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'Și nu le vine lor niciun semn dintre semnele Domnului lor, fără ca ei să se întoarcă de la ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Fiindcă au socotit drept minciună Adevărul [Coranul] atunci când a venit la ei. Dar le vor veni vești despre cele pe care le-au luat în derâdere[3].', '[3] Ei vor experimenta realitatea a ceea ce au negat și consecințele negării lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Nu au văzut ei câte popoare am nimicit Noi înaintea lor? Pe aceia îi întăriserăm Noi pe pământ cum nu v-am întărit pe voi. Și le-am trimis Noi [ploaie din] Cer și am făcut Noi să curgă râuri pe sub picioarele lor. Apoi i-am nimicit Noi pentru păcatele lor și am creat, după ei, alte popoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'Și de ți-am fi pogorât Noi ție, [o, Mohammed], o Carte scrisă pe foi, [coborâtă din Cer] și ar fi atins-o cu mâinile lor, ar fi spus cei care nu cred: „Aceasta nu este decât vrăjitorie învederată”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'Și ei spun: „De ce nu a fost trimis un Înger la el [Mohammed]?”[4] Însă dacă am fi trimis Noi un Înger, treaba ar fi fost decisă[5], căci după aceea nu li s-ar mai fi dat lor niciun răgaz!', '[4] Drept sprijin pentru profeția lui (pacea și binecuvântarea lui Allah fie asupra sa)
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'Și dacă l-am fi făcut Noi [pe Profet] un Înger, Noi l-am fi făcut cu chip de om și s-ar fi aflat în aceeași încurcătură în care sunt ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Însă au fost batjocoriți Trimiși și înainte de tine, dar cei care i-au batjocorit au fost cuprinși tocmai de cele pentru care ei și-au bătut joc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'Spune: „Umblați prin lume și vedeți care este urmarea pentru aceia care socotesc adevărul minciună.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, 'Spune: „Ale cui sunt cele din Ceruri și de pe Pământ?” Spune: „Ale lui Allah.” Și-a prescris Lui Însuși Îndurarea. Și vă va aduna în Ziua Învierii, despre care nu este nicio îndoială. Iar aceia care se vor pierde pe ei înșiși [în Acea Zi, sunt cei care] nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'Ale Lui sunt [toate] cele care sălășluiesc noaptea și ziua și El este Sami'' [Cel care Aude Totul] [și] ''Alim [Bine Știutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'Spune: „Oare să-mi iau eu alt aliat decât Allah, Creatorul Cerurilor și al Pământului? El este Cel care îi hrănește [pe toți] și căruia nu I se dă hrană”. Spune [o, Mohammed]: „Cu adevărat mi s-a poruncit să fiu primul [dintre voi] care primește Islamul!” Și să nu fii printre politeiști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, 'Spune: „Cu adevărat, mi-e frică - de nu mă voi supune Domnului meu – de chinul unei Zile Mari!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'Cel de la care va fi îndepărtată [pedeapsa] în Ziua Aceea - pe acela l-a iertat. Și aceasta este izbândă limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'De te va atinge Allah cu vreun rău, nimeni în afară de El nu-l va putea îndepărta. Iar de te va atinge cu ceva bun, El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'El este Al-Qahir [Stăpânul Suprem] peste robii Lui și El este Al-Hakim [Înțeleptul] [și] Al-Khabir [Bine Știutorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'Spune: „Cine este cu cea mai mare mărturie?” Spune: „Allah, este Martor între mine și între voi și mie mi-a fost revelat acest Coran, pentru ca să vă previn cu el pe voi și pe cei la care va ajunge[6]. Și oare voi mărturisiți că alături de Allah mai sunt și alți dumnezei?” Spune: „Nu mărturisesc [așa ceva]!” Spune: „Numai El [este Un Dumnezeu Unic] și eu nu recunosc asociații pe care îi faceți voi [lui Allah]”.', '[6] În fiecare timp și loc până în Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Cei cărora le-am dăruit Scriptura îl cunosc[7], întocmai cum își cunosc copiii, însă cei care și-au pierdut sufletele [în Viața de Apoi] [sunt] cei care nu cred.', '[7] Coranul. Este interpretat și ca „el” – profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Și cine este mai nelegiuit decât cel care născocește minciuni despre Allah sau nu acceptă Versetele Lui? Cu adevărat, cei nelegiuiți nu vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'Și [spune, o, Mohammed] în Ziua când Noi îi vom aduna pe toți; atunci le vom spune celor care I-au făcut asociați lui Allah: „Unde sunt asociații voștri pe care i-ați pretins?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Atunci nu vor avea alt răspuns decât să spună: „[Jurăm] pe Allah, Stăpânul nostru, noi nu am făcut niciodată asociați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Privește cum se mint pe ei înșiși și cum părăsesc ei ceea ce au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Printre ei sunt unii care ascultă la tine[8], însă Noi am pus acoperăminte peste inimile lor, pentru ca ei să nu-l priceapă, și surzenie în urechile lor. Chiar dacă ei văd fiecare semn, ei tot nu cred în el. Chiar dacă vin la tine ca să discute cu tine, cei necredincioși spun: „Acestea nu sunt decât povești ale celor de demult!”.', '[8] Atunci când reciți Coranul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Și ei îi opresc [pe oameni] de la el și se îndepărtează și ei înșiși de el. Dar ei nu se distrug decât pe ei înșiși, fără ca să-și dea seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'Și dacă i-ai vedea stând în fața Focului, spunând: „O, de ne-am întoarce noi [la viață], n-am mai socoti semnele Domnului nostru mincinoase și am fi în rândul celor credincioși!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Dar nu! Iată că li se arată ceea ce au ascuns mai înainte. Și dacă s-ar întoarce [la viața pământească], ar reveni neîndoielnic la cele ce le-au fost interzise, căci ei sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'Și ei spun: „Nu există [altă viață] decât viața noastră pământească și noi nu vom fi înviați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'Dar dacă i-ai vedea atunci când vor sta dinaintea Domnului lor și El le va spune: „Nu este acest lucru adevărat?” Ei vor răspunde: „Ba da, jurăm pe Domnul nostru!”. Iar El le va spune atunci: „Gustați chinul pentru că nu ați crezut!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Vor pierde cei care tăgăduiesc întâlnirea cu Allah. Iar când Ceasul le va veni în mod neașteptat, ei vor spune: „Vai de noi, pentru ceea ce am nesocotit cu privire la el [Ceasul]!” Și ei vor purta poverile [pentru păcatele] lor în spinările lor. Și ce poveri [grele] vor purta ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Această viață lumească nu este decât joacă și glumă, iar Lumea de Apoi va fi mai bună pentru cei cu frică. Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, '[O, Mohammed] Știm că te mâhnește ceea ce spun ei, însă ei nu te socotesc pe tine mincinos, ci nelegiuiții tăgăduiesc Versetele lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'Într-adevăr, au fost socotiți mincinoși [și alți] Trimiși de dinaintea ta, [o, Mohammed]! Însă ei au îndurat să fie socotiți mincinoși și să fie oropsiți, până când le-a venit Biruința Noastră. Și nu poate nimeni să schimbe Vorbele lui Allah [Decretele Lui] și ți-a venit deja ție o parte din veștile Trimișilor [anteriori].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Dacă nepăsarea lor ți se pare grea pentru tine și de-ai putea căuta un tunel în pământ sau o scară către Cer ca să le aduci o minune, [fă-o]! Iar dacă Allah ar Voi, i-ar aduna pe calea cea dreaptă! Deci nu fi dintre cei neștiutori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Doar cei care aud vor răspunde. Dar pe morți[9] Allah îi va învia. Apoi la El vor fi întorși.', '[9] Morți în ceea ce privește inima, adică cei necredincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, 'Și ei spun: „De ce nu a primit [Mohammed] o minune de la Domnul Său?” Spune: „Allah poate să trimită o minune, dar cei mai mulți dintre ei nu știu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Și nu este vietate pe pământ, nici pasăre care zboară cu aripile ei, decât în neamuri, ca și voi. Nu am lăsat nimic nepomenit în Carte[10]. Apoi, la Domnul lor vor fi adunați.', '[10] Tabla Păstrată - Al-Lauh al-Mahfudh – în care sunt înregistrate toate lucrurile');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'Dar cei care socotesc mincinoase Versetele Noastre sunt surzi și muți, în întunecimi. Pe cine Allah Voiește - îl duce în rătăcire și pe cine Voiește - îl duce pe drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'Spune: „Spuneți-mi: atunci când va veni la voi chinul lui Allah sau va veni la voi Ceasul - veți chema pe altcineva decât pe Allah, dacă voi spuneți adevărul?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Nu, doar pe El [Singurul] L-ați chema, iar El va risipi pricina rugii voastre, dacă El va Voi, iar voi veți uita ceea ce Îi asociați [Lui].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'Și Noi am trimis [Profeți] la popoare, înainte de tine, și le-am încercat cu nenorociri și suferințe, poate că ei se vor ruga [de îndurare]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'Atunci de ce, când le-a venit pedeapsa Noastră ei nu s-au rugat? Însă inimile lor s-au împietrit și Șeitan le-a împodobit ceea ce făceau ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'Când au uitat ei ceea ce li s-a amintit[11], Noi le-am deschis lor porțile tuturor lucrurilor. Iar când se bucurau ei de ceea ce li s-a dat, i-am apucat Noi deodată și iată-i pe ei deznădăjduiți.', '[11] Încercările prin sărăcie și greutate sau prevenirile Profeților lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'Astfel a fost stârpit neamul celor care au fost nelegiuiți. Laudă lui Allah, Domnul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'Spune [o, Mohammed]: „Spuneți-mi, dacă Allah v-ar lua auzul și văzul vostru și v-ar pecetlui inimile, care dumnezeu în afara lui Allah vi le-ar mai putea da înapoi? Privește cum tâlcuim Noi Versetele, dar ei se întorc apoi [de la ele]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'Spune: „Spuneți-mi: Ce credeți voi? Dacă ar veni peste voi pedeapsa lui Allah pe neașteptate sau pe față[12], ar fi pierduți [alții] decât neamul celor nelegiuiți?”', '[12] În fața ochilor lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Noi nu-i trimitem pe Trimiși decât ca vestitori de bine și prevenitori, iar cei care cred și [își] îndreaptă [faptele lor] nu se vor teme și nici nu vor fi mâhniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'Dar pe cei ce țin drept mincinoase semnele Noastre - îi va atinge[13] chinul, pentru că ei săvârșesc nelegiuiri.', '[13] Îi va ajunge');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'Spune [o, Mohammed]: „Eu nu vă spun că la mine se află Comorile lui Allah, nici că eu aș cunoaște necunoscutul și nici nu vă spun că eu aș fi Înger. Eu urmez doar ceea ce îmi este revelat”. Spune: „Este la fel orbul cu cel care vede? Voi nu vă gândiți [la aceasta]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'Și să-i previi cu el [Coranul] pe cei ce se tem că vor fi adunați la Domnul lor - ei nu au în afară de El nici ocrotitor, nici mijlocitor - poate că ei vor fi cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'Și nu-i alunga pe cei care Îl imploră pe Domnul lor, dimineața și seara, dorind Fața Sa [Mulțumirea Sa]. Nu-ți revine ție să le ții socoteală de nimic și nu le revine lor să-ți țină socoteală de nimic. Iar de-i vei alunga, vei fi dintre cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'Și astfel i-am încercat Noi pe unii prin alții, pentru ca [necredincioșii] să spună: „Aceștia sunt cei pe care Allah i-a binecuvântat cu Harul Său dintre noi?” Oare nu este Allah Cel care-i cunoaște cel mai bine pe cei mulțumitori?[14]', '[14] Cei la care se face referire în v. 52-54 sunt musulmanii săraci care au fost credincioși sinceri și discipolii Profetului (pacea și binecuvântarea lui Allah fie asupra sa). Liderii influenți din Quraiș i-au privit cu dispreț atunci când au stat cu ei, spunându-i profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa): „Poate dacă i-ai alunga, noi te-am urma.”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'Și când vin la tine, [o, Mohammed] cei care cred în Versetele Noastre, spune: „Pacea fie asupra voastră. Domnul vostru Și-a prescris Sieși Îndurarea: dacă unul dintre voi face un rău din ignoranță, iar apoi se căiește și îndreaptă fapta sa, [să știe că] El este Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Astfel lămurim Noi Versetele în amănunțime, pentru ca să se vadă limpede calea păcătoșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, 'Spune: „Cu adevărat, mie îmi este oprit să-i ador pe aceia cărora voi vă rugați în afară de Allah”. Spune: „Eu nu urmez poftele voastre, căci eu aș fi atunci rătăcit și nu aș mai fi printre cei bine călăuziți”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'Spune: „Cu adevărat, eu mă bizui numai pe dovadă limpede de la Domnul meu și voi ați luat aceasta de minciună”. Nu stă în puterea mea ceea ce voiți voi să vină mai degrabă. Hotărârea [în privința aceasta] este numai la Allah. El Spune adevărul și El este Cel mai Bun dintre judecători!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'Spune: „Dacă ar sta în puterea mea ceea ce voiți voi să se întâmple, ar fi fost hotărâtă treaba între mine și voi, dar Allah îi Cunoaște mai bine pe cei nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, 'Și la El sunt cheile necunoscutului și nu le știe decât El. Și El cunoaște ceea ce este pe uscat și ceea ce este pe mare. Nu cade nicio frunză fără ca El să o știe. Și nu există bob în întunecimile pământului, nimic proaspăt și nimic uscat, fără ca ele să fie [însemnate] într-o Carte Limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'El este Cel ce vă ia la Sine noaptea[15] și El Știe ceea ce voi ați dobândit peste zi. Apoi El vă readuce la viață în timpul ei, până se va împlini un termen hotărât[16]. Atunci la El va fi întoarcerea voastră și apoi vă Va Vesti El ceea ce ați făcut.', '[15] Atunci când dormiți
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'El este Al-Qahir [Stăpânul Suprem] peste robii Săi și El trimite asupra voastră Îngeri păzitori până când moartea îl ajunge pe unul dintre voi, [iar] Mesagerii noștri [Îngerii morții] îl iau, fără să neglijeze ceea ce li se poruncește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Apoi sunt aduși înapoi la Allah, Stăpânul lor adevărat. Fără îndoială la El este judecata și El este Cel mai grabnic dintre cei care cer socoteală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'Spune: „Cine vă salvează de întunecimile uscatului și ale mării când voi Îl invocați deschis și într-ascuns: „Dacă ne vei mântui de acestea, cu siguranță vom fi printre mulțumitori.”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'Spune: „Este Allah, Cel care vă salvează de acestea și de orice primejdie și totuși voi Îi faceți Lui asociați."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'Spune: „El este [Singurul] în stare să trimită chin asupra voastră, fie de deasupra voastră, fie de sub picioarele voastre, sau să vă deruteze [ca să vă împărțiți] în secte și să vă facă să gustați vătămare unii de la alții.” Privește cum tâlcuim Noi Versetele [și Semnele Noastre], poate că ei vor înțelege.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Însă neamul tău îl socotește mincinos, în vreme ce el este Adevărul. Spune: „Eu nu voi fi ocrotitor al vostru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'Fiecare profeție are un timp al său și [în curând] îl veți cunoaște.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Și de-i vei vedea pe cei care intră în discuții deșarte[17] asupra Versetelor Noastre, îndepărtează-te de ei, până ce ei vor începe o altă discuție! Iar dacă Șeitan te va face să uiți [aceasta], nu mai rămâne cu neamul de nelegiuiți, după amintire!', '[17] Iau în derâdere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Și celor care se tem [de Allah] nu li se va cere socoteală pentru nimic din ceea ce fac [necredincioșii], ci numai să li se aducă aminte; poate că ei vor avea frică de El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Lasă-i pe cei care socotesc religia lor joacă și zăbavă și pe care i-a ademenit viața lumească, dar amintește[-le] cu acesta [Coranul] că un suflet care se expune la pierzanie prin ceea ce a dobândit, nu va avea în afara lui Allah sprijinitor și nici mijlocitor și orice răscumpărare ar încerca să dea, nu i se va primi. Cei care se expun pierzaniei prin ceea ce au dobândit vor avea parte de băutură din apa clocotitoare și de pedeapsă dureroasă, pentru că nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'Spune: „Voiți să invocăm noi în locul lui Allah ceva care nici nu ne folosește, nici nu ne strică și să ne întoarcem pe călcâiele noastre după ce Allah ne-a călăuzit? [Atunci noi am fi] asemenea aceluia pe care șeitanii l-au ademenit și rătăcește pe pământ, confuz, cu toate că el are prieteni care-l cheamă la drumul cel drept, [spunându-i]: „Vino la noi!”[18] Spune: „Cu adevărat, călăuzirea lui Allah este [singura] Călăuzire! Și ni s-a poruncit să ne supunem Stăpânului lumilor!', '[18] Exemplul dat este cel al unuia care și-a pierdut calea și este în continuare derutat de cei răi care îl tentează să urmeze diferite direcții, ce duc toate către distrugere. Deși prietenii lui sinceri îl cheamă la calea cea dreaptă, el îi ignoră.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'Și împliniți Rugăciunea [As-Salat] și fiți cu frică de El”. Și El este Cel la care vă veți aduna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'Și El este Cel care a făcut Cerurile și Pământul întru adevăr. Și în Ziua când El spune „Fii”, [orice lucru] va fi. Cuvântul Său este Adevărul[19] și a Lui va fi Împărăția în Ziua când se va sufla în Trâmbiță. El este Știutorul celor nevăzute[20] și al celor văzute[21]! Și El este Al-Hakim [Înțeleptul] [și] Al-Khabir [Bine Știutorul]!', '[19] Atunci când este interpretat drept „Ceasul (Ziua)” (Învierii) mai departe va spune: „Și în Ziua când El spune „Fii”, [orice lucru] va fi, cuvântul Lui va fi adevărul”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, 'Și [spune, o, Mohammed] atunci când Avraam i-a spus lui ''Azar, tatăl său: „Tu iei idolii drept zei? Cu adevărat, eu te văd împreună cu neamul tău într-o rătăcire limpede!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Și așa i-am arătat Noi lui Avraam Împărăția Cerurilor și a Pământului, pentru ca el să fie dintre aceia care cred cu convingere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'Când noaptea l-a acoperit, el a văzut o Planetă și a spus: „Acesta este Domnul meu!”[22] Și când ea a asfințit, el a spus: „Eu nu-i iubesc pe cei care apun!”', '[22] Doar pentru a demonstra neamului său că ceea ce ei adoră nu le poate fi de niciun folos');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'Și când a văzut el Luna răsărind, a spus: „Acesta este Domnul meu.” Dar când a apus, el a spus: „Dacă Domnul meu nu mă călăuzește, voi fi din neamul celor rătăciți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'Și când a văzut el Soarele răsărind, a spus: „Acesta este Domnul meu! Acesta este mai mare!” Apoi, când a asfințit, el a spus: „O, neam al meu! Eu sunt nevinovat pentru tot ceea ce voi Îi asociați [lui Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Cu adevărat, eu îmi îndrept fața cu credință doar către Cel care a creat Cerurile și Pământul; și niciodată nu voi mai fi dintre cei care-I fac Lui asociați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'Iar poporul lui s-a certat cu el, însă el le-a spus: „Voi vă certați cu mine în privința lui Allah, când El m-a călăuzit? Eu nu mă tem de ceea ce-I alăturați voi, căci numai ce Voiește Domnul meu [se întâmplă]. Domnul meu cuprinde Totul cu Știința [Sa]. Dacă voi ați știi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'Și cum m-aș teme eu de ceea ce voi I-ați alăturat, când voi nu vă temeți să-I alăturați lui Allah [lucruri] pentru care El nu v-a trimis vouă nicio dovadă? Care dintre cele două tabere este mai îndreptățită la siguranță, dacă voi știți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'Cei care cred și nu amestecă credința lor cu nedreptatea sunt în siguranță și ei sunt bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'Aceasta este dovada pe care Noi i-am dat-o lui Avraam împotriva poporului său. Noi îi ridicăm cu trepte pe cei pe care Voim. Domnul Tău este Hakim [Înțelept], ‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'Și Noi i-am dăruit lui [Avraam] pe Isaac și pe Iacob – pe [toți] i-am călăuzit Noi. Și pe Noe l-am călăuzit Noi mai înainte și printre urmașii săi sunt David, Solomon, Iov, Iosif, Moise și Aaron. Astfel îi răsplătim Noi pe cei care fac bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'Și Zaharia, Ioan, Iisus și Elie - toți fiind printre cei dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, 'Și Ismail, Elisei, Iona și Lot - pe toți i-am ales Noi deasupra tuturor lumilor [semințiilor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'Și i-am ales Noi [pe unii] dintre părinții lor și dintre urmașii lor și dintre frații lor și i-am călăuzit Noi pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'Aceasta este Călăuzirea lui Allah, după care El călăuzește pe cine Voiește dintre robii Săi. Dar dacă ei i-ar fi alăturat Lui asociați, ar fi fost în deșert [tot] ceea ce ei au făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'Aceștia sunt cei cărora Noi le-am încredințat Scriptura, Înțelepciunea și Profeția. Dar dacă ei [necredincioșii] nu cred în ele, atunci le încredințăm Noi unui neam care nu se află printre tăgăduitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Pe aceștia i-a călăuzit Allah. Așadar, urmează îndrumarea lor. Spune: „Eu nu vă cer pentru aceasta răsplată. Aceasta nu este decât un îndemn pentru toate lumile.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Ei nu-L prețuiesc pe Allah la măsura Sa dreaptă[23] atunci când spun: „Allah nu a pogorât asupra oamenilor nimic.” Spune: „Cine a pogorât Cartea pe care Moise a adus-o ca lumină și îndrumare [călăuză] pentru oameni? Voi [evreilor] o faceți foi, arătându-le, dar și ascunzând multe [dintre ele]. Și voi [evreilor] ați fost învățați ceea ce n-ați știut nici voi și n-au știut nici părinții voștri”. Spune: „Allah [a trimis-o]!” Și apoi lasă-i să se joace în rătăcirea lor.', '[23] Ei nu au apreciat abilitatea și înțelepciunea lui Allah la nivelul corespunzător');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'Aceasta este o Carte Binecuvântată, pe care Noi am pogorât-o, și care întărește ceea ce exista deja înaintea ei, pentru ca tu să o previi pe Mama Cetăților [Mecca] și împrejurimile ei. Cei care cred în Ziua de Apoi, cred și în ea [în Carte] și ei păzesc cu stăruință Rugăciunea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Și cine este mai nelegiuit decât cel care născocește minciuni despre Allah sau care spune: „Mi s-a revelat mie”, când lui nu i-a fost revelat nimic, sau decât cel care spune: „Voi pogorî și eu ceva asemănător cu ceea ce a pogorât Allah”? Dar de i-ai vedea pe cei nelegiuiți în chinurile morții, în vreme ce Îngerii întind mâinile lor[24], [spunând]: „Lăsați să iasă sufletele voastre! Astăzi veți primi pedeapsa unei umiliri [extreme] pentru ceea ce ați spus despre Allah, în afara adevărului, și pentru că ați fost aroganți [față] de Versetele Lui!”', '[24] Lovindu-i deoarece aceștia nu vor să își dea sufletele pentru a fi judecate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, '[Le va fi spus] „Și acum ați venit la Noi, singuri, precum v-am creat pe voi la început, și ați lăsat în urma voastră tot ceea ce Noi v-am dăruit. Și nu-i vedem Noi, împreună cu voi, pe mijlocitorii voștri, despre care ați pretins că ar fi asociați [ai lui Allah]. Acum s-a tăiat orice legătură între voi[25] și v-au părăsit cei despre care ați pretins [că ar fi mijlocitorii voștri].', '[25] Între voi și asociații și mijlocitorii pretinși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Cu adevărat Allah este Cel care face să se crape semințele grânelor și curmalelor[26]. El dă viață la ceea ce este mort și face să moară ceea ce este viu. Acesta este Allah! Cum, atunci, vă lăsați abătuți [de la El]?', '[26] El le face să crape și să încolțească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, 'El face să se ivească zorile și a statornicit noaptea pentru odihnă și Soarele și Luna pentru socotirea [timpului]. Aceasta este hotărârea și rânduiala Celui Al-''Aziz [Puternic] [și] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'El este Cel care v-a făcut Stelele, pentru ca să vă călăuziți după ele în întunecimile uscatului și ale mării. Noi am tâlcuit semnele pentru oamenii care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'El este Cel care v-a creat dintr-un singur suflet și v-a dat loc de odihnă și loc de repaus. Noi am tâlcuit semnele pentru oamenii care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'El este Cel care a făcut să coboare apă din Cer și prin ea, Noi am făcut să încolțească toate plantele. Din ele am făcut să iasă verdeață, din care scoatem grăunțe, unele peste altele. Iar din curmali - din mlădițele lor - ciorchini deși ce atârnă. Și [am făcut] grădini de struguri, măslini și rodii, asemănătoare, dar diferite unele de altele. Priviți la fructele lor când rodesc, crescând când se coc. Cu adevărat, în aceasta sunt semne pentru oamenii care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'Dar i-au făcut asociați lui Allah - djinnii, în vreme ce El i-a creat pe ei - și I-au născocit Lui fii și fiice, fără știință. Mărire Lui! El este deasupra tuturor celor cu care ei Îl înfățișează!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, '[El este] Badi'' [Făcătorul Desăvârșit] al Cerurilor și al Pământului! Cum să aibă El un fiu, de vreme ce El nu a avut o soață? El le-a Creat pe toate și El pe toate le Știe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, 'Acesta este Allah, Domnul vostru! Nu există altă divinitate în afară de El, Cel care le-a făcut pe toate! Așadar, adorați-L pe El! Și El este peste toate Ocrotitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, 'Privirile nu-L ajung[27], însă El cuprinde toate privirile. El este Latif [Cel Blând] [și] Khabir [Bine Știutor]!', '[27] În această lume. Oamenii din Paradis vor putea să Îl vadă pe Allah în Viața de Apoi. A se vedea 75: 22-23');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'V-au venit vouă dovezi de la Domnul vostru. Cel ce le vede limpede o face pentru sufletul său, iar cel care rămâne orb [la ele] o face împotriva lui [sufletului său]. Și [spune] „Eu nu sunt păzitor peste voi.”[28]', '[28] Profetul (pacea și binecuvântarea lui Allah fie asupra sa) este instruit să se diferențieze de toate credințele și practicile greșite');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'Astfel Noi explicăm Versetele pentru ca ei [necredincioșii] să spună „Tu ai învățat!”[29], dar Noi îl vom tâlcui limpede [Coranul] pentru oamenii care știu.', '[29] Acuzându-l pe Profet (pacea și binecuvântarea lui Allah fie asupra sa) că ar fi învățat de la evrei și creștini');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Urmează [o, Mohammed] ceea ce ți-a fost revelat de către Domnul tău - nu există altă divinitate în afara de El - și nu-i lua în seamă pe cei care-I fac asociați [îndepărtându-te de ei]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Dar dacă Allah ar voi, ei nu I-ar face asociați. Însă Noi nu te-am făcut păzitor peste ei și tu nu ești nici chezaș pentru ei[30].', '[30] Datoria Profetului (pacea și binecuvântarea lui Allah fie asupra sa) se rezumă doar la a transmite mesajul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'Și nu-i insultați pe cei care sunt invocați afară de Allah, ca să nu-L insulte ei pe Allah, întru dușmănie și nepricepere. Astfel Noi am împodobit [în ochii] fiecărei comunități făptuirea sa. Apoi, la Domnul lor va fi întoarcerea lor și El le va vesti despre ceea ce au făptuit ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'Ei jură pe Allah cu toată puterea jurămintelor lor că, dacă le va veni vreo minune, ei vor crede cu siguranță în ea. Spune: „Minunile se află numai la Allah!” Si ce vă face pe voi să înțelegeți - [că și] dacă le-ar veni lor o minune, ei [tot] nu vor crede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'Și Noi le vom întoarce inimile și privirile lor, pentru că ei nu au crezut [în revelație] prima dată și Noi îi vom lăsa să rătăcească în nelegiuirea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Și chiar dacă Noi am fi pogorât la ei Îngerii [cu Mesajul] și chiar dacă le-ar fi vorbit morții și am fi adunat Noi dinaintea lor toate cele, ei tot nu ar fi crezut, doar dacă ar fi Voit Allah. Dar cei mai mulți dintre ei sunt neștiutori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'Astfel am făcut Noi pentru fiecare Profet dușmani - diavoli, dintre oameni și djinni, care să se ispitească unii pe alții cu vorbe împodobite, în chip înșelător. Însă dacă Domnul tău ar fi Voit, ei nu ar fi putut să o facă. Deci părăsește-i pe ei laolaltă cu ceea ce născocesc ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'Și astfel inimile celor care nu cred în Viața de Apoi se vor înclina [ascultând] către ea [vorbirea înșelătoare] și astfel vor fi mulțumiți de ea și vor îndeplini ceea ce ei săvârșesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, '[Spune] „Să caut eu alt judecător în afara lui Allah, când El este Cel care v-a trimis vouă Cartea [Coranul] explicată în detaliu? Cei cărora le-am dat Noi Scriptura știu că ea este pogorâtă de la Domnul tău cu Adevărul. Nu fi, așadar, dintre aceia care se îndoiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Cuvântul Domnului tău a fost plin de Adevăr și Dreptate. Nu este nimeni care să poată schimba Cuvintele Sale, iar El este As-Sami'' [Cel care Aude Totul] [și] Al-Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'De te-ai supune celor mai mulți de pe pământ, ei te-ar abate de la calea lui Allah. Ei nu urmează decât bănuielile [lor] și ei nu fac decât să născocească minciuni[31].', '[31] Din ignoranță, bănuieli și presupuneri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Cu adevărat, Domnul tău îi Știe cel mai bine pe cei care se abat de la Calea Lui și El este Cel care-i Știe cel mai bine și pe cei care urmează Calea cea Dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Așadar mâncați [numai] din cele peste care s-a pomenit Numele lui Allah[32], dacă voi credeți în Versetele Lui.', '[32] În momentul tăierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'Și de ce să nu mâncați din cele peste care s-a pomenit Numele lui Allah când El v-a explicat în detaliu ceea ce v-a interzis, cu excepția celor la care sunteți nevoiți[33]. Și cu adevărat, mulți se amăgesc prin poftele lor, fără știință. Cu siguranță, Domnul tău îi Știe cel mai bine pe cei nelegiuiți.', '[33] Ceea ce este în mod normal interzis devine permis în cazuri de maximă necesitate, însă doar pentru a satisface nevoile');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Și renunțați la păcatele evidente și la cele ascunse. Cu adevărat, cei care dobândesc [vina pentru] păcat vor primi răsplata pentru ceea ce au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Și nu mâncați din cele peste care nu s-a pomenit Numele lui Allah, căci aceasta este neascultare gravă. Și cu adevărat, șeitanii îi vor ispiti pe aliații lor [dintre oameni] să se certe cu voi. Dacă îi veți asculta, veți fi și voi politeiști.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Oare cel care a fost mort și pe care Noi l-am readus la viață și i-am dat lui lumină, după care se călăuzește, și umblă printre oameni poate să fie asemenea cu cel care se află în întuneric, de unde nu poate ieși? Așa le-a fost plăcut necredincioșilor ceea ce ei făceau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Și tot astfel am pus Noi în fiecare cetate pe cei mai mari făcători de rele să conspire, însă ei nu vor conspira decât împotriva lor înșiși, fără ca ei să-și dea seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'Și când vine la ei un semn, ei spun: „Nu vom crede noi până nu ni se va da ceva asemănător cu ceea ce le-a fost dat Trimișilor lui Allah.” Însă Allah știe mai bine cui trimite Mesajul Său. Pe cei care au săvârșit mari răutăți îi va lovi umilirea lui Allah și pedeapsă aspră pentru ceea ce ei au uneltit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Așadar dacă Allah Voiește să Călăuzească pe cineva, atunci El îi deschide pieptul pentru Islam, iar dacă Voiește să ducă pe cineva la rătăcire[34], atunci îi face pieptul îngust și închis, ca și cum s-ar căzni să se urce în Cer. Astfel trimite Allah osânda asupra acelora care nu cred.', '[34] Drept rezultat al aroganței unei persoane și al persistenței sale în păcat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Acesta este drumul drept al Domnului tău. Noi am detaliat Versetele pentru oamenii care își amintesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'Ei vor avea Casa Păcii [Paradisul] la Domnul lor. Și El este Ocrotitorul lor pentru ceea ce fac.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'Și [spune, o, Mohammed] de Ziua în care îi va aduna El pe toți, [și va spune]: „O, obște a djinnilor! Prea mult i-ați rătăcit pe oameni.” Iar aliații lor din rândul oamenilor vor spune: „O, Doamne! Noi am avut folos unii de la alții, dar noi am ajuns la sorocul pe care Tu ni l-ai hotărât nouă!” El va răspunde: „Focul este sălașul vostru și veșnic veți rămâne în el, numai dacă Allah va voi altfel, căci Domnul tău este Hakim [Înțelept], ''Alim [Atoateștiutor].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'Și astfel îi vom face Noi pe unii dintre nelegiuiți aliați ai altora, după cum și-au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, '„O, adunare a djinnilor și a oamenilor[35]! N-au venit la voi Trimiși, aleși dintre voi, care să vă vestească Versetele Mele și să vă prevină asupra întâlnirii cu această Zi a voastră?” Ei vor spune: „Noi facem mărturie împotriva noastră!” Și viața lumească i-a amăgit pe ei și ei au făcut mărturie împotriva lor înșiși precum că ei au fost într-adevăr necredincioși.', '[35] Li se va reproșa astfel în Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Aceasta pentru că Domnul tău nu ar fi distrus cetăți, cu nedreptate, dacă locuitorii lor nu ar fi fost preveniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'Pentru fiecare sunt trepte [diferite] după cele pe care le-a făcut, căci Domnului tău nu-I este necunoscut ceea ce ei fac.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Domnul tău nu are nevoie [de nimeni și de nimic] și este cu Îndurare. El dacă ar Voi, v-ar putea face să pieriți și ar lăsa în urma voastră ceea ce El ar Voi, tot așa cum v-a Creat și pe voi din urmașii altui popor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Cu adevărat, cele care vă sunt promise vor veni, iar voi nu le veți putea împiedica.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'Spune: „O, neam al meu! Faceți după putința voastră, căci și eu voi face [după putința mea]. Și veți afla voi cine va avea izbândă în Casă[36]. Cu adevărat, cei nelegiuiți nu vor izbândi niciodată.”', '[36] Pe pământ sau în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Și ei [politeiștii] I-au hotărât lui Allah o parte din recoltele și din dobitoacele pe care El le-a creat și au spus: „Aceasta este pentru Allah” - după pretenția lor - „iar aceasta este pentru asociații noștri!” Dar, ceea ce este pentru asociații lor, nu ajunge la Allah, pe când ceea ce este pentru Allah, ajunge la asociații lor. Și cât de prost au judecat ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Tot astfel i-au ademenit asociații lor pe mulți dintre idolatri să-și omoare copiii, ca să-i piardă și pe ei și ca să le întunece religia lor. Și de-ar fi Voit Allah, n-ar fi făcut ei aceasta. Deci lasă-i pe ei laolaltă cu ceea ce născocesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Și ei spun: „Aceste animale[37] și recolte sunt interzise. Nu mănâncă din ele decât cei care voim noi!” - după pretenția lor [mincinoasă] – [Și] sunt și acele [cămile] ale căror spinări au fost interzise [de ei][38] și cele peste care nu este spus Numele lui Allah[39] - născocind minciuni pe seama Lui[40]! El îi va răsplăti pentru ceea ce ei au născocit!', '[37] Cele patru categorii de animale domestice numite „anʿām”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Și ei spun: „Ceea ce se află în pântecul acestor animale este menit numai bărbaților noștri și le este interzis femeilor noastre. Dacă, însă, acesta [se naște] mort, atunci cu toții sunt părtași.” Însă Allah îi va pedepsi pentru cuvintele lor. Cu adevărat, El este Hakim [Înțelept], ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Vor fi pierduți cei care și-au omorât copiii, din nesăbuință și neștiință și care au interzis ceea ce Allah le-a dat pentru trai, născocind minciuni pe seama lui Allah! Ei sunt în rătăcire și nu au fost bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'El este Cel care face să crească grădini cu spalieri[41] și fără spalieri și curmali și culturi cu roade diverse, măslini și rodii, asemănătoare și diferite. Mâncați din roadele lor, când ele rodesc, și dați dreptul din ele [zakah] în ziua culesului și nu risipiți[42], căci El nu-i Iubește pe risipitori!', '[41] Suport pentru plante agățătoare
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'Și printre vite sunt unele pentru purtat [poveri] și altele [prea] mici. Mâncați din ceea ce v-a dat Allah pentru trai și nu urmați pașii lui Șeitan[43]. Cu adevărat, el vă este un dușman evident!', '[43] Așa cum au făcut necredincioșii prin faptul că și-au făcut propriile reguli cu privire la ceea ce este permis și ceea ce este interzis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, '[El a creat] opt suflete în perechi: două ovine și două caprine. Spune: „Pe cei doi masculi i-a oprit El sau pe cele două femele, sau ce este cuprins în pântecele celor două femele? Spuneți-mi mie cu știință, dacă voi sunteți sinceri?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'Și două cămile și două bovine. Spune: „Pe cei doi masculi i-a oprit El sau pe cele două femele, sau ce este cuprins în pântecele celor două femele? Sau ați fost voi, cumva, martori când v-a poruncit Allah aceasta? Și cine este mai nelegiuit decât acela care născocește minciuni și le pune pe seama lui Allah, pentru a-i rătăci pe oameni, în necunoștință? Cu adevărat, Allah nu-i călăuzește pe oamenii nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'Spune: „Eu nu găsesc în ceea ce mi-a fost revelat [nimic] interzis de a fi mâncat de către cel care mănâncă, decât dacă este mortăciune sau sânge care s-a scurs sau carne de porc – aceasta fiind murdărie - sau ceva pângărit, peste care s-a rostit numele altcuiva decât al lui Allah. Iar dacă cineva a fost constrâns, fără dorință și fără a trece limitele, Domnul tău este Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'Iar evreilor Noi le-am oprit toate animalele cu o unghie, iar de la bovine și ovine Noi le-am oprit lor grăsimile, în afară de ceea ce poartă pe spatele lor sau este în măruntaie sau ceea ce se amestecă cu oasele. Astfel i-am pedepsit Noi pentru fărădelegea lor și Noi spunem numai Adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'Iar dacă te învinuiesc de minciună, atunci spune-le [o, Mohammed]: „Domnul vostru este cu Nemărginită Îndurare, însă Pedeapsa Sa nu va putea fi respinsă de la neamul de nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Cei care Îi fac asociați lui Allah vor spune: „De ar fi Voit Allah, nu I-am fi făcut asociați nici noi, nici părinții noștri și nici nu am fi oprit nimic.” Tot astfel i-au învinuit și cei de dinaintea lor de minciună [pe Profeți], până ce au gustat pedeapsa Noastră. Spune: „Aveți voi vreo știre pe care să ne-o arătați? Voi nu urmați decât bănuieli și voi nu faceți decât să mințiți!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'Spune: „Numai la Allah se află dovada convingătoare! Iar dacă El ar fi Voit, v-ar fi Călăuzit pe voi toți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'Spune [o, Mohammed]: „Aduceți-i pe martorii voștri care pot întări că Allah le-a oprit pe acestea.” Iar dacă ei fac mărturie, tu să nu mărturisești împreună cu ei și să nu urmezi poftele celor care socotesc Versetele Noastre mincinoase și ale celor care nu cred în Ziua de Apoi și fac parteneri Domnului lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'Spune: „Veniți să vă recit ceea ce Domnul vostru v-a oprit. [El poruncește]: Să nu-I asociați Lui nimic, să fiți buni cu părinții, să nu vă omorâți copiii de teama sărăciei. Noi vă vom da cele de trai atât vouă cât și lor. Și să nu vă apropiați de cele rușinoase, nici cele care se văd, nici cele care sunt ascunse. Nu ucideți sufletul pe care l-a oprit Allah, decât pe drept. Acestea vi le-a poruncit [Allah]; poate că voi veți pricepe.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'Și să nu vă apropiați de averea orfanului, decât cu ceea ce ați putea s-o faceți și mai bună, până când el nu ajunge la maturitate. Și împliniți măsurarea și cântărirea cu dreptate. Noi nu impunem unui suflet decât atât cât poate el. Iar când spuneți [ceva][44], fiți drepți, chiar dacă este vorba de o rudă apropiată și țineți-vă legământul față de Allah. Acestea vi le-a poruncit [Allah], poate că voi vă aduceți aminte.', '[44] Mărturisiți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'Și [mai mult] acesta este drumul Meu drept! Deci urmați-l și nu urmați căile care vă abat de la drumul Lui. Acestea vi le-a poruncit El; poate că veți fi cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Apoi, Noi i-am dat lui Moise Scriptura, împlinind binecuvântarea, ca răsplată pentru cel care a făcut bine [Moise], ca o înfățișare amănunțită a tuturor lucrurilor, drept călăuză și îndurare. Poate că ei vor crede în întâlnirea cu Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'Iar acesta [Coranul] este o Carte Binecuvântată pe care Noi am pogorât-o. Urmați-o și temeți-vă! Poate că vi se va arăta îndurare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, '[Am pogorât-o] pentru ca voi să nu spuneți: „ Cartea [Tora și Evanghelia] a fost pogorâtă doar pentru două popoare, înaintea noastră, dar noi am rămas nepăsători față de studiul lor,”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'Sau să nu spuneți: „Dacă ne-ar fi fost trimisă nouă Cartea, noi am fi fost, neîndoielnic, mai bine călăuziți decât ei.” Și iată că de la Domnul vostru v-a venit vouă Dovadă limpede, Călăuzire și Îndurare. Și cine este mai nelegiuit decât acela care ia Versetele lui Allah drept minciuni și se abate de la ele? Noi îi vom răsplăti pe cei care se îndepărtează de la Versetele Noastre cu pedeapsă grea, pentru că ei abat [și pe alții de la ele].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'Oare așteaptă ei altceva decât să vină Îngerii la ei sau să vină Domnul tău sau să le vină unele semne de la Domnul tău? În ziua când vor veni unele semne de la Domnul tău, nu-i va mai fi de folos niciunui suflet credința sa dacă el nu a crezut mai înainte sau dacă nu a dobândit nimic bun prin credința sa. Spune: „Așteptați.” Cu adevărat, și noi așteptăm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Cu adevărat, tu [Mohammed] nu ești răspunzător cu nimic pentru cei care și-au fărâmițat religia lor în secte. Soarta lor depinde numai de Allah. Și apoi El le va vesti ceea ce au făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Cel care va veni [în Ziua Judecății] cu o faptă bună va avea parte de zece asemenea ei, iar cel care va veni cu o faptă rea nu va fi răsplătit decât cu o faptă pe măsura ei. Dar nu li se va face nicio nedreptate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'Spune: „Într-adevăr, Domnul meu m-a călăuzit pe un drum drept - o Religie adevărată - Religia lui Avraam cel drept întru credință, care nu a fost printre cei care au făcut asociați [lui Allah]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'Spune: „Într-adevăr, Rugăciunea mea, actele mele de devoțiune, viața mea și moartea mea îi aparțin lui Allah, Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'El nu are niciun asociat! Astfel mi s-a poruncit și eu sunt primul dintre musulmani.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'Spune: „Să caut eu un alt Domn în afară de Allah, când El este Stăpân peste toate? Niciun suflet nu va agonisi decât împotriva sa. Și niciun [suflet] purtător de poveri nu va purta povara altuia. Și apoi la Domnul vostru se află întoarcerea voastră și El vă va Vesti despre cele asupra cărora ați fost cu păreri diferite.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'El este Cel care v-a făcut pe voi urmași pe pământ și v-a ridicat pe unii dintre voi deasupra altora, în trepte, pentru a vă încerca întru ceea ce v-a dat. Cu adevărat Domnul tău este repede la pedeapsă, însă El este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Alif, Lam, Mim, Sad[1].', '[1] A se vedea nota de subsol 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, '[Aceasta este] o Carte revelată ție [o, Mohammed] - și să nu fie în inima ta nicio neliniște din pricina ei - pentru ca tu să previi prin ea și drept un îndemn pentru dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Urmați [o, oameni,] ceea ce vi s-a trimis de la Domnul vostru și nu urmați alți aliați în afară de El! Dar voi numai puțin vă aduceți aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Câte cetăți am nimicit Noi și pedeapsa Noastră le-a lovit în timpul nopții sau pe când ei dormeau, la vremea prânzului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'Și când pedeapsa Noastră i-a lovit, strigătul lor a fost doar acesta: „Cu adevărat, noi am fost nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'Atunci îi vom întreba Noi pe cei cărora li s-a trimis [Mesajul], dar îi vom întreba Noi și pe cei trimiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'Atunci le vom povesti Noi [faptele lor] cu deplină cunoștință, căci Noi nu am fost [niciodată] absenți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'Și cântărirea [faptelor] în Ziua aceea va fi dreaptă, iar cei ale căror talere vor atârna mai greu - vor fi cu izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'Iar cei ale căror talere vor fi ușoare - ei sunt cei care își vor pierde sufletele, căci ei au fost nedrepți față de Versetele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Noi v-am dat vouă putere pe acest pământ și v-am dat pe el cele de trebuință pentru trai, dar numai puțini dintre voi aduceți mulțumire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Noi v-am creat [o, oamenilor] și v-am dat chip și le-am spus apoi Îngerilor: „Prosternați-vă înaintea lui Adam!” Și s-au prosternat ei, cu excepția lui Iblis[2], care nu a fost printre cei care s-au prosternat.', '[2] Satana, a se vedea nota 2:34');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, '[Allah] a spus: „Ce te-a oprit să te prosternezi, când ți-am poruncit?” [Iblis] a răspuns: „Eu sunt mai bun decât el! Pe mine m-ai făcut din foc, iar pe el l-ai făcut din lut.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, '[Allah] a spus: „Coboară de aici [din Rai], pentru că aici nu e loc de aroganța ta! Deci ieși afară și tu vei fi dintre cei vrednici de dispreț”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, '[Iblis] a spus: „Dă-mi un răgaz până în Ziua când vor fi înviați [din morți]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, '[Allah] a spus: „Cu adevărat, vei fi dintre aceia cărora li se va da păsuire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, '[Iblis] a spus: „Pentru că M-ai dus în rătăcire, îi voi pândi pe ei pe drumul Tău cel drept,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'Și îi voi împresura în valuri, din față și din spatele lor, de la dreapta și de la stânga lor, și nu-i vei afla pe cei mai mulți dintre ei mulțumitori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, '[Allah] a spus: „Ieși de aici [din Rai], disprețuit și alungat! Cât despre cei dintre ei care te vor urma, voi umple Iadul cu voi toți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, 'Și tu, o, Adam! Sălășluiește împreună cu soția ta în Rai și mâncați voi ori de unde voiți, însă nu vă apropiați de acest pom, căci altfel veți fi dintre cei nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'Dar Șeitan i-a ispitit, voind să le arate goliciunile care le fuseseră ascunse, spunând: „Domnul vostru nu v-a oprit de la acest pom decât pentru ca voi să nu deveniți Îngeri și să nu fiți nemuritori!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, 'Și el a jurat [pe Allah]: „Cu adevărat, eu sunt pentru voi un sfătuitor sincer”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'Așadar, el i-a înșelat prin amăgire. Și când ei au gustat din acel pom, părțile intime le-au devenit vizibile și au început să-și pună peste ele frunze din Rai. Și Domnul lor i-a chemat: „Oare nu v-am oprit Eu de la acest pom și nu v-am spus că Șeitan vă este vouă un dușman evident?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, 'Ei au răspuns: „Doamne, am fost nedrepți cu sufletele noastre și dacă nu ne ierți și nu Te înduri de noi, vom fi printre cei pierduți”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, '[Allah] a spus: „Coborâți! Vă veți fi dușmani unul altuia. Și pe pământ veți avea sălaș și plăcere până la un timp.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, 'Apoi [a mai] spus: „Pe el veți trăi, pe el veți muri și din el veți fi voi scoși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'O, fii ai lui Adam, Noi v-am dat vouă îmbrăcăminte care să vă acopere goliciunile și ca și podoabe. Dar veșmântul smereniei este cel mai bun. Acesta este [unul] dintre semnele lui Allah; poate că ei își vor aminti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'O, fii ai lui Adam, să nu vă amăgească Șeitan, așa cum i-a scos pe părinții voștri din Rai, dezbrăcându-i de veșmintele lor[3], pentru ca să le arate goliciunile lor. Cu adevărat, el [Iblis] vă vede - el și oștenii lui - în vreme ce voi nu-i vedeți. Cu adevărat, Noi i-am pus pe șeitani aliați pentru aceia care nu cred,', '[3] Veșmintele Raiului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'Iar atunci când aceștia săvârșesc o fărădelege, ei spun: „Noi am aflat-o la strămoșii noștri și Allah ne-a poruncit-o.” Spune: „Cu adevărat, Allah nu poruncește nelegiuirea. Voi spuneți despre Allah, ceea ce voi nu știți?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'Spune [o, Mohammed]: „Domnul meu a poruncit dreptatea și să vă întoarceți fețele [către Qiblah] în fiecare loc [sau timp] de prosternare [Rugăciune] și să Îl invocați pe El cu credință adevărată în Religie.” Așa cum v-a creat El, așa vă veți întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'El a călăuzit o parte [dintre voi], în vreme ce o parte a meritat să o lase să rătăcească. Cu adevărat ei i-au luat [mai târziu] pe șeitani drept aliați în locul lui Allah, crezând că sunt bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'O, fii ai lui Adam, luați-vă veșmintele [curate și care vă acoperă goliciunea voastră] la toate locurile de Rugăciune, mâncați și beți, însă nu întreceți măsura. Cu adevărat, El nu-i iubește pe cei care întrec măsura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, 'Spune: „Cine a oprit podoaba [de la] Allah, pe care El a făcut-o pentru robii Săi și bunătățile [permise] necesare pentru viețuire?” Spune: „Ele sunt pentru cei care cred, în viața lumească [și] numai pentru ei în Ziua Învierii.” Astfel facem Noi Versetele Noastre limpezi pentru niște oameni care știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'Spune: „Domnul meu a oprit nelegiuirile - atât pe cele văzute cât și pe cele nevăzute - precum și păcatul[4], nedreptățirea [altora] și să-i faceți lui Allah asociați, de vreme ce El nu a trimis o astfel de poruncă, sau să spuneți despre Allah ceea ce nu știți.”', '[4] Orice faptă nepermisă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Pentru fiecare comunitate este un timp [specific]. Când sosește timpul lor, ele nu pot nici să-l întârzie cu un ceas și nici nu-l pot grăbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'O, fii ai lui Adam, de vă vor veni Trimiși [aleși] chiar dintre voi relatându-vă Versetele Mele [Scripturile și Legile], atunci cine are frică de Allah și se îndreaptă - nu va avea a se teme și nici nu va fi el mâhnit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'Însă cei care iau Versetele Noastre drept mincinoase și sunt aroganți față de ele, vor fi oaspeții Focului și ei vor rămâne veșnic în el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Și cine este mai nelegiuit decât cel care născocește minciuni despre Allah sau ia Versetele Lui drept minciuni? Aceștia vor avea partea lor, care le-a fost prescrisă, până ce vor veni la ei Trimișii Noștri [Îngerii] pentru a le lua sufletele. Ei vor zice: „Unde este ceea ce voi ați chemat în afara lui Allah?” Și ei vor răspunde: „Ei ne-au părăsit pe noi.” și ei vor mărturisi împotriva sufletelor lor că ei sunt necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, '[Allah] va spune: „Intrați în Foc printre djinnii și oamenii din comunitățile care au fost mai înainte de voi!”. Și de fiecare dată când va intra o comunitate, o va blestema pe sora ei[5], până când toate vor ajunge acolo, iar ultima dintre ele va spune despre prima: „Doamne, aceștia ne-au dus pe noi în rătăcire, deci dă-le lor pedeapsă dublă în Foc!”. El va zice atunci: „Pentru fiecare va fi [pedeapsa] dublată, însă voi nu știți!”', '[5] Comunitatea precedentă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'Iar cea dintâi îi va spune celei din urmă: „Dar voi nu aveți niciun merit în plus față de noi! Așadar, gustați chinul pentru ceea ce ați agonisit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Cu adevărat, pentru cei care iau Versetele Noastre drept mincinoase și sunt aroganți față de ele, Porțile Cerului nu li se vor deschide lor și nu vor intra ei în Rai decât atunci când va intra cămila prin urechile acului. Astfel îi răsplătim Noi pe marii păcătoși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'În Iad ei vor avea sălaș, iar deasupra lor [vor fi] acoperăminte [de foc]. Astfel îi răsplătim Noi pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'Dar cei care cred și împlinesc fapte bune - Noi nu impunem niciunui suflet o povară peste puterile lui, iar aceștia vor fi oaspeții Raiului și ei în el vor sălășlui veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'Și Noi vom îndepărta din piepturile lor toată pizma[6] și pe sub ei vor curge râuri. Și ei vor spune: „Laudă lui Allah care ne-a călăuzit spre acestea și noi nu am fi fost călăuziți dacă Allah nu ne-ar fi călăuzit. Cu siguranță Trimișii Domnului nostru au venit cu Adevărul.” Și către ei se va striga: „Acesta este Raiul [pentru voi]! Ați fost făcuți sălășluitorii lui pentru ceea ce ați făptuit".', '[6] Un sentiment de vătămare pentru cele de care a avut parte în viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'Și vor striga atunci oaspeții Raiului către oaspeții Iadului: „Noi am găsit cu adevărat ceea ce Domnul nostru ne-a făgăduit. Voi ați găsit cu adevărat ceea ce Domnul vostru v-a făgăduit?” Ei vor răspunde: „Da.” Apoi un crainic va vesti printre ei: „Blestemul lui Allah se abate asupra nelegiuiților,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, 'Care [îi] opresc [pe oameni] de la drumul lui Allah și caută să-l facă strâmb și nu cred în Viața de Apoi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Iar între cele două [tabere] va fi un zid, iar pe crestele zidului [Al-''A''raf] se vor afla oamenii[7] care-i cunosc pe cei din fiecare tabără după trăsăturile lor[8]. Și vor striga ei către oaspeții Raiului, spunând: „Pace asupra voastră!” Ei nu au intrat în el, dar ei doresc [să intre].', '[7] Ale căror cântare sunt balansate între fapte bune și fapte rele
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Iar când privirile lor vor fi întoarse către oaspeții Iadului, ei vor spune: „Doamne, nu ne așeza pe noi împreună cu cei nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'Și vor striga cei care stau pe crestele zidului [Al-''A''raf] către unii oameni [din Iad] pe care îi cunosc după trăsăturile lor, spunând: „Nefolositor este ceea ce voi ați adunat[9], ca și faptul că ați fost aroganți”', '[9] Avere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, '[Allah va spune]: „Aceștia sunt cei despre care ați jurat că Allah nu le va dărui îndurare? Intrați în Rai [cei care stați pe crestele zidului] fără a vă teme și nu veți avea de ce să vă întristați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'Și oaspeții Iadului vor striga către oaspeții Raiului: „Vărsați și asupra noastră apă sau altceva din ceea ce v-a dăruit Allah!” Însă ei vor răspunde: „Cu adevărat, Allah le-a oprit pentru necredincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, 'Care au luat Religia în derâdere și în joacă și pe care i-a amăgit viața lumească.” Astăzi, Noi îi uităm așa cum ei au uitat întâlnirea cu această Zi a lor și pentru că au respins Versetele Noastre!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'Și Noi le-am adus cu siguranță o Carte pe care am deslușit-o, în deplină cunoștință, drept călăuză și îndrumare pentru un neam [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Oare așteaptă ei altceva decât împlinirea ei? În Ziua când va veni împlinirea ei, cei care mai înainte au uitat-o vor spune: „Trimișii Domnului nostru au venit cu Adevărul și vom avea noi [acum] mijlocitori care să intervină pentru noi? Sau vom putea noi să fim readuși [pe pământ], pentru ca să împlinim alte [fapte] decât cele pe care le-am săvârșit?” Ei și-au pierdut, neîndoielnic, sufletele și i-au părăsit pe ei cele pe care le-au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'Cu adevărat, Domnul vostru este Allah, Cel care a creat Cerurile și Pământul în șase zile, iar apoi S-a înălțat deasupra Tronului. El face ca noaptea să învăluie ziua, urmându-i [altă noapte] degrabă. [El a creat] Soarele, Luna și Stelele supuse Poruncii Sale. Și nu este decât a Lui Înfăptuirea și Poruncirea. Binecuvântat este Allah, Domnul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Chemați-L pe Domnul vostru cu umilință și într-ascuns. El nu-i iubește pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'Nu faceți stricăciune pe pământ, după buna lui întocmire. Și chemați-L pe El întru frică și speranță, căci Îndurarea lui Allah este aproape de cei care săvârșesc bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'El este Cel care trimite vânturile ca vestire a Îndurării Sale. Apoi, după ce ele ridică Nori grei de ploaie, Noi îi trimitem spre un tărâm mort și pogorâm peste el apa și scoatem prin ea tot felul de roade. Astfel îi vom scoate Noi și pe morți; poate că veți lua aminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'Și din tărâmul cel bun cresc plante, cu Voia lui Allah, pe când din tărâmul cel rău nu cresc decât cu greu și neîndestulătoare. Astfel tâlcuim Noi semnele pentru oamenii care aduc mulțumire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Noi l-am trimis pe Noe la poporul său, căruia i-a spus: „O, popor al meu! Adorați-L pe Allah! Voi nu aveți altă divinitate în afara Lui. Cu adevărat, eu mă tem pentru voi de chinul unei Zile cumplite.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Dar căpeteniile poporului său au răspuns: „Noi te vedem pe tine într-o rătăcire clară.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, '[Noe] le-a răspuns: „O, popor al meu! Eu nu sunt în rătăcire, ci eu sunt un Trimis de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'Eu vă vestesc Mesajele Stăpânului meu și vă povățuiesc, căci eu știu de la Allah ceea ce voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'Oare vă mirați voi că v-a venit o îndemnare de la Domnul vostru printr-un om dintre voi, pentru ca să vă prevină, ca voi să fiți cu frică, în nădejdea că voi veți avea parte de îndurare?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Dar ei l-au socotit mincinos, astfel că Noi l-am salvat pe el și pe cei care au fost cu el în corabie și i-am înecat pe cei care au negat semnele Noastre. Cu adevărat, ei au fost orbi[10].', '[10] Pentru mai multe detalii a se vedea 11:25-48');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'Și [poporului] ’Ad [li l-am trimis] pe fratele lor Hud. El le-a spus: „O, neam al meu! Adorați-L pe Allah! Voi nu aveți altă divinitate în afara Lui! Și oare nu vă temeți voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Dar cârmuitorii poporului său, care nu credeau, au spus: „Cu adevărat, noi te vedem pe tine în ignoranță și te socotim pe tine dintre cei mincinoși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, '[Hud] a spus: „O, popor al meu, în mine nu este pic de ignoranță, ci eu sunt un Trimis de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'Eu vă vestesc Mesajele Domnului meu și eu sunt pentru voi sfătuitor credincios.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'Oare vă mirați că îndemnul vă vine de la Domnul vostru printr-un om dintre voi pentru a vă preveni? Aduceți-vă aminte când El v-a făcut urmașii poporului lui Noe și v-a făcut mai mari la înfățișare decât pe ei[11]. Și aduceți-vă aminte de Binefacerile lui Allah; poate că voi o să izbândiți.”', '[11] Mai înalți și mai puternici');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'Ei au spus: „Ai venit la noi pentru ca noi să-L adorăm [numai] pe Allah singur și să părăsim ceea ce au adorat părinții noștri? Atunci adu asupra noastră ceea ce ne promiți[12], dacă tu ești dintre cei ce spun adevărul.”', '[12] Pedeapsa lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, '[Hud] a spus: „Pedeapsa și mânia Domnului vostru v-a ajuns deja. Vă certați cu mine pentru niște nume pe care voi și părinții voștri le-ați dat[13] și despre care Allah nu a pogorât nicio dovadă? Atunci așteptați! Cu adevărat eu voi fi împreună cu voi printre cei care așteaptă.”', '[13] Obiecte false de adorare pe care voi îi numiți „Dumnezei”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Și Noi l-am salvat pe el și pe cei care au fost alături de el, prin Mila Noastră, și i-am stârpit pe aceia care au negat Semnele Noastre și nu au fost credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, 'Și [poporului] lui Thamud [i l-am trimis] pe fratele lor Salih, [care] le-a spus: „O, popor al meu, adorați-L pe Allah! Voi nu aveți altă divinitate în afara Lui! Iată că aveți dovada limpede de la Domnul vostru. Aceasta este cămila de la Allah, dăruită vouă drept semn. Lăsați-o să pască pe pământul lui Allah și nu o atingeți cu niciun rău, ca să nu vă ajungă un chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, 'Și aduceți-vă aminte că El v-a făcut urmașii [neamului] ’Ad și v-a dat sălaș pe acest pământ, pentru ca să vă înălțați palate în șesurile lui și să vă săpați case în munți. Aduceți-vă aminte de Binefacerile lui Allah și nu faceți rău pe acest pământ, aducând stricăciune.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'Dar căpeteniile îngâmfate ale poporului său le-au spus celor care erau asupriți - care credeau dintre ei: „Știți voi de bună seamă că Salih este trimis de Domnul său?” Ei le-au răspuns: „Cu adevărat, noi credem în cele cu care a fost trimis.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, 'Dar cei aroganți au spus: „Cu adevărat, noi nu credem în ceea ce credeți voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'Și au ologit cămila [și au înjunghiat-o] și au încălcat Porunca Domnului lor, spunând: „O, Salih, adu asupra noastră cele ce ne promiți, dacă tu ești dintre Trimiși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'Atunci i-a lovit pe ei cutremurul și dimineața i-a găsit zăcând întinși în casele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, 'Iar el [Salih] s-a întors de la ei, spunând: „O, popor al meu, eu v-am vestit Mesajul Domnului meu și v-am povățuit de bine, însă voi nu-i iubiți pe povățuitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'Și [l-a trimis] pe Lot când i-a spus poporului său: „Faceți voi o asemenea imoralitate pe care nimeni, din toate lumile, nu a mai cunoscut-o înainte de voi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Voi mergeți la bărbați, în locul femeilor. Cu adevărat, voi sunteți un popor de desfrânați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'Și poporul său nu a avut alt răspuns decât că a spus: „Dați-i afară din cetatea voastră! Cu adevărat, ei sunt oameni care vor să se țină neprihăniți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'Și Noi l-am salvat pe el împreună cu familia lui, cu excepția soției sale, care a fost printre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'Și Noi am lăsat să cadă peste ei ploaie [de pietre]. Deci privește care a fost sfârșitul nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, 'Și [poporului] lui Madyan [I l-am trimis] pe fratele lor Șuayb, care le-a spus: „O, popor al meu, adorați-L pe Allah! Voi nu aveți altă divinitate în afara Lui! Iată că v-a venit o dovadă limpede [pentru aceasta] de la Domnul vostru! Deci, dați măsură și greutate dreaptă și nu dați oamenilor mai puțin din lucrurile [care li se cuvin] lor! Și nu faceți stricăciune pe pământ, după buna lui întocmire. Aceasta este mai bine pentru voi, dacă sunteți credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'Și nu vă așezați în fiecare drum, ca să amenințați și să-l împiedicați de la calea lui Allah pe cel care crede în El și să cercați să o faceți strâmbă! Aduceți-vă aminte că voi ați fost puțini și că El v-a înmulțit! Și priviți cum a fost sfârșitul făcătorilor de stricăciune!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'Și dacă o parte dintre voi crede în [Mesajul] cel cu care eu am fost trimis, dar o altă parte nu crede, atunci aveți răbdare până ce Allah va judeca între noi. Și El este Cel mai Bun dintre judecători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Dar au spus căpeteniile arogante din poporul lui: „Te vom alunga, o Șuayb, pe tine și pe cei care cred împreună cu tine afară din cetatea noastră, dacă nu vă întoarceți la religia noastră.” Însă el le-a răspuns: „Chiar dacă nu voim să o facem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, 'Am născoci minciuni împotriva lui Allah, dacă ne-am întoarce la religia voastră după ce Allah ne-a mântuit de ea. Și noi nu trebuie să ne întoarcem la ea decât dacă Voiește Allah, Domnul nostru [să ne ducă în rătăcire]! Însă Domnul nostru Cuprinde toate lucrurile cu Știința Sa. Noi în Allah ne încredem! Doamne, Judecă între noi și între poporul nostru întru dreptate, căci Tu ești Cel mai Bun dintre judecători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'Au spus atunci căpeteniile care nu credeau din poporul lui: „Dacă-l urmați pe Șuayb, atunci [să știți că] voi sunteți pierduți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'Și i-a lovit cutremurul și dimineața i-a găsit zăcând întinși în casele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Cei care l-au socotit pe Șuayb mincinos au fost ca și când n-ar fi locuit niciodată în ele. Cei care l-au socotit pe Șuayb mincinos, aceia au fost pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, '[Șuayb] s-a întors de la ei și le-a spus: „O, popor al meu! Cu siguranță eu v-am vestit Mesajele Domnului meu și v-am sfătuit pe voi. Cum să mă întristez eu pentru un popor de necredincioși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'Și Noi nu am trimis niciun Profet într-o cetate [care a fost negat] fără să nu fi lovit poporul ei cu nenorocire și stricăciune, pentru ca ei să se roage [pentru iertare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'Apoi am schimbat răul cu bine, astfel încât ei au crescut în număr și în bogăție și au spus: „I-au atins și pe părinții noștri nenorocirea și îndestularea[14].” Atunci i-am luat Noi pe neașteptate, fără ca ei să-și dea seama[15].', '[14] În loc să Îi fie mulțumitori lui Allah pentru binecuvântările Sale, ei le-au atribuit schimbării norocului
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'Dacă popoarele acestor cetăți ar fi crezut și ar fi avut frică, atunci Noi le-am fi dăruit binecuvântări din Cer și de pe Pământ, dar ei i-au socotit mincinoși [pe Mesageri] și din această cauză Noi i-am apucat pentru ceea ce au agonisit[16].', '[16] Drept vină pentru păcatele lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'Oare locuitorii cetăților erau siguri că nu va veni peste ei pedeapsa Noastră, în timpul nopții, pe când ei dormeau?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Sau oare locuitorii cetăților erau siguri că nu va veni peste ei pedeapsa Noastră în plină zi, pe când ei se veseleau?[17]', '[17] Erau ocupați cu activități ce nu le aduceau niciun beneficiu');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Oare se credeau ei la adăpost de Planul lui Allah? Dar nu se poate socoti la adăpost de Planul lui Allah decât neamul celor pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Nu le-a fost limpede celor care au moștenit pământul de la cei de dinainte, că Noi, dacă voim, putem să-i pedepsim pentru păcatele lor și să le pecetluim inimile, ca ei să nu mai audă nimic?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'Iată aceste cetăți, ale căror istorii ți le povestim [o, Mohammed]. Cu siguranță Trimișii lor au venit la ei cu semne limpezi, însă ei nu au voit să creadă în ceea ce nu au acceptat mai înainte[18]. Așa pecetluiește Allah inimile necredincioșilor.', '[18] Ei au negat în mod insistent fiecare avertizare primită');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'Noi nu i-am găsit pe cei mai mulți dintre ei ținând un legământ[19], ci pe cei mai mulți dintre ei i-am aflat ca fiind sfidător de neascultători.', '[19] Nu erau credincioși legământului lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Apoi, Noi l-am trimis după ei pe Moise cu semnele Noastre la Faraon și la dregătorii lui, însă ei s-au arătat nedrepți față de ele[20]. Privește, așadar, cum a fost sfârșitul făcătorilor de stricăciuni.', '[20] Ei au respins și s-au opus semnelor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'Și a spus Moise: „O, Faraon! Eu sunt un Trimis de la Stăpânului lumilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, 'Într-adevăr eu nu spun nimic despre Allah decât adevărul. Am venit la voi cu Dovadă Limpede de la Domnul vostru, deci trimite cu mine pe Fiii lui Israel.”[21]', '[21] Eliberează-i de la asuprire și permite-le să emigreze');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, '[Faraon] a spus: „De ai venit cu un semn, atunci adu-l, dacă ești dintre cei care spun adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'Atunci el [Moise] și-a aruncat toiagul și, dintr-o dată, acesta era un șarpe vădit[22].', '[22] Adevărat și nu imaginat, drept miracol de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'Și a scos mâna sa și, iată, ea era albă [strălucitoare] pentru cei care priveau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Au spus atunci dregătorii din poporul lui Faraon: „Acesta este un vrăjitor iscusit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, 'Care voiește să vă scoată pe voi din pământul vostru [prin magie], așadar ce porunciți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, 'Ei au spus[23]: „Amână-l pe el și pe fratele lui și trimite în orașe strângători,', '[23] După consultări');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'Care să-i aducă la tine pe toți vrăjitorii iscusiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'Și au venit vrăjitorii la Faraon și au spus: „Cu adevărat vom avea parte de răsplată, dacă noi vom fi cei biruitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, 'El le-a răspuns: „Da, și [mai mult] veți fi voi, fără îndoială, dintre cei apropiați [mie].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, '[Atunci] au spus ei: „O, Moise, fie arunci tu [primul toiagul], fie suntem noi cei care aruncă [primii].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, '[Moise] le-a răspuns: „Aruncați voi!” Și când au aruncat ei, au fermecat ochii oamenilor și i-au înfricoșat și au adus o mare magie[24].', '[24] Toiagele și funiile lor păreau că sunt șerpi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'Și i-am revelat Noi lui Moise: „Aruncă toiagul tău!” Și iată că el a înghițit ceea ce ei izvodiseră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'Și astfel adevărul a ieșit la iveală, iar ceea ce făceau ei a pierit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'Și ei [Faraon și dregătorii săi] au fost învinși acolo și s-au întors rușinați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, 'Și s-au aruncat vrăjitorii, prosternându-se [lui Allah]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, '[Și] au spus ei: „Credem în Domnul lumilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, 'În Domnul lui Moise și Aaron!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, 'A spus Faraon [atunci]: „Ați crezut în el înainte ca eu să vă fi permis. Acesta este un vicleșug pe care l-ați urzit față de cetate, pentru ca să scoateți din ea poporul lui. Dar veți afla voi în curând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, 'Vă voi tăia mâinile și picioarele voastre cruciș și apoi vă voi răstigni pe toți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'Ei au răspuns: „Noi la Domnul nostru ne întoarcem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, 'Tu nu te răzbuni pe noi decât pentru că noi am crezut în semnele Domnului nostru, atunci când ele ne-au venit. Doamne, revarsă asupra noastră răbdare și fă-ne pe noi să murim musulmani [cu desăvârșire supuși].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'Au spus dregătorii din neamul lui Faraon: „Vrei să-i lași pe Moise și pe neamul lui să facă stricăciune în țară și să te părăsească pe tine și pe zeii tăi?” [Faraon] a răspuns: „Îi vom măcelări pe fiii lor și le vom lăsa în viață pe femeile lor. Noi vom fi deasupra lor, biruitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Moise a spus către neamul său: „Rugați-vă lui Allah pentru ajutor și fiți răbdători. Cu adevărat al lui Allah este Pământul și El îl dă moștenire cui voiește dintre robii Săi. Iar sfârșitul [cel mai bun] este al celor care au frică.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, '[Și] i-au răspuns ei: „Am avut de îndurat înainte ca tu să vii la noi și după ce ai venit la noi!” Dar [Moise] le-a răspuns: „S-ar putea ca Domnul vostru să-l nimicească pe dușmanul vostru și să vă facă pe voi stăpâni pe acest pământ pentru ca să vadă cum faceți voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'Și Noi am încercat poporul lui Faraon cu ani de foamete și cu lipsă de roade, poate că vor lua aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'Și când aveau parte de bine, spuneau: „Aceasta ni se cuvine nouă.” Iar dacă se abătea asupra lor ceva rău, atunci vedeau semn rău în Moise și în cei care erau cu el. Însă nenorocul lor se află la Allah [și numai El este Cel care are Puterea de a-i pedepsi pentru pacatele lor], dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'Și ei au spus: „Orice semne ne vei aduce, ca să ne farmeci cu ele, noi nu-ți vom fi ție credincioși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Și am trimis Noi asupra lor potopul, lăcustele, păduchii, broaștele și sângele, ca semne deslușite, dar ei s-au îngâmfat și au fost un popor de păcătoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'Și când venea asupra lor pedeapsa, ei spuneau: „O, Moise! Roagă-te pentru noi Stăpânului tău, după Legământul pe care L-a făcut cu tine! Și de ne vei izbăvi de pedeapsă, vom crede în tine și-i vom lăsa să plece împreună cu tine pe Fiii lui Israel.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'Iar când i-am izbăvit Noi de pedeapsă până la un termen stabilit, pe care ei trebuiau să-l atingă, ei și-au încălcat promisiunea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'Așa că Ne-am răzbunat pe ei și i-am înecat în mare, pentru că ei au negat semnele Noastre și au fost nepăsători față de ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'Și pe oamenii care au fost asupriți i-am făcut moștenitori peste ținuturile de răsărit ale pământului și peste ținuturile de apus, pe care Noi le-am binecuvântat. Iar Cuvântul cel mai frumos al Domnului tău asupra Fiilor lui Israel s-a împlinit pentru că au fost statornici. Și Noi am nimicit ceea ce au făcut Faraon și neamul său și ceea ce ei au ridicat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'Și i-am făcut Noi pe Fiii lui Israel să treacă marea și au venit ei la un popor care se închina unor idoli. Atunci i-au spus ei: „O, Moise! Fă-ne nouă un zeu, așa cum au și ei zei!” Dar el le-a răspuns: „Cu adevărat voi sunteți un neam de neștiutori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Cele în care petrec aceștia sunt pierdute și în deșert este ceea ce fac ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, 'A [mai] spus el: „Să vă caut vouă o altă divinitate în afara lui Allah, Cel care v-a pus pe voi mai presus de toate lumile?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, '[Aduceți-vă aminte, o Fii ai lui Israel, că] Noi v-am izbăvit de neamul lui Faraon care v-a supus la cel mai rău chin, i-a măcelărit pe fiii voștri și le-a lăsat în viață pe femeile voastre. Aceasta a fost grea încercare de la Domnul vostru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Și Noi i-am hotărât lui Moise după treizeci de nopți, pe care le-am întregit cu încă alte zece, astfel încât termenul fixat de Domnul său venea după patruzeci de nopți. Și Moise i-a spus fratelui său Aaron: „Ține-mi locul printre poporul meu și fii cu dreptate și nu urma drumul celor care aduc stricăciune.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'Și când a venit Moise la timpul hotărât de Noi și a Vorbit cu el Domnul său, a spus el: „Doamne, arată-Te mie ca să Te văd.” [Allah] i-a răspuns: „Tu nu Mă vei vedea[25], dar privește la Munte și de va rămâne neclintit, atunci Mă vei vedea.” Dar când s-a arătat Domnul său Muntelui, l-a prefăcut în pulbere și Moise s-a prăbușit leșinat. Iar când și-a venit în fire, a spus: „Mărire Ție! Mă întorc la Tine căindu-mă și sunt cel dintâi dintre credincioși"', '[25] În viața aceasta');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, '[Allah] a spus: „O, Moise! Te-am ales dintre toți oamenii, cu Mesajele Mele și Cuvintele Mele! Deci primește ceea ce-ți dau și fii dintre cei mulțumitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'Și Noi i-am scris lui pe Table [câte ceva] despre toate lucrurile - îndemânare și tâlcuire, [spunând]:„Ține-le, așadar, cu putere și poruncește neamului tău să primească ce e mai bun în ele! Apoi vă voi arăta vouă sălașul celor abătuți din drum.”[26]', '[26] Acesta este un avertisment serios de la Allah împotriva rebeliunii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Îi voi îndepărta de la semnele Mele pe cei care sunt aroganți pe pământ pe nedrept, chiar de-ar vedea fiecare semn, tot nu ar crede în el. Iar dacă văd calea cea bună, ei nu o primesc drept drum, însă dacă văd calea rătăcirii, o primesc drept drum. Aceasta pentru că ei neagă semnele Noastre și sunt nepăsători față de ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Iar cei care neagă semnele Noastre și întâlnirea cu Ziua de Apoi - faptele lor sunt în deșert. Ar putea fi ei răsplătiți altfel decât după ceea ce fac?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'Și poporul lui Moise a făcut, după el[27], din podoabele lor un vițel cu trup care avea și muget. Nu au văzut că el nu le vorbește și nu-i călăuzește pe niciun drum? L-au luat [drept Dumnezeu] și au fost nelegiuiți.', '[27] După plecarea lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Și când au fost cuprinși de regret și și-au dat seama că au rătăcit, au spus: „Dacă nu se va îndura Domnul nostru de noi și nu ne va ierta, vom fi și noi printre cei pierduți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'Și când s-a întors Moise la poporul său, mâniat și întristat, a spus: „Mare rău ați săvârșit în lipsa mea! Ați voit voi să grăbiți porunca Domnului vostru?” Și a aruncat Tablele, l-a apucat de cap pe fratele său și l-a tras spre el. Și a spus [Aaron]: „O, fiu al mamei mele! Poporul m-a asuprit și aproape m-a ucis. Nu-i face pe dușmani să se bucure de nenorocirea mea și nu mă pune pe mine alături de neamul celor nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, '[Moise] a spus: „Doamne, iartă-mi mie și fratelui meu și lasă-ne pe noi să intrăm întru Îndurarea Ta, căci Tu ești Cel mai Îndurător dintre cei îndurători".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Pe cei ce au luat vițelul [ca adorare] îi va ajunge mânie de la Domnul lor și înjosire în această viață. Astfel îi răsplătim Noi pe cei care născocesc [idoli],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'Dar cei care au săvârșit fapte rele, și s-au căit după aceea și au crezut – cu adevărat Domnul tău este, după aceea, Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'Și după ce s-a potolit mânia lui Moise, a luat Tablele și în scrierea lor era Călăuzire și Îndurare pentru cei care se tem de Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'Și a ales Moise șaptezeci de bărbați din poporul său pentru timpul întâlnirii cu Noi[28]. Și când i-a lovit cutremurul[29] el a spus: „Doamne, dacă Tu ai fi Voit, i-ai fi putut pierde mai dinainte, ca și pe mine. Oare Vrei Tu să ne pierzi pentru ceea ce au săvârșit cei nelegiuiți dintre noi? Aceasta nu este decât o încercare de la Tine, cu care-i duci în rătăcire pe cei care Tu Voiești și îi Călăuzești pe cei care Tu Voiești. Tu ești Ocrotitorul nostru. Deci Iartă-ne nouă și Îndură-Te de noi, căci Tu ești Cel mai Bun dintre iertători!', '[28] Unde își vor cere iertare de la Allah pentru că au adorat vițelul
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, 'Prescrie pentru noi binele în această lume, [la fel] și în Viața de Apoi! Cu adevărat noi ne-am întors la Tine, căindu-ne”. [Allah] a spus: „Cu pedeapsa Mea îi ajung pe cei care Voiesc Eu, iar Îndurarea Mea cuprinde toate lucrurile.” Și o voi prescrie pentru cei care au frică și achită Dania [Az-Zakat] și cei care cred în Versetele Noastre,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, 'Pentru cei care îl urmează pe Trimis, Profetul neînvățat[30], despre care se află scris la ei în Tora și în Evanghelie. El le poruncește ceea ce este drept și-i oprește de la ceea ce este greșit, le îngăduie lor bunătățile și le oprește lor pe cele necurate și-i ușurează pe ei de povara lor[31] și de lanțurile care au fost asupra lor. Cei ce cred în el și îl susțin și îl ajută și urmează Lumina care a fost pogorâtă cu el, vor fi cei izbânditori.”', '[30] Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa), care nu știa să scrie sau să citească
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'Spune [o, Mohammed]: „O, oameni! Eu sunt pentru voi toți Trimisul lui Allah, Cel căruia îi aparține Împărăția Cerurilor și a Pământului. Nu există altă divinitate în afară de El! El dă viață și El dă moarte. Deci credeți în Allah și în Trimisul Său, Profetul cel neînvățat, care crede în Allah și în Cuvintele Sale și urmați-l! Poate că veți fi călăuziți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'Și în poporul lui Moise este o comunitate care-i călăuzește [pe ceilalți] către Adevăr și cu el judecă, după dreptate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'Și Noi i-am împărțit în douăsprezece seminții [clanuri], comunități. Și i-am revelat lui Moise, atunci când poporul său i-a cerut de băut [apă]: „Lovește cu toiagul tău în stâncă!” Și iată că au țâșnit din ea douăsprezece izvoare, încât fiecare seminție știa locul său de băut. Și le-am făcut umbră cu nori și am pogorât asupra lor mana și prepelițele, [spunând]: „Mâncați din bunătățile pe care vi le-am dat ca hrană!” Și nedreptatea lor nu Ne-a atins pe Noi, ci doar pe ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'Și [spune, o, Mohammed] când li s-a spus: „Locuiți în această cetate [Ierusalim] și mâncați din ea de oriunde voiți, dar spuneți: „Iertare” și intrați pe poartă, prosternându-vă [cu smerenie]. Noi vom ierta păcatele voastre și le vom dărui și mai mult acelora care fac bine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Dar aceia dintre ei care au fost nelegiuiți au schimbat cu un altul Cuvântul care li se spusese lor. Atunci, Noi am trimis asupra lor pedeapsă din Cer, pentru că au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'Și întreabă-i pe ei despre cetatea care era așezată lângă Mare - când au încălcat Sabatul - când peștii au venit la ei în ziua Sabatului, ieșind la suprafață; dar în ziua când nu era Sabat, n-au venit la ei. Astfel i-am încercat Noi pentru că au fost sfidător de neascultători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, 'Și când o parte dintre ei a spus: „De ce sfătuiți [sau avertizați] un popor pe care Allah Voiește să-l nimicească sau să-l pedepsească cu un chin greu?”, au răspuns [sfătuitorii]: „Pentru dezvinovățire la Domnul vostru; și poate că ei vor avea frică!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'Și când ei [cei sfătuiți] au uitat ceea ce li s-a poruncit, i-am Mântuit Noi pe cei care au oprit de la rău și i-am osândit pe cei care au fost nelegiuiți la chin aspru, pentru că au fost sfidător de neascultători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'Și atunci când au încălcat ceea ce le fusese interzis, le-am spus Noi: „Fiți maimuțe demne de dispreț!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'Și [spune] când Domnul tău a vestit că El va trimite [mereu] asupra lor pe cineva care să-i încerce cu pedeapsă grea până în Ziua Învierii. Cu adevărat, Domnul tău este repede la pedeapsă, dar El este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'Și Noi i-am împărțit în comunități pe pământ. Unii dintre ei sunt drepți, iar alții sunt mai puțin de-atât. Și i-am încercat cu [timpuri] bune și rele, poate se vor întoarce [la ascultare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'Apoi, după ei au venit urmași care au moștenit Scriptura, însă ei aleg ceea ce este mai josnic în această lume, spunând: „Ni se va ierta nouă!” Și dacă [lucruri] asemănătoare acestuia li se oferă lor, ei le primesc. Oare nu s-a încheiat cu ei legământul Scripturii [Tora], ca ei să nu spună despre Allah decât Adevărul și să cerceteze ceea ce se află în ea. Dar Casa din Lumea de Apoi este mai bună pentru cei care au frică! Oare nu voiți să pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'Iar cei ce se țin de Carte [Coranul] și împlinesc Rugăciunea [As-Salat], [să știe că] Noi nu lăsăm să se piardă răsplata celor cuvioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'Și [spune] când am ridicat Noi muntele deasupra lor, ca și când ar fi fost un Nor negru și ei și-au închipuit că va cădea peste ei[32], [și Allah le-a Spus]: „Țineți cu putere ceea ce v-am dat și aduceți-vă aminte de ceea ce se află înlăuntru! Poate că vă veți teme!”', '[32] Pentru rebeliunea și neascultarea lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'Și [spune] când Domnul tău i-a scos pe urmașii fiilor lui Adam, din coastele lor și le-a cerut să mărturisească ei înșiși, [spunându-le]: „Nu sunt, oare, Eu Domnul vostru?”. Ei au răspuns: „Ba da, mărturisim!”, pentru ca voi să nu spuneți în Ziua Învierii: „Noi nu am știut despre aceasta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, 'Sau să nu spuneți „Părinții noștri au fost politeiști mai înainte, iar noi suntem urmași după ei. Vrei Tu să ne distrugi pentru ceea ce au făcut cei mincinoși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'Astfel facem Noi semnele limpezi; poate că ei se vor întoarce[33].', '[33] La calea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, '[O, Mohammed] istorisește-le lor vestea despre acela[34] căruia Noi i-am dat Semnele Noastre, dar el s-a abătut de la ele, iar Șeitan s-a ținut de el [și nu l-a lăsat] și astfel el s-a aflat printre cei rătăciți.[35]', '[34] Un om dintre Fiii lui Israel în timpul lui Moise
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'Dacă Noi am fi Voit, l-am fi ridicat prin ele[36], însă el a înclinat spre pământ[37] și a urmat poftei sale. Pilda lui este asemenea pildei câinelui: dacă-l alungi, el scoate limba gâfâind; dacă-l lași în pace, tot scoate limba gâfâind. Aceasta este pilda acelora care neagă Semnele Noastre[38]. Istorisește-le, poveștile; poate că ei vor cugeta!', '[36] Prin revelații, semne sau dovezi despre care el a primit știință
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Rea pildă este [aceasta] a neamului celor care au negat semnele Noastre și împotriva lor înșiși au săvârșit ei nedreptatea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Cel pe care îl călăuzește Allah este bine călăuzit, iar cei pe care îi duce în rătăcire sunt pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Noi am făcut pentru Iad pe mulți dintre djinni și oameni. Ei au inimi, dar nu pricep cu ele; ei au ochi, dar nu văd cu ei; ei au urechi, dar nu aud cu ele. Aceștia sunt asemenea animalelor, ba ei sunt chiar și mai rătăciți[39]. Aceștia sunt nepăsători.', '[39] Se face referire la refuzul lor de a gândi în timp ce urmează ceea ce sunt obișnuiți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'Și ale lui Allah sunt Numele Cele mai Frumoase, așadar chemați-L cu ele și depărtați-vă de cei care deviază în ceea ce privește Numele Lui[40]. Ei vor fi răsplătiți după ceea ce fac!', '[40] Nu le folosesc corespunzător sau le neagă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'Și printre cei pe care Noi i-am creat se află o comunitate[41] ce călăuzește după adevăr și judecă, după dreptate.', '[41] Cei care îl urmează pe profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'Dar pe cei care neagă semnele Noastre - îi vom duce treptat [către pieire][42], prin mijloace pe care ei nu le știu.', '[42] În ciuda neascultării lor, Allah îi va testa cu un bine după bine, care îi va face doar să fie mai aroganți și mai păcătoși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'Voi să le dau lor un răgaz. Cu adevărat, Planul Meu este Temeinic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Oare nu pricep ei? În tovarășul lor [Mohammed] nu este pic de nebunie. El nu este decât un prevenitor limpede .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'Oare nu văd ei Împărăția Cerurilor și a Pământului și [toate] lucrurile pe care le-a creat Allah și că s-ar putea ca sorocul lor să fie aproape? În ce cuvinte vor crede ei după aceasta?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Cei pe care Allah îi duce în rătăcire nu vor afla călăuzitor, iar El îi lasă să rătăcească în nelegiuirea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'Ei te vor întreba [o, Mohammed] despre Ceas: „Când va veni el?” Spune: „Numai la Domnul meu este știrea despre el. Numai El îl va descoperi la timpul lui. El este greu[43] peste [cei din] Ceruri și peste [cei de pe] Pământ și nu va veni asupra voastră decât pe neașteptate.” Te întreabă de parcă tu ai fi interesat [să știi]. Spune: „Numai la Allah se află știrea despre el.” Dar cei mai mulți oameni nu știu.', '[43] O sursă de îngrijorare sau frică');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'Spune: „Eu nu stăpânesc niciun folos pentru mine și nicio pagubă, în afară de ceea ce Voiește Allah. Dacă eu aș fi știut necunoscutul, aș avea prisosință de bunuri și nu m-ar atinge răul. Dar eu nu sunt decât un prevestitor și un binevestitor pentru oamenii care cred.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'El este Cel care v-a creat dintr-un singur suflet și din el a făcut-o și pe perechea lui, lângă care el să poată găsi liniște. Și când el a acoperit-o[44], a purtat ea o sarcină ușoară și putea umbla cu ea. Dar când s-a simțit mai grea, au strigat ei amândoi [rugându-se] către Allah, Domnul lor: „De ne vei dărui un [copil] bun[45], vom fi noi dintre cei mulțumitori.”', '[44] Aluzie la relațiile intime
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'Și când le-a dăruit lor un [copil] bun, ei[46] I-au făcut Lui asociați, ca răsplată pentru ceea ce le-a dat. Dar Allah s-a Înălțat deasupra celor pe care i-au asociat [Lui].', '[46] Bărbatul sau femeia nerecunoscători sau politeiști');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Îi asociază [Lui lucruri] ce nu creează nimic și care ele [însele] sunt create?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'Și [zeitățile false] nu-i pot ajuta pe ei cu nimic și nici lor înșiși nu-și pot fi de ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'Și dacă voi [credincioșii] îi chemați la drumul cel drept, ei nu vă urmează. Tot una este pentru voi dacă îi chemați sau păstrați tăcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'Cu adevărat, cei pe care voi [politeiștii] îi invocați alături de Allah sunt robi asemenea vouă. Invocați-i, așadar, și să vă răspundă, dacă voi sunteți cu adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Au ei picioare cu care să meargă? Sau au ei mâini cu care să lovească? Sau au ei ochi cu care să vadă? Sau au ei urechi cu care să audă? Spune [o, Mohammed]: „Chemați-i pe asociații voștri și apoi folosiți viclenia împotriva mea și nu-mi dați niciun răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Cu adevărat, Ocrotitorul meu este Allah, Cel care a pogorât Cartea și El ia asupra Sa [Ocrotirea] celor evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'Și cei pe care îi chemați în locul Lui nu vor putea să vă ajute și nici lor înșiși nu-și vor putea fi de ajutor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'Iar dacă-i chemi la calea cea dreaptă, ei nu aud. Îi vezi cum se uită la tine, însă ei nu văd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Primește ceea ce îți este dat fără constrângeri[47], poruncește ceea ce este bun și îndepărtează-te de neștiutori.', '[47] Din averea oamenilor. Cu alte cuvinte, fii echilibrat atunci când ai de-a face cu oamenii și nu le cauza dificultăți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'Și dacă vreodată Șeitan te îmboldește, ispitindu-te la rău, caută refugiu la Allah, căci El este Sami'' [Cel care Aude Totul] [și] ''Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Cu adevărat, cei care au frică de Allah – atunci când îi atinge ceva rău de la Șeitan, își aduc aminte [de Allah] și iată cum ei văd [primejdia].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'Însă pe frații lor[48] îi împing [șeitanii] în rătăcire, astfel încât ei nu se mai pot opri.', '[48] Acei oameni care ascultă de diavoli și le urmează ordinele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Și când tu [o, Mohammed] nu le aduci lor un semn [miracol] atunci ei spun: „De ce nu-l născocești tu?”. Spune: „Eu nu urmez decât ceea ce-mi este revelat de Domnul meu. Acestea [Coranul] sunt dovezi limpezi de la Domnul vostru, Călăuzire și Îndurare pentru un neam [de oameni] care cred.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'Și când este citit Coranul, atunci ascultați-l cu atenție și păstrați tăcere, poate că voi veți avea parte de Îndurare [de la Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'Și pomenește-L pe Domnul tău în sufletul tău, cu umilință și teamă, fără a o rosti cu glas tare, atât dimineața cât și seara, și nu fi dintre cei nepăsători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Cu adevărat cei ce sunt aproape de Domnul tău [Îngerii] nu se socotesc prea mari pentru a-L adora pe El, ci ei Îl Preamăresc și se prosternează dinaintea Lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Ei te întreabă [o, Mohammed] despre prăzi [din război]. Spune: „Prăzile sunt ale lui Allah și ale Trimisului.”[1] Așadar fiți cu frică de Allah, fiți cu pace între voi și fiți cu supunere față de Allah și față de Trimisul Său, dacă sunteți credincioși.', '[1] Decizia cu privire la prăzi îi aparține lui Allah și profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'Credincioșii sunt doar cei ale căror inimi se cutremură când se pomenește [Numele lui] Allah și a căror credință sporește când li se citesc Versetele Lui și se încred în Domnul Lor -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Cei care împlinesc Rugăciunea [As-Salat] și dau milostenie [pe calea lui Allah] din cele cu care Noi i-am înzestrat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Aceștia sunt cu adevărat credincioși și ei au trepte la Domnul lor, precum și iertare și câștig din belșug.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, '[Este][2] la fel, când Domnul tău te-a scos din casa ta [pentru Bătălia de la Badr] în numele Adevărului, cu toate că o parte dintre dreptcredincioși nu erau doritori,', '[2] Făcând referire la o dispută ce a avut loc între musulmani cu privire la distribuția prăzilor de război');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'Certându-se cu tine în legătură cu Adevărul, după ce el devenise limpede, ca și când ar fi fost duși la moarte și chiar ar fi văzut-o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, '[Aduceți-vă aminte credincioșilor] atunci când Allah v-a făgăduit vouă că una din cele două cete[3] va fi a voastră! Și ați fi vrut voi să fie a voastră cea care nu avea arme[4], însă Allah a voit să întărească Adevărul cu Vorbele Sale și să-i nimicească pe necredincioși până la ultimul,', '[3] Fie caravana tribului Quraiș sau armata lor
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, 'Pentru a face să dovedească Adevărul și să înlăture neadevărul, cu toate că nelegiuiții se împotriveau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, '[Aduceți-vă aminte] când voi cereați ajutor Domnului vostru și El v-a răspuns: „Cu adevărat, Eu vă voi ajuta cu o mie de Îngeri, rânduiți unul după altul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Și Allah nu l-a făcut decât pentru a fi bună vestire, pentru ca inimile voastre să-și găsească liniștea cu ea. Și nu este victorie decât numai de la Allah. Într-adevăr Allah este ‘Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, '[Aduceți-vă aminte] când El v-a învăluit pe voi cu un somn, ca o pavăză din partea Sa, și a pogorât asupra voastră din Cer apă, ca să vă purifice pe voi cu ea și să îndepărteze de la voi murdăria lui Șeitan și să vă întărească inimile și să vă statornicească picioarele cu ea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, '[Aduceți-vă aminte] când Domnul tău le-a revelat Îngerilor: „Eu sunt cu voi! Întăriți-i, așadar, pe cei care cred. Eu voi arunca spaimă în inimile celor care nu cred. Loviți-i, deci, peste gâturi și loviți-i peste toate vârfurile degetelor.”[5]', '[5] Cu care prind și manevrează armele lor. De asemenea este interpretat drept „toate extremitățile”, și anume mâinile și picioarele lor.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'Aceasta pentru că ei s-au împotrivit lui Allah și Trimisului Său. Iar cu cei care se împotrivesc lui Allah și Trimisului Său, Allah este aspru la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, '„Aceasta este [soarta voastră], așadar gustați-o!” Și necredincioșii vor avea parte de chinul Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'O, voi cei care credeți! Dacă vă întâlniți cu cei care nu cred și ei înaintează [la luptă], nu le întoarceți spatele, [fugind].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Iar asupra celor care în ziua aceea le vor întoarce spatele [fugind] - în afară de cei care fac un ocoliș pentru luptă sau de cei care se îndreaptă spre o altă ceată - se va abate mânia lui Allah, iar sălașul lor va fi Iadul - Și ce cumplită soartă [vor avea ei]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Și nu voi i-ați omorât, ci Allah i-a omorât. Și când ai aruncat [un pumn de țărână], nu tu l-ai aruncat, ci Allah l-a aruncat[6] ca să-i încerce pe dreptcredincioși cu un test frumos[7]. Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Atoateștiutor].', '[6] Atunci când Profetul (pacea și binecuvântarea lui Allah fie asupra sa) a aruncat o mână de praf în fețele necredincioșilor, Allah a făcut ca ochii și nasul fiecărui soldat să fie umplut de praf, împiedicându-i să avanseze.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Aceasta pentru ca Allah să slăbească viclenia necredincioșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, 'Dacă voi [necredincioșilor] veți cere biruința [lui Allah], v-a și venit biruința [Lui]. Și dacă veți înceta, e mai bine pentru voi. Însă dacă vă veți întoarce [la război], ne vom întoarce și Noi și nu vă va fi de folos oastea voastră întru nimic, chiar de va fi [și mai] numeroasă, căci Allah este cu dreptcredincioșii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'O, voi cei care credeți, fiți cu supunere față de Allah și de Trimisul Său și nu vă întoarceți de la El, când auziți [Poruncile Sale].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'Și nu fiți ca cei care au spus „Am auzit”, dar ei nu au auzit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, 'Cu adevărat, cele mai rele viețuitoare pentru Allah sunt surzii și muții care nu își folosesc judecata [necredincioșii].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Dacă Allah ar ști ceva bun la ei, i-ar face să audă. Dar chiar de i-ar lăsa să audă, ei ar întoarce spatele [în continuare], îndepărtându-se.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'O, voi cei care credeți, răspundeți-I lui Allah și Trimisului [Său], dacă vă cheamă la ceea ce vă dă viață. Și să știți că Allah se interpune între om și inima sa și că voi la El vă veți aduna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'Și feriți-vă de o încercare[8] care nu-i va atinge doar pe cei care sunt nelegiuiți dintre voi. Și să știți că Allah este aspru la pedeapsă!', '[8] O nenorocire sau pedeapsă în timpul acestei vieți. Atunci când corupția se răspândește, consecințele ei vor afecta pe toți oamenii.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'Și aduceți-vă aminte când voi erați puțini la număr, slabi și oprimați pe pământ și vă temeați să nu vă răpună oamenii, însă El v-a dat adăpost și v-a sprijinit cu Victoria Lui și v-a îndestulat cu Bunătăți, pentru ca voi să fiți mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'O, voi cei care credeți, nu-L trădați pe Allah și pe Trimis, nici nu vicleniți asupra celor ce v-au fost încredințate, cu bună știință [a consecințelor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'Și să știți că bunurile voastre și copiii voștri nu sunt decât o încercare și că la Allah se află răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'O, voi cei care credeți, dacă sunteți cu frică de Allah, atunci El vă va da vouă un Îndreptar[9] și vă va șterge vouă faptele rele și vă va ierta, căci Allah este Dătător de Har nemărginit.', '[9] Prin care să judecați între adevăr și minciună');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'Și [adu-ți aminte, o, Mohammed,] când necredincioșii au plănuit [un rău] împotriva ta, ca să te întemnițeze ori să te omoare, ori să te alunge [din Mecca]. Au plănuit ei, însă și Allah a Plănuit [împotriva lor], căci Allah este Cel mai Bun dintre cei care plănuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Și când li se recită lor Versetele Noastre, ei spun: „Noi am auzit. Iar de am voi noi, am putea spune asemenea acestora, căci ele nu sunt alta decât legende ale popoarelor vechi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'Și [adu-ți aminte] când au spus: „Doamne, dacă acesta este Adevăr de la Tine, atunci fă să plouă asupra noastră pietre din Cer ori adu peste noi pedeapsă dureroasă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Dar Allah nu a Voit să-i pedepsească, atunci când te aflai și tu [o, Mohammed,] printre ei și nu a Voit Allah să îi pedepsească în timp ce ei cereau iertare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'De ce să nu-i pedepsească Allah, de vreme ce ei împiedică [pe dreptcredincioși] de la Moscheea al-Haram, cu toate că nu erau păzitorii ei. Păzitorii ei [adevărați] sunt doar cei dreptcredincioși, însă cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Și rugăciunea lor în Casa [Ka''bah] nu era alta decât numai șuierat și plesnit din palme. Deci gustați din chin, pentru că nu ați crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Cu adevărat, cei care nu cred, cheltuiesc averea lor pentru a împiedica [oamenii] de la calea lui Allah. O vor cheltui ei, dar aceasta le va aduce lor mâhnire, iar apoi vor fi înfrânți. Și aceia care nu cred, vor fi adunați în Iad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, '[Este astfel] pentru ca Allah să-l deosebească pe cel rău de cel bun și să-i pună pe cei răi unul peste altul, să-i îngrămădească pe toți și să-i arunce în Iad. Aceștia sunt cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Spune-le celor care nu cred că, dacă se vor opri, li se va ierta ceea ce a trecut, dar dacă se vor întoarce ei, [atunci vor fi pedepsiți], după pilda celor de dinainte[10].', '[10] Aceasta este o avertizare că pedeapsa este întotdeauna rezultatul rebeliunii împotriva lui Allah și a mesagerilor Săi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'Și luptați împotriva lor până ce nu va mai fi ispită[11] și până ce religia va fi în întregime pentru Allah[12]. Iar de se vor opri, Allah este Basir [Cel care Vede Bine] ceea ce fac ei.', '[11] Persecuție. A se vedea 2:193.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'Iar dacă vă vor respinge, atunci să știți că Allah este Ocrotitorul vostru. Și ce minunat Ocrotitor și ce minunat Sprijinitor [este El]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'Și să știți că a cincea parte din ceea ce ați luat drept pradă este pentru Allah, Trimisul[13] [Său] și familia apropiată[14], orfani, sărmani și călătorul [nevoiaș][15], dacă voi credeți în Allah și în ceea ce Noi am pogorât asupra Robului Nostru[16] în ziua deosebirii [Al-Furqan]: ziua în care s-au întâlnit cele două tabere [la Badr]. Și Allah este cu Putere peste toate.', '[13] Să fie cheltuite pentru cauza lui Allah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, '[Aduceți-vă aminte] când voi erați pe malul apropiat, iar ei [dușmanii] pe malul îndepărtat [al văii], iar caravana se afla mai jos decât voi. Dacă voi v-ați fi dat întâlnire, nu ați fi fost atât de înțeleși asupra timpului întâlnirii. Însă Allah a Voit să împlinească un lucru ce trebuia împlinit, pentru ca să piară [prin necredință] cei care au pierit având dovadă, și să rămână în viață cei care au rămas în viață având dovadă. Și Allah este, neîndoielnic, Sami'' [Cel care Aude Totul] [și] ''Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, '[Adu-ți aminte, o, Mohammed] cum Allah ți i-a arătat în visul tău [ca fiind] puțini. Iar dacă ți i-ar fi arătat mulți, voi [credincioșilor] v-ați fi temut și ați fi avut păreri diferite [dacă să lupte sau nu] asupra acestui lucru. Dar Allah v-a păzit [de aceasta]. El este Bineștiutor al celor dinăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'Și [aduceți-vă aminte] cum El vi i-a arătat vouă puțini în ochii voștri, când v-ați întâlnit, după cum v-a făcut [să păreți] puțini și pe voi în ochii lor, pentru ca Allah să împlinească un lucru ce trebuia împlinit. Și la Allah se întorc [toate] lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'O, voi cei care credeți, când întâlniți o armată [de dușmani], fiți statornici și pomeniți-L pe Allah mult, pentru ca voi să izbândiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'Și ascultați-L pe Allah și pe Trimisul Său și nu vă certați, ca să nu pierdeți și să nu piară forța voastră. Și fiți răbdători, căci Allah este cu cei răbdători!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'Și nu fiți ca cei care au ieșit din casele lor mândri, de ochii lumii, pentru ca să [îi] abată de la Calea lui Allah, căci Allah este Muhit [Cel care Cuprinde] [cu Știința Sa] ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, 'Și [aduceți-vă aminte] când Șeitan le-a înfrumusețat faptele lor, spunând: „Nimeni nu vă poate învinge astăzi dintre oameni, căci eu sunt aliat cu voi.” Dar când cele două oștiri s-au văzut una pe cealaltă, atunci s-a întors el pe călcâie și a zis: „Cu adevărat, eu nu am nicio legătură cu voi. Cu adevărat, eu văd ceea ce voi nu vedeți; cu adevărat, eu mă tem de Allah, căci Allah este aspru la pedeapsă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, '[Și aduceți-vă aminte] când ipocriții și cei care au boală [aroganță și necredință] în inimi au spus: „Pe aceștia [musulmanii] i-a amăgit religia lor.” Însă cei ce se încred în Allah [vor fi victorioși, căci] Allah este ''Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'Și dacă numai ai vedea cum Îngerii iau sufletele celor care nu cred. Îi lovesc peste fețe și peste spate, [spunând]: „Gustați din chinul Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, 'Aceasta pentru ceea ce au săvârșit mâinile voastre, căci Allah doară nu este nedrept cu robii Săi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, '[Ei sunt] asemenea poporului lui Faraon și celor de dinaintea lor, care nu au crezut în semnele lui Allah și pe care Allah i-a pedepsit pentru păcatele lor. Allah este Qauiyy [Puternic] [și] aspru la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'Aceasta pentru că Allah nu schimbă Îndurarea pe care a revărsat-o asupra unui popor, decât dacă ei schimbă ceea ce este în sufletele lor. Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, '[Ei sunt] asemenea neamului lui Faraon și celor de dinaintea lor, care au socotit drept mincinoase semnele Domnului lor și pe care i-am nimicit pentru păcatele lor și am înecat Noi neamul lui Faraon, căci toți erau nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, 'Cu adevărat, cele mai rele vietăți pentru Allah sunt aceia care nu au crezut și care nu cred [și nici nu vor crede vreodată],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, 'Cei cu care ai făcut legământ, dar ei au încălcat de fiecare dată legământul lor și ei nu au frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Așadar dacă tu [o, Mohammed], îi vei domina în război, alungă-i [speriindu-i] prin ei pe cei care vin în urma lor. Poate că ei își vor aduce aminte.[17]', '[17] Omoară-i și fă din ei un exemplu pentru a-i descuraja pe cei care îi urmează');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'Iar dacă tu vreodată [ai motive să] te temi de trădare din partea unui popor, rupe înțelegerea cu ei, întocmai așa.[18] Cu adevărat, Allah nu-i iubește pe trădători.', '[18] Atunci când vezi semne de trădare de la cei cu care ai încheiat un legământ, anunță-le anularea lui pentru ca ei să știe exact unde se află');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'Și să nu-și închipuie niciodată cei care nu cred că ei au scăpat. Cu adevărat, ei nu vor putea niciodată să Ne împiedice.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'Deci pregătiți [pentru luptă] împotriva lor tot ceea ce puteți din forță și din cai înșeuați[19], cu care să-i înspăimântați pe dușmanul lui Allah și pe dușmanul vostru și pe alții decât aceștia, pe care voi nu-i știți, dar pe care Allah îi știe. Și tot ceea ce voi cheltuiți pe calea lui Allah vă va fi dat înapoi pe deplin și nu veți fi nedreptățiți.', '[19] Sau echipament ce are același scop');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Iar dacă ei vor înclina către împăcare, înclină și tu către ea. Și încrede-te în Allah, căci El este Sami'' [Cel care Aude Totul] [și] ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'Însă dacă ei vor voi să te înșele, atunci Allah îți va fi de ajuns. El este Cel care te-a susținut cu ajutorul Său și cu dreptcredincioșii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'Și care a unit inimile lor. Dacă ai fi cheltuit tot ceea ce se află pe pământ, tu tot nu ai fi unit inimile lor, însă Allah i-a unit, căci El este ''Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'O, Profetule, îți este de ajuns Allah [ca Sprijinitor, ție] și dreptcredincioșilor care te urmează!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'O, Profetule, îndeamnă-i pe dreptcredincioși la luptă. Dacă douăzeci dintre voi sunt statornici, vor învinge ei două sute, iar dacă sunt între voi o sută, vor învinge ei o mie dintre cei care nu cred, căci aceștia sunt un neam care nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Acum, Allah v-a ușurat vouă [greutatea], căci El Știe că în voi este slăbiciune. Dar dacă printre voi sunt o sută statornici, ei vor înfrânge două sute, iar dacă printre voi sunt o mie, ei vor înfrânge două mii, cu Voia lui Allah, căci Allah este cu cei statornici.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Un Profet nu ar trebui să ia prizonieri [de război] până când nu a fost cu greutate pe pământ, nimicind [pe dușmanii lui Allah, luptând împotriva lor, învingându-i și punând spaimă în inimile lor, pentru a nu se mai ridica împotriva sa]. Voi [unii musulmani] voiți bunurile acestei lumi, în vreme ce Allah Voiește [pentru voi] Lumea de Apoi, iar Allah este ''Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'De n-ar fi venit mai înainte hotărâre[20] de la Allah, v-ar fi lovit pe voi mare osândă pentru ceea ce ați luat.', '[20] Sunt date trei interpretări pentru cuvântul „hotărâre”: cea prin care companionii de la Badr au fost iertați, cea prin care greșelile neintenționate făcute de credincioși nu sunt pedepsite și cea care a făcut prăzile de război permise.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Deci mâncați voi din cele ce le-ați luat ca pradă de război, [ca fiind] permise și bune, și fiți cu frică de Allah. Cu adevărat, Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'O, Profetule, spune-le celor prinși în mâinile voastre: „Dacă Allah Știe că în inimile voastre se află ceva bun, El vă va Dărui [ceva încă] și mai bun decât ceea ce vi s-a luat și vă va Ierta, căci Allah este Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'Dar dacă ei voiesc să te trădeze, atunci ei L-au trădat deja pe Allah mai înainte și El v-a dat putere asupra lor, căci Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'Cu adevărat, cei care au crezut și au emigrat și au luptat pe calea lui Allah cu averile și cu viețile lor, precum și cei care au dat adăpost și au dat ajutor - își sunt aliați unii altora. Dar cei care au crezut, dar n-au emigrat - voi nu îi veți ajuta până ce nu vor emigra și ei. Iar dacă vă vor cere ajutor, în sprijinul religiei, atunci trebuie să îi ajutați, dar nu împotriva unui neam care are un legământ cu voi, căci Allah este Basir [Cel care Vede] ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Cei care nu cred, își sunt aliați unul celuilalt. Dacă voi nu veți face astfel [să îi luați pe dreptcredincioși drept aliați], va fi fitnah [necredință și asuprire] pe pământ și mare stricăciune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'Dar cei care au crezut și au emigrat și au luptat pe calea lui Allah și cei care au dat adăpost și au dat ajutor - sunt cu adevărat credincioși și ei vor avea parte de iertare și de răsplată îmbelșugată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'Însă aceia care au crezut mai apoi [după emigrarea inițială] și au emigrat [din ținuturile necredinței] luptând alături de voi - sunt de-ai voștri. Iar cei care sunt legați prin rudenie au întâietate unii față de alții [la moștenire], după Legea lui Allah,[21]iar Allah este peste toate Știutor.', '[21] Aceasta se aplică doar rudelor musulmane. Alții pot primi doar prin testament. A se vedea 4:11');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, '[Aceasta este o declarație prin care] s-a disociat Allah și Trimisul Său de aceia dintre politeiști cu care voi ați încheiat legământ[1]', '[1] Dar care l-au încălcat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, '„[O voi necredincioșilor,] călătoriți liber prin țară [timp de] patru luni, dar să știți că voi nu-L veți face pe Allah neputincios și că Allah îi va acoperi de rușine pe necredincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, 'Și [aceasta] este o vestire de la Allah și de la Trimisul Său către oameni în ziua Pelerinajului cel Mare[2] că Allah este dezlegat de politeiști și la fel și Trimisul Său. Dacă vă veți căi, va fi mai bine pentru voi, însă dacă voi vă întoarceți, să știți că nu-L veți putea face pe Allah neputincios[3]! Și vestește-le acelora care nu cred pedeapsă dureroasă.', '[2] Hajj
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Cu excepția acelor politeiști cu care ați încheiat legământ și care nu v-au lipsit pe voi de nimic și nu au sprijinit pe nimeni [în lupta] împotriva voastră! Țineți legământul încheiat de voi până la termenul asupra căruia v-ați învoit cu ei. Cu adevărat, Allah îi Iubește pe cei drepți [care au frică].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Iar când se vor încheia lunile cele sfinte[4], atunci omorâți-i pe idolatri oriunde îi aflați! Prindeți-i, împresurați-i și întindeți-le lor orice cursă. Însă dacă ei se căiesc, împlinesc Rugăciunea [As-Salat] și achită Dania [Az-Zakat], atunci dați-le lor drumul, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '[4] Cele patru luni menționate în versetul 2: Muharram, Rajab, Dhul-Qa`dah și Dhul-Hijjjah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Și dacă vreunul dintre idolatri te roagă să-i dai adăpost, atunci dă-i lui adăpost, pentru ca el să audă Cuvintele lui Allah [Coranul], apoi ajută-l să ajungă la locul său de adăpost. Aceasta pentru că ei sunt un popor care nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Cum să aibă idolatrii un legământ cu Allah și cu Trimisul Său, cu excepția celor cu care voi ați făcut legământ la Moscheea cea Sfântă[5]? Câtă vreme ei sunt drepți cu voi[6], fiți drepți cu ei. Cu adevărat, Allah îi Iubește pe cei care sunt cu frică!', '[5] Al-Masjid al-Haram
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Cum [poate exista un tratat] când ei vă biruiesc pe voi, nu păzesc nici rudenie, nici legământ cu voi? Vă aduc mulțumiri cu gurile lor, însă inimile lor refuză, iar cei mai mulți dintre ei sunt neascultători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'Ei au schimbat Versetele lui Allah pe un preț de nimic și i-au împiedicat [și pe alții] de la calea Lui. Cu adevărat, rău este ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'Ei nu păzesc față de un credincios nici rudenie, nici legământ, iar aceștia sunt cei care întrec măsura în nelegiuirea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Însă dacă ei se căiesc și împlinesc Rugăciunea [As-Salat] și achită Dania [Az-Zakat], atunci ei sunt frații voștri în religie. Iar Noi facem limpezi semnele pentru un popor care știe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'Dar dacă ei încalcă jurămintele după legarea lor și defăimează religia voastră, atunci luptați-vă împotriva căpeteniilor necredinței, căci într-adevăr nu există jurăminte [sacre] pentru ei! Poate că ei vor înceta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Nu v-ați lupta voi împotriva unor oameni care și-au încălcat jurămintele și au vrut să-l alunge pe Trimis și ei au fost cei care v-au atacat mai întâi? Vă temeți de ei? Însă Allah este mai îndreptățit să vă temeți de El, dacă voi sunteți dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Luptați-vă împotriva lor, căci Allah îi va pedepsi prin mâinile voastre și-i va acoperi de rușine și vă va ajuta să-i biruiți și va tămădui piepturile unor oameni dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'Și va alunga mânia din inimile lor! Și Allah va primi căința aceluia de la care El Voiește, căci Allah este Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Sau credeți voi că veți fi lăsați așa, fără ca Allah să-i știe pe cei dintre voi care au luptat și nu au luat ca aliat pe nimeni altcineva decât pe Allah, Trimisul Său și pe dreptcredincioși? Allah este Khabir [Bineștiutor] a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'Nu se cuvine ca politeiștii să întrețină moscheile lui Allah, în vreme ce ei înșiși sunt martorii necredinței lor! Faptele acestora sunt zadarnice și în Foc vor petrece ei veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Ci întrețin moscheile lui Allah doar aceia care cred în Allah și în Ziua de Apoi, împlinesc Rugăciunea [As-Salat], aduc Dania [Az-Zakat] și nu se tem decât de Allah. Poate că aceia vor fi dintre cei bine călăuziți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Considerați voi [sarcina] de a da pelerinilor să bea apă și întreținerea Moscheii celei Sfinte egale cu credința celui care crede în Allah și în Ziua de Apoi și luptă pe calea lui Allah? Ei nu sunt deopotrivă înaintea lui Allah și Allah nu călăuzește neamul de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'Cei care au crezut și au emigrat și au luptat pe calea lui Allah, cu averile și cu viețile lor, sunt pe o treaptă mai înaltă înaintea lui Allah. Și ei sunt cei câștigători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Domnul lor le vestește Îndurarea Lui și Bunăvoință și Grădini pentru ei, în care este plăcere necontenită,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'În care ei vor rămâne în veci. Cu adevărat, Allah are răsplată nesfârșită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'O, voi cei care credeți, nu-i luați pe părinții voștri și pe frații voștri ca aliați, dacă ei iubesc necredința mai mult decât credința. Cei dintre voi care îi iau ca aliați sunt cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'Spune [o, Mohammed]: „Dacă părinții voștri, fiii voștri, frații voștri, soțiile voastre, rudele voastre, bunurile pe care le-ați dobândit, negoțul de al cărui declin vă temeți și locuințele de care sunteți mulțumiți vă sunt vouă mai scumpe decât Allah, decât Trimisul Său și decât lupta pe calea Lui, atunci așteptați-vă să vină Allah cu Porunca Sa.” Iar Allah nu-i călăuzește pe cei nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Allah v-a ajutat să biruiți în numeroase locuri. Și [chiar] în ziua de la Hunayn, când ați fost mândri de numărul vostru mare, însă el nu v-a fost de folos întru nimic. Și îngust vi s-a părut vouă pământul, deși el era întins. Apoi ați întors spatele, fugind.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Apoi, Allah a pogorât liniștea Sa asupra Trimisului Său și asupra dreptcredincioșilor și a trimis soldați [Îngeri] pe care nu i-ați văzut și i-a chinuit pe cei care nu credeau. Aceasta este răsplata necredincioșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Apoi Allah primește căința de la cel care El Voiește, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'O, voi cei care credeți, cu adevărat, politeiștii sunt impuri, deci să nu se mai apropie de Moscheea cea Sfântă după acest [ultim] an al lor. Iar dacă vă temeți de sărăcie, Allah vă va îmbogăți prin Harul Său, dacă va Voi, căci Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Luptați împotriva celor care nu cred în Allah și nici în Ziua de Apoi și nu consideră interzis ceea ce Allah și Trimisul Său au interzis și care nu adoptă Religia Adevărului [Islamul], dintre cei cărora li s-a dat Scriptura – [luptați] până ce ei vor plăti de bună voie jizyah[7], fiind ei supuși.', '[7] O taxă cerută de la nemusulmani prin care aceștia sunt scutiți de la serviciul militar și au dreptul să primească protecție de la statul Islamic. Drept urmare, aceștia nu sunt obligați să plătească zakat-ul, acesta fiind obligatoriu doar pentru musulmani.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Evreii spun: „Ezra este fiul lui Dumnezeu”, iar creștinii spun: „Mesia este fiul lui Dumnezeu” Acestea sunt cuvintele lor, [rostite] cu gurile lor. Ei spun vorbe asemănătoare cu ale celor care nu au crezut mai înainte de ei. Allah să-i nimicească; cum se înșeală ei?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Ei îi iau pe rabinii lor și pe călugării lor, precum și pe Mesia[8], fiul Mariei, ca Domni în locul lui Allah[9], în vreme ce li s-a poruncit să nu adore decât Un Singur Dumnezeu, în afara Căruia nu este [alt] Dumnezeu. Mărire Lui. El este deasupra celor pe care-i asociază Lui.', '[8] Prin adorarea lui împreună cu Allah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'Ei doresc să stingă cu gurile lor Lumina lui Allah, însă Allah nu voiește decât să desăvârșească Lumina Sa, chiar dacă necredincioșii urăsc aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'El este Cel care l-a trimis pe Mesagerul Său cu buna călăuzire și cu religia Adevărului, pentru ca ea să fie biruitoare asupra oricărei alte religii, chiar dacă politeiștii urăsc aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'O, voi cei care credeți, cu adevărat mulți dintre rabini și călugări mănâncă averile oamenilor pe nedrept și [îi] împiedică de la calea lui Allah. Iar celor care strâng[10] aur și argint și nu le cheltuiesc pe calea lui Allah, vestește-le o pedeapsă dureroasă.', '[10] Adună aur și argint și nu plătesc zakat pentru ele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'Într-o Zi în care ele[11] vor fi încinse în focul Iadului și cu ele se vor arde frunțile, laturile și spinările lor. [Li se va spune] „Aceasta este ceea ce ați strâns pentru sufletele voastre, gustați din ceea ce ați strâns.”', '[11] Aurul și argintul ce a fost strâns și pentru care nu s-a plătit zakat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Cu adevărat, numărul lunilor la Allah este de douăsprezece luni în Cartea lui Allah din ziua când El a făcut Cerurile și Pământul. Patru dintre ele sunt sfinte[12]. Aceasta este Religia cea dreaptă. Și nu săvârșiți în timpul lor nedreptate împotriva sufletelor voastre. Și luptați uniți împotriva politeiștilor, întocmai cum luptă ei împreună împotriva voastră. Și să știți că Allah este cu cei care au frică [de El].', '[12] A se vedea 9:5');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Cu adevărat schimbarea [lunilor] nu este altceva decât o sporire a necredinței. Prin aceasta cei care nu cred sunt duși în rătăcire. Un an ei o îngăduiesc[13] și un an o socotesc sfântă, pentru ca să potrivească numărul [lunilor] pe care Allah[14] le-a socotit sfinte. Astfel îngăduiesc ei ceea ce a oprit Allah. Faptele lor rele le sunt înfrumusețate. Și Allah nu călăuzește neamul de necredincioși.', '[13] Lupta în timpul unei luni sfinte
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'O, voi cei care credeți, ce-i cu voi? Când vi s-a zis să purcedeți pe calea lui Allah, voi v-ați lăsat grei pe pământ?[15] Oare v-a plăcut vouă viața lumească mai mult decât Viața de Apoi? Plăcerea acestei vieți nu va fi decât puțină în Lumea de Apoi.', '[15] Înclinând către confortul acestei vieți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Dacă voi nu purcedeți, vă va pedepsi El cu o pedeapsă dureroasă și vă va schimba cu un alt popor și voi nu-I veți putea dăuna întru nimic. Și Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Dacă voi nu-i veniți în ajutor [profetului Mohammed], [să știți că] l-a ajutat Allah [mai înainte], când cei care nu credeau l-au alungat, ca unul dintre cei doi[16]. Când ei doi se aflau în peșteră și el [profetul Mohammed] i-a spus însoțitorului său: „Nu fi mâhnit, căci Allah este cu noi!” Și a pogorât Allah liniștea Sa asupra lui și i-a venit în ajutor cu soldați [Îngeri] pe care voi nu i-ați văzut și a făcut cuvântul celor care nu credeau [să coboare] jos[17], în timp ce Cuvântul lui Allah[18] [s-a înălțat] cel mai sus. Iar Allah este ''Aziz [Puternic] [și] Hakim [Înțelept].', '[16] Al doilea a fost companionul său Abu Bakr
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Purcedeți ușori ori grei[19] și luptați cu averile și sufletele voastre pe calea lui Allah! Aceasta este mai bine pentru voi, dacă pricepeți.', '[19] Tineri sau bătrâni, călare sau pe jos, având o situație ușoară sau grea – în toate circumstanțele și condițiile');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, 'Dacă ar fi fost un câștig ușor sau o călătorie scurtă, atunci ei [ipocriții] te-ar fi urmat, însă distanța li s-a părut lor prea grea și lungă. Și vor jura ei pe Allah[20]: „De-am fi putut noi, am fi purces laolaltă cu voi”, pierzându-se pe ei înșiși [prin jurăminte false], dar Allah Știe că ei sunt mincinoși.', '[20] Atunci când vă întoarceți din expediția de la Tabuk');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, 'Fie ca Allah să te ierte [o, Mohammed, dar] de ce le-ai dat tu voie [să rămână în spate]? [Nu trebuia să faci asta] înainte de a-i descoperi pe cei aflați întru adevăr și de a-i cunoaște pe cei mincinoși?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Nu-ți vor cere îngăduință aceia care cred în Allah și în Ziua de Apoi, când este vorba să lupte cu averile și cu sufletele lor, iar Allah este ''Alim [Bineștiutor] al celor care sunt cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, 'Ci îți cer permisiunea doar cei care nu cred în Allah și în Ziua de Apoi, ale căror inimi s-au umplut de îndoială, căci ei șovăie din pricina îndoielii lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Dacă ei ar fi vrut să purceadă [la luptă], ei ar fi făcut pregătiri pentru aceasta. Însă nu I-a plăcut lui Allah purcederea lor și El i-a oprit și li s-a spus [lor]: „Rămâneți [acasă] cu cei care au rămas.”[21]', '[21] Femeile și copiii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Și de-ar fi purces ei împreună cu voi, n-ar fi făcut decât să sporească tulburarea voastră și s-ar fi grăbit, căutând să semene vrajbă și neînțelegere în rândurile voastre. Și printre voi ar fi fost unii care să le dea ascultare. Dar Allah este ''Alim [Bineștiutor] al nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'Aceștia au căutat mai înainte să semene vrajbă și să-ți încurce ție treburile, până ce a venit Adevărul și a învins religia lui Allah, măcar că lor nu le place.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Printre ei sunt unii care spun: „Permite-mi [să rămân acasă] și nu mă pune la încercare.” Și oare nu în ispită au căzut ei? Și cu adevărat, Iadul îi va cuprinde pe cei necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Dacă ai parte de ceva bun, aceasta îi întristează, iar dacă te lovește o nenorocire, atunci ei spun: „Noi am fost prevăzători dinainte[22]” și se îndepărtează bucuroși.', '[22] Ipocriții au spus că s-au protejat prin rămânerea lor acasă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, 'Spune: „Nu ne va atinge pe noi nimic în afară de ceea ce ne-a prescris Allah, El este Ocrotitorul nostru.” Și în Allah trebuie să se încreadă dreptcredincioșii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'Spune: „Ce așteptați voi, pentru noi, alta decât unul din cele două lucruri minunate [a muri martiri sau victoria] în timp ce noi așteptăm ca Allah să vă lovească cu o pedeapsă dureroasă, fie de la El, fie prin mâinile noastre? Așadar așteptați. Cu adevărat, și noi suntem în așteptare împreună cu voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, 'Spune: „Dacă dăruiți de bunăvoie sau de nevoie oricum nu se va primi niciodată de la voi. Cu adevărat, voi ați fost [și sunteți] un neam de nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'Și ceea ce împiedică să le fie primite darurile lor este faptul că ei nu au crezut în Allah și în Trimisul Său și că ei nu vin la Rugăciune [As-Salat] decât numai cu lene și nu dăruiesc decât obligați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Să nu te uluiască averile sau copiii lor. Allah Voiește numai să-i pedepsească prin ele în această viață și să își dea sufletele [în moarte] ca necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Ei [ipocriții] jură pe Allah că ei sunt cu adevărat dintre voi, însă ei nu sunt dintre voi, ci ei sunt un neam de fricoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Dacă ei ar găsi un adăpost sau peșteri sau orice alt loc în care să intre [să se ascundă], s-ar îndrepta spre acestea, în mare goană.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Și printre ei sunt unii care te critică pentru [împărțirea de] milostenii. De li se dăruiesc lor din acestea, ei sunt mulțumiți, dar de nu li se dăruiesc lor din ele, iată-i cum se înfurie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'Măcar de-ar fi fost ei mulțumiți de ceea ce le-a dăruit Allah și Trimisul Său și ar fi spus: „Ne este de ajuns Allah! Allah ne va dărui din Harul Său și la fel și Trimisul Lui și spre Allah ne îndreptăm noi rugile.” [ar fi fost mai bine pentru ei].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Zakatul este cheltuit numai pentru săraci, pentru sărmani, pentru cei care ostenesc pentru el, pentru aducerea inimilor împreună [în Islam], pentru eliberarea captivilor [sau robilor], pentru cei îndatorați, pentru calea lui Allah și pentru călătorul aflat pe drum. [Aceasta este] Poruncă de la Allah, iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Și printre ei sunt unii care-l necăjesc pe Profet și spun: „El este numai ureche.”[23] Spune: „O ureche pentru binele vostru! El crede în Allah și îi crede pe dreptcredincioși! El este îndurare pentru aceia dintre voi care cred!” Iar cei care-l necăjesc pe Trimisul lui Allah vor avea parte de pedeapsă dureroasă.', '[23] Cineva care crede tot ce aude');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Ei jură pe Allah, pentru ca să vă mulțumească [pe voi, musulmanii]. Însă Allah și Trimisul Său sunt mai îndreptățiți să fie mulțumiți, dacă ei sunt credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Oare nu știu ei că cel care se împotrivește lui Allah și Trimisului Său va avea parte de focul Iadului, în care veșnic va avea sălaș? Și aceasta este mare rușine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Cei ipocriți se tem că va fi pogorâtă despre ei o Sură care să le vestească[24] [dreptcredincioșilor] ceea ce se află în inimile lor. Spune: „Bateți-vă voi joc; cu adevărat, Allah va scoate [la iveală] cele de care voi vă temeți!”', '[24] Să dezvăluie adevărul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Iar dacă-i întrebi, ei vor spune cu siguranță: „Noi vorbeam doar și glumeam!” Spune: „Voi luați în derâdere pe Allah și Versetele Sale și pe Trimisul Lui?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Nu vă dezvinovățiți. Voi v-ați făcut necredincioși după ce ați fost credincioși. Iar dacă Noi iertăm o parte dintre voi, pedepsim o altă parte, pentru că ei sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Bărbații ipocriți și femeile ipocrite sunt unul la fel ca altul. Ei poruncesc ceea ce este interzis și interzic de la ceea ce este permis și-și strâng ei mâinile[25]. Ei l-au uitat pe Allah și i-a uitat și El pe ei. Fățarnicii sunt cei ieșiți din drum.', '[25] Refuză să cheltuiască pe calea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Allah le-a promis bărbaților ipocriți și femeilor ipocrite, precum și necredincioșilor, focul Iadului și veșnic vor sălășlui în el. Aceasta le este de ajuns! I-a blestemat Allah și vor avea ei parte de chin veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, '[Voi necredincioșilor sunteți] ca cei de dinaintea voastră. Ei au fost chiar mai puternici decât voi și au avut mai multe averi și mai mulți copii. Și s-au bucurat de partea lor [în această lume] și v-ați bucurat și voi de partea voastră, așa cum s-au bucurat cei de dinaintea voastră de partea lor. Și vorbiți voi fără de noimă, precum și ei vorbeau fără de noimă. Dar în van sunt faptele acestora atât în această lume, cât și în Lumea de Apoi. Și aceștia sunt pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Nu a ajuns la ei vestea despre cei de dinaintea lor: poporul lui Noe, [tribul lui] ''Ad și Thamud, despre poporul lui Avraam, despre locuitorii din Madyan și despre cetățile cele răsturnate?[26] Trimișii lor le-au adus semne limpezi. Allah nu a voit să le facă nedreptate, ci ei înșiși și-au făcut nedreptate.', '[26] Cele la care a fost trimis profetul Lot și care și-au câștigat pedeapsa lui Allah. A se vedea 11:82-83.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'Dreptcredincioșii și dreptcredincioasele își sunt aliați unii altora. Ei poruncesc ceea ce este cuvenit, opresc de la ceea ce este neîngăduit, împlinesc Rugăciunea [As-Salat], dau Zakat și se supun lui Allah și Trimisului Său. Cu aceștia Allah va fi Îndurător, căci Allah este ''Aziz [Puternic] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Allah le-a promis dreptcredincioșilor și dreptcredincioaselor Grădini pe sub care curg râuri, în care vor avea sălaș veșnic și cămine bune în grădinile Edenului. Însă Mulțumirea lui Allah este și mai mare; aceasta este o Izbândă nemărginită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'O, Profetule, luptă împotriva necredincioșilor și ipocriților și fii aspru cu ei! Iadul va fi sălașul lor și ce sfârșit trist [vor avea ei]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Ei jură pe Allah că nu au spus [nimic împotriva Profetului], însă ei au spus cuvântul necredinței și au respins credința, după [ce au pretins] Islamul lor. Ei au uneltit ceea ce nu au izbutit[27]. Și ei nu au avut alt motiv de reproș în afară de faptul că Allah - ca și Profetul Său - i-a făcut bogați cu Harul Lui[28]. Iar de se vor căi, va fi mai bine pentru ei. Însă de vor întoarce ei spatele, plecând, Allah îi va pedepsi cu un chin dureros atât în această lume, cât și în Lumea de Apoi, și nu vor avea ei pe pământ ocrotitor și nici ajutor.', '[27] Uciderea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Și printre ei sunt unii care au făcut legământ cu Allah [spunând]: „Dacă ne va da nouă din Harul Său, noi vom da milostenii și vom fi dintre cei evlavioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'Dar când El le-a dat din Harul Său, s-au dovedit zgârciți cu El și I-au întors spatele, lepădându-se.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'Astfel i-a pedepsit pe ei cu ipocrizie în inimile lor până în Ziua când se vor întâlni cu El, pentru că ei nu au ținut ce I-au făgăduit lui Allah și pentru că au mințit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Oare nu știu ei că Allah le cunoaște secretele și discuția lor într-ascuns și că Allah este Bineștiutor al lucrurilor necunoscute?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, 'Cei care îi ponegresc pe dreptcredincioșii, care de bunăvoie fac milostenii, dar nu află [pentru a oferi] decât [rodul] trudei lor, și îi iau în derâdere pe ei, pe aceia îi va lua și Allah în derâdere și ei vor avea parte de pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'Roagă-te de iertare pentru ei [o, Mohammed,] sau nu te ruga de iertare pentru ei. Chiar de te vei ruga de iertare pentru ei de șaptezeci de ori, Allah tot nu-i va ierta. Și aceasta pentru că ei nu cred în Allah și în Trimisul Său, iar Allah nu-i călăuzește pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'S-au bucurat cei care au rămas în casele lor, în urma Trimisului lui Allah, și nu au voit să lupte cu bunurile lor și cu sufletele lor pe calea lui Allah și au zis ei: „Nu purcedeți la luptă pe dogoarea aceasta.” Spune: „Focul Gheenei este mult mai dogoritor.” - dacă ei ar pricepe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'Lasă-i să râdă puțin căci [apoi] ei vor plânge mult, drept răsplată pentru ceea ce au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'Dacă Allah te va aduce înapoi la o parte dintre ei [după expediție] și ei îți vor cere îngăduința de a porni [la luptă], spune: „Voi nu veți ieși împreună cu mine niciodată și nu veți lupta alături de mine împotriva vreunui dușman. Cu adevărat, voi ați fost mai mulțumiți să ședeți [acasă] prima dată; ședeți așadar cu cei ce rămân.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'Și nu te ruga [rugăciunea de înmormântare] nicicând pentru vreunul dintre ei care moare și nu sta lângă mormântul lui. Cu adevărat ei nu au crezut în Allah și în Trimisul Său și s-au săvârșit nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Și să nu te uluiască averile și copiii lor, căci Allah Voiește să îi pedepsească prin ele în această lume și ei vor muri necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'Și când este revelată o sură [în care se poruncește]: „Credeți în Allah și luptați împreună cu Trimisul Său”, cei cu stare dintre ei te roagă [să-i scutești de luptă] zicând: „Lasă-ne pe noi să rămânem împreună cu cei care șed [acasă].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Le-a plăcut lor să fie împreună cu cele rămase [acasă]. Inimile lor au fost pecetluite și nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Însă Trimisul și cei care au crezut laolaltă cu el au luptat cu averile și cu sufletele lor. Aceștia vor avea parte de lucrurile bune și aceștia sunt cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Allah a pregătit pentru ei Grădini pe sub care curg râuri, în care ei vor sălășlui veșnic. Iar aceasta este marea izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Și au venit cei care aveau [diverse] motive dintre beduini să ceară îngăduința [de a rămâne acasă], iar cei care L-au mințit pe Allah și pe Trimisul Său au rămas [acasă, fără a cere îngăduință]. Însă pe aceia care nu au crezut dintre ei îi va lovi pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Și nu este niciun păcat pentru cei slabi, nici pentru bolnavi și nici pentru cei care nu au din ce să cheltuiască [pe calea lui Allah], dacă ei sunt sinceri față de Allah și față de Trimisul Său. Împotriva celor care fac bine nu este [cale de învinuire], căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Și nici împotriva acelora care au venit la tine, cerând să-i porți [pe animale de călărie], iar tu le-ai zis: „Nu găsesc pe ce să vă port!” și care s-au întors cu ochii plini de lacrimi, de supărare că ei nu găsesc ce să dea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Ci cale [de învinuire] este numai împotriva acelora care îți cer îngăduință, cu toate că sunt înstăriți. Lor le-a plăcut să fie împreună cu cele rămase. Și a pecetluit Allah inimile lor, însă ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Se vor dezvinovăți față de voi, când vă veți întoarce la ei. Spune: „Nu vă dezvinovățiți, căci noi nu vă vom crede [niciodată]! Allah ne-a prevenit despre veștile voastre.” Și va vedea Allah fapta voastră, precum și Trimisul Său. Apoi veți fi aduși înapoi la Cel care le Știe pe cele nevăzute ca și pe cele văzute[29] și El vă va Vesti cele ce le-ați făcut.”', '[29] A se vedea 6:73');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Ei vă vor jura pe Allah, când voi vă veți întoarce la ei, pentru ca voi să-i lăsați în pace. Îndepărtați-vă de ei, căci ei sunt o spurcăciune, iar sălașul lor va fi Iadul, ca răsplată pentru ceea ce ei au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Vă vor jura vouă ca să fiți mulțumiți de ei. Dar dacă voi veți fi mulțumiți – cu adevărat, Allah nu va fi mulțumit de cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Beduinii sunt mult mai împietriți în necredința și în fățărnicia lor și mult mai probabil să nu cunoască preceptele pe care Allah le-a revelat Trimisului Său. Iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Printre beduini sunt unii care iau ceea ce cheltuiesc [ca milostenie sau pentru război] ca o datorie apăsătoare și pândesc să se abată asupra voastră nenorocirile. Nenorocirea va fi asupra lor! Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'Dar printre beduini sunt unii care cred în Allah și în Ziua de Apoi și iau ceea ce cheltuiesc drept apropiere de Allah și [o cale de obținere a] rugilor Trimisului [în favoarea lor]. Acesta este într-adevăr [un mijloc de] apropiere [de Allah] pentru ei, iar Allah îi va primi sub Îndurarea Lui. Cu adevărat Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Și primii și cei dintâi [credincioși] dintre cei care au purces la pribegie [muhajirun] și sprijinitori [''ansar] și cei care le-au urmat cu bună purtare, - Allah este Mulțumit de ei, precum și ei sunt mulțumiți de El. Și El le-a pregătit Grădini pe sub care curg râuri și veșnic vor sălășlui în ele. Aceasta este marea izbândă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Iar printre beduinii din jurul vostru se află ipocriți, ca și printre locuitorii din Medina, care se îndârjesc în fățărie. Tu nu-i știi, însă Noi îi știm pe ei. Noi îi vom chinui de două ori. Apoi ei vor fi aduși la mare chin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'Și sunt alții care au mărturisit păcatele lor, care au amestecat o faptă bună cu o alta rea[30]. Poate că Allah va primi căința lor, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '[30] Se referă la participarea lor anterioară la luptă, dar la abținerea de a participa în Campania de la Tabuk');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Ia [o, Mohammed] din bunurile lor milostenie, prin care să-i purifici și să-i binecuvântezi și roagă-te pentru ei, căci rugile tale aduc tihnă pentru ei. Iar Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Oare nu știu ei că Allah este Cel care primește căința de la robii Săi și acceptă milostenii și că Allah este Tauuab [Primitorul căinței] [și] Rahim [Îndurătorul]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'Și spune: „Lucrați, căci Allah va Vedea lucrul vostru ca și Trimisul Său și dreptcredincioșii! Și veți fi voi aduși la Cel care le Știe pe cele nevăzute și pe cele văzute și vă va vesti vouă cele pe care le-ați făcut.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Și [există] alții care așteaptă Porunca lui Allah - fie că îi va chinui pe ei, fie că îi va ierta pe ei. Iar Allah este ‘Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'Și [sunt] alți [ipocriți] care au luat o moschee pentru a pricinui daună, necredință și schismă între dreptcredincioși și ca pregătire pentru aceia care au luptat mai înainte împotriva lui Allah și a Trimisului Său și care jură: „Noi nu am vrut decât binele”. Și Allah Mărturisește că aceia sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Să nu te ridici [pentru Rugăciune] în ea, căci o moschee clădită din prima zi[31] pe cucernicie este mai potrivită să te ridici în ea [pentru Rugăciune], fiindcă în ea sunt oameni care doresc să se purifice și Allah îi Iubește pe cei care se purifică.', '[31] Această descriere este a moscheii Quba');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Oare cel care a întemeiat zidirea în credință și frică de Allah și pentru Mulțumirea [Sa] este mai bun sau acela care a întemeiat zidirea pe o margine de prăpastie gata să se surpe, prăbușindu-se cu el în focul Iadului? Iar Allah nu călăuzește neamul de nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Zidirea pe care au înălțat-o nu va înceta să fie pricină de îndoieli în inimile lor, până ce inimile lor nu se vor rupe. Iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Cu adevărat, Allah a cumpărat de la dreptcredincioși sufletele și bunurile lor, în schimbul Raiului. Ei luptă pe calea lui Allah, omorând și fiind omorâți. Aceasta este o promisiune adevărată, pe care a luat-o asupra Lui, în Tora, în Evanghelie și în Coran. Și cine este mai credincios legământului său decât Allah? Bucurați-vă, așadar, pentru negoțul pe care l-ați tocmit, căci aceasta este marea izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, '[Acești credincioși sunt] cei care se căiesc, cei care adoră, cei care aduc laudă, cei care purced prin lume, cei care se pleacă și se prosternează [în rugăciune], cei care poruncesc ceea ce se cuvine și cei care opresc de la cele neîngăduite și cei care păzesc Poruncile lui Allah. Și binevestește-le dreptcredincioșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Nu se cade ca Profetul și cei care cred să ceară iertare pentru politeiști, chiar dacă ei sunt rude, după ce li s-a arătat limpede că ei sunt oaspeții Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'Cererea de iertare a lui Avraam pentru tatăl său nu a fost decât din pricina unei făgăduințe pe care i-a făcut-o. Dar când i-a devenit limpede [lui Avraam] că el [tatăl său] este dușman al lui Allah, atunci s-a dezlegat de el. Avraam era milos și blând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Allah nu duce în rătăcire un popor, după ce l-a călăuzit, până ce nu-i arată limpede de ce trebuie să se ferească [și să îi fie frică]. Allah este peste toate Știutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Cu adevărat a lui Allah este Împărăția Cerurilor și a Pământului. El dă viață și El dă moarte. Și voi nu aveți în afara lui Allah aliat și apărător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Allah a primit căința Profetului, [căința celor] care au purces în peregrinare [Muhajirin] și a sprijinitorilor [Ansar], care l-au urmat la ceasul greului, după ce aproape că se abătuseră inimile unei părți dintre ei. Apoi El i-a iertat, căci El este Ra''uf, [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'Și El [i-a iertat de asemenea] și pe cei trei care au fost lăsați singuri[32], până ce pământul le-a fost lor prea strâmt, cu toate că el era întins[33], iar sufletele lor au devenit și ele prea strâmte și atunci au știut ei că nu este adăpost de Allah decât numai la El. Apoi a primit căința lor, pentru ca ei să se poată întoarce [la El], căci Allah este At-Tauuab [Primitor al căinței] [și] Ar-Rahim [Îndurător].', '[32] Au fost boicotați de ceilalți musulmani, apoi și-au regretat greșeala
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'O, voi cei care credeți! Temeți-vă de Allah și fiți cu cei iubitori de adevăr!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Nu se cuvine ca locuitorii din Medina și beduinii din jurul lor să rămână în urma Trimisului lui Allah, nici să pună sufletele lor mai presus decât sufletul său[34]; aceasta pentru că pe ei nu-i încearcă nici sete, nici trudă, nici foame pe calea lui Allah și ei nu calcă într-un loc care să-i mânie pe necredincioși și nu pricinuiesc niciun rău vreunui dușman, fără ca aceasta să li se scrie lor ca o faptă bună. Cu adevărat, Allah nu pierde răsplata făcătorilor de bine!', '[34] În timp de suferință. Dimpotrivă ei ar trebui să fie dispuși să suporte cu Profetul (pacea și binecuvântarea lui Allah fie asupra sa) orice este necesar pentru Islam.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'Și nu suportă ei nicio cheltuială - nici mică, nici mare - și nu străbat nicio vale fără ca aceasta să li se scrie lor, pentru ca Allah să-i răsplătească pentru cele mai bune [fapte] pe care le împlineau!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'Dreptcredincioșii nu trebuie să purceadă cu toții, ci să purceadă din fiecare grup o parte dintre ei, pentru ca să învețe bine religia și să-i prevină [pe cei din] neamul lor, când se întorc. Poate că ei vor ști să se ferească.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'O, voi cei care credeți, luptați împotriva necredincioșilor de lângă voi. Ei să găsească în voi asprime. Și să știți că Allah este alături de cei care au frică!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'Când este revelat un Capitol, printre ei [ipocriți] sunt unii care spun: „Căruia dintre voi i-a sporit aceasta credința?” Cât despre cei care cred, ea a făcut să le sporească credința și ei se bucură.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'Însă acelora care au boală în inimile lor, [acesta] le va adăuga spurcăciune la spurcăciunea lor[35] și vor muri ei necredincioși.', '[35] Necredință și ipocrizie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Nu bagă ei de seamă că în fiecare an sunt încercați o dată sau de două ori? Și cu toate acestea, ei nu se căiesc și nici nu-și aduc aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'Și când este revelat un Capitol, ei se uită unul la altul, [spunând]: „Vă vede pe voi cineva?” Apoi se îndepărtează ei. Allah a întors inimile lor, pentru că ei sunt un neam care nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'V-a venit vouă un Trimis dintre voi, căruia îi sunt grele necazurile ce vă lovesc, care este plin de grijă pentru voi, iar cu dreptcredincioșii el este milostiv și îndurător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'Iar dacă ei se leapădă [atunci] spune [o, Mohammed]: „Allah îmi este mie de ajuns! Nu există altă divinitate în afară de El! În El mă încred, căci El este Stăpânul Tronului cel Mare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Alif, Lam, Ra''[1]. Acestea sunt Versetele Cărții pline de Înțelepciune[2].', '[1] A se vedea 2:1
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'Sunt oamenii uimiți că Noi am revelat unui bărbat dintre ei [spunând]: „Să-i previi pe oameni și să-i binevestești pe cei care cred că ei vor avea loc meritat[3] la Domnul lor”? [Dar] cei necredincioși spun: „Acesta este un vrăjitor evident.”', '[3] O poziție sigură datorită faptelor lor bune');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Cu adevărat, Domnul vostru este Allah, Cel care a creat Cerurile și Pământul în șase zile, apoi s-a înălțat deasupra Tronului[4], orânduind toate lucrurile. Nu există [vreun] mijlocitor decât cu Voia Lui. Acesta este Allah, Stăpânul vostru, așadar adorați-L pe El. Voi nu chibzuiți?', '[4] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, 'La El este întoarcerea voastră, a tuturor. [Este] promisiunea lui Allah [ce se va împlini] fără niciun dubiu. Cu adevărat, El începe [procesul] creației, apoi o repetă, pentru a-i răsplăti cu dreptate pe cei care cred și săvârșesc fapte bune. Cât despre cei care nu cred, ei vor avea parte de o băutură din apă clocotită și de chin dureros, pentru că nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'Cu adevărat, El este Cel care a făcut Soarele ca o lumină strălucitoare și Luna ca o lumină reflectată și El i-a hotărât fazele, pentru ca voi să cunoașteți numărul anilor și socotirea [timpului]. Allah nu le-a făcut decât pentru [un scop] adevărat. El deslușește semnele pentru oamenii care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'Cu adevărat, în succedarea nopții și zilei și în cele pe care Allah le-a făcut în Ceruri și pe Pământ sunt semne pentru oamenii care au frică [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Cu adevărat, cei care nu așteaptă întâlnirea cu Noi și sunt mulțumiți de viața lumească și se simt în siguranță în ea, precum și aceia care sunt nepăsători față de semnele Noastre,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'Aceștia vor avea ca sălaș Focul, pentru ceea ce ei au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'Cu adevărat, cei care cred și săvârșesc fapte bune, pe ei îi va călăuzi Domnul lor pentru credința lor. Vor curge pe sub ei râuri în Grădinile Plăcerii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Ruga lor în ele va fi „Mărire Ție, O, Allah”, iar salutul lor în ele va fi „Pace [vouă]”, iar sfârșitul rugăciunii lor va fi „Laudă lui Allah, Domnul lumilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Iar dacă Allah ar grăbi pentru oameni răul [pe care ei îl cer] cu repeziciunea cu care El grăbește binele, timpul lor s-ar fi terminat[5]. Dar Noi îi lăsăm pe cei care nu așteaptă întâlnirea cu Noi să bâjbâiască în nelegiuirea lor.', '[5] Allah i-ar fi distrus din această cauză');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'Iar atunci când îl lovește pe om o nenorocire, el Ne cheamă pe Noi, de este el culcat pe o parte, așezat jos sau în picioare. Dar după ce l-am scăpat de nenorocire, el merge mai departe, ca și cum nici nu Ne-ar fi chemat pentru nenorocirea care l-a lovit. Așa le sunt împodobite [faptele] celor nelegiuiți, pe care ei le-au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Iar Noi am făcut să piară deja popoarele de dinaintea voastră, când ele au fost nelegiuite și cu toate că au venit la ele trimișii lor cu semne deslușite, ele nu au crezut. Astfel îi răsplătim Noi pe marii păcătoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Apoi Noi v-am făcut pe voi urmași ai lor pe pământ, pentru a vedea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'Și când li se citesc Versetele Noastre ca dovezi clare, cei care nu așteaptă întâlnirea cu Noi spun: „Adu un alt Coran decât acesta sau schimbă-l!”. Spune [o, Mohammed]: „Nu am eu căderea să-l schimb cu de la mine putere! Eu nu fac decât să urmez ceea ce îmi este revelat. Cu adevărat, eu mă tem, dacă mă răzvrătesc împotriva Stăpânului meu, de pedeapsa unei Zile cumplite!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, 'Spune: „Dacă Allah ar fi Voit, eu nu vi l-aș fi citit și El nu vi l-ar fi făcut cunoscut vouă, căci eu am rămas printre voi vreme îndelungată înainte de el[6]. Voi nu pricepeți?”', '[6] Profetul (pacea și binecuvântarea lui Allah fie asupra sa) a trăit 40 de ani printre poporul său înainte să primească orice revelație');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Și cine este mai nelegiuit decât cel care plăsmuiește minciuni împotriva lui Allah sau neagă Versetele Sale? Cu adevărat, păcătoșii nu vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'Și ei adoră în locul lui Allah ceea ce nici nu le face rău și nici nu le aduce folos și ei spun: „Aceștia sunt mijlocitorii noștri la Allah.” Spune: „Îi vestiți voi lui Allah ceea ce El nu știe din Ceruri și de pe Pământ?” Allah Preamăritul și Preaslăvitul este deasupra celor asociați [Lui].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'Și oamenii nu au fost decât o singură comunitate [unită în religie] și [apoi] s-au deosebit ei. Și dacă nu ar fi fost un cuvânt[7] mai înainte de la Domnul tău, ar fi fost hotărât pentru ei [imediat lucrul] asupra căruia ei au avut păreri diferite.', '[7] Allah hotărăște să-i acorde creației Lui timp pe pământ sau să nu pedepsească pe nimeni înainte ca dovada să ajungă la el');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, 'Și ei spun: „De ce nu i se trimite lui un semn de la Domnul său?” Spune: „Cele neștiute sunt numai la Allah! Așteptați și voi fi și eu împreună cu voi printre cei care așteaptă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'Și când le-am dat Noi oamenilor să guste Îndurare, după o nenorocire care i-a lovit, imediat ei conspiră împotriva Versetelor Noastre. Spune: „Allah este și Mai Priceput în a plănui. Cu adevărat Trimișii Noștri [Îngerii] scriu ceea ce voi vicleniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'El este Cel care vă ajută să umblați pe uscat și pe mare. Dar când sunt ei[8] în corăbii, mânate de vânturi prielnice, bucurându-se de ele, asupra lor se abate vânt năprasnic și se năpustesc peste ei valuri din toate părțile și ei își închipuie că sunt cuprinși, atunci Îl cheamă ei [numai] pe Allah, cu credință în religia Lui: „Dacă ne vei mântui de aceasta, noi vom fi printre cei care Îți aduc mulțumire.”', '[8] Schimbarea pronumelui de la persoana a doua la persoana a treia arată că descrierea următoare se aplică în mod special');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'Dar după ce i-a mântuit El, ei imediat se răzvrătesc pe pământ, fără dreptate. O, oameni, răzvrătirea voastră este doar împotriva sufletelor voastre [fiind doar] o plăcere [trecătoare] a vieții pământești. Apoi întoarcerea voastră va fi la Noi și atunci vă vom Vesti Noi ceea ce ați făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Pilda vieții lumești este, cu adevarat, asemenea ploii pe care Noi o pogorâm din Cer, pe care plantele pământului o absorb – [și] din care mănâncă oamenii și vitele - până când pământul își ia podoaba sa și se împodobește. Dar când sălășluitorii săi cred că ei sunt stăpâni peste el, iată că peste el vine Porunca Noastră, în timpul nopții sau în timpul zilei, și îl prefacem în miriște[9], ca și cum în ajun n-ar fi fost plin de bogăție. Astfel tâlcuim Noi semnele pentru un neam care cugetă.', '[9] Vegetația sa a fost tăiată sau dezrădăcinată, cu alte cuvinte distrusă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Și Allah cheamă la Casa Păcii [Paradis] și-l călăuzește pe cel care Voiește El pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'Cei care fac bine vor avea parte de cea mai bună [răsplată], și încă și mai mult[10]. Chipurile lor nu vor fi acoperite nici de negreală, nici de umilință. Aceștia vor fi oaspeții Raiului și ei în el vor petrece veșnic.', '[10] Pe lângă plăcerile Paradisului, aceștia vor putea să Îl vadă pe Allah, așa cum este relatat într-un hadis autentic înregistrat de Muslim.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'Însă cei care agonisesc fapte rele vor avea parte de răsplată rea, pe măsura lor, și îi va acoperi umilința. Ei nu vor avea niciun apărător de la Allah. Va fi ca și cum chipurile lor ar fi acoperite cu bucăți întunecoase de noapte. Aceștia vor fi oaspeții Focului și în el vor avea ei sălaș veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'Și [spune, o, Mohammed,] de Ziua în care îi vom aduna pe ei toți și atunci le vom zice Noi celor care I-au făcut asociați [lui Allah]: „[Rămâneți] la locul vostru, împreună cu asociații voștri[11]” Apoi Noi îi vom despărți pe unii de alții, iar asociații lor vor spune: „Voi nu ne-ați adorat pe noi,', '[11] Cei făcuți asociați cu Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Allah este de ajuns ca Martor între noi și voi că noi nu am știut de adorarea voastră.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Acolo [în acea Zi] fiecare suflet va încerca [urmările] celor săvârșite mai înainte, iar ei vor fi întorși la Allah, Domnul lor Cel Adevărat, și se va îndepărta de ei ceea ce au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'Spune: „Cine vă dă vouă hrană îndestulătoare din Cer și de pe pământ? Și cine este Stăpân peste auz și peste văz și-l scoate pe cel cu viață din cel fără viață și-l scoate pe cel fără viață din cel cu viață și Cel care orânduiește toate lucrurile?” Ei vor răspunde: „Allah” Atunci spune: „Oare nu aveți voi frică de El?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'Acesta este Allah, Domnul vostru Cel Adevărat. Și ce poate fi dincolo de Adevăr decât numai rătăcirea? Și cum puteți voi fi îndepărtați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Așa se adeverește Cuvântul [Hotărârea] Domnului tău împotriva celor care sunt nelegiuiți - într-adevăr, ei nu vor crede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'Spune: „Se află printre asociații voștri vreunul care să creeze o făptură și să o readucă [la viață după moarte]?” Spune: „Allah creează făptura și apoi o readuce [la viață]. Cum de puteți voi să stați departe de adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'Spune: „Se află printre asociații voștri cineva care să călăuzească spre Adevăr?” Spune: „Allah călăuzește spre Adevăr! Și este mai vrednic să fie urmat Cel care călăuzește spre Adevăr sau cel care nu călăuzește decât dacă este el însuși călăuzit? Ce este cu voi? Cum de judecați astfel?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Cei mai mulți dintre ei nu urmează decât bănuieli. Cu adevărat, bănuielile nu ajută cu nimic față de Adevăr. Iar Allah este Bineștiutor a ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Nu este [posibil] ca acest Coran să fie făcut de altcineva în fără de Allah, ci este confirmarea celor de dinaintea lui și o explicație a Scripturilor [anterioare], despre care nu este nicio îndoială[12] că el este venit de la Stăpânul Lumilor.', '[12] Această frază se referă din nou la Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'Sau spun ei [despre Profet (pacea și binecuvântarea lui Allah fie asupra sa)]: „L-a născocit [Mohammed]?” Spune: „Aduceți voi o sură asemănătoare lui și chemați pe cine puteți, în afară de Allah, dacă voi sunteți întru adevăr.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Dimpotrivă, ei luaseră drept minciună ceea ce nu puteau cuprinde prin cunoașterea lor, căci nu le venise încă tâlcuirea lui. Așa au făcut și cei de dinaintea lor și privește care a fost sfârșitul nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Și printre ei sunt unii care cred în el, și printre ei sunt alții care nu cred în el. Dar Domnul tău îi Cunoaște cel mai bine pe cei care fac stricăciune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'Iar dacă ei te învinuiesc pe tine [o,Mohammed,] de minciună, atunci spune: „Ale mele sunt faptele mele și ale voastre sunt faptele voastre! Voi nu sunteți răspunzători de ceea ce fac eu, iar eu nu sunt răspunzător de ceea ce faceți voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'Și printre ei sunt unii care te ascultă. Dar poți să-i faci pe surzi să audă, când ei nu pricep?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'Și printre ei sunt unii care privesc la tine. Dar poți tu să-i călăuzești pe orbi, când ei nu văd?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Cu adevărat, Allah nu-i nedreptățește pe oameni întru nimic, ci oamenii sunt cei nedrepți față de ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'Și [în] Ziua în care El îi va aduna va fi ca și cum ei nu ar fi rămas [în viață] decât un ceas dintr-o zi, și ei se vor cunoaște reciproc. Vor pierde cei care au negat întâlnirea cu Allah și nu au fost călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Și fie că îți arătăm o parte din cele cu care îi amenințăm pe ei [o, Mohammed], fie că te luăm pe tine la Noi, la Noi este întoarcerea lor. Și Allah este Martor pentru ceea ce ei săvârșesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'Și fiecare comunitate are un Trimis, iar când vine Trimisul lor, se va face judecată între ei cu dreptate, iar ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Și ei spun: „Și când se împlinește această promisiune, dacă voi sunteți întru adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'Spune: „Eu nu am nicio putere spre dăunarea sau spre folosul meu, în afară de ceea ce Voiește Allah. Fiecare comunitate are un termen [specific] și când le sosește termenul, ei nu-l pot întârzia nici măcar cu un ceas și nici nu-l pot grăbi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'Spune: „V-ați gândit: dacă vă va veni pedeapsa Lui în timpul nopții sau în timpul zilei - ce ar putea păcătoșii să grăbească din ea?”[13]', '[13] „Grăbească” se referă la batjocorirea Profetului (pacea și binecuvântarea lui Allah fie asupra sa) de către necredincioși, spunându-i să cheme pedeapsa lui Allah drept dovadă a adevărului său');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, 'Și atunci când va veni, veți crede voi în ea? Acum[14] credeți voi în ceea ce ați voit să grăbiți.[15]', '[14] Când este prea târziu să beneficieze de credință
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Apoi li se va zice celor care au fost nedrepți: „Gustați voi chinul cel veșnic! Sunteți voi răsplătiți cu altceva decât cu ceea ce v-ați agonisit?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, 'Și ei îți cer ție [o, Mohammed] deslușire: „Este adevărat?” Spune: „Da! [Jur] pe Domnul meu, acest lucru este adevărat și voi nu-l veți putea împiedica!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Și dacă fiecare suflet care a fost nedrept ar avea tot ceea ce se află pe pământ, l-ar oferi ca răscumpărare. Ei își vor ascunde remușcarea, când vor vedea chinul. Dar se va judeca între ei cu dreptate și ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Cu adevărat, ale lui Allah sunt cele din Ceruri și de pe Pământ. Cu adevărat, făgăduința lui Allah este adevărată, dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'El este Cel care dă viață și Cel care dă moarte și la El vă veți întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'O, oameni! V-a venit vouă îndemn de la Domnul vostru și tămăduire pentru ceea ce este în piepturi, călăuzire și îndurare pentru dreptcredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'Spune: „De Harul lui Allah și de Îndurarea Sa să se bucure, căci ele sunt mai bune decât toate cele pe care le strâng ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'Spune: „Vedeți ce v-a pogorât Allah drept mijloace de viețuire?! Iar voi ați interzis o parte dintre ele și ați îngăduit [o altă parte]”. Spune: „V-a permis Allah acestea sau voi născociți împotriva lui Allah?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'Și ce părere vor avea în Ziua Învierii[16] cei care au născocit minciuni împotriva lui Allah? Cu adevărat, Allah este Dătător de Har oamenilor, dar cei mai mulți dintre ei nu sunt mulțumitori.', '[16] Ce vor crede că El va face cu ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, 'Și tu [o, Mohammed] nu vei fi în nicio împrejurare și nu vei recita niciun fragment din Coran, iar voi [oamenilor] nu veți împlini nicio faptă fără ca Noi să fim Martori în clipa când o săvârșiți. Domnului tău nu-i va scăpa nici cât greutatea unui atom[17] - nici de pe Pământ, nici din Cer -, nici cât [o greutate] mai mică [decât aceasta] și nici mai mare, fără ca acestea să [fie înscrise] într-o carte limpede.', '[17] Sau „greutatea unei furnici mici”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Cu adevărat, aliații lui Allah nu au motive să se teamă și nici nu vor fi mâhniți -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'Cei care cred și care au frică de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'Pentru ei este bună veste în această viață, și în Lumea de Apoi. Cuvintele [decretul] lui Allah [nu vor cunoaște] nicio schimbare. Aceasta este marea izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Și să nu te întristeze vorbele lor. Cu adevărat, onoarea [datorată puterii] este a lui Allah. El este As-Sami’ [Cel care Aude Totul], Al-’Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'Cu adevărat, ai lui Allah sunt atât cei din Cer, cât și cei de pre Pământ. Și ce urmează aceia care invocă semeni în locul lui Allah? Ei nu urmează decât bănuieli și ei nu fac altceva decât să mintă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'El este Cel care v-a făcut vouă noaptea să vă odihniți în ea și ziua ca să [vă îngăduie să] vedeți[18]. Iar în aceasta sunt semne pentru un popor care ascultă.', '[18] Făcând lucrurile vizibile');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, 'Ei[19] spun: „Allah și-a luat un fiu.” Preaslăvitul este Al-Ghaniyy [îndeajuns de Înstărit]. Ale Lui sunt [toate] cele din Ceruri și cele de pe Pământ. Voi nu aveți nicio dovadă pentru acest lucru. Oare spuneți voi împotriva lui Allah ceea ce nu știți?', '[19] Creștinii și alții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, 'Spune: „Cei care născocesc pe seama lui Allah minciuni nu vor izbuti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, '[Pentru ei este] plăcere trecătoare în această lume. Apoi la Noi este întoarcerea lor, iar Noi îi vom face atunci să guste chinul aspru pentru că nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Și spune-le povestea lui Noe, când el i-a spus poporului său: „O, popor al meu, dacă vă este prea grea șederea mea [printre voi] și pomenirea de către mine a semnelor lui Allah, atunci să știți că eu în Allah mă încred. Înțelegeți-vă, așadar și [chemați-vă] „asociații” voștri și nu ascundeți planurile voastre. Apoi luați hotărârea în privința mea, fără să-mi mai dați vreun răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, 'Iar dacă vă veți lepăda [de sfatul meu] - eu nu v-am cerut răsplată, căci răsplata mea nu este decât de la Allah și mie mi s-a poruncit să fiu dintre cei supuși Voinței lui Allah [musulmani]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Și ei l-au socotit mincinos, astfel că Noi l-am mântuit împreună cu cei care au crezut cu el în corabie și i-am făcut pe ei urmași. Iar pe cei care nu au acceptat semnele Noastre i-am înecat. Deci privește cum a fost urmarea celor preveniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Apoi am trimis Noi, după el, Trimiși la popoarele lor și ei au venit cu semne deslușite. Dar ei nu au crezut în ceea ce luaseră drept minciună mai înainte. Și astfel pecetluim Noi inimile celor care întrec măsura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'După aceea i-am trimis Noi, după ei, pe Moise și pe Aaron cu semnele Noastre la Faraon și căpeteniile sale, însă ei s-au arătat îngâmfați și au fost un popor de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'Și când a ajuns la ei Adevărul din partea Noastră, ei au spus: „Aceasta este vrăjitorie evidentă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, 'Moise a spus: „Spuneți voi despre Adevăr, după ce a venit el la voi, că aceasta este vrăjitorie? Atunci [aflați] că vrăjitorii nu vor izbândi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'Ei au spus: „Ai venit la noi ca să ne abați de la cele în care i-am găsit pe părinții noștri, pentru ca voi doi să aveți puterea pe acest pământ? Dar noi nu credem în voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'Și Faraon a spus: „Aduceți-mi toți vrăjitorii învățați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'Și când au venit vrăjitorii, Moise le-a spus: „Aruncați ceea ce aveți voi de aruncat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'Și când ei au aruncat, Moise a spus: „Ceea ce ați adus voi este [doar] vrăjitorie. Cu adevărat, Allah o va zădărnici, căci Allah nu încurajează fapta celor care aduc stricăciune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Și Allah va consacra Adevărul prin Cuvintele Sale, chiar dacă păcătoșilor nu le place.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'Dar nu a crezut nimeni în [Mesajul lui] Moise decât un grup de oameni din neamul lui [Faraon] și apoi le-a fost teamă că Faraon și căpeteniile sale îi vor persecuta, căci Faraon era un tiran puternic peste acest pământ și era dintre cei necumpătați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'Și Moise a spus: „O, popor al meu! Dacă voi credeți în Allah, încredeți-vă în El, dacă sunteți musulmani [supuși lui Allah]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, 'Și ei au răspuns: „În Allah ne încredem. Doamne, nu ne face pre noi [țintă a] urgisirii poporului de nelegiuiți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'Și izbăvește-ne pe noi, cu Mila Ta, de cei necredincioși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'Și Noi le-am revelat lui Moise și fratelui său: „Pregătiți case pentru poporul vostru în Egipt și faceți în casele voastre loc de rugăciune[20] și împliniți Rugăciunea [As-Salat] și binevestește credincioșilor.”', '[20] Pentru a se putea ruga fără să fie văzuți de către dușmani');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'Și Moise a spus: „Doamne! Tu ai dăruit lui Faraon și căpeteniilor sale podoabe și averi în această viață, Doamne, ca să-i rătăcească [pe oameni] de la drumul Tău! Doamne, nimicește averile lor și pecetluiește inimile lor ca să nu creadă ei până ce nu vor vedea pedeapsa cea dureroasă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, '[Allah] a spus: „Rugămintea voastră a fost acceptată[21]. Mergeți pe calea cea dreaptă și nu urmați calea celor care nu știu!”', '[21] Literar: „rugămintea amândurora” adică cea a lui Moise și a lui Aaron, care i s-a alăturat spunând „Amin”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'Și Noi i-am trecut pe Fiii lui Israel prin mare și Faraon și soldații lui i-au urmărit ca să-i prigonească și să-i nimicească până când l-a ajuns pe el înecul și a spus: „Eu cred că nu există altă divinitate în afară de Cel în care cred Fiii lui Israel și eu sunt [acum] printre cei supuși [musulmani]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, '[Allah a spus]: „Acum? După ce mai înainte tu te-ai răzvrătit și ai fost dintre stricători?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, 'Astăzi îți vom salva Noi trupul[22], pentru ca să fii un semn pentru cei [care vor veni] în urma ta.” Însă mulți dintre oameni sunt nepăsători față de semnele Noastre!', '[22] Corpul său mort va fi păstrat și nu va fi distrus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'Și Noi le-am pregătit Fiilor lui Israel locuință sigură, și le-am dat lor hrană din bunătăți. Și ei nu s-au certat până ce nu a venit la ei știința. Cu adevărat, Domnul tău va judeca între ei în Ziua Învierii cu privire la cele întru care nu s-au înțeles.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'Iar dacă tu [o, Mohammed,] ai îndoială asupra celor pe care ți le-am trimis, atunci întreabă-i pe cei care au citit Cartea revelată mai înainte de tine. Ți-a venit Adevărul de la Domnul tău. Așadar, nu fi printre cei care au îndoieli!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'Și să nu fii printre aceia care țin de mincinoase semnele lui Allah, căci vei fi printre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'Cu adevărat, cei împotriva cărora se va adeveri Cuvântul [de amenințare al] Domnului tău nu vor crede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'Chiar dacă le-ar veni lor toate semnele, până ce nu vor vedea pedeapsa dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'Și nu a fost nicio cetate care să creadă [după ce le-a fost hotărâtă pedeapsa pentru nelegiuirea lor] și căreia credința ei să-i fi fost de folos [în îndepărtarea pedepsei], în afară de cetatea poporului lui Iona, care, după ce a crezut, i-am mântuit Noi [pe locuitorii ei] de chinul rușinii în viața lumească și le-am dat Noi lor bucurie până la un timp.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Și de-ar fi Voit Domnul tău, toți cei de pe pământ ar fi crezut laolaltă! Și oare tu [o, Mohammed] îi silești pe oameni ca să fie credincioși?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Nu poate niciun suflet să creadă, decât cu Voia lui Allah. Și El va trimite pedeapsă împotriva acelora care nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, 'Spune: „Priviți la cele care sunt în Ceruri și pe Pământ!” Însă nici semnele și nici prevenitorii nu sunt de ajuns pentru un neam [de oameni] care nu cred!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Și oare așteaptă ei altceva decât zile asemănătoare cu ale acelora de dinaintea lor? Spune: „Așteptați, așadar. Cu adevărat voi fi și eu printre cei care așteaptă laolaltă cu voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Atunci îi vom salva Noi pe Trimișii Noștri și pe cei care au crezut. Astfel, cu adevărat este de datoria Noastră, să-i salvăm pe dreptcredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, 'Spune [o, Mohammed]: „O, oameni! Dacă sunteți cu îndoială asupra religiei mele, atunci [să știți că] eu nu îi ador pe cei pe care îi adorați în afară de Allah, ci Îl ador pe Allah, Cel care vă va lua la Sine, căci mie mi s-a poruncit să fiu dintre dreptcredincioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, 'Și [mi s-a poruncit]: „Ridică-ți fața către Religia adevărată și nu fi dintre idolatri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'Și nu chema în locul lui Allah ceea ce nu-ți este spre folos și nici spre stricăciune, căci de vei face [aceasta], tu vei fi dintre cei nelegiuiți!”[23]', '[23] A se vedea 10:95');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Și dacă Allah te atinge cu un rău, [să știi că] nu este cine să-l îndepărteze decât numai El! Iar dacă El îți Voiește un bine, nu este nimeni care să poată respinge Harul Său. El îi atinge cu acesta pe cei care Voiește El dintre robii Săi, iar El este Al-Ghafur [Iertător], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, 'Spune: „O, oameni! V-a venit Adevărul de la Domnul vostru și acela care se călăuzește, este călăuzit doar pentru sine, iar acela care rătăcește, el duce în rătăcire numai sufletul său. Iar eu nu sunt păzitor peste voi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Și urmează ceea ce-ți este revelat [o, Mohammed] și fii cu răbdare până ce Allah va Judeca, fiindcă El este Cel mai Bun dintre judecători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Alif, Lam, Ra''[1]. [Aceasta] este o Carte ale cărei Versete sunt bine întocmite, apoi tâlcuite de către un Înțelept [Hakim], Khabir [Bineștiutor].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, '[Printr-un Mesager, spunând]: „Nu-L adorați decât pe Allah. Cu adevărat eu sunt [Trimis] pentru voi de la El, ca prevenitor și vestitor de bine,”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, 'Și [spunând]: „Rugați-vă de iertare la Domnul vostru și întoarceți-vă, căindu-vă, la El [și] El vă va ajuta să vă bucurați de o plăcere frumoasă până la un timp anumit și-i va da fiecăruia care merită răsplata cuvenită. Însă dacă vă veți întoarce, atunci cu adevărat, eu mă tem pentru voi de chinul unei Zile mari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'La Allah este întoarcerea voastră și El este cu Putere peste toate.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Cu adevărat ei [necredincioșii] își închid piepturile, pentru a se ascunde de El. Dar chiar dacă se învelesc ei, ascunzându-se în veșmintele lor, El Știe atât ceea ce țin ei ascuns, cât și ceea ce destăinuiesc, căci El este ''Alim [Bineștiutor] al lăuntrului piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'Și nu este viețuitoare pe pământ a cărei hrană să nu fie în Grija lui Allah. El Știe locul ei de sălaș și locul în care ea va muri. Totul este într-o Carte deslușită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'Și El este Cel care a creat Cerurile și Pământul în șase zile - în vreme ce Tronul Său era deasupra apei - pentru ca să vă cerce care dintre voi este mai bun în făptuire. Iar dacă tu spui: „Veți fi voi înviați după moarte”, cei care nu cred, vor zice: „Aceasta nu este decât vrăjitorie evidentă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Iar dacă Noi întârziem pedepsirea lor până la un timp anumit, atunci ei spun[2]: „Ce o oprește pe ea?” Cu adevărat, în ziua când va veni la ei, nici unul dintre ei nu va mai fi ferit [de ea] și îi va cuprinde ceea ce ei au luat în derâdere.', '[2] Cu batjocoră și necredință');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'Dacă Noi îi dăm omului să guste Îndurare din partea Noastră, iar apoi o luăm de la el, atunci el este deznădăjduit și nemulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'Dacă, însă, Noi îi dăm să guste bucurie după ce l-a atins o nenorocire, atunci el va spune: „S-au dus relele de la mine.” Și, cu adevărat, el va fi bucuros și mândru,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Mai puțin cei care sunt cu răbdare și săvârșesc fapte bune. Ei vor avea parte de iertare și de răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Atunci s-ar putea ca tu să neglijezi o parte din ceea ce îți este revelat[3] și pieptul tău să fie strâns la ea, când ei vor zice: „De ce nu s-a pogorât asupra lui o comoară?” sau „De ce nu a venit împreună cu el un Înger?” Tu nu ești decât un prevenitor, iar Allah este a toate Ocrotitor.', '[3] Cunoscând dificultățile Profetului (pacea și binecuvântarea lui Allah fie asupra sa) Allah îl îndeamnă la răbdare, fiind sigur că acesta nu va eșua în a transmite mesajul complet');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, 'Sau ei vor spune: „El l-a născocit”? Spune: „Așadar, aduceți voi zece sure, asemeni lui, născocite [de voi] și chemați pe cine puteți [în ajutor] în afară de Allah, dacă sunteți voi întru dreptate.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'Și dacă nu vă răspund - atunci să știți că el [Coranul] a fost trimis prin Știința lui Allah[4] și că nu există altă divinitate în afară de El. Și[5], oare [nu] veți fi voi [supuși lui Allah] musulmani]?', '[4] Știința pe care doar Allah o are
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'Pe cei care doresc viața lumească și podoaba ei îi vom răsplăti Noi după faptele lor în ea[6], fără să li se scadă lor nimic din ele.', '[6] În viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'Aceștia sunt cei care în Lumea de Apoi nu vor avea decât Focul. Și zadarnic va fi ceea ce au săvârșit ei în ea[7] și în deșert va fi ceea ce au făcut.', '[7] În viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Și oare acela care se bizuie pe un semn deslușit de la Domnul său și care este recitat de un martor din partea Sa, în vreme ce înainte de el a fost Cartea lui Moise drept ghid și îndurare [este mai bun decât acela care nu se bizuie pe niciun semn]? Aceștia cred în el, însă acele cete care nu cred în el au drept fãgăduință Focul. Nu fi în îndoială asupra lui, căci el este Adevărul de la Domnul tău, dar cei mai mulți dintre oameni nu cred!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'Și cine este mai nelegiuit decât cel care născocește pe seama lui Allah minciună? Aceia vor fi aduși dinaintea Domnului lor, iar martorii vor spune: „Aceștia sunt cei care au mințit împotriva Domnului lor!” Fără îndoială, blestemul lui Allah este asupra nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'Care [îi] împiedică [pe oameni] de la calea lui Allah și încearcă să o facă deviantă. Ei sunt cei care nu cred în Viața de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Aceia nu pot să-[L] facă neputincios [pe Allah] pe pământ și nici nu au alți aliați pentru ei, în afară de Allah, iar pedeapsa lor va fi înmulțită. Ei nu au putut să audă și nici nu au văzut[8].', '[8] Au refuzat să asculte adevărul sau să îl înțeleagă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'Aceia sunt cei care și-au pierdut sufletele și s-a îndepărtat de ei ceea ce ei au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'Fără îndoială, în Lumea de Apoi ei vor fi cei mai pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'Cu adevărat, cei care cred și săvârșesc fapte bune și sunt umili înaintea Domnului lor, aceia sunt oaspeții Raiului și în el vor sălășlui veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Exemplul celor două cete este ca și cel al orbului și al surdului cu cel care vede și aude. Sunt cele două egale la comparație? Atunci, de ce nu luați voi aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'Noi l-am trimis pe Noe la neamul său [și el a spus]: „Cu adevărat, eu sunt pentru voi prevenitor limpede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'Pentru ca voi să nu-L adorați decât pe Allah. Cu adevărat eu mă tem pentru voi de chinul unei zile dureroase”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Și căpeteniile dintre cei care nu au crezut din neamul lui au spus: „Noi nu vedem în tine decât un om ca și noi și nu vedem să te fi urmat pe tine decât cei care sunt vrednici de dispreț dintre noi și fără pic de chibzuință. Noi nu vedem să aveți niciun merit față de noi, ci vă socotim mai degrabă niște mincinoși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, 'El a spus: „O, popor al meu, v-ați gândit: dacă eu am o dovadă limpede de la Domnul meu și El mi-a dat Îndurare de la El, dar ochilor voștri le scapă, să vă silim noi la aceasta, dacă voi o urâți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'Și o, popor al meu, eu nu vă cer vouă vreo avere în schimb, căci răsplata mea nu se află decât la Allah. Și nici nu-i voi alunga eu pe cei care cred. Cu adevărat, ei Îl vor întâlni pe Domnul lor[9]. Însă eu văd că voi sunteți un neam de ignoranți.', '[9] În Ziua Învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'Și o, neam al meu! Cine mă va ajuta pe mine împotriva [pedepsei] lui Allah dacă eu i-aș alunga? Oare nu vă amintiți voi [ceea ce v-ar fi de folos]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Și eu nu vă spun că eu am Comorile lui Allah sau că eu știu neștiutul. Nici nu spun că eu sunt un Înger și nici nu spun acelora pe care ochii voștri îi disprețuiesc că Allah nu le va Dărui lor bine. Allah Știe mai bine ce se află în sufletele lor, iar eu aș fi atunci dintre cei nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, 'Ei[10] au spus: „O, Noe! Te-ai certat cu noi și prea mult te-ai certat. Adu-ne nouă cele cu care ne ameninți, dacă tu ești dintre cei care spun adevărul!”', '[10] Poporul său i-a spus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, 'El le-a răspuns: „Allah o să vi le aducă dacă El Voiește, iar voi nu-L veți putea împiedica.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, 'Și sfatul meu nu vă va folosi - deși mi-aș dori să vă sfătuiesc - dacă Allah Voiește să vă ducă în rătăcire. El este Stăpânul vostru și la El veți fi întorși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Sau spun ei [despre profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)]: „L-a născocit!” Spune: „Dacă eu l-am născocit, atunci eu răspund pentru păcatul meu, însă eu sunt nevinovat de cele pe care le săvârșiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'Și i s-a revelat lui Noe că: „Nimeni din neamul tău nu va crede, decât cei care deja au crezut, dar tu nu te întrista pentru ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'Și construiește arca sub ochii Noștri și după inspirația Noastră și nu-Mi pomeni despre cei care au fost nelegiuiți. Cu adevărat, ei sunt înecați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'Și el lucra la corabie și de câte ori trecea pe lângă el câte o căpetenie din poporul său, îl luau în derâdere. Însă el le-a zis: „Dacă râdeți de noi, vom râde și noi de voi, asemenea cum râdeți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'Și veți afla voi cui îi va veni chinul care-l va umili [pe pământ] și peste cine va veni chinul dăinuitor [în Ziua de Apoi]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, '[Așa a fost] până când a venit porunca Noastră și s-a învolburat[11] cuptorul. Noi am spus: „Adu pe ea [pe arcă] din fiecare [seminție] câte doi soți și familia ta – în afară de cei împotriva cărora hotărârea a fost deja dată - și pe cei care au crezut”. Însă nu au crezut împreună cu el decât puțini.', '[11] Ca un semn pentru Noe că va urma potopul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'Și [Noe] a spus: „Urcați-vă pe ea. În Numele lui Allah va fi mersul ei și ancorarea [oprirea] ei. Cu adevărat, Domnul meu este Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'Și când a purces cu ei printre valuri ca munții, l-a strigat Noe pe fiul său, care stătea deoparte: „O, fiul meu! Urcă împreună cu noi, nu fi laolaltă cu necredincioșii.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, 'Dar a răspuns [fiul]: „Voi găsi refugiu pe un munte ce mă va apăra de apă”. [Noe] i-a spus: „Astăzi nu este apărător de Porunca lui Allah, în afară de cel cu care El este Îndurător.” Și valurile i-au despărțit pe ei doi, iar el a fost printre cei înecați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'Și a fost spus[12]: „O, pământule, înghite apa ta și o, Cerule, încetează [cu ploaia]!” Și a scăzut apa și s-a împlinit porunca, iar ea [arca] s-a așezat pe muntele Al-Judi. Și a fost spus: „Să piară neamul de nelegiuiți.”', '[12] Allah a poruncit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'Și Noe L-a chemat pe Domnul său și a spus: „Doamne, fiul meu este din familia mea și, cu adevărat, Făgăduința Ta este Adevărul, iar Tu ești Cel mai Drept dintre cei drepți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, 'El a spus: „O, Noe! El nu este din familia ta. Cu adevărat, el este [dintre cei care au săvârșit] o faptă necinstită. Nu-Mi cere aceea despre care tu nu ai știință! Eu te îndemn pentru ca tu să nu fii printre cei neștiutori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, '[Noe] a spus: „Doamne, eu caut adăpost la Tine de a Te întreba despre cele în privința cărora eu nu am cunoștință; și de nu mă vei ierta și nu vei fi Îndurător cu mine, voi fi eu printre cei pierduți”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, 'A fost spus: „O, Noe! Coboară cu pace din partea Noastră și cu binecuvântări asupra ta și asupra comunităților ce se vor ivi dintre acei care sunt cu tine. Iar pe alte comunități le vom lăsa să aibă parte de bucurie trecătoare și pe ele le va ajunge apoi chin dureros [venind] de la Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'Acestea sunt câteva vești despre cele neștiute, pe care Noi ți le revelăm [o, Mohammed,] și pe care nu le-ați știut nici tu, nici poporul tău, mai înainte de aceasta. Deci fii răbdător, căci sfârșitul [cel mai bun] va fi al celor temători [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'Și [Noi l-am trimis] la [poporul] ’Ad pe fratele lor Hud, care a spus: „O, popor al meu! Adorați-L pe Allah! Voi nu aveți [altă] divinitate în afară de El! Voi sunteți doar născocitori [de minciuni].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'O, popor al meu, eu nu vă cer pentru aceasta răsplată, ci răsplata mea este numai la Acela care m-a creat. Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'O, popor al meu, rugați-vă de iertare Domnului vostru și apoi căiți-vă față de El, pentru ca El să trimită asupra voastră Cerul încărcat de ploaie și să sporească puterea voastră cu putere! Și nu vă abateți ca niște mari păcătoși”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, 'Ei au spus: „O, Hud! Tu nu ne-ai adus dovezi clare, iar noi nu-i vom părăsi pe zeii noștri, pentru cuvântul tău, și nici nu vom fi cu credință în tine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Noi nu spunem decât că te-a ajuns un rău [nebunie] de la unul din zeii noștri.” El a zis: „Eu Îl iau pe Allah ca Martor și voi, de asemenea, fiți martori, că eu sunt nevinovat pentru ceea ce voi luați ca asociați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'În locul Lui! Deci vicleniți cu toții împotriva mea, fără să-mi dați niciun răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'Cu adevărat, eu mă încred în Allah - Domnul meu și Domnul vostru. Și nu este vietate pe care El să nu o țină de chica ei[13]. Cu adevărat, Domnul meu este pe drumul cel drept [întru Adevăr].', '[13] Pe care să nu o controleze');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Iar de vă veți întoarce, eu v-am transmis deja cele cu care am fost trimis la voi. Și Domnul meu va lăsa să urmeze după voi un alt popor, fără ca voi să-I aduceți Lui vreun rău. Iar Domnul meu este peste toate Păzitor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'Și când a venit Porunca Noastră, i-am salvat Noi pe Hud și pe cei care credeau împreună cu el, prin Mila Noastră, și i-am salvat de pedeapsă cruntă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'Aceștia sunt [poporul] ’Ad. Ei au tăgăduit semnele Domnului lor și nu au dat ascultare Trimișilor Săi și au urmat porunca oricărui tiran îndărătnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'Și au fost urmăriți de un blestem în această lume și în Ziua Învierii. [Poporul] ’Ad nu a crezut în Domnul lor. Departe cu ‘Ad, neamul lui Hud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'Și [Noi am trimis] la Thamud pe fratele lor Salih care a spus: „O, popor al meu! Adorați-L pe Allah! Voi nu aveți altă divinitate în afară de El! El v-a creat pe voi din pământ și v-a dat vouă să locuiți pe el. Rugați-L pe El de iertare și căiți-vă la El. Cu adevărat, Domnul meu este aproape [și] El este Cel care Răspunde întotdeauna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, 'Ei au spus: „O, Salih! Ai fost tu înainte de aceasta dorit peste noi. Ne oprești tu să adorăm ceea ce au adorat părinții noștri? Noi suntem într-o îndoială tulburătoare cu privire la cele la care ne chemi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, 'El a spus: „O, neam al meu! Ce ziceți voi, dacă eu am o dovadă limpede de la Domnul meu, Care mi-a dăruit și Îndurare de la El? Cine mă va apăra pe mine de Allah, dacă eu nu m-aș supune Lui? Voi nu-mi sporiți decât pierderea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'O, popor al meu! Iată această cămilă de la Allah, care este un semn deslușit pentru voi. Lăsați-o să pască pe pământul lui Allah și nu o atingeți cu niciun rău, căci vă va lovi pe voi pedeapsă apropiată!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Însă ei au înjunghiat-o și atunci el le-a spus: „Mai bucurați-vă în casele voastre [încă] trei zile! Aceasta este o făgăduință fără de minciună.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'Și când a venit Porunca Noastră, i-am salvat Noi pe Salih și pe cei care au crezut împreună cu el, prin Îndurarea Noastră, de rușinea acelei zile. Domnul tău este Al-Qauiyy [Cel Puternic] [și] Al-''Aziz [Tare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'Și pe cei nelegiuiți i-a lovit strigătul tunător și au căzut [morți], în casele lor, cu fața în jos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'Ca și când nu ar fi locuit [niciodată] în belșug în ele. Fără îndoială, [poporul] Thamud nu a crezut în Stăpânul lor! Ducă-se Thamud!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'Și au venit Trimișii Noștri [Îngerii] la Avraam cu veste bună. Au zis ei: „Pace!”. Și le-a răspuns el: „Pace [vouă]”! și nu a pregetat să aducă un vițel fript.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'Și când a văzut că mâinile lor nu se întind spre el, a devenit bănuitor și l-a cuprins frica de ei.[14] Dar ei au zis: „Nu-ți fie frică! Noi am fost trimiși la neamul lui Lot!”', '[14] De obicei dacă un musafir refuză să mănânce, însemna că avea dușmănie față de gazdă sau intenționa să-i facă rău');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'Și soția lui stătea în picioare și ea a zâmbit[15]. Atunci Noi i l-am Vestit ei pe Isaac, iar după Isaac pe Iacob.', '[15] De bucurie la aflarea veștilor despre pedepsirea oamenilor răi care l-au negat pe Profetul Lot');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, 'Ci ea a zis: „Vai mie! O să nasc eu când eu sunt o femeie bătrână, iar bărbatul meu e un moșneag?! Acesta este cu adevărat un lucru ciudat!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, 'Dar ei au zis: „Te miri tu de Hotărârea lui Allah? Îndurarea și Binecuvântarea lui Allah asupra voastră, o, locuitori ai acestei case. Cu adevărat, El este Hamid [Cel Vrednic de Laudă] [și] Majid [Cel Vrednic de Glorie].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'Și când i-a trecut lui Avraam frica și i-a venit vestea cea bună, el a început să argumenteze[16] cu Noi [în apărarea] poporului lui Lot.', '[16] Cu Îngerii Noștri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Cu adevărat, Avraam era blând, căinător și rugător', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, '[Îngerii au spus]: „O, Avraam, renunță la aceasta. Cu adevărat, Hotărârea Domnului tău a venit, iar asupra lor se va abate o pedeapsă nestrămutată”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'Și când Trimișii Noștri [Îngerii] au venit la Lot, s-a simțit stingherit[17], neștiind ce să facă și a spus: „Aceasta este o zi cumplită”.', '[17] Profetul Lot s-a temut pentru siguranța și onoarea musafirilor săi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'Și s-a grăbit poporul său către el, după ce până atunci săvârșiseră fapte rele[18]. Și el le-a spus: „O, popor al meu! Acestea sunt fiicele mele[19] și ele sunt mai curate pentru voi. Fiți cu frică de Allah și nu mă faceți de rușine față de oaspeții mei! Nu este printre voi niciun bărbat chibzuit?”', '[18] Făcându-se referire la practica sodomiei și a violului între bărbați
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, 'Dar ei au spus: „Tu știi că nu avem nevoie de fiicele tale și tu știi ceea ce noi vrem.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, 'El a spus: „O, de-aș avea eu putere asupra voastră sau de-aș găsi un sprijin temut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, 'Ei [Îngerii] au spus: „O, Lot! Noi suntem Trimișii Domnului tău! Ei nu vor putea niciodată să ajungă la tine. Deci pleacă cu familia ta la vreme de noapte[20] și să nu se întoarcă niciunul dintre voi [pentru a privi înapoi], în afară de soția ta, pe care o va lovi ceea ce îi lovește pe ei. Ceea ce îi amenință pe ei se va întâmpla în zori. Și oare nu este dimineața aproape?”', '[20] Cândva înainte de răsărit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'Și când a venit Hotărârea Noastră, am făcut Noi ca partea ei [a cetății] de sus să fie partea ei de dedesubt și am trimis asupra ei ploaie de pietre de lut [ars], una după alta,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, 'Însemnate de Domnul tău. Și ele [pedepsele lui Allah] nu sunt departe de cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'Și [l-am trimis Noi] la [poporul] Madyan pe fratele lor Șuayb, care [le-] a spus: „O, popor al meu, adorați-L voi pe Allah, căci nu există altă divinitate în afară de El. Și nu micșorați măsura și greutatea. Cu adevărat, eu vă văd întru bine, dar eu mă tem pentru voi de chinul unei zile care [le] va cuprinde [pe toate].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'Și, o, popor al meu, dați măsura și greutatea întreagă, cu dreptate, și nu le scădeți oamenilor din lucrurile [cuvenite] lor și nu purcedeți pe pământ ca stricători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'Ceea ce vă rămâne din partea lui Allah este mai bun pentru voi, dacă sunteți credincioși. Iar eu nu sunt păzitor peste voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, 'Ei au spus: „O, Șuayb! Oare rugăciunile tale [religia ta] îți poruncesc ca noi să ne lepădăm de ceea ce au adorat părinții noștri și să nu facem ceea ce voim cu averile noastre? Cu adevărat, tu ești blând și chibzuit.”[21]', '[21] Aceasta este o descriere sarcastică ce implică opusul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, 'El a spus: „O, popor al meu, v-ați gândit: dacă eu am o dovadă limpede de la Domnul meu, Care mi-a dăruit din partea Sa avere frumoasă?[22] Eu nu voiesc să fac ceea ce vă interzic vouă. Eu nu voiesc decât îndreptarea [voastră], atât cât pot. Iar izbânda mea nu este decât de la Allah. În El mă încred și la El mă întorc[23].', '[22] Concluzia acestei propoziții este estimată a fi „nu ar fi datoria mea să vă avertizez?”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'O, popor al meu, să nu vă împingă la păcat vrajba ce mi-o arătați, ca să vă lovească ceea ce a lovit poporul lui Noe sau poporul lui Hud sau poporul lui Salih. Iar poporul lui Lot nu este departe de voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'Și rugați-vă de iertare Domnului vostru, apoi căiți-vă față de El, Căci Domnul meu este Rahim [Îndurător] [și] Uadud [Binevoitor].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, 'Ei au spus: „O, Șuayb! Noi nu pricepem prea multe din ceea ce ne spui tu și te socotim slab printre noi. Și de n-ar fi clanul tău, noi te-am ucide cu pietre, căci tu nu ai nicio putere asupra noastră.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, 'El a spus: „O, neam al meu, oare clanul meu are mai mult preț la voi decât Allah, Căruia voi Îi întoarceți spatele? Cu adevărat, Domnul meu cuprinde [cu Știința Sa] tot ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'Și, o, neam al meu, faceți după putința voastră și voi face și eu [tot la fel] și veți afla voi asupra cui se va abate o pedeapsă care-l va înjosi și cine este mincinos. Așteptați, și voi aștepta și eu împreună cu voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'Și când a venit Porunca Noastră, i-am izbăvit Noi pe Șuayb și pe cei care au crezut împreună cu el, prin Îndurarea Noastră, în vreme ce pe cei care au rămas nelegiuiți i-a lovit strigătul tunător și au căzut [morți], în casele lor, cu fața în jos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'Ca și cum ei nu ar fi locuit în ele, în belșug, [niciodată]. Atunci, departe cu Madyan, așa cum departe s-a dus și [poporul] Thamud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'Și l-am trimis Noi pe Moise, cu semnele Noastre și cu putere evidentă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, 'La Faraon și la căpeteniile sale. Însă ei au urmat porunca lui Faraon, dar porunca lui Faraon nu era cu dreptate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'Și va merge el înaintea poporului său în Ziua Învierii și-i va călăuzi pe ei către Foc. Și ce rău loc va fi acesta spre care sunt ei duși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'Și vor fi urmăriți în această [lume] și în Ziua Judecății de blestem. Și ce rău dar[24] va fi acesta care le este menit.', '[24] Blestemul ce îi va urmări în ambele vieți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'Acestea sunt dintre veștile cetăților pe care ți le povestim [o, Mohammed]. Dintre ele [o parte] sunt încă în picioare și [o parte din ele] sunt șterse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Noi nu le-am făcut nicio nedreptate, ci ei înșiși s-au nedreptățit. Și nu le-au fost de niciun folos zeii lor, pe care i-au adorat în locul lui Allah, când a venit Porunca Domnului tău, ci nu au făcut ei decât să le sporească ruina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'Astfel este pedeapsa Domnului tău când El pedepsește cetățile, dacă ele sunt nelegiuite. Iar pedeapsa Lui este dureroasă și aspră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'Cu adevărat, în aceasta este un semn pentru cel care se teme de chinul din Ziua de Apoi. Aceasta este o Zi în care oamenii vor fi adunați! Aceasta este o Zi mărturisită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'Și Noi nu o lăsăm să întârzie decât numai până la un termen hotărât.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'În Ziua ce va veni, nu va grăi niciun suflet, decât numai cu Voia Lui. Și unii dintre ei vor fi osândiți, iar [alții] fericiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'În ce-i privește, pe cei care vor fi osândiți se vor afla în Foc, unde ei vor avea parte de geamăt și de suspin;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'În veci vor sălășlui în el, cât vor dăinui Cerurile și Pământul, doar dacă Domnul tău va voi altfel, căci Domnul tău face tot ceea ce El Voiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'În ceea ce-i privește, pe cei care vor fi fericiți, ei se vor afla în Rai; și în veci vor sălășlui în el, atât cât vor dăinui Cerurile și Pământul, doar dacă Domnul tău va Voi altfel. [Acesta va fi] un dar neîntrerupt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, 'Nu te îndoi [o, Mohammed,] cu privire la ceea ce adoră ei [politeiștii]. Ei nu adoră alta decât ceea ce au adorat părinții lor mai înainte. Iar Noi le vom da partea lor fără nicio micșorare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'Noi i-am dat deja lui Moise Scriptura și s-au ivit neînțelegeri asupra ei. Și de n-ar fi fost mai dinainte un Cuvânt[25] de la Domnul tău, [totul] ar fi fost hotărât pentru ei. Dar ei sunt în îndoială tulburătoare asupra lui.', '[25] A se vedea 10:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'Și cu adevărat, pe fiecare îl va răsplăti Domnul tău pe deplin pentru faptele sale. Cu adevărat, El este Khabir [Bineștiutor] a ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Deci rămâi pe calea cea dreaptă, așa cum ți s-a poruncit, laolaltă cu aceia care s-au căit împreună cu tine. Și nu treceți peste limite, fiindcă El este Basir [Cel care Vede Bine] ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'Și nu înclinați către cei care sunt nelegiuiți, ca să nu vă atingă Focul și voi nu aveți alți aliați afară de Allah și apoi voi nu veți fi ajutați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'Și împlinește Rugăciunea [As-Salat] la cele două capete ale zilei și la anumite ceasuri din noapte. Cu adevărat, faptele bune le alungă pe cele rele. Aceasta este o reamintire pentru cei care își reamintesc [cugetă și I se supun lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'Și fii statornic în răbdare, fiindcă Allah nu lasă să se piardă răsplata făcătorilor de bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'Și oare nu au fost printre popoarele de dinaintea voastră oameni virtuoși care au oprit de la stricăciuni pe acest pământ – în afară de puțini dintre ei pe care Noi i-am izbăvit? Iar cei care au fost nedrepți au trăit mai departe în îmbuibare și au fost mai păcătoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Și Domnul tău nu ar fi nimicit cetățile, cu nedreptate, dacă locuitorii lor s-ar fi îndreptat [și ar fi săvârșit fapte bune].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'Și dacă Domnul tău ar fi Voit, i-ar fi făcut pe toți oamenii o singură comunitate. Dar ei nu încetează să fie în neînțelegere', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'În afară de cei cu care Domnul tău a fost Îndurător. Și de aceea i-a creat pe ei. Și se va împlini Cuvântul Domnului tău: „Voi umple Gheena cu djinni și cu oameni laolaltă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'Și în tot ce-ți povestim ție din veștile despre Trimiși se află [pildă] cu care Noi întărim inima ta. Și prin acestea a venit la tine Adevărul, Îndemnarea și reamintirea pentru dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'Și spune-le celor care nu cred: „Faceți după putința voastră și vom face și noi [tot la fel].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'Așteptați și vom aștepta și noi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'Și ale lui Allah sunt cele neștiute din Ceruri și de pe Pământ. Și la El se întorc toate lucrurile [pentru hotărâre]. Adoră-L, așadar, și încrede-te în El! Și Domnul tău nu este nebăgător de seamă față de ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Alif, Lam, Ra''[1]. Acestea sunt Versetele Cărții limpezi.', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Cu adevărat, Noi am pogorât-o drept un Coran arab[2], poate că voi veți pricepe.', '[2] Revelat în limba arabă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Noi îți vom povesti [o, Mohammed] cea mai frumoasă istorisire din ceea ce îți revelăm în acest Coran, chiar dacă ai fost înainte de ea printre cei neștiutori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, '[Din aceste povești spune] când Iosif i-a spus tatălui său[3]: „O, tată! Eu am văzut [în vis] unsprezece planete, și Soarele și Luna! Eu le-am văzut prosternându-mi-se!”', '[3] Profetul Iacob');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, 'El a spus: „O, fiul meu! Nu povesti visul tău fraților tăi, ca să nu plăsmuiască viclenie împotriva ta. Cu adevărat, Șeitan îi este omului dușman învederat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'Astfel te alege Domnul tău și te învață tâlcuirea vedeniilor [evenimentelor sau viselor] și va împlini El binefacerea Sa asupra ta și asupra neamului lui Iacob, așa cum a împlinit-o El și asupra celor doi părinți ai tăi, Avraam și Isaac, căci Domnul tău este ‘Alim [Atoateștiutor] [și] Hakim [Înțelept]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'În Iosif și în frații săi au fost semne pentru aceia care întreabă, [precum]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Atunci când au spus: „Iosif și fratele său[4] sunt mai dragi decât noi tatălui nostru, chiar dacă noi suntem o ceată. Cu adevărat, tatăl nostru este în rătăcire evidentă.', '[4] Beniamin, născut din aceeași mamă ca și Iosif');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'Omorâți-l pe Iosif sau lăsați-l [pe alt] pământ, astfel încât chipul tatălui vostru să se îndrepte numai spre voi! Iar după aceasta veți fi oameni drepți[5].”', '[5] Vă puteți căi apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'Unul dintre ei a spus: „Nu-l omorâți pe Iosif, ci aruncați-l în fundul unui puț - dacă voi vreți să o faceți - și o să-l ia vreo caravană!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, 'Ei au spus: „O, tată! De ce nu ni-l dai tu pe Iosif în grijă? Noi doară îi suntem lui sfătuitori buni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Trimite-l mâine împreună cu noi, să se bucure și să se joace, iar noi îl vom păzi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, '[Iacob] a spus: „Cu adevărat, eu sunt trist că voi îl luați și mă tem să nu-l mănânce lupul, când voi veți fi fără băgare de seamă față de el.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, 'Ei au spus: „Dacă o să-l mănânce lupul, când noi suntem o ceată, înseamnă că noi suntem atunci cei pierduți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'Și când au plecat cu el și s-au înțeles cu toții să-l arunce în adâncul puțului, atunci i-am revelat Noi lui: „Tu le vei vorbi despre această faptă a lor [într-o zi], fără ca ei să te cunoască!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, 'Și seara au venit la tatăl lor, plângând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, 'Și au spus: „O, tată! Noi ne-am dus și ne-am luat la întrecere și l-am lăsat pe Iosif lângă lucrurile noastre. Și l-a mâncat lupul. Tu nu ne crezi, măcar că noi spunem adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'Și au adus cămașa lui [mânjită] cu sânge mincinos[6]. [Iacob] a spus: „Mai degrabă sufletele voastre v-au îndemnat să faceți ceva [rău], deci [nu-mi rămâne decât] răbdarea cuminte. Și Allah este Cel la care se cere ajutor pentru cele pe care voi le povestiți.”', '[6] Ei au pătat cămașa lui Iosif cu sângele unui miel, dar au uitat să o sfâșie, iar aceasta a sporit suspiciunea tatălui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'A venit o caravană și [cei din caravană] l-au trimis pe cel care scotea apă pentru ei și el a coborât găleata lui. Dar el a spus: „Ce veste bună! Aici este un băiețel!” Și l-au ascuns în chip de marfă[7]. Dar Allah este ''Alim [Bineștiutor] a ceea ce au făcut ei.', '[7] De a fi vândut ca și sclav');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'Și l-au vândut ei pentru un preț de nimic, pentru câțiva dirhami, căci atât de puțin l-au prețuit ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'Și a spus cel din Egipt, care l-a cumpărat, către soția lui: „Cinstește șederea lui [printre noi]! S-ar putea să ne fie de folos sau să-l luăm ca fiu!” Și astfel i-am dat Noi lui Iosif stare temeinică pe acest pământ, pentru a-l învăța pe el tâlcuirea vedeniilor. Allah are Putere să facă orice lucru dacă Voiește, dar cei mai mulți oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Și când a ajuns el [Iosif] la vârsta bărbăției, i-am dat Noi înțelepciune și știință, căci astfel îi răsplătim Noi pe cei care fac bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'Și a vrut ea, cea în a cărei casă se afla, să-l ademenească, împotriva voinței lui. Și a încuiat ușile și i-a spus: „Vino încoace!” Însă el i-a răspuns: „Ferească Allah! Cu adevărat, el[8] este stăpânul meu, care mi-a dat bun loc. Într-adevăr nelegiuiții nu izbândesc.”', '[8] Soțul femeii, al-Aziz');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'Și ea era cu adevărat hotărâtă [să îl seducă] și ar fi avut și el poftă de ea, dacă nu ar fi văzut semnul Domnului său. Astfel [am făcut Noi], ca să îndepărtăm răul și fapta rușinoasă de el. Cu adevărat, el era unul dintre robii Noștri aleși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, 'Și au alergat amândoi spre ușă, iar ea i-a rupt cămașa la spate. Și l-au găsit pe soțul ei lângă ușă și i-a spus ea [atunci]: „Care este pedeapsa pentru cel care voiește familiei tale un rău, decât temnița sau pedeapsa dureroasă?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, '[Iosif] a spus: „Dar ea a vrut să mă ademenească, în pofida voinței mele!” Însă un martor din familia ei a mărturisit: „Dacă cămașa lui este ruptă în față, atunci ea a spus adevărul, iar el a fost dintre aceia care mint,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'Însă dacă cămașa lui a fost ruptă la spate, atunci ea a mințit, iar el este dintre aceia care spun adevărul”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'Și când a văzut cămașa lui că a fost ruptă la spate, el a spus: „Acesta este un vicleșug de-al vostru, [femeilor], iar viclenia voastră este fără de margini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'Iosif, uită de aceasta. Iar tu, [soție] roagă-te de iertare pentru vina ta, căci tu ai fost dintre cei păcătoși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'Și femeile din cetate au spus: „Soția lui Al-Aziz îl ademenește pe băiatul ei sclav, în pofida voinței lui. Iubirea pentru el a făcut-o să-și piardă mințile! Noi o vedem cu adevărat în rătăcire limpede”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'Și când a aflat ea de clevetirea lor, le-a chemat și le-a pregătit un ospăț și a dat fiecăreia dintre ele câte un cuțit. Și atunci a spus: „Ieși afară la ele, [Iosif]!” Iar când l-au văzut, s-au minunat de el peste măsură și și-au tăiat mâinile, în vreme ce spuneau: „Allah să ne ferească! Acesta nu este om! Acesta este un înger nobil.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, 'Ea a spus: „Priviți-l pe cel pentru care voi m-ați clevetit! Am încercat să-l ademenesc în pofida voii lui, însă el s-a împotrivit, [rezistând ispitei]. Iar de nu va face ce-i poruncesc, să fie întemnițat și să fie printre cei umiliți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, 'El a spus: „Doamne! Temnița îmi este mai dragă decât aceea la care mă cheamă ele. Și dacă nu vei depărta de la mine vicleșugul lor, voi simți dorință pentru ele și voi fi astfel printre cei ignoranți“.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'Și Domnul său i-a răspuns și a depărtat viclenia lor de la el. Cu adevărat, El este As-Sami'' [Cel care Aude Totul] [și] Al-''Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'Apoi li s-a năzărit lor, după ce au văzut semnele[9] ca el [al-Aziz] să-l întemnițeze până la un timp[10].', '[9] Dovezile inocenței lui
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Și au intrat împreună cu el în temniță doi tineri. Și a spus unul dintre ei: „Cu adevărat, eu m-am văzut [într-un vis] storcând [struguri pentru] vin”. Iar celălalt a spus: „Cu adevărat, eu m-am văzut purtând pe cap pâine, din care mâncau păsările. Vestește-ne nouă tâlcuirea acestora, căci te vedem pe tine dintre binefăcători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, 'El a spus: „Nici nu vă va sosi mâncarea cu care voi sunteți hrăniți, că eu vă voi și vesti tâlcuirea, înainte ca ea să vă vină. Aceasta [face parte] din ceea ce m-a învățat Domnul meu. Cu adevărat, eu am părăsit religia unui popor ce nu crede în Allah și care, în Viața de Apoi este necredincios.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'Și eu am urmat religia strămoșilor mei Avraam, Isaac și Iacob. Nu se cuvine să-I alăturăm lui Allah nimic. Aceasta este din Harul lui Allah asupra noastră și asupra [tuturor] oamenilor, însă cei mai mulți dintre oameni nu aduc mulțumire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, 'O, voi, tovarăși ai mei de temniță! Sunt mai buni domnii risipiți sau Allah Al-Uahid [Cel Unic], Al-Qahhar [Stăpânul Atotputernic]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Nu adorați în afară de El decât niște nume pe care le-ați născocit[11] voi și părinții voștri și cărora Allah nu le-a pogorât nicio dovadă. Judecata nu este decât la Allah. El v-a poruncit să nu-L adorați decât pe El. Aceasta este religia cea dreaptă, însă cei mai mulți oameni nu știu.', '[11] Obiecte false de adorare pe care i-ați numit „zei”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'O, voi, tovarăși ai mei de temniță! Unul dintre voi va da stăpânului său să bea vin. Cât despre celălalt, el va fi răstignit, iar păsările vor mânca din capul lui. S-a hotărât treaba asupra căreia voi îmi cereți sfat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'Și el a spus apoi celui dintre ei despre care știa că va fi eliberat: „Pomenește și de mine stăpânului tău.” Dar Șeitan l-a făcut să uite să-i amintească stăpânului său și el [Iosif] a rămas în temniță câțiva ani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'Și regele a spus: „Cu adevărat, am văzut [într-un vis] șapte vaci grase mâncate de alte șapte costelive și șapte spice verzi și altele [șapte] uscate. O, voi, dregători ai mei! Dați-mi mie sfat asupra vedeniei mele, dacă voi știți să tâlcuiți vedenia.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, 'Ei au răspuns: „[Este doar] un amestec de vise neîntemeiate și noi nu suntem pricepuți în tâlcuirea viselor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'Dar cel care fusese eliberat dintre cei doi și-a adus aminte după o vreme: „Eu vă voi vesti tâlcuirea acestora! Deci trimiteți-mă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, '[El a spus] „O, Iosif, iubitorule de adevăr, explică-ne despre șapte vaci grase mâncate de alte șapte costelive, și despre șapte spice verzi și alte [șapte] uscate, ca să mă întorc la oameni pentru ca ei să știe [despre tine].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, '[Iosif] a spus: „O să semănați șapte ani, unul după altul, cu hărnicie, dar ceea ce secerați să lăsați în spice, afară de puțin din care o să mâncați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Apoi vor veni, după aceea, șapte [ani] aspri, care vor consuma ceea ce ați strâns pentru ei mai înainte, afară de puțin din ceea ce voi veți păstra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Apoi va veni, după aceea, un an în care oamenii vor avea parte de ploaie îmbelșugată și în care vor stoarce [măsline și struguri]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'Și regele a spus: „Aduceți-l la mine.” Și când a venit solul la el, [Iosif] i-a spus: „Întoarce-te la stăpânul tău și întreabă-l: Ce-au avut muierile care și-au tăiat mâinile? Cu adevărat, Domnul meu este ‘Alim [Bineștiutor] al vicleniei lor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, 'Și [regele le-] a spus [femeilor]: „Care a fost pricina ce v-a împins pe voi să încercați să-l ispitiți pe Iosif?” Au răspuns [ele]: „Allah să ne ferească! Noi nu știm nimic rău despre el.” Și a spus femeia lui Al-Aziz: „Acum adevărul este limpede. Eu am fost cea care a încercat să-l ispitească, însă el a spus adevărul întotdeauna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, 'Aceasta, ca să știe [al-Aziz] că eu nu l-am trădat în absență, și că Allah nu călăuzește viclenia celor trădători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, 'Eu nu mă dezvinovățesc pe mine, căci sufletul este înclinat către rău, în afară de cel pe care îl păzește Domnul meu prin Îndurarea Lui, căci Domnul meu este Ghafur [Iertător] și Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'Și regele a spus: „Aduceți-mi-l, căci voiesc să-l păstrez lângă mine.” Și când a vorbit cu el, i-a spus: „Cu adevărat, de astăzi tu ești pentru noi cu putere și de încredere.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, '[Iosif] a spus: „Pune-mă pe mine peste hambarele țării. Cu adevărat, eu voi fi un păzitor bun și priceput.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'Astfel i-am dat Noi putere lui Iosif pe pământ și i-am îngăduit să se așeze în el acolo unde voiește. Noi îl cuprindem cu Îndurarea Noastră pe cel care voim și nu lăsăm să se piardă răsplata binefăcătorilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'Iar răsplata din Lumea de Apoi este chiar și mai bună pentru cei care cred și sunt cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'Și frații lui Iosif au venit [căutând mâncare] și au intrat la el. El i-a cunoscut, însă ei nu l-au mai cunoscut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'Și după ce i-a pregătit pe ei cu proviziile lor, a spus: „Aduceți-mi pe un frate al vostru de la tatăl vostru[12]. Nu vedeți voi că eu dau măsură plină și că eu sunt cel mai bun primitor de oaspeți?', '[12] Beniamin, care a fost ținut acasă de tatăl său Iacob');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Iar de nu mi-l veți aduce, nu veți mai avea măsură la mine și nu vă veți mai apropia de mine”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, 'Ei au spus: „Vom încerca să-l convingem pe tatăl lui. Noi o vom face.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'Și [Iosif] le-a spus slujitorilor săi: „Puneți marfa[13] lor înapoi, în sacii lor de pe cămile! Poate că ei o s-o recunoască, atunci când se vor întoarce la familia lor, și poate că ei vor reveni.”', '[13] Bunurile pe care aceștia le-au adus pentru a face troc pentru mâncare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'Și când s-au întors la tatăl lor, ei au spus: „O, tată al nostru! Ne-a fost nouă oprită măsura. Așadar, trimite-l împreună cu noi pe fratele nostru ca să căpătăm măsura și noi îl vom păzi pe el.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, 'Dar el a spus: „Să vi-l încredințez așa cum vi l-am încredințat pe fratele lui mai înainte? Allah este mai bun Păzitor și El este Cel mai Îndurător dintre îndurători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'Și când și-au desfăcut sarcinile lor, au văzut că marfa lor le-a fost dată înapoi. Și ei au spus atunci: „O, tată al nostru! Ce să mai dorim noi [mai mult]? Iată că marfa noastră ne-a fost dată înapoi. Astfel vom procura noi provizii pentru familia noastră și-l vom păzi pe fratele nostru și vom adăuga noi o încărcătură de cămilă și aceasta este o măsură ușoară”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, '[Iacob] a spus: „Nu-l voi trimite împreună cu voi până ce nu veți face învoială cu mine înaintea lui Allah să mi-l aduceți înapoi, în afară de situația că voi ați fi înconjurați [de dușmani].” Și când au făcut legământul, el a spus: „Allah este Chezaș pentru ceea ce vorbim.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'Și a mai spus el: „O, fiii mei! Nu intrați pe o singură poartă, ci intrați pe porți diferite. Eu nu vă pot fi de niciun folos împotriva [decretului] lui Allah. Hotărârea nu este decât la Allah! Eu în El mă încred și în El să se încreadă aceia care se încred.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'Și când au intrat așa cum le-a poruncit tatăl lor, nu le-a fost aceasta de niciun folos împotriva [hotărârii] lui Allah. N-a fost decât că s-a împlinit o dorință din sufletul lui Iacob. El avea înțelepciunea din ceea ce l-am învățat Noi, dar cei mai mulți oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'Și când au intrat la Iosif, l-a luat [acesta] pe fratele său lângă el și i-a spus: „Eu sunt fratele tău. Nu fi îngrijorat pentru ceea ce au făcut ei [cu mine].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'Iar atunci când le-a pregătit proviziile lor, a pus el cupa în sacul de pe cămila fratelui său. Apoi un vestitor a strigat: „O, voi călătorilor! Voi sunteți niște hoți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Ei au spus, întorcându-se la ei: „Ce vă lipsește?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, 'Ei au răspuns: „Ne lipsește măsura regelui. Iar cel care o va aduce, va primi [încă] o sarcină de cămilă. Și eu îi sunt chezaș.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, 'Ei au spus: „Pe Allah, voi știți că n-am venit să facem stricăciune în țară și nu suntem hoți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, '[Acuzatorii] au răspuns: „Și care să fie pedeapsa lui, dacă voi sunteți mincinoși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, '[Frații] au spus: „Pedeapsa lui, a celui în ai cărui saci va fi găsită, este că el însuși va fi răsplată[14]. Astfel îi pedepsim noi pe cei nelegiuiți.”', '[14] Conform legii lor, un hoț condamnat era făcut sclavul celui de la care a furat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, 'Și a început [căutarea] cu sacii lor înainte de sacul fratelui său. Apoi a scos-o din sacul fratelui său. Astfel am plănuit Noi Hotărârea pentru Iosif. El nu ar fi putut să-l ia pe fratele său, după religia regelui, decât cu voia lui Allah. Noi îi ridicăm câteva trepte pe cei pe care Voim și peste oricine are știință, este cineva mai știutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, 'Ei au spus: „Dacă el a furat, a mai furat și un frate al lui mai înainte”. Însă Iosif a ținut aceasta ascunsă în sufletul său și nu le-a dezvăluit-o, ci el a spus [în sinea lui]: „Voi sunteți într-o poziție și mai rea, dar Allah Știe mai bine despre ceea ce spuneți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, 'Ei au răspuns: „O, Al-Aziz[15]! El are un tată tare bătrân. Ia-l pe unul dintre noi în locul lui. Noi vedem că tu ești cu adevărat dintre oamenii binefăcători.”', '[15] Adresându-i-se lui Iosif, care avea titlul de „Al-Aziz”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, 'El a spus: „Ferească Allah să luăm pe altcineva decât pe cel la care am găsit lucrul nostru, căci atunci noi am fi nedrepți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'Când n-au mai avut nicio nădejde în privința lui, s-au tras deoparte ca să se sfătuiască. A spus cel mai mare dintre ei: „Oare nu știți că tatăl vostru a făcut legământ cu voi înaintea lui Allah? Și [nu vă amintiți] cum l-ați pierdut voi pe Iosif mai înainte? Eu nu voi pleca din [acest] pământ până ce nu-mi va îngădui tatăl meu sau până ce Allah nu va Judeca în favoarea mea, căci El este Cel mai Bun dintre judecători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, 'Întoarceți-vă la tatăl vostru și spuneți-i: „O, tată al nostru! Fiul tău a furat. Noi nu facem mărturie decât pentru ceea ce știm și noi nu am avut cunoștință despre cele nevăzute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, 'Întreabă cetatea în care am fost și caravana cu care am venit. Cu adevărat, noi nu spunem decât adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, '[Iacob] a spus: „Ba mai degrabă sufletele voastre au născocit ceva rău pentru voi. Dar răbdare cuviincioasă! Poate că Allah mi-i va aduce pe toți. Căci El este Cel Al-''Alim [Atoateștiutor] [și] Al-Hakim [Înțelept].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'Și s-a întors de la ei și a spus: „Cât de rău îmi pare pentru Iosif.” Și ochii lui s-au albit[16] de tristețe și el era mâhnit.', '[16] Și-a pierdut vederea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, 'Ei au spus: „Pe Allah! Tu nu vei conteni să-l pomenești pe Iosif, până ce nu te vei îmbolnăvi de moarte sau vei fi pierit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, 'El a răspuns: „Însă eu nu mă plâng decât numai față de Allah pentru supărarea și mâhnirea mea, căci eu știu de la Allah ceea ce voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, 'O, fiii mei, plecați și căutați-i pe Iosif și pe fratele său și nu vă pierdeți nădejdea în Îndurarea lui Allah! Nu-și pierde nădejdea în Îndurarea lui Allah decât neamul de necredincioși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'Și când au intrat la el [la Iosif], ei au spus: „O, Al-Aziz! S-a abătut nenorocirea asupra noastră și asupra familiei noastre și nu venim decât cu o marfă lipsită de mare valoare. Deci dă-ne nouă o măsură plină și fi milostiv cu noi. Cu adevărat, Allah îi răsplătește pe cei milostivi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, 'El a spus: „Oare știți ce ați făcut cu Iosif și cu fratele său, când ați fost neștiutori?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, 'Ei au răspuns: „Oare tu ești cu adevărat Iosif!?” El a spus: „Eu sunt Iosif, iar acesta este fratele meu! Allah Și-a revărsat Harul asupra noastră. Cu adevărat, pentru cei care au frică și au răbdare - Allah nu pierde răsplata celor binefăcători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, 'Ei au spus: „Pe Allah! Cu adevărat, Allah te-a preferat pe tine nouă, iar noi am fost supuși greșelii.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, 'El a spus: „Astăzi nu mai este nicio vină împotriva voastră. Allah să vă ierte, căci El este Cel mai Milostiv dintre cei milostivi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, 'Duceți-vă cu această cămașă a mea și puneți-o pe fața tatălui meu, și el va deveni din nou văzător. Și veniți la mine cu tot neamul vostru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'Când caravana a părăsit [Egiptul], tatăl lor a spus: „Eu simt mirosul lui Iosif, chiar dacă-mi spuneți că aiurez!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, 'Iar ei au răspuns: „Pe Allah, tu ești încă în vechea ta rătăcire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'Și când a sosit binevestitorul[17], a pus-o peste fața lui și el a devenit din nou văzător. Și a spus [Iacob]: „Nu v-am spus că eu știu de la Allah ceea ce voi nu știți?”', '[17] Cel dintre frați care ducea cămașa lui Iosif');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, 'Iar ei au spus: „O, tată al nostru! Roagă-te pentru iertarea greșelilor noastre, căci noi am fost păcătoși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, 'El le-a răspuns: „Voi cere de la Domnul meu iertare pentru voi, căci El este Al-Ghafur [Iertător], Ar-Rahim [Îndurător]!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'Și când au intrat la Iosif, el i-a primit pe părinții săi și a spus: „Intrați în Egipt - cu Voia lui Allah - în siguranță!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'Și el i-a ridicat pe părinții săi pe tron și au căzut [cu toții] dinaintea lui, prosternându-se[18], iar el a spus: „O, tată, acesta este tâlcul vedeniei mele de odinioară. Domnul meu a făcut-o să fie adevăr și a fost Bun cu mine, căci m-a scos din temniță, iar pe voi v-a adus din ținutul beduinilor, după ce Șeitan a iscat pizmă între mine și frații mei. Domnul meu este Binevoitor cu ceea ce Voiește. El este Al-''Alim [Cel Atoateștiutor] [și] Al-Hakim [Înțelept].', '[18] Drept salutare și respect, aceasta fiind permisă până în timpul profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa). Prosternarea în fața unei persoane sau obiect a fost după aceea interzisă.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'Doamne, Tu mi-ai dat putere și m-ai învățat tâlcuirea vedeniilor. Tu ești Creatorul Cerurilor și Pământului. Tu ești Ocrotitorul meu în această lume și în Lumea de Apoi. Ia-mi viața când eu sunt în totală supunere [musulman] și alătură-mă celor evlavioși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'Aceasta este una dintre istoriile neștiute, pe care Noi ți-o revelăm [o, Mohammed]. Tu nu ai fost lângă ei, atunci când s-au adunat cu toții și au viclenit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'Și cei mai mulți oameni nu vor crede, chiar dacă tu te vei stradui pentru aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Și tu nu le ceri vreo răsplată pentru aceasta, căci el [Coranul] nu este decât îndemnare pentru toate lumile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'Și câte semne sunt în Cer și pe Pământ, pe lângă care [oamenii] trec, întorcându-și fața de la ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Iar cei mai mulți dintre ei nu cred în Allah, fără să-I facă Lui asociați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Atunci sunt ei siguri că nu va veni o nenorocire a pedepsei lui Allah sau că Ceasul nu va veni pe neașteptate, fără ca ei să-și dea seama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, 'Spune: „Aceasta este calea mea. Eu chem la Allah, eu și cei care m-au urmat, bizuindu-ne pe dovadă limpede. Mărire lui Allah. Iar eu nu sunt dintre politeiști.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'Și nu am trimis [ca Mesageri] înainte de tine decât bărbați - dintre locuitorii cetăților - cărora Noi le-am trimis revelații. Oare ei[19] nu umblă pe acest pământ, ca să vadă care a fost sfârșitul celor de dinaintea lor? Sălașul din Lumea de Apoi este mai bun pentru cei care au frică. Oare voi nu pricepeți?', '[19] Cei care îl neagă pe profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'Chiar și când Trimișii și-au pierdut nădejdea și au crezut că au fost socotiți mincinoși, a venit la ei Ajutorul Nostru. Și au fost mântuiți cei care Noi am Voit. Însă pedeapsa Noastră nu va fi îndepărtată de la neamul celor nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'În istoria lor a fost pildă pentru cei dăruiți cu minte. El [Coranul] nu este o poveste care să fie născocită, ci, dimpotrivă, este întărirea celor dinaintea lui și tâlcuirea tuturor lucrurilor, călăuză și îndrumare pentru oamenii care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Alif, Lam, Mim, Ra[1]. Acestea sunt Versetele Cărții, iar ceea ce ți-a fost revelat de către Domnul tău este Adevărul, însă cei mai mulți oameni nu cred.', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Allah este Cel care a înălțat Cerurile fără stâlpi pe care să-i vedeți, iar apoi S-a înălțat deasupra Tronului și a supus[2] Soarele și Luna, fiecare urmându-și cursul său până la un termen hotărât. El orânduiește [fiecare] lucru și tâlcuiește semnele în amănunțime, poate că voi veți fi încrezători în întâlnirea cu Domnul vostru.', '[2] În folosul omenirii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'El este Cel care a întins pământul și a așezat pe el munți și râuri. Și din toate roadele a făcut pe el câte o pereche. El lasă ca noaptea să acopere și să ascundă ziua. Cu adevărat, în acestea sunt semne pentru cei care cugetă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'Iar pe pământ sunt parcele învecinate și grădini de viță de vie, de grâne, de palmieri în tufe și câte unul de la o rădăcină, udate de la o singură apă. Și le-am făcut Noi pe unele mai bune decât altele. Cu adevărat, în acestea sunt semne pentru un neam [de oameni] care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'Și dacă ești uimit[3] [o Mohammed] – atunci uimitoare sunt vorbele lor: „Oare când vom fi țărână, vom fi noi creați din nou?” Aceia sunt cei care nu cred în Domnul lor. Aceia sunt cei pe ale căror gâturi se vor afla juguri. Aceia sunt oaspeții Focului și ei în el vor avea sălaș veșnic.', '[3] De cei care neagă Învierea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Și ei îți cer să grăbești răul înaintea binelui[4], când înaintea lor au fost pilde. Domnul tău este Cel cu iertare pentru oameni, în pofida nelegiuirii lor. Și Domnul tău este aspru la pedeapsă.', '[4] Aceștia au spus provocându-l pe Profet (pacea și binecuvântarea lui Allah fie asupra sa): „Adu pedeapsa dacă ești sincer” în loc să se roage pentru milă și iertare de la Allah.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'Și cei care nu cred spun: „De ce nu i s-a trimis lui un semn de la Domnul lui?” Dar tu ești numai un prevenitor și fiecare neam are un călăuzitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Allah știe ce poartă[5] fiecare femeie [în pântece] și ceea ce lipsește sau ceea ce este prea mult în pântece și tot lucrul are la El măsură.', '[5] Allah cunoaște toate aspectele legate de existența fetusului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, '[El este] Știutorul celor ascunse și al celor vizibile, Cel Mare, Cel Preaînalt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'Pentru El sunt egali acela dintre voi care ține ascuns cuvântul său și acela care îl rostește cu glas tare, acela care stă ascuns în timpul nopții și acela care se arată în ziua mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'El [fiecare] are Îngeri[6] care-l însoțesc unul după altul, înaintea lui și în urma lui, care îl veghează din Porunca lui Allah. Cu adevărat Allah nu schimbă starea unor oameni până ce ei nu schimbă ceea ce se află în sufletele lor. Iar dacă Allah Voiește un rău[7] pentru un popor, acesta nu poate fi respins. Și ei nu au în locul lui Allah niciun alt ocrotitor.', '[6] Care se înlocuiesc unul pe altul
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'El este Cel care vă arată fulgerul [ce vă inspiră] teamă și nădejde și El plăsmuiește Norii cei grei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'Și-L preamărește tunetul [pe Allah] aducându-I laudă, și Îngerii, cu teamă de El. Și El trimite trăsnetele cu care lovește pe cine voiește, pe când ei se ceartă asupra lui Allah, în vreme ce El este de temut pentru puterea Sa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, '[Doar] Lui I se adresează Chemarea cea Adevărată, iar aceia pe care îi cheamă afară de El nu le vor răspunde în niciun chip, ci ei sunt ca acela care întinde mâinile sale către apă pentru ca ea să ajungă la gura lui, fără ca ea să ajungă [vreodată][8]. Iar chemarea necredincioșilor nu este decât în deșert.', '[8] Analogia indică faptul că zeitățile false nu le vor răspunde niciodată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'Înaintea lui Allah se prosternează [toți cei] care sunt în Ceruri și pe Pământ, cu voie și fără voie și la fel și umbrele lor dimineața și înainte de asfințit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, 'Spune: „Cine este Stăpânul Cerurilor și al Pământului?” Spune: „Allah” Spune: „Și v-ați luat voi în afară de El ocrotitori care nu au nici pentru ei înșiși folos și nici [apărare de] rău?” Spune: „Oare sunt egali orbul și cel care vede? Sau oare sunt egale întunericul și lumina? Sau i-au făcut lui Allah asociați care au creat precum creația Lui, încât li se pare lor creația asemănătoare?” Spune: „Allah este Creatorul tuturor lucrurilor; El este cel Al-Uahid [Unic] [și] Al-Qahhar [Biruitor]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'El face să coboare din Cer apă și văile curg după măsura lor, iar șuvoiul duce spumă înaltă și o spumă asemănătoare cu ea se ivește peste ceea ce [oamenii] topesc în foc, căutând să facă o podoabă ori un lucru. Astfel dă Allah pildă despre Adevăr și neadevăr; iar în ceea ce privește spuma ea se duce fără urmă, în vreme ce ceea ce le este oamenilor spre folos rămâne în pământ. Astfel dă Allah pilde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Pentru aceia care răspund Domnului lor este răsplata cea mai bună, în vreme ce aceia care nu-I răspund - chiar dacă ar avea toate cele care se află pe Pământ și încă pe atât pentru a le da ca răscumpărare - aceia vor avea parte de rea socoteală, iar sălașul lor va fi Gheena - și ce rău așternut [este ea]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Oare acela care știe că ceea ce ți s-a revelat de către Domnul tău este Adevărul să fie ca acela care este orb? Ci dară chibzuiesc cei care au minte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, 'Aceia care-și împlinesc făgăduința față de Allah și nu încalcă legământul făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'Și țin unit ceea ce Allah a poruncit să fie unit[9] și au frică de Domnul lor și se tem de răul socotirii.', '[9] Aceștia țin legăturile de rudenie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'Și cei care sunt statornici în căutarea chipului Domnului lor [Mulțumirea lui Allah] și plinesc Rugăciunea [As-Salat] și fac milostenie într-ascuns și pe față din ceea ce Noi le-am dăruit și resping răul prin bine, aceia vor avea parte de răsplata Casei [Veșnice][10],', '[10] Lumea și încercările ei, consecințele bune fiind Paradisul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, 'De grădinile Edenului, în care vor intra laolaltă cu [toți] aceia care au fost evlavioși, dintre părinții, soții și copiii lor, iar Îngerii vor intra la ei prin toate porțile [spunând]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, '„Pace vouă, pentru că ați fost statornici! Și ce bună este răsplata Casei [Veșnice]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'Iar cei care încalcă făgăduința făcută lui Allah, după legământul față de El, și rup ceea ce Allah a poruncit să fie unit și semănă rău pe pământ, aceia vor avea parte de blestem și vor avea parte de rea casă [veșnică].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Allah dăruiește cu prisosință sau cu măsură cele de trebuință pentru trai cui voiește El. Și ei se bucură de viață în această lume, dar nu este viața în această lume decât plăcere trecătoare față de Viața de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'Și cei care nu cred spun: „De ce nu a fost pogorât asupra lui [Mohammed] un semn de la Domnul său?” Spune [o, Mohammed]: „Allah face să rătăcească pe cine Voiește și călăuzește către El pe cel care se căiește,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, 'Pe cei ce cred și ale căror inimi sunt liniștite întru pomenirea lui Allah, căci prin pomenirea lui Allah se liniștesc inimile."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'Cei ce cred și săvârșesc fapte bune vor avea parte de fericire și bună întoarcere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'Astfel te-am trimis Noi într-o comunitate înaintea căreia au fost alte comunități, ca să le citești lor ceea ce Noi îți revelăm, în vreme ce ei nu cred în Cel Milostiv. Spune: „El este Stăpânul meu. Nu există altă divinitate în afară de El. În El mă încred și la El este întoarcerea și căința mea.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'Și de ar fi un Coran cu care să se mute munții sau cu care să se despice Pământul sau cu care să se facă morții să vorbească [ar fi acest Coran], însă a lui Allah este întreaga Poruncă. Și oare nu știu cei care cred că Allah - dacă ar Voi - i-ar călăuzi pe toți oamenii? Și nu va înceta să se abată asupra celor care nu cred o nenorocire pentru ceea ce ei au făcut sau să cadă în apropiere de sălașul lor, până ce se va împlini Promisiunea lui Allah, căci Allah nu-Și calcă făgăduința.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'Au fost luați în râs Trimiși și înainte de tine, însă Eu le-am dat un răgaz celor care nu au crezut. Apoi i-am apucat pe ei. Și cum a fost Pedeapsa Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Oare Cel care veghează asupra fiecărui suflet și [vede] ceea ce dobândește [este la fel ca asociații]? Și totuși Îi fac lui Allah asociați. Spune [-le lor]: „Numiți-i! Sau voiți să-I vestiți Lui ceva[11] ce nu Știe El de pe Pământ? Sau cele ce sunt doar vorbe [aparente și] deșarte?[12] Ba au fost cei care nu cred amăgiți de viclenia lor împodobită și au fost abătuți de la drum. Iar cei pe care Allah îi lasă să rătăcească nu au pe nimeni călăuzitor.”', '[11] „Alte zeități”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Ei vor avea parte de osândă în viața aceasta, iar chinul din Viața de Apoi va fi și mai greu și nu vor avea ei niciun apărător de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Pilda [descrierea] Grădinii care s-a promis celor evlavioși; [este că] pe sub ea curg pâraie și veșnice sunt roadele ei și umbra ei. Aceasta este răsplata celor care au frică [de Allah], iar răsplata celor necredincioși este Focul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Și aceia cărora le-am dat Noi deja Scriptura [anterioară] se bucură pentru ceea ce ți s-a pogorât [o, Mohammed]. Însă unele cete tăgăduiesc o parte din ea. Spune: „Mi s-a poruncit să-L ador pe Allah și să nu-I fac Lui asociați. Eu la El chem [oamenii] și la El este întoarcerea mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'Așa i-am trimis Noi [Coranul], ca o orânduială, [în limba] arabă! Iar dacă tu vei urma poftelor lor, după știința ce a venit la tine, nu vei avea tu nici ocrotitor, nici apărător de Allah!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'Am trimis Noi Profeți și mai înainte de tine. Și le-am dat lor soții și urmași. Însă niciun Trimis nu a putut să aducă vreun semn decât cu Voia lui Allah. Și fiecare soroc are un timp scris.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Allah șterge sau întărește ceea ce Voiește și la El se află Mama Cărții[13].', '[13] Tablele bine păstrate (al-Lauh al-Mahfudh) în care este scrisă fiecare Scriptură originală revelată de către Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Și de-ți vom arăta ție o parte din cele cu care-i amenințăm sau de te vom lua pe tine la Noi [lăsându-te să mori], datoria ta este [doar] propovăduirea și la Noi este socotirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Oare nu văd ei că Noi venim cu porunca Noastră pe Pământ și că Noi îl îngustăm? Allah judecă și nimeni nu poate împiedica judecata Sa și El este repede la socotire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Și au viclenit cei de dinaintea lor [împotriva Trimișilor lor], însă Plănuirea [deplină] este la Allah. El știe ce dobândește fiecare suflet, iar necredincioșii vor ști cine va avea parte de răsplata cea bună a Casei [Veșnice].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Cei care nu cred spun: „Tu nu ești un Trimis!” Spune [o, Mohammed]: „Allah este de ajuns ca Martor între mine și voi. [Și cine este mai drept decât] acela care are cunoștință despre Scriptură[14]?!”', '[14] Cei care recunosc adevărul datorită cunoștințelor lor despre scripturile anterioare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Alif. Lam. Ra[1]. [Aceasta este] o Carte pe care Noi ți-am revelat-o [o, Mohammed] pentru ca tu să-i scoți pe oameni din întuneric la lumină, cu Voia Domnului lor pe drumul lui Al-''Aziz [Celui Puternic] [și] Al-Hamid [Vrednic de Laudă].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Allah este Cel căruia Îi aparțin toate cele din Ceruri și de pe Pământ. Și vai celor necredincioși pentru pedeapsa cea aspră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'Aceia cărora le place această viață mai mult decât Viața de Apoi și-i împiedică [pe oameni] de la calea lui Allah și caută să le-o strâmbe, aceia se află într-o rătăcire adâncă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Și Noi nu am trimis niciun Profet decât cu limba poporului său, pentru ca să le facă limpede [revelația] și Allah împinge în rătăcire pe cine Voiește[2] El și călăuzește pe cine Voiește El, căci El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '[2] Pe cei care Îi refuză călăuzirea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'Noi l-am trimis pe Moise cu semnele Noastre, [spunându-i]: „Scoate poporul tău din întuneric la lumină și adu-le lor aminte de zilele lui Allah.” În aceasta sunt semne pentru toți cei răbdători și mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'Și [adu-ți aminte] când Moise a spus poporului său: „Amintiți-vă de Binefacerea lui Allah asupra voastră, când El v-a izbăvit de clanul lui Faraon care v-a supus la rău chin, i-a măcelărit pe fiii voștri și le-a lăsat în viață pe femeile voastre! Și în aceasta a fost pentru voi mare încercare de la Domnul vostru!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'Și când Domnul vostru a vestit: „Dacă veți fi mulțumitori, vă voi înmulți [Binefacerile Mele], iar de veți fi nemulțumitori, pedeapsa Mea va fi aspră!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'Și Moise a spus: „Dacă voi și toți cei de pre Pământ sunteți nerecunoscători, [atunci aflați] că Allah este Ghany [Își este Sieși Deajuns, Cel Bogat] [și] că El este Hamid [Vrednic de Laudă]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Nu v-a venit vouă vestea despre cei de dinaintea voastră: poporul lui Noe și poporul ’Ad și poporul Thamud și cei de după ei și pe care numai Allah îi știe? Trimișii lor au venit la ei cu semne limpezi, însă ei și-au dus mâinile la gură[3] și au spus: „Cu adevărat noi nu credem [în mesajul] cu care ați fost trimiși și suntem într-o îndoială tulburătoare în privința aceleia la care ne chemați”.', '[3] Au fost date mai multe explicații pentru înțeles. Bazat pe concluzia versetului, Ibn Kathir a preferat explicația precum că acest gest a fost unul de negare și respingere.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Trimișii lor au spus: „Aveți voi îndoială în privința lui Allah, Creatorul Cerurilor și al Pământului, Care vă cheamă ca să vă ierte pentru o parte din păcatele voastre și vă dă vouă răgaz până la un termen hotărât[4]?” Și au răspuns [necredincioșii]: „Voi nu sunteți decât niște oameni ca și noi și voiți să ne abateți de la ceea ce adorau părinții noștri! Aduceți-ne o dovadă clară.”', '[4] Vă amână moartea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, 'Trimișii lor le-au răspuns: „Noi nu suntem decât niște oameni ca și voi, însă Allah Binecuvântează pe cine Voiește El dintre robii Săi. Nu ne revine nouă să vă aducem dovadă, decât numai cu Îngăduința lui Allah. Și în Allah trebuie să se încreadă dreptcredincioșii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, 'Și cum să nu ne încredem noi în Allah, când El ne-a călăuzit pe căile noastre [pe care trebuia să le urmăm]? Însă noi vom îndura orice durere ne veți aduce. Și în Allah trebuie să se încreadă cei care se încred.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Dar cei care nu credeau au spus către trimișii lor: „Noi vă vom alunga din țara noastră, dacă nu vă întoarceți la religia noastră!” Dar Domnul lor le-a revelat: „Cu adevărat, Noi îi vom nimici pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, 'Și vă vom stabili pe voi pe acest pământ, după ei. Aceasta pentru cei care se tem de întâlnirea cu Mine[5] și se tem de amenințarea Mea.”', '[5] „Să stea [pentru judecată] în fața Mea”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, 'Ei au cerut decizia [victoria de la Allah], însă fiecare trufaș îndărătnic a fost înfrânt,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'În urma lui se află Gheena și va fi el adăpat cu apă de puroi[6],', '[6] Ce rezultă din pielea locuitorilor Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Pe care el o va sorbi cu înghițituri mici și abia o va putea, înghiți. Și moartea vine la el din toate părțile, însă el nu va fi mort și va avea el [parte de] osândă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Pilda celor care nu cred în Domnul lor este că faptele lor sunt ca cenușa în care suflă vântul cu putere într-o zi furtunoasă. Ei nu vor avea niciun folos din ceea ce agonisesc. Aceasta este rătăcire adâncă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Oare nu vezi că Allah a creat Cerurile și Pământul în adevăr? Dacă El ar vrea, v-ar face să dispăreți și ar aduce făpturi noi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'Și acest lucru nu este greu pentru Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'Și toți se vor înfățișa [pentru judecată] dinaintea lui Allah și vor spune cei slabi către cei care s-au arătat îngâmfați: „Cu adevărat noi v-am urmat pe voi, deci puteți voi să ne fiți de vreun folos împotriva osândei lui Allah?” Și ei vor spune: „Dacă ne-ar fi călăuzit Allah, v-am fi călăuzit și noi. Acum este la fel pentru noi dacă suntem mâhniți sau avem răbdare, căci nu este pentru noi scăpare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'Și Șeitan va spune când totul va fi hotărât: „Cu adevărat, Allah v-a făcut vouă o făgăduință adevărată. [Va spune] V-am făgăduit și eu, însă v-am trădat. Eu nu am avut nicio putere asupra voastră, decât că eu v-am chemat, iar voi mi-ați răspuns. Deci nu mă învinovățiți pe mine, ci învinovățiți-vă pe voi înșivă! Eu nu vă pot fi de niciun ajutor, și nici voi nu-mi puteți fi de niciun ajutor. Cu adevărat, eu mă socotesc nevinovat de faptul că voi m-ați făcut cândva asociat [al lui Allah]. Nelegiuiții [politeiștii] vor avea parte de osândă dureroasă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'Cei care cred și săvârșesc fapte bune vor fi duși să intre în grădini pe sub care curg râuri și în ele vor sălășlui veșnic - cu Voia Stăpânului lor. Iar salutul lor în ele va fi: „Pace [vouă]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Nu vezi ce pildă a dat Allah pentru cuvântul bun? El este ca un pom bun, cu rădăcina neclintită și cu ramuri [ce se înalță] în Cer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'El dă fructe tot timpul - cu Voia Domnului său. Și Allah dă Pilde oamenilor pentru ca ei să-și aducă aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'Iar Pilda unui cuvânt rău este ca un pom rău care a fost smuls de pe fața Pământului și care nu mai are pic de statornicie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Allah îi întărește pe cei care cred cu vorbe hotărâte[7] atât în viața aceasta, cât și în Viața de Apoi[8]. Allah îi duce în rătăcire pe cei nelegiuiți și Allah face ceea ce Voiește.', '[7] Mărturisirea că nu există altă divinitate în afară de Allah și că Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) este Mesagerul lui Allah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Nu i-ai văzut pe cei care au schimbat Îndurarea lui Allah cu necredința și au adus poporul lor în casa pieirii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, '[Este] în Gheena, în care vor arde și ce rău sălaș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'Și i-au făcut lui Allah parteneri care să-i ducă în rătăcire [pe oameni] de la calea Lui. Spune: „Veseliți-vă [în această viață], căci sfârșitul vostru va fi în Foc.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, '[O, Mohammed] spune robilor Mei care cred să împlinească Rugăciunea [As-Salat] și să dăruiască într-ascuns și pe față din ceea ce le-am dat spre viețuire, înainte de a veni Ziua în care nu va fi nici răscumpărare, nici prietenie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Allah este Cel care a creat Cerurile și Pământul și a pogorât din cer apa, cu care scoate pentru voi din roade mijloc de viețuire. El a supus pentru voi corăbiile care plutesc pe mare, la porunca Sa, și a supus pentru voi râurile', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'Și a supus pentru voi Soarele și Luna, amândouă urmându-și cursul fără oprire, și a supus pentru voi noaptea și ziua .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'Și v-a dat El din toate câte le-ați cerut. Și de ați socoti Binefacerile lui Allah, nu le-ați putea număra. Dar omul este cu adevărat nelegiuit și necredincios[9].', '[9] Nu crede și neagă Favoarea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'Și [spune, o, Mohammed] când Avraam a spus: „Doamne, fă acest oraș un loc sigur și ferește-mă pe mine și pe fiii mei [ca] să nu-i adorăm pe idoli!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'Doamne, cu adevărat ei i-au dus în rătăcire pe mulți oameni. Iar cel ce mă va urma va fi dintre ai mei, iar cel ce nu mi se va supune – cu adevărat, Tu ești Gafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'Doamne, eu am așezat o parte din urmașii mei într-o vale fără verdeață, în apropiere de Casa Ta cea Sfântă. Doamne, pentru ca ei să împlinească Rugăciunea [As-Salat]! Și fă inimile unor oameni să încline cu dragoste către ei și dă-le lor din roade spre viețuire, poate că ei vor fi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'Doamne, cu adevărat, Tu Știi și ce ținem ascuns și ce lăsăm să se vadă, căci nu-I este nimic ascuns lui Allah, nici de pe Pământ și nici din Cer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Laudă lui Allah, care mi i-a dat mie, în ciuda bătrânețelor mele, pe Ismail și pe Isaac. Domnul meu este Cel care aude rugăciunile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'Doamne, fă ca eu să împlinesc Rugăciunea [As-Salat] cu sârguință, ca și o parte din urmașii mei! Și primește ruga mea, Doamne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'Doamne, iartă-mi mie și părinților mei și dreptcredincioșilor în Ziua când se va face socoteala.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'Să nu crezi că Allah nu este cu luare aminte la ceea ce săvârșesc nelegiuiții, însă El doar le dă lor răgaz până într-o Zi în care privirile lor vor fi împietrite [de spaimă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, 'În vreme ce ei vor alerga cu capetele ridicate, cu ochii rătăciți și cu inimile goale[10].', '[10] Aceasta este starea lor în morminte, în timpul Învierii. Capetele lor vor fi ridicate în sus și fixate de teroare, neputând nici să se întoarcă înapoi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Și [o, Mohammed] prevestește-i pe oameni despre Ziua în care va veni peste ei Pedeapsa și în care cei ce au fost nelegiuiți vor spune: „Doamne, păsuiește-ne pe noi pentru un termen scurt, ca să răspundem Chemării Tale și să-i urmăm pe Trimiși.” [Dar le va fi spus:] „Dar oare n-ați jurat voi mai înainte că pentru voi nu va fi niciun sfârșit?”[11]', '[11] De binecuvântările pe care Allah vi le-a dat în viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'Voi ați locuit în sălașurile celor care au fost nelegiuiți față de ei înșiși și vi s-a arătat vouă limpede ce am făcut cu ei. Și v-am dat vouă [multe] pilde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, 'Au plăsmuit ei vicleșug, însă vicleșugul lor este la Allah, chiar de-ar fi vicleșugul lor [într-atât de puternic] încât să dispară munții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, 'Și să nu socotești că Allah nu-Și ține făgăduința făcută Trimișilor Săi. Allah este Al-’Aziz [Puternic] Stăpânul Răzbunării.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, '[Va fi] în Ziua în care Pământul va fi schimbat cu un altul, ca și Cerurile, și ei [toate creaturile] se vor înfățișa dinaintea lui Allah Al-Uahid [Cel Unic], Al-Qahhar [Biruitorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'Și în Ziua aceea îi vei vedea pe păcătoși legați unii de alții cu lanțuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Iar straiele lor vor fi din catran și focul le va acoperi chipurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, '[Toate acestea] pentru ca Allah să răsplătească fiecare suflet după ce și-a agonisit. Cu adevărat, Allah este repede la socotire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, 'Acesta [Coranul] este o vestire pentru oameni, pentru ca să fie preveniți prin ea și pentru ca să știe că El este un Dumnezeu Unic și să ia aminte cei înzestrați cu judecată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Alif, Lam, Ra[1]. Acestea sunt Versetele Cărții și ale unui Coran limpede.', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Poate că cei care nu au crezut vor dori[2] să fi fost musulmani.', '[2] În Ziua Judecății de Apoi sau la momentul morții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Lasă-i să mănânce și să se bucure și speranța [falsă] să-i desfete pentru că ei vor ști [pe urmă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, 'Și Noi nu am nimicit nicio cetate fără ca ea să nu fi avut un termen hotărât', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Niciun neam nu poate să grăbească termenul său și nici să-l întârzie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Și ei [meccanii] spun: „O, tu cel căruia i-a fost pogorât Coranul, tu ești nebun[3].', '[3] Literar: „posedat de djinn”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'De ce nu ne aduci tu Îngerii, dacă ești tu dintre cei care spun adevărul?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Noi nu facem să coboare Îngerii decât cu Adevărul[4]. Și atunci ei [necredincioșii] nu vor mai fi păsuiți.', '[4] Cu un mesaj sau așa cum sugerează versetul pentru a îndeplini o pedeapsă promisă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Cu adevărat, Noi am pogorât Mesajul [Coranul] și cu adevărat Noi îi vom fi păzitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'Și cu adevărat, Noi am trimis [Profeți] mai înainte de tine [o, Mohammed] la sectele popoarelor vechi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'Și nu a venit la ei un Trimis că numaidecât l-au și batjocorit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Astfel facem Noi [necredința] să intre în inimile nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Ei nu cred în ea [Carte] în ciuda a ceea ce s-a întâmplat cu obiceiul popoarelor anterioare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Și [chiar] dacă le-am deschide o poartă din Cer și ei ar ajunge să tot urce prin ea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'Ei ar spune cu siguranță: „Ochii noștri au fost doar închiși. Dimpotrivă noi suntem un popor de [oameni] fermecați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Și Noi am pus în Cer stele mari și l-am înfrumusețat pentru privitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'Și l-am păzit Noi de orice șeitan afurisit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'În afară de cel care a ascultat pe furiș, dar în urma căruia a pornit flacăra mistuitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'Iar Pământul l-am întins Noi și am aruncat pe el munți neclintiți și am lăsat să crească de toate cu măsură cumpănită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'Și v-am dat Noi vouă pe el [pe Pământ] cele de trebuință pentru trai, ca și pentru aceia pe care voi nu-i hrăniți[5].', '[5] Allah a pus în serviciul vostru alți oameni și animale cărora Allah le asigură traiul. Un alt înțeles este și că Allah asigură traiul pentru viața voastră și pentru toate celelalte creații.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'Și nu sunt lucruri ale căror hambare să nu se afle la Noi și pe care Noi să nu le trimitem cu măsură cunoscută [anumită].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Și Noi trimitem vânturile mănoase[6] și trimitem apă din Cer pe care v-o dăm de băut, însă voi nu o puteți strânge [având control asupra sa].', '[6] Cauzând precipitații în Nori sau ducând polen');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'Cu adevărat, Noi dăm viață și dăm moarte și Noi suntem moștenitori[7].', '[7] Allah rămâne după ce toată creația a murit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'Noi îi Știm pe aceia dintre voi care au fost mai înainte și Noi îi Știm și pe cei care n-au venit încă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'Și cu adevărat, Domnul tău îi va aduna pe ei, iar El este Hakim [Înțelept] [și] ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Și cu adevărat, Noi l-am făcut pe om din lut tare, provenit dintr-un nămol moale,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'Iar pe djinn Noi l-am făcut și mai înainte, din focul fierbinte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'Și [adu-ți aminte, o, Mohammed] când le-a zis Domnul tău Îngerilor: „Eu am să fac un om din lut tare, provenit dintr-un nămol moale,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'Iar când îl voi face și voi sufla în el din Duhul[8] Meu, voi să cădeți dinaintea lui, prosternându-vă. ”', '[8] Elementul vieții și al sufletului pe care Allah le-a creat pentru acel corp, nu sufletul Său sau o parte din El (așa cum unii cred, în mod eronat)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Și s-au prosternat toți Îngerii laolaltă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'Cu excepția lui Iblis[9], care s-a împotrivit să fie împreună cu cei ce s-au prosternat.', '[9] Care făcea parte dintre djinni. A se vedea 18:50');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, '[Allah] a spus: „O, Iblis! De ce nu ești tu împreună cu cei care se prosternează?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, 'El a răspuns: „Eu nu mă voi prosterna dinaintea unui om pe care l-ai făcut din lut tare, provenind dintr-un nămol moale.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, '[Allah] a spus: „Ieși din el[10] și cu adevărat, tu ești izgonit.”', '[10] Din Paradis sau din Ceruri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'Și blestemul [să fie] asupra ta până în Ziua Judecății”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, 'Dar el a spus: „Doamne, atunci dă-mi mie păsuire până în Ziua în care ei vor fi înviați! ”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, '[Allah] a spus: „Cu adevărat, tu vei fi dintre cei păsuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, 'Până în Ziua timpului hotărât.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, '[Iblis] a spus: „Doamne, pentru că m-ai dus în rătăcire, le voi împodobi lor [lucrurile de] pe Pământ și-i voi duce pe ei toți în rătăcire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'În afară de robii Tăi curați și aleși dintre ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, '[Allah] a spus: „Acesta este un Drum Drept [care duce] către Mine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, 'Cu adevărat, tu nu vei avea putere asupra robilor Mei, în afară numai de cei care te-au urmat dintre cei amăgiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'Și cu adevărat, Iadul este locul promis pentru ei toți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'El are șapte porți și fiecare poartă are o parte anumită dintre ei[11].”', '[11] Cei care îl urmează pe Șeitan');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Cu adevărat, cei cu frică vor fi în Grădini și la izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, '[Și le va fi spus]: „Intrați în ele în pace și cu siguranță.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Și Noi vom scoate pizma[12] din piepturile lor și ca frații vor ședea pe paturi (sau divane) unii în fața altora.', '[12] A se vedea 7:43');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Nu-i va atinge în ele osteneala și nici nu vor fi ei scoși din ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, '[O, Mohammed] vestește-le robilor Mei că Eu sunt Al-Ghafur [Iertătorul], Ar-Rahim [Îndurătorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, 'Și că aceasta este Pedeapsa Mea care este un chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'Și vestește-i pe ei despre oaspeții lui Avraam,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'Când au intrat la el și au spus „Pace”, iar [Avraam] le-a răspuns: „Ne este nouă teamă de voi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, '[Îngerii] au spus: „Nu-ți fie teamă! Noi îți aducem vestea bună a [nașterii] unui băiețel plin de învățătură. ”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, 'Și el a răspuns: „Îmi aduceți voi mie veste bună când m-au ajuns bătrânețile? Ce veste bună să-mi mai aduceți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, 'Ei au spus: „Îți vestim Adevărul, deci nu fi dintre aceia care deznădăjduiesc.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, 'El a răspuns: „Dar cine deznădăjduiește în privința Îndurării Domnului său, în afară de cei rătăciți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, '[Avraam] a spus: „Și ce vreți voi, o, Mesagerilor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, 'Ei au răspuns: „Cu adevărat, noi suntem trimiși la un popor de nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, 'Cu excepția familiei lui Lot pe care o vom mântui în întregime,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, 'Mai puțin pe soția lui.” Noi [Allah] am hotărât ca ea să fie dintre cei nimiciți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'Și când au venit Mesagerii la casa lui Lot,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, 'El le-a spus: „Cu adevărat, voi sunteți [pentru mine] un neam de necunoscuți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, 'Și ei i-au răspuns: „Dar am venit la tine, aducând [pedeapsa] pentru cele de care s-au îndoit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, 'Și ți-am adus noi Adevărul, și cu siguranță noi spunem Adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Deci pleacă cu familia ta spre sfârșitul nopții și mergi în urma lor și să nu se uite înapoi vreunul dintre voi, ci mergeți unde vi se poruncește.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'Și Noi i-am vestit lui această poruncă, pentru că aceia [păcătoșii] să fie nimiciți până dimineața.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'Și au venit locuitorii cetății [la el] bucuroși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, '[Lot] le-a spus: „Aceștia sunt oaspeții mei, deci nu-mi faceți rușine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, 'Și fiți cu frică de Allah și nu mă faceți de rușine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, 'Ei au spus: „Nu ți-am oprit noi [să aperi] oamenii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, '[Lot] a spus: „Acestea sunt fiicele mele[13], dacă voiți voi să faceți [o căsătorie permisă].”', '[13] Femeile din comunitatea sa care se puteau căsători');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, 'Pe viața ta, [o, Mohammed], cu adevărat ei rătăceau în aiureala lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'Așadar, la răsăritul Soarelui i-a prins pe ei strigătul[14]', '[14] A se vedea 11:67');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'Și Noi am răsturnat [cetatea] cu susul în jos și am lăsat să plouă peste ei pietre de lut întărit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'Și cu adevărat, în aceasta sunt semne pentru cei care știu să judece limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'Și cu adevărat, ea [cetatea] este pe un drum cunoscut de toți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'Și cu adevărat, întru aceasta este un semn pentru credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'Și locuitorii din Al-Ayka [poporul lui Madyan] erau [de asemenea] nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'Și Noi ne-am răzbunat pe ei și, cu adevărat, amândouă [cetățile] sunt pe un drum cunoscut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'Și cu adevărat locuitorii din Al-Hijr[15] [Thamud] i-au socotit pe trimiși drept mincinoși.', '[15] Valea Stâncii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'Și le-am adus semnele Noastre, însă ei s-au abătut de la ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Și ei își scobeau în munți case, trăind în siguranță,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'Însă strigătul i-a lovit în zorii dimineții,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'Și nu le-a fost lor spre folos ceea ce au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Și Noi nu am creat Cerurile și Pământul, precum și ceea ce este între ele, decât cu dreptate. Și, cu adevărat, Ceasul va veni, [fără îndoială]! Deci iartă-le lor cu frumoasă iertare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'Cu adevărat, Domnul tău este Al-Khallaq [Creatorul] [și] al-''Alim [Atoateștiutorul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Noi ți-am dat [o, Mohammed] șapte [Versete][16] dintre cele care se repetă și Coranul cel Măreț.', '[16] Referindu-se la Surat al-Fatihah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Nu-ți îndrepta ochii spre lucrurile pe care Noi le-am dat ca bucurie trecătoare unora dintre ei [necredincioșii] și nici nu fi trist pentru ei, ci pleacă aripa ta[17] peste dreptcredincioși.', '[17] Arată-le bunătate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, 'Și spune: „Cu adevărat, eu sunt prevestitorul cel deslușit” -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, '[Ți-am trimis ție Coranul], precum am trimis [Scripturi] celor ce au împărțit [între ei][18],', '[18] Evreii și creștini care s-au separat de învățăturile Profeților lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'Care au împărțit Coranul în bucăți[19].', '[19] Acceptând o parte și respingând altă parte în funcție de înclinațiile proprii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'Și - pe Domnul tău! - de la toți vom cere socoteală', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, 'Pentru ceea ce au făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Atunci vestește, ceea ce ți se poruncește[20] și nu-i băga în seamă pe politeiști.', '[20] Implicația este „Astfel îi vei putea separa pe necredincioși de credincioși.”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'Cu adevărat, Noi suntem de ajuns pentru tine împotriva zeflemitorilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, 'Cei care Îi asociază lui Allah un alt Dumnezeu. Dar ei vor ști [în curând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Și Noi știm prea bine că pieptul ți se strânge pentru ceea ce spun ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'Însă adu laude Domnului tău și fii printre cei care [I] se prosternează [Lui]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'Și adoră-L pe Domnul tău până ce-ți va veni sfârșitul [moartea].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Porunca lui Allah vine, deci nu o grăbiți. Mărire Lui! El este deasupra a ceea ce Îi asociază Lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'El îi trimite pe Îngeri cu revelația, după porunca Sa, asupra acelora care Voiește El dintre robii Săi, [spunând]: „Preveniți că nu există altă divinitate în afară de Mine și fiți cu frică de Mine, așadar!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'El a creat Cerurile și Pământul cu adevăr. El este deasupra a ceea ce Îi asociază Lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'El l-a făcut pe om dintr-o picătură și dintr-o dată[1] el [omul] este cârtitor învederat.', '[1] Atunci când devine puternic și independent');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'Și vitele le-a făcut pentru voi, de la ele aveți căldură[2] și alte foloase și de la ele și mâncați.', '[2] Îmbrăcăminte, corturi etc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'Ele sunt pentru voi mândrețe, când le adunați [seara] și când le scoateți la păscut [dimineața];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'Ele poartă poverile voastre către o țară unde nu ați putea ajunge decât cu trudă mare. Cu adevărat, Domnul vostru este Ra''uf [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'Și [El a făcut] caii, catârii și măgarii, să călăriți pe ei și ca podoabă și El creează ceea ce voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, 'Lui Allah îi revine [să arate prin mare Mila Sa] calea cea dreaptă și printre ele [căile, se află] și cele false. Dar dacă El ar Voi, v-ar călăuzi pe toți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'El este Cel care trimite apă din Cer pentru voi. Din ea este de băut pentru voi și din ea cresc tufișurile, unde voi vă pașteți cirezile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Din ea El face să crească pentru voi semănăturile, măslinii, curmalii, vița de vie și tot felul de roade. Cu adevărat, în aceasta este dovadă pentru un neam [de oameni] care chibzuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'El a supus pentru voi noaptea și ziua, Soarele și Luna. Și Stelele sunt supuse, prin Porunca Lui. Și întru aceasta sunt semne pentru un neam [de oameni] care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'Și [a supus] ceea ce a creat pentru voi pe Pământ de felurite culori. Și întru aceasta este un semn pentru un neam de oameni care își aduc aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'El este Cel care a supus marea, pentru ca voi să mâncați din ea carne proaspătă și să scoateți din ea podoabă pe care să o purtați. Și vezi corăbiile care o brăzdează ca să căutați Harul Său. Și poate că voi veți fi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'El a așezat pe Pământ munți statornici, ca să nu se clatine cu voi, râuri și drumuri, poate că voi veți fi călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'Și semne de reper. Și după stele ei se călăuzesc [de asemenea][3].', '[3] Prin deșert sau noaptea pe mare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Atunci este Cel care creează la fel ca cel care nu creează? Oare voi nu sunteți cu luare aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Și de ați [vrea să] socotiți Binefacerile lui Allah, voi nu veți reuși să le numărați. Cu adevărat, Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Și Allah Știe atât ceea ce voi țineți ascuns, cât și ceea ce dezvăluiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'Însă cei pe care îi cheamă în locul lui Allah nu creează nimic, ci ei sunt creați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, 'Ei sunt [de fapt] morți[4], nu sunt vii, și ei nu știu când [oamenii] vor fi înviați.', '[4] Neînsuflețiți sau fără putere de înțelegere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Domnul vostru este un Domn Unic. Iar inimile celor care nu cred în Viața de Apoi tăgăduiesc [Unicitatea lui Allah] și ei sunt trufași.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'Fără îndoială că Allah Știe ce ascund și ce dezvăluie ei. Cu adevărat, El nu-i iubește pe cei trufași.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'Dacă sunt întrebați: „Ce a pogorât Domnul vostru?” ei răspund: „Legende ale popoarelor anterioare,”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'Ei vor avea de purtat păcatele lor în întregime, în Ziua Învierii, precum și o parte din păcatele celor pe care îi duc în rătăcire, fără de știință. Fără îndoială, rea este [povara] ce vor avea de purtat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'Au viclenit cei care au fost mai înainte de ei, însă Allah a năruit chiar temeliile zidirii lor și acoperișul s-a prăbușit peste ei[5] și chinul a căzut peste ei, de unde nu se așteptau.', '[5] Allah a făcut ca planul lor să eșueze și le-a expus complotul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'Apoi, în Ziua Învierii, El îi va acoperi de rușine și le va spune: „Unde sunt semenii Mei, pentru care voi i-ați certat [pe credincioși]?” Cei cărora li s-a dat știința vor spune: „Rușinea și răul se abat astăzi asupra necredincioșilor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, 'Cei cărora Îngerii le iau viața când sunt nelegiuiți cu ei înșiși și [care] apoi se vor supune cu umilință, [spunând]: „Noi nu am făcut nimic rău.” Ba da, cu adevărat, Allah Știe ce ați făcut voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Intrați, așadar, pe porțile Iadului și în el veți petrece veșnic. Ce rău sălaș va fi pentru cei aroganți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'Și li se va spune celor care au avut frică [de Allah]: „Ce a pogorât Domnul vostru?” Iar ei vor spune: „[Ceea ce este] bine.” Cei care fac bine în această lume vor avea parte de bine, însă locuința din Viața de Apoi va fi și mai bună. Și ce minunată va fi locuința celor evlavioși -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, 'Grădinile Edenului, în ele vor intra, iar pe sub ele vor curge râuri. În ele vor avea ceea ce vor voi. Astfel îi răsplătește Allah pe cei evlavioși -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, 'Celor buni, cărora le iau sufletele, [Îngerii] le vor spune: „Pace vouă! Intrați în Rai, pentru ceea ce ați făcut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Și ce pot să aștepte [necredincioșii] decât să vină la ei Îngerii sau să le vină Porunca Domnului tău? Așa au făcut și cei care au fost înaintea lor și nu i-a nedreptățit Allah, ci ei înșiși s-au nedreptățit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, 'Și i-au lovit consecințele rele a ceea ce au săvârșit și cele pe care le-au luat în derâdere i-au înconjurat din toate părțile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'Și cei care i-au făcut asociați lui Allah spun: „Dacă ar fi Voit Allah, noi nu am fi adorat nimic în afară de El - nici noi, nici părinții noștri - și nu am fi oprit nimic altceva afară de ceea ce El a oprit!”. Așa au făcut cei de dinaintea lor. Dar oare le revine Trimișilor altceva decât propovăduirea limpede?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Și Noi am trimis la fiecare comunitate un Mesager [ca să le spună]: „Adorați-L pe Allah și țineți-vă departe de Taghut[6].” Pe unii dintre ei i-a călăuzit Allah, însă altora le-a fost hărăzită rătăcirea. Călătoriți prin lume și vedeți care a fost sfârșitul celor care i-au socotit mincinoși [pe Mesagerii Noștri]!', '[6] Obiecte false de adorare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, '[Chiar] dacă tu [o, Mohammed] voiești cu tot dinadinsul călăuzirea lor, [să știi că] Allah nu-i călăuzește pe cei care îi duce în rătăcire[7], iar ei nu vor avea ajutători.', '[7] Drept rezultat al alegerii lor de a respinge călăuzirea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Și ei jură pe Allah cu cele mai grele jurăminte [că] Allah nu-i va învia pe cei care au murit. Ba da, promisiunea [lui Allah] este adevărată, dar cei mai mulți dintre oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, '[El îi va învia] pentru a le arăta limpede cele asupra cărora au fost cu neînțelegere și pentru ca cei care nu cred să știe că ei au fost mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Cu adevărat, când Noi Voim un lucru, singurul Cuvânt pe care-l Spunem este „Fii!” și el este.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Și celor care au migrat pentru Allah, după ce au suferit nedreptate, Noi le vom pregăti [locuință] bună în această viață, dar răsplata lor în Viața de Apoi va fi și mai mare. Măcar dacă ei ar ști.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, 'Aceștia sunt cei care au fost statornici și au avut încredere în Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Și Noi nu am trimis mai înainte de tine decât bărbați, cărora Noi le-am pogorât revelații. Întrebați-i pe oamenii pricepuți în Cărți, dacă voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, '[I-am trimis cu] semne limpezi și cu Scripturi. Iar ție ți-am pogorât Noi Mesajul [Coranul], pentru ca tu să le tâlcuiești oamenilor deslușit ceea ce a fost pogorât pentru ei, - poate că ei vor chibzui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'Oare sunt siguri cei care au pus la cale fapte rele că Allah nu va face Pământul să-i înghită sau că nu va veni asupra lor osânda de acolo de unde ei nu se așteaptă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'Sau să-i facă să piară în timpul umbletului lor, fără ca ei să aibă o ieșire?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Sau să-i facă să piară în plină spaimă? Dar cu adevărat Domnul vostru este Ra''uf [Milostiv], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Oare n-au văzut ei că toate lucrurile pe care le-a creat Allah - având umbră ce se întinde la dreapta și la stânga - se prosternează în fața lui Allah cu supunere?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'Și în fața lui Allah se prosternează toate vietățile din Ceruri și de pe Pământ; și la fel și Îngerii, fără ca ei să fie trufași.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'Se tem de Domnul lor de deasupra lor și fac ceea ce li se Poruncește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Și Allah spune: „Nu luați două[8] divinități. Cu adevărat, El [Allah] este Un Singur Dumnezeu, deci fiți cu frică numai de Mine!”', '[8] Însemnând nu mai mult de Un Singur Dumnezeu');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'Ale Lui sunt cele din Ceruri și cele de pe Pământ și la El este supunerea veșnică. Și oare vă temeți voi de altcineva în afara lui Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'Voi nu aveți binefacere decât de la Allah. Apoi, dacă vă lovește un rău, voi nu vă rugați [pentru ajutor] decât Lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'Apoi, dacă El v-a mântuit de la rău, iată că o parte dintre voi Îi fac Stăpânului lor asociați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'Pentru a tăgădui ceea ce le-am dăruit lor. Bucurați-vă [pentru un timp]. Apoi veți cunoaște voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'Ei fac o parte din ceea ce le-am dat lor spre viețuire [idolilor pe care] nici nu-i cunosc. Pe Allah, veți fi întrebați pentru ceea ce născociți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, 'Și ei îi atribuie lui Allah – Mărire Lui! – fiice[9], iar lor ceea ce poftesc ei [fii]', '[9] Susținând că Îngerii sunt fiicele lui Dumnezeu');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'Iar dacă vreunuia dintre ei i se vestește [nașterea] unei fiice, chipul lui devine negru și el e plin de mânie,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Se ascunde de lume din cauza răului ce i s-a vestit. Să o țină el, în ciuda umilinței, sau să o îngroape în țărână? Ce proastă judecată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'Celor care nu cred în Viața de Apoi li se potrivește pilda răului, iar lui Allah I se potrivește pilda cea mai înaltă, căci El este Al-''Aziz [Atotputernic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Și dacă Allah ar voi să-i apuce pe oameni pentru nelegiuirea lor, nu ar lăsa pe el [pe Pământ] nicio vietate, însă El îi amână până la un termen hotărât, iar dacă sorocul lor sosește, atunci El nu-i mai întârzie nici măcar cu un ceas și nici nu-i grăbește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Și ei Îi atribuie lui Allah ceea ce lor nu le place [de ex. fiice], iar limbile lor născocesc minciuni când spun că ei vor avea ceea ce este mai bun! Fără îndoială că ei vor avea parte de Iad [și în el ei vor fi pedepsiți și] uitați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'Pe Allah, am trimis Noi [Profeți] și la alte comunități înainte de tine, însă Șeitan le-a împodobit faptele lor și el este tovarășul lor astăzi, dar ei vor avea parte de pedeapsă dureroasă [în Lumea de Apoi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Și nu ți-am pogorât ție [o, Mohammed] Cartea decât ca să le deslușești lor limpede cele asupra cărora aveau ei neînțelegeri și ca un ghid și ca îndurare pentru un popor [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Și Allah pogoară din Cer apa, cu care dă viață pământului după moartea lui. Cu adevărat, în aceasta este un semn pentru un popor [de oameni] care aud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Și cu adevărat aveți voi o pildă și la vite. Noi vă dăm să beți din ceea ce se află în burțile lor, între murdărie și sânge - un lapte curat, plăcut celor care-l beau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'Iar din roadele curmalilor și ale viței de vie luați băutură îmbătătoare și venit bun[10]. Cu adevărat, în aceasta este un semn pentru un popor [de oameni] care pricep.', '[10] Acest verset a fost revelat înainte de interzicerea băuturilor alcoolice. Se referă la faptul că în unele lucruri există atât avantaje cât și dezavantaje');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Și [iată ce] le-a revelat Domnul tău albinelor: „Faceți-vă case [stupi] în munți, în pomi și în ceea ce ei făuresc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, 'Apoi mâncați din toate roadele[11] și urmați căile ușoare ale Domnului vostru.” Din burțile lor iese o băutură cu felurite culori, în care este leac pentru oameni. În aceasta este cu adevărat un semn pentru un popor [de oameni] care chibzuiesc.', '[11] Substanțe delicioase găsite de albine');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Și Allah v-a creat pe voi și El vă face să muriți. Iar unii dintre voi vor ajunge până la cea mai decrepită vârstă [la bătrânețe], încât nu vor mai ști nimic, după ce au avut știință. Allah este ‘Alim [Atoateștiutor] [și] Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Allah i-a pus pe unii dintre voi înaintea altora în privința celor necesare viețuirii. Însă cei care au fost aleși nu dau din partea lor celor asupra cărora au deplină stăpânire [sclavi], pentru ca ei să fie egali întru aceasta. Oare tăgăduiesc ei Binefacerile lui Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Și Allah v-a făcut soții din voi înșivă și v-a dat El vouă de la femeile voastre fii și nepoți și v-a dat spre hrană din cele bune. Și iată cum cred ei în deșertăciune și nu cred în Binefacerea lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'Și adoră ei, afară de Allah, ceea ce nu le poate aduce lor nicio hrană din Ceruri și de pe Pământ, căci sunt fără de putere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Nu-I faceți, așadar, semeni lui Allah, căci Allah Știe, în vreme ce voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Allah dă ca exemplu: un sclav cumpărat, care nu are nicio putere și un altul pe care Noi l-am dăruit cu mijloace de trai bune, din care el face milostenie atât pe ascuns cât și pe față. Oare sunt ei egali? Laudă lui Allah! Dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Și Allah dă ca exemplu doi bărbați: unul dintre ei este mut, nu este în stare de nimic și devine o povară pentru stăpânul său, căci oriunde l-ar trimite, el nu aduce nimic bun. Oare este el egal cu acela care poruncește dreptatea și care este pe drumul cel drept?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'Ale lui Allah sunt cele neștiute din Ceruri și de pe Pământ. Iar Porunca [privitoare la] Ceas este ca o clipire din ochi sau chiar și mai scurtă. Cu adevărat, Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Allah v-a scos pe voi din pântecele mamelor voastre, fără ca voi să aveți știre de ceva, și v-a dat vouă auzul și văzul și inimile, pentru ca voi să fiți mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Oare nu văd ei păsările supuse din văzduhul Cerului, pe care nimeni nu le ține decât numai Allah? Întru aceasta sunt cu adevărat semne pentru un popor [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Și Allah v-a făcut casele voastre spre locuință și v-a făcut vouă din pieile vitelor case, care să vă fie ușoare în timpul plecării și în timpul așezării voastre, iar din lâna, din blana și din părul lor, [v-a făcut] veșminte și lucruri pentru un timp.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Și Allah v-a făcut vouă umbră din ceea ce a creat și v-a dat vouă adăposturi în munți și v-a făcut vouă straie care să vă ferească de arșiță și cămăși [din zale] care să vă apere de asprimea voastră. Astfel El desăvârșește binefacerea Sa asupra voastră, poate că voi veți fi supuși Voinței Sale [în Islam].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'Iar de se vor întoarce ei, tu [o, Mohammed] nu ești dator decât cu propovăduirea limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Ei recunosc Binefacerea lui Allah și apoi o tăgăduiesc, iar cei mai mulți dintre ei sunt nerecunoscători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'Și [spune despre] Ziua în care Vom ridica din fiecare comunitate un martor, nu li se va îngădui atunci celor care nu au crezut [să se dezvinovățească], nici nu vor fi ei iertați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Și când cei care au fost nelegiuiți vor vedea pedeapsa, iar ea nu le va fi ușurată și nici nu li se va mai da lor vreun răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'Și când cei care I-au făcut asociați [lui Allah] îi vor vedea pe semenii lor, vor spune: „O, Doamne! Aceștia sunt idolii noștri la care ne-am rugat în locul Tău!” Însă ei [idolii] le vor întoarce vorba, [spunând]: „Cu adevărat voi sunteți niște mincinoși.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'În Ziua aceea Îi vor arăta ei supunere deplină lui Allah și îi va părăsi pe ei ceea ce au născocit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Iar celor care nu au crezut și au împiedicat de la calea lui Allah, le vom adăuga Noi pedeapsă peste pedeapsă, pentru stricăciunea ce au făcut-o [pe Pământ].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'Și [spune de] Ziua în care vom ridica din fiecare comunitate un martor împotriva lor, chiar dintre ei [Trimisul lor]. Noi te vom aduce pe tine martor împotriva acestora. Și Noi ți-am trimis ție Cartea ca tâlcuire pentru toate lucrurile, călăuză, îndurare și bună vestire pentru musulmani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Cu adevărat, Allah poruncește dreptatea, împlinirea faptei bune și dărnicia față de rude și El oprește de la desfrâu, fapta urâtă și nelegiuire. El vă îndeamnă pentru ca voi să vă aduceți aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'Țineți-vă legământul față de Allah, după ce l-ați făcut și nu călcați jurămintele după ce le-ați întărit și după ce L-ați luat pe Allah drept chezaș pentru voi, căci Allah Știe ceea ce faceți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'Nu fiți ca [femeia] aceea care destramă torsătura ei, după ce fusese fermă și bine răsucită, în firicele, luându-vă jurămintele voastre un mijloc de a vă înșela între voi, pentru ca o comunitate să devină mai puternică decât o altă comunitate[12]. Allah nu face decât să vă încerce prin aceasta, iar în Ziua Învierii vă va arăta vouă deslușit [Adevărul] asupra acelor lucruri pentru care voi v-ați certat.', '[12] Nu jurați fals și nu încălcați un tratat sau contract doar pentru avantaje lumești');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Și dacă Allah ar fi Voit, v-ar fi făcut pe voi o singură comunitate, însă El lasă în rătăcire pe cine voiește El și călăuzește pe cine Voiește El[13]. Iar voi veți da socoteală neîndoielnic pentru ceea ce ați făcut.', '[13] Conform Științei Sale cu privire la preferința fiecărui suflet');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'Și nu luați jurămintele voastre drept mijloc pentru a vă înșela unii pe alții, astfel încât să alunece piciorul [vostru], după ce a fost bine întărit și să gustați voi răul [în această Viață] pentru că ați împiedicat de la Calea lui Allah, și să aveți parte de osândă cumplită [în Viața de Apoi]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'Și nu vindeți legământul cu Allah pentru un preț de nimic, căci numai la Allah se află ceea ce e mai bun pentru voi, dacă voi știți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Ceea ce aveți voi se termină, pe când ceea ce se află la Allah va rămâne mereu. Iar Noi îi vom răsplăti pe cei care sunt statornici după [faptele] cele mai bune pe care le-au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Pe cel ce face o faptă bună - bărbat sau femeie - și este credincios îl vom dărui Noi cu o viață bună. Și Noi îi vom răsplăti pe ei după [faptele] cele mai bune pe care le-au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Atunci când reciți Coranul, caută [mai întâi] adăpost la Allah împotriva lui Șeitan cel alungat și afurisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'Cu adevărat, el nu are nicio putere asupra acelora care cred și care în Domnul lor se încred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'El are stăpânire [și îi cârmuiește] doar pe aceia care îl iau drept ocrotitor și pe aceia care prin el [și pizmuirea lui] Îi fac asociați lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Când Noi înlocuim un Verset cu un alt Verset – și Allah Știe mai bine ceea ce pogoară! – ei spun: „Tu [Mohammed] ești numai un născocitor!” Însă cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'Spune: „L-a pogorât Duhul Sfânt [Îngerul Gavriil] de la Domnul tău întru adevăr ca să-i întărească pe cei care cred și să fie călăuză și bună vestire pentru musulmani!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Noi Știm că ei zic: „Îl învață pe el [Coranul] un om.” Dar limba aceluia spre care ei arată este străină [nearabă], în vreme ce aceasta este o limbă arabă limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Cu adevărat, pe aceia care nu cred în Versetele lui Allah, Allah nu-i va călăuzi și ei vor avea parte de pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Ci plăsmuiesc minciună numai cei care nu cred în Versetele lui Allah și aceia sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Cei care nu cred în Allah, după ce au crezut – în afară de cel care este silit [să nu creadă], dar inima lui este netulburată întru credință – asupra acelora care și-au deschis inima necredinței va veni mânie de la Allah și ei vor avea parte de chin cumplit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Aceasta pentru că ei au iubit viața lumească mai mult decât Viața de Apoi, iar Allah nu călăuzește poporul de necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'Aceștia sunt cei cărora Allah le-a pecetluit inimile, auzul și văzul și aceștia sunt cei nepăsători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'Fără îndoială că în Lumea de Apoi ei vor fi pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Însă Domnul tău, cu cei care au pribegit după ce au fost ispitiți și apoi au luptat și au îndurat, cu aceia Domnul tău va fi după aceasta Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, '[Amintește-le de] Ziua când fiecare suflet va veni și se va apăra pe sine și fiecare suflet va fi pe deplin răsplătit pentru ceea ce a săvârșit, fără ca ei să fie nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Allah dă ca exemplu o cetate: ea a fost în siguranță și în liniște, venind spre ea cele de trebuință pentru viețuire din toate părțile cu prisosință; apoi ea s-a arătat nemulțumitoare față de binefacerile lui Allah și Allah a făcut-o să guste veșmântul foametei și spaimei, [ca pedeapsă] pentru ceea ce au săvârșit [locuitorii ei].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'Și a venit la ei un Trimis din mijlocul lor, însă ei l-au socotit mincinos și i-a lovit pe ei osânda pentru că ei au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Atunci mâncați din ceea ce v-a hărăzit Allah, îngăduit și bun, și fiți mulțumitori pentru Binefacerea lui Allah, dacă Îl adorați pe El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'El v-a oprit vouă doar mortăciunea[14], sângele, carnea de porc și ceea ce a fost dedicat altcuiva decât lui Allah. Însă cu cel care a fost constrâns [de necesitate] - fără să se lăcomească sau să poftească - Allah este Ghafur [Iertător], Rahim [Îndurător].', '[14] Animalele care nu au fost sacrificate sau vânate doar pentru mâncare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'Și nu spuneți, luându-vă după limbile voastre care rostesc minciuni: „Acesta este îngăduit și acesta este oprit”, pentru a născoci minciună împotriva lui Allah. Cu adevărat, cei care născocesc minciuni împotriva lui Allah nu vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, 'Cu puțină bucurie [se vor desfăta], iar apoi de chin dureros vor avea ei parte', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'Evreilor le-am oprit Noi ceea ce ți-am spus înainte[15]. Noi nu i-am nedreptățit, ci ei înșiși au fost nedrepți cu ei.', '[15] A se vedea 6:146');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'Apoi cu cei care au săvârșit rău întru neștiință, iar după aceea s-au căit și s-au îndreptat, Domnul tău este după aceasta Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Cu adevărat, Avraam a fost un călăuzitor [lider] supus lui Allah, dreptcredincios și nu a fost dintre cei care Îi fac asociați lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'El a fost mulțumitor față de binefacerile Lui și El l-a ales și l-a călăuzit pe drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'Și i-am dăruit Noi bună parte în această lume, iar cu adevărat, în Lumea de Apoi el va fi printre cei drepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'Apoi ți-am revelat Noi [o, Mohammed]: „Urmează religia lui Avraam cel dreptcredincios, care nu a fost dintre cei care Îi fac asociați lui Allah.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Sabatul a fost orânduit doar pentru cei care nu s-au înțeles asupra lui, iar Domnul tău va judeca între ei în Ziua Învierii în privința celor asupra cărora au fost cu neînțelegere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'Cheamă la calea Domnului tău cu înțelepciune și bună îndemnare și discută cu ei cum e mai frumos. Cu adevărat, Domnul tău este mai bine Ştiutor al acelora care s-au abătut de la calea Sa și El este mai bine Știutor al celor care sunt bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Dacă pedepsiți [un dușman, o credincioșilor], atunci pedepsiți cu ceea ce voi ați fost pedepsiți, iar dacă răbdați, e chiar mai bine pentru cei răbdători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Și rabdă [o, Mohammed], căci răbdarea ta nu vine decât [cu ajutorul] lui Allah! Și nu fi mâhnit pentru ei și nu fi îngrijorat de ceea ce uneltesc ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Cu adevărat, Allah este cu aceia care sunt cu frică [de El] și cu aceia care sunt făcători de bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Mărire[1] Celui care l-a dus pe robul Său [profetul Mohammed] în timpul unei nopți de la Moscheea Al-Haram la Moscheea Al-Aqsa[2], a cărei împrejmuire am binecuvântat-o, ca să-i arătăm din semnele Noastre. Cu adevărat El este As-Sami'' [Cel care Aude Totul] [și] Al-Basir [Cel care Vede Totul]!', '[1] Deasupra oricărei imperfecțiuni sau greșeli
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'Și Noi i-am dat lui Moise Cartea, pe care am făcut-o drept călăuză pentru Fiii lui Israel, [spunând]: „Nu luați un alt ocrotitor afară de Mine[3],”', '[3] Încredeți-vă în Allah știind că El are Putere peste orice lucru');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, '[O, voi] urmași ai celor pe care Noi i-am purtat împreună cu Noe [în arcă]! El a fost cu adevărat un rob mulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'Și Noi le-am vestit Fiilor lui Israel în Carte: „Voi veți aduce stricăciune pe Pământ de două ori și vă veți ridica cu mare nelegiuire.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'Și când a venit timpul primei dintre cele două[4], Noi am trimis împotriva voastră robi de-ai Noștri dintre cei înzestrați cu mare putere și ei au cercetat lăuntrul căminelor[5] și acesta este un soroc [promis] ce se va fi îndeplinit.', '[4] Pedeapsa promisă pentru prima dintre cele două nelegiuiri
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Apoi Noi v-am dat vouă putere asupra lor și v-am înzestrat pe voi cu mai multe averi și mai mulți copii și v-am făcut o ceată cu putere mai mare în luptă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, '[Spunând]: „De veți face bine, pentru sufletele voastre veți face bine, iar de veți face rău, [tot] pentru ele va fi”. Și când va veni ultima [cea de-a doua] Promisiune, [Vom trimite dușmanii voștri și] vă vom întrista chipurile și vor intra în Moschee [Ierusalim] așa cum au intrat prima oară pentru ca să distrugă cu desăvârșire tot ceea ce au cucerit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, '[Atunci Allah a spus] „Se poate ca Domnul vostru să fie Îndurător cu voi. Dar de vă veți întoarce din nou [ la păcate], și Noi ne vom întoarce [pentru a vă pedepsi]. Și Noi am făcut Iadul drept temniță pentru necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Cu adevărat acest Coran călăuzește către ceea ce este mai drept și binevestește dreptcredincioșilor care împlinesc fapte bune că ei vor avea parte de mare răsplată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'Iar celor care nu cred în Ziua de Apoi le-am pregătit Noi chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'Și omul cheamă răul tot așa cum cheamă și binele, fiindcă omul este tare grăbit[6].', '[6] Nerăbdător, emoțional');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'Noi am făcut din noapte și din zi două semne și am șters apoi semnul nopții și am lăsat să se vadă semnul zilei, ca să căutați harul Domnului vostru și să știți numărul anilor și socotirea. Și Noi am tâlcuit toate lucrurile cu toată limpezimea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'Și fiecărui om i-am legat de gât faptele sale[7]. Iar în Ziua Învierii vom scoate pentru el o carte pe care el o va găsi deschisă.', '[7] După ce l-am instruit, Noi l-am făcut responsabil pentru propriul destin');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, '[Și i se va spune lui]: „Citește cartea ta! Astăzi tu ești de ajuns ca să fii pentru tine socotitor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Cel care urmează calea cea dreaptă o urmează numai pentru sine însuși, iar cel care rătăcește, rătăcește tot pentru sine însuși. Și nu va purta [un suflet] încărcat povara altuia și Noi nu am pedepsit [niciodată un popor] înainte de a-i trimite un Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Și dacă voim Noi să nimicim o cetate, le vom porunci celor îmbuibați din ea[8], însă ei, [dimpotrivă], se vor deda desfrâului. Atunci pedeapsa hotărâtă împotriva ei se va adeveri și Noi o vom nimici cu totul.', '[8] Să îl asculte pe Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'Dar câte generații am nimicit Noi după Noe! Iar Domnul tău este Khabir [îndeajuns Știutor] [și] este Basir [Cel care Vede] păcatele robilor Săi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Dacă cineva dorește [viața] cea pieritoare, Noi dăm degrabă în ea ceea ce Voim și cui Voim Noi. Apoi, Noi îi hotărâm lui Iadul, în care el va arde rușinat și lepădat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'Iar aceia care voiesc Lumea de Apoi și se trudesc cu râvnă pentru ea și sunt credincioși, râvna acelora va fi răsplătită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'Și le vom dărui Noi - atât acestora cât și acelora – din darurile Domnului tău, iar darurile Domnului tău nu sunt oprite [pentru nimeni].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Privește cum i-am ales Noi pe unii înaintea altora, însă în Lumea de Apoi sunt trepte și mai înalte [de diferențiere] și foloase mai alese.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Nu pune lângă Allah un alt zeu, ca să nu șezi rușinat și alungat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Și Domnul tău a poruncit să nu-L adorați decât pe El și să vă purtați frumos cu părinții voștri, iar dacă bătrânețile îi ajung pe unul dintre ei sau pe amândoi lângă tine, nu le ziceți lor „Of!”[9] și nu-i certa pe ei, ci spune-le vorbe cuviincioase.', '[9] O expresie de dezaprobare sau iritare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'Și coboară asupra lor aripa smereniei cu îndurare și spune: „Doamne, ai Milă de ei, căci ei m-au crescut [când am fost] mic.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'Domnul vostru știe mai bine ce se află în sufletele voastre, iar dacă sunteți voi cinstiți, atunci cu adevărat, El este Iertător cu aceia care se căiesc[10].', '[10] Allah le promite iertare celor care intenționează să facă fapte bune, se grăbesc să se căiască în urma păcatelor și greșelilor comise ca urmare a slăbiciunii umane');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, '„Și dă-i celui care ți-e rudă ceea ce i se cuvine, ca și nevoiașului și călătorului de pe drum [aflat la nevoie], însă nu risipi peste măsură,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Cu adevărat risipitorii sunt frații șeitanilor, iar Șeitan este nerecunoscător Domnului său.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'Și dacă [ești nevoit să] te întorci de la ei [nevoiași], așteptând Îndurarea Domnului tău, în care tu nădăjduiești, atunci spune-le lor o vorbă prietenoasă[11].', '[11] Dacă nu ai mijloace să le dai atunci');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Și nu ține mâna înlănțuită în jurul gâtului tău[12], dar nici nu o întinde de tot[13], ca să rămâi ocărât și întristat.', '[12] Refuzând să cheltuiești
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'Cu adevărat, Domnul tău dă cele de trebuință cu prisosință cui Voiește El sau le dă cu măsură. El este Khabir [Bine Știutor] al robilor Săi, Basir [Atoatevăzător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Și nu vă omorâți copiii voștri de frica sărăciei. Noi le vom asigura cele de trebuință ca și vouă. Omorârea lor este un păcat mare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'Și nu vă apropiați de preacurvie[14]. Cu adevărat, ea este o josnicie! Și ce rea cale este ea!', '[14] Evită toate situațiile ce ar putea duce la ea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'Și nu luați sufletul pe care Allah l-a socotit interzis, decât pe drept[15]. Dacă cineva a fost omorât pe nedrept, atunci dăm Noi putere celui mai înrudit cu el, însă acesta să nu întreacă limita în omor. Cu adevărat, el este ajutat [de lege].', '[15] Ca urmare a unei hotărâri juridice sau în timpul luptei împotriva dușmanilor voștri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'Și nu vă apropiați de averea orfanului, decât pentru ceva și mai bun[16], până ce el ajunge la vârsta maturității. Și țineți legământul, căci, cu adevărat, cu privire la legământ veți fi întrebați.', '[16] Pentru a mări averea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Dați măsura plină atunci când măsurați și cântăriți cu o balanță dreaptă. Acest lucru este mai bun [pentru voi] și urmarea va fi și ea mai bună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'Și nu urma [lucrul despre] care nu ai cunoștință. Cu adevărat, auzul și văzul și inima, pentru toate acestea vei fi întrebat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Și nu purcede pe Pământ cu semeție. Cu adevărat, tu niciodată nu vei despica Pământul și nici nu vei atinge înălțimea munților[17].', '[17] Omul, în toată aroganța sa este slab și mic');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Toate acestea sunt rele și sunt urâte de Domnul tău.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'Aceasta este din ceea ce Domnul tău ți-a revelat ție [o, Mohammed] cu înțelepciune. Și [o, voi oamenilor] nu așezați alături de Allah un alt dumnezeu, căci veți fi aruncați în Iad, certați și alungați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Oare v-a ales Domnul vostru pentru voi numai băieți și a luat [pentru Sine] fiice dintre Îngeri? Cu adevărat, voi spuneți un cuvânt grav.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'Noi am tâlcuit [pildele] în acest Coran, pentru ca ei [omenirea] să chibzuiască, însă aceasta nu face decât să le sporească [necredincioșilor] îndepărtarea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'Spune [o, Mohammed]: „Dacă ar fi alături de El și alți zei, așa cum spun, atunci [fiecare dintre] ei ar fi căutat o cale către Stăpânul Tronului.[18]”', '[18] Pentru a-I face pe plac, recunoscându-I superioritatea. O altă interpretare este „...ei ar fi căutat o cale” să Îl înlăture și să Îi ia Tronul.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Mărire Lui. El este mai presus decât ceea ce pretind ei cu prisosință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Îl preamăresc cele șapte Ceruri și Pământul și cei care se află în ele și nu este nimic care să nu-L preamărească și să nu-I aducă laude, însă voi nu pricepeți preamărirea lor. Cu adevărat, El este Halim [Blând], Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'Și când tu citești Coranul, Noi punem între tine și aceia care nu cred în Viața de Apoi un văl nevăzut[19].', '[19] Prevenind călăuzirea de a ajunge la ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'Și Noi punem peste inimile lor acoperăminte, astfel încât ei să nu-l înțeleagă, iar în urechile lor o greutate. Iar când tu Îl pomenești în Coran numai pe Domnul tău, ei întorc spatele, cu dezgust.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Noi știm prea bine cum ascultă ei, atunci când te ascultă pe tine și când sunt singuri șușotesc [între ei] iar cei nelegiuiți spun: „Voi nu urmați decât un bărbat vrăjit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Privește cu cine te-au asemuit pe tine[20]. Însă ei sunt rătăciți și nu pot găsi o cale [spre Adevăr].', '[20] Descriindu-l pe Profet (pacea și binecuvântarea lui Allah fie asupra sa) ca fiind un poet, un nebun sau sub influența magiei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Și ei spun: „Oare după ce vom deveni noi oase și resturi, vom mai putea fi înviați din nou?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, 'Spune: „De ați fi voi pietre sau fier', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'Sau o creatură care pare prea mare[21] în piepturile voastre.” Iar ei vor spune: „Cine ne va face pe noi să fim din nou?” Spune: „Acela care v-a creat pe voi prima oară.” Atunci ei vor clătina capetele spre tine[22] și vor spune: „Când va fi aceasta?” Spune: „S-ar putea să fie în curând -', '[21] Precum Cerurile și Pământului
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'În acea Zi, El vă va chema și voi Îi veți răspunde, preamărindu-L, și veți crede că voi nu ați rămas [în această lume] decât puțin [timp].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'Și spune-le robilor Mei să spună ceea ce este mai frumos; căci, cu adevărat, Șeitan stârnește vrajbă între ei, iar Șeitan este un dușman învederat al omului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Domnul vostru vă Cunoaște mai bine pe voi. Dacă El Voiește, va fi Milostiv cu voi, iar dacă El Voiește, vă va osândi pe voi. Și Noi nu te-am trimis [o, Mohammed] ca să fii răspunzător pentru ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Și Domnul tău îi Cunoaște mai bine pe fiecare din Ceruri și pe cei de pe Pământ și Noi i-am ales pe unii dintre Profeți înaintea altora și i-am dat Noi lui David Psalmii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'Spune: „Chemați-i pe cei pe care voi i-ați pretins în locul Lui [drept zei], pentru că ei nu vă pot mântui de rău, nici nu-l pot depărta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Cei pe care îi cheamă ei[23] caută și ei mijlocul [care să-i conducă] cât mai aproape de Domnul lor, nădăjduiesc în Îndurarea Sa și se tem de Pedeapsa Lui. Și Pedeapsa Domnului tău este, cu adevărat, de temut.', '[23] Dintre creațiile supuse ale lui Allah precum Îngeri, Profeți, învățații morți etc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'Și nu este o cetate pe care Noi să nu o distrugem[24] înainte de Ziua Învierii sau pe care să nu o chinuim cu chin aspru. Și acest lucru este scris în Carte[25] [cea eternă].', '[24] Din cauza păcatelor locuitorilor săi
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'Și nu Ne împiedică să trimitem semnele [miracolele] decât numai faptul că înaintașii le-au ținut de minciună. Și i-am dat [neamului] Thamud cămila, care a fost [un semn] vizibil, însă ei s-au purtat nedrept cu ea. Și Noi nu trimitem semne decât ca o avertizare pentru ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'Și [adu-ți aminte, o, Mohammed] când Noi ți-am spus: „Cu adevărat, Domnul tău i-a cuprins pe toți oamenii[26]”. Și nu am orânduit Noi vedenia ce ți-am arătat-o[27] decât ca o încercare pentru omenire, ca și pomul cel blestemat [menționat] în Coran. Noi îi umplem de spaimă, însă aceasta nu face decât să le sporească marea lor nelegiuire.', '[26] Cu Puterea și Știința Sa, însemnând că Allah îl va proteja
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'Și [spune] când Noi le-am spus Îngerilor: „Prosternați-vă înaintea lui Adam” și s-au prosternat ei, în afară de Iblis[28], care a spus: „Să mă prosternez eu dinaintea celui pe care L-ai creat din lut?”', '[28] A se vedea 2:34');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, '[Iblis] a mai spus: „Îl vezi pe cel pe care l-ai cinstit mai mult decât pe mine? Dacă Tu îmi vei da răgaz până în Ziua Învierii, îi voi distruge[29] pe urmașii lui, în afară de puțini [dintre ei]”.', '[29] Prin ispitirea lor pe o cale greșită');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, '[Allah] a spus: „Pleacă! Și cine te va urma pe tine dintre ei, Iadul va fi răsplata voastră - o bogată răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'Tulbură-i cu glasul tău pe cei care poți dintre ei și adu-i împotriva lor pe călăreții tăi și pe pedestrașii tăi! Fă-te părtaș cu ei la bunurile lor și la copiii lor și fă-le lor făgăduințe!” Însă nu făgăduiește Șeitan decât numai ca să amăgească!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, 'Cu adevărat, asupra robilor Mei [credincioși] tu nu vei avea putere. Și Domnul tău este de ajuns ca Ocrotitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Domnul vostru este Cel care vă mână corăbiile pe mare, pentru ca voi să căutați ceva din Harul Lui. Cu adevărat, El este Rahim [Îndurător] cu voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Și când răul vă va ajunge pe mare, rătăcesc departe cei pe care voi îi chemați, în afară de El. Dar după ce El vă mântuiește, aducându-vă pe uscat, voi vă întoarceți [de la El], căci omul este nerecunoscător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Sunteți voi siguri că El nu va face să se scufunde cu voi o bucată de uscat sau că El nu va trimite împotriva voastră vijelie cu pietriș și că voi nu veți mai găsi apoi niciun ocrotitor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Sau sunteți voi siguri că El nu vă va întoarce [pe mare] altă dată și nu va trimite asupra voastră vânt pustiitor și nu vă va îneca, din cauza negării[30] voastre? Și atunci nu veți mai afla voi pe nimeni, ca ajutor împotriva Noastră.', '[30] Sau din cauza necredinței voastre');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Noi i-am cinstit pe fiii lui Adam și i-am purtat pe ei pe uscat și pe mare și le-am dat lor ca hrană felurite bunătăți și i-am ales pe ei înaintea multor altora dintre cei pe care i-am creat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, '[Spune, o, Mohammed] de Ziua în care vom chema fiecare grup de oameni împreună cu înscrierile[31] lor, aceia cărora li s-a dat cartea în mâna dreaptă, aceia vor citi cartea lor și nu vor fi nedreptățiți nici cât un firicel.', '[31] Alte înțelesuri sunt „cu liderul lor” sau cu „ceea ce ei au urmat”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'Iar cel care în această [lume] este orb, va fi orb și în Lumea de Apoi și va fi și mai rătăcit de la drum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'Și cu adevărat, ei au fost aproape să te abată de la ceea ce Noi ți-am revelat, pentru ca tu să plăsmuiești împotriva Noastră altceva și atunci te-ar fi primit ei ca prieten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'Și dacă Noi nu te-am fi ținut tare, erai aproape să te apleci puțin către ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'Atunci [dacă ai fi făcut-o] Noi te-am fi făcut să guști îndoit [suferința] vieții și îndoit [suferința] morții și apoi tu n-ai mai fi găsit ajutor împotriva Noastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'Și, cu adevărat, ei au fost aproape să te provoace pe tine ca să te alunge din țară [Mecca]. Dar atunci n-ar mai fi rămas ei în urma ta decât puțin[32].', '[32] La doar 10 ani după emigrarea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa), Mecca a fost complet eliberată de dușmanii săi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, '[Aceasta a fost] rânduiala cu aceia pe care i-am trimis înaintea ta dintre Trimișii Noștri și nu vei afla nicio schimbare în rânduiala Noastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Împlinește Rugăciunea [As-Salat] de la înclinarea Soarelui până la întunericul nopții[33] și [citirea] Coranului din zori[34], căci citirea din zori are martori.', '[33] Perioada ce include Rugăciunile Dhuhr, Asr, Maghrib și Ișa
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'Iar în timpul nopții stai de veghe și împlinește rugăciuni peste cele cuvenite; deoarece Domnul tău te va readuce la viață într-o poziție demnă de laudă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'Și spune: „Doamne, fă-mă să intru printr-o intrare a Adevărului[35] și scoate-mă pe mine printr-o ieșire a Adevărului[36] și dă-mi de la Tine Putere ajutătoare.”', '[35] În Medina la timpul emigrării sau în mormânt
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'Și spune: „A venit Adevărul și a pierit deșertăciunea. Cu adevărat, deșertăciunea este sortită să piară.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Noi pogorâm prin Coran ceea ce este Tămăduire și Îndurare pentru dreptcredincioși și nu face decât să sporească pierderea celor nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'Când Noi Ne revărsăm binefacerea asupra omului [necredinciosului], el se întoarce și se duce departe, iar atunci când îl ajunge un rău, el este deznădăjduit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'Spune: „Fiecare purcede după orânduiala lui, însă Domnul vostru știe mai bine cine este mai bine călăuzit pe drum.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Te întreabă [o, Mohammed] despre Duh [suflet]. Spune: „Sufletul este din porunca Domnului meu!” Iar vouă [oamenilor] nu v-a fost dată decât puțină știință.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'Și de am Voi Noi, am face să dispară ceea ce ți-am revelat, iar tu nu ai mai găsi niciun sprijinitor împotriva Noastră,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'În afară de Îndurarea de la Domnul tău. Cu adevărat, Harul Său asupra ta este mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'Spune: „De s-ar aduna oamenii și djinnii ca să facă [ceva] ca acest Coran, ei nu vor fi în stare să facă [ceva] asemenea lui, chiar dacă își vor fi unul altuia ajutor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Noi am tâlcuit pentru oameni în acest Coran din fiecare pildă, însă cei mai mulți oameni au respins [totul], în afară de necredință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'Și ei spun: „Noi nu-ți vom crede ție până ce vei face să țâșnească pentru noi un izvor din pământ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'Sau [până] vei avea o grădină de curmali și viță de vie și vei face să țâșnească printre ele pâraie îmbelșugate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'Sau vei face să cadă peste noi Cerul în bucăți - așa cum ai pretins - sau Îl vei aduce pe Allah și pe Îngeri în fața noastră,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'Sau vei avea tu o casă împodobită [cu aur] sau vei sui în Cer. Și [chiar și atunci] nu vom crede în ascensiunea ta în Cer până ce nu vei pogorî asupra noastră o Carte pe care noi să o putem citi!” Spune: „Mărire Domnului meu! Oare sunt eu mai mult decât un om trimis?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'Și nu-i împiedică pe oameni să creadă, când le vine lor călăuzirea, decât că ei spun: „Allah a trimis un om ca sol?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, 'Spune: „Dacă ar fi pe pământ Îngeri care să umble în pace și liniște[37], atunci le-am pogorî lor din Cer un Înger ca trimis”.', '[37] Stabiliți acolo, așa cum este omul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, 'Spune: „Allah este de ajuns ca Martor între mine și voi. Cu adevărat, El este Khabir [Bine Știutor] [și este] Basir [Cel care îi Vede Bine pe robii Săi].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Și cel pe care-l călăuzește Allah este [cu adevărat] cel bine călăuzit, iar celor pe care El îi duce în rătăcire nu le vei găsi ocrotitori afară de El. Și Noi îi vom aduna în Ziua Învierii târâți pe fețele lor - orbi, muți, surzi. Adăpostul lor va fi Focul Iadului și ori de câte ori va scădea [focul], Noi îl vom aprinde cu flacără.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'Aceasta va fi răsplata lor pentru că nu au crezut în semnele Noastre și au spus: „Oare după ce vom fi oase și resturi vom mai putea fi înviați din nou?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Nu văd ei că Allah care a creat Cerurile și Pământul poate să creeze asemenea lor? El a orânduit pentru ei un termen asupra căruia nu este îndoială, însă nelegiuiții resping [totul] afară de necredință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'Spune-le: „Dacă voi ați avea vistieriile Îndurării Domnului meu, voi le-ați păstra de frică să nu le cheltuiți”, căci omul este zgârcit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'I-am dat Noi lui Moise nouă semne limpezi. Întreabă-i pe Fiii lui Israel, [atunci] când a venit [Moise] la ei și Faraon i-a zis: „Cu adevărat, eu cred, o, Moise, că tu ești vrăjit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, '[Moise] a spus: „Tu știi că nu le-a trimis pe acestea decât Stăpânul Cerurilor și al Pământului, ca semne limpezi și eu te cred, o, Faraon, pierdut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Și a voit el să-i alunge de pe pământ, însă atunci l-am înecat împreună cu toți cei care erau cu el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'Și după el [Faraon], am spus Noi Fiilor lui Israel: „Locuiți pe acest pământ. Dar când va veni promisiunea [Vieții] de Apoi, vă vom aduna Noi în [o singură] adunare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Cu adevăr l-am pogorât pe el [Coranul] și cu adevăr el a coborât, iar pe tine nu te-am trimis [o, Mohammed] decât ca vestitor și prevenitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, '[Noi l-am făcut] un Coran pe care l-am împărțit [în intervale de timp] pentru ca tu să-l citești oamenilor pe o perioadă îndelungată. Și l-am pogorât Noi rând pe rând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'Spune: „De credeți voi în el ori nu credeți”. Cu adevărat, cei cărora li s-a dat știința înaintea lui[38] - dacă li se recită lor - cad, prosternându-se, cu fețele la pământ.', '[38] Cei dreptcredincioși dintre Oamenii Cărții care recunosc adevărul din Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'Și ei spun: „Mărire Domnului nostru! Cu adevărat, făgăduința Domnului nostru este împlinită”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'Și ei cad cu fețele la pământ, plângând, și acesta [Coranul] le sporește lor smerenia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'Spune: „Chemați-L Allah sau chemați-L Milostivul și oricum L-ați chema, ale Lui sunt Numele cele mai frumoase.” Și nu rosti cu glas [prea] tare Rugăciunea ta, dar nici nu o rosti în șoaptă, ci caută între acestea [două] o cale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, 'Și spune: „Laudă lui Allah, Care nu Și-a luat niciodată un fiu, Care nu are părtaș la Stăpânire și nici nu are nevoie să fie apărat de vreo slăbiciune. Și slăvește-L pe El, aducându-I preamărirea cuvenită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, '[Toată] Lauda [I se cuvinte] lui Allah care i-a pogorât robului Său [Mohammed] Cartea și nu a lăsat în ea nicio deviere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, '[O Carte] dreaptă, ca să prevină despre o pedeapsă grea din partea Lui și să binevestească dreptcredincioșilor care împlinesc fapte bune că ei vor avea răsplată frumoasă [Paradisul]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'În care vor rămâne veșnic,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'Și pentru ca să-i prevină pe cei care au spus: „Allah Și-a luat un fiu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'Nici ei și nici părinții lor nu au avut despre aceasta cunoștință[1]. Ce cuvânt greu iese din gurile lor. Ei nu spun alta decât minciună.', '[1] Nu ar fi putut știi despre ceva ce nu este adevărat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Poate că tu [Mohammed] te vei tulbura de moarte, din pricina întristării, pentru că ei nu cred în acest Mesaj.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Noi am făcut ceea ce se află pe pământ podoabă pentru el, pentru a-i încerca [pe oameni și a ști] care dintre ei săvârșesc cele mai bune fapte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'Și, cu adevărat, Noi vom preschimba ceea ce se află pe el într-o țărână stearpă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Oare crezi tu că oamenii din Peșteră și Ar-Raqim au fost dintre semnele Noastre cele mai minunate?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, '[Spune] când s-au adăpostit în peșteră, tinerii au spus astfel: „Doamne, dă-ne nouă Îndurare de la Tine și orânduiește-ne nouă lucrurile noastre așa cum este drept.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'Și am tras Noi peste urechile lor [un văl de somn], în Peșteră, pentru vreme de mulți ani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'Apoi i-am trezit Noi, pentru a face cunoscut care din cele două cete au socotit cât timp au rămas ei acolo.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Noi îți povestim ție [o, Mohammed] istoria lor cu adevărat. Cu adevărat, ei au fost niște tineri care au crezut în Domnul lor, iar Noi le-am sporit buna lor Călăuzire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Le-am întărit Noi, așadar inimile, când ei s-au ridicat și au spus: „Domnul nostru este Stăpânul Cerurilor și a Pământului. Noi nu vom chema niciodată un alt Dumnezeu în afară de El, căci, dacă am face aceasta, noi am rosti o nelegiuire.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, 'Aceștia sunt neamul nostru care au luat alți dumnezei în locul Lui! De ce nu au adus ei dovadă limpede asupra lor? Și cine este mai nelegiuit decât cel care plăsmuiește minciună despre Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, '[Tinerii și-au spus unul altuia:] „Iar când vă depărtați voi de la ei și de cei pe care ei îi adoră, în afară de Allah, adăpostiți-vă în peșteră! Domnul vostru va întinde Mila Sa asupra voastră și vă va orândui lucrurile voastre în liniște și tihnă."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'Și [dacă ai fi fost prezent] puteai vedea Soarele, când răsărea, cum se îndepărta de la peștera lor către dreapta, iar când apunea, trecea departe la stânga lor, în vreme ce ei stăteau într-un loc întins din ea. Aceasta este una din Minunile lui Allah. Cel pe care îl călăuzește Allah este bine călăuzit, iar celui pe care El îl duce în rătăcire tu nu-i vei găsi niciun ocrotitor călăuzitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'Ai fi crezut că sunt treji, în vreme ce ei dormeau și Noi îi întorceam pe partea dreaptă și pe partea stângă, iar câinele lor stătea cu labele întinse la intrare. Dacă i-ai fi văzut, te-ai fi întors și ai fi luat-o la fugă, plin de spaimă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'Tot astfel i-am trezit Noi, ca să se întrebe laolaltă. Și a întrebat unul dintre ei: „Cât timp ați petrecut [aici]?” Și au răspuns ei: „Am petrecut o zi sau mai puțin de o zi!” [Alții] au spus: „Domnul vostru Știe mai bine cât timp ați petrecut. Trimiteți-l pe unul dintre voi cu bănuții ăștia [de argint] ai voștri în oraș, ca să vadă care este cea mai curată mâncare și să vă aducă ceva hrană de ei. Dar el să fie prudent și să nu dea nimănui de înțeles despre voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'Cu adevărat ei, dacă vor afla de voi, vă vor ucide cu pietre sau vă vor aduce înapoi la religia lor și nu veți mai izbândi, atunci niciodată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'Și astfel am lăsat Noi să fie descoperiți, pentru ca ei să știe că făgăduința lui Allah este adevăr și că nu este nicio îndoială asupra Ceasului. Și când se certau ei[2] în privința întâmplării lor, au spus [unii]: „Înălțați peste ei o zidire! Domnul lor Știe mai bine ce-i cu ei.” Dar cei care au ieșit biruitori în această pricină au spus: „Să zidim deasupra lor un loc de rugăciune.”', '[2] Oamenii cetății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'Ei [oamenii] vor spune că ei au fost trei, iar al patrulea era câinele lor”. [Iar alții] vor spune: „[Au fost ei] cinci, iar al șaselea era câinele lor", făcând presupuneri. Și vor zice [alții]: [Au fost] șapte și al optulea era câinele lor”. Spune: „Domnul meu Știe mai bine numărul lor și nu sunt decât puțini cei care îi cunosc pe ei și nu discuta asupra [numărului] lor, decât numai dacă ești sigur și nu întreba pe nimeni dintre ei despre ei [despre adormiți]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'Și nu spune [niciodată] în privința unui lucru: „Cu adevărat, eu voi face asta mâine”,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, 'Decât [adăugând]: „Dacă Voiește Allah.” Și pomenește-L pe Domnul tău, dacă uiți și spune: „Poate mă va călăuzi Domnul meu către o dovadă mai puternică decât aceasta, [pentru profeția mea]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'Au rămas ei în peștera lor trei sute de ani și încă nouă[3].', '[3] Conform calendarului lunar');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'Spune: „Allah Știe mai bine cât au rămas ei acolo. Ale Lui sunt cele neștiute din Ceruri și de pe Pământ! Cât de bine Vede El și cât de bine Aude El [totul]. Ei nu au niciun ocrotitor afară de El și El nu are niciun asociat în Legiuirea Lui!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'Și recită [o, Mohammed] ceea ce ți-a fost revelat din Cartea Domnului tău. Nimeni nu poate schimba Cuvintele Sale și tu nu vei afla în afară de El adăpost.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Și fii răbdător împreună cu cei care-L cheamă pe Domnul lor dimineața și seara, dorind Fața Sa. Și nu întoarce ochii tăi [pentru alții] de la ei, râvnind la podoaba vieții din această lume și nu te supune aceluia căruia i-am făcut inima nepăsătoare față de Pomenirea Noastră, care urmează poftei sale și ale cărui fapte sunt în deșert[4].', '[4] Sau „în exces”, trecând peste limitele lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'Spune: „Adevărul vine de la Domnul vostru, iar cine voiește să creadă și cine voiește să nu creadă.” Cu adevărat, Noi am pregătit pentru nelegiuiți un Foc ale cărui [flăcări] îi înconjoară din toate părțile, iar atunci când vor cere ei ajutor, li se va veni lor în ajutor cu o apă ca fierul topit, ce le va arde fețele. Cumplită băutură și cumplit sălaș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'Cu adevărat, cei care cred și împlinesc fapte bune, [să știe că] Noi nu lăsăm să se piardă răsplata celui care săvârșește fapte bune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'Aceia vor avea parte de grădinile pentru sălaș [Eden], pe sub care trec pâraie. Se vor împodobi în ele cu brățări de aur și vor îmbrăca straie verzi din mătase și brocart, rezemându-se [îmbrăcați] în ele pe divane. Minunată este răsplata și minunat este sălașul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'Spune-le lor exemplul a doi bărbați: Noi i-am dat unuia dintre ei două grădini cu viță de vie, pe care le-am împrejmuit cu palmieri de curmale, iar între ele am făcut ogoare verzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Amândouă grădinile au dat roadele lor și nu i-a lipsit lui nimic. Și Noi am făcut să curgă prin mijlocul lor un pârâu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'Și a avut el și alte roade și i-a zis semenului său, când stătea de vorbă cu el: „Eu am mai multă avere decât tine și sunt mai puternic, [căci am] mai mulți sprijinitori.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'A intrat în grădina lui, păcătuind față de sine însuși [prin necredința sa] și a spus: „Nu cred că aceasta va pieri vreodată [5]-', '[5] Mândru și nerecunoscător lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'Și nu cred că Ceasul va veni. Iar de voi fi adus la Domnul meu, voi găsi [loc] și mai bun decât ea, în schimb.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'Și i-a zis semenul său, stând de vorbă cu el: „Nu crezi tu în Cel care te-a creat pe tine din țărână, apoi dintr-o picătură și la urmă ți-a dat ție chip de bărbat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'În ce mă privește, Allah este Domnul meu și nu-I fac Domnului meu pe nimeni asociat”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'Și de ce când ai intrat în grădina ta n-ai spus: „Ce Voiește Allah [se împlinește]! Nu este Putere decât numai la Allah!” Iar dacă mă vezi pe mine cu mai puțină avere și cu mai puțini copii decât tine,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'S-ar putea întâmpla ca Domnul meu să-mi dea ceva mai bun decât grădina ta și să trimită asupra ei nenorocire din Cer, încât să devină un pământ lunecos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'Sau apa ei să se ducă așa de adânc, încât n-o s-o mai poți scoate.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'Și roadele lui au fost înconjurate [de distrugere], iar el a rămas frângându-și mâinile [cu mâhnire] pentru ceea ce cheltuise pentru ea și [via] era distrusă cu totul pe proptelele ei. Și atunci a zis el: „Ce bine ar fi fost dacă eu nu-I făceam Domnului meu niciun asociat.”[6]', '[6] Și-a atribuit prosperitatea lui însuși și nu lui Allah și nu a crezut în Judecata Vieții de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'Și n-a avut el nicio ceată care să-l ajute împotriva [pedepsei] lui Allah și nici el însuși nu și-a putut fi de niciun ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'Acolo ocrotirea vine numai de la Allah, [Ocrotitorul] Adevărat. El dă cea mai bună răsplată și urmarea cea mai bună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Și dă-le lor exemplul vieții lumești. Ea este asemenea apei pe care Noi o trimitem din Cer și se amestecă plantele pământului cu ea, apoi se transformă ele în fân uscat pe care-l împrăștie vântul. Iar Allah este cu Putere asupra tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Averea și copiii sunt podoaba vieții celei lumești, însă [lucrurile] care rămân sunt faptele bune ce vor avea răsplată mai bună la Domnul tău și mai dătătoare de nădejde vor fi ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'Și [avertizează] de o Zi când Noi vom face să plece munții din loc și vei vedea Pământul neted[7] și-i vom aduna pe toți, fără să lăsăm pe niciunul dintre ei.', '[7] Neted și expus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'Și ei vor fi așezați dinaintea Domnului tău în rând [și El va spune]: „Iată că ați venit la Noi precum v-am creat pe voi dintru întâi, cu toate că ați pretins că Noi nu vom împlini Făgăduința Noastră.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'Și cartea [fiecăruia] va fi pusă dinaintea [lui cu faptele sale] și îi vei vedea pe păcătoși înfricoșați de ceea ce se află în ea. Și vor grăi ei: „Vai nouă! Ce-i cu această carte care nu a lăsat nimic nepomenit, nici cel mai mic, nici cel mai mare păcat?” Și ei vor afla dinaintea lor tot ceea ce au săvârșit și nu-l va nedreptăți Domnul tău pe niciunul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'Și [spune] când Noi le-am spus Îngerilor: „Prosternați-vă dinaintea lui Adam” și s-au prosternat ei, afară de Iblis care era dintre djinni și nu s-a supus Poruncii Domnului său. Îi luați voi pe el și pe urmașii lui drept ocrotitori în locul Meu, când ei vă sunt vouă dușmani? Acesta este rău schimb pentru nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Eu nu i-am luat ca martori la crearea Cerurilor și a Pământului și nici la crearea lor înșiși, căci Eu nu i-am luat pe cei care amăgesc spre rătăcire ca susținători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'Și [avertizează] de o Zi când El va spune: „Chemați-i voi pe aceia care ați pretins că sunt asociații Mei.” Și-i vor chema, însă ei nu le vor răspunde și Noi vom pune între ei un loc de pierzare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'Nelegiuiții vor vedea focul și vor ști că vor intra în el, dar nu vor afla scăpare de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'Noi tâlcuim în acest Coran tot felul de pilde pentru oameni, însă omul este cel mai certăreț [dintre toate ființele].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'Și nu îi împiedică pe oameni să creadă, după ce le-a venit călăuzirea, și să ceară iertare Domnului lor, decât că ei vor trebui să afle soarta înaintașilor[8] sau să se afle față în față cu chinul.', '[8] Care au negat Adevărul adus de Mesagerii lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Iar Noi nu trimitem Profeți decât ca vestitori de bine și ca prevenitori, însă cei care nu cred, se ceartă, [venind cu temeiuri deșarte, încercând] să tăgăduiască Adevărul și iau în derâdere Versetele Mele și cele cu care au fost preveniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'Și cine este mai nelegiuit decât acela căruia i s-au vestit Versetele Domnului său, însă el le întoarce spatele și uită ce au săvârșit mâinile lui mai înainte? Noi am pus peste inimile lor acoperăminte, ca să nu-l înțeleagă și în urechile lor o greutate. Chiar dacă tu îi vei chema spre calea cea bună, ei nu vor putea - așadar - să fie niciodată bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Domnul tău este Al-Ghafur [Iertător] și Dătător de Îndurare. Dacă ar voi El să-i piardă pentru ceea ce ei au agonisit, le-ar grăbi lor osânda, însă ei au un soroc și nu vor afla adăpost de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, 'Și am nimicit Noi acele cetăți [9] pentru că [popoarele lor] au săvârșit nelegiuiri și am rânduit Noi un timp pentru nimicirea lor.', '[9] Ale popoarelor Ad, Thamud și celelalte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, '[Adu-ți aminte] când Moise i-a zis slujitorului său: „Nu mă voi opri până ce nu vom ajunge la întâlnirea celor două mări, chiar dacă voi umbla ani îndelungați.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'Și când au ajuns ei la întâlnirea lor, au uitat peștele lor și el a apucat nestingherit drumul lui către mare, ca printr-un canal.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'Și când au trecut ei [de locul acela], i-a zis slujitorului său: „Adu-ne mâncarea, căci ne-a ajuns oboseala din pricina călătoriei noastre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, 'El i-a răspuns: „Vezi tu, când ne-am adăpostit lângă stâncă? Eu am uitat peștele. Și nu m-a făcut să uit și să nu-ți mai pomenesc de el decât numai Șeitan, iar el a apucat drumul spre mare, într-un mod ciudat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, '[Moise] a spus: „Acesta este ceea ce căutăm noi.” Și s-au întors după urmele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'Și au găsit ei un rob dintre robii Noștri [al-Khidr], căruia Noi i-am dăruit Îndurare, din partea Noastră, și l-am învățat Știință de la Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, 'Moise i-a spus: „Pot eu să te urmez, astfel încât să mă înveți din ceea ce tu ai învățat, ca bună călăuzire?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, 'I-a răspuns: „Cu adevărat, tu nu vei putea să ai răbdare cu mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, 'Cum ai putea tu să rabzi ceea ce nu cuprinzi tu cu știința?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, '[Moise] a spus: „Dacă Allah Voiește, mă vei afla tu răbdător și nu mă voi împotrivi nici uneia dintre poruncile tale.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, 'El a spus: „Dacă mă urmezi, nu mă întreba despre niciun lucru, câtă vreme nu-ți pomenesc [nu îți explic] nimic despre el .”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'Și au purces la drum amândoi. Dar când au urcat pe o corabie, el [al-Khidr] a găurit-o și Moise i-a spus: „Ai găurit-o pentru ca să-i îneci pe oamenii de pe ea? Tu ai săvârșit un lucru foarte rău.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, '[Al-Khidr] a spus: „Nu am spus eu că tu nu vei putea răbda împreună cu mine?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, '[Moise] a spus: „Nu mă învinovăți pentru ceea ce am uitat și nu mă împovăra cu prea mare greutate pentru treaba [asta a] mea.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'Și au pornit ei doi mai departe și au mers până ce s-au întâlnit cu un băiat, pe care el [al-Khidr] l-a ucis. I-a spus atunci [Moise]: „Ai ucis un suflet nevinovat, ce nu a luat niciun suflet! Ai săvârșit un lucru îngrozitor."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, '[Al-Khidr] a spus: „Nu ți-am spus eu că nu vei avea răbdare cu mine?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, '[Moise] a spus: „De te voi mai întreba despre ceva după aceasta, să nu mă mai ții în tovărășia ta! Acum ai dobândit de la mine îngăduința [de a te despărți de mine]."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'Și au pornit mai departe până ce au ajuns la oamenii unei cetăți, de la care au cerut mâncare, însă aceștia nu au dorit să-i ospăteze. Și au găsit în ea un perete ce stătea să se prăbușească, iar el [al-Khidr] l-a îndreptat. Și [atunci] i-a zis [Moise]: „Dacă ai fi voit, ai fi obținut o plată pentru aceasta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, '[Al-Khidr] a spus: „Aceasta este despărțirea între mine și între tine. Însă eu îți voi vesti tâlcuirea celor pentru care tu nu ai avut răbdare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'În ceea ce privește corabia, ea era a unor sărmani care lucrau pe mare și eu am voit să o stric, pentru că venea din urma lor un rege care lua toate corăbiile, cu forța.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Cât despre fecior, părinții lui erau dreptcredincioși și ne-a fost teamă ca el să nu le impună lor nelegiuirea și necredința.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'Și am voit ca Domnul lor să le dea în schimb un altul mai curat decât el și mai iubitor [față de ei].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'În ceea ce privește peretele, el aparținea la doi copii orfani din acest oraș, iar sub el se afla o comoară pentru ei, iar tatăl lor a fost un om cuvios. Și Domnul tău a Voit ca atunci când ei vor ajunge la vârsta bărbăției să-și scoată comoara lor [ei înșiși], ca Milă de la Domnul tău. Și nu am făcut-o după socotința mea. Aceasta este tâlcuirea celor pentru care nu ai putut să fii cu răbdare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'Ei te întreabă [o, Mohammed] despre Dhu-l-Qarnayn. Spune: „Vă voi pomeni vouă ceva despre el.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'Cu adevărat, Noi am întărit puterea lui pe Pământ și i-am dat lui căile și mijloacele pentru toate lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'Și a urmat el astfel o cale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'Până când a ajuns la locul unde apune Soarele [la Vest], l-a găsit [ca și cum] ar apune într-un izvor noroios și a găsit lângă el un popor. Și Noi i-am zis: „O, Dhu-l-Qarnayn! Fie îi pedepsești, fie te vei arăta binevoitor față de ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, 'El a răspuns: „Cât despre cel care este nelegiuit, pe acela îl vom pedepsi. Apoi el se va întoarce la Domnul său și El o să-l pedepsească asemenea cu un chin aspru [Focul Iadului].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'Însă cel care crede și săvârșește bine va avea parte de cea mai frumoasă răsplată [Paradisul] și noi [Dhu-l-Qarnayn] lui îi vom da porunci ușoare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'Apoi el a purces pe o [altă] cale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'Până când a ajuns la locul unde răsare Soarele [la est], a aflat că el răsare peste un popor [de oameni] căruia Noi nu le-am dat niciun scut [cu care să se apere] de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, 'Așa a fost[10], iar Noi am cuprins cu Știința Noastră tot ceea ce ținea de el.', '[10] Chestiunea cu Dhul-Qarnayn');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'Apoi el a urmat [o altă] cale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'Până când a ajuns între cei doi munți, a găsit dincolo de ei un popor care cu greu înțelegeau vorba sa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, 'Și au spus ei: „O, Dhu-l-Qarnayn, cu adevărat Yagog și Magog[11] fac stricăciune pe Pământ. Putem noi să-ți dăm ție un tribut pentru ca tu să ridici o stavilă între noi și între ei?”', '[11] Triburi sălbatice care au distrus părți mari din Asia centrală, făcând tot felul de atrocități');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, 'El a spus: „Cele cu care m-a înzestrat Domnul meu sunt mai bune [decât tributul vostru]! Așadar, ajutați-mă cu puterea [voastră] și eu voi înălța o stavilă între voi și între ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Aduceți-mi bucăți de fier” - până când a umplut deschizătura dintre cei doi munți, a spus: „Suflați! [cu burduful]” Apoi, când s-a făcut văpaie, a zis: „Aduceți-mi să torn peste el aramă topită.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, 'Astfel n-au mai putut ei [Yagog și Magog] să se cațăre pe el, nici n-au mai putut să-l străpungă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, '[Dhu-l-Qarnayn] a spus: „Aceasta este Îndurare de la Domnul meu. Însă când va veni Făgăduința Domnului meu[12], îl va face pe el una cu Pământul, iar Făgăduința Domnului meu este Adevărată.”', '[12] Ora Învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'Și în Ziua[13] aceea, îi vom lăsa să se ridice ca valurile unii peste alții și se va sufla în Trâmbiță și-i vom aduna pe toți.', '[13] Ziua în care barajul va fi distrus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'Și în Ziua aceea le vom înfățișa Noi Iadul de aproape necredincioșilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, 'Ai căror ochi au fost acoperiți cu un văl care-i împiedica să-și amintească de Mine și care nu puteau nici auzi[14].', '[14] Au refuzat să asculte Coranul sau să îl înțeleagă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Oare își închipuie cei care nu cred că-i vor putea lua pe robii Mei ca ocrotitori în locul Meu? Noi am pregătit Iadul ca sălaș pentru necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, 'Spune [o, Mohammed]: „Voiți să vă Vestim Noi cine sunt cei care vor avea cel mai mult de pierdut din faptele lor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Cei a căror râvnă în această lume este rătăcită, în vreme ce ei își închipuie că fac bine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'Aceia sunt cei care nu au crezut în Versetele Domnului lor și în întâlnirea cu El, iar faptele lor au fost în deșert. Și nu le vom da lor în Ziua Învierii nicio greutate [importanță].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Astfel, răsplata acestora va fi Iadul, pentru că nu au crezut și au luat semnele Mele și pe Trimișii Mei în derâdere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'Însă aceia care cred și împlinesc fapte bune vor avea ca sălaș grădinile Firdausului[15]', '[15] Cel mai înalt nivel al Paradisului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'Și în veci vor petrece în ele și nu vor dori nicio schimbare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'Spune: „Dacă marea ar fi cerneală pentru [scrierea] Cuvintelor Domnului meu, marea s-ar isprăvi înainte de a se isprăvi Cuvintele Domnului meu, chiar dacă i-am aduce spre ajutor o [altă mare] asemenea ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'Spune: „Ci eu sunt doar un om, ca și voi! Și mi s-a revelat mie că Domnul vostru este un Domn Unic! Acela care nădăjduiește să-L întâlnească pe Domnul său să săvârșească fapte bune și să nu asocieze pe nimeni altcineva la adorarea Domnului său.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Kaf, Ha'', Ya'' Ayn, Sad[1]', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, '[Aceasta este] o pomenire despre Îndurarea Domnului tău față de robul Său Zaharia', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'Când el L-a chemat pe Domnul lui într-ascuns,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'Spunând: „Doamne, cu adevărat, oasele mele sunt slabe și capul mi s-a aprins de căruntețe, dar nicicând eu nu am fost nefericit rugându-mă Ție, Doamne,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, 'Și cu adevărat, eu mă tem de urmașii[2] mei de după mine, căci soția mea este stearpă, deci dăruiește-mi mie un urmaș de la Tine,', '[2] Acei urmași din partea tatălui care i-ar moșteni autoritatea religioasă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, 'Care să mă moștenească pe mine și să moștenească și neamul lui Iacob. Și fă-l să-Ți fie plăcut Ție, Doamne!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, '[I s-a spus][3] „O, Zaharia, Noi îți aducem buna vestire a unui prunc, al cărui nume fi-va Ioan, așa cum Noi nu am numit pe nimeni mai înainte de el.”', '[3] De către Allah prin Îngeri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, 'El a spus: „Doamne, cum să am eu un prunc, când soția mea este stearpă, iar pe mine bătrânețea mult m-a prea ajuns?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, '[Îngerul] a spus: „Așa va fi! Așa spune Domnul tău: „Aceasta va fi neînsemnată faptă, după ce te-am creat pe tine, înainte de aceasta, fără ca tu să fi fost nimic!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, '[Zaharia] a spus: „Doamne, dă-mi mie un semn!” Și i-a răspuns: „Semnul tău este că nu vei [putea] vorbi cu niciun om vreme de trei nopți, măcar că tu ești [om] întreg.”[4]', '[4] Sănătos fizic și psihic');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'Și a ieșit el de la locul de rugăciune înaintea poporului său și le-a făcut lor semn să aducă laude [lui Allah] dimineața și seara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, '[Allah a spus]: „O, Ioan, primește [urmează-o] Scriptura întru putere.” Și i-am dăruit Noi înțelepciune, pe când el era încă un copil,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'Și Îndurare din partea Noastră și puritate și el avea frică de Allah', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'Și era iubitor față de părinții lui; și nu era el semeț sau nesupus [lui Allah sau părinților lui]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Și pacea fi-va asupra lui în ziua când se va fi născut el, ca și în ziua când se va sfârși și în ziua când va fi readus în viață.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'Și pomenește [O, Mohammed] în Carte [Coranul] și de Maria, când ea s-a retras de la neamul ei într-un loc spre răsărit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'Și a pus între ea și între ei un văl. Și atunci am trimis la ea Duhul Nostru[5], care i s-a arătat cu înfățișarea unui om adevărat.', '[5] Îngerul Gavriil');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, 'Ea a spus: „Caut apărare la Cel Milostiv față de tine! Dacă ai teamă de Allah [nu te apropia de mine].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, 'El i-a răspuns: „Eu sunt numai un Trimis al Domnului tău ca să-ți vestesc un prunc curat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, 'Însă ea a spus: „Cum să am eu un prunc, dacă nu m-a atins niciun bărbat și eu nu sunt nici desfrânată [Baghiyya]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, 'El a spus: „Așa [va fi] spune Domnul tău: „Acesta pentru Mine-i [un lucru] ușor! Și-l vom face Noi un semn pentru oameni și o îndurare din partea Noastră! Acesta-i un lucru [de mult] hotărât.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'Și ea l-a purtat [în pântece] și s-a retras cu el într-un loc depărtat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'Și durerile nașterii au dus-o lângă trunchiul unui curmal și a zis: „O, de aș fi murit înainte de aceasta și cu totul de-aș fi fost uitată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'Dar [un glas] a strigat-o de sub ea, [spunându-i]: „Nu fi mâhnită! Domnul tău a făcut mai jos de tine un pârâiaș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, 'Și scutură spre tine trunchiul de curmal, căci vor fi lăsate să cadă lângă tine curmale proaspete coapte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'Așadar, mănâncă, bea și fii fericită [de copilul tău]. Iar de vei vedea vreun om, spune-i: „Cu adevărat, eu i-am jurat Celui Milostiv un post și de aceea nu voi sta astăzi de vorbă cu niciun om.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'Apoi ea l-a adus la poporul ei, purtându-l [în brațe]. Și ei i-au spus: „O, Maria, tu ai făcut un lucru îngrozitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'O, soră a lui Aaron, tatăl tău nu a fost un om [făcător] de rău, iar mama ta nu a fost o desfrânată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, 'Ea [Maria] a făcut semn spre el, dar ei au spus: „Cum să vorbim cu acela care este un [mic] prunc în leagăn?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, '[Iisus] a spus: „Cu adevărat, eu sunt robul lui Allah! El mi-a dăruit Scriptura și m-a făcut Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'Și El m-a binecuvântat, oriunde aș fi, și mi-a poruncit Rugăciunea [As-Salat] și Dania [Az-Zakat], cât voi trăi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'Și m-a făcut ascultător față de mama mea și nu m-a făcut pe mine trufaș, nici ticălos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'Și pacea fie asupra mea în ziua în care m-am născut și în ziua în care voi muri și în ziua în care voi fi adus la viață [din nou].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, '[Spune, o, Mohammed]: „Acesta este Iisus, fiul Mariei!” Aceasta este povestea adevărată de care ei se îndoiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Nu se cuvine ca Allah să-Și atribuie un fiu. Mărire Lui! Dacă El hotărăște un lucru, atunci El zice „Fii!”, iar el este.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, '[Iisus a spus] Într-adevăr Allah este Domnul meu și Domnul vostru. Adorați-L pe El și acesta este un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'Dar sectele se ceartă între ele și va fi vai pentru cei care nu cred, la vederea unei Zile cumplite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Cât de limpede vor auzi și vor vedea ei în Ziua când vor veni la Noi. Însă nelegiuiții sunt astăzi într-o rătăcire de netăgăduit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'Și avertizează-i [o, Mohammed] despre Ziua căirii când totul va fi hotărât, pentru că ei sunt nepăsători și nu cred!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Cu adevărat, Noi suntem cei care moștenim Pământul și pe toți cei care sunt pe el și la Noi se vor întoarce ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'Și pomenește-l în Carte pe Avraam. Cu adevărat, el a fost un iubitor de adevăr și un Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, '[Spune] când i-a zis el tatălui său: „O, tată! Pentru ce te închini tu la ceea ce nu aude, nu vede și nu-ți este de niciun folos?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, 'O, tată! Mi-a venit mie știința care ție nu ți-a venit! Deci urmează-mă și eu te voi călăuzi pe un drum drept!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'O, tată! Nu te închina la Șeitan, căci Șeitan a fost răzvrătit împotriva Celui Milostiv [Ar-Rahman]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'O, tată! Mă tem să nu te atingă o pedeapsă de la Cel Milostiv și să nu devii un tovarăș al lui Șeitan [în focul Iadului]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, '[Tatăl său] a spus: „O, Avraam! Te lepezi tu de zeii mei? Dacă nu încetezi, eu te voi alunga cu pietre! Îndepărtează-te de mine pentru totdeauna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, '[Avraam] a spus: „Vei avea numai Pace [din partea mea]! Mă voi ruga de iertare la Domnul meu pentru tine, căci El este Binevoitor cu mine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, 'Și eu mă separ de voi, ca și de ceea ce chemați voi în locul lui Allah și-L voi chema pe Domnul meu. Poate că eu nu voi fi nefericit pentru chemarea Domnului meu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Și după ce s-a despărțit de ei și de ceea ce adorau ei în locul lui Allah, Noi i-am dăruit lui pe Isaac și pe Iacob și din fiecare Noi am făcut un Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'Și le-am dăruit Noi din Îndurarea Noastră și i-am făcut Noi să fie lăudați de oameni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'Și pomenește-l în Carte pe Moise. Cu adevărat, el a fost ales și a fost un Mesager și un Profet[6].', '[6] Un Mesager (rasul) este cel însărcinat de Allah cu reformarea societății. Un Profet (Nabi) este cel care a primit revelație de la Allah. Sunt mai mulți Profeți decât Mesageri.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Noi l-am chemat din partea dreaptă a Muntelui Tor[7] și l-am apropiat de Noi ca tainic', '[7] Muntele Sinai');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'Și i l-am dăruit Noi, prin Îndurarea Noastră, pe fratele său Aaron, ca Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'Și pomenește-l în Carte pe Ismail. Cu adevărat, el a fost credincios făgăduinței sale, și a fost el un Mesager și un Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'El a poruncit neamului său Rugăciunea [As-Salat] și Dania [Az-Zakat] și a fost pentru Domnul său un rob plăcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'Și pomenește-l în Carte pe Idris. Cu adevărat, el a fost iubitor de adevăr și Profet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'Și Noi l-am ridicat pe o treaptă înaltă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'Aceștia sunt cei pe care Allah i-a binecuvântat dintre Profeți, din urmașii lui Adam, din cei pe care Noi i-am purtat cu Noe, din urmașii lui Avraam și ai lui Israel și din cei pe care Noi i-am călăuzit și i-am ales. Iar când Versetele Celui Milostiv li se recitau, ei cădeau prosternându-se, plângând', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'Și a venit după ei urmași care s-au lepădat de rugăciune și s-au luat după pofte, iară ei se vor afla în pierdere', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Cu excepția celor care se vor căi, vor crede și vor împlini fapte bune, căci aceștia vor intra în Rai și nu vor fi nedreptățiți nicicum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'În grădinile Edenului, pe care Cel Milostiv le-a făgăduit robilor Săi - [și ei au crezut în această făgăduință] nevăzută - căci făgăduința Lui se va împlini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'Ei nu vor auzi în ele [niciun fel de] vorbe deșarte, ci numai „Pace.” Și ei vor avea în ele hrana lor, dimineața și seara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'Acesta este Raiul pe care Noi îl dăm ca moștenire robilor Noștri care sunt evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, '[Gavriil a spus] „Noi [Îngerii] nu pogorâm decât la porunca Domnului tău. Ale Lui sunt toate care se află dinaintea noastră și care se află înapoia noastră și cele care se află între acestea. Și Domnul tău nu uită niciodată -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, 'El este Stăpânul Cerurilor și al Pământului și al celor ce se află între cele două. Adoră-L pe El și fii statornic în adorarea Lui! Oare știi tu pe altcineva asemenea Lui?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'Și zice omul [necredincios]: „Oare dacă am murit, voi mai fi eu iarăși adus înapoi la viață?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'Dar oare nu-și aduce omul aminte că Noi l-am creat mai înainte, după ce el nu fusese nimic?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'Pe Domnul tău! Noi îi vom aduna pe ei și pe șeitani, apoi îi vom aduce pe ei în genunchi, de jur împrejurul Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'Apoi îi vom scoate Noi din fiecare grup pe cei care au fost cei mai înverșunați împotriva Celui Milostiv.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'Apoi, Noi Știm cel mai bine care dintre ei merită să fie arși în el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'Și nu se află nimeni printre voi care să nu treacă pe acolo[8]. Aceasta este o hotărâre nestrămutată a Domnului tău.', '[8] Să fie expuși. Însă oamenii Paradisului nu vor fi afectați de aceasta');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'După aceea, îi vom mântui Noi pe cei care au fost cu frică, iar pe cei nelegiuiți îi vom lăsa acolo în genunchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Și când li se citesc Versetele Noastre cele limpezi, zic cei care nu cred către cei care cred: „Care din cele două grupuri are o situație mai bună și o tovărășie mai plăcută?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'Dar câte neamuri care îi întrec pe ei ca avere și ca înfățișare am nimicit Noi înaintea lor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'Spune: „Acelora care sunt în rătăcire Cel Milostiv le va prelungi zilele pentru un timp, până ce ei vor vedea fie chinul, fie Ceasul, cu care ei sunt amenințați. Atunci vor ști ei cine are loc mai rău și cine este mai slab în armată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'Allah va spori călăuzirea celor care sunt bine călăuziți, iar faptele bune care rămân vor avea mai bună răsplată de la Domnul tău și o mai bună urmare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'L-ai văzut pe cel care nu a crezut în Versetele Noastre și a spus: „Mi se vor dărui mie neîndoielnic avere și copii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Oare a pătruns el necunoscutul sau a primit vreo promisiune de la Cel Milostiv?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'În nici un caz! Iar Noi vom scrie ceea ce spune și-i vom spori Noi chinul', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'Noi vom lua de la el moștenire ceea ce spune el și va veni la Noi singur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Ei și-au făcut alți zei în locul lui Allah, ca să le fie lor apărători [împotriva pedepsei].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Dar dimpotrivă! [Acești zei] se vor lepăda de adorarea lor și le vor fi lor dușmani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Tu nu ai văzut că Noi am trimis șeitanii asupra necredincioșilor ca să-i ațâțe pe ei cu furie?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Deci nu te grăbi împotriva lor! Noi ținem socoteala precisă [a tuturor faptelor lor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'În Ziua în care îi vom aduna pe cei cu frică la Cel Milostiv, venind în grupuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'Și-i vom mâna pe nelegiuiți către Iad ca [pe o turmă] la adăpătoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'Ei nu vor putea mijloci, afară de aceia care au făcut un legământ[9] față de Cel Milostiv!', '[9] Să nu adore pe altcineva în afară de El');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, 'Și ei spun: „Cel Milostiv și-a luat un fiu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Voi spuneți un lucru cumplit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, 'Aproape că Cerurile se crapă de aceste [vorbe], pământul se despică și munții se prăbușesc în fărâme', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'Pentru că ei Îi atribuie Celui Milostiv un fiu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'În vreme ce nu se cuvine ca Cel Milostiv să-și ia un fiu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Toți cei care se află în Ceruri și pe Pământ vor veni la Cel Milostiv ca robi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'El i-a socotit și i-a numărat pe ei bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'Și fiecare dintre ei va veni la El în Ziua Învierii singur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'Cu adevărat, celor care cred și săvârșesc fapte bune Cel Milostiv le va arăta Iubire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Și [o, Mohammed] Noi l-am făcut ușor [Coranul], în limba ta, pentru ca tu să-i bine vestești prin el pe cei cu frică și să previi prin el un neam neînduplecat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'Și câte neamuri am nimicit Noi înainte de ei? Mai simți vreun singur [om] din ele? Sau mai auzi tu cea mai mică șoaptă a lor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Ta, Ha[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, 'Noi nu ți-am pogorât Coranul pentru ca tu să fii nefericit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'Ci ca o vestire pentru aceia care se tem [de Allah],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, '[Și ca] o revelație de la Cel care a creat Pământul și Cerurile cele înalte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Cel Milostiv care s-a înălțat deasupra Tronului[2],', '[2] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'Ale Lui sunt cele din Ceruri și cele de pe Pământ, precum și cele care se află între cele două și sub țărână.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'Și dacă tu rostești vorbele cu glas tare, El Știe, [neîndoielnic], taina și ceea ce este chiar și mai ascuns.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Allah! Nu există altă divinitate în afară de El! Ale Lui sunt Numele cele mai frumoase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'Oare ai aflat tu povestea lui Moise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'Când a văzut el un foc și a zis către familia lui: „Rămâneți [aici]! Eu văd un foc! Poate că o să vă aduc un tăciune de la el sau voi afla la foc călăuzire”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'Și când a ajuns la el, a fost el strigat: „O, Moise!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, 'Cu adevărat Eu sunt Stăpânul tău! Scoate-ți încălțările tale, căci tu te afli în Valea cea Sfântă, Tuua.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Și Eu te-am ales, deci ascultă la ceea ce ți se revelează!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Eu sunt Allah și nu există altă divinitate în afară de Mine! Așadar, venerează-Mă și împlinește Rugăciunea [As-Salat], pentru pomenirea Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Cu adevărat Ceasul va sosi - de-abia îl mai țin ascuns[3] - pentru ca fiecare suflet să fie răsplătit după cum se ostenește!', '[3] Însemnând că doar Allah Singurul are cunoștințe despre Ceas');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, 'Și să nu te abată de la el[4] cel care nu crede în el și urmează poftei sale, pentru ca să nu pieri!', '[4] Din pregătirile pentru Ceas sau pentru Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'Dar ce ai în mâna ta dreaptă, o, Moise?”[îl intrebă Allah, deși El Știa prea bine ce era]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, 'El a răspuns: „Acesta este toiagul meu, pe care mă sprijin și cu care scutur frunze pentru oile mele și de la care mai am și alte foloase”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, '[Allah] a spus: „Aruncă-l, o, Moise!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'Și l-a aruncat și iată-l [preschimbat într-] un șarpe ce se târa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, '[Allah] a spus: „ Ia-l, fără să te temi, căci Noi îl vom readuce la prima sa stare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'Și strânge mâna ta la subsuoară! Ea va ieși albă, fără nicio vătămare – o altă Minune,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'Pentru ca să-ți arătăm [și altele] din Minunile Noastre cele mai mari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Și du-te la Faraon. Cu adevărat, el întrece orice măsură!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, '[Moise] a spus: „Doamne, deschide-mi mie pieptul [să am certitudine]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'Și ușurează-mi mie lucrul [ce trebuie să-l împlinesc]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'Și dezleagă-mi nodul limbii mele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'Pentru ca ei să priceapă vorbele mele', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'Și dă-mi mie un sfetnic [sprijinitor] din familia mea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'Pe Aaron, fratele meu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'Sporind prin el forța mea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'Și fă-l pe el părtaș la lucrul meu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'Pentru ca noi să Te Lăudăm îndelung', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'Și să Te pomenim mult.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Cu adevărat, Tu întotdeauna ne-ai văzut pe noi, [știind astfel tot ceea ce noi facem]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, '[Allah] a spus: „Cererea ta a fost împlinită, o, Moise!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, 'Și Noi ți-am mai dăruit Grația Noastră și altă dată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'Când i-am revelat mamei tale ceea ce a fost revelat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, '[Spunând]: „Așează-l pe el într-un coș și pune-l pe râu, pentru ca apoi apa fluviului să-l arunce la mal, de unde îl va lua un dușman al Meu și dușman al lui!” Și am pogorât asupra ta dragostea Mea[5] [și să fi iubit și de ceilalți], pentru ca tu să fii crescut sub ochii Mei.', '[5] Allah a făcut ca oamenii să îl iubească pe Moise');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, 'Și iată cum sora ta mergea, [urmându-te], și a spus: „Să vă arăt eu pe cineva care să-l întrețină și să-l crească?” Și te-am înapoiat Noi mamei tale, pentru ca ea să se bucure și să nu mai fie mâhnită! [Și atunci când] ai ucis un suflet[6], Noi te-am mântuit de întristare. Și te-am încercat Noi în fel și chip. Apoi tu ai rămas ani în șir printre poporul din Madian. Apoi ai venit [aici], așa cum a fost orânduiala, o, Moise.', '[6] Coptul care a murit după ce a fost lovit de Moise');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'Și te-am ales Eu pentru [slujirea] Mea[7].', '[7] Allah l-a ales pe Moise și i-a dăruit un trup puternic și un caracter bun, toate necesare misiunii sale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Pleacă tu împreună cu fratele tău, cu Minunile Mele, și să nu încetați să Mă pomeniți pe Mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Duceți-vă la Faraon, căci el a întrecut orice măsură!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'Și spuneți-i lui vorbe blânde. Poate că el își va aduce aminte sau se va teme [de Allah]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, 'Ei au spus: „Doamne, ne e frică să nu ne pedepsească degrabă și să nu întreacă măsura”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, '[Allah] a spus: „Nu vă fie frică. Cu adevărat, Eu sunt cu voi. Aud și Văd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Deci mergeți la el și spuneți: „Noi suntem Mesagerii Domnului tău. Trimite-i pe Fiii lui Israel împreună cu noi și nu-i mai chinui. Venim la tine cu un semn de la Domnul tău. Pacea[8] [fie] asupra celui care urmează calea cea dreaptă!', '[8] Siguranță de pedepsele lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, 'Cu adevărat, ni s-a revelat nouă că pedeapsa este pentru cel care tăgăduiește credința și îi întoarce spatele”!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, '[Faraon] a spus: „Și cine este Domnul vostru, o, Moise?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, 'El i-a răspuns: „Domnul nostru este Cel care a dat fiecăruia firea sa și apoi l-a călăuzit”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, 'Atunci [Faraon] l-a întrebat: „Și ce spui despre generațiile anterioare?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, '[Moise] i-a răspuns: „Știința despre ele se află la Domnul meu într-o Carte. Domnul meu nu greșește și nu uită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, 'El este Acela care v-a făcut Pământul ca leagăn și v-a făcut vouă pe el drumuri și a pogorât apa din Cer. Și prin ea a făcut să răsară soiuri de felurite plante.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, 'Mâncați și lăsați să pască vitele voastre. Cu adevărat, întru aceasta sunt semne pentru cei dăruiți cu minte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Din el [Pământ] v-am creat, în el Noi vă vom întoarce și din el vă vom scoate încă o dată”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'Și i-am arătat Noi toate semnele Noastre [lui Faraon], însă el le-a tăgăduit și nu a voit [să creadă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, 'Și el a spus: „Ai venit la noi ca să ne scoți din pământul nostru cu vrăjile tale, o, Moise!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, 'Îți vom aduce și noi vrăji asemenea lor. Deci hotărăște între noi și tine o întâlnire de la care să nu lipsim nici noi, nici tu, într-un loc desemnat [un loc public]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, '[Moise] a spus: „Întâlnirea cu voi va fi în ziua de sărbătoare și lumea să se adune dimineața!”[9]', '[9] Pentru ca semnele lui Allah să fie văzute în mod clar');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'Și Faraon a plecat, și-a întocmit vicleșugul și apoi s-a întors [la întâlnire].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, 'Moise le-a spus [vrăjitorilor aduși de Faraon]: „Vai vouă! Nu născociți minciună împotriva lui Allah, căci vă va nimici cu pedeapsa Lui! Iar cei care vor născoci, vor pierde!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'Și au discutat ei între ei despre lucrul lor, dar au făcut-o într-ascuns.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, 'Ei au spus: „Cu adevărat, aceștia sunt doi vrăjitori care vor să vă alunge din pământul vostru cu farmecele lor și să vă ia rânduiala voastră cea desăvârșită [religia sau tradiția].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'Adunați-vă, așadar, vicleșugul vostru și veniți într-un singur rând, căci astăzi va izbândi acela care va fi deasupra.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, 'Apoi ei au spus: „O, Moise, arunci tu [primul, toiagul tău] sau vom fi noi primii care aruncă?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, 'El a spus: „Ba aruncați voi!” Și i s-a părut lui că funiile și toiegele lor se târăsc [ca șerpii] în urma vrăjii lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'Și Moise a simțit oarecare teamă în sufletul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, 'Atunci i-am zis Noi: „Nu te teme, căci tu vei fi deasupra!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, 'Aruncă ce ai în dreapta ta și aceasta va înghiți ce au făcut ei, căci ei au făcut doar vicleșug de vrăjitor, iar vrăjitorul nu va izbândi, oriunde ar fi el.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, 'Și vrăjitorii s-au aruncat, prosternându-se[10], și au zis: „Noi credem în Domnul lui Aaron și al lui Moise.”', '[10] După ce au văzut Miracolele pe care Allah i le-a dat lui Moise și au realizat că acestea sunt reale și nu sunt iluzii create de magie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, '[Faraon] a spus: „Ați crezut în el [Moise] înainte ca eu să vă permit. Cu adevărat, el este liderul vostru, care v-a învățat vrăjitoria. Eu vă voi tăia mâinile și picioarele voastre în cruciș și vă voi răstigni de trunchiurile palmierilor și astfel veți ști voi care dintre noi este mai aspru și mai statornic în chin!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, 'Ei au spus: „Noi nu te vom prefera niciodată în locul dovezilor limpezi care ne-au venit și în locul Celui care ne-a creat. Hotărăște ceea ce vrei să hotărăști, dar tu nu vei hotărî decât în această viață lumească.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, 'Cu adevărat, noi credem în Domnul nostru, pentru ca El să ne ierte păcatele noastre și vrăjitoria la care ne-ai obligat!” Iar Allah este mai bun [la Răsplată] și mai statornic [la Pedeapsă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Cu adevărat, cel ce vine nelegiuit la Domnul său - va avea parte de Iad, în care el nici nu va muri, dar nici nu va trăi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'Dar cei care vin la El credincioși și care au săvârșit fapte bune - vor avea treptele cele mai înalte -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'Grădinile Edenului, pe sub care curg râuri, unde vor avea veșnic sălaș în ele, căci aceasta este răsplata acelora care s-au curățit”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'Și Noi i-am revelat lui Moise: „Purcede noaptea cu robii Mei și croiește-le lor un drum uscat prin mare! Nu-ți fie teamă că vei fi ajuns din urmă [de Faraon] și nu-ți fie frică [de înec]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'Și a pornit Faraon pe urma lor cu soldații săi, dar marea i-a cuprins și i-a acoperit cu totul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'Iar Faraon și-a dus poporul în rătăcire și nu l-a călăuzit pe drumul cel bun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'O, Fii ai lui Israel, Noi v-am mântuit de dușmanul vostru și v-am orânduit vouă întâlnire[11] la coasta cea din dreapta Muntelui! Și am pogorât asupra voastră mana și prepelițele!', '[11] Cu Profetul vostru pentru a primi Scriptura pentru voi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, '[Spunând]: „Mâncați din bunătățile cu care v-am înzestrat, însă nu întreceți măsura întru aceasta, ca să nu vă lovească mânia Mea, căci, cel pe care-l lovește mânia Mea, este pierdut.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'Dar, cu adevărat, Eu sunt Iertător cu cel care se căiește, crede și împlinește fapte bune și apoi se lasă călăuzit pe calea cea bună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, '[Allah a spus]: „Și de ce te-ai grăbit [să te îndepărtezi] de neamul tău, o, Moise?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, 'El a spus: „Ei sunt pe urmele mele și eu am grăbit spre Tine, Doamne, pentru ca Tu să fii mulțumit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, '[Allah a Spus]: „ Dar, cu adevărat, Noi am încercat poporul tău după tine și As-Samiriy[12] l-a dus pe el în rătăcire”.', '[12] Tradus ca și „Samaritean” (din Samaria), un ipocrit dintre ei care i-a făcut pe Fiii lui Israel să adore idoli');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'Atunci s-a întors Moise la neamul său, mânios și mâhnit, și a spus: „O, popor al meu! Nu v-a făcut Domnul vostru frumoasă făgăduire[13]? Legământul a fost prea lung pentru voi sau ați vrut să se abată asupra voastră mânia Domnului vostru și de aceea ați încălcat făgăduința făcută mie?”', '[13] Că El va pogorî Tora, ce conține călăuzire pentru voi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, 'Ei au spus: „Noi nu am încălcat făgăduința dată ție cu voia noastră, însă noi am fost încărcați cu sarcini de podoabe ale neamului [lui Faraon] și le-am aruncat noi [în foc] și asemenea le-a aruncat și As-Samiriy”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'Și le-a scos lor un vițel - un corp [neînsuflețit] care scotea un sunet slab - și ei au spus: „Acesta este dumnezeul vostru și dumnezeul lui Moise, însă el l-a uitat”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Oare n-au văzut ei că el nu le răspundea cu nicio vorbă și că el nu avea putere să le facă lor un rău sau să le fie spre folos?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'Și le zisese și Aaron mai înainte [de întoarcerea lui Moise]: „O, popor al meu! Voi ați fost numai testați prin aceasta. Însă Domnul vostru cu adevărat este Cel Milostiv. Așadar, urmați-mă și ascultați de porunca mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, 'Ei au răspuns: „Vom rămâne adoratori ai lui [ai vițelului] până ce se va întoarce Moise la noi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, '[Moise] a spus: „Ce te-a împiedicat pe tine, o, Aaron, când i-ai văzut că ei se duc în rătăcire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'Să vii după mine? Te-ai răzvrătit și tu împotriva poruncii mele?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, '[Aaron] a spus: „O, fiu al mamei mele! Nu mă apuca nici de barbă, nici de [părul din] cap. Cu adevărat, mie mi-a fost teamă să nu zici: Tu i-ai dezbinat pe Fiii lui Israel și nu ai așteptat porunca mea.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, '[Moise] a spus: „Și care a fost socoteala ta, o, As-Samiriy?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, 'El a spus: „Eu am văzut ceea ce ei nu au văzut: am luat o mână [de țărână] de pe urma mesagerului[14] și am aruncat-o[15]. Așa mi-a spus sufletul meu”.', '[14] O urmă de potcoavă lăsată de calul Îngerului Gavriil în pământ
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, '[Moise] a spus: „Du-te! În această viață vei spune tu [la toată lumea]: „Nu mă atingeți.” Și vei avea o întâlnire de la care nu vei putea lipsi. Și privește la dumnezeul tău, căruia i-ai rămas credincios! Noi îl vom preface în pulbere și-l vom risipi în mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Domnul vostru este numai Allah, afară de care nu există altă divinitate. Iar El le Cuprinde pe toate cu Știința.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'Astfel îți povestim Noi istorisiri despre cele care au trecut și îți dăm Noi ție o pomenire din partea Noastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Iar cei care se îndepărtează de el [Coran] vor purta în Ziua Învierii o povară.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'Și veșnic vor sălășlui în el[16]. Și ce grea Povară vor avea ei în Ziua Învierii!', '[16] În păcat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'Ziua în care se va sufla în Trâmbiță și-i vom aduna pe cei nelegiuiți, învinețiți.[17]', '[17] De teroare sau complet orbi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'Și ei vor șușoti între ei: „Voi nu ați zăbovit decât zece [zile]”!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Noi Știm mai bine ceea ce spun ei, când va zice cel cu purtarea cea mai aleasă dintre ei: „Voi nu ați zăbovit decât o zi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'Și ei te întreabă despre munți. Spune: „Domnul meu îi va face praf, risipindu-i,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, 'Și va lăsa [Pământul] ca pe un șes neted,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'În care nu vei vedea ridicătură sau adâncitură.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'În Ziua aceea [toți] îl vor urma pe Cel care cheamă[18], fără abatere, iar glasurile vor coborî smerite înaintea Celui Milostiv [Ar-Rahman ] și nu vei auzi decât o șoaptă.', '[18] La adunare pentru judecată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'În Ziua aceea nu va fi de folos mijlocirea, decât de la cel căruia Cel Milostiv [Ar-Rahman] îi va îngădui și a cărui vorbă o va găsi plăcută.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'El [Allah] Știe ceea ce se află în fața lor [în prezent] și ceea ce se află în urma lor[19], în vreme ce ei nu-L cuprind cu știința.', '[19] A se vedea 2:255');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Și [toate] fețele se vor pleca umilite în fața Celui Veșnic Viu [Al-Hayy] [și] Atotputernic [Al-Qayyum ] și [nefericit] și pierdut va fi acela care va purta o nedreptate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'Dar cel care săvârșește fapte bune și este dreptcredincios nu are a se teme de nedreptate sau de oprimare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'Astfel l-am pogorât Noi un Coran în [limba] arabă. Și am deslușit în el avertizările, pentru ca ei să fie cu teamă și pentru ca să le trezească lor amintirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'Și mai presus [de toate] este Allah - Al-Malik [Regele], Al-Haqq [Adevărul]! Nu te grăbi [O, Mohammed] cu recitarea Coranului mai înainte de a ți se încheia revelarea lui! Și spune: „Doamne, sporește-mi mie știința.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'Noi am încheiat un legământ cu Adam mai înainte, însă el l-a uitat și Noi nu am aflat în el tărie[20].', '[20] De a rezista tentației');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'Și [spune] când Noi le-am spus Îngerilor: „Prosternați-vă dinaintea lui Adam” și s-au prosternat ei, afară de Iblis[21], care s-a împotrivit.', '[21] A se vedea 2:34');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, 'Atunci Noi am spus: „O, Adam, acesta vă este dușman ție și soaței tale. [Fiți cu grijă] să nu vă scoată pe voi din Rai și să fii tu nefericit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'Cu adevărat, este [o promisiune] pentru tine; pentru ca să nu-ți fie foame în el și să nu fii gol,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'Pentru ca să nu-ți fie ție sete în el și să nu te lovească dogoarea soarelui”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'Atunci Șeitan l-a ispitit, spunându-i: „O, Adam, vrei tu să-ți arăt pomul veșniciei și împărăția care nu piere?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'Și au mâncat ei doi [Adam și soția sa] din el și li s-a arătat goliciunea lor și au început să strângă, pentru a se acoperi, frunze din Rai. Adam nu s-a supus, așadar, Domnului său și a ajuns în rătăcire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'Apoi l-a ales pe el Domnul său, l-a iertat și l-a călăuzit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, '[Allah a spus]: „Coborâți amândoi din el [din Paradis]! Vă veți fi toți dușmani unul altuia. Apoi, dacă va mai veni la voi o călăuzire din partea Mea, cel care va urma calea Mea cea dreaptă nu va rătăci [în această viață] și nu va fi nefericit [în Viața de Apoi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'Însă cel care se va îndepărta de la Pomenirea Mea, cu adevărat, el va avea parte de o viață grea și în Ziua Învierii îl vom aduce pe el orb la adunare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, 'El va spune: „Doamne, de ce m-ai adus pe mine orb, la adunare, după ce mai înainte am fost eu bine-văzător?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, '[Allah] va spune: „Așa cum Versetele Noastre au venit la tine, iar tu le-ai uitat, așa și tu ești în această Zi uitat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'Astfel îl răsplătim Noi pe cel care întrece măsura și nu crede în semnele Domnului său, iar pedeapsa din Viața de Apoi va fi mai aspră și mai îndelungată[22].', '[22] Decât cea din această viață');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Oare nu le folosește lor spre bună călăuzire câte neamuri au fost nimicite mai înainte de ei, în ale căror case merg ei [acum]? Cu adevărat, întru aceasta sunt semne pentru cei care au minte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'Și de n-ar fi fost un cuvânt[23] de la Domnul tău mai înainte, [pedeapsa] ar fi venit numaidecât, dar este un termen deja hotărât.', '[23] A se vedea 10:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Rabdă ceea ce ei spun și înalță laudă Domnului tău; înainte de răsăritul soarelui, înainte de asfințitul lui și în ceasurile nopții laudă-L și la capetele zilei, poate că astfel vei fi tu mulțumit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'Și nu privi îndelung la ceea ce Noi am dat ca plăcere trecătoare unora dintre ei și ca strălucire a vieții din această lume, pentru a-i încerca pe ei prin aceasta! Ceea ce Allah îți dă va fi mai bun și mai dăinuitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Și poruncește neamului tău Rugăciunea [As-Salat] și fii statornic în ea! Noi nu-ți cerem câștig [și provizii de trebuință], fiindcă Noi îți dăm ție câștig [și cele de trebuință], iar urmarea bună este a evlaviei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Și ei au spus: „De ce nu ne aduce el un semn de la Domnul său?” Dar oare nu a venit la ei dovadă limpede care se află în Scripturile de mai înainte de el?[24]', '[24] Nu este Coranul o dovadă adecvată a faptului că Mohammed este Profet?');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'Dar dacă Noi i-am fi nimicit printr-o pedeapsă mai înainte de el[25], atunci ar fi zis ei: „Doamne, de ce nu ne-ai trimis Tu un Profet, ca să fi putut urma semnele Tale înainte ca noi să fi fost umiliți și loviți de rușine?”', '[25] Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa); sau cu referire la Coran, de asemenea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, 'Spune: „Fiecare este în așteptare. Deci așteptați și voi! Și veți ști voi cine sunt cei care se află pe drumul cel drept și cine a fost bine călăuzit”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'Se apropie de oameni [termenul] socotirii cu ei, însă ei se îndepărtează cu nepăsare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'Nu le vine lor o revelație nouă [din Coran] de la Domnul lor fără ca ei să n-o asculte și să n-o ia în batjocură,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'Cu inimi nepăsătoare, iar cei care sunt nelegiuiți vorbesc în șoaptă: „Este acesta altceva decât un om ca și voi? Voiți să veniți la vrăjitorie, când voi o vedeți limpede?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, 'El [Profetul (pacea și binecuvântarea lui Allah fie asupra sa)] a spus: „Domnul meu Știe ceea ce se spune și în Cer și pe Pământ. El este As-Sami'' [Cel care Aude Totul] [și] Al-''Alim [Atoateștiutor]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Dar ei spun: „[Revelațiile] sunt vise false; ba el le-a plăsmuit; ba el este mai degrabă un poet. Să ne aducă o minune, așa cum au fost trimiși cei de mai înainte [cu miracole]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Nicio cetate din cele pe care Noi le-am distrus nu a crezut înainte de ei[1]! Și oare ei ar crede?', '[1] Deși au văzut semne și miracole');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'Și Noi nu am trimis înainte de tine [o, Mohammed] decât numai bărbați cărora le-am revelat [Mesajul]. Întrebați-i pe oamenii Cărții, dacă voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Și Noi nu i-am făcut pe ei [pe Profeți] niște trupuri care nu mănâncă hrană[2] și ei nu au fost veșnici.', '[2] Precum Îngerii. Dimpotrivă ei sunt ființe omenești cu atribute umane');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Apoi[3] le-am adeverit Noi făgăduința și i-am mântuit pe ei și pe cei care am voit Noi și i-am nimicit pe cei care au întrecut măsura.', '[3] După ce au transmis mesajul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Cu adevărat, Noi v-am pogorât o Carte [Coranul] în care se află pomenirea voastră. Oare nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, 'Și câte cetăți care au fost nelegiuite am distrus Noi?! Și după ele am creat Noi alte neamuri?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'Și când ei [locuitorii lor] simt pedeapsa Noastră, iată-i cum o iau la fugă, părăsindu-le!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, '[Unii Îngeri spun:] „Nu fugiți, ci întoarceți-vă la cele cu care v-ați îmbuibat și la casele voastre, pentru ca voi să puteți fi întrebați[4]!”', '[4] Despre ce s-a întâmplat cu voi. Aceasta le este spus într-un mod sarcastic');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, 'Dar ei spun: „Vai nouă! Noi am fost nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, 'Și nu vor înceta aceste strigăte ale lor până ce nu-i vom face Noi niște miriști, stinși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Și Noi nu am creat Cerul și Pământul și ceea ce se află între ele, în joacă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Dacă am fi Voit să facem o joacă, am fi făcut-o [din lucrurile apropiate] de Noi, dacă am fi făcut-o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Dimpotrivă, Noi lovim cu adevărul deșertăciunea și o distrugem[5] și iată că ea este ca și moartă. Și va fi vai de voi pentru ceea ce Îi puneți Lui în seamă [că Allah ar avea soție și un fiu].', '[5] O facem să dispară sau o omorâm');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'Ai Lui sunt cei din Ceruri și de pe Pământ. Iar cei care sunt lângă El [Îngerii] nu se socotesc prea mari pentru a-L adora și nici nu obosesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'Ei Îi aduc laudă noaptea și ziua fără să slăbească [în adorare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Sau iau ei [oamenii] zei pe pământ care să poată să-i învie [pe morți]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Dacă s-ar afla în ele [în Ceruri și Pământ] alți dumnezei în afară de Allah, amândouă ar fi stricate. Mărire lui Allah, Stăpânul Tronului, Care este mai Presus decât ceea ce spun ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'El nu este întrebat despre ceea ce Face, pe când ei vor fi întrebați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Sau iau ei în locul Lui alți dumnezei? Spune [Mohammed]: „Aduceți dovada voastră. Acesta [Coranul] este Mesajul celor care sunt cu mine și Mesajul celor de dinainte de mine! Însă cei mai mulți dintre ei nu cunosc Adevărul și se întorc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, 'Și Noi nu am trimis înaintea ta niciun Profet fără să nu-i revelăm lui: „Nu există altă divinitate în afară de Mine, deci adorați-Mă pe Mine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Și ei spun: „Cel Milostiv Și-a luat un fiu.” Mărire Lui! Însă ei[6] nu sunt decât niște robi ținuți în cinste.', '[6] Cei pe care aceștia îi consideră a fi „copiii” lui Allah, precum Îngerii, Ezra, Iisus, etc.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Ei nu I-o iau înainte cu vorba și ei se comportă numai după Porunca Lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'El Știe ce este înaintea lor [în prezent] și ce este în urma lor și ei nu pot mijloci decât pentru cel de care El este mulțumit. Iar ei sunt cu teamă de El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'Iar pe acela dintre ei care spune: „Eu sunt un dumnezeu alături de El!” îl vom răsplăti cu Iadul, căci astfel îi răsplătim pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Oare nu văd cei care nu cred că Cerurile și Pământul au fost împreună și că Noi le-am despărțit și din apă am făcut tot ce este lucru viu? Și oare tot nu cred ei?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'Și Noi am Făcut pe Pământ munți neclintiți, pentru ca el să nu se clatine cu ei, iar printre ei [munți] am făcut cărări și drumuri pentru ca ei să se poată călăuzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'Și Noi am Făcut Cerul ca un acoperiș bine păzit și totuși ei sunt fără băgare de seamă la semnele[7] lui.', '[7] Semnele prezente în Ceruri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'Și El este Cel care a creat noaptea și ziua, Soarele și Luna și fiecare plutește pe orbita sa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, 'Și Noi nu am dat veșnicia niciunui om înainte de tine. Dacă tu mori, ar putea fi ei nemuritori?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Fiecare suflet va gusta moartea. Noi vă încercăm cu răul și cu binele, în chip de ispită, și la Noi vă veți întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Și când te văd cei care nu cred [o, Mohammed], nu te privesc altfel decât cu batjocură [și spun:] „Acesta este cel care îi vorbește [de rău] pe dumnezeii voștri?” Însă ei în Mesajul Celui Milostiv nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'Omul a fost creat din grabă [fiind nerăbdător]. Eu vă voi arăta semnele Mele, însă nu-Mi cereți să Mă grăbesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, 'Și ei spun: „Și când va veni această amenințare, dacă sunteți întru adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'Dacă ar ști cei care nu cred [momentul] când ei nu vor putea să oprească focul de la fețele lor, nici de la spatele lor și nici nu vor putea ei să fie ajutați...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Însă acesta va veni asupra lor pe neașteptate și ei vor fi uluiți și nu îl vor putea îndepărta de ei și nici nu li se va mai da răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Și au fost batjocoriți și alți Mesageri de dinainte de tine, dar cei care i-au batjocorit au fost învăluiți de ceea ce obișnuiau să ridiculizeze.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'Spune: „Cine vă [poate] apară noaptea și ziua de Cel Milostiv?” Însă ei se feresc să-L Pomenească pe Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Sau au ei dumnezei, în afară de Noi, care să-i apere de Noi? Ei nu se pot ajuta nici pe ei înșiși și nici nu vor fi ei ajutați împotriva Noastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Dar [dimpotrivă] Noi le-am dăruit acestora și părinților lor plăcerile trecătoare, și au avut ei parte de viață lungă. Dar oare nu văd ei că Noi venim asupra Pământului pe care îl îngustăm din toate părțile[8]? Și oare ei vor fi biruitori?', '[8] A se vedea 13:41');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, 'Spune: „Eu doar vă previn prin ceea ce îmi este revelat”. Însă cei surzi nu aud chemarea când sunt preveniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'Dar când îi atinge pe ei o adiere a chinului Domnului tău, atunci ei spun: „Vai nouă! Noi am fost, într-adevăr, nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'În Ziua Învierii, Noi vom pune balanța dreaptă[9] și niciun suflet nu va fi urgisit câtuși de puțin. Și de ar fi ceva, chiar și numai cât greutatea unei semințe de muștar[10], Noi îl vom aduce. Și Noi suntem îndeajuns ca socotitori.', '[9] În Ziua aceea judecata va fi dreaptă
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Și Noi le-am dat lui Moise și lui Aaron Cartea de îndreptare [Al-Furqan], ca o lumină și o îndemnare pentru cei cu frică,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, 'Pentru cei care se tem de Domnul lor nevăzut[11] și pentru cei care se tem de Ceasul [de Apoi].', '[11] Care poate însemna „Allah nu este văzut” de ei sau „deși ei nu sunt văzuți de alții”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Acesta [Coranul] este un Mesaj binecuvântat pe care chiar Noi l-am pogorât. Și oare voi îl tăgăduiți[12]?', '[12] Pretinzând ignoranță sau refuzând să îl acceptați?');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Și i-am dat Noi lui Avraam călăuzirea pe drumul cel drept mai înainte[13], pentru că Noi îl Cunoșteam foarte bine.', '[13] Înainte de Moise. Allah l-a călăuzit de tânăr');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Și când le-a zis el tatălui său și poporului său: „Ce sunt aceste statui pe care voi le adorați?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, 'Ei i-au răspuns: „Noi i-am aflat pe părinții noștri închinându-se la ele”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, 'El a spus: „Voi și părinții voștri ați fost în rătăcire învederată”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, 'Ei au spus: „Tu ai venit la noi cu Adevărul sau tu ești dintre aceia care glumesc?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, 'Iar el a răspuns: „[Nu,] dimpotrivă, Domnul vostru este Stăpânul Cerurilor și al Pământului, care le-a creat pe ele, iar eu sunt unul dintre aceia care vă mărturisesc vouă despre aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, 'Și, [jur] pe Allah! Eu voi urzi împotriva idolilor voștri, după ce veți întoarce spatele, îndepărtându-vă.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'Și i-a făcut pe ei fărâme, afară de cel mai mare dintre ei, astfel încât să se întoarcă spre el [pentru a-l întreba].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, 'Ei au spus: „Cine a făcut aceasta cu zeii noștri? Cu adevărat, el este dintre cei nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, 'Ei au spus: „Am auzit un fecior vorbind împotriva lor. El se numește Avraam”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, 'Ei au spus: „Aduceți-l dinaintea oamenilor pentru ca ei să facă mărturie![14] ”', '[14] Despre ce l-au auzit că a spus. Poate să însemne și...ca ei să fie martori [la ce i se va pregăti ca pedeapsă]');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, 'Ei au spus: „Tu ai făcut aceasta cu zeii noștri, o, Avraam?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, 'El a spus: „Ba a făcut-o cel mai mare dintre ei, acesta! Întrebați-i, dacă ei pot vorbi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'Atunci s-au întors la [a se învinovăți pe] ei și au spus [unii altora]: „Cu adevărat, voi sunteți cei nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Apoi au întors capetele lor[15] [spunând]: „Tu știi prea bine că aceștia nu vorbesc!”', '[15] După ce și-au recunoscut prima dată greșeala, aceștia au fost cuprinși de mândrie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, 'Și el a spus: „Dar oare voi vă închinați, în loc de Allah, la ceva care nu vă este de niciun folos și nici nu vă poate face nimic rău?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, 'Uf! Pentru voi și pentru ceea ce adorați în locul lui Allah! Oare voi nu pricepeți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, 'Ei au spus: „Ardeți-l și ajutați-i pe zeii voștri, dacă voi vreți să faceți [ceva pentru ei]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, 'Dar Noi [Allah] am spus: „O, foc! Fii răcoare și siguranță pentru Avraam!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'Ei au vrut un vicleșug împotriva lui, însă Noi am făcut ca ei să fie cei mai în pierdere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'Și Noi l-am salvat pe el și [asemenea] și pe Lot pe Pământul pe care l-am binecuvântat pentru [toate] lumile [pentru oameni și djini].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'Și i-am dăruit Noi pe Isaac și pe Iacob, pe deasupra, și pe toți i-am făcut evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'Și i-am făcut Noi lideri, care au călăuzit [lumea] după Porunca Noastră, și le-am revelat lor să facă fapte bune, să împlinească Rugăciunea [As-Salat] și să dea Dania [Az-Zakat] și ei Ne-au fost Nouă adoratori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'Iar lui Lot i-am dăruit Noi Înțelepciune și Știință și l-am salvat pe el din cetatea care săvârșea desfrâu. Cu adevărat, ei au fost un neam de oameni răi, nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'Și l-am făcut pe el să intre sub Îndurarea Noastră, căci el era cu adevărat dintre cei evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'Și [spune de] Noe, când a chemat el [pe Allah][16], mai înainte, și i-am răspuns Noi și l-am salvat pe el împreună cu familia lui de necazul cel mare.', '[16] Când s-a rugat împotriva poporului său care persista în negare și animozitate. A se vedea 71:26-28');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'Și l-am ajutat Noi împotriva poporului care ținea semnele Noastre de minciună. Ei erau un neam rău și i-am înecat pe ei cu toții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'Și [spune de] David și Solomon, când au judecat asupra câmpului cultivat pe care au păscut [noaptea] oile unui popor[17]. Iar Noi am fost Martori la judecata lor.', '[17] Mâncând și distrugând');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'Și Noi l-am învățat pe Solomon să o înțeleagă și fiecăruia i-am dat putere de judecată și știință. Și i-am supus lui David munții și păsările ca să Ne aducă Laudă împreună cu el. Și Noi le-am Făcut[18].', '[18] Însemnând că Allah a fost întotdeauna capabil de a realiza orice își Dorește');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'Noi l-am învățat meșteșugul cămășilor din zale, pentru ca să vă apere de asprimea voastră. Și oare sunteți voi mulțumitori?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'Iar lui Solomon [i-am supus Noi] vântul cel vijelios, ca să alerge la porunca sa pe Pământul pe care Noi l-am binecuvântat. Și Noi am avut Știinţă asupra tuturor lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'Și printre șeitani [djinni] au fost unii care se cufundau pentru el și făceau și alte lucruri, iar Noi am fost păzitori peste ei[19].', '[19] Prevenind orice neascultare sau deviere din partea lor în ceea ce privește instrucțiunile lui Solomon și protejându-l de a fi rănit de către aceștia');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'Și [spune de] Iov, când l-a chemat pe Domnul lui: „M-a atins pe mine răul! Însă Tu ești Cel mai Milostiv între milostivi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'Și Noi i-am răspuns și am îndepărtat răul care-l lovise și i-am dat lui înapoi familia lui, și încă pe atât împreună cu ei, ca Îndurare din partea Noastră și ca amintire pentru adoratori [ai lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'Și [spune de] Ismail și de Idris și de Dhu-l-Kifl - și toți erau dintre cei răbdători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'Și i-am făcut Noi să intre în Îndurarea Noastră, căci ei au fost cu adevărat evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'Și [spune de] de omul peștelui [Iona], când el a plecat furios[20] și și-a închipuit că Noi nu vom mai avea putere asupra lui[21]. Atunci el a strigat în întunecimi[22]: „Nu există altă divinitate în afară de Tine! Slavă Ție! Eu am fost dintre cei nelegiuiți!”', '[20] Din cauza necredinței poporului său
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Și Noi i-am răspuns și l-am izbăvit de mâhnire. Astfel îi salvăm Noi pe dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'Și [adu-ți aminte] de Zaharia, când l-a chemat pe Domnul său: „Doamne, nu mă lăsa singur, căci Tu ești Cel mai bun dintre moștenitori!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Și i-am răspuns Noi și i l-am dat lui pe Ioan și am tămăduit-o pentru el pe soața lui. Ei se întreceau în bine și Ne chemau cu dorință și cu teamă și erau evlavioși față de Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'Și [spune] de cea care și-a păstrat castitatea [Maria]. Și am suflat Noi asupra ei prin duhul Nostru [Gavriil] și am făcut din ea și din fiul ei semn pentru [toate] lumile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Cu adevărat, această credință a voastră este o credință unică, iar Eu sunt Domnul vostru. Așadar, adorați-Mă pe Mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Dar ei s-au divizat între ei[23]. Însă cu toții se vor întoarce la Noi.', '[23] Împărțindu-se în secte și denominații');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'Iar cel care împlinește fapte bune și este dreptcredincios – străduința sa nu va fi negată, iar Noi [Îngerii Noștri] o vom scrie pentru el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'Și le este oprit [locuitorilor] unei cetăți pe care Noi am distrus-o să se mai întoarcă[24],', '[24] Ei nu se pot întoarce în această lume și nici nu se pot căi la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'Până când vor fi lăsați să treacă Yagog și Magog și ei se vor grăbi de pe toate înălțimile;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'Și [când] va fi apropiată promisiunea cea adevărată [Învierea], atunci deodată ochii celor care nu au crezut vor fi împietriți [și vor spune]: „Vai nouă! Am fost cu nebăgare de seamă față de aceasta, ba am fost nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'Cu adevărat, voi [necredincioșilor] și cei pe care îi adorați, în afară de Allah, veți fi vreascurile [arse în focul] Iadului, spre care voi veniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Dacă aceștia [zeii falși] ar fi dumnezei, nu ar veni spre el. Dar toți vor rămâne veșnic în el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'Ei vor scoate în el gemete și ei nu vor auzi în el [nimic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'Cu adevărat, cei cărora li s-a promis de mai înainte [răsplata] cea mai bună din partea Noastră vor sta departe de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Ei nu vor auzi glasul lui [al Iadului], și acolo unde vor pofti sufletele lor, ei vor rămâne veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, 'Nu-i va întrista spaima cea mare[25] și îi vor întâmpina Îngerii [spunându-le]: „Aceasta este Ziua voastră, care vi s-a promis”.', '[25] Evenimentele Ceasului și ale Învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'În Ziua aceea vom închide Noi Cerul, așa cum se închid sulurile cu scripturi. Așa cum am Făcut Noi prima făptură, o vom face din nou. Aceasta este o Promisiune pe care Noi am făcut-o și pe care o Îndeplinim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Și Noi am scris în Carte[26], după Pomenire[27]: „Robii Mei cei evlavioși vor moșteni pământul [Paradisului]”.', '[26] Toate Cărțile primite de Profeți
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'În acest [Coran] este un Mesaj pentru un popor [de oameni] care adoră [pe Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'Și Noi nu te-am trimis [o, Mohammed] decât ca o îndurare pentru lumi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, 'Spune: „Mi s-a revelat mie că Domnul vostru este un Domn Unic! Oare voi sunteți supuși Voinței Lui [musulmani]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'Și dacă, după aceea, ei întorc spatele, spune: „Eu v-am vestit vouă cu toată dreptatea[28], însă eu nu știu dacă este aproape ori este departe ceea ce vi s-a promis.', '[28] Profetul (pacea și binecuvântarea lui Allah fie asupra sa) a făcut cunoscut acest mesaj tuturor oamenilor și nu a ascuns nimic din el de alți oameni și nici nu a preferat un grup în locul altuia');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'El Știe vorbele rostite de voi cu glas tare și El Știe și ceea ce ascundeți [în inimi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'Și eu nu știu; poate aceasta[29] nu este o ispită pentru voi sau o plăcere [trecătoare] până la un timp”.', '[29] Amânarea pedepsei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, 'El spune: „Doamne, judecă întru dreptate!” Și Domnul nostru Ar-Rahman [Cel Milostiv] este Cel la Care se cere ajutor împotriva a ceea ce voi rostiți[30]!”', '[30] Minciunile și necredința lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'O, voi oameni! Fiți cu frică de Domnul vostru. Cu adevărat, cutremurul Ceasului va fi un lucru înspăimântător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'În Ziua în care îl veți vedea, fiecare femeie care alăptează va uita de cel pe care ea îl alăpta și fiecare femeie însărcinată va lepăda sarcina ei, iar pe oameni îi vei vedea amețiți, fără ca ei să fie beți, dar pedeapsa lui Allah va fi aspră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'Printre oameni sunt unii care se ceartă în privința lui Allah, fără de știință, și care îl urmează pe orice șeitan răzvrătit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'Căruia i-a fost scris că, pe acela care-l va lua drept ocrotitor, el îl va duce în rătăcire și îl va călăuzi către chinul Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'O, voi oameni! Dacă sunteți în îndoială cu privire la Înviere, atunci [gândiți-vă că] Noi, cu adevărat, v-am creat din țărână, apoi dintr-o picătură, apoi dintr-un cheag de sânge [ca o lipitoare], apoi dintr-o bucată de carne, cu formă, după ce a fost fără formă [plăsmuită și neplăsmuită][1], pentru ca să vă arătăm vouă [Puterea Noastră]. Și Noi lăsăm să sălășluiască în pântece ceea ce Voim Noi până la un timp hotărât; apoi vă scoatem pe voi ca prunci, pentru ca apoi să ajungeți voi la vârsta maturității. Și unii dintre voi mor [tineri], iar alții sunt lăsați [să trăiască] până la cea mai neputincioasă vârstă, pentru ca să nu mai știe nimic după ce au știut. Tu vezi Pământul fără viață, iar dacă Noi pogorâm apa asupra lui, el se mișcă, se umflă și lasă să răsară [plante] din fiecare soi minunat.', '[1] Ceea ce este incomplet. Aceasta poate include ceea ce este avortat în acea stare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Aceasta pentru [ca să știți] că Allah este Adevărul și pentru [ca să știți] că El îi readuce la viață pe cei morți și El este peste toate Qadir [Atotputernic];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'Și pentru [ca să știți] că Ceasul va sosi, fără îndoială, și [atunci] Allah îi va învia pe cei din morminte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Dar printre oameni sunt unii care discută despre Allah, fără de știință, fără călăuzire și fără carte luminătoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'Întorcându-și capul cu semeție [cu aroganță], pentru a-i abate [pe oameni] de la calea lui Allah. Aceștia vor avea parte de rușine în această viață și îi vom face pe ei să guste în Ziua Învierii chinul Focului [în timp ce li se va spune lor:]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, '„Aceasta este pentru ceea ce au săvârșit mai înainte mâinile voastre, căci Allah nu este nedrept față de robi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Și printre oameni este cel care Îl adoră pe Allah pe o margine[2]: Dacă are parte de bine, el este netulburat, dar dacă are parte de o încercare, atunci el își întoarce fața [în cealaltă parte], pierzând și această lume și Viața de Apoi. Aceasta este pierderea evidentă.', '[2] Pe lângă religia sa, cu incertitudine, ipocrizie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'El cheamă în locul lui Allah ceea ce nici nu îi face rău și nici nu îi aduce niciun bine. Aceasta este rătăcirea adâncă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'El cheamă pe cel a cărui stricăciune este mai aproape decât ajutorul lui. Ce rău aliat și ce rău tovarăș!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Cu adevărat, Allah îi primește pe aceia care cred și săvârșesc fapte bune să intre în Grădini pe sub care curg râuri. Cu adevărat, Allah face ceea ce Voiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Cel care își închipuie că Allah nu-l va ajuta [pe Profetul Său] în această viață și în Viața de Apoi, să întindă o funie până la Cer, iar apoi [să-și] oprească [respirația][3] și să vadă: va îndepărta vicleșugul său ceea ce îl înfurie?', '[3] Să se spânzure');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'Și astfel l-am pogorât Noi [Coranul], în Versete limpezi, iar Allah călăuzește pe cine Voiește El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Cu adevărat, în legătură cu cei care au crezut și cu cei care au fost evrei, cu sabeenii și cu creștinii, cu magii și cu cei care i-au făcut asociați lui Allah - Allah va hotărî între ei în Ziua Judecății. Cu adevărat, Allah este la toate Martor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Oare tu nu vezi [nu știi] că dinaintea lui Allah se prosternează cei din Ceruri și cei de pe Pământ, Soarele, Luna, Stelele, munții, copacii, vietățile și mulți oameni? Însă multora li se cuvine pedeapsa. Iar cel pe care îl înjosește Allah, nu va afla pe cineva care să-i dea cinste. Cu adevărat, Allah face ceea ce Voiește!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Acești doi[4] adversari se ceartă asupra Domnului lor. Însă celor care nu cred li se vor croi veșminte din foc, iar peste capetelor lor se va turna apă clocotitoare,', '[4] Credincioșii și necredincioșii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'Cu care se vor topi cele pe care le au în burțile lor, precum și pieile [lor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'Și vor avea ei parte de bice de fier.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'Și de fiecare dată când vor încerca să iasă din el [Iad], [pentru a scăpa] de suferință, ei vor fi împinși înapoi [și li se va zice lor]: „Gustați chinul Focului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'Cu adevărat, Allah îi va aduce pe cei ce cred și săvârșesc fapte bune în Grădini pe sub care curg râuri și în ele vor fi împodobiți cu brățări de aur și mărgăritare, iar veșmintele lor vor fi în ele de mătase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, 'Ei au fost călăuziți [în viața lumească] către cuvântul bun și ei au fost călăuziți către calea Celui Vrednic de Laudă [Al-Hamid].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Cu adevărat, celor care nu cred și împiedică [oamenii] de la calea lui Allah și de la Moscheea Al-Haram, pe care Noi am făcut-o pentru oameni - atât pentru cel rezident, cât și pentru cel din afară - precum și celor care intenționează [să facă] acolo[5] [o faptă de] deviere [în religie] sau nelegiuire - le vom da Noi să guste dintr-o pedeapsă dureroasă.', '[5] Fie că intenționează să facă rău în interiorul hotarelor sale sau intenționează din afară să facă rău în interior. Moscheea al Haram este unică deoarece numai planul de a face păcate acolo (indiferent dacă este pus sau nu în aplicare) este suficient pentru a aduce pedeapsa lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'Și [spune, o, Mohammed,] când Noi i-am arătat lui Avraam locul casei [Al- Ka’aba], [spunând]: „Nu-Mi aduce Mie pe nimeni ca asociat și purifică Casa Mea pentru cei care fac tauaf[6] și pentru cei care stau în picioare [rugându-se] și pentru cei ce se pleacă în supunere sau se prosternează!”', '[6] A se vedea 2:125');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, 'Și cheamă-i pe oameni la Hajj [Pelerinaj] și ei se vor îndrepta către tine pe jos și pe cămile slabe, venind pe toate drumurile din depărtări,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'Pentru ca ei să beneficieze [de răsplată în urma efectuării Pelerinajului] și pentru a pomeni Numele lui Allah în zile hotărâte asupra vitelor cu care El i-a înzestrat din animale [de sacrificat][7]. „Mâncați din ele și dați să mănânce și celui aflat în greutate și sărac”!', '[7] Al-An`am: cămile, vite, oi și capre');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Apoi să pună capăt celor ce le-au fost oprite lor, să-și împlinească legămintele lor și să înconjoare Casa cea străveche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, 'Așa [a fost poruncit], iar cel care cinstește lucrurile sacre ale lui Allah va avea parte de bine de la Domnul lui. Și vă sunt vouă îngăduite vitele, în afară de ceea ce v-a fost menționat[8]. Și feriți-vă voi de murdăria idolilor și feriți-vă de vorbele mincinoase.', '[8] A se vedea 5:3');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, '[Fiți] drepți în credința față de Allah, fără să-i faceți Lui asociați, căci cel care-I face lui Allah asociați este ca și cum ar cădea din Cer și l-ar înșfăca păsările sau l-ar arunca vântul într-un hău adânc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, 'Așa [este]! Iar cel care cinstește rânduielile lui Allah să știe că [aceasta] este din cuvioșia inimii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'Voi aveți foloase de la ele [de la vite] până la un termen hotărât[9]; apoi locul lor de sacrificare este lângă Casa cea străveche[10].', '[9] Pentru ca ele să fie mulse sau călărite (în cazul cămilelor) înainte de timpul lor de sacrificare
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'Și pentru fiecare națiune Noi am rânduit un ritual [de sacrificiu], pentru ca ei să pomenească Numele lui Allah asupra a ceea cu care El i-a înzestrat din animale [de sacrificiu]. Și Domnul vostru este un Domn Unic. Deci supuneți-vă Lui! Și [o, Mohammed,] binevestește celor care sunt umili [înaintea Domnului lor],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'Care, atunci când este pomenit Numele lui Allah, li se cutremură inimile, și celor care sunt răbdători cu ceea ce-i lovește și celor care împlinesc Rugăciunea [As-Salat] și celor care din cele cu care i-am înzestrat Noi fac milostenie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'Și [sacrificarea] cămilelor și a vitelor Noi am hotărât-o pentru a fi dintre rânduielile lui Allah. În ele se află bine pentru voi. Pomeniți Numele lui Allah asupra lor, când ele sunt pregătite [pentru sacrificare]. Apoi, când ele cad pe o parte [după sacrificare], luați pentru voi și dați să mănânce și celui nevoiaș [care nu cere] și celui care cere cu umilință. Astfel vi le-am supus Noi, pentru ca să fiți voi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'Nu vor ajunge la Allah carnea și sângele lor, ci va ajunge la El evlavia voastră. Astfel vi le-am supus vouă, pentru ca voi să-L preamăriți pe Allah, pentru că v-a călăuzit pe voi. Și binevestește celor care săvârșesc fapte bune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Cu adevărat, Allah îi apără pe cei care cred. Allah nu-i iubește pe cei haini și necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Li s-a permis [să lupte] celor care sunt atacați[11], căci ei sunt nedreptățiți. Și cu adevărat, Allah este în stare să-i ajute.', '[11] Făcându-se referire la companionii Profetului (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, '[Ei sunt] cei care au fost scoși din căminele lor pe nedrept, doar pentru că au spus: „Domnul nostru este Allah!” Și de nu i-ar opri Allah pe oameni, pe unii prin alții, ar fi dărâmate mănăstiri, biserici, sinagogi și moschei în care Numele lui Allah este pomenit atât de mult. Allah îi sprijină neîndoielnic pe cei care sprijină cauza Lui. Cu adevărat, Allah este Qauiyy [Tare] [și] ''Aziz [Puternic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'Aceștia [sunt] cei care - dacă Noi le dăm putere pe pământ - împlinesc Rugăciunea [As-Salat], achită Dania [Az-Zakat], poruncesc ceea ce este drept și opresc de la ceea ce este neîngăduit. Iar sfârșitul [tuturor lucrurilor] Îi aparține lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'Iar dacă ei te învinuiesc de minciună, [să știi că] și cei de dinaintea lor i-au socotit mincinoși [pe Trimișii lor] popoarele lui Noe, al lui ’Ad și al lui Thamud,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'Și poporul lui Avraam și poporul lui Lot', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'Și locuitorii din Madyan. Și Moise a fost socotit mincinos. Eu le-am dat un răgaz necredincioșilor, iar apoi i-am apucat [cu pedeapsă]. Și cât de aspră a fost Pedeapsa Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'Și câte cetăți am nimicit Noi pentru că ele erau nelegiuite. Iar ele sunt acum în ruină! Și câte fântâni părăsite! Și câte palate zidite [asemenea]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Dar oare n-au umblat ei prin lume și n-au avut ei inimi cu care să priceapă sau urechi cu care să audă? Cu adevărat, nu ochii lor sunt orbi, ci inimile din piepturi sunt oarbe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'Și ei te grăbesc [să vii] cu pedeapsa. Dar Allah nu-Și încalcă făgăduința Sa. Cu adevărat, o zi la Domnul tău este cât o mie de ani, după socoteala voastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'Și la câte cetăți nu le-am dat Eu răgaz, în vreme ce ele erau nelegiuite. Însă apoi le-am apucat Eu [cu pedeapsă]! Și la Mine este întoarcerea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, 'Spune: „O, voi oameni! Eu sunt pentru voi numai un prevenitor limpede.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'Și cei care cred și săvârșesc fapte bune vor avea parte de iertare și de câștig din belșug.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'Dar cei care se străduiesc să zădărnicească[12] Versetele Noastre vor fi oaspeții Iadului”.', '[12] Să le submineze credibilitatea și astfel să îl învingă pe Profet (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'N-am trimis Noi mai înainte de tine niciun Mesager și niciun Profet care să fi recitat [ceea ce i-a fost lui revelat], fără ca Șeitan să nu fi încercat să arunce [îndoială] în privința recitării sale. Însă Allah nimicește ceea ce Șeitan aruncă, apoi Allah întărește Versetele Sale, căci Allah este ‘Alim [Atoateștiutor], Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Și El face din ceea ce aruncă Șeitan o încercare pentru cei care au în inimi o boală[13] și ale căror inimi sunt neîndurătoare. Cei nelegiuiți sunt într-o dezbinare adâncă.', '[13] A se vedea 2:10');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, 'Și să știe cei cărora li s-a dăruit știința că el [Coranul] este Adevărul venit de la Domnul tău și să creadă în el și inimile lor să se supună lui. Cu adevărat, Allah este Călăuzitorul celor care cred pe calea cea dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'Dar cei care nu cred nu încetează să fie cu îndoială asupra lui până când Ceasul va veni peste ei pe neașteptate sau va veni peste ei pedeapsa unei Zile sterpe[14].', '[14] O Zi care nu va fi urmată de noapte și după care nu va veni o zi nouă, făcându-se referire la Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'Stăpânirea va fi în Ziua aceea a lui Allah, care va judeca între ei. Și cei care au crezut și au săvârșit fapte bune vor intra în Grădinile Plăcerii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'Dar cei care n-au crezut și au luat semnele Noastre drept minciună, vor avea parte de o pedeapsă umilitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Și cei care au purces, [părăsindu-și căminele] pentru Cauza lui Allah, iar după aceea au fost uciși sau au murit - Allah le va dărui o bună provizie [ca răsplată], căci Allah este Cel mai Bun dintre cei care dăruiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'El îi va lăsa să intre într-un loc pe care-l vor găsi plăcut, căci Allah este ''Alim [Atoateștiutor] [și] Halim [Blând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, 'Așa [este]! Iar pe acela care va pedepsi cu ceea ce a fost pedepsit, și apoi va fi nedreptățit, Allah îl va ajuta. Cu adevărat, Allah este ''Afuu [Îndurător], Ghafur [Iertător][15].', '[15] În ciuda abilității Sale de a se răzbuna. Acest Verset conține o sugestie ca și credincioșii să ierte la fel.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Aceasta pentru că Allah face să intre noaptea în zi și să intre ziua în noapte și pentru că Allah este Sami'' [Cel care Aude Totul] [și] Basir [Cel care Vede Totul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'Aceasta pentru că Allah este Adevărul, iar ceea ce cheamă ei în locul Său este deșertăciune și că Allah este Al-''Aliyy, [Cel mai Înalt] [și] Al-Kabir [Cel mai Mare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Oare nu vezi că Allah pogoară apă din Cer și Pământul devine înverzit? Allah este Latif [Cel Binevoitor] [și] Khabir [Bine Știutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'Ale Lui sunt cele din Ceruri și cele de pe Pământ. Cu adevărat, Allah este Al-Ghaniyy [Cel De ajuns pentru Sine] [și] Al-Hamid [Cel Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Oare nu vezi că Allah v-a supus vouă ceea ce este pe Pământ, iar corăbiile plutesc pe mare din Porunca Lui? El ține Cerul să nu cadă peste Pământ, decât cu Voia Sa. Allah este Ra''uf [Cel cu Milă] [și] Rahim [Îndurător cu oamenii].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'Și El este Cel care v-a dat viață, apoi vă dă vouă moarte, apoi vă va învia pe voi. Dar, cu adevărat, omul este nemulțumitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'Fiecărei comunități I-am hotărât Noi o rânduială pe care ea o urmează. Și să nu se certe cu tine despre acest lucru! Și cheamă la Domnul tău! Cu adevărat, tu ești pe o cale dreaptă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'Iar dacă se vor certa cu tine, spune: „Allah Știe mai bine ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Allah va judeca între voi în Ziua Învierii pentru cele asupra cărora sunteți cu păreri diferite.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Nu știi că Allah Cunoaște ceea ce este în Cer și pe Pământ? Acestea sunt într-o Carte[16]. Cu adevărat, acesta este pentru Allah [un lucru] ușor!', '[16] Tabla bine Păstrată (al-Lauh al-Mahfudh) care este la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'Ei adoră în locul lui Allah lucruri despre care nu s-a pogorât nicio dovadă și despre care ei nu au știință. Iar cei nelegiuiți nu vor avea ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'Și când li se recită lor Versetele Noastre cele limpezi, cunoști pe chipurile celor care nu cred neplăcerea [supărarea și furia]. De-abia se stăpânesc să nu se arunce asupra celor care le recită Versetele Noastre. Spune: „Să vă vestesc vouă ceva mai rău decât aceasta?[17] [Este] Focul pe care Allah l-a promis celor care nu cred. Și ce rea soartă!”', '[17] Mai rău decât furia pe care o simți împotriva celor care recită versetele lui Allah sau mai rău decât amenințările tale la adresa lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'O, voi oameni! Vi s-a dat vouă o pildă, ascultați-o. Cu adevărat, cei pe care voi îi chemați în locul lui Allah nu vor putea crea nici măcar o muscă, chiar dacă s-ar uni ei pentru aceasta. Iar dacă musca le răpește un lucru [mic], ei nu-l vor putea lua înapoi! Slabi sunt și cel care cere și cel de la care se cere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Ei nu L-au prețuit pe Allah după adevărata Sa măsură[18]. Allah este Qauiyy [Cel Tare], ''Aziz [Preaputernic]!', '[18] Nu I-au luat în considerare Atributele Sale Perfecte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Allah alege Trimiși dintre Îngeri și dintre oameni. Allah este Sami'' [Cel care Aude Totul] [și] Basir [Cel care Vede Totul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'El Știe ceea ce se află înaintea lor și ceea ce se află în urma lor[19] și la Allah se întorc [toate] lucrurile.', '[19] A se vedea 2:255');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'O, voi cei care credeți! Faceți plecăciuni, prosternați-vă și adorați-L pe Domnul vostru și faceți bine! Poate că voi veți izbândi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'Și luptați-vă pentru Allah cu toată osteneala pe care El o merită. El v-a ales pe voi și nu v-a impus în religie nicio greutate; ea este religia părintelui vostru Avraam. [Allah este] Cel care v-a numit pe voi musulmani atât mai înainte, cât și în această [Carte], pentru ca Trimisul să fie martor pentru voi și pentru ca voi să fiți martori pentru oameni. Împliniți Rugăciunea [As-Salat], achitați Dania [Az-Zakat] și legați-vă strâns de Allah, căci El este Stăpânul vostru! Ce minunat Stăpân și ce minunat Ocrotitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Cu adevărat, credincioșii vor avea izbândă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'Cei care în Rugăciunea lor sunt smeriți întru supunere', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'Și care rămân departe de vorbele deșarte', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'Și care achită Dania [Az-Zakat]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'Și care își păzesc castitatea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, 'În afară de soțiile lor și de ceea ce stăpânesc mâinile lor drepte[1], căci, cu adevărat, pentru aceasta ei nu sunt învinuiți', '[1] Femeile sclave sau captive aflate sub tutela lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'Dar cei care caută mai mult de atât sunt nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'Însă cei care sunt cu grijă față de cele care le-au fost încredințate și față de făgăduința lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'Și cei care veghează la Rugăciunea lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'Aceia sunt moștenitorii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'Cei care vor moșteni Firdausul[2], și ei în el vor sălășlui.', '[2] Partea cea mai înaltă a Paradisului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Noi l-am creat pe om din lut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'Apoi l-am făcut Noi o picătură[3] într-un loc sigur [uter],', '[3] Sau „un zigot”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'Apoi am făcut din picătură un cheag și am făcut din cheag o bucată de carne și am făcut din bucata de carne oase și am îmbrăcat oasele cu carne. Apoi l-am scos la iveală ca o altă făptură. Binecuvântat fie Allah, Făcătorul, Cel Bun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Apoi, după aceasta, voi cu siguranță veți muri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'Iar în Ziua Învierii, cu siguranță veți fi readuși la viață.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'Și Deasupra voastră am făcut Noi șapte straturi de Cer [unul deasupra celuilalt]. Și Noi nu suntem cu nebăgare de seamă față de făpturi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Și Noi am pogorât apă din Cer cu măsură și am făcut-o să stea în pământ. Cu adevărat, Noi avem Puterea să o facem să dispară.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'Și Noi v-am făcut vouă cu ajutorul ei grădini de curmali și vii, în care voi aveți roade multe și din ele voi mâncați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'Și [Noi v-am făcut vouă] un pom [măslin] ce crește pe Muntele Sinai care dă ulei și hrană pentru cei care mănâncă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'Și cu adevărat, în vite voi aveți un exemplu bun, căci vă dăm vouă să beți din ceea ce ele au în pântece și multe foloase aveți de la ele și de la ele mâncați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'Și pe ele și pe corăbii sunteți purtați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Noi l-am trimis pe Noe la poporul său și el a zis: „O, popor al meu! Adorați-L voi pe Allah! Voi nu aveți altă divinitate în afară de El. Oare nu vă temeți voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Dar căpeteniile poporului său, care nu au crezut au spus: „Acesta nu este decât un om asemenea vouă, care voiește să se ridice deasupra voastră. Dacă Allah ar fi Voit [să trimită un Mesager] ar fi făcut să coboare Îngeri. Noi n-am auzit aceasta de la străbunii noștri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Acesta nu este decât un bărbat atins de nebunie. Deci așteptați voi până la un timp!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, '[Noe] a spus: „Doamne, ajută-mă pe mine, fiindcă ei mă învinuiesc de minciună.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'Și i-am revelat Noi: „Fă-ți arca sub ochii Noștri și după revelația Noastră. Iar când va veni porunca Noastră și va clocoti cuptorul[4], atunci du pe ea din fiecare [specie] câte o pereche și familia ta, cu excepția celor asupra cărora s-a rostit cuvântul. Și nu vorbi cu Mine pentru cei care s-au purtat cu nelegiuire, căci ei vor fi înecați.', '[4] A se vedea 11:40');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Și după ce te vei îmbarca tu și cei care sunt cu tine, spune: „Mărire lui Allah, Care ne-a izbăvit pe noi de poporul de nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'Și spune: „Doamne, alege pentru mine un loc de coborâre binecuvântat, căci Tu ești Cel mai Bun dintre cei care ne-ar putea coborî în siguranță.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'Cu adevărat, întru aceasta sunt semne, și cu adevărat, Noi [îi] testăm [pe robii Noștri].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'Iar după ei am făcut Noi să se ivească mai apoi un alt popor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'Și le-am trimis lor un Mesager[5] dintre ei, [pentru ca el să le spună]: „Adorați-L pe Allah! Voi nu aveți altă divinitate afară de El! Oare voi nu vă temeți [de El]?”', '[5] Profetul Hud, care a fost trimis la neamul lui `Aad.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Însă căpeteniile poporului său care nu au crezut și au tăgăduit întâlnirea din Lumea de Apoi și pe care Noi le-am ținut în belșug în această lume au spus: „Acesta nu este decât un om ca și voi, care mănâncă ceea ce mâncați voi și bea ce beți voi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'Iar de veți da ascultare unui om asemenea vouă, atunci veți fi pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Vă promite el că după ce veți fi țărână și oseminte veți fi voi scoși [încă o dată]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Departe, foarte departe este ceea ce vi se făgăduiește[6].', '[6] Cât de departe și improbabil este');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'Nu este decât viața noastră lumească; noi murim și trăim și nu vom fi niciodată înviați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'El nu este decât un om care a născocit minciuna și a pus-o pe seama lui Allah și noi nu credem în el.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, 'El a spus: „Doamne, ajută-mă pe mine, căci ei mă cred mincinos.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, '[Allah a spus]: „În curând ei vor ajunge să se căiască.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'Și i-a cuprins pe ei strigătul[7] cu toată dreptatea, și Noi i-am făcut ca o spumă [purtată de un torent]. Așadar, departe cu neamul de nelegiuiți.', '[7] A se vedea 11:67');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'Apoi, am creat Noi, în urma lor, alte popoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'Nicio comunitate nu poate grăbi și nici întârzia termenul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Apoi Noi am trimis Mesagerii Noștri unul după altul. Și de fiecare dată când Mesagerul venea la comunitatea lui, ei îl considerau mincinos. Și Noi am făcut să se urmeze unii pe alții [către distrugere] și am făcut din ei povești pilduitoare[8]. Deci departe cu un popor care nu crede.', '[8] Istorie sau lecții pentru omenire');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'Apoi i-am trimis Noi pe Moise și pe fratele său Aaron, cu semnele Noastre și cu dovadă limpede', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, 'La Faraon și la dregătorii lui, însă aceștia s-au semețit, căci erau un neam de trufași', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Și ei au spus: „Să credem noi în doi oameni asemenea nouă, pe când cei din poporul lor sunt înrobiți la noi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'Și i-au socotit pe amândoi drept mincinoși, însă ei au fost nimiciți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Și, cu adevărat, Noi i-am dăruit lui Moise Cartea pentru ca ei[9] să fie călăuziți.', '[9] Fiii lui Israel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'Și am făcut Noi din fiul Mariei și din mama lui un semn și Noi le-am dat lor doi [adăpost] pe o colină statornică și cu izvor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, '[Allah a spus]: „O, Mesagerilor, mâncați din cele bune și fiți drepți. Cu adevărat, Eu sunt Bineștiutor a ceea ce săvârșiți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Și cu adevărat, această religie a voastră este una singură[10], iar Eu sunt Domnul vostru. Deci fiți cu frică de Mine.”', '[10] A se vedea 21:92');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'Însă ei și-au divizat religia, despărțindu-se în secte; fiecare sectă bucurându-se de ceea ce avea ea[11].', '[11] Credințe, păreri, obiceiuri etc.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Deci lasă-i în rătăcirea lor până la un timp.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Oare socotesc ei că ceea ce Noi le dăruim din bunuri și copii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'Sunt bunuri pe care Noi le dăm în grabă? Ba nu! Dar ei nu pricep[12].', '[12] Faptul că lucrurile bune primite în această viață sunt doar o încercare pentru ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Cu adevărat, cei care au teamă de Domnul lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'Și cei care cred în semnele Domnului lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'Și cei care nu-I fac asociați Domnului lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'Și cei care dau ce dau cu inimile pline de frică[13] [la gândul că] se vor întoarce la Domnul lor,', '[13] Cu frică ca ele să nu fie acceptate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'Aceia se grăbesc către faptele bune și ei se întrec în ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Noi nu impunem unui suflet decât atât cât este în puterea lui, iar Noi avem o carte ce rostește adevărul și ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Însă inimile lor sunt în rătăcire de la aceasta și ei au alte fapte [rele] pe care le săvârșesc în afară de aceasta [necredință],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'Până când Noi îi apucăm cu chinul[14] pe cei mai înstăriți dintre ei și atunci iată-i pe ei cum strigă [implorând]!', '[14] În viața lumească, înainte de pedepsirea din Viața de Apoi. Deși făcută în mod general, această descriere include în mod specific pedepsirea celor din Qurayș cu foamete.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, '„Nu strigați astăzi [implorând]. Cu adevărat, nu veți fi ajutați de Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'Versetele Mele v-au fost recitate vouă, însă voi v-ați întors pe călcâiele voastre,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'Fiind aroganți față de el[15], și le-ați hulit când ați stat la povești noaptea.”', '[15] Față de revelație sau față de Profet (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Nu cugetă ei la ceea ce este spus [Coran]? Și oare le-a venit lor ceea ce nu le-a venit strămoșilor lor cei dintru început?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Sau poate că ei nu-l cunosc pe Trimisul lor și de aceea se leapădă de el?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, 'Sau spun ei: „El este posedat!” Ba el le-a adus lor Adevărul, iar celor mai mulți dintre ei nu le place adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Și dacă Adevărul s-ar potrivi cu poftele lor, s-ar fi stricat Cerurile și Pământul, precum și toți cei care se află în ele. Însă Noi le-am adus Pomenirea lor [Coranul], dar ei de la Pomenire se întorc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Sau tu [o, Mohammed] ceri de la ei o răsplată? Dar răsplata Domnului tău este mai bună, iar El este Cel mai Bun dintre îngrijitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Cu adevărat, tu doar îi chemi către o cale dreaptă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'Dar cu adevărat, cei care nu cred în Viața de Apoi se abat de la această cale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'Dacă Ne-am fi îndurat de ei și am fi îndepărtat răul de la ei, s-ar fi îndârjit în nelegiuirea lor și ar fi rătăcit [mai departe în ea].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'I-am apucat Noi cu chin [drept avertizare], însă ei nu s-au supus Domnului lor și nici nu s-au rugat [Lui] cu umilință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'Până când le-am deschis Noi poarta către un chin aspru, iată-i pe ei acolo deznădăjduiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Și El este Cel care a creat pentru voi auzul, văzul și inimile. Însă voi sunteți atât de puțin mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'El este Cel care v-a răspândit pe voi pe Pământ și la El veți fi voi adunați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'El este Cel care dă viața și dă moarte și la El se află schimbarea nopții și zilei. Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Dimpotrivă, ei spun asemenea cum au zis și cei de mai înainte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Ei au spus: „Oare după ce vom muri și vom fi noi țărână și oseminte, vom mai fi noi aduși la viață din nou?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'Ni s-a făgăduit și nouă și părinților noștri, mai înainte, aceasta, însă acestea nu sunt decât legende ale înaintașilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'Spune [o, Mohammed]: „Cui îi aparțin Pământul și cei care se află pe el, dacă voi știți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, 'Ei vor spune: „Lui Allah!” Spune: „Oare voi nu voiți să luați aminte?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, 'Spune: „Și cine este Stăpânul celor șapte Ceruri și Stăpânul Tronului sublim?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, 'Ei vor spune: „[Ele sunt ale] lui Allah!” Spune: „Și atunci nu vă veți teme de El?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, 'Spune: „În Mâna cui se află stăpânirea tuturor lucrurilor și Cine apără și de Cine nu există apărare dacă știți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, 'Ei vor spune: „Ale lui Allah sunt [toate]!” Spune: „Și cum se face că sunteți voi fermecați?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Noi le-am adus lor Adevărul, însă ei sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Allah nu Și-a luat niciun copil și nu este nicio divinitate alături de El. [Dacă ar fi fost mai multe divinități], fiecare divinitate s-ar fi dus împreună cu ceea ce a creat și unii dintre ei ar fi încercat să fie deasupra celorlalți. Mărire lui Allah Care este mai Presus de tot ceea ce vorbesc ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, '[El este] Cunoscătorul tuturor celor nevăzute și văzute! Și El este mai Presus de ceea ce Îi aduc ei ca și parteneri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'Spune [o, Mohammed]: „Doamne, dacă Tu mă lași să văd ceea ce le este lor făgăduit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'Atunci nu mă așeza, Doamne, în neamul celor nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, 'Cu adevărat, Noi avem Puterea să-ți arătăm ceea ce le făgăduim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Respinge răul cu ceva care este mai bun! Noi știm prea bine ceea ce vorbesc ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'Și spune: „Doamne, eu caut scăpare la Tine împotriva ispitelor șeitanilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'Și eu caut scăpare la Tine, Doamne, pentru ca ei să nu se apropie de mine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, '[Căci astfel este starea necredincioșilor încât] abia când vine moartea la unul dintre ei, el spune: „Doamne, adu-mă pe mine înapoi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'Pentru ca eu să fac bine, în cele pe care le-am lăsat[16]!” Nu! Acesta este un cuvânt pe care el îl va rosti. Iar în urma lor este o despărțire [Barzakh], până în Ziua când vor fi sculați [din morți].', '[16] Sau „pe care le-am neglijat”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Iar când se va sufla în Trâmbiță, nu vor mai fi înrudiri între ei în Ziua aceea, nici nu se vor întreba unii pe alții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Și cei ale căror balanțe vor atârna mai greu [cu fapte bune], aceia vor fi cei fericiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'Iar cei ale căror balanțe vor atârna mai ușor, aceia sunt cei care și-au pierdut sufletele lor și ei în Iad vor avea sălaș veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'Focul le va arde fețele și buzele lor vor fi schimonosite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, '[Li se va spune]: „Oare nu vi s-au recitat vouă Versetele Mele, iar voi le-ați luat drept minciună?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, 'Ei vor spune: „Doamne, rătăcirea noastră ne-a învins și noi am fost un neam de oameni rătăciți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'Doamne, scoate-ne pe noi din el! Și dacă iarăși ne vom întoarce, atunci cu adevărat, noi suntem nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, 'El va spune: „Rămâneți în el umiliți și nu mai vorbiți cu Mine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Cu adevărat, a fost o parte dintre robii Mei care au spus: «Doamne, noi am crezut! Deci iartă-ne și îndură-Te de noi, căci Tu ești Cel mai Bun dintre cei îndurători!»', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Însă voi i-ați batjocorit, până ați uitat pomenirea Mea, și voi râdeați de ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Cu adevărat, Eu îi răsplătesc Astăzi pentru că ei au fost statornici, astfel încât ei să fie cei care izbândesc.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, '[Allah] va spune: „Câți ani ați rămas voi pe Pământ?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, 'Ei vor răspunde: „Am rămas o zi sau doar o parte dintr-o zi. Întreabă-i pe cei care țin numărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, 'El va spune: „Nu ați rămas voi decât puțin [timp]! Măcar dacă ați ști voi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, 'Atunci credeți voi că Noi v-am creat fără rost și că nu vă veți întoarce la Noi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'Preaînalt este Allah, Stăpânul adevărat! Nu există altă divinitate în afară de El, Stăpânul Tronului sublim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'Și cel care cheamă alături de Allah un alt dumnezeu, fără să aibă dovadă despre el, acela va da socoteală Domnului său. Iar necredincioșii nu vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, 'Și spune [o, Mohammed]: „Doamne, iartă și fii îndurător, căci Tu ești Cel mai Bun dintre cei îndurători.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, '[Aceasta este] o Sură pe care Noi am trimis-o și pe care Noi am făcut-o obligatorie și în care Noi am trimis Versete limpezi pentru ca voi să luați aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Pe femeia [necăsătorită] și pe bărbatul [necăsătorit] care preacurvesc[1], biciuiți-i pe fiecare cu câte o sută de lovituri. Și să nu vă apuce mila[2] de ei în împlinirea Legii lui Allah[3], dacă voi credeți în Allah și în Ziua de Apoi! Și un grup de dreptcredincioși să fie martori la pedepsirea lor!', '[1] Fie prin mărturisirea voluntară a celor vinovați, fie prin mărturisirea a patru martori bărbați care să fi văzut efectiv actul în desfășurare. Altfel, nu poate exista o sentință.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Cel care preacurvește nu se însoară decât cu o femeie care preacurvește sau cu o păgână, iar pe femeia care preacurvește nu o ia de nevastă decât un bărbat care preacurvește[4] sau un păgân. Acest lucru [căsătoria cu o astfel de persoană] le este oprit dreptcredincioșilor.', '[4] În această regulă sunt incluși și cei care fac adulter. Astfel de persoane nu se pot căsători cu dreptcredincioși decât dacă s-au căit și reformat.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Pe aceia care defăimează femei cinstite și apoi nu aduc patru martori, biciuiți-i cu optzeci de lovituri și nu mai primiți mărturie de la ei niciodată, căci ei sunt nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'În afară de cei care pe urmă se căiesc și se îndreaptă, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'Și cei care își acuză soțiile [de adulter] și nu au alți martori în afară de ei înșiși, fiecare dintre ei[5] trebuie să facă patru mărturii [cu jurământ] pe Allah că el este dintre cei care spun adevărul.', '[5] Soții care au fost trădați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, 'Și o a cincea [mărturie cu jurământ] ca blestemul lui Allah să cadă asupra lui, dacă el este dintre cei care mint.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'Însă pedeapsa va fi îndepărtată de la ea, dacă ea face patru mărturii [cu jurământ] pe Allah că el este dintre cei care mint.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, 'Și o a cincea [mărturie cu jurământ] ca mânia lui Allah să se abată asupra ei, dacă el este dintre cei care spun adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'Și dacă nu ar fi Grația lui Allah asupra voastră și Îndurarea Lui[6] și Allah este Tauuab [Iertător] [și] Hakim [Înțelept].', '[6] „...voi ați fi fost cu siguranță pedepsiți sau distruși,” sau „...voi ați fi trecut prin multe situații dificile.”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'Cu adevărat, cei care au venit cu minciuna[7] sunt un grup dintre voi. Nu o socotiți a fi un rău pentru voi, ci mai degrabă ea este un bine pentru voi. Fiecare om dintre ei are păcatul ce și l-a agonisit, iar aceluia căruia îi revine cea mai mare parte din ea[8] va avea parte de mare chin [Iad].', '[7] Făcându-se referire la incidentul când soția Profetului (pacea și binecuvântarea lui Allah fie asupra sa), Aișa a fost acuzată pe nedrept de ipocriți
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'De ce, atunci când ați auzit-o [această calomnie], nu au avut credincioșii și credincioasele o bănuială bună în sinea lor și de ce nu au spus: „Aceasta este o minciună învederată”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'De ce nu au adus ei [cei care au defăimat] patru martori pentru aceasta? Fiindcă ei nu au adus martori, aceștia în fața lui Allah sunt niște mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'Și dacă nu ar fi fost Grația lui Allah asupra voastră și Îndurarea Lui, atât în această lume, cât și în Lumea de Apoi, v-ar fi ajuns pe voi un chin mare pentru ceea ce ați vorbit voi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'Căci l-ați primit cu limbile voastre[9] și ați spus cu gurile voastre lucrul despre care nu aveți nicio știință și l-ați ținut drept [lucru] ușor, când – de fapt – el este la Allah [un lucru] greu.', '[9] Și nu cu urechile voastre, fără să vă gândiți la ceea ce ați auzit, ci grăbindu-vă să le repetați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Și de ce, când ați auzit-o, n-ați spus voi: „Nu se cuvine să vorbim despre aceasta! Mărire Ție! Aceasta este o mare clevetire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Allah vă îndeamnă să nu vă mai întoarceți la una ca aceasta niciodată, dacă sunteți dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'Și Allah vă deslușește vouă Versetele, iar Allah este ''Alim [Bineștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'Aceia care vor ca printre dreptcredincioși să se răspândească ticăloșia vor avea parte de osândă dureroasă atât în această lume, cât și în Lumea de Apoi. Allah Știe, în vreme ce voi nu știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'Și de n-ar fi Grația lui Allah asupra voastră și Mila Lui și [faptul] că Allah este Ra''uf [Cel cu Milă], Rahim [Îndurător], [voi ați fi aspru pedepsiți].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'O, voi cei care credeți! Nu urmați pașii lui Șeitan! Aceluia care urmează pașii lui Șeitan el îi poruncește ticăloșia și lucrul oprit. Și de nu ar fi Grația lui Allah asupra voastră și Mila Sa, nici unul dintre voi nu ar fi curat nicicând. Însă Allah curățește pe cine Voiește El. Iar Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Să nu jure cei înzestrați cu belșug și cu bogăție dintre voi că ei nu vor mai da [nimic] rudelor, sărmanilor și celor care purced pe calea lui Allah! Ci să ierte și să treacă cu vederea. Oare nu voiți voi ca Allah să vă ierte vouă? Iar Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Aceia care defăimează femei evlavioase, preacurate și dreptcredincioase vor fi blestemați atât în această viață, cât și în Viața de Apoi și vor avea parte de chin mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'Într-o zi, limbile, mâinile și picioarele lor vor face mărturie împotriva lor pentru ceea ce ei au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'În Ziua aceea, Allah îi va răsplăti după cuviință cu răsplata lor cea dreaptă și vor ști ei că Allah este Al-Haqq [Adevărul] cel limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, '[Cuvintele, faptele sau femeile] cele rele sunt pentru [oamenii] cei răi, iar cei răi sunt pentru [cuvintele, faptele sau femeile] cele rele, după cum cele bune sunt pentru cei buni, iar cei buni sunt pentru cele bune. Aceia vor fi nevinovați cu privire la ceea ce spun alții despre ei. Ei au iertare și câștig ales.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'O, voi cei care credeți! Nu intrați în alte case afară de casele voastre, înainte de a cere îngăduința și a-i saluta[10] pe sălășluitorii lor! Aceasta este mai bine pentru voi. Poate că voi veți lua aminte!', '[10] Cu salutul „Assalamu alaikum” („Pacea fie asupra voastră”)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'Iar dacă nu găsiți pe nimeni în ele, nu intrați până ce nu vi se îngăduie vouă. Iar dacă vi se spune vouă „Întoarceți-vă!”, atunci întoarceți-vă. Aceasta este mai curat pentru voi, iar Allah este ''Alim [Bineștiutor] a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Nu este niciun păcat dacă intrați în case nelocuite, în care se află un bine pentru voi[11]. Iar Allah Știe atât ceea ce faceți voi pe față, cât și ceea ce țineți voi ascuns.', '[11] Unele beneficii precum odihnă, adăpost, comodități, bunurile persoanele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'Spune dreptcredincioșilor să-și plece privirile[12] și să-și păzească pudoarea lor[13]. Aceasta este mai curat pentru ei. Allah, doară, este Khabir [Bineștiutor] a ceea ce fac ei.', '[12] Să se uite doar la ceea ce este permis și să își îndepărteze privirea de ceea ce nu este permis
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'Și spune dreptcredincioaselor să-și plece privirile[14] și să-și păzească pudoarea lor, să nu-și arate gătelile lor[15], afară de ceea ce este pe dinafară[16], și să-și coboare [parte din] vălurile lor peste piepturile lor! Și să nu-și arate frumusețea lor decât înaintea soților, sau a părinților lor, sau a părinților soților lor, sau a fiilor lor, sau a fiilor soților lor, sau a fraților lor, sau a fiilor fraților lor, sau a fiilor surorilor lor, sau a femeilor lor, sau a acelora pe care le stăpânesc mâinile lor drepte, sau a slujitorilor dintre bărbați, care nu mai au dorință, sau a copiilor mici care nu știu ce este goliciunea femeilor. Și să nu lovească cu picioarele lor, astfel încât să se afle ce podoabe ascund ele! Și căiți-vă cu toții, o, voi dreptcredincioșilor, față de Allah, pentru ca voi să izbândiți!', '[14] Să se uite doar la ceea ce este permis și să își îndepărteze privirea de la ceea ce nu este permis
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Căsătoriți-i pe cei care sunt singuri dintre voi, precum și pe cei virtuoși dintre robii și roabele voastre. Dacă ei sunt săraci, Allah îi va face bogați prin mare Mila Sa, căci Allah este Uasi'' [Cel cu Har Nemărginit] [și] ''Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'Iar cei care nu află [cele de trebuință] pentru căsătorie să se abțină [de la relațiile sexuale] până ce Allah îi va îmbogăți pe ei din mare Mila Sa. Cu aceia dintre cei pe care îi stăpânesc mâinile voastre drepte care caută un contract [de eliberare din sclavie] încheiați voi acest contract, dacă voi știți că ei sunt buni, și dăruiți-le lor din binecuvântările lui Allah pe care El vi le-a dat vouă. Și nu le siliți pe sclavele voastre la prostituție [acest lucru fiind un păcat], dacă ele vor să rămână curate, căutând un profit trecător în această viață lumească. Iar dacă cineva le silește, Allah - chiar și după silirea lor este Ghafur [Iertător], Rahim [Îndurător][păcatul va fi asupra celor care le-a silit].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Și Noi v-am trimis vouă Versete clare[17] și exemple de la cei care s-au petrecut mai înainte de voi și îndemn pentru cei care au frică [de Allah].', '[17] Reguli și prescripții, în special în acest Capitol');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Allah este Lumina[18] Cerurilor și a Pământului. Lumina Lui[19] seamănă cu o firidă în care se află o lampă[20]. Lampa este într-un vas de cristal, iar acesta pare a fi o stea scânteietoare. Ea se aprinde de la un pom binecuvântat, un măslin, nici de la răsărit, nici de la apus, al cărui ulei aproape că luminează fără să-l fi atins focul. Lumină peste lumină! Allah călăuzește către Lumina Sa pe cine Voiește El și Allah dă oamenilor pilde. Iar Allah le Știe pe toate.', '[18] Sursa și Dătătorul de lumină și cunoaștere
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'În case [moschei] pe care le-a poruncit Allah să fie înălțate și în ele să fie pomenit Numele Său. În ele Îl preamăresc pe El dimineața și seara', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, '[Sunt] bărbați pe care nici negoțul, nici marfa nu-i împiedică de la pomenirea lui Allah, de la împlinirea Rugăciunii [As-Salat] și de la achitarea Daniei [Az-Zakat], care se tem de o Zi când inimile și privirile vor fi tulburate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, '[Ei fac astfel] pentru ca Allah să le răsplătească faptele cele mai frumoase pe care le-au săvârșit și să le înmulțească din Harul Său, căci Allah îi dăruiește fără socoteală [limită] aceluia care Voiește El.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'Cât despre faptele celor care nu cred, ele sunt ca o nălucire într-un pustiu întins, pe care cel însetat îl ia drept apă, dar când ajunge la el, nu găsește nimic. Însă el Îl găsește acolo pe Allah, care îi va plăti lui în întregime căci Allah este grabnic la socoteală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'Sau [ele sunt] ca întunecimile dintr-o mare adâncă, fără fund, pe care o învăluie valurile, iar peste ele alte valuri și deasupra lor norii. Întunecimi unele deasupra altora. Dacă [cineva] scoate mâna, aproape că nici nu o vede. Iar acela căruia Allah nu-i dă lumină nu va avea nicio lumină.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'N-ai văzut tu că pe Allah Îl preamăresc toți cei din Ceruri și de pe Pământ, ca și păsările care-și întind aripile [în zborul lor]? Fiecare știe rugăciunea sa și lauda sa. Iar Allah este ''Alim [Bineștiutor] a ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'Și a lui Allah este împărăția Cerurilor și a Pământului și la Allah este întoarcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Nu ai văzut tu că Allah mână Norii? Apoi îi aduce împreună, apoi îi face grămadă și apoi vezi tu ploaia ivindu-se din ei. Și El face să coboare din Cer, din munți de gheață, grindină și lovește cu ea pe cine Voiește El și o îndepărtează de la cine Voiește El. Iar scânteia fulgerului său aproape că răpește vederea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Allah face să se schimbe noaptea și ziua. Cu adevărat, întru aceasta este o pildă pentru cei care văd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Allah a creat toate vietățile din apă și unele dintre ele merg pe burtă, altele merg pe două picioare și altele merg pe patru [picioare]. Allah creează ceea ce Voiește El și Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Noi am pogorât Versete deslușite și Allah călăuzește pe cine Voiește El pe o cale dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, 'Dar ei [ipocriții] spun: „Noi credem în Allah și în Trimis și ne supunem”. Apoi se întorc o parte dintre ei, după aceasta, și aceștia nu sunt credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Iar când sunt chemați la [Cuvintele lui] Allah și la Trimisul Său pentru a judeca între ei, iată că o parte dintre ei se îndepărtează.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'Iar dacă ei ar avea dreptatea de partea lor, ar veni spre el supuși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Oare în inimile lor este o boală? Sau se îndoiesc ei? Sau se tem că Allah și Trimisul Său vor fi nedrepți cu ei? Dimpotrivă, aceștia sunt nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Singurele vorbe ale dreptcredincioșilor [adevărați], atunci când ei sunt chemați la Allah și la Trimisul Său pentru a judeca între ei, sunt că ei trebuie să zică: „Am auzit și ne-am supus.” Aceștia vor fi cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Cei care se supun lui Allah și Trimisului Său, se tem de Allah și sunt cu frică de El, aceia vor fi izbânditori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Ei jură pe Allah cu jurăminte grele că, dacă le vei porunci, vor ieși. Spune: „Nu jurați! Supunerea este mai potrivită! Allah este Khabir [Bineștiutor] a ceea ce faceți voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'Spune: „Supuneți-vă lui Allah și supuneți-vă Trimisului Său!” Dacă ei se întorc, el răspunde doar pentru cele cu care a fost însărcinat, iar vouă vă revine răspunderea pentru cele cu care ați fost însărcinați. Iar de vă veți supune lui, veți fi călăuziți. Și nu-i revine Trimisului decât transmiterea limpede [a Mesajului].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Allah le-a făgăduit acelora dintre voi care au crezut și au săvârșit fapte bune să-i facă pe ei stăpâni pe pământ, așa cum i-a făcut stăpâni și pe cei de dinaintea lor, și să dea forță religiei lor, pe care El a acceptat-o pentru ei și să le schimbe teama lor cu siguranța. Pentru că ei Mă adoră pe Mine și nu-Mi fac Mie ca asociați nimic. Și cei care vor mai fi necredincioși[21] după aceasta, aceia sunt nelegiuiți.', '[21] Neagă favoarea lui Allah sau nu trăiește după prescripțiile Lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'Împliniți Rugăciunea [As-Salat], achitați Dania [Az-Zakat] și supuneți-vă Trimisului; poate că voi veți avea parte de îndurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, 'Să nu socotești tu că cei care nu cred vor fi în stare să scape de pedeapsa lui Allah pe pământ! Sălașul lor va fi Focul. Și ce rea soartă [vor avea ei]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'O, voi cei care credeți! Să vă ceară îngăduință [să intre] cei pe care îi stăpânesc mâinile voastre drepte, precum și aceia dintre voi care nu au ajuns pubertatea, în cele trei ocazii: înainte de Rugăciunea [As-Salat] din zori, când vă scoateți veșmintele voastre la amiază [pentru odihnă] și după Rugăciunea [As-Salat] de seară – [acestea sunt] cele trei momente când vă dezbrăcați. În afară de acestea, nu este niciun păcat nici pentru voi, nici pentru ei de a pleca și de a veni unii la alții. Astfel vă tâlcuiește Allah Versetele Sale, iar Allah este ''Alim [Bineștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'Dar când au ajuns copiii voștri la pubertate, să ceară îngăduință, așa cum au cerut cei de dinaintea lor. Astfel vă tâlcuiește Allah Versetele Sale, iar Allah este ''Alim [Bineștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'Cât despre femeile ajunse de bătrânețe, care nu mai nădăjduiesc la căsătorie, nu este niciun păcat dacă ele își scot vălurile, însă fără să-și arate podoabele. Dar dacă se rețin e și mai bine pentru ele. Și Allah este Sami'' [Cel care Aude Totul] [și] ''Alim [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, 'Nu este niciun păcat pentru cel orb, nu este păcat nici pentru cel șchiop, nu este păcat nici pentru cel bolnav și nici pentru voi dacă mâncați din casele voastre, sau din casele părinților voștri, sau din casele mamelor voastre, sau din casele fraților voștri, sau din casele surorilor voastre, sau din casele unchilor voștri dinspre tată, sau din casele mătușilor voastre dinspre tată, sau din casele unchilor voștri dinspre mamă, sau din casele mătușilor voastre dinspre mamă, sau din acelea de la care aveți chei, sau ale prietenului vostru. Nu este păcat să mâncați fie împreună, fie separat. Iar când intrați în case, salutați-vă unii pe alții cu un salut binecuvântat[22] și bun de la Allah! Astfel vă tâlcuiește Allah Versetele, pentru ca voi să pricepeți.', '[22] Spunând „Assalamu alaikum” („Pacea fie asupra voastră”)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'Dreptcredincioșii [adevărați] sunt cei care cred în Allah și în Trimisul Său, iar dacă sunt împreună cu el pentru o chestiune de interes comun, nu pleacă înainte de a-i cere lui îngăduință. Aceia care-ți cer îngăduință, aceia sunt cei care cred în Allah și în Trimisul Său. Iar dacă-ți cer îngăduință pentru vreo treabă de-a lor, îngăduie cui voiești dintre ei și roagă-te de iertare pentru ei la Allah, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Nu faceți chemarea Trimisului între voi ca pe o chemare a unuia dintre voi către altul! Allah îi Cunoaște pe aceia dintre voi care se furișează, căutând adăpost [la alții]. Cei care se furișează după alții și fug de porunca lui [a Profetului] să se ferească să nu-i lovească pe ei o nenorocire sau să nu-i lovească pe ei o pedeapsă dureroasă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Ale lui Allah sunt cele din Ceruri și de pe Pământ. El Știe bine starea în care sunteți voi[23]. Iar în Ziua când ei vor fi aduși la El, îi va înștiința pe ei, despre cele pe care le-au săvârșit, căci Allah le Știe pe toate.', '[23] Dacă credința voastră este sinceră sau voi sunteți ipocriți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Binecuvântat este Cel care a trimis Îndreptarul [Al-Furqan] robului Său, pentru ca el să fie o prevenire pentru toate lumile,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, 'Celui Căruia Îi aparține Împărăția Cerurilor și a Pământului, Care nu Și-a atribuit un fiu și nu are asociat la Împărăție și a creat toate lucrurile și le-a orânduit cu bună rânduială.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'Ei au luat în locul Lui dumnezei care nu creează nimic, ci care ei sunt creați, care nu-și pot aduce lor înșiși nici rău și nici folos, și care nu au putere asupra morții, nici asupra vieții sau a Învierii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Cei care nu cred spun: „Acesta [Coranul] nu este decât o minciună pe care el a născocit-o și în care l-a ajutat și un alt neam.” Însă ei aduc nedreptate și minciună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, 'Și ei spun: „Legende ale înaintașilor sunt cele pe care el le-a scris și ele îi sunt dictate lui dimineața și seara”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, 'Spune [o, Mohammed]: „L-a pogorât Cel care știe taina din Ceruri și de pe Pământ. El este Ghafur [Iertător], Rahim [Îndurător]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'Și ei spun: „Ce este cu acest Trimis, care mănâncă bucate și merge prin târguri? De ce nu este trimis la el un înger care să fie împreună cu el ca prevenitor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, 'Sau să i se aducă lui o comoară [din Cer] sau să aibă el o grădină din care să mănânce!” Și cei nelegiuiți spun: „Voi nu urmați decât un bărbat fermecat!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Privește cum îți dau ei pilde[1], dar ei sunt rătăciți și nu vor mai putea să afle calea.', '[1] Din propria imaginație pentru a te nega sau pentru a te discredita');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Binecuvântat este Cel care, dacă Voiește, îți dăruiește ție [lucruri] mai bune decât acesta: grădini pe sub care curg pâraie, și-ți va da și palate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Ei au socotit Ceasul drept minciună, însă Noi am pregătit vâlvătăile pentru cei care tăgăduiesc Ceasul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Dacă li se arată dintr-un loc depărtat [Iadul], ei îi aud furia și trosnetul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'Și când ei vor fi aruncați într-un loc îngust din el, legați la un loc, vor chema atunci pieirea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, '[Li se va spune]: „Astăzi nu vă rugați voi pentru o singură pieire, ci rugați-vă pentru mai multe pieiri!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, 'Spune: „Oare aceasta este mai bine sau Grădina veșniciei care le-a fost făgăduită celor cu frică? Aceasta le va fi răsplată și loc de sosire [necurmat]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'Ei vor avea în ea ceea ce doresc și veșnic vor sălășlui acolo. Aceasta este o promisiune făcută de Domnul tău și care trebuie îndeplinită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'Și [spune] de Ziua în care îi va aduna împreună cu ceea ce ei adoră alături de Allah, și le va spune: „Voi i-ați dus în rătăcire pe robii Mei ori ei au pierdut singuri drumul?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, 'Ei vor spune: „Mărire Ție! Nu se cade să luăm noi alți aliați afară de Tine, însă Tu le-ai dat lor și părinților lor atâtea plăceri încât ei au uitat de pomenire și au devenit ei un popor pierdut”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Și ei [necredincioșii] vă socotesc mincinoși [și acum] pentru ceea ce spuneți[2]. Și nu veți fi voi în stare nici de scăpare, nici de ajutor. Iar aceluia dintre voi care nelegiuiește, îi vom da Noi să guste chin mare”.', '[2] La timpul Judecății obiectele false de adorare îi vor trăda și nega pe adoratorii lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Și Noi nu am trimis mai înainte de tine [o, Mohammed] decât Trimiși care au mâncat bucate și au umblat prin piețe. Și Noi v-am făcut pe unii dintre voi încercare pentru alții, veți fi voi [statornici și] răbdători? Iar Domnul tău este Atoatevăzător [a ceea ce fac ei].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Cei care nu nădăjduiesc în întâlnirea cu Noi spun: „De ce nu ni s-ar trimite nouă Îngeri sau de ce nu Îl putem vedea pe Domnul nostru? Cu adevărat ei au devenit prea trufași și se poartă cu semeție mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Iar în Ziua în care ei îi vor vedea pe Îngeri[3], nu va fi veste bună atunci pentru nelegiuiți și vor zice [Îngerii]: „Victoria vă este interzisă [vouă tuturor]!”', '[3] În momentul morții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'Și vom preschimba faptele pe care ei le-au făcut[4] în țărână risipită.', '[4] În Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Oaspeții Raiului vor fi în Ziua aceea într-un loc mai bun și într-un loc de odihnă mai frumos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'Și [spune] de Ziua când Cerul se va despica și se vor ivi nori[5] și vor fi pogorâți Îngerii în cete.', '[5] În care se află Îngeri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'În Ziua aceea Stăpânirea cea adevărată va fi a Celui Milostiv și ea va fi o Zi grea pentru necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'În Ziua aceea nelegiuitul își va mușca mâinile [în semn de regret] și va spune: „Ce bine ar fi fost, dacă aș fi urmat calea cu Trimisul[6].', '[6] „dacă l-aș fi urmat pe Profet pe calea călăuzirii”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, 'Vai mie! Ce bine ar fi fost dacă nu l-aș fi luat pe cutare[7] ca prieten!', '[7] Persoana care l-a dus pe o cale greșită');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'El m-a dus pe mine în rătăcire de la îndemnare[8] după ce ea a venit la mine. Șeitan este hain cu omul, [după ce l-a ispitit].”[9]', '[8] De la Coran sau de la pomenirea lui Allah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Și Trimisul spune: „Doamne, cu adevărat, poporul meu a luat Coranul [drept un lucru] părăsit!”[10]', '[10] Îl evită, nu îl ascultă și nici nu îl înțeleg, nu trăiesc în conformitate cu el sau preferă altceva');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Și astfel i-am dat Noi fiecărui Profet un dușman dintre nelegiuiți. Însă Domnul tău îți este de ajuns ca ocârmuitor și ca ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Și cei care nu cred spun: „De ce nu i-a fost trimis Coranul dintr-o singură dată?” Așa a fost pentru ca Noi să întărim cu el inima ta și Noi l-am revelat treptat și cu grijă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Și ei nu-ți vor aduce niciun argument, fără ca Noi să venim cu Adevărul și cu cea mai frumoasă tâlcuire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, 'Aceia care vor fi târâți pe fețele lor către Iad, aceia au locul cel mai rău și ei sunt rătăciți de la drum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Și i-am dat Noi lui Moise Cartea și i l-am făcut pe fratele său Aaron sfetnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, 'Și Noi am spus: „Mergeți voi doi la poporul celor care au ținut semnele Noastre de minciuni.” Și i-am nimicit pe ei cu desăvârșire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'Și pe cei din poporul lui Noe care i-au socotit pe Trimiși[11] mincinoși i-am înecat Noi și i-am făcut pe ei un semn pentru oameni. Și Noi am pregătit pentru cei nelegiuiți osândă dureroasă.', '[11] Prin faptul că l-au considerat pe Profet mincinos, aceștia i-au considerat mincinoși pe toți cei care au adus același mesaj de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, 'Și [Noi am distrus] popoarele lui ’Ad și Thamud și pe oamenii din Ar-Rass și multe alte popoare între acestea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'La toți le-am dat noi exemple [avertizări] și pe toți i-am nimicit cu desăvârșire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'Și ei au trecut pe lângă cetatea peste care a căzut ploaia nenorocirii [cu pietre]. Oare nu au văzut-o ei? Însă ei nu nădăjduiesc în Înviere[12].', '[12] Și nu iau exemplul celor din trecut');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Iar când te văd [o, Mohammed], ei nu te iau decât în derâdere [spunând]: „Acesta este cel pe care l-a trimis Allah ca Mesager?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, 'Puțin a lipsit să ne ducă pe noi în rătăcire de la zeii noștri, dacă noi nu ne-am fi ținut de ei cu statornicie.” Însă ei vor ști, când vor vedea chinul, cine este mai rătăcit de la drum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Nu-l vezi pe cel care și-a luat pofta lui drept divinitate pentru el? Tu vrei să fii chezaș pentru acesta?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Sau crezi tu că cei mai mulți dintre ei aud sau pricep? Ei nu sunt decât asemenea vitelor[13], ba ei sunt chiar și mai rătăciți de la drum!', '[13] Vite sau oi care merg unde li se spune fără a pune întrebări');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Nu L-ai văzut pe Domnul tău cum a întins umbra? Și dacă ar fi Voit El, ar fi lăsat-o nemișcată. Apoi am făcut Soarele dovadă pentru ea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'Apoi o tragem către Noi ușor[14].', '[14] Când Soarele este deasupra la prânz');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'El este Cel care v-a făcut noaptea ca veșmânt și somnul spre odihnă și v-a făcut ziua ca o înviere[15].', '[15] Pentru reînnoirea vieții și activității');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'Și El este Acela care trimite vântul ca bună vestire înaintea Îndurării Sale. Și Noi trimitem din Cer apă curățitoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'Ca să înviem cu ea un ținut mort și să dăm să bea din ea celor pe care le-am creat - vite și oameni în număr mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'Noi am răspândit-o printre ei, pentru ca ei să-și aducă aminte[16], însă cei mai mulți oameni au ales să nu fie altfel, decât nerecunoscători.', '[16] De abilitatea lui Allah de a aduce morții la viață');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Însă dacă Noi am fi Voit, am fi trimis în fiecare cetate câte un prevenitor[17].', '[17] Însă, Allah a Voit ca profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) să fie trimis ca ultimul Mesager pentru toți oamenii de pe Pământ până în Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Nu da ascultare necredincioșilor și trudește împotriva lor cu el [Coranul], cu mare silință!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'El este Cel care a lăsat să curgă liber cele două mări - una plăcută și dulce și una sărată și amară - și a făcut între ele un perete și un baraj de netrecut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'El este Cel care i-a creat pe oameni din apă și i-a legat prin obârșie și prin căsătorie. Iar Domnul tău este Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'Dar ei adoră în afară de Allah ceea ce nu le este nici spre folos și nici nu le strică. Și cel necredincios este împotriva Domnului său un ajutor [ai lui Șeitan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'Și Noi nu te-am trimis [o, Mohammed] decât ca binevestitor și ca prevenitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'Spune: „Eu nu vă cer o răsplată pentru el, ci numai acela care voiește să ia o cale către Domnul său.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Și încrede-te în Cel Veșnic Viu, care nu moare niciodată, și înalță-I Lui laudă! El este Bineștiutor al păcatelor robilor Săi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'El este Cel care a creat Cerurile și Pământul și ceea ce este între ele în șase zile, iar apoi s-a înălțat deasupra Tronului, Cel Milostiv. Întreabă despre aceasta pe cineva bine știutor [profetul Mohammed].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'Și dacă li se spune lor: „Prosternați-vă dinaintea Celui Milostiv”, ei răspund: „Și ce este Cel Milostiv? Să ne prosternăm noi la ceea ce ne poruncești tu?” Și aceasta sporește înverșunarea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Binecuvântat este Cel ce a pus Stelele mărețe în Cer și a făcut în el o candelă arzătoare [Soarele] și o Lună luminoasă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'Și El este Cel care a făcut ca noaptea și ziua să urmeze una după alta, pentru acela care voiește să ia aminte sau voiește să-și arate mulțumirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'Robii Celui Milostiv sunt cei care merg pe Pământ cu smerenie[18], iar atunci când cei neștiutori le vorbesc lor [cu asprime], ei le răspund: [cu blândețe și prin cuvinte de] „Pace!”', '[18] Cu demnitate și fără ignoranță');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'Și cei care petrec noaptea [parte din ea] prosternându-se și stând în picioare [rugându-se] dinaintea Domnului lor;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'Și cei care spun: „Doamne, ține departe de noi chinul Iadului, căci chinul lui este pieire veșnică', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'Ce locuință rea și ce rău loc de ședere este ea.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'Și cei care, atunci când cheltuiesc, nu sunt nici risipitori nici zgârciți, ci fac aceasta cu măsură', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'Și cei care nu cheamă un alt dumnezeu împreună cu Allah și nu ucid sufletul pe care l-a oprit Allah [să fie omorât], decât pe drept, și aceia care nu preacurvesc - căci acela care face aceasta va afla pedeapsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Și va fi sporit chinul lui în Ziua Învierii și în veci va rămâne în ea disprețuit -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'În afară de cel care se căiește, crede și săvârșește fapte bune; acestora le va schimba Allah faptele rele cu fapte bune, căci Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'Iar cel care se căiește și săvârșește fapte bune se întoarce la Allah ispășit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, 'Și cei care nu fac mărturie mincinoasă și dacă trec pe lângă clevetiri, trec cu vrednicie;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'Și cei care atunci când le sunt pomenite semnele Domnului lor, nu se apleacă asupra lor surzi și orbi;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'Și cei care spun: „Doamne, dă-ne nouă de la soațele noastre și de la vlăstarele noastre mângâiere pentru ochi[19] și fă din noi bune exemple pentru cei evlavioși!”;', '[19] O sursă de fericire datorită cuvioșenii lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Aceia sunt cei care vor avea drept răsplată cel mai înalt loc [din Paradis] pentru că au fost statornici și vor fi întâmpinați în el cu salut și cu pace [cuvinte de respect]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'Și în el vor rămâne veșnic. Ce frumoasă locuință și ce frumos loc de ședere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'Spune [o, Mohammed, necredincioșilor]: „Nu vă dă nicio atenție Domnul meu, dacă voi nu vă rugați Lui! Însă voi ați socotit mincinoasă [Religia Sa] și [pedeapsa voastră] va fi [nesfârșită și] de nedespărțit!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Ta’, Sin, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Acestea sunt Versetele Cărții celei limpezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, 'Poate că tu [Mohammed] te sfârșești de supărare, pentru că ei nu sunt credincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Dar de am Voi, am face Noi să coboare din Cer peste ei un semn și atunci ar rămâne gâturile lor [aplecate] de umilință[2].', '[2] Ar fi obligate să creadă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'Și nu le vine lor nicio îndemnare nouă de la Cel Milostiv, fără ca ei să se întoarcă de la ea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Ei au luat drept minciună [tot ceea ce le-a trimis Domnul lor], însă le vor veni lor vești despre cele de care și-au bătut joc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Nu privesc ei la Pământ, cum am făcut Noi să crească din fiecare soi nobil?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'Cu adevărat, întru aceasta este semn! Dar cei mai mulți dintre ei nu sunt credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'Și [spune] când l-a chemat Domnul tău pe Moise, [spunându-i]: „Du-te tu la poporul celor nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, 'Poporul lui Faraon. Oare nu au ei frică?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, 'Și el a spus: „Doamne, mă tem că mă vor socoti mincinos', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, 'Și că pieptul meu se va strânge și că limba mea nu-și va da drumul. Deci trimite după Aaron.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'Ei mă învinuiesc de un păcat și mă tem să nu mă omoare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, '[Allah] a spus: „Nicidecum! Mergeți amândoi cu semnele Noastre. Cu adevărat, Noi suntem cu voi și Auzim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, 'Mergeți, așadar, la Faraon și spuneți-i: „Noi suntem Trimișii Stăpânului lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, '[Și am primit poruncă să spunem] „Trimite-i pe Fiii lui Israel împreună cu noi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, '[Faraon] a spus: „Nu te-am crescut printre noi când erai tu un prunc? Și nu ai rămas tu printre noi din viața ta ani [la rând]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'Și [apoi] ai săvârșit tu fapta[3] pe care ai săvârșit-o. Iar acum tu ești dintre cei nerecunoscători!”', '[3] Lovindu-l pe Copt, care a murit apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, '[Moise] a spus: „Am săvârșit-o când eu eram printre cei rătăciți [ignoranți]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, 'Și am fugit de la voi, pentru că mi-a fost teamă de voi, însă Domnul meu mi-a dat înțelepciune și m-a făcut pe mine [unul] dintre Trimiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'Și este aceasta pe care o pomenești o favoare făcută mie [lăsându-mă liber] – iar tu i-ai înrobit pe Fiii lui Israel?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, 'A întrebat Faraon: „Și ce este Stăpânul lumilor”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, '[Moise] a spus: „Este Stăpânul Cerurilor și a Pământului și al celor care se află între ele, dacă voi ați putea să fiți convinși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, '[Faraon] le-a spus celor din jurul său: „Voi nu auziți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, '[Moise] a spus: „Stăpânul vostru și Stăpânul părinților voștri cei dintâi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, '[Faraon] a spus: „Cu adevărat, Mesagerul vostru care v-a fost trimis vouă este nebun!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, '[Moise] a spus: „Stăpânul Răsăritului și al Apusului și al celor care se află între acestea, dacă voi pricepeți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, '[Faraon] a spus: „Dacă tu iei un alt dumnezeu afară de mine, te voi pune printre cei întemnițați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, '[Moise] a spus: „Dar dacă eu ți-aș aduce un lucru ca dovadă limpede?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, '[Faraon] a spus: „Adu-l, dacă tu ești dintre cei care spun adevărul!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, 'Și [Moise] a aruncat toiagul său care s-a făcut un șarpe învederat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'Și a scos mâna sa și ea era albă, pentru cei care priveau la ea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, '[Faraon] le-a spus dregătorilor din jurul său: „Acesta este un vrăjitor priceput;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, 'El vrea să vă scoată din pământul vostru cu farmecele sale. Deci ce sfătuiți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, 'Ei au spus: „Păsuiește-l pe el și pe fratele său și trimite prin orașe vestitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'Ca să-i aducă pe toți vrăjitorii iscusiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'Așadar, vrăjitorii au fost strânși la timpul dintr-o zi hotărâtă[4].', '[4] Dimineața zilei de sărbătoare. A se vedea 20:58-59');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'Și li s-a spus oamenilor: „Sunteți voi adunați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'Pentru că o să-i urmăm pe vrăjitori, dacă ei vor fi biruitori?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'Și când au venit vrăjitorii, ei i-au spus lui Faraon: „Vom avea noi răsplată, dacă vom fi biruitori?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, 'El a spus: „De bună seamă! Și vă veți număra voi printre apropiații mei!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Moise le-a spus: „Aruncați ceea ce vreți să aruncați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'Și au aruncat ei frânghiile și toiegele lor și au spus: „Jurăm pe puterea lui Faraon, noi vom fi biruitori!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Apoi a aruncat și Moise toiagul său și iată-l înghițind ceea ce au născocit ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Atunci vrăjitorii au căzut, prosternându-se [lui Allah]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'Ei au spus: „Noi credem în Domnul lumilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Domnul lui Moise și al lui Aaron!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, '[Faraon] a spus: „Ați crezut în el [Moise] mai înainte ca eu să vă îngădui? El este mai-marele vostru care v-a învățat și pe voi vrăjitoria! Acum o veți ști voi, căci vă voi tăia mâinile și picioarele opuse și vă voi răstigni pe toți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, 'Și ei au spus: „Nu ne pasă! La Domnul nostru ne vom întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'Cu adevărat, nădăjduim ca Domnul nostru să ne ierte păcatele, căci noi am fost cei dintâi care au crezut.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'Și i-am revelat Noi lui Moise: „Purcede în timpul nopții cu robii Mei, căci veți fi urmăriți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'Și a trimis Faraon vestitori prin cetăți [să spună][5]:', '[5] Recrutori ai unei armate cu scopul de a preveni emigrarea Fiilor lui Israel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, '„Aceștia sunt doar o ceată puțin numeroasă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'Și cu adevărat, ei stârnesc furia noastră,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'Dar noi suntem mulți și ne ferim!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'Și i-am scos Noi din grădini și de la izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'De la comori și locuri plăcute, cu răcoare[6].', '[6] Allah i-a făcut să își abandoneze bunurile și proprietatea în căutarea lor, a israeliților');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Astfel a fost! Și le-am dat Noi moștenire Fiilor lui Israel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'Și la răsăritul Soarelui, au pornit în urma lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'Și când cele două cete s-au văzut una pe alta, însoțitorii lui Moise au spus: „Suntem ajunși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, 'Dar [Moise] a spus: „Nu! Cu adevărat, Domnul meu este cu mine și El mă va călăuzi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'Atunci i-am revelat Noi lui Moise: „Lovește cu toiagul tău marea!” Și ea s-a despicat și fiecare parte era ca un munte imens.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'Și Noi i-am adus aproape de locul acela pe ceilalți [urmăritori]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Și i-am izbăvit Noi pe Moise și pe toți cei care erau cu el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'Și apoi i-am înecat pe ceilalți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'Cu adevărat, întru aceasta este un semn, însă cei mai mulți dintre ei nu au crezut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'Și recită-le lor istoria lui Avraam:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'Când el le-a spus tatălui său și poporului său: „Pe cine adorați voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, 'Ei i-au răspuns: „Noi îi adorăm pe idoli și rămânem slujindu-i pe ei”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, 'Și el le-a spus: „Oare vă aud ei când îi chemați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'Sau vă sunt ei de folos sau vă fac vouă vreun rău?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, 'Ei au răspuns: „Dar i-am aflat pe părinții noștri făcând așa!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, 'El a spus: „Și ați văzut voi ceea ce adorați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'Voi și părinții voștri cei de demult?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'Cu adevărat, ei îmi sunt dușmani mie, în afară de Stăpânul lumilor[7],', '[7] Oamenii adorau idoli împreună cu Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, 'Care m-a creat și El [este Cel care] mă călăuzește,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'Care mă hrănește și-mi dă de băut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'Iar când sunt bolnav, El mă vindecă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'Și care mă lasă să mor și-apoi mă readuce la viață,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'Care nădăjduiesc că-mi va ierta păcatele în Ziua Judecății.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, '[Și el a spus]: „Doamne, dă-mi mie înțelepciune și ajută-mă pe mine să mă alătur celor drepți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'Fă să fiu eu pomenit de bine de cei care vor urma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'Și fă-mă pe mine să fiu unul dintre moștenitorii Grădinii Plăcerii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'Și iartă-i tatălui meu. Cu adevărat, el a fost dintre cei rătăciți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'Și să nu mă acoperi de rușine, în Ziua când vor fi înviați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'Ziua în care nu vor folosi nici avere, nici copii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'În afară de cel care vine la Allah cu inima curată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, '[În ziua aceea] va fi apropiat Raiul de evlavioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, 'Și li se va arăta Iadul celor rătăciți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, 'Și li se va spune lor: „Unde este ceea ce ați adorat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, 'În locul lui Allah? Oare vă ajută ei? Sau se ajută pe ei înșiși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Apoi [idolii] vor fi aruncați de-a valma în el [Iad], ei și cei rătăciți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'Împreună cu toți soldații lui Iblis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'Și vor spune ei în el, certându-se:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, '„Pe Allah! Noi am fost în rătăcire învederată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'Când v-am făcut pe voi egali cu Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'Și nu ne-au dus pe noi în rătăcire decât numai nelegiuiții', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'Și n-avem pe nimeni ca mijlocitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'Nici prieten apropiat [care să ne fie de ajutor],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'Însă de ar fi întoarcere pentru noi, am fi noi credincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'Cu adevărat, întru aceasta este un semn, însă cei mai mulți dintre ei nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'Poporul lui Noe i-a socotit pe Trimiși mincinoși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Atunci când fratele lor Noe le-a spus: „Oare nu aveți voi frică?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Cu adevărat, eu sunt pentru voi un trimis vrednic de încredere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'Așadar fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'Și nu vă cer pentru aceasta nicio răsplată, căci răsplata mea vine de la Domnul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'Așadar fiți cu frică de Allah și dați-mi ascultare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, 'Dar ei au spus: „Oare să-ți dăm ție crezare, când pe tine te urmează cei mai josnici [oameni]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, 'El a spus: „Și ce știu eu despre ceea ce făceau ei?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, 'Socoteala lor nu este decât la Domnul meu, dacă măcar ați pricepe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'Și eu nu îi alung pe credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'Eu nu sunt decât un prevenitor limpede”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, 'Ei au spus: „Dacă nu încetezi, Noe, vei fi dintre cei loviți cu pietre!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, 'El a spus: „Cu adevărat, Doamne, poporul meu mă socotește mincinos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'Deci hotărăște între mine și între ei și mântuiește-mă pe mine împreună cu cei credincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'Atunci l-am mântuit Noi pe el împreună cu cei care erau cu el în arca încărcată', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'Și apoi i-am înecat pe cei rămași.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'Cu adevărat, întru aceasta este un semn, dar cei mai mulți dintre ei nu au fost credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'Cu adevărat, Domnul tău este Al-''Aziz [Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, '[Poporul] ’Ad i-au socotit și ei mincinoși pe Trimiși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Când le-a spus fratele lor Hud: „Oare nu aveți voi frică?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Cu adevărat, eu sunt un Trimis vrednic de încredere pentru voi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'Deci fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'Și eu nu vă cer nicio răsplată pentru aceasta, căci răsplata mea nu este decât la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Clădiți voi pe fiecare înălțime un semn[8], jucându-vă?', '[8] Un simbol sau un semn ce indică averea și puterea lor. Aceștia obișnuiau să construiască structuri impunătoare de-a lungul drumului pentru ca acestea să fie văzute de cei care treceau.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'Și construiți voi zidiri [palate și fortărețe], crezând că veți sălășlui în ele veșnic?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'Și când vă năpustiți asupra cuiva, o faceți fără îndurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Fiți cu frică și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Și fiți cu frică de Cel care v-a înzestrat pe voi [cu prisosință] cu ceea ce cunoașteți! -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'V-a înzestrat pe voi cu vite și cu urmași,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'Cu grădini și cu izvoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Cu adevărat, eu mă tem pentru voi de chinul unei zile cumplite!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, 'Ei au spus: „Ne este totuna de propovăduiești tu sau nu ești dintre propovăduitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'Acestea nu sunt decât obiceiuri ale înaintașilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'Iar noi nu vom fi chinuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'Așadar ei l-au socotit mincinos și Noi i-am nimicit. Cu adevărat, întru aceasta este un semn, dar cei mai mulți dintre ei nu au crezut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, '[Poporul] Thamud i-a socotit mincinoși pe Trimiși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Când fratele lor Salih le-a spus: „Oare nu aveți voi frică?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Cu adevărat, eu sunt pentru voi un Trimis vrednic de încredere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'Așadar fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'Și eu nu vă cer răsplată pentru aceasta, căci eu nu am răsplată decât de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Oare veți fi voi lăsați în siguranță [față de moarte] în ceea ce aveți aici?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'În grădini și la izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'La semănături și la curmali cu fructe plăcute?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'Și vă scobiți case în munți cu iscusință?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'Așadar fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'Și nu ascultați de porunca celor silnici,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'Cei care aduc stricăciune pe Pământ și nu fac bine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'Dar ei au spus: „Tu ești dintre cei fermecați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'Tu nu ești decât un om ca și noi! Fă o minune, dacă ești dintre cei care spun adevărul!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, 'El a spus: „Aceasta este o cămilă[9]. Ea are [un timp] pentru adăpat și voi aveți [un timp] pentru băut o zi anumită!', '[9] Trimisă în mod miraculos de Allah ca semn');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'Să nu o atingeți cu vreun rău, căci vă va cuprinde pe voi chinul unei zile cumplite!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Însă ei au înjunghiat-o și dimineața s-au și căit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'Și de aceea i-a lovit pedeapsa. Cu adevărat, întru aceasta este un semn, însă cei mai mulți dintre ei nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'Poporul lui Lot i-a socotit mincinoși pe Trimiși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Când le-a spus fratele lor Lot: „Oare nu aveți frică?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Eu vă sunt un Trimis vrednic de încredere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'Așadar fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'Eu nu vă cer pentru aceasta răsplată, căci răsplata mea nu este decât la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Oare mergeți voi la bărbații din toate lumile', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'Și vă lăsați soțiile voastre pe care Domnul vostru le-a creat pentru voi? Voi sunteți un popor de nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'Ei i-au spus: „Dacă nu vei înceta, o, Lot, vei fi dintre cei alungați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, 'Iar el a răspuns: „Cu adevărat, eu sunt dintre cei care urăsc faptele voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'Doamne, izbăvește-mă pe mine și pe familia mea de [pedeapsa pe care le-o dai pentru] ceea ce fac ei.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Și l-am izbăvit pe el împreună cu toată familia lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'În afară de o bătrână[10] dintre cei care au rămas [în cetate],', '[10] Soția lui Lot, care a colaborat cu răufăcătorii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'Apoi i-am nimicit pe ceilalți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'Și am lăsat să cadă asupra lor o ploaie [cu pietre] și a fost ea o ploaie cumplită pentru cei care au fost preveniți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'Cu adevărat, întru aceasta este un semn, însă cei mai mulți dintre ei nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'Locuitorii din Ayka [poporul lui Madyan] i-au socotit mincinoși pe trimiși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Când le-a zis lor Șuayb: „Oare nu aveți voi frică [de Allah]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Cu adevărat, eu sunt pentru voi un Trimis vrednic de încredere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'Așadar fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'Și eu nu vă cer pentru aceasta răsplată, căci răsplata mea nu este decât la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Dați măsura întreagă și nu fiți dintre cei care le cauzează [oamenilor] pierderi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'Și cântăriți cu o balanță dreaptă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'Și nu le împuținați oamenilor lucrurile lor și nu pricinuiți rău pe Pământ, fiind stricători,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'Și fiți cu frică față de Cel care v-a creat pe voi și [a creat] popoarele de mai înainte!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, 'Ei au spus: „Tu ești, neîndoielnic, dintre cei fermecați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'Tu nu ești decât un om ca și noi și, cu adevărat, noi te socotim pe tine dintre cei mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'Deci fă să cadă asupra noastră bucăți de Cer, dacă tu ești dintre cei care spun adevărul!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, 'El a spus: „Domnul meu știe mai bine ceea ce faceți voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'Însă ei l-au socotit mincinos și i-a lovit pe ei pedeapsa zilei umbrei [un Nor întunecat]. Cu adevărat, ea a fost pedeapsa unei zile cumplite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'Cu adevărat, întru aceasta este un semn, dar cei mai mulți dintre ei nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'Și, cu adevărat, Domnul tău este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'Iar el [Coranul] este o revelație de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'A coborât cu el Duhul cel demn de încredere [Gavriil]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, 'Peste inima ta [o, Mohammed], pentru ca tu să fii dintre prevenitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'Într-o limbă arabă limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'El a fost deja [pomenit] în scripturile înaintașilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'Oare nu a fost un semn pentru ei [faptul că] îl cunosc cei înțelepți dintre Fiii lui Israel?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'Și chiar dacă l-am fi pogorât Noi unui nearab', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'Și el l-ar fi recitat [perfect][11], nu ar fi crezut în el.', '[11] Drept un miracol de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Astfel am lăsat Noi să intre [respingerea Coranului] în inimile nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'Ei nu vor crede în el până ce nu vor vedea chinul cel dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'Și va veni asupra lor pe neașteptate, fără ca ei să-și dea seama', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'Și atunci ei vor spune: „Oare vom fi noi păsuiți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Oare grăbesc ei pedeapsa Noastră?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Oare vezi tu, chiar dacă i-am lăsa să se mai bucure de plăceri vreme de un număr de ani', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'Și apoi ar veni la ei cele care le-au fost promise', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'Și tot nu le-ar fi lor de niciun folos cele de care s-au bucurat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Și nu am nimicit Noi nicio cetate, fără ca ea să nu fi avut prevenitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'Spre aducere aminte. Și Noi nu am fost nedrepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Și nu au pogorât cu el [Coranul] șeitanii[12],', '[12] Așa cum au spus necredincioșii. Dimpotrivă, a fost adus de Gavriil, Duhul cel Credincios.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'Căci aceasta nu li se cuvine lor și nici nu pot [să o facă]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Ei se află departe de auzire[13].', '[13] A se vedea 72:9');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, '[Deci] nu chema împreună cu Allah o altă divinitate, ca să nu fii tu dintre cei chinuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'Și previne-i tu pe oamenii care-ți sunt cei mai apropiați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'Și coboară aripa ta pentru cei care te urmează dintre credincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'Iar de nu ți se vor supune ei, atunci spune: „Cu adevărat, eu sunt fără de nicio vină pentru ceea ce faceți voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'Și încrede-te în Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'Care te vede când te ridici[14]', '[14] Din patul tău noaptea pentru a te ruga desi ești singur');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'Și care vede și mișcările tale împreună cu cei care se prosternează[15].', '[15] Dintre cei care se roagă cu tine în congregație');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'Cu adevărat, El este As-Sami'' [Cel care Aude Totul] [și] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Să vă vestesc Eu despre cei asupra cărora se pogoară șeitanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Ei se pogoară asupra fiecărui mincinos și păcătos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'Ei transmit ceea ce aud[16], însă cei mai mulți dintre ei sunt mincinoși!', '[16] Aceasta a fost înainte ca ei să fie opriți, așa cum este descris în 72:8-9');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'Cât despre poeți, pe ei îi urmează cei aflați în rătăcire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Oare nu-i vezi cum rătăcesc prin fiecare vale[17]', '[17] Spunând minciuni și lăudându-i pe alții după pofta lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'Și cum spun ei ceea ce nu fac,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'În afară de acei [poeți] care cred și săvârșesc fapte bune și pomenesc [Numele] lui Allah adeseori și [îi] apără [pe musulmani], după ce au fost nedreptățiți. Și vor ști cei care au fost nedrepți către ce sfârșit se întorc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Ta’, Sin[1]. Acestea sunt Versetele Coranului, și o Carte limpede -', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'O călăuză și o bunăvestire pentru dreptcredincioșii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'Care împlinesc Rugăciunea [As-Salat], achită Dania [Az-Zakat] și cred cu tărie în Lumea de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Cu adevărat, acelora care nu cred în Viața de Apoi Noi le-am înfrumusețat faptele, iar ei sunt în cumplită rătăcire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'Aceștia sunt cei care vor avea parte de pedeapsă rea, iar în Viața de Apoi ei sunt cei care vor pierde cel mai mult.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'Și, cu adevărat, [o, Mohammed] tu primești Coranul de la un Înțelept și Bineștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, '[Spune] când Moise i-a zis familiei sale: „Eu zăresc un foc. Vă voi aduce o veste de la el sau vă voi aduce un tăciune aprins, pentru ca voi să vă încălziți”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Dar când a venit la el, i s-a Spus lui: „Binecuvântat este cel care este la foc [un foc neobișnuit de strălucitor care nu ardea și a cărui Lumină era înălțată către Cer - considerat a fi Vălul de foc sau de Lumină din spatele căruia Allah i-a Vorbit lui Moise] și oricine este în jurul lui [Îngerii]! Și Preaslăvit fie Allah, Stăpânul Lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'O, Moise! Eu sunt Allah Al-’Aziz [Cel Preaputernic] [și] Al-Hakim [Înțelept].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, '[Și i s-a spus] „Aruncă toiagul tău.” Și când l-a văzut mișcându-se ca un șarpe, a apucat-o la fugă, fără să se mai uite înapoi. [Allah a Spus:] „O, Moise, nu te teme! Trimișii nu se tem în prezența Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'Doar dacă cineva a fost nedrept, însă apoi a schimbat răul cu bine, căci într-adevăr Eu sunt Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Pune-ți mâna în deschizătura cămășii tale! Ea va ieși albă, fără niciun rău. [Acestea sunt] dintre cele nouă minuni pentru Faraon și poporul său, fiindcă ei sunt într-adevăr un popor de nelegiuiți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'Și când semnele Noastre li s-au arătat lor clare, ei au spus: „Aceasta este magie clară.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'Și ei le-au tăgăduit, cu nedreptate și îngâmfare, chiar dacă sufletele lor erau convinse de ele. Și privește care a fost sfârșitul celor nelegiuiți [necredincioși și mincinoși].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Noi le-am dat lui David și lui Solomon știință și ei au spus: „Mărire lui Allah care ne-a ales pe noi înaintea multora dintre robii Săi credincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'Și Solomon l-a moștenit [prin știință] pe David și a spus: „O, voi oameni! Noi am fost învățați graiul păsărilor și ni s-a dat nouă din toate lucrurile. Cu adevărat, acesta este Harul cel limpede!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'Și au fost adunate la Solomon oștile sale de djinni, de oameni și de păsări și au fost ele aranjate în cete [mărșăluind].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'Și când au sosit ele în Valea Furnicilor, o furnică a spus: „O, voi furnicilor! Intrați în casele voastre, ca să nu vă strivească Solomon și oștile sale, fără ca ei să-și dea seama!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'El [Solomon] a surâs, amuzat de vorbele ei, și a spus: „Doamne, îngăduie-mi mie să-Ți mulțumesc pentru Harul pe care l-ai revărsat asupra mea și asupra părinților mei și să săvârșesc fapte bune de care Tu să fii mulțumit și ajută-mă pe mine să fiu - prin Îndurarea Ta - printre robii Tăi cei evlavioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'Apoi el a cercetat păsările și a spus: „De ce nu văd eu pupăza? O fi ea dintre cei care sunt absenți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'O voi pedepsi cu o pedeapsă chinuitoare sau o voi sacrifica! Doar dacă îmi va aduce ea un motiv deslușit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'Dar ea nu a rămas [absentă] prea mult și [s-a ivit], spunând: „Eu am aflat ceea ce tu nu știi! Îți aduc din Saba'' o veste sigură:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Eu am găsit [acolo] o femeie care împărățește peste ei. Și i s-au dat ei din toate lucrurile. Și are ea un tron minunat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Am aflat-o prosternându-se împreună cu poporul ei dinaintea Soarelui, în locul lui Allah. Șeitan le-a împodobit faptele lor și i-a abătut pe ei de la calea [lui Allah] și nu sunt ei bine călăuziți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, '[Și] astfel ei nu voiesc să se prosterneze lui Allah, Cel care face să iasă la iveală cele ascunse în Ceruri și pe Pământ și Care Știe atât ceea ce țin ei ascuns cât și ceea ce mărturisesc ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Allah! Nu există altă divinitate în afară de El, Stăpânul Tronului Măreț!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, '[Solomon] a spus : „Vom vedea, dacă tu spui adevărul ori de ești dintre cei care mint.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Du-te cu această scrisoare de la mine și aruncă-le-o lor. Apoi stai departe de ei și vezi ce vor trimite ca răspuns!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, 'Ea a spus: „O, voi înalți dregători! A fost aruncată dinaintea mea o scrisoare nobilă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'Într-adevăr vine de la Solomon și este [scris]: „În Numele lui Allah Ar-Rahman [Cel Milostiv], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Nu fiți semeți cu mine, ci veniți la mine cu supunere [față de Allah, ca și musulmani]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'Ea a spus: „O, voi înalți dregători! Sfătuiți-mă în această privință căci eu nu hotărăsc în nicio treabă fără ca voi să fiți de față [pentru a mă sfătui]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, 'Ei au spus: „Noi avem putere și avem tărie mare, însă porunca este la tine, așa că vezi ce poruncești!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'Ea a spus: „Cu adevărat, când regii intră într-o cetate, ei o strică și pe cei mai puternici dintre locuitorii ei îi fac umili. Astfel fac ei [de obicei];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'Dar eu voi să le trimit lor un dar și voi aștepta să văd cu ce se întorc solii!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'Când a venit [solia] la Solomon, el a spus: „Voiți voi să-mi sporiți averea, când ceea ce mi-a dat mie Allah este mai bun decât ceea ce v-a dat vouă?! Așadar bucurați-vă voi de darul vostru!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'Întoarce-te [conducător al soliei] la ei! Și vom veni noi cu soldați asupra lor, cărora nu le vor putea sta împotrivă! Și-i vom alunga noi de acolo umiliți și vor fi ei rușinați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, '[Solomon] a spus: „O, voi înalți dregători [dintre djnni]! Cine dintre voi îmi va aduce mie tronul ei, înainte ca ei să vină la mine supuși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'Unul puternic dintre djinni a spus: „Eu ți-l voi aduce mai înainte ca tu să te ridici de pe locul tău, căci eu sunt în stare de aceasta și sunt vrednic de încredere!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'A spus unul care avea știință din Scriptură: „Eu ți-l voi aduce înainte ca tu să clipești din ochi!”. Și când a văzut [Solomon tronul] stând dinaintea lui, a spus: „Aceasta este prin grația Domnului meu, ca să mă încerce dacă eu sunt mulțumitor sau sunt nemulțumitor. Însă acela care este mulțumitor este mulțumitor pentru sine însuși, cât despre acela care este nemulțumitor, Domnul meu Își este Deajuns pentru Sine și El este Ghaniy [Înstărit] [și] Karim [Mărinimos].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Și a [mai] spus el: „Faceți tronul ei de nerecunoscut [pentru ea], să vedem dacă ea este călăuzită sau dacă ea este dintre aceia care nu sunt călăuziți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'Și când a venit ea, i s-a spus: „Tronul tău este ca acesta?” Iar ea a răspuns: “Parcă ar fi el...” [Solomon a spus] „Și nouă ni se dăduse știința înaintea ei și eram noi deja supuși”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'Însă pe ea o abătuse ceea ce ea adora în locul lui Allah și era ea dintr-un popor de necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'I s-a spus ei: „Intră în palat!” Și când l-a văzut ea, l-a socotit a fi o mare adâncă[2] și [și-a ridicat poalele], descoperindu-și picioarele. Atunci, [Solomon] a spus: “Este un palat pardosit cu cristal”. Ea a spus: „Doamne, eu am fost nedreaptă față de mine însămi! Eu mă supun împreună cu Solomon lui Allah, Stăpânul Lumilor!”', '[2] Podeaua era transparentă și sub ea curgea apa');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'Și l-am trimis Noi la poporul Thamud pe fratele lor Salih, [care le-a spus lor]: „Adorați-L pe Allah!” Dar iată că ei s-au împărțit în două cete care s-au luat la ceartă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, 'El a spus: „O, popor al meu! De ce vă grăbiți voi cu răul înaintea binelui?[3] De ce nu vă rugați lui Allah pentru iertare? Poate că vi se va arăta vouă Îndurare!”', '[3] Provocându-l pe Salih să aducă pedeapsa promisă în loc să ceară Milă de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, 'Ei au spus: „Noi vedem în tine și în cei care sunt cu tine semn rău”. Dar el le-a răspuns: „Semnul vostru [destinul] rău este la Allah! Însă voi sunteți un popor testat[4].”', '[4] Sau „ispitit [de Șeitan]”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'Și se aflau în cetate nouă căpetenii care semănau numai rău pe Pământ și nu făceau niciun bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'Ei au spus: „Jurați pe Allah că noi ne vom năpusti peste noapte asupra sa și asupra familiei sale! Apoi îi vom spune noi rudei sale celei mai apropiate [căreia îi revine răzbunarea lui]: „Noi nu am fost de față la pieirea familiei lui. Și noi spunem adevărul”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'Și ei au făcut un plan și am făcut și Noi un plan, fără ca ei să-și dea seama', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'Și privește care a fost sfârșitul vicleșugului lor: Noi i-am nimicit pe ei împreună cu tot poporul lor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'Iar casele acestea ale lor au rămas pustii pentru că ei au fost nelegiuiți. Întru aceasta este un semn pentru un popor [de oameni] care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'Însă Noi i-am Mântuit pe cei care au crezut și au fost cu frică de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'Și [spune] când Lot i-a spus poporului său: „Vă dedați voi la faptă rușinoasă[5], când voi vedeți limpede [răul pe care îl faceți]?', '[5] Homosexualitate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'Vă apropiați voi de bărbați cu poftă, în loc de muieri? Cu adevărat, voi sunteți un popor ce se poartă nesăbuit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'Și nu a fost răspunsul poporului său altul decât că au spus: „Alungați familia lui Lot din cetatea voastră, căci ei sunt oameni care se pretind curați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'Și l-am mântuit Noi pe el împreună cu familia sa, în afară de soția lui, căreia i-am hotărât să fie dintre cei pierduți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'Și am făcut Noi să coboare asupra lor ploaie [de pietre]. Și ce rea a fost ploaia acestor oameni preveniți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'Spune [o, Mohammed]: „Laudă lui Allah și pace asupra robilor Săi pe care i-a ales! Allah este mai Bun sau ceea ce ei Îi asociază?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Oare cine este Cel care a creat Cerurile și Pământul și v-a pogorât vouă apă din cer? Și cu ea Noi am făcut să răsară grădini minunate! [Altfel] nu v-ar fi fost vouă dat să faceți să răsară pomii lor! Oare există altă divinitate alături de Allah[6]? Însă ei sunt un popor [de oameni] care se abat!', '[6] Are trei înțelesuri: „Este oare un alt dumnezeu care a făcut aceasta împreună cu Allah?” sau „Există oare un alt dumnezeu ce merită a fi adorat împreună cu Allah?” „Există oare un alt dumnezeu ce poate fi comparat cu Allah?”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Oare Cine este Cel care a făcut Pământul loc de repaus, a pus în mijlocul lui râuri, și a făcut munți neclintiți, și a pus o stavilă între cele două mări? [Însă] cei mai mulți dintre ei nu știu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Oare cine este Cel care răspunde celui care este la nevoie, când Îl cheamă, și îndepărtează răul și vă face pe voi urmași pe pământ? Oare există altă divinitate alături de Allah? Numai rareori vă aduceți voi aminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Oare cine este Cel care vă călăuzește prin întunecimile uscatului și mării și Cel care trimite vânturile ca vestitori de bine înaintea Îndurării Sale [ploii]? Oare există altă divinitate alături de Allah? Allah Preamăritul este mai Presus de ceea ce-I fac ei ca asociați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Oare Cine este Cel care a început înfăptuirea [omului] și apoi îl va face din nou? Oare Cine este Cel care vă dă din Cer și de pe Pământ cele de trebuință traiului? Oare există altă divinitate alături de Allah? Spune: „Aduceți dovada voastră dacă voi sunteți cei care grăiesc adevărul!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'Spune: „Nu știe nimeni dintre cei care sunt în Ceruri și pe Pământ Necunoscutul, în afară de Allah!” Iar ei nu-și dau seama când vor fi înviați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Și oare știința lor a ajuns [să afle ceva] despre Ziua de Apoi? Dimpotrivă, ei sunt în îndoială despre aceasta, ba ei sunt orbi față de aceasta!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Iar cei care nu cred spun: „Dacă suntem noi țărână, noi și părinții noștri, mai putem noi fi scoși?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Ni s-a făgăduit nouă aceasta, ca și părinților noștri mai înainte, dar acestea nu sunt decât povești ale popoarelor celor vechi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'Spune [o, Mohammed]: „Purcedeți prin lume și vedeți voi care este sfârșitul nelegiuiților!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'Nu fi mâhnit pentru ei și nu fi îngrijorat pentru ceea ce urzesc ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, 'Și ei spun: „Când va fi [împlinită] această făgăduință, dacă voi grăiți adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'Spune: „S-ar putea ca o parte din ceea ce voi căutați să grăbiți să fie numaidecât în urma voastră!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'Cu adevărat, Domnul tău este Cel cu Mare Milă față de oameni, dar cei mai mulți dintre ei nu-I aduc Lui mulțumire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Și, cu adevărat, Domnul tău Știe ce tăinuiesc piepturile lor și ce dezvăluie ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Și nimic din cele ascunse în Cer și pe Pământ nu este nepomenit într-o Carte limpede[7].', '[7] Tabla bine Păstrată (al-Lauh al-Mahfuth), care se află la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Cu adevărat, acest Coran istorisește Fiilor lui Israel cele mai multe despre cele în care ei sunt în neînțelegere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'Și, cu adevărat, el este călăuză și îndurare pentru dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Cu adevărat, Domnul tău va hotărî între ei prin judecata Sa, și El este Al-’Aziz [Atotputernic] [și] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'Încrede-te în Allah, fiindcă tu ești [pe calea] Adevărului limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Cu adevărat, tu nu-i vei putea face pe cei morți să audă și nu-i vei putea face nici pe cei surzi să audă chemarea, dacă ei întorc spatele îndepărtându-se.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Și nu poți tu să fii călăuzitorul celor orbi, [scoțându-i] din rătăcirea lor. Tu nu-i vei putea face să audă decât pe aceia care cred în Versetele Noastre și care sunt supuși lui Allah [musulmani].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'Și când se va apropia [Ziua de Apoi], le vom scoate Noi din pământ o fiară care le va vorbi lor, [spunându-le] că oamenii nu s-au încrezut în Versetele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'Și [avertizează] de Ziua când Noi vom aduna din fiecare comunitate câte o ceată dintre aceia care nu cred în semnele Noastre, ei vor fi mânați [spre un loc unde vor fi judecați],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'Iar când ei vor sosi, le va spune [Allah]: „Ați ținut de minciună semnele Mele, fără să le fi cuprins cu priceperea voastră? Sau ce ați făcut voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'Și va cădea cuvântul [pedeapsa Sa] asupra lor pentru ceea ce au săvârșit ei cu nedreptate, iar ei nu vor putea rosti [nicio vorbă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Oare nu au văzut ei că Noi am făcut noaptea pentru ca să se odihnească în timpul ei și ziua pentru ca ei să vadă? Iar întru aceasta sunt semne pentru un popor de oameni care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'Și [avertizează] de Ziua când se va suna în Trâmbiță și se vor înspăimânta cei care sunt în Ceruri și cei care sunt pe Pământ - afară de cei care va Voi Allah - vor veni toți la El umiliți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'Și vei vedea munții pe care-i crezi nemișcați cum trec asemenea trecerii Norilor. [Acesta este] Lucrul lui Allah, care a făcut totul desăvârșit. El este Bineștiutor a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Cei care vin [la judecată] cu o faptă bună, vor avea ceva și mai bun decât ea și ei se vor afla la adăpost de spaima acelei Zile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'Iar cei care vin cu o faptă rea[8], vor fi aruncați cu fețele în jos, în Foc [și li se va spune]: „Sunteți voi răsplătiți altfel decât după cum voi ați săvârșit?”.', '[8] Fără ca ei să se fi căit. Se poate referi în general la un păcat sau, mai specific, la a-I face asociați lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, '[Spune, o, Mohammed] „Mi s-a poruncit mie să-L ador pe Stăpânul acestei cetăți[9] pe care El a făcut-o sacră - și ale Lui sunt toate lucrurile - și mi s-a poruncit mie să fiu dintre musulmani.', '[9] Sau regiune, înțelegându-se Mecca și zona care o înconjoară');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'Și să recit Coranul”. Și acela care este călăuzit este călăuzit numai pentru el, iar cât despre cel care este în rătăcire, spune-i tu: „Eu sunt doar dintre prevenitori!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'Și spune: „[Toată] Slava lui Allah! El vă va arăta semnele Sale, iar voi le veți cunoaște!” Iar Domnul tău nu este fără băgare de seamă față de ceea ce săvârșiți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Ta’, Sin, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Acestea sunt Versetele unei Cărți deslușite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Noi îți recităm din povestea lui Moise cu Faraon în tot adevărul, pentru [a preveni] un popor [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Cu adevărat, Faraon a devenit prea semeț pe Pământ. A împărțit poporul lui în trepte, asuprind o parte dintre ei, măcelărindu-i pe fiii lor [nou născuți] și lăsându-le în viață doar pe copilele lor. Cu adevărat, el era dintre făcătorii de stricăciune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'Însă Noi am dorit să Ne arătăm Îndurarea față de cei care au fost socotiți slabi pe Pământ și să-i facem stăpânitori și să-i facem pe ei moștenitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'Și să le dăm lor putere pe Pământ și să le arătăm lui Faraon, lui Haman [ministrului său] și soldaților lor lucrurile de care lor le-a fost teamă [că se vor întâmpla]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'Și i-am revelat Noi mamei lui Moise: „Alăptează-l! Iar dacă te temi pentru el, pune-l pe apa râului! Și nu-ți fie teamă și nu fi mâhnită, căci Noi îl vom întoarce pe el la tine și-l vom face pe el [unul] dintre Trimiși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'Și familia lui Faraon l-a ridicat [din râu], ca să le fie lor dușman și [motiv de] tristețe. Cu adevărat, Faraon, Haman și soldații lor erau păcătoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'Și soția lui Faraon a spus: „[Acest copil] va fi o bucurie pentru mine și pentru tine! Nu-l ucideți! S-ar putea să ne fie de folos sau îl vom lua noi ca fiu!” Însă ei nu presimțeau[2]!', '[2] Care va fi urmarea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'Și inima mamei lui Moise a devenit goală. Și puțin a lipsit ca ea să nu dea totul în vileag, dacă Noi nu i-am fi întărit inima pentru ca ea să fie dintre cei credincioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'Și i-a spus ea surorii lui: „Urmărește-l!” Și a privit ea la el de la distanță, fără ca ei să-și dea seama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'Și Noi l-am oprit pe el mai înainte de aceasta de la doici[3]. Și a spus [sora lui Moise]: „Să vă duc eu la stăpânii unei case, care să-l îngrijească pentru voi și care îl vor crește cu bună-cuviință?”', '[3] Înainte de aceasta Moise a refuzat orice altă femeie ca și doică');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'Și astfel l-am adus Noi înapoi la mama lui, pentru ca ea să se bucure și să nu fie mâhnită și pentru ca să știe că făgăduința lui Allah este adevărată. Dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'Și când a ajuns el la vârsta bărbăției și era pe deplin format, i-am dat lui înțelepciune și știință. Astfel îi răsplătim Noi pe făcătorii de bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'Și el a intrat în cetate într-un moment de neatenție a locuitorilor ei[4]. Și a găsit în ea doi bărbați care se certau între ei: unul era din tabăra lui, iar celălalt era dintre dușmanii lui. Cel din tabăra lui l-a chemat în ajutor împotriva celui dintre dușmanii lui. Și l-a lovit Moise [cu pumnul] și l-a ucis [fără intenție]. Și a spus el [Moise]: „Aceasta este o faptă a lui Șeitan; într-adevăr el este un dușman învederat care duce la rătăcire!”', '[4] În timpul odihnei de prânz');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, 'El a spus: „Doamne, eu am fost nedrept față de mine însumi. Deci iartă-mă pe mine!” Și l-a iertat pentru că El este Al-Ghafur [Iertător], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, 'El a spus: „Doamne, pentru că Tu ai revărsat Grația Ta asupra mea, eu nu voi fi susținător al nelegiuiților!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'În dimineața următoare, pândea el prin cetate speriat. Și iată-l pe cel care în ajun îl chemase în ajutor, strigându-l [din nou] în ajutor. Însă Moise i-a spus: „Cu adevărat, tu ești un rătăcitor limpede!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'Dar când a vrut să-l lovească pe cel care le era dușman amândurora, el[5] a spus: „O, Moise! Voiești tu să mă ucizi pe mine, așa cum ai ucis ieri un suflet? Tu nu voiești decât să fii un tiran pe Pământ și nu voiești să fii dintre cei împăciuitori!”', '[5] Israelitul, crezând că Moise a vrut să îl lovească. Unii comentatori au atribuit vorbele Coptului, însă doar israelitul știa de întâmplările anterioare.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'Și a venit un bărbat de la capătul cetății, alergând, și a spus: „O, Moise! Cârmuitorii pun la cale să te omoare. Deci fugi [din cetate]! Eu îți sunt bun sfătuitor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'Și a ieșit din ea, așteptând cu frică. El a spus: „Doamne, mântuiește-mă pe mine de poporul de nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'Și când s-a îndreptat către Madyan, el a spus: „Poate că Domnul meu mă va călăuzi pe drumul cel drept!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'Și când a ajuns la [fântâna de] apa de la Madyan, a găsit acolo o mulțime de oameni care adăpau [turmele]. Și în afară de ei, a găsit el și două femei care-și țineau departe [turma lor]. Și le-a întrebat el: „Care este necazul vostru?” Ele au răspuns: „Noi nu vom putea să adăpăm până ce nu s-au dus păstorii, iar tatăl nostru este tare bătrân!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'Și a adăpat el [turmele lor] pentru ele, apoi s-a întors la umbră și a spus: „Doamne, eu am mare nevoie de binele pe care îl faci să coboare asupra mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'Apoi a venit la el una dintre cele două [femei], mergând cu sfială, și i-a spus: „Tatăl meu te cheamă să-ți dea o răsplată pentru că ne-ai adăpat nouă [turma]". Și când a venit [Moise] la el[6] și i-a istorisit povestea, i-a spus: „Nu te teme, căci ai scăpat de poporul de nelegiuiți!”', '[6] Profetul Șu`ayb, tatăl celor două fete');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'A spus una dintre ele: „Tată, angajează-l [la tine], căci cel mai bun pe care-l poți lua cu simbrie este cel puternic și vrednic de încredere!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, 'El a spus: „Eu voiesc să-ți dau de nevastă una din aceste două copile ale mele, cu condiția să mă slujești opt ani. Iar de vei împlini zece, aceasta este de la tine, căci eu nu voiesc să te împovărez, ci mă vei afla pe mine - dacă va Voi Allah - printre făcătorii de bine”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, '[Moise] a spus: „Așa să fie între tine și mine! Și oricare dintre cele două termene le voi împlini, nu va fi nedreptate asupra mea. Iar Allah ne este Chezaș pentru ceea ce vorbim!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'Când Moise a împlinit termenul și a purces cu familia sa, a zărit un foc dinspre Munte și a spus familiei sale: „Rămâneți aici! Eu văd un foc. Poate că o să vă aduc vești de acolo sau un tăciune din foc, ca să vă încălziți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'Și când a ajuns la el, a fost Strigat din partea dreaptă a văii, dinspre pomul din locul binecuvântat: „O, Moise! Eu sunt Allah, Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'Aruncă toiagul tău! Și când l-a văzut mișcându-se ca un șarpe, s-a întors și a luat-o la fugă, fără să se mai uite înapoi. „O, Moise! Apropie-te și nu te teme, căci tu ești dintre cei aflați în siguranță!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'Vâră-ți mâna prin deschizătura cămășii tale și ea va ieși albă, neatinsă de niciun rău! Și strânge brațul către tine pentru ca să nu-ți fie frică! Acestea sunt două semne de la Domnul tău pentru Faraon și pentru dregătorii lui. Cu adevărat, ei sunt un popor de nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'El a spus: „Doamne, eu am ucis un suflet de-al lor și mă tem ca ei să nu mă ucidă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'Însă fratele meu Aaron este mai limpede decât mine la limbă. Trimite-l cu mine spre ajutor, ca să adeverească spusele mele, căci mă tem să nu mă socotească mincinos!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, '[Allah] a spus: „Vom întări brațul tău prin fratele tău și vă vom da vouă putere, astfel încât ei să nu ajungă la voi. Cu semnele Noastre veți fi voi și cei care vă urmează pe voi biruitori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'Și când a venit Moise la ei cu semnele Noastre deslușite, ei au spus: „Aceasta nu este decât fermecătură născocită! Noi n-am auzit de aceasta la strămoșii noștri cei mai vechi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'Moise a spus: „Domnul meu Știe mai bine cine a venit cu îndreptare de la El și a cui va fi Casa cea de Veci! Nelegiuiții nicicum nu vor izbândi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'A spus Faraon: „O, dregători ai mei! Eu nu știu altă divinitate pentru voi, afară de mine! O, Haman! Arde pentru mine lut și înalță-mi mie un turn! Poate astfel voi ajunge eu să privesc la Domnul lui Moise, pe care eu îl socotesc dintre mincinoși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'Și s-au purtat el și oștenii lui cu semeție pe Pământ, pe nedrept, și și-au închipuit ei că nu vor fi întorși la Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Însă Noi i-am prins pe el și pe oștenii lui și i-am aruncat pe ei în mare[7]. Privește, deci, care este sfârșitul nelegiuiților!', '[7] Allah i-a făcut să își lase toate bunurile și să intre în mare pentru a-i urmări pe Fiii lui Israel. A se vedea 26:52-66.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'Și i-am făcut Noi chemători [ai oamenilor] către Foc, iar în Ziua Învierii nu vor fi ei ajutați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'Și am făcut Noi să-i urmărească în această lume un blestem, iar în Ziua Învierii vor fi ei rușinați[8].', '[8] Literar „hidoși”, care nu vor primi binele și mila');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'Și i-am dat Noi lui Moise Cartea [Tora] - după ce am nimicit popoarele de mai înainte - ca dovezi limpezi pentru oameni, călăuzire și îndurare, pentru ca ei să ia aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'Și tu [o, Mohammed] nu ai fost pe coasta de apus [a Muntelui], când i-am dat lui Moise porunca, și nici n-ai fost printre martori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Însă Noi am făcut să se ivească generații [după Moise] și vremea care s-a scurs peste ele a fost lungă[9]. Tu nu ai locuit printre oamenii din Madyan ca să le reciți Versetele Noastre, dar Noi te-am trimis ca Mesager[10].', '[9] Și astfel ei au uitat sau au neglijat Ordinele lui Allah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Tu nu ai fost nici la coasta Muntelui Tor, când Noi am Chemat, dar [Noi ți-am revelat], ca o Îndurare de la Domnul tău, pentru ca tu să îndemni un popor cărora nu le-a venit un prevenitor mai înainte de tine, pentru ca ei să ia aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'Și nu a fost o nenorocire să-i lovească pentru ceea ce au făcut mâinile lor mai înainte, fără ca ei să spună: „Doamne, de ce nu ai trimis Tu un Profet la noi, ca să urmăm semnele Tale și să fim noi printre dreptcredincioși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'Dar când le-a venit lor Adevărul din partea Noastră, ei au spus: „Dacă măcar i s-ar fi trimis și lui asemenea cu ceea ce i-a fost trimis lui Moise!” Dar oare nu au tăgăduit ei ceea ce i s-a trimis lui Moise mai înainte? Ei spun: „Două vrăjitorii care se ajută una pe alta[11]!” Și mai spun: „Noi nu credem în niciuna!”', '[11] Referința este făcută de necredincioșii din Qurayș față de Coran și Tora.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'Spune: „Aduceți voi o carte de la Allah mai bună pentru călăuzire decât acestea două [Tora și Coranul] și eu o voi urma, dacă voi veți fi întru adevăr!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Iar de nu-ți vor răspunde, să știi că ei urmează doar poftele lor! Și cine este mai rătăcit decât acela care urmează poftei sale fără o călăuzire de la Allah? Cu adevărat, Allah nu-i călăuzește pe cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'Noi am făcut să ajungă la ei Cuvântul [Coranul], pentru ca ei să ia aminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Celor [evreii și creștinii] cărora Noi le-am dat Cartea mai înainte de el - cred în acesta [în Coran];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'Și când li se recită lor ei spun: „Noi credem în el. Acesta este Adevărul de la Domnul nostru. Și noi am fost supuși [lui Allah] înainte de [pogorârea lui]”;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'Aceștia vor fi dăruiți cu răsplată de două ori, pentru că ei sunt statornici și pentru că ei resping fapta rea prin fapta bună și fac milostenie din cele cu care i-am înzestrat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'Iar când ei aud vorbele grele [murdare și inutile] se îndepărtează de ele și spun: „Noi avem parte de faptele noastre și voi aveți parte de faptele voastre! Pacea asupra voastră! Noi nu căutăm tovărășia celor ignoranți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Cu adevărat, Tu, [Mohammed], nu călăuzești pe cine-ți place, ci Allah călăuzește pe cine Voiește și El îi Cunoaște mai bine pe cei ce se lasă călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'Și ei [cei din Qurayș] spun: „Dacă am urma călăuzirea cea bună împreună cu tine, am fi noi smulși din pământul nostru!” Dar oare nu le-am stabilit Noi un loc sacru și sigur, în care se aduc roade de toate soiurile, spre folos din partea Noastră? Însă cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'Și câte cetăți am nimicit Noi, după ce s-au semețit în viața lor! Și iată casele care nu au mai fost locuite după ei decât de puțini și Noi suntem moștenitorii [lor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'Însă Domnul tău nu nimicește cetățile mai înainte de a fi trimis un Mesager la mama lor [cea mai importantă dintre ele], care să le citească Versetele Noastre. Și Noi nu am făcut să piară cetățile decât dacă locuitorii lor au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Și tot ceea ce vi s-a dat vouă [oamenilor] dintre lucruri este numai plăcere trecătoare a acestei vieți și podoabă a ei, pe când ceea ce este la Allah este mai bun și este veșnic. Voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Oare acela căruia i-am făcut Noi frumoasă făgăduință [Paradisul], pe care el o primește, este la fel ca acela căruia Noi i-am dăruit bucuriile vieții lumești și care în Ziua Învierii se va afla printre cei aduși [pentru pedeapsă în Iad]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'Și în Ziua când El îi va chema, le va spune: „Unde sunt aceia despre care ați pretins că ar fi asociații Mei?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, '[Atunci] vor spune cei împotriva cărora se va rosti cuvântul[12]: „Doamne, aceștia sunt cei pe care i-am dus în rătăcire. Și i-am dus pe ei în rătăcire, precum și noi am fost în rătăcire. Însă noi ne dezvinovățim înaintea Ta. Ei nu ne-au adorat pe noi”.', '[12] Hotărârea pentru pedeapsa lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, 'Și se va spune [atunci]: „Chemați-i pe asociații voștri!” Și ei îi vor chema, dar nu le vor răspunde. Și ei vor vedea chinul și atunci vor dori ei să fi fost bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'Și [spune] de Ziua Aceea când El îi va Chema și le va spune: „Ce le-ați răspuns voi Trimișilor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'Dar în Ziua Aceea dovezile lor vor fi oarbe pentru ei și ei nu se vor putea întreba unul pe altul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'Însă aceia care s-au căit, au crezut și au făcut bine, aceia vor fi printre cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Și Domnul tău creează ceea ce Voiește și alege, însă ei nu vor avea alegere. Mărire lui Allah! El este mai Presus de ceea ce-I asociază Lui!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Și Domnul tău Știe ceea ce ascund piepturile lor și ceea ce ele fac deschis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Și El este Allah. Nu există altă divinitate în afară de El! A Lui este Lauda atât în această lume cât și în Lumea de Apoi și la El este Judecata și la El veți fi întorși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'Spune: „Ce credeți voi? Dacă Allah ar așterne peste voi o noapte nesfârșită până în Ziua Învierii, care dumnezeu afară de Allah v-ar aduce vouă o lumină? Oare voi nu auziți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'Spune: „Ce credeți voi! Dacă Allah ar așterne peste voi o zi nesfârșită până în Ziua Învierii, care dumnezeu afară de Allah v-ar aduce vouă o noapte ca să vă odihniți în timpul ei? Oare voi nu vedeți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Prin Îndurarea Sa, El v-a făcut noaptea și ziua, ca să vă odihniți și ca să căutați Mila Lui. Poate că voi veți fi mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'Și [amintește-le] de Ziua când El îi va chema și va spune: „Unde sunt aceia despre care ați pretins că ar fi asociații Mei?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'Și vom scoate Noi din fiecare comunitate un martor și vom spune: „Aduceți dovada voastră!” Și vor ști ei că Adevărul este la Allah și că s-au îndepărtat de ei acelea pe care ei le-au plăsmuit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Cu adevărat, Qarun a fost din poporul lui Moise, însă el s-a răzvrătit împotriva lor. Și i-am dat Noi atâtea comori, încât numai cheile lui apăsau greu asupra unei cete de [bărbați] vânjoși. Și când i-a spus lui poporul său: „Nu te semeți, fiindcă Allah nu-i iubește pe cei care se semețesc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, 'Ci caută cu ceea ce ți-a dăruit Allah Casa cea veșnică! Și nu uita partea ta din această viață! Și fă bine, așa după cum și Allah ți-a făcut ție bine! Și nu umbla după stricăciune pe pământ, fiindcă Allah nu-i iubește pe cei care fac stricăciune",', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, 'El a spus: „Mie mi s-a dat ceea ce am numai datorită științei mele!” Oare el nu știa că Allah a nimicit înainte de el dintre popoare bărbați mai puternici decât el și care adunaseră mai multe bunuri? Iar nelegiuiții nu sunt întrebați pentru păcatele lor[13]!', '[13] Nu va mai fi nevoie ca păcatele lor să fie enumerate, deoarece cantitatea lor este evidentă și mai mult decât suficientă pentru a garanta pedeapsa în Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'Și a ieșit el dinaintea poporului său cu toată podoaba sa. Cei care voiau viața lumească au spus atunci: „O, de-am avea și noi asemenea cu ceea ce i s-a dat lui Qarun! El este [un om] cu mare noroc.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'Însă cei cărora le-a fost dăruită știința au spus: „Vai vouă! Răsplata lui Allah este mai bună pentru cei care cred și săvârșesc fapte bune!” Însă ea [răsplata] nu va fi primită decât de către cei statornici.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'Noi am făcut ca pământul să-l înghită pe el și casa lui și nu a avut el nicio ceată care să-l sprijine împotriva lui Allah și nu a fost el dintre cei în stare să se ajute pe ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'Și cei care doriseră ieri să fie în locul lui au spus în dimineața următoare: „Vai! Într-adevăr Allah mărește câștigul aceluia care Voiește El dintre robii Săi sau îl micșorează. Dacă Allah nu ar fi fost Milostiv cu noi, ar fi [lăsat pământul] să ne înghită și pe noi. Vai! Într-adevăr necredincioșii nu izbândesc!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'Această Casă de Veci [Paradisul] o facem Noi pentru aceia care nu voiesc fală pe Pământ, nici stricăciune. Iar sfârșitul [bun] este al acelora care au frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Cel ce vine cu faptă bună va avea parte de ceva și mai bun decât ea, iar cel ce vine cu faptă rea [să știe că] cei care săvârșesc fapte rele nu vor fi răsplătiți decât după ceea ce au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Cu adevărat [o, Mohammed], Acela care ți-a dăruit Coranul te va aduce înapoi la locul unde [tu vrei] să te întorci[14]. Spune: „Domnul meu Știe mai bine cine vine cu călăuzirea și cine este în rătăcire răzvedită!”', '[14] Însemnând Mecca (în viața aceasta) sau în Paradis (în Viața de Apoi)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Tu nu nădăjduiai să ți se aducă ție Cartea, decât ca o Îndurare de la Domnul tău. Așadar, nu fi niciodată un ajutor pentru necredincioși.[15]', '[15] În religia lor prin a face concesii pentru credințele lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'Și ei să nu te abată de la Versetele lui Allah, după ce ele ți-au fost trimise ție, și cheamă la Domnul tău și nu fi tu dintre politeiști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'Și nu chema alături de Allah alt dumnezeu, căci nu există altă divinitate în afară de El! Totul va pieri în afară de Chipul Său[16]. La El este Judecata și la El veți fi aduși înapoi!', '[16] În afară de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Alif, Lam, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'Oare oamenii cred că vor fi lăsați [în pace], dacă vor spune „Noi credem!”, și că ei nu vor fi încercați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'Noi i-am încercat pe cei de dinaintea lor și Allah îi va face cunoscuți pe cei care spun adevărul și îi va face cunoscuți pe cei care mint [în privința credinței].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Sau se gândesc cei care săvârșesc fapte rele că vor putea scăpa de Noi? Ce rău judecă ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Cei care nădăjduiesc în răsplata bună la întâlnirea cu Allah [să știe că] termenul lui Allah va veni. El este As-Sami'' [Cel care Aude Totul] [și este] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'Și cel care se luptă nu se luptă decât pentru sine. Cu adevărat, Allah nu se află în nicio nevoie de lumi [oameni, djini și toată creația Sa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'Cât despre cei care cred și săvârșesc fapte bune, Noi îi vom ierta pe ei pentru faptele lor rele și-i vom răsplăti pe ei pentru faptele cele mai bune pe care le-au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'L-am îndemnat pe om să se poarte cu părinții săi frumos. Însă dacă ei se vor lupta cu tine pentru ca să-Mi faci Mie ca asociat ceva despre care tu nu ai știință[2], nu le da lor ascultare! La Mine este întoarcerea voastră, iar Eu vă voi vesti ceea ce ați făcut.', '[2] Nu ai știință despre divinitatea sa. Nu poate exista știință despre ceva ce este inexistent sau neadevărat.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'Și pe cei care cred și săvârșesc fapte bune îi vom face Noi să intre printre cei buni [în Paradis].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Și printre oameni sunt [unii] care spun: „Noi credem în Allah”, dar dacă ei au de suferit pentru [cauza lui] Allah, atunci ei socotesc că încercarea [necazul] oamenilor este [precum] chinul lui Allah. Dar dacă le vine victoria de la Domnul tău, atunci ei spun: „Cu adevărat, noi am fost cu voi [ajutându-vă]!” Dar oare nu este Allah Cel care Știe cel mai bine ce se află în piepturile tuturor lumilor [oameni, djini și toată creația Sa]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'Și Allah îi va face cunoscuți prea bine pe cei care cred, după cum la fel de bine îi va face cunoscuți și pe cei fățarnici.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Și cei care nu cred le zic acelora care cred: „Urmați calea noastră, iar noi vom purta păcatele voastre!” Însă ei nu vor purta nimic din păcatele lor, căci ei sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'Dar ei vor purta cu siguranță poverile lor [proprii] și alte poveri împreună cu poverile lor[3] și cu siguranță, ei vor fi întrebați în Ziua Învierii despre ceea ce au născocit.', '[3] În afară de păcatele proprii, ei vor avea și păcatele celor pe care i-au călăuzit greșit, fără ca acestea să scadă pentru ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Și Noi l-am trimis pe Noe la poporul său și el a rămas printre ei o mie de ani fără cincizeci de ani. Și i-a apucat pe ei potopul, pentru că au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'Și i-am mântuit Noi pe el și pe locuitorii corabiei și am făcut Noi [această întâmplare[4]] un semn pentru lumi.', '[4] Arca, întâmplarea sau povestea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'Și [Noi l-am trimis] pe Avraam, când a spus poporului său: „Adorați-L pe Allah și fiți cu frică de El! Aceasta este mai bine pentru voi, dacă voi știți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'Însă voi adorați în locul lui Allah niște idoli și născociți minciună. Cu adevărat, cei în care credeți voi în locul lui Allah nu pot avea niciun mijloc pentru hrănirea voastră. Căutați hrana voastră la Allah, adorați-L pe El și aduceți-I Lui mulțumire, căci la El veți fi întorși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'Iar dacă voi învinuiți de minciună, [să știți că] și alte comunități au învinuit de minciună înainte de voi, iar Trimisului nu-i revine decât transmiterea limpede.[5]', '[5] Comentatorii au păreri diferite cu privire la acest Verset – dacă este o continuare a cuvintelor profetului Avraam sau cuvinte de consolare date de Allah profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra lor), variantă care în acest context este mai probabilă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Oare nu au văzut ei cum începe Allah creația prima oară și cum o va face pe ea apoi din nou? Cu adevărat acesta este [un lucru] ușor pentru Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'Spune [o, Mohammed]: „Umblați pe Pământ și vedeți cum [Allah] a început creația! Tot astfel va crea Allah făpturile din nou [în Ziua Judecății], căci Allah este peste toate cu Putere.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'El pedepsește pe cine Voiește El și este Îndurător cu cine Voiește El și la El veți fi aduși înapoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Și nu puteți voi să scăpați [de Allah] nici pe Pământ și nici în Cer și voi nu aveți în afară de Allah nici aliat și nici sprijinitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'Iar cei care nu cred în semnele lui Allah și în întâlnirea cu El, aceia nu pot nădăjdui în Îndurarea Mea și aceia vor avea parte de osândă dureroasă”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Și nu a fost răspunsul poporului său[6] decât că ei au spus: „Omorâți-l sau ardeți-l în foc!”, însă Allah l-a mântuit de la foc. Întru aceasta sunt semne pentru un popor de oameni care cred.', '[6] Lui Avraam');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, 'Și [Avraam] a spus: „Voi i-ați făcut lui Allah asociați dar dragostea dintre voi este doar în viața lumească, iar în Ziua de Apoi vă veți lepăda unul de celălalt și vă veți blestema unul pe altul, iar sălașul vostru va fi Focul și nu veți avea voi sprijinitori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'Și Lot a crezut în el [în mesajul său]. [Avraam] a spus: „Eu purced către Domnul meu. El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'Și Noi i-am dăruit lui [Avraam] pe Isaac și pe Iacob, am dăruit urmașilor săi Profeția și Cartea și i-am dat lui răsplata [cuvenită] în această lume, iar în Lumea de Apoi se va afla el printre cei drepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'Și [spune] despre Lot când a spus poporului său: „Voi săvârșiți faptă rușinoasă [homosexualitatea - unul din cele mai mari păcate], pe care nu a mai săvârșit-o nimeni din toate lumile mai înainte de voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'Cu adevărat, voi vă apropiați de bărbați și pândiți la drum[7] și în adunarea voastră săvârșiți faptă urâtă.” Răspunsul poporului său nu a fost altul decât că ei au zis: „Fă să ne vină pedeapsa lui Allah, dacă tu ești dintre cei care spun adevărul!”', '[7] Îi jefuiți pe călători sau îi agresați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, 'El a spus: „Doamne, ajută-mă împotriva poporului de stricători!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'Și când au venit trimișii Noștri [Îngerii] la Avraam cu vestea cea bună[8], i-au spus: „Cu adevărat, noi îi vom distruge pe locuitorii acestei cetăți, căci locuitorii ei sunt nelegiuiți!”', '[8] Despre nașterea lui Isaac și a descendentului său Iacob');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, 'El a spus: „Dar în ea se află Lot!” Și ei au răspuns: „Noi știm mai bine cine se află în ea! Pe el împreună cu familia lui îi vom mântui, în afară de soția lui care va fi printre cei ce vor pieri”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'Și când au venit trimișii Noștri [Îngerii] la Lot, el a fost tulburat pentru ei și nu s-a simțit în stare să-i ajute[9], însă ei au spus: „Nu te teme și nu fi mâhnit!... Noi te vom mântui pe tine împreună cu familia ta, afară de muierea ta care va fi printre cei ce vor pieri.', '[9] A se vedea 11:77');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'Cu adevărat, Noi vom pogorî asupra locuitorilor din această cetate pedeapsă aspră din Cer, pentru că ei sunt nelegiuiți”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'Și Noi am făcut din aceasta un semn limpede pentru un popor de oameni care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'Și la [poporul din] Madyan [l-am trimis Noi] pe fratele lor Șuayb, care le-a spus: „O, popor al meu! Adorați-L pe Allah! Și nădăjduiți voi în răsplata din Ziua de Apoi și nu pricinuiți stricăciune pe pământ!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Însă ei l-au socotit mincinos și i-a lovit pe ei cutremurul și au căzut [morți], cu fața în jos, în casele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'Și [tot astfel i-am nimicit și pe cei din popoarele] ’Ad și Thamud și vă este vouă limpede din casele lor [ruinate]. Șeitan le-a împodobit faptele lor și i-a împiedicat pe ei de la drum, cu toate că ei fuseseră în stare să vadă limpede [că ei urmează calea rătăcirii].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'Și [Noi i-am distrus] pe Qarun, pe Faraon și pe Haman. Și Moise a venit la ei cu semne limpezi, însă s-au purtat cu aroganță pe Pământ și nu au scăpat nici ei [de pedeapsa Noastră].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'Pe fiecare I-am pedepsit Noi după păcatul lor: printre ei se află aceia asupra cărora am trimis vijelie cu pietre; printre ei se află aceia pe care i-a lovit strigătul; printre ei se află aceia pe care Noi am făcut să-i înghită pământul; printre ei se află aceia pe care Noi i-am înecat. Și nu Allah a fost nedrept cu ei, ci ei au fost nedrepți față de ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Exemplul celor care au luat ocrotitori în locul lui Allah este precum exemplul păianjenului care și-a făcut o casă; dar cea mai slabă casă este casa păianjenului, dacă ei măcar ar fi știut!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Cu adevărat, Allah Știe orice cheamă ei în locul Său, căci El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'Și aceste exemple Noi le dăm oamenilor, dar nu le înțeleg decât cei pricepuți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Allah a creat Cerurile și Pământul cu [chibzuință] adevărată. Și, cu adevărat, în aceasta este un semn pentru cei credincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'Recită [o, Mohammed,] ceea ce ți s-a revelat din Carte și împlinește Rugăciunea [As-Salat]! Într-adevăr Rugăciunea [As-Salat] împiedică de la ceea ce este rușinos și de la ceea ce este oprit. Și Pomenirea lui Allah este și mai mare, iar Allah Știe ce faceți voi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'Nu discutați cu oamenii Cărții [evreii și creștinii] decât în felul cel mai frumos [folosind cuvinte și maniere alese], în afară de aceia dintre ei care sunt nelegiuiți [cu voi]! Și spuneți: „Noi credem în ceea ce ni s-a trimis nouă și vi s-a trimis vouă! Domnul nostru și Domnul vostru este Unul singur și noi Lui îi suntem supuși [musulmani]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Și astfel ți-am trimis Noi ție Cartea [Coranul]. Iar aceia cărora Noi le-am dat Scriptura cred în ea. Și printre aceștia [oamenii din Mecca] sunt unii care cred în ea și numai necredincioșii tăgăduiesc semnele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Și tu [o, Mohammed,] nu ai citit mai înainte de ea [de Coran] nicio altă scriptură și nici nu ai scris-o cu dreapta ta [fiindcă era neștiutor de carte]. Atunci s-ar fi îndoit cei care tăgăduiesc Adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Dimpotrivă el este [format din] Versete învederate în piepturile acelora cărora li s-a dat cunoașterea și nu tăgăduiesc Versetele Noastre decât numai cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'Și ei spun: „De ce nu i se trimit lui minuni de la Domnul său?” Spune: „Dar minunile sunt numai la Allah, iar eu sunt doar un prevenitor limpede”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'Oare nu le este lor de ajuns că Noi ți-am trimis ție Cartea [Coranul] care le este recitată? Cu adevărat, întru aceasta este Îndurare și pomenire pentru un popor [de oameni] care vor să creadă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'Spune: „Allah este de ajuns ca Martor între mine și între voi! El Știe ce se află în Ceruri și ce se află pe Pământ. Iar aceia care cred în deșertăciune și nu cred în Allah, aceia sunt cei care pierd.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Ei îți cer să grăbești pedeapsa. Și de n-ar fi un termen hotărât, le-ar veni pedeapsa! Și fără îndoială că ea va veni peste ei, pe neașteptate, fără ca ei să simtă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Ei îți cer să grăbești pedeapsa, în vreme ce [ei știu că] Iadul îi va împresura pe necredincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'Într-o zi, când îi va cuprinde pe ei chinul de deasupra lor și de sub picioarele lor și li se va spune lor: „Gustați voi ceea ce ați săvârșit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'O, robi ai Mei care ați crezut! Pământul Meu este atât de întins! Adorați-Mă pe Mine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Fiecare suflet va gusta moartea. Apoi veți fi voi aduși înapoi la Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'Acelora care cred și săvârșesc fapte bune le vom dărui Noi locuință în părțile de sus ale Raiului, pe sub care curg pâraie și veșnic vor sălășlui ei în ele. Minunată răsplată pentru cei ce fac lucruri [bune],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'Pentru cei care sunt statornici și în Domnul lor se încred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'Și câte vietăți sunt care nu poartă hrana lor! Allah le hrănește și pe ele și pe voi! El este As-Sami'' [Cel care Aude Totul] [și] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'Și dacă tu îi întrebi, cine a creat Cerurile și Pământul și a supus Soarele și Luna, ei răspund: „Allah!” Atunci cum de se lasă ei abătuți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Allah dă din belșug cele spre viețuire cui Voiește El dintre robii Săi sau le împuținează lor. Allah este Atoateștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'Iar dacă tu îi întrebi cine pogoară apa din Cer și învie cu ea pământul, după ce el a fost mort, ei răspund: „Allah!” Spune: „Slavă lui Allah!” Însă cei mai mulți dintre ei nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Și nu este această viață lumească decât joacă și glumă, însă în Lumea de Apoi este viața cea adevărată! Dacă ei ar ști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Și când se urcă ei pe o corabie Îl invocă numai pe Allah, fiind [supuși] sinceri Lui și în religie[10], dar după ce îi aduce pe uscat, ei Îi fac asociați,', '[10] Fără a-I face asociați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'Pentru a tăgădui ceea ce le-am dat lor și pentru a se bucura [de plăcerile acestei lumi], însă ei vor ști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Oare nu văd ei că Noi am făcut [Mecca] un loc sacru și sigur, în vreme ce oamenii din jurul lor sunt răpiți? Și oare cred ei în deșertăciune și tăgăduiesc binefacerea lui Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Și cine este mai nelegiuit decât acela care născocește minciuni împotriva lui Allah sau tăgăduiește Adevărul, atunci când vine la el? Oare nu se află în Iad sălaș pentru necredincioși?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Iar pe aceia care se străduiesc de dragul Nostru îi vom călăuzi pe căile Noastre, căci Allah este cu cei credincioși care fac bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'Alif, Lam, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'Romanii au fost înfrânți[2],', '[2] De către Persani');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'În pământul cel mai apropiat [Siria, Irak, Iordania și Palestina]. Însă după înfrângerea lor, vor învinge ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'Între trei și nouă ani. La Allah a fost hotărârea și mai înainte și după aceea; și în ziua aceea se vor bucura dreptcredincioșii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'De ajutorul lui Allah[3]. El ajută cui Voiește El și El este Al-''Aziz [Cel Atotputernic] [și] Ar-Rahim [Îndurător].', '[3] Victoria dată de Allah oamenilor Cărții (creștinii) peste cei din Persia');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'Aceasta este făgăduința lui Allah. Și Allah nu-Și calcă făgăduința, însă cei mai mulți oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Ei cunosc ceea ce este văzut din viața aceasta, însă ei sunt neștiutori față de Viața de Apoi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'Oare nu meditează ei în înseși sufletele lor [cum au fost ei creați] că Allah nu a creat Cerurile și Pământul și ceea ce este între ele decât întru adevăr și pentru un termen hotărât? Însă mulți dintre oameni nu cred în întâlnirea cu Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Oare n-au purces ei pe Pământ și n-au văzut ei cum a fost sfârșitul celor de dinainte de ei? [Aceia] au fost mai puternici decât ei, au scurmat pământul și l-au locuit în număr mai mare decât îl locuiesc ei. Și au venit la ei Trimișii lor cu semnele limpezi. Și Allah nu i-a nedreptățit pe ei, ci numai ei s-au nedreptățit pe ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'Apoi a fost rău sfârșitul celor care au săvârșit rău, fiindcă ei au tăgăduit semnele lui Allah și le-au luat pe ele în derâdere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Allah creează făptura, apoi o face din nou, apoi la El veți fi aduși înapoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'În Ziua când va veni Ceasul, nelegiuiții vor fi deznădăjduiți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Și nu vor avea dintre asociații lor mijlocitori și se vor lepăda de asociații lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'În Ziua când va veni Ceasul, în Ziua aceea se vor despărți ei [unii de alții].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'În ce-i privește pe cei care au crezut și au săvârșit fapte bune, ei se vor bucura într-o Grădină [din Paradis],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'Iar în ce-i privește pe cei care nu au crezut și au socotit Versetele Noastre ca și întâlnirea cu Lumea de Apoi a fi minciuni, aceia vor fi aduși la chin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Aduceți, așadar, Slavă lui Allah, când vine seara și când vă treziți dimineața!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'Slavă Lui în Ceruri și pre Pământ - atât înainte de asfințit, cât și când sunteți în mijlocul zilei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'El îl scoate pe cel viu din cel mort și-l scoate pe cel mort din cel viu. El dă viață pământului, după moartea lui. Și tot astfel veți fi și voi scoși[4].', '[4] Din morminte sau din pământ la momentul învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'Și printre semnele Lui [este acela] că El v-a creat pe voi din țărână și apoi iată-vă pe voi oameni care v-ați răspândit [pe Pământ].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'Și printre semnele Lui [este acela] că El v-a creat din voi înșivă soațe, pentru ca voi să trăiți în liniște împreună cu ele. Și El a pus între voi dragoste și îndurare și întru aceasta sunt semne pentru un neam [de oameni] care chibzuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'Și printre semnele Lui sunt crearea Cerurilor și a Pământului și deosebirea limbilor voastre și a culorilor voastre. Întru aceasta sunt semne pentru cei care știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'Și printre semnele Lui sunt somnul vostru în timpul nopții și în timpul zilei și căutarea de către voi a Harului Său. Întru aceasta sunt semne pentru un popor [de oameni] care aud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'Și printre semnele Lui este [acela] că El vă arată vouă fulgerul, cu teamă [de trăsnet] și cu nădejde [în ploaie], și că pogoară apă din Cer, cu care învie Pământul, după moartea lui. Întru aceasta sunt semne pentru un neam [de oameni] care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'Și printre semnele Lui este [acela] că Cerul și Pământul există prin Porunca Sa, iar dacă El vă va Chema pe voi cu o chemare, veți ieși voi din pământ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'Ai Lui sunt cei din Ceruri și de pe Pământ și toți Îi sunt Lui supuși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'El este Cel care creează prima oară făpturile și apoi le face din nou - și aceasta este și mai ușor pentru El - și a Lui este descrierea cea mai înaltă [Atributele] din Ceruri și de pe Pământ și El este Al-''Aziz [Atotputernic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'El vă va face vouă exemplu din voi înșivă: Aveți voi dintre cei pe care-i stăpânesc mâinile voastre drepte [sclavi] asociați la cele cu care v-am înzestrat pe voi și sunteți voi întru aceasta de-o seamă cu ei? Vă temeți de ei așa cum este teama voastră de voi înșivă[5]? Astfel tâlcuim Noi Versetele pentru un neam [de oameni] care pricep.', '[5] Unii de alții între voi și asociații voștri de drept');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Ba aceia care sunt nelegiuiți urmează poftele lor, fără de știință. Și cine-l poate călăuzi pe cel pe care Allah l-a dus în rătăcire? Ei nu vor avea sprijinitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'Ridică-ți fața ta spre Religia cea adevărată! [Urmează] Fitrah [monoteismul] lui Allah[6], după care El i-a creat pe oameni. Nu există schimbare în creația lui Allah. Aceasta este Religia cea dreaptă, dar cei mai mulți oameni nu știu.', '[6] Fitrah- înclinația naturală a omului de a-L adora pe Creatorul său, existentă înainte de coruperea naturii sale de forțe externe. Astfel, monoteismul islamic este descris drept religia naturii înnăscute Fitrah a omului.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'Întoarceți-vă la El căindu-vă! Fiți cu frică de El și împliniți Rugăciunea [As-Salat] și nu fiți dintre politeiști,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, '[Sau] dintre cei care au divizat religia lor și au devenit secte, fiecare ceată bucurându-se pentru ceea ce are ea[7]!', '[7] Credințe, opinii, obiceiuri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'Dacă-i atinge pe oameni un rău, atunci Îl cheamă ei pe Domnul lor, întorcându-se căiți către El. Apoi, după ce le dă să guste Îndurarea Sa, iată-i pe o parte dintre ei cum Îi fac Domnului lor asociați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'Fiind nemulțumitori față de ceea ce Noi le-am dat. „Bucurați-vă voi, dar în curând voi veți ști!...”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Sau le-am trimis Noi vreo dovadă care vorbește despre ceea ce ei I-au făcut Lui ca asociați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'Când le dăm Noi oamenilor să guste Îndurarea, atunci se bucură de ea, însă când îi lovește pe ei vreun rău pentru ceea ce au săvârșit mâinile lor mai înainte, atunci iată-i pe ei cum deznădăjduiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Oare n-au văzut ei că Allah oferă Daruri din belșug cui Voiește El sau le împuținează [cui Voiește El]? Întru aceasta sunt semne pentru un neam [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Așadar, dă celui care ți-e rudă apropiată ceea ce i se cuvine, ca și sărmanului și trecătorului de pe drum! Aceasta este mai bine pentru aceia care doresc Fața lui Allah. Și aceștia sunt cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'Ceea ce voi dați cu camătă pentru ca să se mărească pe seama averii oamenilor nu va spori la Allah, însă ceea ce voi oferiți ca Danie [Az-Zakat], dorind Fața lui Allah [Mulțumirea Sa], aceia vor avea înmulțit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Allah este Cel care v-a creat pe voi, apoi v-a dat vouă cele de trebuință, apoi vă face pe voi să muriți, apoi vă readuce pe voi la viață. Oare se află printre asociații voștri cineva care să facă ceva din acestea? Preamărire Lui! El este mai Presus de ceea ce Îi faceți voi ca asociați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'Stricăciunea [păcatele și nesupunerea față de Allah] s-a arătat pe uscat și pe mare, din pricina a ceea ce săvârșesc mâinile oamenilor, pentru ca [Allah] să-i facă pe ei să guste o parte din ceea ce ei au făcut. Poate că ei se vor întoarce!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'Spune [o, Mohammed]: „Purcedeți pe pământ și vedeți care a fost sfârșitul celor de mai înainte! Cei mai mulți dintre ei au fost politeiști!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'Îndreaptă fața ta către Religia cea dreaptă, înainte de a veni de la Allah o Zi ce nu poate fi respinsă! În Ziua aceea [oamenii] vor fi despărțiți[8]:', '[8] În cei destinați Paradisului și cei destinați Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Acela care nu crede va avea parte de necredința lui, iar aceia care au săvârșit fapte bune pentru sufletele lor pregătesc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'Pentru ca [Allah] să-i răsplătească pe cei care cred și săvârșesc fapte bune din mare Mila Sa. Cu adevărat, El nu-i iubește pe necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Și printre semnele Sale sunt [acela că El trimite] vânturile de bine vestitoare, pentru ca să vă facă să gustați din Îndurarea Sa și pentru ca să plutească la porunca Sa corăbiile, pentru ca să căutați Harul Său. Poate că voi veți fi mulțumitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'Noi am trimis Profeți la neamurile lor mai înainte de tine și le-au dus lor semne limpezi. Și Ne-am răzbunat Noi pe cei care au fost nelegiuiți și a fost o datorie pentru Noi ajutarea dreptcredincioșilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Allah este Cel care trimite vânturile și ele ridică Nori, iar El îi risipește pe Cer, așa după cum Voiește, și îi face pe ei bucăți și vezi atunci ploaia cum iese din mijlocul lor. Iar când îi atinge cu ea pe cine Voiește El dintre robii Săi, iată-i pe ei cum se bucură,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'Deși erau, înainte de a fi trimisă asupra lor - înainte de aceasta, încremeniți de disperare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Privește la urmările Îndurării lui Allah, cum învie El Pământul, după moartea lui. Cu adevărat, acesta este Cel care îi învie pe morți și El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'Însă dacă trimitem Noi un vânt și văd [ogorul lor] îngălbenit, rămân ei după aceea nemulțumitori[9].', '[9] Nerecunoscători pentru favorurile anterioare de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'Dar tu nu-i poți face pe morți să audă și nu-i poți face pe surzi să audă chemarea, dacă ei întorc spatele, fugind.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'Tu nu poți fi călăuzitor pentru cei orbi [îndepărtându-i] de rătăcirea lor. Tu nu-i poți face să audă decât pe cei care cred în Versetele Noastre și sunt cu totul supuși [musulmani].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Allah este Cel care vă creează pe voi în slăbiciune, apoi după slăbiciune vă dă putere, iar după putere dă slăbiciune și căruntețe, căci Allah creează ceea ce Voiește și El este Al-’Alim [Atoateștiutor] [și] Al-Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'Și în Ziua în care va sosi Ceasul vor jura nelegiuiții că ei nu au rămas decât un ceas. Așa sunt ei îndepărtați de la adevăr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'Însă cei care au fost dăruiți cu învățătură și credință vor spune: „Voi ați rămas, după hotărârea lui Allah, până în Ziua Învierii și aceasta este Ziua Învierii, însă voi nu ați știut.”[10].', '[10] Nu ați recunoscut adevărul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Și în Ziua aceea nu le va fi de niciun folos dezvinovățirea acelora care au fost nelegiuiți și nici nu vor fi ei chemați să caute Îndurarea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'Am dat Noi în acest Coran tot felul de exemple pentru oameni, însă [o, Mohammed] dacă le aduci lor un semn, cei care nu cred spun: „Voi nu sunteți decât niște înșelători!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'Așa pecetluiește Allah inimile celor care nu știu[11].', '[11] Cei care nu doresc să afle adevărul și îl refuză');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'Însă fii răbdător. Cu adevărat, făgăduința lui Allah este Adevăr! Și să nu te clintească cei care nu cred!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'Alif, Lam, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Acestea sunt Versetele Cărții celei pline de Înțelepciune[2].', '[2] A se vedea 10:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, '[În ele sunt] călăuzire și Îndurare pentru cei care fac bine,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'Care împlinesc Rugăciunea [As-Salat], achită Dania [Az-Zakat] și care cred în Viața de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'Aceștia au călăuzire [dreaptă] de la Domnul lor și aceștia vor fi cei care vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'Dar printre oameni sunt și [unii] care cumpără poveștile deșarte[3] pentru a rătăci cu ele de la calea lui Allah, fără de știință, și pentru a o lua în derâdere. Aceia vor avea parte de pedeapsă înjositoare.', '[3] Ceea ce nu are niciun beneficiu. Diferiți companioni le-a descris ca fiind politeism (Șirk), povești mincinoase, cântece frivole sau muzică, însă acestea includ tot ceea ce îl distrage sau îndepărtează pe om de la Coran și de la pomenirea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Iar atunci când i se recită lui Versetele Noastre, el se întoarce de la ele semeț, de parcă nici nu le-ar auzi, ca și când ar avea în urechile sale o greutate . Vestește-i lui un chin dureros!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Aceia, însă, care cred și săvârșesc fapte bune vor avea parte de Grădinile fericirii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'Și veșnic vor rămâne în ele. Făgăduința lui Allah este adevărată, iar El este Al-’Aziz [Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'El a creat Cerurile fără stâlpi pe care voi să-i puteți vedea și a răspândit [înfigând] în Pământ munți trainici, pentru ca el să nu se clatine cu voi și a împrăștiat pe el tot felul de vietăți. Și am coborât Noi din Cer ploaia și am făcut să crească pe el perechi de plante folositoare de tot felul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'Aceasta este creația lui Allah! Arătați-mi Mie ce au creat aceia pe care [i-ați luat] în locul Lui. Dimpotrivă, cei nelegiuiți sunt în rătăcire învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'Noi i-am dat lui Luqman înțelepciunea, [spunând]: „Adu-I mulțumiri lui Allah, căci cel care aduce mulțumire nu aduce mulțumire decât pentru sine, pe când cel care este nemulțumitor [să știe că] Allah cu adevărat [Își este îndeajuns Sieși] Ghaniyy și nu are nevoie de nimic și El este Hamid [Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'Și [spune, o, Mohammed] când Luqman i-a spus fiului său, sfătuindu-l pe el: „O, fiule! Nu-I face lui Allah asociat. Cu adevărat, facerea de asociați este fărădelege mare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Noi l-am povățuit pe om [să facă bine] părinților săi. Mama lui l-a purtat, [suportând pentru el] slăbiciune după slăbiciune, iar înțărcarea lui a fost după doi ani. Adu-Mi mulțumire Mie și părinților tăi, căci la Mine este întoarcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'Dar dacă se străduiesc pentru ca tu să-Mi faci ca asociat altceva, despre care tu nu ai cunoștință[4], atunci nu te supune lor! Poartă-te cu ei în această lume, cu dreptate, dar urmează calea acelora care se întorc către Mine, căci apoi la Mine este întoarcerea și Eu vă voi Vesti ceea ce ați făcut!”', '[4] A se vedea 29:8');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, '[Și Luqman a spus] „O, fiul meu! De ar fi [ceva] de greutatea unui bob de muștar și s-ar afla ascuns într-o stâncă, sau în Ceruri sau (oriunde) pe Pământ, Allah îl va scoate la iveală, iar Allah este Latif [Binevoitor] [și] Khabir [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'O, fiul meu! Împlinește Rugăciunea [As-Salat], poruncește fapta bună, oprește de la ceea ce este rău și rabdă ceea ce vine asupra ta. Cu adevărat, aceasta este dintre lucrurile hotărâte [de Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'Și nu-ți întoarce fața ta de la oameni[5] și nu păși pe pământ cu aroganță. Cu adevărat, Allah nu-l iubește pe cel trufaș și mândru!', '[5] Întorcându-le spatele, ci, dimpotrivă, respectă-i uitându-te la ei și fiind atent la ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'Fii cumpătat în mersul tău și scoboară glasul tău, căci cel mai urât dintre toate este glasul măgarului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Oare nu vedeți voi că Allah v-a supus vouă câte sunt în Ceruri și câte sunt pe Pământ și v-a copleșit pe voi cu binefacerile Sale – atât cele văzute cât și cele ascunse? Și sunt unii dintre oameni care discută despre Allah fără știință, călăuzire și fără Carte care să-i lumineze!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'Și când li se spune lor : „Urmați ceea ce a trimis Allah!”, atunci ei spun: „Ba noi urmăm cele cu care i-am găsit pe părinții noștri!” Chiar dacă-i cheamă Șeitan la pedeapsa văpăii?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Cel care supune fața sa lui Allah și este binefăcător, s-a prins de toarta cea mai trainică. La Allah se află sfârșitul [tuturor] lucrurilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'Iar cel care nu crede, să nu te întristeze necredința lui. La Noi este întoarcerea lor și [atunci] Noi le vom vesti ceea ce au făcut ei. Allah este Bineștiutor al celor ascunse în piepturi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'Noi le dăm lor bucuria numai pentru puțin [timp], apoi îi vom sili pe ei la chin aspru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'Însă dacă îi întrebi: „Cine a Creat Cerurile și Pământul?”, ei vor răspunde: „Allah!” Spune: „Laudă lui Allah!” Dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'Ale lui Allah sunt cele din Ceruri și de pe Pământ. Cu adevărat, Allah este Al-Ghaniyy [Deajuns pentru Sine] [și] Al-Hamid [Vrednic de Laudă]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Și de s-ar schimba în calemuri toți copacii de pe pământ iar marea [ar fi cerneală] de s-ar vărsa în ea șapte alte mări [de cerneală], Cuvintele[6] lui Allah tot nu s-ar termina. Allah este Al-’Aziz [Puternic] [și] Al-Hakim [Înțelept].', '[6] A se vedea 18:109');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Crearea voastră și învierea voastră nu sunt [pentru Allah] decât [la fel de ușoare] ca pentru un singur suflet! Allah este Sami’ [Cel care Aude Totul] [și] Basir [Cel care Vede]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Oare nu vezi că Allah face să intre noaptea în zi și face să intre ziua în noapte și că El a supus Soarele și Luna, fiecare alergând până la un termen hotărât, și că Allah este Bineștiutor a ceea ce faceți voi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'Aceasta pentru că Allah este Adevărul, iar ceea ce cheamă ei în locul Lui sunt vorbe deșarte și pentru că Allah este Al-’Aliyy [Cel Înalt] [și] Al-Kabir [Cel Mare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Oare nu vezi că din Harul lui Allah corăbiile plutesc pe mare, spre a vă arăta vouă din semnele Sale? Cu adevărat, întru aceasta sunt semne pentru oricine este răbdător și mulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'Și dacă-i învăluie pe ei valurile, asemenea umbrelor, atunci Îl cheamă ei numai pe Allah, cu credință față de religia Lui, iar după ce-i izbăvește pe ei, [aducându-i] pe uscat, atunci unii dintre ei sunt șovăitori și nimeni nu tăgăduiește semnele Noastre, în afară de cel viclean și de cel nemulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'O, voi oameni, fiți cu frică față de Domnul vostru și temeți-vă de o Zi în care niciun părinte nu-i va putea fi fiului său de ajutor și niciun fiu nu-i va fi de ajutor părintelui său, cu nimic. Cu adevărat, făgăduința lui Allah este Adevăr. Și să nu vă înșele pe voi viața lumească și să nu vă înșele pe voi cel amăgitor [Șeitan] în privința lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Numai la Allah se află Cunoașterea Ceasului. El face să coboare ploaia îmbelșugată și El Știe ce se află în pântece. Niciun suflet nu știe ce va dobândi mâine și niciun suflet nu știe în care [loc de pe] pământ va muri. Allah este ‘Alim [Atoateștiutor] [și] Khabir [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Alif, Lam, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Revelarea acestei Cărți în care nu există nicio îndoială este de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Ei spun: „El [Mohammed] a plăsmuit-o!” Dimpotrivă, ea este Adevărul de la Domnul tău [o, Mohammed], pentru ca tu să previi un popor, căruia nu i-a venit niciun prevenitor mai înainte de tine. Pentru ca ei să fie călăuziți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Allah este Cel care a creat Cerurile și Pământul, precum și ceea ce se află între ele, în șase zile, și apoi S-a înălțat deasupra Tronului[2]. Voi nu aveți în afara Lui ocrotitor și nici mijlocitor. Oare voi nu vreți să luați aminte?', '[2] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'El cârmuiește toate lucrurile din Cer și de pre Pământ. Apoi vor urca ele la El într-o zi a cărei măsură este de o mie de ani, după cum numărați voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'Acesta este Știutorul lumii celor nevăzute și a celor văzute, Al-''Aziz [Atotputernic] [și] Ar-Rahim [Îndurător],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, 'Care a făcut desăvârșit tot ceea ce a creat. Așadar, [El] a creat omul din lut, la început,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'Apoi i-a făcut pe urmașii lui dintr-o apă anume disprețuită [sperma].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'Apoi l-a plăsmuit pe el și a suflat în el duhul[3][sufletul creat de Allah pentru acea persoană]. Și v-a dat vouă auzul, ochii și inimile. Însă voi îi aduceți atât de puțin mulțumire!', '[3] A se vedea 15:29');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'Și ei spun: „Oare când noi ne vom pierde [dezintegra] în pământ, vom mai fi noi făcuți din nou?” [Desigur], dar ei nu cred în întâlnirea cu Domnul lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'Spune: „Vă va lua Îngerul morții căruia i-au fost încredințate sufletele voastre, dar apoi veți fi aduși înapoi la Domnul vostru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'Și de i-ai vedea tu pe nelegiuiți atunci cu capetele plecate înaintea Domnului lor, spunând: „Doamne, noi am văzut și am auzit. Lasă-ne pe noi să ne întoarcem, ca să săvârșim fapte bune, căci noi credem acum cu tărie!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'Dacă Noi am Voi, i-am da fiecărui suflet călăuzire, dar Cuvântul Meu [pe care îl merită necredincioșii] se va adeveri: „Voi umple Iadul cu djinni și oameni, adunați la un loc!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, '„Gustați, așadar, pentru că voi ați uitat întâlnirea cu această zi a voastră! Și Noi v-am uitat pe voi. Gustați chinul cel veșnic pentru ceea ce ați făcut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'Ci numai aceia cred în Versetele Noastre, care, atunci când ele le sunt pomenite, cad, prosternându-se, și aduc Laudă și Slavă Domnului lor, fără ca ei să fie semeți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Când coastele lor părăsesc culcușurile, pentru a-L chema pe Domnul lor cu frică și cu nădejde și ei fac milostenie din cele cu care i-am înzestrat[4].', '[4] Pentru cauza lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'Dar niciun suflet nu știe ce-i este ascuns ca bucurie, drept răsplată pentru ceea ce a săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'Dar oare cel care crede este asemenea cu cel care nu crede? Nu, ei nu sunt deopotrivă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'În ce-i privește pe cei care cred și săvârșesc fapte bune, ei vor avea parte de grădinile Sălașului ca răsplată pentru ceea ce au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'În ce-i privește pe cei care sunt necredincioși, sălașul lor va fi Focul și ori de câte ori vor încerca să iasă din el, vor fi împinși înapoi în el și li se va zice lor: „Gustați chinul Focului, pe care voi l-ați tăgăduit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'Însă Noi le vom da lor să guste din chinul cel mai apropiat[5], înainte de chinul cel mare, pentru ca ei să se întoarcă.', '[5] Calamitățile acestei vieți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Și cine este mai nelegiuit decât acela căruia i se pomenesc Versetele Domnului său, iar el se întoarce apoi de la ele? Noi suntem pedepsitori față de cei nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Noi i-am dat lui Moise Cartea - deci nu te îndoi de întâlnirea cu el[6]. Și Noi am făcut-o [Tora] îndreptare pentru Fiii lui Israel.', '[6] Întâlnirea profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) cu profetul Moise în noaptea de al-Mi`raj');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Și Noi am făcut dintre ei ocârmuitori care să călăuzească după porunca Noastră, câtă vreme ei s-au arătat (statornici și) răbdători și au crezut cu tărie în semnele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Cu adevărat, Domnul tău este Cel care va hotărî între ei în Ziua Învierii cu privire la cele asupra cărora au păreri deosebite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Oare nu au luat ei pildă de la neamurile pe care Noi le-am făcut să piară mai înainte de ei și prin ale căror locuințe umblă? Întru aceasta sunt semne! Oare ei nu aud?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Oare ei nu văd că Noi mânăm apa în pământul cel uscat și din ea facem să se ivească semănături, din care mănâncă vitele lor și ei înșiși? Oare ei nu văd?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'Și ei zic: „Și când va fi această victorie[7], dacă voi spuneți adevărul?”', '[7] Sau „decizie”, adică judecată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'Spune [o, Mohammed]: „În ziua victoriei nu le va fi de niciun folos credința acelora care nu cred și nu li se va da lor niciun răgaz!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Deci, întoarce-te de la ei și așteaptă, căci ei sunt în așteptare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'O, Profetule! Fii cu frică de Allah și nu da ascultare necredincioșilor și ipocriților, căci Allah este ''Alim [Atoateștiutor] și Hakim [Înțelept]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'Și urmează ceea ce îți este revelat de către Domnul tău, căci Allah este bine știutor a ceea ce săvârșiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'Și încrede-te în Allah, căci El este suficient ca orânduitor al lucurilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Allah nu i-a dat omului două inimi înlăuntrul său și nu le-a făcut pe soțiile voastre, de care voi vă despărțiți[1], să fie asemenea mamelor voastre. Și nu i-a făcut pe copiii voștri înfiați să fie asemenea fiilor voștri [biologici]. Acestea sunt cuvinte ce ies din gurile voastre, însă Allah spune Adevărul și El călăuzește pe drumul cel drept.', '[1] Prin expresia: „Tu ești pentru mine precum spatele mamei mele”. Un astfel de jurământ făcut pentru a nu mai avea relații cu soția era o practică pre-islamică declarată de către Allah un păcat pentru care era necesară ispășirea așa cum este descris în 58:3-4');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Chemați-i[2] după părinții lor, căci astfel este mai cu dreptate față de Allah. Iar dacă nu-i cunoașteți pe părinții lor, atunci socotiți-i frați ai voștri întru credință și aliați ai voștri! Și nu este niciun păcat pentru ceea ce săvârșiți voi din greșeală, ci numai pentru ceea ce inimile voastre săvârșesc cu bună știință. Allah este Ghafur [Iertător], Rahim [Îndurător].', '[2] Pe copiii aflați în grija voastră');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Profetul este [mai apropiat și] mai îndreptățit față de dreptcredincioși decât își sunt ei înșiși, iar soțiile sale sunt mamele lor. Rudele de sânge sunt mai îndreptățite între ele [în privința succesiunii], după Cartea lui Allah, decât dreptcredincioșii [de la Medina] și decât însoțitorii lui emigranți [de la Mecca], afară de ceea ce [voiți] să dați ca binefacere aliaților voștri și aceasta se află scrisă în Carte[3].', '[3] Tabla bine Păstrată (al-Lauh al-Mahfuth)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'Și [spune, o, Mohammed,] când am luat noi legământ cu Profeții și cu tine, cu Noe, cu Avraam, cu Moise și cu Iisus – fiul Mariei – și am luat de la ei legământ puternic,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'Ca El să-i întrebe pe cei sinceri [pe Mesagerii și Profeții Lui] despre sinceritatea lor [transmiterea Mesajului]! Iar pentru cei necredincioși a pregătit El o pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'O, voi cei care credeți! Aduceți-vă aminte de Harul lui Allah asupra voastră când a venit oștirea asupra voastră și când Noi am trimis asupra lor un vânt și o oștire [de Îngeri] pe care voi nu ați văzut-o. Și Allah este Cel care Vede ceea ce voi împliniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, '[Adu-ți aminte] când ei au venit la voi de deasupra voastră și de sub voi și când ochii voștri au fost tulburați și inimile v-au ajuns în gât și v-ați făcut voi fel de fel de gânduri îndoielnice în privința [făgăduinței] lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'Atunci au fost dreptcredincioșii încercați și au fost zdruncinați puternic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'Și [adu-ți amine] când au zis ipocriții și aceia în ale căror inimi era boală [îndoială]: „Allah și Trimisul Său nu ne-au promis nouă decât numai deșertăciune!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Și când au zis o parte dintre ei: „O, voi, popor din Yathrib[4]! Nu este loc pentru voi! Deci întoarceți-vă!” Și au cerut atunci un grup dintre ei îngăduința Profetului, zicând: „Casele noastre sunt neprotejate!”, în vreme ce ele nu erau neprotejate, însă ei voiau numai să fugă.', '[4] Numele orașului Medina înainte de venirea Profetului (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'De s-ar fi intrat peste ei prin laturile lui [orașului] și de li s-ar fi cerut fără să fie expuși să se răzvrătească [urmând necredința], ei ar fi făcut-o fără să fi rămas decât numai puțin [timp],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'Însă ei făcuseră mai înainte legământ față de Allah să nu se întoarcă, fugind, și va trebui să dea socoteală pentru legământul față de Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'Spune [o, Mohammed]: „Nu vă va fi de niciun folos fuga, dacă voi veți fugi de moarte [fără luptă] sau de ucidere [în luptă], și atunci nu v-ați bucura voi [de viață] decât puțin [timp]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'Spune: „Cine este acela care vă va apăra pe voi de Allah, dacă El vă va vrea un rău sau dacă El vă va dori vouă îndurare?” Nu vor găsi pentru ei [aceia care-și încalcă legământul față de Allah] ocrotitor și ajutor afară de Allah!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Allah îi Cunoaște pe aceia dintre voi care pun piedici[5] și pe acei [ipocriți] care le spun fraților lor: „Veniți la noi!”[6], în vreme ce ei nu participă la luptă decât numai puțini dintre ei[7],', '[5] Care îi conving pe alții să nu îl sprijine pe Profet (pacea și binecuvântarea lui Allah fie asupra sa) în bătălie
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, '[Fiind] zgârciți cu voi. Și când teama vine, îi vezi pe ei cum privesc la tine cu ochii rotindu-se, ca cel care este copleșit de moarte [din cauza spaimei]. Iar când teama se duce, atunci vă rănesc pe voi cu limbi ascuțite, zgârciți cu fapta bună. Aceștia nu au crezut niciodată și, de aceea, Allah zădărnicește faptele lor, căci acest lucru este ușor pentru Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, 'Ei cred că aliații nu au plecat[8]. Iar dacă aliații vin [încă o dată], doresc ca ei să meargă prin deșert printre beduini și să întrebe despre voi [de cât mai departe]. Și de ar fi printre voi, nu ar lupta ei decât [foarte] puțin.', '[8] Din cauza fricii lor excesive ipocriții lași nu puteau crede că forțele inamice au fost învinse');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Ați avut voi în Trimisul lui Allah un exemplu frumos, pentru cel care nădăjduiește în [întâlnirea cu] Allah și în Ziua de Apoi și Îl pomenește pe Allah mereu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'Și când i-au văzut dreptcredincioșii pe aliați, au zis: „Aceasta este ceea ce ne-au făgăduit Allah și Trimisul Său. Adevăr au grăit Allah și Trimisul Său”. Și nu a făcut aceasta decât să le sporească lor credința și supunerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'Între dreptcredincioși sunt oameni care au fost sinceri în legământul pe care l-au făcut față de Allah, unii dintre ei l-au împlinit [murind], iar alții dintre ei așteaptă fără să schimbe nimic [din legământul lor],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'Pentru ca Allah să-i răsplătească pe cei sinceri pentru sinceritatea lor și să-i chinuiască pe cei ipocriți, dacă El Voiește, sau să accepte căința lor, căci Allah este Ghafur, [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Și Allah i-a alungat înapoi pe cei care nu au crezut, cu toată furia lor. Ei nu au dobândit niciun bine. Allah este de ajuns pentru dreptcredincioși în luptă, căci Allah este Qauiyy [Puternic] [și] ''Aziz [Tare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'El i-a lăsat pe cei care i-au ajutat dintre oamenii Cărții[9] să coboare din cetățile lor și a aruncat spaimă în inimile lor. Pe o parte dintre ei i-ați omorât [dintre bărbați], iar o altă parte dintre ei i-ați luat în captivitate [femei și copii].', '[9] Evreii din Bani Quraydah, care au încălcat tratatele lor cu musulmanii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'El v-a dat vouă spre moștenire ținutul lor, casele lor, averile lor și un pământ pe care voi nu l-ați mai călcat niciodată. Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'O, Profetule! Spune-le soțiilor tale: „Dacă vă doriți voi această viață și podoabele ei, atunci veniți, căci eu vă voi da vouă mijloacele cele necesare și vă voi da vouă dezlegare [prin divorț], după cuviință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'Iar dacă Îl voiți voi pe Allah, precum și pe Trimisul Său și Casa de Apoi, atunci Allah a pregătit pentru cele binefăcătoare dintre voi răsplată mare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'O, voi soții ale Profetului! Aceea dintre voi care va săvârși o faptă rușinoasă va avea parte de un chin ce i se va spori îndoit, căci aceasta este pentru Allah [un lucru] ușor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'Însă aceleia dintre voi care arată supunere față de Allah și față de Trimisul Lui și împlinește fapte bune îi vom da Noi răsplată îndoită și îi vom pregăti daruri alese.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'O, voi soții ale Profetului! Voi nu sunteți ca nici una dintre femei. Dacă sunteți pioase, nu vă arătați binevoitoare [față de bărbați], cu vorba, pentru ca acela care are o boală în inimă să nu poftească la voi, și spuneți vorbe potrivite!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'Ședeți în casele voastre și nu vă arătați [frumusețea], așa cum se arătau în vremea Jahiliyyei de mai înainte! Împliniți Rugăciunea [As-Salat], achitați Dania [Az-Zakat] și fiți cu supunere față de Allah și Trimisul Său! Allah Voiește să țină departe de la voi, o, neam al [Profetului], rușinea și să vă purifice pe voi întru totul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'Și luați aminte Versetele lui Allah care sunt recitate în casele voastre și Înțelepciunea[10]! Allah este Latif [Cel Binevoitor] [și] Khabir [Bineștiutor].', '[10] Învățăturile Profetului (pacea și binecuvântarea lui Allah fie asupra sa) sau Sunnah lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Musulmanilor și musulmanelor, dreptcredincioșilor și dreptcredincioaselor, celor supuși și celor supuse, celor iubitori de adevăr și celor iubitoare de adevăr, celor răbdători [și statornici] și celor răbdătoare [și statornice], celor smeriți și celor smerite, celor ce dau milostenii și acelora [dintre femei] care dau milostenii, celor care postesc și acelora [dintre femei] care postesc, celor care își păzesc castitatea lor și acelora [dintre femei] care și-o păzesc, celor care-L pomenesc pe Allah mereu și acelora [dintre femei] care-L pomenesc, Allah le-a pregătit iertare și răsplată mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Nu se cuvine ca un dreptcredincios și nicio dreptcredincioasă să mai aleagă, dacă Allah și Trimisul Său au hotărât în privința lor un lucru. Iar acela care se răzvrătește împotriva lui Allah și a Trimisului Său se află în rătăcire învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'Și [adu-ți aminte, o, Mohammed,] când i-ai spus celui asupra căruia Allah Și-a trimis Harul Său[11], cum și tu ai trimis harul tău asupra lui: „Păstreaz-o pentru tine pe soția ta și fii cu frică de Allah!”. Tu ai ținut ascuns în sufletul tău ceea ce Allah a Voit să descopere[12]. Tu te-ai temut de oameni[13], măcar că Allah este mai Vrednic să te temi de El[14]. Apoi, când Zayd a întrerupt orice legătură cu ea, Noi ți-am dat-o ție să-ți fie soție, pentru ca dreptcredincioșii să nu mai aibă reținere în privința soțiilor fiilor lor adoptivi, dacă aceștia întrerup orice legături cu ele. Și Porunca lui Allah trebuie să fie împlinită.', '[11] Referindu-se la sclavul eliberat al Profetului (pacea și binecuvântarea lui Allah fie asupra sa), Zayd bin Harithah
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Nu este niciun păcat pentru Profet întru ceea ce i-a poruncit Allah[15]. Aceasta este Legea lui Allah pentru aceia care au fost mai înainte. Porunca lui Allah este o hotărâre hărăzită.', '[15] Sau permis lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'Aceia care transmit Mesajele lui Allah și se tem de El și nu se tem de nimeni afară de Allah [să știe că] Allah este de ajuns pentru a ține socoteala [la toate].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Mohammed nu este tată nici unuia dintre bărbații voștri, ci el este Trimisul lui Allah și încheietorul Profeților, și Allah este Atoateștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'O, voi cei care credeți, pomeniți-L pe Allah mereu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'Și slăviți-L pe El dimineața și după-amiaza [timpul de Asr]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'El este Cel ce vă binecuvântează, ca și Îngerii Săi, pentru ca să vă scoată pe voi din întunecimi la lumină. Și El este cu dreptcredincioșii Îndurător.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'Salutul lor în ziua când Îl vor întâlni va fi „Pace!”, iar El le-a pregătit lor o răsplată generoasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'O, Profetule, cu adevărat, Noi te-am trimis ca martor, ca binevestitor, ca prevenitor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'Și ca un chemător [al oamenilor] la Allah, cu Voia Lui, și ca o candelă luminoasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'Vestește dreptcredincioșilor că ei vor avea de la Allah mare Îndurare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'Nu da ascultare necredincioșilor și ipocriților, nu da atenție răutății lor și încrede-te în Allah, căci Allah este de ajuns ca Ocrotitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'O, voi cei care credeți! Dacă vă căsătoriți cu dreptcredincioase și apoi divorțați de ele, înainte să le fi atins, voi nu le puteți impune o perioadă de așteptare. Dați-le lor lucruri de care să se bucure și lăsați-le pe ele libere, după cuviință!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'O, Profetule! Noi îți îngăduim ție soțiile tale, cărora tu le dai zestre, precum și pe acelea care se află sub stăpânirea dreptei tale, pe care Allah ți le-a dăruit ca pradă, precum și pe fiicele unchiului tău după tată și pe fiicele mătușii tale după tată, pe fiicele unchiului tău după mamă și pe fiicele mătușii tale după mamă, care au purces împreună cu tine, și asemenea orice femeie dreptcredincioasă, dacă se dăruiește [întru căsătorie] ea însăși Profetului, dacă acceptă Profetul să o ia în căsătorie, acesta este un privilegiu numai pentru tine, fără de [ceilalți] dreptcredincioși. Noi Știm ceea ce le-am impus lor în privința soațelor lor și a acelora pe care le stăpânesc dreptele lor, ca să nu fie nicio stânjeneală pentru tine, iar Allah este Ghafur, [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'Tu [Mohammed] poți lăsa să aștepte pe cine voiești dintre ele[16] și tu poți primi la tine pe cine voiești. Și nu este niciun păcat pentru tine, dacă tu chemi la tine una dintre cele pe care le-ai îndepărtat. Acesta este [lucrul] cel mai apropiat pentru ca ochii lor să se răcorească și pentru ca ele să nu se întristeze și să fie mulțumite cu ceea ce le-ai dat lor. Allah Știe ceea ce este în inimile voastre căci Allah este ‘Alim [Atoateștiutor] [și] Halim [Blând].', '[16] Pe cele menționate în versetul anterior ca fiind legale pentru Profet (pacea și binecuvântarea lui Allah fie asupra sa) sau soțiile sale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'El nu-ți mai îngăduie ție [o, Mohammed, să iei alte] femei apoi, nici să le schimbi pe ele cu alte soațe, chiar dacă îți place frumusețea lor – afară de cele pe care le stăpânește dreapta ta. Allah este peste toate Veghetor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'O, voi cei care credeți! Nu intrați în casele Profetului, decât dacă vi se dă vouă încuviințare, pentru o mâncare, fără să așteptați prepararea ei. Dar dacă sunteți chemați, atunci intrați, însă după ce ați mâncat, împrăștiați-vă, fără a zăbovi la povești. Aceasta îi pricinuia neplăcere Profetului și el se rușinează de voi [să vă poftească să ieșiți], însă Allah nu se rușinează [să vă spună] adevărul. Iar dacă le rugați pe ele pentru un lucru, atunci rugați-le de după o perdea. Aceasta este mai curat pentru inimile voastre și pentru inimile lor. Și nu se cade ca voi să-i pricinuiți vreo neplăcere Trimisului lui Allah, nici să vă căsătoriți vreodată cu soțiile sale, după el. Acesta ar fi pentru Allah un mare [păcat].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Dacă voi scoateți la iveală un lucru ori îl țineți ascuns, Allah este ‘Alim al tuturor lucrurilor [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Nu este niciun păcat pentru ele în privința părinților lor, copiilor lor, fraților lor, a fiilor fraților lor, fiilor surorilor lor, a femeilor lor, a acelora pe care le stăpânesc dreptele lor [sclavi]. Și fiți cu frică de Allah, căci Allah este Martor la toate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Allah trimite binecuvântări asupra Profetului și Îngerii se roagă [la Allah] pentru el. O, voi cei care credeți, rugați-vă pentru el și salutați-l pe el cu tot respectul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Cei care Îl supără pe Allah și Trimisul Său [spunând minciuni despre ei și acționând împotriva cerințelor islamului] vor fi blestemați de Allah în această lume și în Lumea de Apoi și El le va pregăti lor osândă umilitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'Iar cei care îi vor necăji pe dreptcredincioși și pe dreptcredincioase, fără ca ei să fi agonisit [ceva pentru care să merite aceasta], vor avea parte de ponegrire și de păcat învederat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'O, Profetule! Spune-le soțiilor tale și copilelor tale și femeilor dreptcredincioșilor să se învelească în jilbaburile[17] lor, căci astfel vor fi mai bine distinse să fie cunoscute[18] și să nu li se pricinuiască necazuri! Allah este Ghafur, [Iertător], Rahim [Îndurător][19].', '[17] Jilbabul este un veșmânt ce acoperă capul și ajunge până jos, acoperind astfel întregul corp al femeii
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Dacă nu vor înceta cei ipocriți și cei ce au boală în inimile lor[20] și cei ce seamănă zvonuri, [îndemnând la răzvrătire], în Medina, Noi te vom instiga împotriva lor și atunci nu-ți vor mai fi ei vecini în ea decât pentru puțin [timp],', '[20] Referitor aici la cei care fac adulter sau preacurvie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Blestemați vor fi ei și oriunde vor fi aflați, vor fi ei prinși și măcelăriți fără îndurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'Aceasta a fost legea lui Allah pentru cei care au trăit mai înainte și tu nu vei afla schimbare pentru Legea lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'Oamenii te întreabă despre Ceas. Spune: „Numai la Allah este Știința despre el!” Și de unde să știi? S-ar putea ca Ceasul să fie aproape.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Cu adevărat, Allah i-a blestemat pe necredincioși și le-a pregătit lor flăcările,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'Veșnic vor sălășlui în ele și nu vor găsi ocrotitor și nici sprijinitor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'Iar în ziua când fețele lor vor fi întoarse de pe o parte pe alta în Foc, ei vor spune: „Vai nouă! De I-am fi dat noi ascultare lui Allah și de i-am fi dat noi ascultare Trimisului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'Și ei vor spune: „Doamne, noi le-am dat ascultare stăpânilor noștri și mai marilor noștri[21], însă ei ne-au rătăcit pe noi de la drum!', '[21] Poate fi interpretat de asemenea ca „nobilii noștri sau bătrânii noștri”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'Doamne, dă-le lor pedeapsă îndoită și blestemă-i pe ei cu mare blestem.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'O, voi cei care credeți! Nu fiți ca cei care l-au defăimat pe Moise. Iar Allah l-a socotit pe el nevinovat de spusele lor și a fost el la Allah în mare cinste.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'O, voi cei care credeți! Fiți cu frică de Allah și spuneți vorbe adevărate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Pentru ca El să vă îndrepte faptele voastre și să vă ierte greșelile voastre! Acela care este cu supunere față de Allah și față de Trimisul Său va dobândi mare izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Cu adevărat, Noi am propus Cerurilor, Pământului și munților Sarcina[22] de a purta povara Adevărului, dar ele au refuzat să o poarte și le-a fost teamă de ea [de pedeapsa lui Allah], însă s-a încărcat omul cu ea, căci el este tare nedrept [față de el însuși] și tare neștiutor.', '[22] Acceptarea obligațiilor și ascultării față de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, '[Este[23] astfel] pentru ca Allah să-i osândească pe ipocriți și pe ipocrite, pe politeiști și pe politeiste. Însă Allah primește căința dreptcredincioșilor și dreptcredincioaselor. Allah este Ghafur, [Iertător], Rahim [Îndurător].', '[23] Motivul pentru care omenirii i-a fost permis să poarte Sarcina');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, '[Toată] Lauda [este a] lui Allah, Căruia Îi aparțin toate cele din Ceruri și cele de pe Pământ, și Lui I se cuvine toată Slava în Viața de Apoi! El este Al-Hakim [Cel Înțelept] [și] Al-Khabir [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'El știe ce intră în Pământ și ce iese din el, ce coboară din Cer și ce se suie la el. Și El este Ar-Rahim [Îndurător], Al-Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'Cei care nu cred spun: „Ceasul nu va veni la noi!” Spune: „Ba – [jur] pe Domnul meu! – el va veni la voi. [Allah este] Cel ce știe Necunoscutul.” Nu-I scapă nici măcar greutatea unui atom[1], nici din Ceruri, nici de pe Pământ. Și nimic - nici mai mic decât aceasta, nici mai mare – nu există fără să nu fie [înscris] într-o Carte deslușită (Al-Lauh Al Mahfuz).', '[1] Sau „greutatea unei furnici mici”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'Pentru ca El să-i răsplătească pe cei care cred și săvârșesc fapte bune, căci pentru ei este iertare și înzestrare generoasă;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'Însă, cei care se străduiesc să facă zadarnice[2] Versetele Noastre, vor avea parte de suferința unei pedepse dureroase.', '[2] Să le submineze credibilitatea cu scopul de a-l învinge pe Profet (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Și cei cărora li s-a dat știința văd că ceea ce ți s-a trimis de către Domnul tău este Adevărul care călăuzește către calea lui Al-''Aziz [Celui Puternic] [și] Al-Hamid [Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'Dar cei care nu cred spun: „Vreți să vă îndrumăm către un bărbat [către Mohammed] care vă vestește că, după ce vă veți fi făcuți voi fărâme împrăștiate, veți fi voi întorși la viață?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'A plăsmuit el minciună, punând-o pe seama lui Allah sau este el stăpânit de nebunie?” [Ba nu!] Iar cei care nu cred în Viața de Apoi vor avea parte de osândă pentru că ei sunt în rătăcire adâncă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Oare nu văd ei de dinaintea lor și din urma lor Cerul și Pământul? De am voi Noi, am face ca Pământul să se scufunde cu ei sau am face să cadă asupra lor bucăți din Cer. Întru aceasta se află semn pentru orice rob care se căiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Și Noi i-am dat lui David îndurare din partea Noastră. „O, voi munți, aduceți mărire, repetând împreună cu el, și voi păsări [asemenea]!” Și am muiat Noi fierul pentru el,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, '[Poruncindu-i lui:] „Fă cămăși de zale și îmbină bine verigile! Și săvârșiți lucruri bune [tu și neamul tău]! Eu sunt Basir [Veghetor] la ceea ce faceți voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'Și lui Solomon [i-am supus] vântul, încât mersul lui de dimineață a fost cât o lună de zile și mersul lui de seară a fost cât o lună de zile [într-o singură zi putea să parcurgă distanța echivalentă cu două luni de călătorie]. Și am făcut să curgă pentru el un izvor de aramă. Și printre djinni erau [unii] care munceau dinaintea lui, cu îngăduința Domnului său. Iar pe aceia dintre ei care se abăteau de la porunca Noastră îi făceam Noi să guste chinul Flăcărilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Îi lucrau lui ceea ce el voia: sanctuare[3] și statui[4], vase [pentru mâncat] cât bazinele și oale care se așează bine. [Am spus] „Lucrați, o familie a lui David, [după legea lui Allah], pentru a-I aduce mulțumire!” Dar puțini dintre robii Mei sunt mulțumitori.', '[3] Descrise de comentatori drept palate, locuințe sau locuri de rugăciune
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'Și când am hotărât Noi moartea lui [Solomon], nimic nu le-a arătat lor [djnnilor] moartea lui, afară de o vietate a pământului care a ros toiagul lui[5]. Și când s-a prăbușit, li s-a arătat djinnilor că, dacă ei ar fi știut cu adevărat necunoscutul, ei nu ar fi rămas în chinul umilitor [al robiei lor][6].', '[5] Pe care se sprijinea la momentul morții sale. O termită a continuat să roadă toiagul până când acesta s-a rupt
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Și a avut [poporul din] Saba'' în sălașul lor un semn: două grădini, în dreapta și în stânga. [Li s-a spus:] „Mâncați din darul Domnului vostru și aduceți-I Lui mulțumire! O țară bună [aveți voi] și un Stăpân Ghafur [Iertător] !”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'Însă ei s-au întors [refuzând] și Noi am trimis asupra lor înecul de la Al-''Arim [un potop venit din baraj] și le-am schimbat amândouă grădinile lor cu două grădini cu roade amare, tamarisc și câțiva jujubieri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'Aceasta le-am dat-o ca răsplată pentru că ei au fost necredincioși. Și oare răsplătim Noi [astfel pe altcineva] afară de cel necredincios?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'Și Noi am așezat între ei și între cetățile pe care le-am binecuvântat alte cetăți cunoscute[7] și am hotărât distanțele dintre ele [spunând]: „Mergeți între ele nopți și zile, în siguranță!”', '[7] În ținutul care este astăzi Siria și Palestina');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Însă ei au spus: „Doamne, depărtează mai mult distanțele noastre [neapreciind această binecuvântare]!” Însă ei au fost nedrepți față de ei înșiși, așa încât Noi i-am făcut legende[8] și i-am risipit pe ei, despărțindu-i. Întru aceasta se află semne pentru cel răbdător și mulțumitor!', '[8] Drept exemple sau pilde');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'Bănuiala[9] lui Iblis s-a adeverit prin ei[10] și ei l-au urmat pe el, afară de o parte dintre dreptcredincioși.', '[9] Că omenirea ar fi ușor ademenită de el
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'Și el [Iblis] nu a avut asupra lor putere. [Ei au fost încercați cu ispitele lui] numai pentru ca Noi să-l evidențiem pe cel care crede în Lumea de Apoi de acela care se îndoiește asupra ei. Iar Domnul tău, [o, Mohammed] este Hafiz [Atoatepăzitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'Spune [o, Mohammed]: „Chemați-i pe cei care voi ați pretins [că ar fi divinități] afară de Allah! Ei nu stăpânesc nici cât greutatea unui fir de colb în Ceruri și nici pe Pământ. Ei nu au nicio parte la acestea, iar El nu are nici un ajutor între ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Și nu este de niciun folos mijlocirea la El, în afară de cei cărora El le îngăduie, [ei așteaptă ] până când frica este îndepărtată din inimile lor[11], atunci ei spun: „Ce a spus Stăpânul vostru?” Și ei răspund: „Adevărul! El este Al-''Aliyy [Cel mai Înalt] [și] Al-Khabir [Cel Mare]”.', '[11] Ale Îngerilor cărora le va fi permis să mijlocească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'Spune: „Cine vă dăruiește cu cele de trebuință pe voi din Ceruri și de pe Pământ?” Spune: „Allah! Cu adevărat noi sau voi suntem ori pe un drum bun ori într-o rătăcire răzvedită”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'Spune: „Voi nu veți fi întrebați pentru păcatele ce le-am săvârșit, iar noi nu vom fi întrebați pentru cele pe care voi le săvârșiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'Spune: „Domnul nostru ne va aduna laolaltă, apoi va hotărî între noi cu dreptate, căci El este Al-Fattah [Marele Judecător] [și] Al-''Alim [Atoateștiutorul]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'Spune: „Arătați-mi-i pe cei pe care i-ați alăturat Lui ca asociați! Nicidecum! El este Allah Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Și Noi nu te-am trimis decât ca vestitor și prevenitor pentru toată lumea, însă cei mai mulți dintre oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'Și ei spun: „Când [se va împlini] această promisiune, dacă voi grăiți adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'Spune: „Voi aveți hotărâtă o Zi, pe care nu o puteți nici amâna cu un ceas, nici nu o puteți grăbi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'Dar cei care nu cred spun: „Noi nu vom crede în acest Coran și nici în acelea de dinaintea lui!” Dar de i-ai vedea pe nelegiuiți stând în picioare dinaintea Domnului lor, întorcându-și unii altora vorbe! Cei care au fost socotiți slabi le vor zice celor care s-au arătat trufași: „De n-ați fi fost voi [ocârmuitori], noi am fi fost credincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'Cei care s-au arătat trufași le vor zice celor care au fost socotiți slabi: „Oare noi v-am îndepărtat de la calea cea dreaptă, după ce ea v-a venit vouă? Ba voi ați fost nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'Iar cei care au fost socotiți slabi le vor zice celor care s-au arătat trufași: „Ba este mai degrabă vicleșugul vostru de zi și de noapte, când voi ne-ați poruncit să nu credem în Allah și să-I facem Lui semeni!” Și se vor umple ei de regret, când vor vedea pedeapsa. Și vom pune Noi lanțuri pe gâturile celor care nu au crezut. Și oare vor fi ei răsplătiți altfel decât după ceea ce au săvârșit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Și nu am trimis Noi niciun prevenitor în vreo cetate fără ca cei înstăriți din ea să nu zică: „Cu adevărat, noi nu credem în cele cu care ați fost trimiși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'Și ei[12] au spus: „Noi am avut mai multe bogății și mai mulți copii și noi nu vom fi chinuiți!”', '[12] Cei bogați în general sau oamenii din Mecca în mod specific');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'Spune: „Cu adevărat, Domnul meu dă din belșug sau împuținează cele de trebuință cui Voiește El, însă cei mai mulți oameni nu știu!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Nici averile voastre, nici copiii voștri nu sunt dintre lucrurile care vă vor aduce aproape de Noi, ci numai cei care au crezut și au săvârșit fapte bune vor avea parte de răsplată îndoită pentru ceea ce au făptuit și ei vor fi în siguranță în odăile de sus [ale Paradisului].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'Iar cei care se străduiesc să facă Versetele Noastre zadarnice[13], vor fi aduși la chin.', '[13] A se vedea 34:5');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'Spune: „Domnul meu dă din belșug cele de trebuință acelora care Voiește El dintre robii Săi sau le împuținează lor. Și pentru tot ceea ce dăruiți voi El vă va da vouă în schimb, căci El este Cel mai Bun dintre dăruitori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'Și într-o Zi, îi va aduna pe ei toți și apoi le va zice Îngerilor: „Aceștia v-au adorat pe voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'Însă ei vor răspunde: „Mărire Ție! Tu ești Ocrotitorul nostru, nu ei! Ei i-au adorat pe djinni; cei mai mulți dintre ei au crezut în aceștia!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'În Ziua aceea, nu-și vor putea ei aduce unul altuia nici folos nici vătămare și le vom zice Noi acelora care au fost nelegiuiți: „Gustați chinul Focului pe care voi l-ați tăgăduit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Și când li se recită lor Versetele Noastre limpezi, atunci ei spun: „Acesta nu este decât un om care voiește să vă îndepărteze pe voi de la cele pe care le-au adorat părinții voștri!” Și zic ei: „Aceasta nu este decât o minciună plăsmuită!“ Iar cei care nu au crezut în Adevăr spun, atunci când el vine la ei: „Acesta nu este decât vrăjitorie învederată!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'Noi nu le-am dat lor [arabilor] cărți ca să învețe din ele, nici nu le-am trimis lor mai înainte de tine [o, Mohammed,] vreun prevenitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'Cei de dinainte de ei [alte națiuni] i-au învinuit de minciună [pe Trimișii lor]. Dar la ei [la cei din neamul tău] nu a ajuns nici a zecea parte din ceea ce le-am dat lor. Ei, deci, i-au socotit mincinoși pe Trimișii Mei, dar și cum a fost lepădarea Mea [de ei]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'Spune: „Eu vă îndemn pe voi cu privire la un singur lucru: Să vă ridicați voi înaintea lui Allah [dorind adevărul] câte doi sau câte unul și apoi să cugetați [la viața lui Mohammad]! Tovarășul vostru [Mohammed] nu este stăpânit de duhul nebuniei, ci el nu este decât un prevenitor pentru voi înainte de o osândă aspră!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'Spune: „Eu nu am cerut de la voi nicio răsplată pentru călăuzirea voastră, căci răsplata mea nu este decât numai la Allah și El este la toate Șahid [Martor]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'Spune: „Cu adevărat, Domnul meu trimite Adevărul! El este Știutorul deplin al celor neștiute!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'Spune: „A venit Adevărul [Coranul și revelația lui Allah]! Minciuna nu mai poate să înceapă, nici să mai revină [vreodată]![14]', '[14] Însemnând că falsitatea a fost abolită');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'Spune: „Eu dacă rătăcesc, rătăcesc spre pierderea mea însumi, iar dacă sunt călăuzit, aceasta este prin ceea ce Allah îmi revelează mie, fiindcă El este Sami’ [Cel care Aude] [și] este Qarib [Apropiat]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'Și de i-ai vedea tu[15] când sunt cuprinși de spaimă, căci nu mai este scăpare pentru ei, și cum sunt ei luați dintr-un loc apropiat!', '[15] Dacă ar putea vedea Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'Și ei vor zice atunci: „Noi credem [acum]”! Dar cum ar mai putea ei primi [credința] într-un loc atât de îndepărtat[16],', '[16] În viața anterioară pe pământ când ar fi avut toate șansele, însă acum toate acestea s-au dus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'După ce mai înainte nu au crezut și au hulit necunoscutul dintr-un loc atât de îndepărtat?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'Și se va pune stavilă între ei și între ceea ce ei voiesc[17], întocmai cum s-a făcut cu semenii lor mai înainte, fiindcă ei s-au aflat în mare îndoială.', '[17] Însemnând obținerea credinței și beneficiile sale sau intrarea în Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Mărire lui Allah, Creatorul Cerurilor și al Pământului, Cel care a făcut Îngeri mesageri cu câte două aripi sau cu câte trei sau cu câte patru. El adaugă făpturii ceea ce Voiește, cu adevărat Allah este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Orice binecuvântare pe care o dăruiește Allah oamenilor ca Îndurare - nu poate fi interzisă de nimeni, iar ceea ce interzice El, nu mai poate permite nimeni, după El, căci El este Al-''Aziz [Atotputernic] [și] Al-Hakim [Înțelept]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'O, oameni! Aduceți-vă aminte de Îndurarea lui Allah asupra voastră! Oare mai este vreun alt creator afară de Allah care să vă dăruiască cu cele de trebuință pe voi din Cer și de pre Pământ? Nu există altă divinitate afară de El! Cum de puteți voi fi abătuți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'Și dacă te socotesc pe tine mincinos, au mai fost socotiți mincinoși și alți Trimiși înainte de tine. Și la Allah se întorc lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'O, oameni! Făgăduința lui Allah este Adevăr! Așadar, să nu vă înșele pe voi viața lumească și să nu vă amăgească pe voi, în privința lui Allah, [diavolul] cel amăgitor !', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Cu adevărat, Șeitan este pentru voi un dușman. Țineți-l, așadar, ca pe un dușman! El nu face decât să-i cheme pe susținătorii săi ca să fie oaspeți ai flăcărilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'Cei care nu cred, vor avea parte de chin aspru, iar cei care cred și împlinesc fapte bune, vor avea parte de iertare și de mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'Oare acela căruia i se împodobește fapta sa rea, încât o socotește bună, [este la fel cu acela care împlinește fapte bune]? Dar Allah duce în rătăcire pe cine Voiește El și călăuzește pe calea cea bună pe cine Voiește El. Deci nu lăsa să se petreacă sufletul tău în suspine pentru ei! Allah este Bine Știutor a ceea ce săvârșesc ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Allah este Cel care trimite vânturile ce ridică nouri, iar Noi îi conducem către un ținut mort și înviem cu ei Pământul, după ce a fost mort. Astfel va fi și Învierea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Cel care voiește onoarea [prin putere], la Allah este toată Onoarea[1]! La El se înalță cuvântul cel bun și El înalță fapta cea bună[2], iar aceia care uneltesc fapte rele, aceia vor avea parte de chin aspru, iar uneltirea acestora nu va izbuti.', '[1] A se vedea 4:139
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Și Allah v-a creat pe voi din țărână, apoi dintr-o picătură, apoi v-a făcut pe voi perechi. Și nicio femeie nu rămâne grea și nici nu naște decât cu Știrea Lui. Și nici unuia din cei care au parte de viață lungă nu i se dă mai mult și nu i se scade din viața lui, fără [ca aceasta să fie înscrisă] într-o Carte. Cu adevărat, acest lucru este pentru Allah ușor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Și cele două mări nu sunt la fel; una este bună, dulce, plăcută la băut, iar cealaltă este sărată și amară. Și totuși din fiecare [dintre cele două] mâncați carne proaspătă și scoateți podoabă pe care o purtați. Și tu vezi corăbiile despicând apa pentru ca voi să căutați Îndurarea Sa. Poate că voi veți fi mulțumitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'El lasă ca noaptea să intre în zi și lasă ca ziua să intre în noapte. El a supus Soarele și Luna și fiecare deplasându-se către un termen hotărât. Acesta este Allah, Domnul vostru. A Lui este Stăpânirea, iar aceia [idolii] pe care voi îi chemați în locul Lui nu stăpânesc nici cât pielița sâmburelui de curmală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Dacă îi chemați, ei nu aud chemarea voastră și chiar dacă ar auzi-o, tot nu v-ar răspunde vouă. Iar în Ziua Învierii, ei vor tăgădui că i-ați făcut asociați [lui Allah]. Și nimeni nu te poate învăța așa cum o face un Khabir [Bineștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'O, oameni! Voi sunteți sărmani [ aveți nevoie] de Allah, iar Allah este Ghaniyy [Cel Deajuns pentru Sine] [și] Hamid [Cel Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Dacă El ar voi, v-ar face să pieriți și ar aduce o creație nouă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'Căci acest [lucru] nu este greu pentru Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'Și nu va purta niciun suflet povara altuia. Iar dacă un suflet încărcat va chema după ajutor, nimic din povara sa nu va fi purtat [de altcineva], nici dacă ar fi o rudă apropiată. Tu îi previi numai pe cei care au frică de Domnul lor, atunci când ei nu sunt văzuți [de alți oameni], și care împlinesc Rugăciunea [As-Salat]. Iar acela care se curățește nu se curățește decât pentru sine însuși și la Allah este întoarcerea [finală].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Nu sunt la fel cel orb cu cel care vede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'Nici întunericul cu lumina,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'Nici umbra cu dogoarea[3].', '[3] A Soarelui sau a unui vânt dogoritor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'Și nu sunt la fel cei vii cu cei morți. Allah face să audă pe cine Voiește El, pe când tu nu-i poți face să audă pe cei din morminte[4].', '[4] Cele patru comparații date de Allah în Versetele 19-22 sunt cele ale unui credincios și al unui necredincios, diferite tipuri de necredință și credința (adevărată), Paradisul și Iadul și cei receptivi la călăuzire și cei nereceptivi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'Tu [Mohammed] nu ești decât un prevenitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Cu adevărat, Noi te-am trimis cu Adevărul, ca binevestitor și prevenitor, și nu este comunitate care să nu fi avut un prevenitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Și dacă te socotesc pe tine mincinos, [să știi că] și cei de mai înaintea lor i-au socotit mincinoși [pe trimișii lor], în vreme ce Trimișii lor le-au adus semne limpezi, cu Scripturile și cu Cartea cea luminoasă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'Apoi, Eu i-am apucat pe cei care nu au crezut și cum a fost mustrarea Mea [de teribilă]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'Oare nu vezi că Allah a făcut să coboare din Cer apă și că Noi am făcut apoi să iasă la iveală roduri cu felurite culori și că în munți sunt dâre albe și roșii, cu felurite culori, și stânci foarte negre?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'Tot astfel sunt și printre oameni și viețuitoare și vite cu felurite culori. Singurii ce se tem de Allah sunt cei dăruiți cu știință dintre robii Săi. Cu adevărat, Allah este ‘Aziz [Puternic] [și] Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'Cu adevărat, cei care recită Cartea lui Allah, împlinesc Rugăciunea [As-Salat] și fac milostenii din cele cu care i-am înzestrat, într-ascuns și pe față, vor nădăjdui într-un negoț care nu piere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'Pentru că El [Allah] o să le dea răsplata lor întreagă și o să mai și sporească din mare Mila Sa. Cu adevărat, El este Ghafur [Iertător] [și] Șakur [Mulțumitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'Și ceea ce ți-am revelat noi ție [o, Mohammed] din Carte este Adevărul, întărind ceea ce a fost mai înainte de ea. Allah este Khabir [Bineștiutor] [și] Basir [Limpede Văzător] al robilor Săi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Apoi, Noi am dat spre moștenire Cartea acelora pe care i-am ales dintre robii Noștri[5]. Printre ei sunt cei nedrepți cu ei înșiși, printre ei sunt unii care țin măsura și printre ei sunt alții care îi întrec cu faptele lor bune [pe toți ceilalți], cu Voia lui Allah. Aceasta este marea Îndurare.', '[5] Cei care l-au urmat pe Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Ei vor intra în grădinile Edenului și vor fi împodobiți în ele cu brățări de aur și mărgăritare, iar straiele lor vor fi din mătase, în ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'Ei vor zice: „Laudă lui Allah care a îndepărtat de la noi mâhnirea! Domnul nostru este Ghafur [Iertător] [și] Șakur [Mulțumitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'El este Cel care ne lasă pe noi să sălășluim în casa eternă [Paradisul], prin mare Mila Lui, și nu ne va ajunge în ea oboseala și nici nu ne va ajunge în ea neputința”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'Iar cei care nu au crezut vor avea parte de focul Iadului. [Moartea] nu le este destinată lor pentru ca ei să moară, dar nici nu li se va ușura chinul lor. Astfel îl răsplătim Noi pe fiecare necredincios.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'Și ei vor striga plângând acolo: „Doamne, scoate-ne pe noi[6], căci noi vom săvârși fapte bune, nu așa precum am făcut!” Dar oare nu v-am lăsat Noi să aveți parte de viață lungă pentru ca cel care a vrut să chibzuiască să poată chibzui? Și a venit la voi Prevenitorul. Deci gustați [pedeapsa voastră]! Iar pentru cei nelegiuiți nu este ajutor!', '[6] Sensul este „Întoarce-ne pe noi la viața anterioară”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Cu adevărat, Allah este Știutorul celor necunoscute din Ceruri și de pe Pământ. El este Știutorul celor ascunse înlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'Allah este Cel care v-a făcut pe voi urmași pe Pământ. Cel care este necredincios, împotriva lui se va întoarce necredința sa. Iar necredința celor necredincioși nu sporește decât mânia Domnului lor și nu le sporește necredința celor necredincioși decât numai pieirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'Spune: „Îi vedeți pe asociații voștri[7] pe care voi îi invocați afară de Allah? Arătați-mi ce au creat ei pe Pământ? Sau au ei vreo parte în crearea Cerurilor? Sau lor le-am dat Noi vreo carte pe care ei să o [cunoască bine] și să o aducă ca evidență? [Nicidecum!] Dar nu-și făgăduiesc cei nelegiuiți unii altora decât numai înșelăciune.”[8]', '[7] Înțeles drept „Spune-mi despre...”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'Cu adevărat, Allah ține Cerurile și Pământul ca să nu se prăbușească. Iar dacă s-ar prăbuși, nimeni, după El, nu le-ar mai putea ține! El este Halim [Răbdător] [și] Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'Ei au făcut [mai înainte] jurăminte puternice, pe Allah, că de le va veni un prevenitor ei vor fi mai bine călăuziți decât orice altă comunitate [anterioară]. Dar când le-a venit lor un prevenitor [Mohammed], venirea lui nu a făcut decât să le sporească nesuferirea și mai mult,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'Semețindu-se pe pământ și prin viclenia celui șiret. Însă viclenia perfidă nu cuprinde decât neamul ei. Și oare așteaptă ei [altceva] decât rânduiala [soarta] popoarelor vechi? Dar nu vei găsi nicicând înlocuire pentru rânduiala lui Allah și nu vei găsi niciodată schimbare[9] în rânduiala lui Allah[10]!', '[9] Sau pedepsirea altora în locul lor.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Oare n-au purces ei prin lume și nu au văzut care a fost sfârșitul celor de dinaintea lor, deși au fost mai puternici decât ei?! Și nimic din Ceruri și de pe Pământ nu poate să scape de pedeapsa lui Allah. Cu adevărat, El este ''Alim [Atoateștiutor] [și] Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Iar dacă Allah i-ar pedepsi pe oameni pentru ceea ce au dobândit, n-ar mai lăsa pe fața lui [a Pământului] nicio vietate. Însă El îi păsuiește până la un termen hotărât și când va sosi termenul lor, atunci Allah va fi cu robii Săi Basir [Binevăzător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Ya-Sin[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, '[Jur] pe Coranul plin de Înțelepciune[2],', '[2] A se vedea 10:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'Cu adevărat tu [Mohammed] ești [unul] dintre Trimiși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, 'Pe un drum drept!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, '[Aceasta este] revelația lui Al-’Aziz [Celui Atotputernic] [și] Ar-Rahim [Îndurător],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'Pentru ca să previi un popor, ai cărui părinți nu au fost preveniți, iar ei sunt nebăgători de seamă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'Cuvântul [porunca] s-a adeverit deja pentru cei mai mulți dintre ei, dar ei nu vor crede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Cu adevărat, Noi am pus lanțuri pe gâturile lor și ele sunt până la bărbii, iar capetele lor sunt înălțate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'Și Noi am pus o stavilă dinaintea lor și o stavilă în urma lor și astfel le-am acoperit lor ochii și iată că ei nu mai văd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'Și le este totuna de-i previi ori nu-i previi, căci ei nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Tu îl previi numai pe cel care urmează Îndemnarea și se teme de Ar-Rahman [Cel Milostiv] în taină. Binevestește-i lui iertare și răsplată generoasă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Cu adevărat, doar Noi îi înviem pe cei morți și scriem ceea ce au făcut ei mai înainte, ca și ceea ce au lăsat în urmele lor, și toate lucrurile le-am enumerat într-o carte limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Și dă-le lor drept pildă pe locuitorii cetății, când au venit la ei Trimișii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'Când am trimis la ei doi [Mesageri], dar i-au socotit pe ei mincinoși. Atunci i-am întărit și cu un al treilea și au zis ei: „Cu adevărat, noi suntem Trimiși la voi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'Dar ei le-au răspuns: „Voi nu sunteți decât niște oameni ca și noi. Cel Milostiv [Ar-Rahman] nu a făcut să coboare nimic, iar voi nu faceți decât să mințiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, 'Însă [Trimișii le-]au zis: „Domnul nostru știe că noi suntem Trimiși la voi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, 'Iar noi nu suntem datori decât cu transmiterea limpede [a mesajului nostru]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'Ei [oamenii] au spus: „Cu adevărat, noi vedem un semn [prevestitor de] rău în voi. Dacă nu încetați, noi vă vom ucide cu pietre și vă va ajunge o pedeapsă dureroasă de la noi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, 'Le-au răspuns: „Semnul prevestitor [soarta] de rău să fie cu voi! Când ați fost preveniți [ați prevestit semnul rău]?... Ba nu, voi sunteți un popor care întrece măsura!…”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'Și de la capătul cetății a venit un bărbat, alergând, și a spus: „O, neam al meu, urmați-i pe Trimiși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'Urmați-i pe cei care nu cer răsplată și care sunt pe drumul cel bun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'De ce să nu-L ador eu pe Cel care m-a creat pe mine? Și la Care veți fi voi întorși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Să iau eu alți zei în locul Lui? [Pe când] Dacă Ar-Rahman [Cel Milostiv] va voi să-mi facă mie un rău, nu-mi va fi de niciun folos mijlocirea lor și ei nu mă vor putea salva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'Cu adevărat, eu aș fi într-o rătăcire învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'Cu adevărat, eu cred în Domnul vostru, deci ascultați de mine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'Și i se spune lui: „Intră în Rai!”[3] Iar el răspunde: “O, de ar ști poporul meu', '[3] O trecere rapidă către Viața de Apoi sugerează că omul a fost omorât în mod violent de necredincioși și a fost considerat martir pentru cauza lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'Că Domnul meu m-a iertat și m-a așezat pe mine între cei cinstiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'Și Noi nu am făcut să coboare asupra poporului său, în urma lui, vreo armată din Cer, căci nu a fost necesar [acest lucru].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'Nu a fost decât un singur strigăt[4] și iată-i pe ei stinși, fără viață.', '[4] De la Gavriil sau un strigăt din Cer');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'Vai, pentru robii [Mei]! Nu vine la ei niciun Trimis fără ca ei să-l batjocorească!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Nu au văzut ei câte neamuri am nimicit Noi înaintea lor? [Și nu au văzut ei că ele] nu se vor mai întoarce niciodată la ei[5]?!', '[5] La cei care trăiesc în prezent în această lume');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'Dar fiecare, toți la un loc vor fi aduși [înaintea] Noastră!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Și un semn pentru ei este Pământul cel mort, pe care Noi îl aducem la viață și scoatem din el grâne, din care ei mănâncă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Și Noi facem pe el grădini de palmieri și vii și facem să țâșnească din el izvoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'Pentru ca ei să mănânce din roadele Sale și din ceea ce au făcut mâinile lor. Oare ei nu vor fi mulțumitori?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Mărire Celui care le-a creat pe toate perechi, din ceea ce face Pământul să crească și din ei înșiși și din cele pe care ei nu le cunosc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'Și un semn pentru ei este și noaptea! Noi tragem din ea ziua și iată-i pe ei în întuneric,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'Iar Soarele aleargă către un sălaș al lui. Aceasta este rânduiala lui Al-’Aziz [Celui Atotputernic] [și] lui Al-’Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'Iar pentru Lună am orânduit Noi faze, până ce ea devine ca un ciorchine bătrân de palmier.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Nici Soarele nu se cuvine să ajungă Luna, nici noaptea nu poate să o ia înaintea zilei și toate plutesc pe orbite [proprii].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'Și un [alt] semn pentru ei este acela că Noi i-am purtat pe descendenții[6] lor într-o corabie încărcată', '[6] Însemnând „descendenți” sau „urmași”, făcându-se referire la descendenții lui Noe care au fost salvați de potop');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'Și le-am făcut lor altele asemenea ei, pe care ei se suie', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'Și de am Voi Noi, i-am îneca pe ei și ei nu ar avea niciun ajutor [ca să audă țipetele lor] și nici n-ar fi ei mântuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'Decât prin Îndurarea Noastră [îi lăsăm să mai trăiască] și să se bucure pentru un timp.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'Și dacă li se spune lor: „Fiți cu frică de ceea ce a fost înaintea voastră și de ceea ce este în urma voastră[7], poate că [astfel] vi se va arăta vouă îndurare!” [ei se semețesc].', '[7] De păcate sau de această viață sau de Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'Și nu le vine lor niciun semn dintre semnele Domnului lor fără ca ei să nu se îndepărteze de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'Și dacă li se spune lor: „Dăruiți din cele cu care Allah v-a înzestrat pe voi!”, aceia care nu cred grăiesc către aceia care cred: „Să-l hrănim noi pe cel pe care l-ar hrăni Allah, dacă ar Voi? Voi nu sunteți decât într-o rătăcire vădită!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'Și ei zic: „Și când se va împlini această amenințare, dacă voi spuneți adevărul?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'Ei nu au a aștepta decât un singur strigăt[8], care-i va apuca pe ei, în vreme ce ei se vor certa.', '[8] Primul strigăt din Trâmbiță ce va omorî toate creaturile vii fără nicio avertizare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'Și ei nu vor putea nici să facă vreo îndemnare, nici să se întoarcă la familiile lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'Și se va sufla în Trâmbiță[9] și iată-i pe ei grăbindu-se din morminte către Domnul lor', '[9] Pentru a doua oară, însemnând Învierea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Și ei vor spune: „Vai nouă! Cine ne-a sculat pe noi din culcușul nostru?” [Răspunsul va fi:] „Aceasta este ceea ce a făgăduit Ar-Rahman [Cel Milostiv], iar Trimișii au spus adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Nu va fi decât un singur strigăt și iată că ei toți vor fi aduși înaintea Noastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'Și în Ziua aceea nu va fi niciun suflet nedreptățit întru nimic și nu veți fi răsplătiți decât pentru ceea ce ați făcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Cu adevărat, locuitorii Raiului vor fi în Ziua aceea ocupați, bucurându-se fericiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Ei împreună cu soțiile lor, la umbră, vor fi rezemați pe divanuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'Acolo vor avea ei roade și [tot] ceea ce vor cere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, '[Și] „Pace!” Un cuvânt de la un Stăpân Îndurător', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, '[Și atunci El va spune:] „Iar voi, nelegiuiților, să stați despărțiți [de credincioși] în Ziua aceea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'Oare nu am făcut Eu legământ cu voi, o, fii ai lui Adam, să nu-l adorați pe Șeitan, căci el vă este vouă dușman învederat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'Și să Mă adorați pe Mine [pentru că] acesta este drumul drept?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'El a dus în rătăcire o mare parte dintre voi. Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'Acesta este Iadul care vi s-a promis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, '[Intrați în el și] ardeți astăzi în el, pentru că voi nu ați crezut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'În această Zi vom pecetlui gurile lor și ne vor grăi nouă mâinile lor, iar picioarele lor vor face mărturie pentru ceea ce ei au dobândit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Și de am fi Voit, am fi stins [orbit] Noi ochii lor și s-ar fi întrecut ei către drum [să-l găsească], dar cum ar mai fi putut ei să vadă?[10]', '[10] Allah ar fi putut să îl lase pe om fără mijloace de călăuzire în viața aceste lumi, deși, prin Mila Lui, El nu a făcut astfel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'Și de am fi Voit, i-am fi deformat Noi [încremenindu-i] în locurile lor și n-ar mai fi putut ei nici să meargă înainte, și nici înapoi[11].', '[11] Allah l-ar fi putut priva pe om de abilitățile care îi pot aduce beneficii, atât în această viață, cât și pentru Viața de Apoi, dar El nu a făcut acest lucru');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Și aceluia căruia îi dăruim Noi viață lungă, aceluia îi slăbim Noi înfățișarea[12]. Oare ei nu pricep?', '[12] În capacitate fizică și mentală');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Și Noi nu l-am învățat pe el [profetul Mohammed] poezia, căci aceasta nu s-ar fi cuvenit pentru el. Aceasta nu este decât îndemnare și un Coran limpede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'Pentru a-l preveni pe cel care este viu[13] și pentru a se împlini Cuvântul împotriva necredincioșilor.', '[13] În inimă și minte (credincioșii)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Oare ei nu văd că Noi le-am făcut lor, printre cele pe care le-au creat mâinile Noastre, vite, cărora ei le sunt stăpâni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'Și le-am făcut supuse lor și unele dintre ele le servesc pentru călărie, iar de la altele mănâncă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'Și au de la ele [și alte] foloase și băuturi. Oare ei nu vor aduce mulțumire?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'Și ei au luat în locul lui Allah alți zei [falși], în nădejdea că ei vor fi ajutați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'Dar nu le vor putea fi de niciun ajutor, și [ei înșiși] sunt pentru ei [pentru idoli ca] o oaste pregătită[14].', '[14] Protejându-și „zeii”. O altă interpretare este că ei (zeii) vor fi soldați ce vor lupta împotriva lor în Iad.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'Și să nu te mâhnească vorbele lor! Cu adevărat, Noi Știm atât ceea ce ei țin ascuns, cât și ceea ce ei mărturisesc pe față.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'Oare nu vede omul că Noi l-am creat pe el dintr-o picătură? Și dintr-o dată[15] el Ne este Nouă un dușman învederat.', '[15] Atunci când se poate descurca singur');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'El ne dă Nouă un exemplu[16], uitând de crearea sa și spune: „Cine le mai dă viață oaselor după ce ele sunt putrezite?”', '[16] Încercând să hotărască sfârșitul morții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'Spune: „Le va da lor viață Acela care le-a creat pe ele prima oară, căci El este Bineștiutor al întregii firi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, '[El este] Cel care a făcut pentru voi din pomul verde foc și iată că voi de la el aprindeți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Oare Acela care a creat Cerurile și Pământul nu are putința să creeze asemenea lor? Ba da! Și El este Al-Khallaq [Creatorul] Al-’Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'Și dacă Voiește El un lucru, Porunca Lui este numai să zică „Fii” și el este.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Laudă Celui în Mâna Căruia se află Stăpânirea tuturor lucrurilor! Și la El veți fi aduși înapoi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'Pe cei [Îngerii] ce se înșiră în rânduri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'Și pe cei care mână cu îndârjire [Norii]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'Și pe cei care transmit Îndemnarea[1]:', '[1] Profeților sau între ei. Allah jură pe aceste trei tipuri de Îngeri ceea ce este menționat în următorul verset');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'Cu adevărat, Domnul vostru este Unul Singur,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'Stăpânul Cerurilor și al Pământului și al celor dintre ele și Stăpânul răsăriturilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Cu adevărat, Noi am împodobit Cerul cel mai apropiat cu podoaba Stelelor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'Care apără împotriva oricărui șeitan răzvrătit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'Ei nu vor putea să tragă cu urechea la căpeteniile preaînalte și vor fi loviți din toate părțile[2],', '[2] De Meteoriți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'Pentru a fi alungați. Și ei vor avea parte de chin veșnic,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'În afară de cel care prinde din zbor [câteva cuvinte] și care este urmărit de o stea căzătoare, lucitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Întreabă-i pe ei [o, Mohammed] „Sunt ei o creație mai puternică decât cei pe care Noi i-am creat [cei din Ceruri ș.a.m.d.]?” Noi i-am făcut [pe oameni] dintr-un lut lipicios.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Ba nu, tu te miri [de obrăznicia lor], cum ei își bat joc [de tine și de Coran].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'Iar când li se pomenește [Coranul], ei nu iau aminte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'Iar dacă văd un semn, ei caută numai decât să-și bată joc [de el],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'Și spun: „Aceasta nu este decât vrăjitorie învederată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'Oare când vom muri și vom fi noi țărână și oseminte, vom mai putea noi să fim înviați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'Și la fel și primii noștri strămoși?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'Spune: „Da, și veți fi voi umiliți apoi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'Va fi numai un singur strigăt și iată-i pe ei cum privesc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'Zicând: „Vai nouă! Aceasta este Ziua Judecății!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, '[Li se va spune]: „Aceasta este Ziua Judecății de Apoi, pe care voi ați tăgăduit-o!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, '[Îngerilor li se va porunci:] „Adunați-i pe cei care au fost nedrepți și pe semenii lor, împreună cu cei pe care i-au adorat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'În locul lui Allah și duceți-i pe ei pe drumul Iadului!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'Și opriți-i pe ei, pentru că ei trebuie să fie întrebați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, '[Ei vor fi întrebați:] „Ce e [în neregulă] cu voi? De ce nu vă ajutați voi unii altora?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Dar în Ziua aceea vor fi ei supuși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'Și se vor întoarce unul către celălalt și se vor întreba [acuzându-se];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Vor zice: „Voi ați venit la noi cu dreapta!”[3]', '[3] Dintr-o poziție de putere sau de unde noi am fi acceptat adevărul, prevenindu-ne');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'Dar ei le vor răspunde: „Ba voi nu ați fost credincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'Iar noi nu am avut nicio putere asupra voastră, căci ați fost un popor de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'Deci s-a împlinit Cuvântul [hotărârea] Domnului nostru împotriva noastră și [acum] noi gustăm [pedeapsa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'Și v-am dus pe voi în rătăcire, căci și noi înșine am fost rătăciți.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'Și în Ziua aceea vor fi ei împreună la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'Cu adevărat, astfel facem Noi cu nelegiuiții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Cu adevărat, când li s-a spus lor „Nu există altă divinitate afară de Allah”, ei s-au semețit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'Spunând: „Să-i părăsim noi pe zeii noștri pentru un poet nebun?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'Însă el [profetul Mohammed] a venit cu Adevărul și a adeverit [Mesajele] Trimișilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Cu adevărat, voi [necredincioșilor] veți gusta voi chinul cel dureros', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'Și nu veți fi socotiți decât pentru ceea ce ați făcut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'În afară de robii lui Allah cei aleși;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'Ei vor avea parte de un dar bineștiut;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'Fructe[4]; și vor fi ei cinstiți', '[4] Însemnând tot ce este delicios');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'În Grădinile Fericirii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'Pe divanuri, așezați față în față,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'Și se va trece printre ei cu o cupă [de vin pur] umplută dintr-un izvor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'Albă, plăcută pentru cei ce beau,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'În ea nu va fi amețeală și nici nu se vor îmbăta din pricina ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 'Și vor avea lângă ei fete neprihănite, cu priviri scurte și cu ochi mari, frumoși[5],', '[5] Caste și modeste, care se uită doar la partenerii lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'Semănând cu niște ouă [fragile] păstrate cu grijă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'Și se vor întoarce unii spre alții, întrebându-se,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'Va spune unul dintre ei: „Eu am avut un prieten apropiat [pe pământ]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'Care spunea: „Tu ești dintre cei care cred cu adevărat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'Oare după ce am murit și ne-am făcut țărână și oseminte, ni se va mai cere nouă socoteală?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'El va spune[6]: „Vreți voi să priviți în jos?”', '[6] Companionilor săi din Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'Și va privi el și îl va vedea pe acela[7] în mijlocul Iadului.', '[7] Pe companionul care a încercat să îl convingă să nu creadă când erau în viața de pe Pământ');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'Și va spune el atunci: „ [Jur] Pe Allah! Aproape că mi-ai adus pieirea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Și de n-ar fi fost Îndurarea Stăpânului meu, aș fi și eu printre cei aduși [în Iad]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, '[Vor spune locuitorii Paradisului] Este adevărat că noi nu vom muri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'Decât cu moartea noastră cea dintâi și că nu vom fi noi chinuiți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Cu adevărat, aceasta este marea izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'Pentru așa ceva se cuvine să se străduiască aceia care se străduiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'Oare această ospeție [Paradisul] este mai bună sau pomul Zaqqum?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Cu adevărat, Noi l-am făcut ca o încercare pentru cei nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'Cu adevărat, este un pom care iese din fundul Iadului', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'Și roadele sale sunt ca niște capete de șeitani,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Iar ei sunt siliți să mănânce din ele, umplându-și pântecele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'Apoi, cu adevărat, vor avea ei, peste aceasta, un amestec de apă clocotită,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'Apoi, cu adevărat, întoarcerea lor va fi către Iad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Ei i-au aflat pe părinții lor în rătăcire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'Și iată-i alergând pe urmele lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'Căci și înainte de ei s-au aflat în rătăcire cei mai mulți dintre înaintașii lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'Și am trimis Noi prevenitori la ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'Însă privește care a fost sfârșitul celor preveniți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'Afară de robii cei aleși ai lui Allah:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'Noe Ne-a chemat pe Noi și Noi suntem Cei mai Buni dintre cei care răspund!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'Și l-am mântuit pe el împreună cu familia lui de nenorocirea cea mare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'Și i-am făcut pe urmașii săi singurii care au rămas [pe pământ]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'Și am lăsat Noi pentru neamurile care au venit după ei [această binecuvântare]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, '„Pace asupra lui Noe în toate veacurile!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Cu adevărat, astfel îi răsplătim Noi pe binefăcători.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'Cu adevărat, el a fost unul dintre robii Noștri dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'Apoi i-am înecat Noi pe ceilalți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'Printre cei care au urmat [calea lui Noe] s-a aflat Avraam,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'Când a venit el la Domnul său cu inima curată', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'Și când le-a zis tatălui său și poporului său: „Pe cine adorați voi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'Voiți voi, prin minciună, alți dumnezei afară de Allah?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'Ce credeți voi despre Stăpânul lumilor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'Și a aruncat el o privire spre Stele', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'Și a spus: „Cu adevărat, eu sunt [pe cale să devin] bolnav [prefăcându-se doar pentru ca ei să plece]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'Și s-au întors de la el, îndepărtându-se [fiindu-le teamă de boala sa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'Apoi s-a întors către zeii lor și le-a spus: „Voi nu mâncați?[8]', '[8] Ceea ce le era servit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'De ce nu vorbiți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'Apoi s-a năpustit asupra lor și i-a lovit cu mâna dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'Atunci s-au apropiat [oamenii] de el în fugă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, 'Și el le-a spus: „Vă închinați voi la ceea ce ciopliți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'În vreme ce Allah v-a creat pe voi, precum și ceea ce faceți voi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, 'Ei au spus: „Construiți pentru el un cuptor și aruncați-l în flăcări!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'Au voit să viclenească împotriva lui, dar Noi i-am făcut pe ei să fie cei mai umiliți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'Și a zis el, apoi: „Cu adevărat, eu mă duc la Domnul meu care mă va călăuzi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'Doamne, dă-mi [un copil] dintre cei evlavioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'Și Noi i-am dat bună veste despre un flăcău blând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'Și când [fiul său] a ajuns la vârsta la care putea lucra împreună cu el, a spus: „O, fiul meu! Cu adevărat, am văzut în vis că te voi jertfi. Vezi cum ți se pare?” I-a răspuns: „O, tată! Fă după cum ți se poruncește, căci mă vei afla pe mine - dacă va Voi Allah - printre cei răbdători!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'Și când s-au supus amândoi[9] și l-a întins pe el pe o tâmplă,', '[9] Poruncii lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Am strigat Noi la el: „O, Avraam!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'Tu ai împlinit vedenia.” Astfel îi răsplătim Noi pe cei care săvârșesc bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'Cu adevărat, aceasta a fost o încercare răzvedită', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Și l-am răscumpărat pe el printr-o jertfă minunată[10]', '[10] Allah a trimis un berbec uriaș pentru a fi sacrificat în locul lui Ismail');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'Și am lăsat Noi pentru neamurile care au venit după el [această binecuvântare]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, '„Pace asupra lui Avraam!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Cu adevărat, astfel îi răsplătim Noi pe cei care săvârșesc bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'Cu adevărat, el a fost dintre robii Noștri dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'Și i l-am vestit lui pe Isaac ca Profet, dintre oamenii cei evlavioși[11].', '[11] Aceasta arată că primul fiu care era menit să fie sacrificat era Ismail și nu Isaac, așa cum pretind evreii și creștinii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'Și l-am binecuvântat pe el și pe Isaac. Dar printre urmașii lor s-au aflat unii făcători de bine și alții lămurit nedrepți față de ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'Și, cu adevărat, Noi ne-am arătat mare Mila Noastră față de Moise și Aaron', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'Și, cu adevărat, i-am izbăvit pe ei doi, împreună cu neamul lor, de năpasta cea mare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'Și, cu adevărat, i-am ajutat pe ei și au fost ei biruitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'Și le-am dăruit lor Scriptura [Tora] cea deslușită', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'Și i-am călăuzit pe ei pe calea cea dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'Și am lăsat Noi pentru neamurile care au venit după ei [această binecuvântare]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, '„Pace asupra lui Moise și a lui Aaron!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Și, cu adevărat, astfel îi răsplătim Noi pe cei care împlinesc bine;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'Fiindcă ei doi au fost printre robii Noștri dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'Și, cu adevărat, printre Trimiși a fost și Elia,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Care i-a spus poporului său: „Vouă nu vă este frică?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Îl chemați voi pe Baal[12] și-l părăsiți voi pe Cel Mai Bun Creator?', '[12] Numele unui idol măreț adorat de oameni și care înseamnă „domn”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'Allah este Domnul vostru și Domnul părinților voștri cei dintâi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Însă ei l-au socotit pe el mincinos. Și vor fi ei aduși [la pedeapsă],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'În afară de robii cei aleși ai lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'Și am lăsat Noi pentru popoarele care au venit după el [această binecuvântare]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, '„Pace asupra lui Elia!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Cu adevărat, astfel îi răsplătim Noi pe cei care împlinesc bine,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'Iar el este dintre robii Noștri dreptcredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'Și, cu adevărat, a fost și Lot unul dintre Trimiși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Și l-am mântuit Noi împreună cu toată familia lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'În afară de o bătrână [soția lui] care s-a aflat printre cei rămași [alături de nelegiuiți],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'Apoi i-am nimicit pe ceilalți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'Iar voi treceți pe lângă ei dimineața', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'Și noaptea. Oare voi nu pricepeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'Și, cu adevărat, a fost și Iona printre Trimiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, '[Spune] când a alergat el la corabia încărcată', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'Și a tras la sorți[13] și a fost osândit [să fie aruncat]', '[13] Pentru a afla cine va fi aruncat peste bord pentru a-i salva pe ceilalți pasageri. Având prea mulți pasageri, corabia era pe punctul de a se scufunda');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'Și l-a înghițit peștele cel mare, pentru că el era vinovat[14]', '[14] Pentru că și-a pierdut speranța prea repede cu poporul său și a plecat fără a primi permisiunea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'Și de n-ar fi fost el printre cei care aduceau preamărire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'Ar fi rămas în burta lui până în ziua când vor fi înviați[15].', '[15] Însemnând că burta peștelui ar fi devenit mormântul lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, '[Însă] L-am aruncat Noi pe Pământul cel gol fiind el bolnav,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'Și am lăsat să crească peste el un lujer de dovleac[16]', '[16] Care este cunoscut a face umbră și a îndepărta muștele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'Și l-am trimis pe el[17] [ca Profet] la o sută de mii [de oameni] sau chiar mai mulți,', '[17] L-am întors apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'Iar ei au crezut și i-am lăsat pe ei să se bucure de viață până la un timp.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'Întreabă-i pe ei: „Oare are Domnul tău [numai] fiice și ei au fii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Sau i-am făcut Noi pe Îngeri femei și ei au fost martori?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Iată că ei din pricina nelegiuirii lor spun:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, '„Allah a zămislit!” Ba ei sunt mincinoși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'A ales El fiicele înaintea fiilor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Ce-i cu voi? Cum judecați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Oare voi nu chibzuiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Sau aveți voi o dovadă limpede?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Aduceți cartea voastră, dacă spuneți voi adevăr?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Au plăsmuit ei că între El și între dijnni ar fi înrudire, însă djinnii știu că ei [cei care au făcut aceste acuzații] vor fi aduși [pentru a fi pedepsiți].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Laudă lui Allah! El este mai Presus de ceea ce ei vorbesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'În afară de robii lui Allah cei aleși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Dar voi și aceia pe care îi adorați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'Nu veți putea fi ademenitori [pentru a-i rătăci pe credincioși]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'Decât cu cel care va arde în Foc[18].', '[18] Din cauza necredinței și a faptelor rele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, '[Îngerii spun][19] Și nu este niciunul printre noi care să nu aibă un loc cunoscut[20].', '[19] Dezmințind ceea ce necredincioșii au spus despre ei
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'Și, cu adevărat, noi suntem aranjați în rânduri [pentru rugăciune]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'Și, cu adevărat, noi suntem cei care aducem Laudă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'Și, cu adevărat, ei [necredincioșii] spuneau[21]:', '[21] Înainte de revelarea Coranului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, '„Dacă am fi avut noi o îndemnare de la înaintași,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'Am fi fost noi robi aleși ai lui Allah”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'Însă ei îl tăgăduiesc[22], dar în curând vor ști.', '[22] Coranul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'Cuvântul Nostru [porunca noastră] a fost rostit mai înainte față de robii Noștri cei trimiși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Că ei vor fi cei victorioși', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'Și, cu adevărat, că soldații Noștri [credincioșii] vor fi cei biruitori[23].', '[23] Dacă nu în această lume, atunci în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'Deci, [o, Mohammed] întoarce-te de la ei până la un timp!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'Și privește la ei, [atunci când îi lovește pedeapsa], căci atunci, și ei vor vedea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Oare vor ei să grăbească osânda Noastră?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Dar când va coborî ea în curtea lor, rea dimineață va fi pentru cei preveniți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'Întoarce-te de la ei până la un timp!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'Și privește la ei, [atunci când îi lovește pedeapsa], căci atunci, și ei vor vedea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Slavă Domnului tău, Stăpânul Puterii! El este mai Presus de ceea ce spun ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'Pace asupra Trimișilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'Și Laudă lui Allah, Stăpânul tuturor lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Sad[1]. Pe Coranul cel plin de povață![2]', '[1] A se vedea 2:1
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'Ba nu, cei care nu au crezut sunt [mai degrabă] în îngâmfare și schismă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Câte popoare am nimicit Noi mai înainte de ei! Într-un sfârșit ei au strigat, însă nu mai era timp pentru ei de mântuire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'S-au mirat ei că le-a venit un prevenitor [profetul Mohammed] chiar dintre ei, iar necredincioșii au zis: „Acesta este un vrăjitor mincinos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Oare a făcut el din zei un Dumnezeu Unic? Cu adevărat, acesta este un lucru ciudat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'Însă mai-marii lor au pornit să spună: „Mergeți voi înainte și rămâneți statornici la zeii voștri [în apărarea lor]! Cu adevărat, acesta este un lucru dorit![3]', '[3] Plănuit de profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) pentru a câștiga influență și prestigiu pentru el');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'Noi nu am auzit despre aceasta în ultima religie![4] Aceasta nu este decât o născocire!', '[4] Făcându-se referire la creștinism sau posibil la religia păgână a celor din Qurayș');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'Oare Pomenirea i-a fost trimisă tocmai lui, dintre noi [toți]?” Ei sunt în îndoială asupra Îndemnării Mele [Coranul]. Ba ei nu au gustat încă pedeapsa Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Ori au ei comorile Îndurării Domnului tău Al-’Aziz [Cel Puternic] [și] Al-Uahhab [Darnic]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Ori au ei Împărăția Cerurilor și a Pământului și a ceea ce se află între ele? Dacă-i așa, atunci să urce în Cer!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, '[Ei sunt doar] soldați [care vor fi] învinși acolo printre aliați [necredincioși].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'Mai înainte de ei au învinuit de minciună și popoarele lui Noe, lui ’Ad și lui Faraon, stăpânul țărușilor[5],', '[5] Cu care i-a torturat pe oameni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'Și [tribul lui] Thamud și neamul lui Lot și neamul din Al-Ayka. Aceștia sunt aliații![6]', '[6] Care au fost învinși, printre care vor fi și necredincioșii din Qurayș și alții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Nu a fost niciunul dintre ei care să nu-i fi socotit, pe Trimiși, mincinoși. Așadar, a fost dreaptă pedeapsa [Mea]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'Aceștia nu așteaptă decât un singur strigăt [al Trâmbiței], care va veni, fără întrerupere, [până ce îi va nimici pe toți].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'Ei spun: „Doamne, grăbește-ne nouă pedeapsa noastră, înainte de Ziua Judecății!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Fii răbdător cu ceea ce spun ei și adu-ți aminte de robul Nostru David, cel cu putere [în adorare și credință]; cu adevărat, el a arătat căință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Cu adevărat, Noi am supus munții să-L slăvească [pe Allah] împreună cu el, după-amiaza [târzie] și dimineața [după răsărit]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'Și păsările cele adunate! Toate se vor întoarce spre el [David] repetând [laudele]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'Și Noi am întărit stăpânirea lui și i-am dat lui înțelepciunea și judecata sănătoasă în vorbire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'Oare a ajuns până la tine vestea celor care se certau și care s-au cățărat pe zidul templului?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'Când au intrat la David și el s-a speriat de ei au zis ei: „Nu-ți fie frică! Noi suntem doi care ne certăm; unul dintre noi a fost nedrept cu celălalt. Deci judecă între noi cu dreptate și nu fi cu strâmbătate și călăuzește-ne pe noi pe calea cea dreaptă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'Cu adevărat, acesta este fratele meu. El are nouăzeci și nouă de oi, iar eu am o singură oaie. Și mi-a zis el: „Dă-mi-o în grija mea!” Și m-a biruit el cu vorba”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, '[David] a spus [în grabă, fără să-l asculte pe celălalt]: „El a fost nedrept cu tine, când ți-a cerut să împreuni oaia ta cu oile lui. Și mulți dintre cei care se asociază își încalcă unii altora drepturile, afară de aceia care cred și împlinesc fapte bune - dar cât de puțini sunt ei!” Și David a înțeles că Noi îl punem la încercare și s-a rugat de iertare Domnului său și a căzut, prosternându-se, și s-a căit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'Și i-am iertat Noi aceasta și el a avut parte de loc apropiat la Noi și de frumoasă întoarcere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, '[Noi am spus] „O, David! Noi te-am făcut pe tine urmaș pe pământ. Deci judecă între oameni cu adevăr și nu urma poftei care te abate de la calea lui Allah!” Cei care se abat de la calea lui Allah vor avea parte de osândă aspră, pentru că au uitat de Ziua Socotirii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Noi nu am făcut în deșert Cerul și Pământul și ceea ce se află între ele. Aceasta este bănuiala celor care nu au crezut. Dar vai necredincioșilor pentru Focul [care-i așteaptă]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'Oare să-i punem Noi pe cei care cred și împlinesc fapte bune împreună cu cei care fac stricăciuni pe Pământ sau să-i punem pe cei cu frică [de Allah] în rând cu nelegiuiții?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, '[Iată] o Carte binecuvântată pe care Noi ți-am trimis-o [o, Mohammed], pentru ca ei să ia aminte la Versetele ei și pentru ca cei care au pricepere să chibzuiască!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'Și i l-am dăruit Noi lui David pe Solomon, care a fost un rob prea bun și care a fost cu căință!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, '[Spune] când i s-au adus lui după-amiaza cai sprinteni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'Și a spus el: „Eu am fost înclinat către iubirea bunurilor [din această lume] într-atât încât [am uitat de] Pomenirea Domnului meu, până ce [Soarele] s-a ascuns în spatele vălului său [de întuneric];”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, '[El a spus] „Aduceți-i înapoi la mine!” Și s-a pornit el să le mângâie[7] picioarele și gâturile.', '[7] Cu sabia lui drept ispășire pentru păcatul său, sacrificându-i. Unele comentarii au sugerat de asemenea și înțelesul „mângâierii” cu mâna');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Și l-am încercat Noi pe Solomon și am aruncat pe tronul lui un trup[8]. Apoi s-a căit el.', '[8] Despre care se spune că este un diavol sau un corp fără viață (unul fără capabilitate), dar doar Allah Singurul Știe cel mai bine');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'A zis: „Doamne, iartă-mă pe mine și dăruiește-mi mie o stăpânire cum nu se mai cuvine nimănui după mine, căci Tu ești Al-Uahhab [Cel Darnic]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'Și i-am supus lui vântul, ca să alerge lin, după porunca lui, unde el voia,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'Ca și pe șeitani: pe toți ziditorii și cufundătorii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'Ca și pe alții legați în lanțuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, '[Noi am spus] „Acesta este Darul Nostru. Deci împarte-l sau păstrează-l, fără să dai nicio socoteală!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Și cu adevărat, el are la Noi un loc apropiat și frumoasă întoarcere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'Și adu-ți aminte de robul Nostru Iov, care L-a invocat pe Domnul său spunând: „Șeitan m-a atins pe mine cu nenorocire [năruindu-mi sănătatea] și cu suferință [năruindu-mi averea]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, '[I s-a spus] „Lovește [pământul] cu piciorul tău și [privește cum iese] o apă răcoroasă pentru spălat și pentru băut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'Și Noi i-am dat lui [înapoi] familia sa și încă pe atât, ca Îndurare de la Noi și ca îndemnare pentru cei care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, '[Noi am spus] „Și ia în mâna ta un mănunchi [de iarbă] și lovește cu el [spre soția ta] și nu încălca jurământul tău![9]” Și Noi l-am aflat statornic pe el! Un rob prea bun care se căiește!', '[9] La un moment dat în timpul bolii sale, Iov s-a mâniat pe soția lui și a jurat că dacă se însănătoșește o va pedepsi cu 100 de lovituri de bici. Conform instrucțiunilor lui Allah, jurământul a fost îndeplinit prin lovirea ei o dată cu 100 de fire de iarbă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'Și adu-ți aminte de robii Noștri Avraam, Isaac și Iacob - cei cu putere [în adorare și credință] și cu pricepere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Cu adevărat, Noi i-am ales pe ei și i-am deosebit printr-o trăsătură aleasă: Pomenirea [frecventă a] Vieții de Apoi [și pregătirea lor pentru ea prin împlinirea de fapte bune și chemarea oamenilor la aceasta].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'Și, cu adevărat, ei au fost la Noi printre cei mai buni aleși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'Și adu-ți aminte de Ismail, de Eliseu, și de Dhu-l-Kifl, căci toți au fost printre cei mai buni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Aceasta este o Pomenire, iar cei cu frică vor avea parte de frumos loc la întoarcere:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'Grădinile Edenului cu porțile deschise pentru ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'Unde, rezemați, vor cere ei fructe din belșug și băuturi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 'Și vor avea ei [fecioare] frumoase, cu priviri curate, toate de aceeași vârstă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'Aceasta este ceea ce vi se promite vouă [dreptcredincioșilor] pentru Ziua Socotirii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'Cu adevărat, acesta va fi darul Nostru [pentru voi] și el va fi fără de sfârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Astfel va fi! Însă nelegiuiții vor avea parte de cel mai rău loc de întoarcere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Iadul în care, vor arde! Și rău culcuș va fi el!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'Astfel va fi! Și vor gusta ei apă clocotită și puroi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'Și alte [pedepse] asemenea acesteia.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, '[Și atunci li se va zice nelegiuiților]: „Aceasta este o ceată ce intră grăbită împreună cu voi. Să nu aibă [această ceată] parte de bun venit, pentru că ea este sortită să ardă în Foc!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, 'Ei vor zice: „Ba voi nu veți avea parte de bun venit! Voi ați adus aceasta asupra noastră!” Ce rău culcuș va fi el!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'Vor zice ei: „Doamne, acelora care au adus aceasta asupra noastră, sporește-le pedeapsa îndoit, în Foc!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'Și ei vor zice: „De ce nu-i vedem pe bărbații pe care noi îi socoteam printre cei răi?[10]', '[10] Ei se referă la credincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'I-am luat noi în batjocură! Sau ochii noștri nu-i zăresc?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Aceasta este cu adevărat cearta neamului Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'Spune: „Eu sunt numai un prevenitor! Nu există nicio divinitate afară de Allah Al-Uahid [Cel Unic], Al-Qahhar [Stăpânul Atotputernic]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Stăpânul Cerurilor și a Pământului și al celor ce se află între ele, Al-’Aziz [Cel Puternic] [și] Al-Ghaffar [Mereu Iertător]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'Spune: „Aceasta este o veste măreață,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'Însă voi vă îndepărtați de la ea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'Eu nu am nicio cunoștință despre căpeteniile preaînalte [ale Îngerilor] când ele au avut disputa [în legătură cu crearea lui Adam],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'Mie nu mi s-a revelat decât că eu sunt un prevenitor limpede!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, '[Și spune] când Domnul tău le-a spus Îngerilor: „Eu voi crea un om din lut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'Și când Eu îl voi fi plăsmuit și voi fi suflat în el din Duhul Meu[11], voi să cădeți dinaintea lui, prosternându-vă [în semn de respect]!”', '[11] A se vedea 15:29');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Și s-au prosternat toți Îngerii laolaltă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'Cu excepția lui Iblis[12], căci el a fost arogant și a devenit unul dintre cei care au tăgăduit credința.', '[12] A se vedea 2:34');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, '[Allah] a spus: „O, Iblis! Ce te-a împiedicat pe tine să te prosternezi dinaintea a ceea ce Eu am plămădit cu Mâinile Mele[13]? Ai fost arogant [atunci] sau te-ai socotit tu [deja] printre cei înalți?”', '[13] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, '[Iblis] a spus: „Eu sunt mai bun decât el! Pe mine m-ai plămădit din foc, în vreme ce pe el l-ai plămădit Tu din lut!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, '[Allah] a spus: „Ieși din el [Paradis] și vei fi tu alungat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Și asupra ta se va abate blestemul Meu până în Ziua Judecății!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, '[Iblis] a spus: „Doamne, dă-mi mie răgaz până în Ziua când vor fi ei înviați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, '[Allah] a zis: „Vei fi printre cei păsuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'Până în Ziua timpului hotărât!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, '[Iblis] a spus: „Pe Puterea Ta [jur]! Eu îi voi duce în ispită pe toți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'În afară de robii Tăi cei devotați dintre ei!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, '[Allah] a spus: „Eu sunt Al-Haqq [Cel Drept]! Adevăr este ceea ce spun:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'Voi umple Iadul cu tine și cu toți cei care te-au urmat pe tine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'Spune [o, Mohammed]: „Eu nu vă cer pentru acesta [Coranul] nicio răsplată și eu nu sunt dintre prefăcuți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'El nu este decât Îndemnare pentru lumi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'Și voi veți cunoaște [adevărul despre] vestea lui, după un timp!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Revelarea Cărții [Coranului] [vine] de la Allah Al-’Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Cu adevărat, Noi ți-am trimis Cartea în tot adevărul, deci adoră-L pe Allah, arătându-I numai Lui credință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'Fără îndoială, lui Allah I se cuvine credința curată[1]. Iar cei care și-au luat ocrotitor în locul Lui [spunând]: „Noi nu-i adorăm pe ei decât pentru ca ei să ne apropie de Allah”, Allah va judeca între ei în cele în care ei nu se înțeleg. Cu adevărat, Allah nu-l călăuzește pe cel care este mincinos și nemulțumitor.', '[1] Allah nu acceptă ca altcineva să fie asociat cu El în adorare și ascultare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'De ar fi Voit Allah să-Și ia un fiu, El ar fi ales ceea ce ar fi Voit din ceea ce a creat. Laudă Lui! El este Allah Al-Uahid [Cel Unic] [și] Al-Qahhar [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'El a creat Cerurile și Pământul întru adevăr. El învăluie noaptea peste zi și ziua peste noapte. El a supus Soarele și Luna și fiecare grăbește până la un termen hotărât. El este Al-’Aziz [Cel Puternic] [și] Al-Ghaffar [Atoateiertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'El v-a creat pe voi [toți] dintr-un singur suflet. Apoi a făcut din el pe soția sa. Și v-a trimis vouă opt suflete de vite[2]. El vă creează în pântecele mamelor voastre, făptură după făptură, în trei întunecimi[3]. Acesta este Allah, Stăpânul vostru! A Lui este Împărăția! Nu există altă divinitate afară de El! Cum de vă abateți?', '[2] A se vedea 6:143-144
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Dacă nu credeți – cu adevărat, Allah se poate lipsi de voi, căci Lui nu-I place necredința robilor Săi. Însă dacă voi sunteți mulțumitori, aceasta Îi place Lui. Și nu va purta niciun [suflet] păcătos povara altuia. Apoi la Domnul vostru este întoarcerea voastră și El vă va vesti ceea ce ați făcut. Cu adevărat, El Știe ceea ce se află în înlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'Dacă pe om îl lovește o nenorocire, atunci el Îl cheamă pe Domnul său, căindu-se înaintea Lui. Apoi, când îi dăruiește lui Îndurare din partea Sa, uită cele cu care se rugase și Îi face lui Allah semeni, pentru ca să-i rătăcească [pe oameni] de la drumul Său. Spune: „Bucură-te pentru puțin [timp] de necredința ta, însă tu vei fi dintre oaspeții Focului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Oare cel care petrece timpul nopții în Rugăciuni, prosternându-se și stând în picioare, este cu teamă de Ziua de Apoi și Îl roagă de Îndurare pe Domnul său? Spune: „Oare sunt egali cei care știu cu aceia care nu știu?” Însă numai aceia care au minte trag învățăminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'Spune[4]: „O, robii Mei cei dreptcredincioși! Fiți cu frică de Domnul vostru! Cei care fac bine în această lume vor avea parte de bine. Pământul lui Allah este întins. Cu adevărat, cei statornici vor primi răsplata lor fără măsură!”', '[4] Profetul (pacea și binecuvântarea lui Allah fie asupra sa) este instruit să le spună în Numele lui Allah credincioșilor Săi robi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'Spune [o, Mohammed]: „Mi s-a poruncit mie să-L Ador pe Allah, arătându-I numai Lui credință!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'Și mi s-a poruncit să fiu primul dintre musulmani!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'Spune: „Cu adevărat, eu mă tem, dacă nu-I voi arăta supunere Domnului meu, de pedeapsa unei Zile cumplite!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'Spune: „Pe Allah [Unicul] Îl voi adora, curat în credința mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'Adorați ceea ce voiți afară de El! Spune: „Cei care pierd sunt cei care și-au pierdut sufletele lor și familiile lor în Ziua Învierii! Aceasta este pierderea învederată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'Ei vor avea deasupra lor umbre de foc și sub ei alte umbre!” Cu aceasta îi amenință Allah pe robii Săi. „O, robii Mei, fiți cu frică de Mine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'Dar cei care s-au ferit să-l adore pe Thagut[5] și s-au întors, căindu-se, la Allah - vor avea veste bună! Deci binevestește robilor Mei,', '[5] Satana sau orice alt obiect de adorare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'Care ascultă cuvântul și urmează ceea ce este cel mai bun în el! Aceștia sunt cei pe care îi călăuzește Allah și aceștia sunt cei cu pricepere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Oare pe cel împotriva căruia se adeverește cuvântul pedepsei, oare îl vei mai putea tu mântui când el se află deja în Foc?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'Însă cei care au fost cu frică de Domnul lor vor avea parte de odăi[6] peste care alte odăi au fost clădite. Pe sub ele vor curge pâraie. [Aceasta este] făgăduința lui Allah și Allah nu calcă făgăduința Sa.', '[6] Camere sau locuințe sau palate ridicate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Oare tu nu vezi că Allah trimite apă din Cer, apoi o îndreaptă ca izvoare în pământ, apoi scoate cu ajutorul ei roade de felurite culori, apoi ele se ofilesc și le vezi galbene, apoi le face bucățele. Cu adevărat, întru aceasta se află îndemnare pentru cei care au pricepere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Oare cel căruia i-a deschis Allah pieptul pentru Islam și care are lumină de la Domnul său [este ca cel a cărui inimă îl respinge]? Vai acelora cu inimile împietrite față de pomenirea lui Allah. Aceia se află într-o rătăcire învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Allah a trimis vestea cea mai frumoasă, ca o Carte [în care unele Versete] se aseamănă și se repetă. Pieile acelora care se tem de Domnul lor se înfioară la auzul ei; apoi se liniștesc pieile și inimile lor la pomenirea lui Allah. Aceasta este călăuzirea lui Allah; El călăuzește cu ea pe cine Voiește. Iar acela pe care Allah îl duce în rătăcire nu va avea niciun ocârmuitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Oare acela care în Ziua Învierii se va feri cu fața[7] sa de răul chinului? Și li se va spune celor nelegiuiți: „Gustați ceea ce ați agonisit!”', '[7] În locul mâinilor lui, care vor fi legate de gâtul său');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Au tăgăduit aceia de dinainte de ei și le-a venit lor chinul de acolo de unde ei nu se așteptau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Și le-a dat lor Allah să guste rușine în viața aceasta, iar pedeapsa din Viața de Apoi va fi și mai mare, măcar dacă ei ar ști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Și Noi le-am dat oamenilor în acest Coran tot felul de pilde, pentru ca ei să ia aminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'Un Coran arab, fără de nicio deviere[8], pentru ca ei să fie dreptcredincioși!', '[8] De la adevăr');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'A dat Allah ca exemplu un bărbat [rob] cu [stăpâni] asociați care se ceartă între ei [asupra lui] și un [alt] bărbat cu totul supus unui singur om. Oare sunt ei în aceeași situație? Laudă lui Allah! Dar cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'Tu vei muri [într-o zi] și vor muri și ei [într-o zi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'Apoi, în Ziua Învierii, vă veți certa voi între voi, înaintea Domnului vostru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Și cine este mai nedrept decât cel care minte împotriva lui Allah și socotește Adevărul drept minciună, atunci când vine la el?! Oare nu se află în Iad sălaș pentru cei necredincioși?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'Iar cel care a adus Adevărul [Profetul] și cel care îl crede - aceștia sunt cei evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'Ei au la Domnul lor ceea ce voiesc. Aceasta este răsplata celor care săvârșesc fapte bune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'Pentru ca Allah să le șteargă lor cele mai rele [fapte] pe care le-au săvârșit și să le dea răsplată după cele mai bune [fapte] pe care le-au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Oare nu este Allah de ajuns pentru robul Său [Profetul Mohammed]? Însă ei voiesc să te sperie cu aceia care ar fi în locul Lui. Dar acela pe care Allah îl duce în rătăcire nu va avea parte de ocârmuitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'Iar pe cel pe care îl călăuzește Allah nu va avea cine să-l ducă în rătăcire. Oare nu este Allah ’Aziz [Puternic] și Dătător de răzbunare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'Dacă tu îi întrebi „Cine a creat Cerurile și Pământul?”, ei vor răspunde: „Allah!”. Spune: „Îi vedeți voi[9] pe aceia pe care-i invocați, afară de Allah? Dacă Allah îmi Voiește mie un rău, pot ei să risipească răul Lui? Sau dacă El îmi Voiește o Îndurare, pot ei să împiedice Îndurarea Lui?” Spune: „Allah îmi este de ajuns și în El se încred aceia care se încred.”', '[9] Spuneți-mi despre...');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'Spune: „O, popor al meu! Lucrați voi după calea voastră și voi lucra și eu [după calea mea] și [curând] veți afla voi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'Asupra cui va veni chinul care îl înjosește și asupra cui se va coborî pedeapsa veșnică!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Cu adevărat, Noi ți-am trimis ție Cartea, pentru oameni, întru adevăr. Acela care este călăuzit, este numai pentru sine, iar acela care rătăcește, [o face] numai împotriva sa însuși, iar tu nu ești chezaș pentru ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Allah ia la Sine sufletele, la moartea lor, și pe cele care nu mor [le ia], în timpul somnului lor. El le ține la Sine pe acelea asupra cărora a hotărât moartea, iar pe celelalte le trimite [în trupurile lor] până la un timp hotărât. În aceasta sunt semne pentru un popor [de oameni] care chibzuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Oare au luat ei mijlocitori, afară de Allah? Spune: „Chiar și dacă ei nu au nicio putere și nu au nici minte?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'Spune: „A lui Allah este mijlocirea în întregime. A Lui este Împărăția Cerurilor și a Pământului și apoi la El vă veți întoarce!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Când este pomenit doar Allah singur, [fără asociați], se strâng inimile celor care nu cred în Viața de Apoi, iar când sunt pomeniți cei luați în locul Lui, atunci se bucură ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'Spune: „O, Allah, Creator al Cerurilor și a Pământului, Cunoscător al celor nevăzute și al celor văzute, Tu judeci între robii Tăi, asupra celor în care ei nu se înțeleg.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Dacă cei care sunt nelegiuiți ar avea tot ceea ce se află pe Pământ și încă o dată pe atât, laolaltă cu aceasta, [în zadar] le-ar oferi ei ca răscumpărare pentru [a scăpa de] chinuri în Ziua Învierii; li se va arăta lor de la Allah ceea ce ei n-au pus în socoteală niciodată,[10]', '[10] Mânia și pedeapsa Lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'Li se vor arăta relele pe care le-au agonisit și-i vor împresura pe ei cele de care și-au bătut joc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'Când îl atinge pe om o nenorocire, atunci Ne cheamă el. Apoi, după ce-i dăruim îndurare din partea Noastră, el spune: „Mi se cuvine pentru știința mea”. Dar aceasta este o încercare, însă cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Așa au grăit și cei de dinaintea lor și nu le-au fost de niciun folos cele pe care le-au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'Și i-au lovit pe ei consecințele rele a ceea ce au agonisit. Și pe cei care sunt nelegiuiți dintre aceștia [mecanii] îi vor lovi relele pe care le-au agonisit și nu se vor putea ei împotrivi Puterii [lui Allah].[11]', '[11] Nu Îl vor putea împiedica pe Allah de la ceea ce El dorește sau nu vor putea să scape de pedeapsă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Oare ei nu știu că Allah îl înzestrează cu prisosință pe acela care Voiește El sau îl înzestrează cu măsură? Cu adevărat, în aceasta sunt semne pentru un popor [de oameni] care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'Spune: „O, voi, robii Mei care ați întrecut măsura în defavoarea voastră, nu deznădăjduiți în privința Îndurării lui Allah.” Allah iartă toate păcatele[12]. Cu adevărat, El este Al-Ghafur [Iertător], Ar-Rahim [Îndurător].', '[12] Celor care se căiesc și se îndreaptă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'Întoarceți-vă cu căință spre Domnul vostru și supuneți-vă Lui, înainte de a veni chinul la voi, căci apoi nu veți mai putea fi voi mântuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'Și urmați cele mai bune [porunci] care v-au fost vouă trimise de către Domnul vostru, înainte de a veni la voi osânda pe neașteptate, fără ca voi să băgați de seamă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'Înainte să spună un suflet[13]: „Vai mie, pentru că nu am luat seama [la îndatoririle mele] față de Allah, fiindcă eu am fost printre batjocoritori!”', '[13] În Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Sau să spună: „Dacă Allah m-ar fi călăuzit, aș fi fost printre cei evlavioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Sau să spună, atunci când va vedea chinul: „O, dacă ar fi pentru mine întoarcere, astfel încât să fiu eu printre făcătorii de bine!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, '„Dar Versetele Mele au venit la tine și tu le-ai socotit mincinoase și ai fost arogant și ai fost printre cei necredincioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'În Ziua Învierii vei vedea tu chipurile celor care au mințit împotriva lui Allah, întunecate. Oare nu se află în Iad sălaș pentru cei aroganți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Și Allah îi va mântui pe cei care au avut frică de El prin ceea ce au dobândit[14]. Nu-i va atinge pe ei niciun rău și nu vor fi ei mâhniți.', '[14] Succesul lor în încercările vieții lumești și dobândirea Paradisului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Allah este Creatorul tuturor lucrurilor și El este peste toate Chezaș!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'El are cheile Cerurilor și ale Pământului, iar aceia care nu cred în Versetele lui Allah, aceia vor fi cei care pierd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'Spune [o, Mohammed]: „Îmi porunciți, voi, neștiutorilor, să ador pe altcineva afară de Allah?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'Vi s-a revelat ție și acelora de dinaintea ta: „De vei face asociați lui Allah, vor fi în zadar faptele tale și vei fi tu printre cei care pierd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Deci, adoră-L tu pe Allah și fii dintre cei care aduc mulțumire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Ei nu L-au prețuit pe Allah după cum se cuvine[15], deși în Ziua Învierii întregul Pământ va fi [în] Pumnul Său, iar Cerurile vor fi adunate în Mâna Sa Dreaptă. Mărire Lui! El este mai Presus de ceea ce Îi fac ei asociați!', '[15] Nu I-au apreciat Atributele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'Și atunci când se va sufla în Trâmbiță, vor fi nimiciți toți cei care se află în Ceruri și pre Pământ, afară de cei care va Voi Allah. Apoi se va sufla în ea a doua oară și iată-i pe ei în picioare, așteptând.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'Și va străluci Pământul în Lumina Domnului său, va fi așezată cartea [cu faptele] și vor fi aduși Profeții și martorii și se va face judecată între ei cu dreptate și ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'Și va fi răsplătit fiecare suflet după ceea ce a săvârșit, căci El Știe mai bine ceea ce fac ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Și vor fi mânați cei care nu au crezut, în cete, către Iad, iar când vor ajunge la el se vor deschide porțile sale și păzitorii lui le vor spune: „Oare nu au venit la voi Trimiși, chiar dintre voi, ca să vă recite Versetele Domnului vostru și să vă prevină pe voi despre întâlnirea voastră cu această Zi?” Ei vor spune: „Ba da! Însă s-a adeverit cuvântul despre pedeapsa împotriva necredincioșilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'Se va spune: „Intrați pe porțile Iadului; veșnic veți fi în ea sălășluitori!” Și cât de rău va fi sălașul celor trufași!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'Și vor fi conduși cei care au fost cu frică de Domnul lor spre Rai, în cete, iar când vor ajunge la el, li se vor deschide porțile lui și le vor spune păzitorii lui: „Pace asupra voastră! Voi ați fost buni, intrați pentru a fi în veci sălășluitori în el!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'Și vor spune ei: „Slavă lui Allah, care a împlinit făgăduința Sa față de noi și ne-a făcut pe noi să moștenim Pământul, ca să putem locui în Paradis oriunde vom voi!” Minunată este răsplata celor care au săvârșit [fapte bune]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'Și îi vei vedea tu pe Îngeri înconjurând Tronul, slăvindu-L pe Domnul lor și aducându-I laude. Se va judeca între ei după dreptate și se va spune: „Slavă lui Allah, Stăpânul lumilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Ha'', Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Revelarea Cărții [Coranul] este de la Allah Al-’Aziz [Cel Puternic], Al-’Alim [Știutor],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Iertătorul păcatelor, Primitorul căinței, Cel aspru la pedeapsă, Dătătorul de Îndurare. Nu există altă divinitate afară de El și la El este întoarcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'Nu se împotrivesc față de semnele lui Allah decât cei care nu cred. Așadar, să nu te înșele umbletul lor prin țări [pentru că sfârșitul lor va fi în Iad]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'Mai înainte de ei, i-au socotit mincinoși [pe Trimișii lor] poporul lui Noe, și după ei și alte grupuri, și fiecare comunitate se gândea cum să-l piardă pe Trimisul ei, și ei au luat ca argument neadevărul pentru a tăgădui cu el Adevărul și de aceea i-am lovit Eu. Și cum a fost pedeapsa Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'Astfel s-a adeverit cuvântul [soarta] Domnului tău împotriva celor care nu au crezut: „Ei vor fi oaspeții Focului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Cei[2] ce poartă Tronul și cei care-l înconjoară Îl preamăresc pe Domnul lor, aducându-I laudă, cred în El și cer iertare pentru cei care cred [spunând]: „Doamne! Tu cuprinzi toate lucrurile cu Îndurarea și Știința Ta. Așadar, iartă-i pe cei care Îți cer iertare, se căiesc și urmează calea Ta și păzește-i de chinul Iadului,', '[2] Îngerii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'Doamne! Și fă-i pe ei să intre în grădinile Edenului, pe care Tu le-ai promis, ca și pe cei care au fost evlavioși dintre părinții lor, soțiile lor și urmașii lor, căci Tu ești Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'Și păzește-i pe ei de cele rele! Iar acela pe care-l păzești de rele, în Ziua Aceea, de acela Te-ai îndurat. Și aceasta este marea izbândă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Cu adevărat, celor care nu cred li se va spune [de către Îngeri atunci când vor fi mânați spre Foc]: „Mânia lui Allah a fost mai mare față de voi [când ați respins Mesajul] decât ura voastră față de voi înșivă [acum în Iad] - atunci când erați chemați la credință, iar voi stăruiați în necredință!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'Ei vor spune: „Doamne, ne-ai dat nouă moarte de două ori și ne-ai dat nouă viață de două ori, deci mărturisim păcatele noastre. Oare există vreo cale de ieșire?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, '[Li se va spune:] „Aceasta este pentru voi, pentru că atunci când a fost invocat numai Allah Singur, voi nu ați crezut, în timp ce, atunci când I s-au făcut Lui asociați, atunci ați crezut voi. Însă Judecata este la Allah Al-''Aliyy [Cel Înalt] [și] Al-Kabir [Mare].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'El este Cel care vă arată semnele Sale și face să coboare pentru voi din Cer cele de trebuință. Dar nu se lasă îndemnat decât acela care se căiește și se întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Deci chemați-L pe Allah, cu credință numai în El, chiar dacă aceasta le displace necredincioșilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'El este Cel mai Presus, cu Însușiri fără egal, Stăpânul Tronului; El trimite Duhul, prin Porunca Sa [relevația], asupra aceluia care Voiește El dintre robii Săi, pentru ca să prevină asupra Zilei întâlnirii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'Ziua în care ei se vor arăta fără ca nimic să-I fie ascuns lui Allah în privința lor. [Și atunci se va grăi]: „A cui este Împărăția în Ziua aceasta?” [Allah Însuși va răspunde:] „ A Lui Allah, Al-Uahid [Cel Unic] [și] Al-Qahhar [Atotputernic]!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'În Ziua aceea, fiecare suflet va fi răsplătit, după cum își va fi agonisit. Nu va fi nedreptate în Ziua aceea. Cu adevărat, Allah este grabnic la socotire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'Și să-i previi pe ei [o, Mohammed] despre Ziua ce este aproape, căci inimile vor ajunge la gâturi și vor fi ei înspăimântați și nu vor avea nelegiuiții nici prieten, nici mijlocitor căruia să i se dea ascultare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, 'El [Allah] cunoaște hainia din ochi și ceea ce ascund piepturile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Și Allah judecă cu toată dreptatea, în vreme ce aceia pe care îi invocă, afară de El, nu vor judeca întru nimic. Allah este As-Sami’ [Cel care Aude] [și] Al-Basir [Vede Totul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Oare n-au purces ei pe Pământ ca să vadă cum a fost sfârșitul celor care au trăit înainte de ei? Au fost mai tari decât ei și au lăsat pe Pământ urme mai puternice decât ei, însă Allah i-a apucat pentru păcatele lor și nu au avut ei apărător înaintea lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Aceasta a fost și pentru că Trimișii lor au venit la ei cu semnele cele limpezi, iar ei nu au crezut. Atunci i-a apucat Allah. Cu adevărat, El este Qauiyy [Puternic] [și] Aspru la pedeapsă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Și l-am trimis Noi pe Moise cu semnele Noastre și cu dovadă limpede', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'La Faraon și la Haman și la Core, însă ei au spus: „El este un vrăjitor și un mincinos!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'Și când le-a adus lor Adevărul de la Noi, atunci au spus ei: „Omorâți-i pe pruncii acelora care au crezut împreună cu el și lăsați-le în viață numai pe femeile lor!” Dar viclenia necredincioșilor nu este decât în deșert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'Și Faraon a spus: „Lăsați-mă să-l omor pe Moise și el să-L cheme pe Domnul său! Mă tem să nu vă schimbe religia voastră și să nu aducă stricăciunea pe pământ!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Dar Moise a spus: „Eu caut apărare la Domnul meu și Domnul vostru împotriva oricărui trufaș care nu crede în Ziua socotirii!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'Și un om care credea, din poporul lui Faraon, și care-și ascundea credința lui a spus: „Oare voiți voi să omorâți un om [doar] pentru că el a spus: „Domnul meu este Allah”, după ce a venit el cu semne deslușite de la Domnul vostru? Dacă el este mincinos, minciuna sa va fi numai spre dauna lui, însă dacă el spune adevărul, atunci vă va lovi pe voi o parte din cele cu care vă amenință! Allah nu-l călăuzește pe cel care este nelegiuit și mincinos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'O, popor al meu! A voastră este stăpânirea astăzi și sunteți voi biruitori pe pământ! Dar cine ne va ajuta pe noi împotriva mâniei lui Allah, dacă ea se va abate asupra noastră?” Faraon a spus: „Eu nu vă arăt decât ceea ce văd și nu vă călăuzesc pe voi decât pe calea cea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'Și cel care credea a spus: „O, popor al meu! Eu mă tem pentru voi, de o zi asemenea Zilei aliaților[3],', '[3] Zilele în care Allah și-a trimis pedeapsa asupra celor care au respins Profeții Lui în trecut');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'Asemenea cum a pățit poporul lui Noe și [poporul] ’Ad și [poporul] Thamud și cei care au venit după ei! Dar Allah nu voiește nedreptate pentru robi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'O, popor al meu! Eu mă tem pentru voi de Ziua Chemării[4],', '[4] Ziua Judecății, atunci când nelegiuiții vor urla de teroare, oamenii se vor chema unii pe alții (a se vedea 7:44-51) și Îngerii vor vesti rezultatele judecării fiecărei persoane');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'De Ziua în care veți întoarce voi spatele, fugind, fără ca să aveți voi apărător de Allah! Iar cel pe care îl duce Allah în rătăcire nu va avea ocârmuitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Și Iosif a venit la voi, mai înainte, cu semne învederate, însă voi nu ați încetat să aveți îndoieli asupra celor pe care vi le-a adus. Iar când el a murit, atunci ați spus voi: „Allah nu va mai trimite un alt Trimis, după el!” Astfel îl duce Allah în rătăcire pe cel care este nelegiuit și se îndoiește.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'Cei care discută semnele lui Allah [revelația, versetele, evidențele ș.a.m.d.], fără nicio dovadă care să le fi venit, [fapta lor] este foarte urâtă de Allah și de cei care cred. Astfel pecetluiește Allah orice inimă a unui [om] îngâmfat și nelegiuit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'Și Faraon a spus: „O, Haman, durează-mi mie un turn, poate că eu voi ajunge la cărări[5],', '[5] Mijloace de urcare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'La cărările Cerurilor, astfel încât să-L văd pe Dumnezeul lui Moise, căci eu îl socotesc pe el mincinos!...” Astfel am făcut Noi ca fapta rea a lui Faraon să i se pară bună și a fost el abătut de la drum. Iar vicleșugul lui Faraon nu a fost decât întru pierdere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'Și omul care credea a spus: „O, popor al meu! Urmați-mă pe mine și eu vă voi călăuzi pe drumul cel drept!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'O, popor al meu! Această viață lumească nu este decât o plăcere trecătoare, în vreme ce Viața de Apoi este Casa odihnei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Cel care săvârșește o faptă rea nu va fi răsplătit decât cu una asemănătoare cu ea, iar cel care săvârșește o faptă bună - fie el bărbat sau femeie - și este credincios, va intra în Paradis, unde va primi cele de trebuință, fără socoteală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'O, popor al meu! Cum se face că eu vă chem pe voi la mântuire, în vreme ce voi mă chemați pe mine la Foc?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'Voi mă chemați să mă lepăd de Allah și să-I fac Lui ca asociați cele despre care eu nu am nicio știință, în vreme ce eu vă chem pe voi la Al-''Aziz [Cel Puternic] [și] Al-Ghaffar [Atoateiertător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'Nu este îndoială că acela la care mă chemați nu are nicio [putere să răspundă] chemării voastre, nici în această lume, nici în Lumea de Apoi, și că întoarcerea noastră este la Allah, iar cei nelegiuiți vor fi oaspeții Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'În curând vă veți aduce aminte de ceea ce vă spun, iar eu las soarta mea în seama lui Allah. Allah îi Vede bine pe robii [Săi]".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'Și Allah l-a ferit de relele pe care ei le-au plăsmuit și chinul cel rău a împresurat clanul lui Faraon,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'Focul la care ei vor fi expuși dimineața și seara[6]. Iar în Ziua când va sosi Ceasul, [se va spune]: „Faceți să intre clanul lui Faraon la osânda cea mai aspră!”', '[6] De la momentul morții lor până în Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'Iar când vor avea ei disputa în Foc vor zice cei slabi către cei care au fost aroganți: „Noi v-am urmat vouă. Oare nu puteți voi să ne scăpați de o parte din Foc?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'Atunci vor spune cei aroganți: „Cu adevărat noi suntem cu toții în el!” Allah a judecat deja între robii [Săi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'Și cei care se vor afla în Foc vor zice către păzitorii Iadului [Îngerii]: „Rugați-vă Domnului vostru ca să ne ușureze nouă chinul [măcar] pentru o zi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, 'Ei vor spune: „Oare nu v-au adus vouă Trimișii voștri dovezi limpezi?” Și ei vor răspunde: „Ba da!” Ei vor spune: „Atunci, rugați-vă [voi înșivă]!” Dar ruga necredincioșilor va fi numai în deșert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'Cu adevărat, Noi îi vom ajuta pe Trimișii Noștri și pe cei care cred, atât în viața din această lume, cât și în Ziua când se vor ridica martorii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'În Ziua când dezvinovățirea nu le va mai fi de niciun folos nelegiuiților și când vor avea ei parte de blestem și rău sălaș [Iadul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Și i-am dat Noi lui Moise călăuzire și i-am făcut pe Fiii lui Israel să moștenească Scriptura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'Ca o cârmuire și o îndemnare pentru cei dăruiți cu pricepere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Deci fii statornic [o, Mohammed], căci Făgăduința lui Allah este adevăr, cere iertare pentru păcatul tău[7] și preamărește-L pe Domnul tău cu Laudă, atât spre seară cât și spre dimineață!', '[7] Se referă la „greseală” sau „eroare” în alegere, deoarece toți Profeții au fost protejați de Allah de la a face păcate. Sensul este că toți credincioșii să caute iertare pentru păcatele lor.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Cu adevărat cei care discută despre Versetele lui Allah, fără să le fi venit lor nicio dovadă, nu au în piepturile lor decât numai îngâmfare și ei nu vor atinge țelul lor. Deci caută ocrotire la Allah, căci El este As-Sami’ [Cel care Aude] [și] Al-Basir [Cel care Vede]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Crearea Cerurilor și a Pământului este mai măreață decât crearea oamenilor, dar cei mai mulți oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Nu sunt deopotrivă cel care este orb și cel care vede; nici cei care cred și împlinesc fapte bune [nu pot fi deopotrivă] cu cel care săvârșește o faptă rea. Dar cât de rar vă aduceți voi aminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Ceasul va veni, fără îndoială, însă cei mai mulți oameni nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Și Domnul vostru zice: „Chemați-Mă și Eu vă voi răspunde! Cei care din prea multă trufie refuză să Mă adore vor intra în Iad umiliți".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Allah este Cel care v-a făcut vouă noaptea, ca să vă odihniți în ea, și ziua, ca să vedeți deslușit. Allah este Cel plin de Îndurare față de oameni, însă cei mai mulți dintre oameni nu sunt mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'Acesta este Allah, Domnul vostru, Creatorul tuturor lucrurilor. Nu există altă divinitate afară de El. Cum se poate să vă întoarceți [de la El]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'Astfel s-au întors aceia care au tăgăduit semnele lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Allah este Cel care v-a dat vouă Pământul, ca să trăiți pe el și Cerul, ca acoperiș, și v-a creat în cea mai bună și perfectă formă - și v-a înzestrat pe voi cu cele bune [ca hrană]. Acesta este Allah, Domnul vostru! Binecuvântat fie Allah, Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'El este Al-Hayy [Cel Veșnic Viu]. Nu există altă divinitate afară de El, deci chemați-L pe El cu credință curată numai în El! Mărire lui Allah, Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'Spune [o, Mohammed]: „Mi s-a oprit mie să-i ador pe aceia pe care îi chemați în locul lui Allah, după ce mi-au venit semnele cele limpezi de la Domnul meu și mi s-a poruncit să mă supun Stăpânului lumilor.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'El este Cel care v-a creat pe voi din țărână, apoi dintr-o picătură, apoi dintr-un cheag de sânge. Apoi El vă face să ieșiți copii mici, pentru ca apoi să ajungeți la maturitate și apoi să fiți bătrâni - însă pe unii dintre voi îi va ajunge moartea mai înainte [de a ajunge la bătrânețe] - și să ajungeți la un termen hotărât[8]. Poate că voi veți pricepe.', '[8] Timpul scris pentru moartea voastră');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'El este Cel care dă viață și dă moarte și, dacă hotărăște un lucru, El spune: „Fii” și el este.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Tu nu-i vezi pe aceia care se ceartă asupra semnelor lui Allah cum sunt abătuți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'Cei care socotesc mincinoase Cartea [Coranul] și cele cu care i-am trimis pe Trimișii Noștri vor ști [în curând],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Când cătușele și lanțurile vor fi pe gâtul lor și vor fi ei trași', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'În apa clocotită și apoi vor arde în Foc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'Apoi li se va zice lor: „Unde sunt cei pe care voi i-ați făcut asociați [lui Allah în adorare]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'Alături de Allah?” Și vor răspunde ei: „S-au rătăcit de noi. Ba noi nu am chemat mai înainte nimic!” Astfel îi duce Allah în rătăcire pe necredincioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, '[Îngerii vor spune:] „Acesta este prețul pentru că voi v-ați bucurat pe Pământ întru nedreptate și pentru că v-ați îngâmfat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'Intrați pe porțile Iadului, în care veșnic veți sălășlui! Și ce loc rău vor avea cei îngâmfați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Deci fii statornic [o, Mohammed]! Făgăduința lui Allah este adevăr și fie că îți vom arăta o parte din aceea cu care îi amenințăm, fie că te vom lua pe tine [înainte de aceasta], oricum la Noi se vor întoarce!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'Noi am trimis Mesageri și mai înainte de tine. Despre unii dintre ei ți-am povestit, iar despre alții dintre ei nu ți-am povestit. Și nu i-a fost dat niciunui Trimis să vină cu un semn, decât cu Îngăduința lui Allah. Când Porunca lui Allah va veni, se va judeca întru dreptate și atunci vor pierde cei care spun minciuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Allah este Cel care v-a făcut vouă vitele: pentru ca să călăriți pe unele dintre ele și pentru ca să mâncați de la altele;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Voi aveți de la ele [și alte] foloase și pentru ca voi să vă împliniți o dorință din piepturile voastre, însă, mai sunteți purtați pe ele și pe corăbii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'El vă arată semnele Sale, dar care dintre semnele lui Allah le tăgăduiți voi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Oare nu au purces ei pe pământ pentru a vedea care a fost urmarea pentru cei de dinaintea lor? Au fost mai numeroși decât ei și mai puternici și au lăsat mai multe urme pe pământ, însă nu le-au fost de niciun folos cele pe care le-au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Și când au venit la ei Trimișii lor cu semnele cele limpezi, s-au bucurat de știința pe care o aveau, însă cele de care și-au bătut joc i-au împresurat pe ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'Și când au văzut mânia Noastră, au spus ei: „Noi credem numai în Allah Singur și ne lepădăm de ceea ce I-am făcut Lui ca asociați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Însă nu le-a mai fost credința lor de niciun folos, când au văzut mânia Noastră. Aceasta este rânduiala lui Allah față de robii Săi și au pierdut atunci aceia care nu au crezut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Ha'', Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, '[Aceasta este] o Revelație de la Ar-Rahman [Cel Milostiv], Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'O Carte ale cărei Versete sunt tâlcuite, un Coran arab, pentru un popor [de oameni] care știu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'Un binevestitor și un prevenitor, însă cei mai mulți dintre ei se întorc și nu ascultă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'Și ei spun: „Inimile noastre sunt acoperite față de aceea la care ne chemi tu, în urechile noastre este surzenie, iar între noi și între tine este o perdea. Deci tu lucrează [ceea ce voiești][2] și vom lucra și noi [ceea ce voim]!”', '[2] Pentru religia ta sau împotriva noastră');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'Spune [o, Mohammed]: „Eu nu sunt decât un om, ca și voi, însă mie mi se revelează că Domnul vostru este un Domn Unic. Așadar, căutați calea cea dreaptă către El și rugați-L pe El de iertare!” Și vai pentru cei care-i fac Lui asociați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'Cei care nu dau Az-Zakat [Dania] și nu cred în Viața de Apoi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'Cu adevărat, cei care cred și împlinesc fapte bune, vor avea parte de o răsplată neîntreruptă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'Spune: „Oare voi nu credeți în Acela care a creat Pământul în două zile și Îi faceți Lui semeni?” Acesta este Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Și El a pus pe el [pe Pământ] munți neclintiți și l-a binecuvântat și a orânduit pe el toate cele necesare pentru hrană, până la patru zile, ca răspuns pentru cei care întreabă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Apoi S-a întors către Cer[3] - care era un fum - și i-a spus lui și Pământului: „Veniți[4] amândouă, de voie sau fără de voie!” Și au răspuns ele: „Venim, supunându-ne de bunăvoie!”', '[3] A se vedea 2.19
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Și le-a hotărât El să fie șapte Ceruri, în două zile, și a orânduit fiecărui Cer menirea sa. Și am împodobit Noi Cerul cel mai de jos cu candele [Stele] și strajă[5]. Aceasta este orânduiala Celui Al-’Aziz [Puternic] [și] Al-’Alim [Atoateștiutor].', '[5] Față de diavolii care încearcă să fure informația de la Îngeri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Și dacă se întorc ei, atunci spune: „Vă previn pe voi asupra unei nenorociri asemenea nimicirii [care a lovit popoarele] ’Ad și Thamud!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'Când au venit Trimișii la ei, de dinaintea lor și de după ei, [spunându-le]: „Nu-L adorați decât pe Allah!”, ei au spus: „Dacă Domnul nostru ar fi voit, ar fi făcut El să se pogoare Îngeri. Noi nu credem în cele cu care ați fost voi trimiși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'În ce-i privește pe cei din [poporul] ’Ad, ei au fost aroganți pe Pământ, pe nedrept, și au spus: „Cine este mai puternic decât noi?” Oare n-au văzut ei că Allah, Care i-a creat pe ei este mai puternic? Și au tăgăduit ei semnele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'Și, de aceea, am trimis Noi împotriva lor un vânt aprig și geros în niște zile fără de noroc [pentru ei], pentru ca să le dăm să guste chinul rușinii în viața lumii de acum. Însă pedeapsa din Viața de Apoi va fi și mai rușinoasă, iar ei nu vor fi ajutați [de nimeni].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'În ce-i privește pe [cei din poporul] Thamud, Noi i-am călăuzit, însă ei au iubit rătăcirea mai mult decât călăuzirea și i-a lovit pe ei trăsnetul pedepsei umilitoare pentru ceea ce au agonisit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'Și i-am izbăvit Noi pe cei care au crezut și au fost cu frică [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'Și [spune, o, Mohammed,] într-o Zi, vor fi adunați dușmanii lui Allah către Foc și vor fi ei mânați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'Astfel încât, atunci când vor ajunge la el, vor da mărturie împotriva lor urechile lor și ochii lor și pieile lor, pentru ceea ce ei au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'Și vor grăi ei către pieile lor: „De ce ați făcut mărturie împotriva noastră?”, iar ele le vor răspunde: „Ne-a făcut să grăim Allah Cel care face să grăiască toate lucrurile. El v-a creat pe voi întâia oară și la El fi veți întorși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Voi nu v-ați putut ascunde, ca să nu dea mărturie împotriva voastră urechile voastre, ochii voștri și pieile voastre, însă voi v-ați închipuit că Allah nu știe multe din cele pe care voi le săvârșiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'Această închipuire pe care voi ați avut-o despre Domnul vostru v-a dus la pieire pe voi și ați ajuns să fiți printre cei pierduți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Și de vor răbda ei, Focul le va fi sălaș, iar de vor cere ei iertare [lui Allah], nu vor fi ei dintre cei iertați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'Le-am orânduit lor tovarăși[6] care le-au împodobit ceea ce a fost înaintea lor și ceea ce a fost după ei și s-a adeverit împotriva lor Cuvântul [pedeapsa], așa cum s-a adeverit și în privința altor comunități de dinainte de ei, dintre djinni și dintre oameni. Și ei sunt cei care vor pierde!', '[6] În această lume printre djinnii răi și oameni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Și cei care nu cred spun: „Nu plecați urechea la acest Coran, ci faceți zarvă pentru ca voi să biruiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'Și-i vom face Noi pe cei care nu cred să guste chinul aspru și-i vom răsplăti după cea mai rea [faptă] pe care au săvârșit-o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'Aceasta este răsplata dușmanilor lui Allah: Focul. În el vor avea locuința veșniciei, drept răsplată pentru că au tăgăduit semnele Noastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'Și cei care nu cred spun: „Doamne, arată-ni-i nouă pe aceia dintre djinni și dintre oameni, care ne-au dus în rătăcire, pentru ca noi să-i punem sub picioarele[7] noastre, astfel încât să fie ei printre cei mai de jos!”', '[7] În cele mai joase niveluri ale Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Însă cei care spun: „Domnul nostru este Allah!” și apoi urmează calea cea dreaptă, asupra lor se vor coborî Îngerii, [spunându-le]: „Nu vă temeți și nu fiți mâhniți și primiți bunăvestire despre Raiul ce vi s-a făgăduit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Noi [Îngerii] suntem prietenii voștri în viața din această lume și din Viața de Apoi; voi veți avea în ea ceea ce doresc sufletele voastre și veți avea în ea ceea ce veți cere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'Ospeție de la Cel care este Ghafur [Iertător], Rahim [Îndurător].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'Și cine spune vorbe mai frumoase decât acela care cheamă la Allah, săvârșește faptă bună și zice: „Cu adevărat, eu sunt dintre musulmani”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'Nu este fapta cea bună deopotrivă cu fapta cea rea. Respinge [fapta cea rea] cu cea care este mai bună [arătând bunătate celui care ți-a făcut rău] și iată-l pe acela care a fost între tine și el dușmănie ca și cum ar fi un prieten apropiat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'Însă nu le va fi dat decât celor care sunt răbdători și nu-i va fi dat decât aceluia care va avea parte de bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'Și dacă [vreodată] te va ademeni cu un gând rău Șeitan [șoptindu-ți], caută adăpost la Allah, căci El este As-Sami'' [Cel care Aude] [și] Al-''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Și printre semnele Sale sunt noaptea și ziua și Soarele și Luna. Însă nu vă prosternați nici dinaintea Soarelui, nici dinaintea Lunii, ci prosternați-vă dinaintea lui Allah Care le-a creat pe ele, dacă pe El Îl adorați voi.[8]', '[8] Nu Îl adorați pe Allah prin creația Lui, ci adorați-L pe El direct și exclusiv');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'Dar dacă [necredincioșii] sunt aroganți, [să fie ei], căci cei care sunt la Domnul tău [Îngerii] Îl laudă pe El noaptea și ziua, fără ca ei să ostenească [niciodată].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'Și printre minunile Sale [este și aceea că] tu vezi pământul umilit [pustiu și neroditor], dar când Noi facem să coboare apa peste el, atunci el se mișcă și se umflă. Cu adevărat, Acela care îi dă lui viață este Cel care dă viață și morților, fiindcă El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Cu adevărat, cei care răstălmăcesc Versetele Noastre nu Ne sunt necunoscuți. Și oare este mai bun cel care este aruncat în Foc sau cel care va veni în siguranță în Ziua Învierii? Faceți ceea ce voiți, fiindcă El este Binevăzător a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Cu adevărat, cei care nu cred în Mesaj [Coran][9], când el vine la ei...[10]. Și cu adevărat, el este o Carte plină de Putere[11].', '[9] Îl resping sau preferă interpretările deviante
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'Deșertăciunea nu va veni la ea nici dinaintea și nici din urma ei, pentru că ea este o Revelație de la un [Domn care este] Hakim [Înțelept], Hamid [Vrednic de Laudă]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Nu ți se spune ție decât ceea ce li s-a spus și Trimișilor de dinaintea ta. Domnul tău este Dătător de Iertare și Dătător de pedeapsă dureroasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'Dacă Noi l-am fi făcut un Coran într-o altă limbă [decât araba], ei ar zice: „De ce nu sunt Versetele sale tâlcuite? Un [Coran] nearab și un [Mesager] arab?” Spune: „El este pentru cei care cred ocârmuire și tămăduire, însă aceia care nu cred [au] în urechile lor surzenie și el este pentru ei rătăcire! Aceștia sunt ca și cei chemați dintr-un loc depărtat.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'Noi i-am dăruit lui Moise Cartea și au fost neînțelegeri asupra ei. Și de n-ar fi fost un cuvânt [poruncă][12] de mai înainte de la Domnul tău, s-ar fi fost hotărât între ei. Însă ei au rămas în mare nedumerire în privința ei.', '[12] A se vedea 10:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Cel care săvârșește o faptă bună [o face] pentru sine însuși, iar cel care face rău o face împotriva sa. Domnul tău nu este nedrept cu robii Săi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'La El se află știința despre Ceas. Și nu ies roduri din învelișurile lor și nu rămâne însărcinată nicio femeie și nici nu naște, fără Știrea Lui. Și în Ziua când El îi va chema [mustrându-i]. „Unde sunt asociații Mei?”, vor spune ei: „Îți vestim Ție că nu este niciun martor printre noi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'Ceea ce ei au evocat mai înainte îi va părăsi pe ei și ei vor înțelege că nu au scăpare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'Omul nu ostenește să ceară binele, dar dacă îl atinge pe el răul, atunci el este deznădăjduit și descumpănit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'Dar dacă-i dăm să guste Îndurare din partea Noastră, după o nenorocire care l-a lovit, atunci el spune: „Aceasta mi se cuvine[13] și eu nu cred că Ceasul va sosi [vreodată]! Și dacă voi fi adus înapoi la Domnul meu, voi avea eu de la El cea mai bună [cinstire]!” Noi le vom vesti celor care nu au crezut ceea ce au făcut și le vom da lor să guste dintr-un chin aspru!', '[13] Datorită efortului, științei, excelenței mele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Și dacă-l copleșim cu Harul Nostru pe om, el se abate și se îndepărtează aparte, dar, când îl atinge pe el răul, atunci el sporește în [cereri și] rugăminte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'Spune: „Vedeți voi? Dacă el [Coranul] este de la Allah și voi îl tăgăduiți, atunci cine se află în rătăcire mai mare decât acela care este într-o schismă adâncă?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Noi le vom arăta semnele Noastre [în cele mai îndepărtate] zări [ale Pământului] și în sufletele lor înșiși, astfel încât să le fie limpede că el [Coranul] este Adevărul[14]. Oare nu este de ajuns că Domnul tău este Martor la toate?', '[14] Sau „El (Allah) este Adevărul”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'Ei sunt în îndoială în privința întâlnirii cu Domnul lor, dar El este Cel care Cuprinde toate lucrurile [cu Știința Sa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Ha'', Mim,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Ayn, Sin, Qaf[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'Astfel, Allah Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept] îți trimite ție [o, Mohammed] revelații, tot așa cum le-a trimis și celor de dinainte de tine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'Ale Lui sunt cele din Ceruri și cele de pe Pământ și El este Al-''Aliyy [Cel mai Înalt], Al-''Azim [Măreț]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Aproape că se despică Cerurile în înălțimea lor[2], când Îngerii Îl preamăresc pe Domnului lor lăudându-L și se roagă de iertare pentru cei de pe Pământ. Allah este Al-Ghafur [Iertătorul], Ar-Rahim [Îndurătorul].', '[2] Datorită Grandorii lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Cât despre cei care își iau ocrotitori în afara Lui, Allah este Veghetor peste ei și tu nu ești chezaș pentru ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Astfel, ți-am revelat Noi un Coran arab, pentru ca tu să previi Mama cetăților [Mecca] și pe cei din împrejurimile ei[3] și să previi pentru Ziua Adunării - despre care nu este îndoială. O parte vor fi în Rai și o parte vor fi în Văpaie.', '[3] Toate celelalte popoare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'Și de ar fi Voit Allah, i-ar fi făcut El pe ei o singură națiune[4], însă El lasă să intre întru Îndurarea Sa pe cine El Voiește[5]. Iar nelegiuiții nu vor avea ocrotitor și nici ajutor.', '[4] Ar fi urmat toți aceeași cale în credință
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Ori au luat ei ocrotitori afară de El? Allah este Al-Ualiyy [Ocrotitorul], El dă viață morților și El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'Și pentru orice lucru ați fi cu neînțelegere, judecata asupra lui se află la Allah. [Spune:] „Acesta este Allah, Domnul meu, în El mă încred și la El mă întorc [cu căință].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, '[El este] Făcătorul Cerurilor și al Pământului. El a făcut pentru voi soațe din voi înșivă și [a făcut] și animalelor perechi. Prin aceasta vă înmulțește. Nu este nimic asemenea cu El[6]. El este As-Sami'' [Cel care Aude Totul] și Al-Basir [Cel care Vede Totul].', '[6] Nu există nicio asemănare între Creator și creația Sa în esență, atribute sau fapte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'Ale Lui sunt cheile [comorilor] Cerurilor și ale Pământului; El Dăruiește cu prisosință cele spre viețuire, cui Voiește El, sau le Dăruiește cu măsură, [cui Voiește El]; El este ‘Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'El v-a orânduit vouă religia pe care i-a prescris-o lui Noe, pe care Ți-am revelat-o ție [o, Mohammed] și am prescris-o pentru Avraam și Moise și Iisus: „Stabiliți religia și nu vă scindați!” Li se pare prea mare politeiștilor aceea la care tu îi chemi. Allah îi alege [pentru aceasta] pe cei pe care El Voiește și îi călăuzește către El pe cei care se căiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'Ei nu s-au despărțit decât după ce le-a venit lor știința, din pricina pizmei dintre ei. Și dacă nu ar fi venit mai înainte un cuvânt[7] de la Domnul tău pentru un termen hotărât, s-ar fi hotărât [numaidecât] între ei. Iar cei de după ei, cărora le-a fost dăruită Cartea spre moștenire, sunt în mare îndoială în privința ei.', '[7] A se vedea 10:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'De aceea, cheamă-i tu [o, Mohammed, pe oameni la religia lui Allah][8] și mergi pe calea cea dreaptă - așa cum ți s-a poruncit - și nu urma poftelor lor, ci spune: „Cred în ceea ce a fost revelat dintre scripturi [Coran] și mi s-a poruncit mie să judec cu dreptate între voi. Allah este Domnul nostru și Domnul vostru. Faptele noastre sunt ale noastre și faptele voastre sunt ale voastre[9]. Nu este [nevoie de] ceartă între noi și voi[10]. Allah ne va aduna pe noi, căci la El este întoarcerea!”', '[8] Un alt înțeles este „Și din cauza aceea (a divizării și separării în secte), invită-i (înapoi la Allah)...”
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'Însă cei care se ceartă în privința lui Allah, după ce s-a răspuns [chemării Sale][11], cearta lor este în van la Domnul lor și asupra lor se abate mânia și chinul aspru.', '[11] După ce oamenii au acceptat adevărul de la Allah într-o încercare de a-i îndepărta pe oameni de la religia Lui (Islamul)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Allah este Cel care a trimis Cartea cu Adevărul și cu Balanța [dreptatea]. Și de unde să știi? Poate că Ceasul este aproape.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Încearcă să-l grăbească cei care nu cred în el[12], însă cei care cred sunt cu teamă de el și știu că acesta este Adevărul. Iar cei care se ceartă asupra Ceasului, se află în rătăcire adâncă.', '[12] Ei l-au provocat pe Profet (pacea și binecuvântarea lui Allah fie asupra sa) să îl aducă imediat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Allah este Binevoitor cu robii Săi. El Dăruiește cele spre viețuire cui Voiește El. El este Al-Qauiyy [Tare], Al-''Aziz [Puternic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Celui care voiește să semene [ogorul] Lumii de Apoi, Noi îi vom spori semănătura, iar celui care voiește să semene [ogorul] acestei lumi, Noi îi vom da din ea, însă el nu va avea parte în Lumea de Apoi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Sau au ei asociați [ai lui Allah] care le-au orânduit lor o religie pe care Allah nu a îngăduit-o? Dacă nu ar fi cuvântul hotărârii[13], s-ar fi judecat între ei. Cei nelegiuiți vor avea parte de chin dureros.', '[13] Poruncă. A se vedea 10:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'Tu îi vei vedea pe cei nelegiuiți temându-se de ceea ce au agonisit, când [pedeapsa] se va abate asupra lor, în vreme ce aceia care au crezut și au săvârșit fapte bune se vor afla în locurile înflorite ale Grădinilor și vor avea ei parte de tot ceea ce voiesc de la Domnul lor. Acesta este marele Har!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'Aceasta este ceea ce Allah le binevestește robilor Săi care cred și săvârșesc fapte bune! Spune [o, Mohammed]: „Eu nu vă cer vouă pentru acesta [Mesajul revelației] răsplată, în afară de bunăvoință față de mine și față de legătura [de rudenie] ce ne leagă [lăsându-mă să transmit Mesajul].” Celui care împlinește o faptă bună îi vom spori Noi binele în schimbul ei. Cu adevărat, Allah este Ghafur [Iertător], Șakur [Mulțumitor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Sau ei spun: „El a născocit minciună pe seama lui Allah!” Dar de ar Voi Allah, El ar pecetlui inima ta. Allah șterge deșertăciunea și întărește Adevărul cu Vorbele Sale. El este Bineștiutor al celor dinlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'El este Cel care primește căința robilor Săi și iartă pentru faptele cele rele și El știe ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'El împlinește [dorințele] celor care cred și săvârșesc fapte bune și le sporește lor Harul Său, în vreme ce necredincioșii vor avea parte de chin aspru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'Dacă Allah i-ar înzestra cu prisosință pe [toți] robii Săi, s-ar purta ei cu nedreptate pe Pământ, însă El trimite cu măsură ceea ce Voiește. El este Khabir [Bineștiutor] [și] Basir [Binevăzător] al robilor Săi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'El este Cel care pogoară ploaia, după ce ei au fost deznădăjduiți, și întinde Îndurarea Sa. El este Al-Ualiyy [Ocrotitor] [și] Al-Hamid [Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Printre Semnele Sale sunt tocmeala Cerurilor și a Pământului și a vietăților pe care le-a risipit prin ele. Dar El are Puterea de a le aduna pe ele, dacă Voiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Nu vă lovește nicio nenorocire, decât pentru ceea ce agonisesc mâinile voastre, însă El iartă multe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'Voi nu veți putea să[-L] slăbiți pe pământ [pe Allah][14] și voi nu aveți ocrotitor și ajutor afară de Allah!', '[14] Nu veți putea fugi de el');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'Și printre semnele Sale sunt corăbiile de pe mare, ce seamănă cu munții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Dacă Voiește, El domolește vântul și ele rămân nemișcate pe suprafața apei. Întru aceasta se află semne pentru toți oamenii care sunt răbdători și mulțumitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Sau El le lasă să piară[15], pentru cele pe care le-au agonisit. Însă El iartă mult.', '[15] Însemnând că Allah ar putea scufunda corăbiile cu ajutorul unui vânt puternic');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'Și să știe cei care se ceartă asupra semnelor Noastre că ei nu vor avea scăpare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Și tot ceea ce vi se dă vouă este bucurie trecătoare pentru viața din această lume. Însă ceea ce se află la Allah este mai bun și mai dăinuitor pentru cei care cred și se încred în Domnul lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'Pentru cei care se feresc de păcatele mari și de faptele rușinoase și care iartă, atunci când se mâniază,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'Pentru cei care răspund Domnului lor și împlinesc Rugăciunea [As-Salat], iar pentru treburile lor [țin] sfat laolaltă și dau Dania [Az-Zakat] din cele cu care îi înzestrăm,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'Și pentru cei care, atunci când nedreptatea se abate asupra lor, ei o înfruntă[16].', '[16] Sau își cer drepturile într-un mod drept, nelăsându-i pe agresori să profite de slăbiciunea lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Răsplata pentru un rău este un rău deopotrivă cu el. Însă răsplata aceluia care iartă și care caută împăcare se află la Allah. El nu-i iubește pe cei nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'Cât despre cei care caută dreptatea, după ce sunt nedreptățiți, împotriva acestora nu este cale [pentru dojană];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Ci drumul pentru dojană este împotriva acelora care-i năpăstuiesc pe [ceilalți] oameni și săvârșesc fărădelegi pe Pământ, fără de dreptate. Aceștia vor avea parte de chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'Iar cel care rabdă și iartă, [să știe că] aceasta este dintre lucrurile înalte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'Acela pe care Allah îl duce în rătăcire nu va avea, după El, niciun ocrotitor. Și îi vei vedea pe cei nelegiuiți spunând, când vor vedea pedeapsa: „Oare este vreo cale pentru întoarcere [la viața anterioară]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'Și-i vei vedea cum stau înaintea lui [Focului] smeriți de umilință, trăgând cu ochiul pe furiș, în vreme ce vor spune cei care au crezut: „Cei pierduți sunt cei care s-au pierdut pe ei înșiși și [și-au pierdut] familiile lor în Ziua Învierii. Cei nelegiuiți se vor afla într-un chin necontenit.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Și nu vor avea ei niciun fel de ocrotitori care să-i ajute afară de Allah, iar acela pe care Allah îl duce în rătăcire nu va avea niciun drum [spre călăuzire].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Ascultați de Domnul vostru înainte de a veni o Zi de la Allah, [Zi] pentru care nu este amânare! În Ziua aceea nu va fi pentru voi nici scăpare, nici tăgăduire[17].', '[17] A păcatelor voastre sau o „dezaprobare” a pedepsei voastre');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'Dacă ei se îndepărtează, Noi nu te-am trimis la ei ca păzitor peste ei, ci tu nu ești dator decât numai cu vestirea. Când îi dăm Noi omului să guste Îndurare din partea Noastră, atunci se bucură el de ea, însă dacă îl lovește pe el un rău, pentru ceea ce au săvârșit mâinile sale mai înainte, atunci omul este nemulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'A lui Allah este Stăpânirea Cerurilor și a Pământului. El creează ceea ce Voiește și Dăruiește El copile cui Voiește și Dăruiește El băieți cui Voiește,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'Sau dă El și băieți și copile și-l face sterp pe cel pe care El Voiește. El este ''Alim [Atoateștiutor] [și] Qadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Unui om nu i se cuvine ca Allah să-i Vorbească decât numai printr-o revelație, sau din spatele unui văl, sau [prin] trimiterea unui Trimis care revelează, cu Voia Sa, ceea ce El Voiește. Cu adevărat, El este ‘Aliyy [Cel Preaînalt] și Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Astfel, ți-am revelat Noi o inspirație [Coranul], la porunca Noastră. Tu nu ai știut [mai înainte] ce este Cartea și ce este credința, însă Noi am făcut-o lumină cu care călăuzim pe cine voim dintre robii Noștri. Și tu călăuzești pe un drum drept,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'Pe drumul lui Allah, ale Căruia sunt cele din Ceruri și de pe Pământ. Și către Allah se îndreaptă [toate] lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Ha'', Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'Pe Cartea cea limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Cu adevărat, Noi l-am făcut un Coran arab, pentru ca voi să pricepeți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'Și cu adevărat, el este la Noi, în Mama Cărții[2], înălțat și plin de înțelepciune.', '[2] Tabla bine Păstrată (al-Lauh al-Mahfuth)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Ar trebui să îndepărtăm Noi Îndemnarea de la voi, pentru că voi sunteți un popor de păcătoși?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'Și câți Profeți le-am trimis Noi popoarelor celor dintâi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'Însă nu a venit niciun Profet la ei fără să-l ia în derâdere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Și i-am nimicit Noi [pe alții] mai puternici decât ei[3] și a umblat exemplul înaintașilor dintâi!', '[3] Necredincioșii din Qurayș care nu l-au acceptat pe profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Și dacă-i întrebi pe ei „Cine a făcut Cerurile și Pământul?”, ei răspund cu siguranță: „Le-a făcut Al-''Aziz [Cel Puternic] [și] Al-''Alim [Atoateștiutor]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, '[El este] Cel care v-a făcut vouă Pământul ca un pat și v-a făcut vouă pe el cărări pentru ca voi să fiți călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'Și El este Cel care face să pogoare apa din Cer, cu măsura cuvenită, și cu ea am dat Noi viață unui ținut mort. Astfel veți fi și voi scoși [din morminte].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'Și El este Cel care a creat toate soiurile și v-a făcut vouă corăbiile și dobitoacele pe care le călăriți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'Ca să vă așezați pe spinările lor și apoi să pomeniți Îndurarea Domnului vostru, când ședeți pe ele, spunând: „Slavă Celui care ni le-a supus nouă pe acestea pe care noi nu am fi putut să le stăpânim!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'Și, cu adevărat, noi la Domnul nostru ne vom întoarce.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'Și ei I-au atribuit Lui dintre robii Săi asociați. Cu adevărat, omul este nemulțumitor.[4]', '[4] Susținând că El are un fiu sau o fiică așa cum se spune că un copil este o parte din părinții lui. Acest concept este complet incompatibil cu Unicitatea lui Allah.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Sau Și-a luat El copile din cele pe care le-a creat și v-a dat numai vouă băieți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'Și când i se vestește unuia dintre ei [nașterea unei copile], ceea ce el a hotărât pentru Ar-Rahman [Cel Milostiv], atunci fața sa devine întunecată și el este plin de mânie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'O ființă care este crescută în podoabe [femeie] și care într-o ceartă nu este în stare să se apere, cu dovadă limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Și-i fac pe Îngeri, care sunt robii lui Ar-Rahman [Celui Milostiv], copile! Au fost ei martori la facerea lor? Mărturisirea lor se va scrie și vor fi ei întrebați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'Și ei spun: „Dacă ar fi voit Cel Milostiv [Ar-Rahman], noi nu i-am fi adorat pe ei!” Însă ei nu au nicio știință despre aceasta, ci numai născocesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Sau le-am dăruit Noi o Scriptură mai înainte de el [Coran] și ei se țin strâns de ea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Ba ei spun: „Noi i-am găsit pe părinții noștri într-o credință și noi ne călăuzim după urmele lor”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Tot astfel nu am trimis Noi în nicio cetate un prevenitor mai înainte de tine, fără ca [mai marii lor și] cei înstăriți dintre ei să nu spună: „Noi i-am găsit pe părinții noștri într-o religie și noi ne călăuzim după urmele lor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, 'A spus [Trimisul]: „Chiar dacă eu v-aș aduce vouă o călăuzire mai bună decât aceea în care i-ați găsit pe părinții voștri?” I-au răspuns: „Noi nu credem în cele cu care ai fost trimis!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'Și Noi Ne-am răzbunat pe ei și privește care a fost sfârșitul acelora care au tăgăduit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'Și [spune, o, Mohammed,] când a spus Avraam tatălui său și poporului său: „Eu mă dezic de cei la care vă închinați voi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'În afară de Cel care m-a făcut pe mine și Care mă va călăuzi cu siguranță!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Și el [Avraam] a făcut-o[5] un cuvânt care să rămână pentru urmașii săi. Poate că ei se vor întoarce [și se vor căii].', '[5] Mărturisirea lui că nimeni nu are dreptul să fie adorat în afară de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'Dar nu, Eu le-am dăruit acestora [celor din Mecca] și părinților lor[6] bucurie, până ce a venit la ei Adevărul și un Trimis[7] care să facă lucrurile deslușite.', '[6] Descendenții lui Avraam
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'Și când a venit Adevărul la ei, au spus: „Aceasta este vrăjitorie și noi nu credem în ea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'Și au spus: „De ce nu a fost trimis acest Coran unui om de vază din cele două cetăți[8]?”', '[8] Făcându-se referire la Mecca și Taif');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Oare ei împart Îndurarea Domnului tău? Noi le-am împărțit lor cele spre trebuință în viața din această lume și i-am ridicat pe ei unii deasupra altora, în trepte, pentru ca unii dintre ei să fie folositori altora la lucru. Iar Îndurarea Domnului tău [Paradisul] este mai bună [o, Mohammed,] decât ceea ce adună ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'Și de n-ar fi oamenii o singură comunitate [de necredincioși][9], am fi făcut Noi pentru casele celor care-L tăgăduiesc pe Ar-Rahman [Cel Milostiv] acoperișuri și scări de argint, pe care ei să urce,', '[9] Care a crezut că generozitatea lui Allah față de ei era un semn al aprobării Sale sau care s-ar grăbi către necredință pentru a obține avere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'Și uși [de argint] pentru casele lor și divanuri pe care să stea rezemați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'Și podoabe de aur. Dar toate acestea nu sunt decât bucurie trecătoare din viața din această lume, în vreme ce Viața de Apoi se află la Domnul tău, [numai] pentru cei cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Cât despre acela care se întoarce de la Îndemnarea lui Ar-Rahman [Cel Milostiv], aceluia îi vom orândui Noi un șeitan care-i va fi tovarăș nedespărțit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'Și, cu adevărat, ei [diavolii] îi vor abate pe ei de la drum, în vreme ce ei vor socoti că sunt bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'Până când, atunci când va veni el la Noi [pentru judecată], îi va spune tovarășului său: „[Vai!] De ar fi între mine și tine distanța dintre cele două răsărituri! Ce rău tovarăș ai fost!.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Și nu vă va fi vouă de niciun folos în Ziua aceea - de vreme ce voi ați fost nelegiuiți - că veți fi voi împreună la pedeapsă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Și oare tu [Mohammed] poți să-i faci să audă pe cei surzi și-i poți călăuzi pe cei orbi și pe cel care se află în rătăcire învederată?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'Fie că Noi te vom lua pe tine [la moarte sau nu], cu adevărat Noi ne vom răzbuna pe ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'Fie că îți vom arăta ție ceea ce le-am făgăduit lor, căci Noi avem Putere asupra lor [și îi vom pedepsi așa cum am promis].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Tu ține-te cu putere de ceea ce ți-a fost revelat, căci tu ești pe drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Și, cu adevărat, el [Coranul] este doară îndemnare pentru tine și pentru poporul tău și voi veți fi întrebați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'Întreabă-i pe Trimișii Noștri, pe care i-am trimis înainte de tine: Oare am făcut Noi alte divinități, afară de Ar-Rahman [Cel Milostiv], ca să fie adorate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Și l-am trimis Noi pe Moise cu semnele Noastre la Faraon și la dregătorii săi și a spus el: „Cu adevărat, eu sunt Trimisul Stăpânului lumilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'Dar când le-a arătat lor semnele Noastre, ei au râs de ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'Și nu le-am arătat Noi niciun semn care să nu fi fost și mai mare decât sora lui. Și i-am apucat Noi cu chinul, poate că ei se vor întoarce [la Noi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'Și ei i-au spus [lui Moise]: „O, vrăjitorule! [acesta fiind un titlu de onoare în acea vreme] Roagă-te pentru noi Domnului tău, pentru legământul ce l-a făcut cu tine și noi vom urma calea cea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'Și când Noi am îndepărtat chinul de la ei, atunci iată-i pe ei cum și-au încălcat făgăduința.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'Și Faraon a strigat către poporul său, spunând: „O, popor al meu! Oare nu sunt ale mele împărăția Egiptului și aceste pâraie care curg la picioarele mele? Oare voi nu vedeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'Oare nu sunt eu mai bun decât acesta [Moise] care este umilit și abia de poate grăi? [Faraon astfel mințind oamenii că Moise ar mai avea defectul în vorbire pe care l-a avut înainte, însă Allah l-a vindecat]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'De ce nu i se aruncă lui brățări de aur sau de ce nu vin cu el Îngerii pentru a-l însoți?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'Și astfel i-a amăgit el pe [oamenii din] poporul său și ei s-au supus, fiindcă ei erau un popor de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'Și când Ne-au supărat pe Noi, Ne-am răzbunat Noi pe ei și i-am înecat pe toți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'Și i-am făcut Noi [printre cei] trecuți și exemplu pentru cei de după ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'Și când a fost dat fiul Mariei ca exemplu [ca fiind adorat împreună cu Allah], iată poporul tău strigând,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'Și au spus: „Oare zeii noștri sunt mai buni sau el [fiul Mariei]?” Și nu ți l-au dat ție ca exemplu, decât pentru ceartă. Ba ei sunt un popor [de oameni] gâlcevitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'El [Iisus] nu este decât un rob, asupra căruia Noi ne-am revărsat Harul Nostru și din care am făcut o pildă pentru Fiii lui Israel.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'Și de am fi voit Noi, am fi făcut în locul vostru Îngeri care să vă urmeze pe Pământ.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'Și, cu adevărat, el [Iisus] va fi un semn pentru Ceas; deci nu vă îndoiți în privința lui și urmați-mă pe Mine[10], căci aceasta este o cale dreaptă!', '[10] Urmați poruncile lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'Și să nu vă abată pe voi Șeitan. Cu adevărat, el vă este dușman învederat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'Și când a venit Iisus cu semnele limpezi, el a spus: „Am venit la voi cu înțelepciunea, pentru a vă limpezi vouă unele [din lucrurile] în care voi sunteți deosebiți. Fiți cu frică de Allah și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Cu adevărat, Allah este Stăpânul meu și este Stăpânul vostru, așadar adorați-L pe El! Aceasta este calea cea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Dar sectele s-au certat între ele. Și vai acelora care au fost nedrepți pentru chinul unei Zile dureroase!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Oare așteaptă ei altceva decât să vină asupra lor Ceasul, deodată, fără ca ei să-și dea seama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Prietenii apropiați își vor fi în Ziua aceea dușmani unii altora, în afară de cei cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, '[Cărora Allah le va spune] „O, robii Mei! Fiți fără teamă în Ziua aceasta și nu vă întristați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, '[Voi] cei care credeți în Versetele Noastre și sunteți musulmani!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'Intrați în Paradis, voi și cei ca voi[11], și vă veți bucura!”', '[11] Un alt înțeles este „soțiile voastre”, cele dreptcredincioase dintre ele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Se va trece printre ei cu tipsii de aur și cupe; în el se va afla tot ceea ce poftesc sufletele și place ochilor. „Și în veci veți rămâne voi în el,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'Căci acela este Paradisul ce vi s-a dat ca moștenire pentru ceea ce ați împlinit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'Și în el veți avea multe roade[12] din care veți mânca”.', '[12] Tot ce este delicios');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Iar nelegiuiții vor petrece în veci în chinurile Iadului,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'Care nu se vor potoli pentru ei și vor fi fără de nădejde în ele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Și Noi nu i-am nedreptățit pe ei, ci s-au nedreptățit ei înșiși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'Și ei vor striga: „O, Malik[13]! Să ne sfârșească Domnul tău!” Iar el le va răspunde: „Cu adevărat, voi veți rămâne astfel [veșnic]!"', '[13] Paznicul Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Noi am venit la voi cu Adevărul, însă cei mai mulți dintre voi urăsc Adevărul!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Au luat ei vreo hotărâre[14]? Vom hotărî și Noi!', '[14] O conspirație împotriva profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa). Se face referire la necredincioșii din Mecca');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Sau cred ei că Noi nu auzim taina lor și discuția lor în șoaptă? Ba da! Iar trimișii Noștri [Îngerii] sunt cu ei și scriu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'Spune [o, Mohammed]: „Dacă ar avea Ar-Rahman [Cel Milostiv] un fiu, eu aș fi primul dintre adoratorii lui!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Mărire Stăpânului Cerurilor și Pământului, Stăpânul Tronului! El este mai Presus de ceea ce ei vorbesc [despre El]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Lasă-i pe ei să se afunde și să se joace, până ce se vor întâlni cu Ziua lor, care le-a fost făgăduită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'El este Cel care este Domn în Cer și care este Domn pe Pământ; El este Al-Hakim [Cel Înțelept] [și] Al-''Alim [Atoateștiutor]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'Binecuvântat este Cel a Căruia este Împărăția Cerurilor și a Pământului și a celor dintre ele. La El este Știința despre Ceas și la El vă veți întoarce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Și cei pe care îi cheamă în afară de El nu au putere ca să mijlocească[15], ci numai cei care fac mărturie despre Adevăr și care știu.', '[15] Puterea mijlocirii este dată de către Allah doar cui Dorește El');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'Și dacă îi întrebi[16] cine i-a creat pe ei, vor răspunde: „Allah!” Atunci cum de se întorc ei?', '[16] Pe cei care Îi fac asociați lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'Și [Allah Cunoaște] vorba lui [a Profetului spunând]: „Doamne, aceștia sunt un popor [de oameni] care nu cred!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'Deci, îndepărtează-te de ei și spune: „Pace!”[17], căci ei vor afla [în curând].', '[17] Însemnând „Nu vă voi face rău”. Aceasta a fost înainte ca lupta să le fie permisă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Ha'', Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'Pe Cartea cea limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Cu adevărat, Noi am trimis-o într-o noapte binecuvântată[2]. Cu adevărat, Noi am fost prevenitori', '[2] Noaptea Destinului (Qadr). A se vedea Surat 97.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'În care se hotărăsc[3] toate rânduielile înțelepte,', '[3] Îngerii scriu și coboară cu ceea ce Allah a destinat pentru următorul an');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, '[Fiecare] rânduială [ce vine] de la Noi. Cu adevărat, Noi trimitem [Mesagerul],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'Ca Îndurare de la Domnul tău. Cu adevărat, El este As-Sami'' [Cel Care Aude Totul] și Al-''Alim [Atoateștiutorul],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'Stăpânul Cerurilor și a Pământului și al celor ce sunt între ele, dacă voi sunteți cu credință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'Nu există altă divinitate afară de El; El dă viață și dă moarte și El este Stăpânul vostru și Stăpânul părinților voștri cei dintâi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'Însă ei sunt în îndoială și râd.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Deci, așteaptă o zi în care Cerul va aduce un fum învederat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'Care-i va învălui pe oameni. Acesta va fi un chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, '[Ei vor spune:] „Doamne, îndepărtează chinul de la noi, căci noi [acum] credem!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'Și ce mustrare vor avea, când a venit la ei un Trimis limpede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'Iar ei s-au întors de la el și au spus: „El este om învățat [de către alții], un nebun!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'Cu adevărat, Noi vom îndepărta puțin chinul, iar voi veți reveni [tot așa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'Dar într-o Zi vom lovi cu asprimea cea mai mare și atunci Noi Ne vom răzbuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'Mai înainte de ei am încercat Noi poporul lui Faraon, când a venit la ei un Trimis nobil [Moise]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, '[Și le-a spus lor]: „Aduceți-i la mine pe robii lui Allah[4], căci eu sunt un Trimis vrednic de încredere', '[4] Fiii lui Israel');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'Și nu vă ridicați cu semeție împotriva lui Allah, căci eu vă aduc dovadă limpede', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'Și eu caut apărare la Domnul meu și Domnul vostru pentru ca voi să nu mă loviți cu pietre[5],', '[5] Pentru a mă ucide sau „să nu mă loviți cu vorbele voastre sau să îmi faceți rău altfel”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'Iar dacă nu voiți să mă credeți, stați departe de mine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'Și L-a chemat el pe Domnul lui, [spunând]: „Aceștia sunt un popor de oameni nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, '[Allah a spus] „Deci, purcede noaptea împreună cu robii Mei! Însă voi veți fi urmăriți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'Și lasă marea liniștită[6]! Ei sunt oșteni sortiți înecului!”', '[6] După ce s-a despicat pentru ca soldații lui Faraon să îi urmeze pe Fiii lui Israel și să fie înecați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'Câte grădini și izvoare au lăsat [în urma lor],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'Câte ogoare și locuri minunate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'Și câte plăceri de care s-au bucurat ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Așa [a fost]! Și am lăsat Noi un alt popor care să-i moștenească,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'Și nu i-au plâns pe ei nici Cerul, nici Pământul și nu li s-a dat lor niciun răgaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'Și i-am mântuit Noi pe Fiii lui Israel de chinul cel umilitor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'De Faraon care era îngâmfat și întrecea măsura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'Și Noi i-am ales pe ei cu bună știință peste [toate] lumile', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'Și le-am dat lor semne în care s-a aflat încercare limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'Cu adevărat, acești [necredincioși] spun:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, '„Nu este pentru noi decât prima noastră moarte și nu vom mai fi noi readuși la viață;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'Aduceți-i [înapoi] pe părinții noștri, dacă voi spuneți adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Oare sunt ei mai buni sau poporul lui Tubba''[7] și cei de dinainte de ei? Noi i-am făcut să piară, pentru că ei au fost nelegiuiți.', '[7] Neamul lui Saba');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Și nu am făcut Noi Cerurile și Pământul și cele ce se află între ele, jucându-ne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Nu le-am făcut Noi decât întru adevăr, însă cei mai mulți dintre ei nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'Cu adevărat, Ziua Judecății este timpul hotărât pentru ei toți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'O Zi în care un aliat nu va putea fi de niciun folos unui [alt] aliat și în care ei nu vor fi ajutați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'În afară de cei cărora Allah le va arăta Îndurare, căci El este Al-''Aziz [Puternic] și Ar-Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'Cu adevărat, pomul Zaqqum', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'Va fi hrana păcătosului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'Ca smoala topită va fierbe în pântece,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'Ca apa clocotită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, '[Va fi poruncit] „Apucați-l și târâți-l pe el în mijlocul Iadului!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'Apoi turnați asupra capului său din chinul apei fierbinți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, '[Și i se va spune]: „Gustă! Tu ești puternic și nobil[8]!', '[8] Așa cum pretindea pe Pământ. El este chinuit cu aceste cuvinte în Iad drept amintire și pedeapsă suplimentară');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Cu adevărat, aceasta este aceea de care vă îndoiați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'Cu adevărat, cei cu frică [de Allah] se vor afla într-un loc sigur,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'În grădini și printre izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'Vor purta straie de mătase și brocart, șezând față în față.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Așa [va fi]! Și îi vom căsători Noi cu femei frumoase cu ochii mari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'Și în ele vor cere în deplină liniște tot felul de fructe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'Nu vor gusta în ele moartea, afară de moartea cea dintâi [din viața lumească]. Și Allah îi va feri pe ei de chinul Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'Aceasta este ca Îndurare de la Domnul tău și aceasta este marea izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'Și, cu adevărat, Noi l-am făcut ușor [Coranul], în limba ta, astfel încât ei să ia aminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'Așteaptă [o, Mohammed] fiindcă și ei așteaptă [sfârșitul tău].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Ha'', Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Revelarea Cărții este de la Allah Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'Cu adevărat, în Ceruri și pe Pământ sunt semne pentru cei care cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'Și în propria voastră făptură și în vietățile pe care El le-a risipit se află semne pentru un popor de oameni care cred cu tărie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'Și în schimbarea nopții și zilei și în hrana pe care Allah a pogorât-o din cer și a înviat Pământul cu ea, după ce el a fost mort, și în schimbarea vânturilor se află semne pentru un popor de oameni care pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'Acestea sunt Versetele lui Allah pe care Noi ți le recităm în tot adevărul. Și în ce cuvânt ar mai putea ei să creadă, după [Cuvântul lui] Allah și după Versetele Lui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'Vai pentru tot mincinosul păcătos!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'Care aude Versetele lui Allah care i se recită, apoi stăruie cu îngâmfare, de parcă nu le-ar fi auzit. Deci vestește-i lui pedeapsă dureroasă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'Iar dacă știe ceva din Versetele Noastre, el le ia în râs. Aceștia vor avea parte de pedeapsă umilitoare;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'În urma lor[2] se află Iadul și nu le vor fi lor de folos nimic din cele pe care le-au agonisit și nici ceea ce și-au luat ei ca aliați în locul lui Allah. Și vor avea ei parte de mare chin.', '[2] A se vedea 14:16');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'Acesta [Coranul] este o călăuză, iar cei, care tăgăduiesc Versetele Domnului lor, vor avea parte de chinurile unei osânde dureroase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Allah este Cel care v-a supus vouă marea, ca să plutească vasele pe ea, la Porunca Sa, și pentru ca voi să umblați în căutarea Harului Său. Poate că voi veți fi mulțumitori!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'Și El v-a supus vouă toate cele care se află în Ceruri și care se află pre Pământ; toate sunt de la El. Și întru aceasta se află semne pentru un popor de oameni care chibzuiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'Spune-le [o, Mohammed] celor care cred, să-i ierte pe cei care nu nădăjduiesc în zilele lui Allah [cei care nu apreciază binecuvântările], în care El va răsplăti[3] [fiecare] popor [de oameni] după cele pe care le-au agonisit!', '[3] În Viața de Apoi cei care vor ierta vor fi răsplătiți și cei care au făcut rău vor fi pedepsiți. Acesta a fost începutul chemării la Islam (dauah) înainte de permisiunea pentru luptă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Cel care face o faptă bună o face pentru el, iar cel care săvârșește răul [o face] împotriva lui. Apoi, la Domnul vostru veți fi aduși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Noi le-am dat Fiilor lui Israel Cartea, înțelepciunea[4], Profeția și i-am înzestrat pe ei cu bunuri și i-am ales înaintea celorlalte lumi.', '[4] Înțelegerea legii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'Noi le-am dat semne limpezi asupra Poruncii, însă ei nu au fost în neînțelegere decât după ce le-a venit știința, din pricina nelegiuirii lor. Domnul tău va judeca între ei în Ziua Învierii cu privire la cele asupra cărora au fost în neînțelegere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'Apoi te-am așezat Noi pe calea cea adevărată a religiei. Urmeaz-o, așadar, și nu urma poftelor celor care nu știu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'Cu adevărat, ei nu-ți vor fi de niciun folos, în fața lui Allah. Cei nedrepți își sunt aliați unii altora, în vreme ce Allah este Ocrotitorul celor cu frică.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'Acesta [Coranul] conține dovezi limpezi pentru oameni, ocârmuire și îndurare pentru un popor de oameni care cred cu tărie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Ori socotesc cei care au săvârșit fapte rele că îi vom face pe ei deopotrivă cu cei care au fost cu credință și au împlinit fapte bune, atât în viața lor cât și după moartea lor? Rău judecă ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'Allah a creat Cerurile și Pământul în adevăr și pentru ca fiecare suflet să fie răsplătit după ceea ce a agonisit. Și ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Îl vezi tu pe cel care și-a luat dorința [proprie] drept dumnezeu al lui și pe care Allah îl duce în rătăcire din cauza științei[5] și-i pecetluiește auzul său și inima sa și întinde un văl peste vederea lui? Cine-l va călăuzi pe el după Allah? Oare voi nu luați aminte?', '[5] Aceasta se poate referi la Știința lui Allah despre respectiva persoană și despre preferințele pentru înclinațiile sale sau la cunoașterea acelei persoanei despre adevăr deși l-a refuzat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'Ei spun: „Nu este decât viața noastră pământească! Noi murim și trăim și nu ne distruge nimic, decât timpul!” Însă ei nu au știință despre aceasta, ci ei doar își închipuie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'Iar când li se recită lor Versetele Noastre cele limpezi, atunci ei nu au alt temei decât să spună: „Faceți-i să revină pe părinții noștri, de grăiți voi adevăr!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'Spune: „Allah vă dă viață, apoi vă dă moarte, apoi vă va aduna pe voi în Ziua Învierii! Nu este îndoială întru aceasta, însă cei mai mulți oameni nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'A lui Allah este Împărăția Cerurilor și a Pământului, iar în Ziua când va sosi Ceasul, în Ziua aceea vor pierde cei care o iau în deșert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'Și vei vedea fiecare comunitate căzută în genunchi [îngenunchiată]. Fiecare comunitate va fi chemată la cartea sa [a faptelor lor].” Astăzi veți primi voi răsplată pentru ceea ce ați săvârșit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Aceasta este cartea Noastră, care vă grăiește vouă adevărul. Cu adevărat, Noi am scris [în ea][6] ceea ce ați făcut”.', '[6] De către Îngerii care au înregistrat faptele');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'În ce-i privește pe cei care au fost cu credință și au împlinit fapte bune, pe ei Domnul lor îi va lăsa să intre sub Îndurarea Sa. Aceasta este izbânda învederată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'În ceea ce-i privește pe cei care nu au fost cu credință, [li se va spune lor]: „Oare nu vi s-au recitat vouă Versetele Mele? Însă voi ați fost aroganți și ați fost un popor de nelegiuiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Și ori de câte ori s-a spus: „Făgăduința lui Allah este adevăr și nu este îndoială asupra Ceasului”, atunci ați spus voi: „Noi nu știm ce este Ceasul. Noi nu facem decât să presupunem, însă noi nu suntem încredințați”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'Și li se vor arăta lor relele ce le-au săvârșit și îi vor împresura pe ei cele pe care le-au luat în batjocură.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'Și li se va spune lor: „Astăzi vă uităm Noi, întocmai așa cum ați uitat voi întâlnirea cu această Zi a voastră. Sălașul vostru va fi Focul și nu veți avea voi sprijinitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'Aceasta este pentru că voi ați luat Versetele lui Allah în derâdere și v-a înșelat pe voi viața lumească!” În Ziua aceea, ei nu vor fi scoși din el și nici nu vor fi ei primiți cu îndurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'Slavă lui Allah, Stăpânul Cerurilor și Stăpânul Pământului, Stăpânul [tuturor] lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'A Lui este Mărirea în Ceruri și pe Pământ și El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Ha’, Mim[1].', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Revelarea Cărții este de la Allah Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Noi nu am creat Cerurile și Pământul și cele care se află între ele decât întru adevăr și [pentru] un termen hotărât. Însă cei care nu cred se întorc de la cele despre care au fost preveniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'Spune [o, Mohammed]: „V-ați gândit voi la cei pe care îi chemați în locul lui Allah? Arătați-mi ce au creat ei pe Pământ! Sau au ei vreo parte [alături de Allah] la Ceruri? Aduceți-mi mie o carte [revelată] de dinainte sau vreo urmă de știință, dacă voi spuneți adevărul.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Și cine este mai rătăcit decât cel care invocă în locul lui Allah pe cineva care nu-i va răspunde lui până în Ziua Învierii, căci ei nu bagă în seamă chemarea acestora!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Iar când oamenii vor fi adunați [în Ziua Judecății], ei [cei pe care îi adorau] le vor fi dușmani și vor tăgădui adorația lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'Și când li se recită lor Versetele Noastre cele limpezi, spun cei care nu cred despre Adevăr, când vine la ei: „Aceasta este vrăjitorie limpede!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Sau ei spun: „El l-a plăsmuit!” Spune: „Dacă l-am plăsmuit, atunci voi nu aveți nicio putere pentru mine împotriva [pedepsei] lui Allah! Însă El Știe prea bine ceea ce vorbiți voi împotriva lui [a Coranului]. El este de ajuns ca Martor între mine și între voi. Și El este Ghafur [Iertător], Rahim [Îndurător]”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'Spune: „Eu nu sunt nou între trimiși[2] și nu știu ce se va face cu mine și nici cu voi. Eu nu urmez decât ceea ce îmi este revelat și nu sunt decât un prevenitor limpede!”', '[2] Nu sunt nici primul Trimis, nici nu aduc ceva diferit față de ceilalți Trimiși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'Spune: „Ce spuneți voi, dacă [se adeverește că el] este de la Allah și voi îl tăgăduiți, în vreme ce un martor dintre Fiii lui Israel face mărturie că este deopotrivă cu ea [cu Tora] și el crede, în vreme ce voi sunteți aroganți?” Cu adevărat, Allah nu călăuzește poporul de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'Și cei care nu cred spun către cei care cred: „De ar fi fost el bun, nu ne-ar fi luat-o ei înainte cu aceasta!” Și cum nu se vor lăsa călăuziți de el, vor spune ei: „Aceasta este o minciună veche!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Însă mai înainte de el a fost Cartea lui Moise, ca îndreptar și ca îndurare, iar aceasta este o Carte care întărește, în limba arabă, pentru a-i preveni pe cei care au fost nedrepți și ca bunăvestire pentru făcătorii de bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Cu adevărat, cei care spun „Domnul nostru este Allah!” și urmează calea cea dreaptă nu se vor teme și nici nu vor fi ei mâhniți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Aceia vor fi oaspeții Paradisului, veșnic sălășluitori în el, ca răsplată pentru ceea ce au săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'Noi i-am poruncit omului să le arate bunătate părinților săi. Mama sa l-a purtat cu dureri și l-a născut cu dureri. Purtarea lui și [până la] înțărcarea lui sunt treizeci de luni. Iar când ajunge în plină putere și împlinește patruzeci de ani, el spune: „Doamne, ajută-mă pe mine ca să-Ți aduc mulțumire pentru binefacerea Ta, cu care Te-ai îndurat de mine și de părinții mei, și să împlinesc o faptă bună care să-Ți placă! Și fă ca urmașii mei să fie oameni buni [evlavioși]! Eu mă întorc la Tine, căindu-mă, și eu sunt dintre cei supuși [musulmani].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'Aceștia sunt cei de la care primim [faptele lor] cele bune pe care le-au împlinit și peste ale căror fapte rele Noi trecem [cu vederea]. [Ei vor fi] dintre oaspeții Raiului: o făgăduință adevărată ce le-a fost făcută lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'Dar [este și] cel care spune către părinții săi: „Uff[3] vouă; îmi făgăduiți că voi fi scos [din mormânt la viață], după ce au trecut [atâtea] popoare înainte de mine [și ele nu au fost înviate]!” Iar ei [părinții] cer ajutor de la Allah, [spunând]: „Vai ție! Fii cu credință! Făgăduința lui Allah este adevărată!” Dar el răspunde: „Acestea nu sunt decât povești ale celor de demult!”', '[3] O expresie de iritare și silă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'Aceștia sunt cei cărora li s-a cuvenit cuvântul [prescris] dintre popoarele de djinni și de oameni care au trecut mai înainte de ei, că ei vor fi pierduți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'Și pentru fiecare sunt trepte [de răsplată și pedeapsă], pentru ceea ce au făcut, pentru ca [Allah] să-i răsplătească pe ei după faptele lor; și ei nu vor fi nedreptățiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'Și în Ziua când cei care nu au crezut vor fi dați Focului, [li se va spune lor]: „Voi ați primit lucrurile voastre bune în viața cea pământească și v-ați bucurat pe deplin de ele! Astăzi voi veți fi răsplătiți cu chinul umilinței, pentru că ați fost aroganți pe Pământ, fără drept, și pentru că ați fost nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'Și spune [Mohammed] de fratele lui ’Ad[4], când a prevenit el pe poporul său din Al-’Ahqaf - și au trecut prevenitori și mai înainte de el și după el - [spunând]: „Adorați-L voi numai pe Allah! Eu mă tem pentru voi de chinul unei zile mari!”[5]', '[4] Profetul Hud
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'Ei au spus: „Ai venit la noi ca să ne depărtezi de la zeii noștri? Adu-ne nouă cele cu care ne ameninți, dacă ești tu dintre cei care grăiesc adevăr!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, 'El le-a spus: „Știința [despre timpul ei] se află numai la Allah. Eu vă vestesc cele cu care am fost trimis, însă văd că voi sunteți un popor de oameni neștiutori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'Și când au văzut un Nor, venind către văile lor, au spus: „Acesta este un Nor care ne va da ploaie!” „Ba nu! El este ceea ce ați cerut voi să vină mai degrabă[6]: un vânt în care se află pedeapsă dureroasă,', '[6] Atunci când l-ați provocat pe Profetul vostru. A se vedea v. 22 din acest Capitol');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'Care nimicește totul, la porunca Domnului său!” Și nu s-au mai văzut decât sălașurile lor. Astfel am răsplătit Noi poporul de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'Și i-am întărit Noi pe ei cu ceea ce nu v-am întărit pe voi [o, Qurayș]. Și i-am dăruit pe ei cu urechi, cu ochi și cu inimi, dar nu le-au fost lor de niciun folos nici urechile lor, nici ochii lor, nici inimile lor, fiindcă ei au tăgăduit semnele lui Allah și i-a împresurat pe ei cea pe care au luat-o în râs.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Noi am nimicit cetățile din jurul vostru și am tâlcuit semnele [versetele] în fel și chip, pentru ca ei să se întoarcă [de la necredință].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'De ce nu i-au ajutat cei pe care i-au luat ei, în locul lui Allah, ca zei ca să se apropie [de El][7]. Însă ei i-au părăsit și aceasta a fost doar o minciună a lor și ceea ce ei au plăsmuit.', '[7] Așa cum spun ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'Și [spune, o, Mohammed,] când Noi am abătut către tine o ceată de djinni ca să asculte Coranul. Și când s-au adunat, au spus: „Ascultați cu luare-aminte!”. Iar când s-a terminat, s-au întors la poporul lor ca îndemnători și prevenitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'Și au spus: „O, popor al nostru! Noi am auzit o Carte, care a fost trimisă după Moise, întărind ceea ce a fost înainte de ea. Ea călăuzește către Adevăr și către o cale dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'O, popor al nostru! Răspundeți celui [Mesagerului] care cheamă la Allah[8] și credeți în el, căci Allah vă va ierta din păcatele voastre și vă va apăra pe voi de o pedeapsă dureroasă.', '[8] Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'Dar cel care nu-i va răspunde celui care cheamă la Allah nu va scăpa de puterea [lui Allah] pe Pământ și nu va avea ocrotitori în locul Lui. Aceia se află în rătăcire învederată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Oare nu văd ei că Allah care a creat Cerurile și Pământul și nu a fost ostenit la facerea lor este în stare să-i aducă la viață pe morți? Ba da, cu adevărat, El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'Și în Ziua când vor fi aduși la Foc cei care nu au crezut, [li se va spune lor]: „Oare nu este acesta adevărul?” Ei vor spune: „Ba da, pe Domnul nostru!” Va spune: „Gustați chinul pentru ceea ce ați tăgăduit!”[9]', '[9] Sau „fiindcă nu ați crezut”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'Deci ai răbdare [o, Mohammed], așa cum au avut cei statornici dintre Trimiși și nu cere să vină degrabă asupra lor[10]! Și în Ziua când vor vedea ce li se promite, atunci li se va părea că nu au rămas [pe Pământ] decât un ceas dintr-o zi. Iată o vestire! Și oare cine să fie nimiciți, în afară de poporul de nelegiuiți?', '[10] Pedeapsa lui Allah pentru necredincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Celor care nu cred și opresc [pe ceilalți] de la calea lui Allah, El le va zădărnici faptele lor[1],', '[1] Nu vor avea nicio răsplată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'Iar acelora care cred și săvârșesc fapte bune și cred în ceea ce i-a fost trimis lui Mohammed - și acesta este Adevărul de la Domnul lor! - El le va șterge faptele lor cele rele și va îndrepta starea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'Aceasta pentru că cei care nu cred urmează deșertăciunea și cei care cred urmează Adevărul [venind] de la Domnul lor. Astfel face Allah pilde pentru oameni[2].', '[2] Pentru ca ei să știe care sunt rezultatele alegerii lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Atunci când îi întâlniți [în luptă] pe cei care nu cred, loviți-le gâturile, iar când îi slăbiți pe ei, legați-i strașnic în lanțuri[3] și apoi, [arătați] fie îndurare[4], fie răscumpărare, până ce războiul se sfârșește. Astfel [v-a fost poruncit], iar de ar Voi Allah, El s-ar răzbuna pe ei, însă El vă încearcă pe unii prin alții [prin luptă]. Iar celor care sunt uciși pe calea lui Allah - El nu le va lăsa faptele lor să fie în deșert.', '[3] Luați-i pe cei care au rămas drept captivi
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'El îi va călăuzi și va îndrepta starea lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'Și îi va face pe ei să intre în Paradisul pe care El l-a făcut cunoscut lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'O, voi cei care credeți! Dacă voi veți sprijinii cauza lui Allah, vă va sprijini și El pe voi și va întări picioarele voastre [pe calea Sa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'Dar cei care nu cred vor avea parte de nenorocire și Allah va lăsa faptele lor să fie în deșert.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'Aceasta fiindcă ei au pizmuit ceea ce a pogorât Allah și, de aceea, El a zădărnicit faptele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Oare nu au purces ei prin lume ca să vadă cum a fost sfârșitul celor de dinainte de ei? Allah i-a nimicit. Și asemenea [soartă] vor avea cei care nu cred.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'Aceasta pentru că Allah este Ocrotitorul celor care cred și pentru că cei, care nu cred, nu au niciun ocrotitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Cu adevărat, Allah îi duce pe cei care cred și săvârșesc fapte bune în Grădini pe sub care curg râuri, în vreme ce cei care nu cred se vor bucura [în această lume] și vor mânca așa cum mănâncă dobitoacele [cu lăcomie] și Focul le va fi lor sălaș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'Și câte cetăți mai puternice decât cetatea ta [Mecca], care te-a alungat, am făcut Noi să piară, fără să aibă ei niciun ajutor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Oare cel care se ține de o dovadă limpede [venită] de la Domnul său este ca acela căruia i s-a înfrumusețat fapta sa rea și a urmat poftelor lui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Iată descrierea Paradisului care le-a fost făgăduit celor cu frică de Allah: în el sunt râuri cu apă care nu se schimbă[5] și râuri cu lapte al cărui gust nu se modifică și râuri de vin spre plăcerea celor ce beau și râuri de miere limpede. Și vor avea în el din toate roadele precum și iertare de la Domnul lor. [Oare locuitorii săi sunt] ca cei care vor sălășlui veșnic în Foc și ca cei cărora li se va da să bea apă clocotită, ce le va mărunți intestinele?', '[5] La gust sau ca miros, nu este nici stagnantă și nici poluată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Și printre ei sunt unii care ascultă la tine [o, Mohammed], însă numai ce ies de la tine și le spun ei celor cărora li s-a dăruit cunoașterea: „Ce a spus el adineauri?” Aceștia sunt cei cărora Allah le-a pecetluit inimile și care au urmat poftelor lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'Iar celor care se află pe calea cea bună - El le sporește călăuzirea și le dăruiește lor evlavie[6].', '[6] Taqua, însemând pietate, frica de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Și oare așteaptă ei altceva decât Ceasul, să vină asupra lor pe neașteptate? Semnele lui au și venit! Și cum să mai fie prevenirea lor, când va veni asupra lor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Deci să știi [o, Mohammed] că nu există altă divinitate afară de Allah și cere iertare pentru păcatele tale[7] și pentru dreptcredincioși și dreptcredincioase. Allah Cunoaște umbletul vostru [pe pământ] și odihna voastră [în casele voastre].', '[7] A se vedea 40:55');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'Cei care cred spun: „De ce nu ne este trimisă o Sură?”[8] Dar când este revelată o Sură limpede, în care este pomenită lupta, îi vezi pe cei care au o boală în inimile lor privind spre tine cu privirea aceluia care este leșinat [de teamă] la apropierea morții. Dar ar fi fost mai bine pentru ei[9] [să se supună].', '[8] În care să le fie dată permisiunea de a lupta cu dușmanii lor
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'Ascultarea și vorba cuviincioasă [ar fi fost mai bune]. Apoi, când lucrul este hotărât, ar fi mai bine dacă ei ar trudi pentru Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Și dacă vă întoarceți voi[10], [dacă vi s-ar da puterea] nu s-ar putea să semănați voi stricăciune pe pământ și să rupeți legăturile voastre de rudenie?', '[10] De la Islam sau de la Jihad (lupta pentru cauza lui Allah)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'Aceștia sunt cei pe care i-a blestemat Allah și i-a făcut surzi și le-a orbit vederile lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Oare ei nu cugetă la Coran sau peste inimile lor sunt lacăte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Cu adevărat, pe cei care întorc spatele [renunțând la Islam], după ce drumul cel drept li s-a arătat cu limpezime, îi ispitește Șeitan și-i înșeală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'Aceasta pentru că ei le spun celor care pizmuiesc ceea ce trimite Allah[11]: „Noi voim să dăm ascultare la o parte a poruncilor voastre!” Însă Allah Cunoaște ceea ce tăinuiesc ei.', '[11] Evreii din Medina');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'Și cum [va fi] când îi vor lua Îngerii și-i vor lovi peste fețele și peste spinările lor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Aceasta pentru că ei urmează ceea ce Îl mânie pe Allah și pizmuiesc ceea ce Îi aduce Mulțumire Lui și, de aceea, El va face zadarnice faptele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Ori își închipuie cei care au boală în inimile lor că Allah nu va scoate la iveală ura lor ascunsă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'Dacă am voi Noi, ți i-am arăta ție și tu i-ai recunoaște pe ei după semnele lor. Dar o să-i cunoști tu după tonul vorbei lor. Iar Allah Cunoaște faptele voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'Și vă vom încerca până ce îi vom face cunoscuți pe cei care luptă [pentru Cauza lui Allah] dintre voi și pe cei [statornici] și răbdători și [vă] vom încerca [pentru a vădi care este] situația voastră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Cu adevărat, cei care nu cred, împiedică [pe ceilalți] de la calea lui Allah și se împotrivesc Trimisului, după ce li s-a arătat lor limpede calea cea dreaptă, nu-i vor pricinui lui Allah nimic rău și El va zădărnici faptele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'O, voi cei care credeți! Fiți cu ascultare față de Allah și fiți cu ascultare față de Trimis și nu faceți ca faptele voastre să fie în deșert!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Cu adevărat, cei care nu cred și împiedică de la calea lui Allah, iar apoi mor fiind necredincioși, Allah nu-i va ierta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'Nu slăbiți [în înfruntarea voastră] și nu chemați la pace pe când voi sunteți superiori [în luptă], căci Allah este cu voi și El nu vă va lipsi niciodată de [răsplata pentru] faptele voastre!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, '[Această] viața pământească este numai joacă și glumă. Și de veți crede voi și de veți fi cu frică [de Allah], vă va dărui El răsplata voastră și nu vă va cere bunurile voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Și de vi le-ar cere El și v-ar stânjeni pe voi, ați fi voi zgârciți și El ar scoate la iveală răutățile voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'Iată că voi sunteți chemați să cheltuiți pe calea lui Allah. Și unii dintre voi sunt zgârciți, iar cel care este zgârcit este zgârcit numai spre paguba lui însuși. Allah este de ajuns pentru Sine, iar voi sunteți săraci. Iar de vă veți întoarce [de la Islam], El vă va înlocui cu un alt popor și apoi aceia nu vor fi asemenea vouă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'Cu adevărat, Noi ți-am dat ție [o, Mohammed] o biruință învederată[1],', '[1] Ibn Masud a spus: „Voi [oamenilor] credeți că este vorba de Mecca, însă noi credem că este vorba despre Tratatul de la Hudaybiyah.” Al-Bukhari a consemnat o relatare similară de la al-Bara bin Azib. Deși inițial, considerat de către companioni a fi un pas în spate, tratatul de fapt a ajutat la răspândirea islamului și astfel, la cucerirea Meccăi doi ani mai târziu.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'Pentru ca Allah să-ți ierte păcatele tale [greșelile], cele care au fost și cele care vor veni, să-Și împlinească binefacerea Sa asupra ta și să te călăuzească pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'Și pentru ca Allah să-ți dea un mare ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'El este Cel care a trimis liniștea în inimile dreptcredincioșilor, pentru a spori credința lor cu [noua lor] credință - și ai lui Allah sunt soldații din Ceruri și de pe Pământ, iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'Pentru a-i face să intre pe dreptcredincioși și pe dreptcredincioase în Grădini pe sub care curg râuri și în care ei vor fi veșnic sălășluitori și pentru ca să le ierte păcatele lor cele rele. Și aceasta este pentru Allah o mare izbândă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'Și pentru ca El să-i pedepsească pe cei ipocriți și pe cele ipocrite, pe politeiști și pe politeiste, care nutresc gând rău despre Allah. Asupra lor se va abate nenorocirea umilitoare. Allah s-a mâniat pe ei, i-a blestemat și le-a pregătit lor Iadul. Și ce soartă rea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'Ai lui Allah sunt soldații din Ceruri și de pe Pământ, iar Allah este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'Cu adevărat, Noi te-am trimis pe tine ca martor, vestitor de bine și prevenitor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'Pentru ca voi să credeți în Allah și în Trimisul Său și pentru ca să-l sprijiniți și să-l cinstiți [pe Profet] și să-L preamăriți dimineața și la sfârșitul zilei [pe Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Cu adevărat, cei care fac jurământ de credință față de tine [o, Mohammed] fac jurământ de credință față de Allah; Mâna[2] lui Allah este deasupra mâinilor lor[3]. Cel care calcă [jurământul] îl calcă numai în defavoarea lui, iar celui care-și ține legământul făcut lui Allah, El îi va Dărui răsplată mare.', '[2] A se vedea 2:19
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Aceia dintre arabii beduini care au rămas în urmă îți vor spune: „Am fost ocupați cu averile noastre și cu familiile noastre, deci roagă-te de iertare pentru noi!” Rostesc cu limbile lor ceea ce nu este în inimile lor. Spune: „Cine apoi are putere [să intervină] la Allah, dacă vă Voiește El un rău sau dacă vă Voiește El un bine? Ba nu, Allah este Bineștiutor a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Voi vă închipuiți că Trimisul și dreptcredincioșii nu se vor mai întoarce nicicând la familiile lor. Și aceasta a fost împodobită în inimile voastre. Însă ați gândit voi gând rău și ați fost un popor pierdut”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'Iar cel care nu crede în Allah și în Trimisul Său [să știe că] Noi am pregătit pentru necredincioși Flăcările.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'A lui Allah este Împărăția Cerurilor și a Pământului. El iartă cui Voiește El și îl pedepsește pe acela care Voiește El. Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'Cei care rămân de obicei în urmă vor spune atunci când voi purcedeți la prăzi ca să le luați: „Lăsați-ne pe noi să vă urmăm!” Ei voiesc să schimbe Cuvântul lui Allah. Spune: „Voi nu ne veți urma! Așa a vestit Allah mai înainte!” Dar ei vor spune: „Voi ne pizmuiți!” Însă ei nu au înțeles decât numai puțin.[4]', '[4] Nu au înțeles decât aspectele materialele ale vieții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Spune arabilor beduini care au rămas în urmă: „Voi sunteți chemați împotriva unui popor de oameni cu mare putere și vă veți lupta cu ei sau se vor supune ei[5]. Și dacă veți asculta, vă va da Allah răsplată bună, iar dacă vă veți întoarce așa cum v-ați mai întors și mai înainte, vă va pedepsi El cu un chin dureros!”', '[5] Lui Allah în Islam');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'Nu este niciun păcat pentru cel orb, nici pentru cel șchiop nu este păcat și nici pentru cel bolnav nu este păcat [să rămână în urmă]. Însă pe cel care ascultă de Allah și de Trimisul Său îl va face El să intre în Grădini pe sub care curg pâraie, în vreme ce pe acela care se întoarce îl pedepsește El cu un chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'Allah a fost mulțumit de dreptcredincioși, când ei au făcut legământ cu tine [o, Mohammed] [acolo] sub pom [să moară în lupta pentru cucerirea Meccăi]. El a Știut ce a fost în inimile lor și a făcut să pogoare asupra lor liniștea și i-a răsplătit pe ei cu biruință apropiată[6],', '[6] Cea de la Khaybar, care a precedat cucerirea orașului Mecca');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'Ca și cu prăzi numeroase, pe care ei le vor aduna. Allah este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Allah v-a făgăduit vouă [în viitor și alte] prăzi numeroase pe care voi le veți dobândi și a grăbit aceasta pentru voi. Și a îndepărtat El mâinile oamenilor de la voi, pentru ca să fie un semn pentru dreptcredincioși și pentru ca să vă călăuzească pe voi pe un drum drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'Și [v-a promis] alte [victorii] asupra cărora voi nu aveți putere [deocamdată], dar pe care Allah le-a cuprins[7], căci Allah este cu Putere peste toate.', '[7] Pregătit sau decretat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'Și dacă cei care nu cred [din Mecca] ar fi luptat împotriva voastră, ar fi întors spatele și atunci nu ar mai fi aflat nici ocrotitor și nici ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, '[Aceasta este] Legea lui Allah, care a fost și mai înainte și nu vei afla schimbare pentru Legea lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'El este Cel care a îndepărtat mâinile lor de la voi și mâinile voastre de la ei, în Valea Meccăi, după ce v-a dat vouă izbândă asupra lor. Și Allah Vede bine ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'Ei sunt cei care nu au crezut și care v-au oprit pe voi de la Moscheea Al-Haram și jertfa[8] a fost împiedicată să ajungă la locul de junghiere. Dacă nu ar fi fost [în Mecca] bărbați credincioși și femei credincioase, pe care voi nu-i cunoșteați și pe care voi ați fi putut să-i omorâți [în luptă], fără să vă dați seama, ați fi avut voi parte de păcat. Allah primește în Îndurarea Sa pe cine Voiește El. Și de ar fi fost ei [necredincioșii de credincioși] despărțiți, i-am fi pedepsit Noi pe cei care nu credeau dintre ei cu chin dureros.', '[8] 70 de cămile intenționate pentru sacrificiu și pentru hrănirea săracilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'Și când cei care nu credeau purtau în inimile lor furia - furia neștiinței -, Allah a pogorât liniștea Sa asupra Trimisului Său și asupra credincioșilor și i-a făcut pe ei statornici la cuvântul evlaviei, pentru că ei au fost cei mai demni și mai vrednici de el. Allah este Atoateștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Cu adevărat, Allah a făcut adevărată viziunea prin care El i-a vestit Trimisului Său cu tot adevărul: Veți intra în Moscheea cea Sfântă, cu Voia lui Allah, în siguranță, cu părul ras și [cu părul] scurtat[9], fără să vă temeți! Dar pentru că El Știa ceea ce voi nu știați, a făcut El, înainte de aceasta, o biruință apropiată.', '[9] Îndeplinind ritualurile Pelerinajului Mic (Umrah)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'El este Cel care l-a trimis pe Trimisul Său cu îndreptare și cu religia Adevărului pentru ca să o facă să triumfe asupra întregii religii. Și Allah este de ajuns ca Martor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Mohammed este Trimisul lui Allah. Iar cei care stau alături de el sunt aspri față de necredincioși și sunt îndurători între ei. Îi vezi pe ei aplecați și prosternându-se [în rugăciune], căutând Mila lui Allah și mulțumirea Lui. Semnele prosternării se văd pe chipurile lor. Aceasta este imaginea lor în Tora. Și imaginea lor în Evanghelie este că ei sunt asemenea tulpinilor din care au odrăslit mlădițe, pe care le ajută, și apoi ele se îngroașă și se înalță pe tulpinile lor, spre bucuria semănătorilor. Cu ei, Allah îi umple de ciudă pe necredincioși. Și Allah a făgăduit acelora dintre ei care cred și împlinesc fapte bune, iertare și mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'O, voi cei care credeți! Nu luați [hotărâri] înaintea [hotărârii] lui Allah și a Trimisului Său și fiți cu frică de Allah! Allah este Sami'' [Cel care Aude Totul] [și este] ''Alim [Atoateștiutor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'O, voi cei care credeți! Nu ridicați glasurile voastre peste glasul Profetului și nu strigați când vorbiți cu el, așa cum strigați voi unii la alții, pentru ca faptele voastre să nu fie în deșert, fără ca voi să băgați de seamă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Cu adevărat, cei care coboară glasurile lor în prezența Trimisului lui Allah sunt cei ale căror inimi le-a încercat Allah pentru evlavie; ei vor avea parte de iertare și de răsplată mare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Cu adevărat, cei care te cheamă [o, Mohammed] din afara odăilor tale, cei mai mulți dintre ei nu au judecată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'Dacă ar avea ei răbdare până ce tu ieși la ei, ar fi mai bine pentru ei. Însă Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'O, voi cei care credeți! Dacă vine la voi un nelegiuit cu o veste, chibzuiți cu [mare] băgare de seamă, ca să nu pricinuiți rău unui popor, din neștiință, și să vă căiți (mai apoi) pentru ceea ce ați făcut!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'Și să știți că Trimisul lui Allah este printre voi. Dacă el v-ar da ascultare vouă în multe lucruri, ați cădea în necaz, însă Allah v-a făcut pe voi să iubiți credința și a împodobit-o în inimile voastre și v-a făcut pe voi să urâți necredința, ticăloșia și nesupunerea. Aceștia sunt cei care urmează calea cea dreaptă -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, '[Este] un Har de la Allah și o binecuvântare. Iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'Și dacă două cete de dreptcredincioși se ceartă între ele, voi împăcați-le! Dacă una dintre ele este nedreaptă cu cealaltă, atunci luptați împotriva celei care este nedreaptă până ce ea se întoarce la Porunca lui Allah, iar când se întoarce, atunci împăcați-le pe ele cu dreptate și fiți nepărtinitori. Cu adevărat, Allah îi Iubește pe cei drepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Dreptcredincioșii sunt frați. Deci împăcați-i pe cei doi frați ai voștri și fiți cu frică de Allah! Poate că veți afla Îndurare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'O, voi cei care credeți! Să nu râdă un popor de alt popor, care s-ar putea să fie mai bun decât el, nici femeile [să nu râdă] de alte femei, care s-ar putea să fie mai bune decât ele! Nu vă ocărâți și nu vă batjocoriți cu porecle unii pe alții. Ce rău este numele urât și rușinos, după credință! Iar cei care nu se căiesc, aceia sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'O, voi cei care credeți! Feriți-vă cu strășnicie de bănuieli. Cu adevărat, unele bănuieli sunt păcat! Nu vă iscodiți și nu vă ponegriți unii pe alții! Oare voiește vreunul dintre voi să mănânce carnea fratelui său mort? [Nu!] Voi ați urât aceasta! Și fiți cu frică de Allah, fiindcă Allah este Tauuab [Iertător] și Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'O, voi oameni! Noi v-am creat pe voi dintr-un bărbat și o femeie și v-am făcut pe voi popoare și triburi, pentru ca să vă cunoașteți. Cel mai cinstit dintre voi la Allah este cel mai evlavios[1] dintre voi. Allah este ''Alim [Atoateștiutor] [și] Khabir [Bineștiutor].', '[1] Literar: „cel care are cea mai mare „Taqua”, adică conștiință și frică de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Arabii beduini au spus: „Noi credem!” Spune: „Voi nu credeți! Ci spuneți: „Noi suntem supuși!”, fiindcă nu a intrat credința încă în inimile voastre! Și de veți arăta ascultare lui Allah și Trimisului Său, voi nu veți pierde nimic din faptele[2] voastre. Cu adevărat, Allah este Ghafur [Iertător], Rahim [Îndurător].”', '[2] Răsplata faptelor voastre');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'Dreptcredincioși sunt numai cei care cred în Allah și în Trimisul Său, care apoi nu s-au mai îndoit și au luat parte la luptă cu averile lor și cu sufletele lor, pe calea lui Allah. Aceștia sunt cei sinceri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'Spune: „Oare voiți să-I faceți cunoscută lui Allah credința voastră, când Allah Știe ce este în Ceruri și ce este pe Pământ și când Allah este Atoateștiutor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Ei îți amintesc că ți-au făcut cinste acceptând Islamul. Spune: „Nu-mi faceți nicio cinste mie cu Islamul vostru! Dimpotrivă, Allah v-a făcut vouă cinste prin aceea că v-a călăuzit spre credință, dacă voi sunteți adevărați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Cu adevărat, Allah știe Necunoscutul din Ceruri și de pre Pământ și Allah Vede bine ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Qaf[1]. Pe Coranul cel Glorios![2]', '[1] A se vedea 2:1
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Însă ei se miră că le vine ca prevenitor unul dintre ei și cei necredincioși zic:Acesta este lucru ciudat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'Oare după ce am murit noi și ne-am făcut țărână [vom mai fi noi readuși la viață]? Aceasta este o întoarcere depărtată.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Noi Știm ce mistuie Pământul din ei. Noi avem o Carte păstrătoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Însă ei au socotit Adevărul drept minciună, când a venit la ei. Și ei sunt într-o stare încurcată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'Oare nu se uită ei spre Cerul de deasupra lor cum l-am înălțat Noi și l-am înfrumusețat și cum nu are el niciun fel de crăpături?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'Iar Pământul l-am întins Noi și am așezat pe el munți neclintiți și am făcut să crească pe el din fiecare soi minunat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'Spre dovadă și îndemnare pentru fiecare rob care se căiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Și Noi trimitem din Cer apă binecuvântată cu care facem să crească grădini și grâne pentru seceriș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'Și palmieri semeți, cu ciorchini rânduiți unii peste alții,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'Ca hrană pentru robi. Și cu ea Noi dăm viață unui ținut mort. Astfel va fi și învierea [din morminte].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Înainte de ei[3], au învinuit de minciună poporul lui Noe, locuitorii din ar-Rass, Thamud,', '[3] Înainte de necredincioșii din Mecca');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'Și ’Ad, Faraon, și frații lui Lot,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'Locuitorii din Al-Ayka și poporul lui Tubba''. Toți i-au învinuit pe Trimiși de minciună și amenințarea Mea s-a adeverit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'Oare am ostenit Noi la creația cea dintâi? Ba nu, ei sunt în îndoială cu privire la o nouă creație [Învierea].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Noi l-am creat pe om și Noi Știm ce-i șoptește sufletul său, căci Noi suntem mai aproape de el[4] decât vâna gâtului,', '[4] Cunoaște totul despre el');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Când cei doi primitori [Îngerii care scriu] primesc[5], stând [unul] în dreapta și [celălalt] în stânga,', '[5] Și scriu fiecare cuvânt și faptă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'Și el [omul] nu va rosti niciun cuvânt, fără să aibă lângă el un supraveghetor pregătit [să scrie].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Și vine agonia morții cu adevărat: „Aceasta este cea de care tu te-ai ferit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'Se va sufla în Trâmbiță: Aceasta este Ziua amenințării.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'Și va veni fiecare suflet împreună cu un mânător și un martor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, '[Se va spune păcătosului]„Tu ai fost nepăsător față de aceasta. Și Noi am îndepărtat vălul tău și privirea ta este astăzi pătrunzătoare”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'Și însoțitorul său [Îngerul] va spune: „Iată ce se află la mine pregătit [scrierile]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, '[Allah va spune]: „Aruncați în Iad pe tot necredinciosul îndârjit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'Împiedicător al binelui, nelegiuit și bănuitor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'Care a așezat alături de Allah un alt dumnezeu!. Aruncați-l pe el la chinul cel aspru!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'Însoțitorul său [diavolul] va spune: „Doamne, eu nu l-am oropsit, ci el s-a aflat în rătăcire adâncă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, '[Allah] le va spune: „Nu vă certați în fața Mea! Eu v-am trimis amenințarea mai înainte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'La Mine vorba nu se schimbă și Eu nu sunt nedrept cu robii Mei!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'În Ziua aceea, Îi vom spune Iadului: „Te-ai umplut?” Iar el va răspunde: „Mai sunt încă [de venit]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'Și va fi Paradisul adus aproape de cei care se tem [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, '[Li se vor spune]: „Aceasta este ceea ce s-a făgăduit fiecărui om care se căiește, păzitor al legământului,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'Care a fost cu teamă de Ar-Rahman [Cel Milostiv], fără ca el să-L vadă, și care a venit [către El] cu inima plină de căință.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'Intrați în el cu pace!” Aceasta este Ziua veșniciei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'În el vor avea tot ceea ce vor voi. Și la Noi este și mai mult.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'Și câte popoare am nimicit Noi mai înainte de ei, care erau și mai puternice decât ei. Și au purces ei prin țară, [căutând]. Oare este vreo scăpare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'Întru aceasta este o îndemnare pentru cel care are inimă sau ascultă și este martor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Am creat Noi Cerurile și Pământul și ceea ce se află între ele în șase zile și nu Ne-a cuprins pe Noi nici cea mai mică osteneală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Deci răbdă [o, Mohammed] față de ceea ce spun ei și Preamărește-L cu Laudă pe Stăpânul tău, înainte de răsăritul Soarelui și înainte de asfințit [Rugăciunile de Fajr, Dohor, Asr];', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'Și în timpul unei părți din noapte Laudă-L pe El! Și după prosternări [după încheierea Rugăciunii obligatorii]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'Și ascultă în Ziua în care cel care cheamă[6] va chema dintr-un loc apropiat,', '[6] Un Înger care va vesti comanda lui Allah pentru Înviere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'În Ziua când vor auzi sunetul [Trâmbiței] cu adevărat! Aceasta va fi Ziua ieșirii [din morminte].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Cu adevărat, Noi dăm viață și dăm moarte și la Noi va fi întoarcerea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'În Ziua când se va crăpa Pământul [lăsându-i] pe ei [să iasă] grăbiți! Aceasta este o adunare ușoară pentru Noi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Noi Știm bine ce spun ei. Tu nu ești pus tiran[7] peste ei. Și îndeamnă-l prin Coran pe acela care se teme de amenințarea Mea!', '[7] Forțându-i pe oameni să creadă sau să se supună');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'Pe [vânturile] cele care risipesc, împrăștiind', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'Și [Norii] care poartă povară [de apă]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'Și cele [corăbiile] care lunecă ușor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'Și pe acei [Îngerii] care împart după poruncă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'Ceea ce vi se promite este adevărat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Iar răsplata este hotărâtă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'Pe Cerul cel bine întocmit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Voi vă aflați în vorbă învrăjbită[1],', '[1] Despre Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) și Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Prin care este ținut departe de el cel care a fost îndepărtat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Să fie blestemați mincinoșii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'Care stau nepăsători într-un potop [de confuzie]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'Ei întreabă: „Când va fi Ziua Judecății?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'În Ziua aceea, ei vor fi încercați prin Foc [și astfel pedepsiți]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, '[Și li se va spune:] „Gustați încercarea voastră! Aceasta este ceea ce voi ați căutat să grăbiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'Cu adevărat, cei ce se tem [de Allah] vor fi în Grădini și [printre] izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Primind ceea ce le dăruiește Domnul lor; înainte de aceasta ei doară au fost de binefăcători', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'Ei nu dormeau decât puțin în timpul nopții[2],', '[2] Rugându-se o parte din noapte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'Iar înainte de ivirea zorilor ei se rugau de iertare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'Și în averea lor se afla un drept pentru cerșetor și pentru cel nevoiaș.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'Pe Pământ se află semne pentru cei care cred cu putere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'Ca și în voi înșivă. Voi nu vedeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'Și în Cer se află înzestrarea voastră și ceea ce vi se făgăduiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'Pe Stăpânul Cerului și a Pământului! Aceasta este la fel de adevărat precum aceea că voi puteți vorbi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'A ajuns la tine istoria despre oaspeții cei cinstiți ai lui Avraam?[3]', '[3] Cei care erau Îngeri și au primit poziții onorabile de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Când au intrat la el și au zis „Pace!”, iar el le-a zis lor „Pace, oameni necunoscuți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'Apoi s-a dus el pe furiș la familia lui și a adus un vițel gras.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'Și l-a apropiat de ei, zicând: „Voi nu mâncați?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'Și l-a cuprins pe el frica[4], însă ei i-au zis: „Nu te teme!” Și i-au vestit lui [nașterea] unui fecior înțelept.', '[4] A se vedea 11:70');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'S-a apropiat soția lui, văicărindu-se, lovindu-și obrajii și a zis: „[Eu sunt] o femeie în vârstă stearpă...”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, 'Dar ei au spus: „Așa a grăit Domnul tău și El este Al-Hakim [Înțelept] [și] Al-''Alim [Atoateștiutor]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, '[Avraam] a spus: „Și ce v-a adus pe voi, o, Trimișilor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, 'Ei au răspuns: „Noi am fost trimiși la un neam de nelegiuiți[5],', '[5] Cei care l-au negat pe Lot');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'Ca să aruncăm asupra lor pietre de lut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'Însemnate de Domnul tău pentru nelegiuiți!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Și i-am scos Noi din ele [cetăți] pe cei care erau credincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'Dar nu am găsit printre ei decât o singură casă de supuși [musulmani][6],', '[6] Lot și cele două fiice ale sale, însă fără soția sa');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'Și am lăsat Noi în ea un semn pentru aceia care se tem de chinul cel dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, '[Și a fost un semn] și în Moise, când l-am trimis Noi cu o dovadă limpede la Faraon.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'Însă [acesta] s-a întors cu căpeteniile sale și a zis: „Un vrăjitor sau un nebun!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'Și l-am apucat Noi pe el împreună cu soldații lui și l-am aruncat în mare, căci și-a meritat-o!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, '[Și a fost un semn] și în ’Ad, când am trimis la ei vântul nerodnic,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Care nu a lăsat niciun lucru peste care s-a abătut, fără să nu-l fi făcut asemenea pulberii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'Și în Thamud când li s-a spus lor: „Bucurați-vă voi până la o vreme!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Și s-au împotrivit ei cu îndârjire poruncii Domnului lor și i-a lovit pe ei trăsnetul, pe când ei priveau.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'Și n-au mai fost ei în stare să se ridice și nu au fost de nimeni ajutați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'Și în poporul lui Noe, mai înainte, căci și ei au fost un neam de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Iar Cerul l-am înălțat cu Puterea Noastră și Noi îl lărgim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'Iar Pământul l-am întins și ce frumos l-am netezit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'Și din fiecare lucru Noi am creat perechi. Poate că voi vă veți lăsa îndemnați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'Deci fugiți voi la Allah[7]. Eu sunt pentru voi prevenitor limpede din partea Lui.', '[7] Întoarceți-vă la Allah și căutați refugiu la El de necredință și păcat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'Și nu așezați lângă Allah un alt dumnezeu! Eu sunt pentru voi prevenitor limpede din partea Lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'Tot astfel nu a venit la cei de dinainte de ei niciun Trimis fără ca ei să nu zică: „Este un vrăjitor sau un nebun!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Oare și-au lăsat ei această moștenire unii altora? Ba ei sunt mai degrabă un popor de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Deci întoarce-te de la ei și nu vei fi tu pedepsit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'Și îndeamnă, căci îndemnarea le este spre folos dreptcredincioșilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Eu nu i-am creat pe djinni și oameni decât pentru ca ei să Mă adore.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Eu nu Voiesc de la ei întreținere și nici nu Voiesc ca ei să Mă hrănească pe Mine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Într-adevăr Allah este Ar-Razzaq [Întreținătorul], Stăpânul puterii, Al-Matin [Cel Statornic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'Și cu adevărat, cei care sunt nedrepți au o parte [de pedeapsă] asemănătoare cu partea tovarășilor lor. Și să nu-Mi ceară ei să Mă grăbesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'Și vai celor care nu cred în Ziua lor, cu care sunt amenințați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'Pe At-Tur!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'Și pe Cartea scrisă[1]', '[1] Pe Tabla Bine Păstrată sau pe Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'Pe un pergament întins!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'Și pe Casa cea locuită[2]', '[2] Casa de adorare pentru Îngeri în ce-l de-al șaptelea Cer, comparabilă cu Ka’bah pe Pământ');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'Și pe bolta cea înaltă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'Și pe marea cea aprinsă![3]', '[3] În Ziua Învierii. Sau „pe marea care s-a revărsat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'Cu adevărat, pedeapsa Domnului tău va veni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Nimeni nu o va putea împiedica,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'În Ziua în care Cerul se va învolbura într-un vârtej', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'Și munții se vor urni din loc[4].', '[4] Vor fi precum praful și se vor mișca precum Norii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'Vai în Ziua aceea pentru cei care învinuiesc de minciună', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'Și care se joacă cu vorbe ușoare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'În Ziua aceea vor fi ei împinși în Iad, cu neîndurare [Îngerii vor spune]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, '„Acesta este Focul pe care voi l-ați luat drept minciună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'Oare aceasta este vrăjitorie sau voi nu vedeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Ardeți în el și răbdați sau nu răbdați, căci e totuna pentru voi; căci voi veți fi răsplătiți pentru ceea ce faceți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'Cu adevărat, cei cuvioși vor fi în Grădini și la plăcere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Bucurându-se de ceea ce le-a dat Domnul lor. Și Domnul lor îi va apăra de pedeapsa Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, '[Și li se va spune]: „Mâncați și beți în pace pentru ceea ce ați făcut,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'Întinși pe paturi rânduite!” Și Noi le vom da ca soațe hurii cu ochii mari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Aceia care cred și pe care scoborâtorii lor îi urmează în credință, pe aceia îi vom face să fie laolaltă cu scoborâtorii lor și nu le vom micșora întru nimic faptele lor[5]. Fiecare om va fi răspunzător pentru ceea ce a agonisit.', '[5] Răsplata faptelor lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Și le vom dărui lor spre întreținere fructe și carne, după cum vor pofti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'Și acolo își vor întinde ei o cupă unul altuia, în care nu este greșeală și nici păcat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'Și se vor plimba printre ei pentru a-i servi feciori ca niște mărgăritare bine păstrate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'Iar ei se vor întoarce unul către altul, întrebându-se.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'Și vor spune: „Cu adevărat, înainte, noi am trăit în mijlocul poporului nostru, temători,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'Însă Allah S-a Îndurat de noi și ne-a apărat de chinul vântului fierbinte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Pentru că noi L-am chemat și mai înainte, căci El este Al-Barr [Cel Milostiv], Ar-Rahim [Îndurător]”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Deci îndeamnă [o, Mohammed], căci, prin Îndurarea Domnului tău, tu nu ești un ghicitor și nici un nebun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Sau ei spun [despre tine]: „[Acesta este] un poet! Noi așteptăm [să-l lovească] pe el soarta amenințătoare.”[6]', '[6] Un fel de accident sau inevitabilă moarte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, 'Spune: „Așteptați, pentru că și eu voi fi împreună cu voi printre cei care așteaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Oare, le poruncesc mințile lor aceasta[7]? Ba ei sunt un popor de îndărătnici!', '[7] În acest verset se face o aluzie subtilă la liderii celor din Quraiș care considerau că au minți strălucite');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Sau ei spun: „El l-a născocit!” Ba nu, dar ei nu vor să creadă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'Să aducă ei o poveste asemenea lui dacă grăiesc adevăr!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Oare au fost ei creați de nimeni sau ei sunt creatorii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Sau au creat ei Cerurile și Pământul? Nu, ei nu cred cu convingere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Sau sunt cu ei comorile Domnului tău? Sau sunt ei stăpâni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Sau au ei o scară [către Paradis] de pe care ascultă? Să vină cei care ascultă dintre ei cu o dovadă limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Sau are El copile, iar voi aveți fii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Sau le ceri tu [o, Mohammed] o răsplată, încât ei sunt împovărați de grea datorie?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Sau știu ei Necunoscutul pentru ca să-l pomenească în scris?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Sau caută ei un vicleșug? Însă cei care nu cred sunt victime ale propriului lor vicleșug.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Sau au ei un alt dumnezeu decât Allah? Allah Preaslăvitul este mai Presus de ceea ce Îi asociază Lui!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'Și dacă văd ei bucăți de Cer căzând[8], atunci spun: „[Aceștia sunt] Nori îngrămădiți”.', '[8] Marcând începutul Pedepsei lui Allah, așa cum au cerut ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Lasă-i pe ei, până ce vor întâlni Ziua lor, când ei vor fi trăsniți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Ziua în care vicleșugul lor nu le va fi de niciun folos și în care nu vor fi ei ajutați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'Și, cu adevărat, cei care au fost nedrepți vor avea parte de un chin[9], pe lângă aceasta, dar cei mai mulți dintre ei nu știu.', '[9] Dacă nu în această viață, atunci în mormânt');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'Așteaptă [o, Mohammed] cu răbdare Judecata Domnului tău, căci tu ești sub Ochii Noștri! Și Laudă Mărirea Domnului tău, când te trezești din somn,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'Și laudă-L pe El și o vreme din noapte, ca și la asfințitul Stelelor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'Pe Steaua care apune!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'Tovarășul vostru [Mohammed] nu este rătăcit, nici nu este pe un drum greșit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Nici nu rostește nimic după pofta lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'El [Coranul] nu este decât o revelație trimisă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, 'L-a învățat pe el cel cu puteri deosebite [Îngerul Gavriil],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'Stăpânul înțelepciunii[1] care i s-a arătat cu înfățișarea sa adevărată[2],', '[1] Care are putere în corp și în minte
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'Când se afla în zarea cea mai înaltă[3].', '[3] În Cer, deasupra de orizontul de est');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Apoi s-a apropiat și a coborât mai jos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'Încât s-a aflat la două bătăi de arc sau chiar mai aproape.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'Și i-a revelat robului Său[4] ceea ce i-a fost revelat.', '[4] Profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'Inima[5] nu a mințit în ceea ce a văzut.', '[5] Mintea sau percepția (profetului Mohammed -pacea și binecuvântarea lui Allah fie asupra sa-)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Oare vă îndoiți de ceea ce a văzut?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'L-a mai văzut el la o altă coborâre[6],', '[6] Cu altă ocazie. În timpul călătoriei la Ceruri (al-Miraj), Profetul (pacea și binecuvântarea lui Allah fie asupra sa) l-a văzut și atunci în forma sa adevărată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'La Lotusul de la Capăt[7],', '[7] Sidrat al-Muntaha, un pom din al șaptelea Cer');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'Lângă care se află Grădina Adăpostului,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Când îi vine lotusului ce-i vine[8].', '[8] Acolo el (pacea și binecuvântarea lui Allah fie asupra sa) l-a văzut pe Îngerul Gavril în forma sa de Înger');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'Privirea [Profetului (pacea și binecuvântarea lui Allah fie asupra sa)] nu s-a abătut și nici nu a trecut mai departe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'El a văzut unele din semnele cele mai mari ale Domnului său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Ați văzut voi pe Al-Lat și pe Al-''Uzza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'Și pe alta, pe Manat, cea de-a treia?[9]', '[9] Cele trei nume din acest Verset și cel anterior sunt ale „zeițelor” bine-cunoscute ce erau adorate de arabii păgâni înainte de Islam');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Oare voi aveți băiat și El are copilă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'Aceasta este, așadar, o împărțire nedreaptă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'Ele nu sunt decât niște nume pe care le-ați dat voi și părinții voștri. Allah nu a trimis asupra lor nicio putere. Ei nu urmează decât bănuiala și ceea ce poftesc sufletele, în vreme ce de la Domnul lor le-a venit călăuzirea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'Oare are omul ceea ce poftește?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Dar ale lui Allah sunt Viața de Apoi și viața cea dintâi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'Și câți Îngeri sunt în Ceruri și mijlocirea lor nu folosește întru nimic, decât după ce Allah îngăduie cui Voiește El și cui Îi Place!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Cu adevărat, cei care nu cred în Viața de Apoi îi cheamă pe Îngeri cu nume de femei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'Însă ei nu au știință despre aceasta. Ei nu urmează decât bănuiala, însă bănuiala nu este de niciun folos față de Adevăr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Așadar, îndepărtează-te de cel care se întoarce de la îndemnarea Noastră și care nu voiește decât viața pământească!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'Aceasta este știința la care ajung ei. Însă, cu adevărat, Domnul tău îi Știe mai bine pe cei care rătăcesc de la Calea Sa și El îi Știe mai bine pe aceia care sunt drept călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'Ale lui Allah sunt cele din Ceruri și cele de pe Pământ, pentru ca să-i răsplătească pe cei care au săvârșit rău după ceea ce au făcut și să-i răsplătească pe cei care au împlinit bine cu cea mai bună [răsplată].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'Cei care se feresc de păcatele mari și de faptele cele rușinoase, în afară de micile greșeli, [să știe că] Domnul tău este Darnic la Iertare. El vă Cunoaște cel mai bine, fiindcă El v-a creat pe voi din pământ, precum și atunci când ați fost plămădiți în pântecele mamelor voastre. Așadar, nu vă lăudați cu curățenia sufletelor voastre, fiindcă El îi Știe mai bine pe cei care sunt cu teamă [de El]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Îl vezi pe cel care se întoarce [de la Islam]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'Și dă cu zgârcenie, iar apoi nu mai dă deloc?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Oare are el știința Necunoscutului și poate el vedea?[10]', '[10] Că proviziile sale se vor sfârși dacă cheltuiește pentru săraci în timp ce Allah a promis altceva');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Sau oare nu i s-a vestit lui ce se află în Scripturile lui Moise', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'Și ale lui Avraam, care și-a ținut cu credință [făgăduința lui de a transmite]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'Că niciun suflet nu va purta povara altuia', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'Și că omul nu va dobândi decât [rodul] celor pe care le-a agonisit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'Și că agoniseala lui se va vedea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'Iar apoi va primi pentru ea răsplata cuvenită?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'Și că la Domnul tău este întoarcerea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'Și că El face [pe cineva] să râdă și face să plângă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'Și că El dă moartea și El dă viața', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'Și că El i-a creat pe cei doi soți - bărbătușul și femeiușca -,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'Dintr-o picătură, când ea este vărsată?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'Și că a Lui este și cealaltă creație [Învierea]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'Și că El îmbogățește și îndestulează?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'Și că El este Stăpânul Stelei aș-Și''ra[11]', '[11] O Stea adorată de unii dintre arabii păgâni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'Și că El a făcut să piară ’Ad cel dintâi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'Și Thamud și nu a lăsat să rămână nimic,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'Ca și poporul lui Noe, mai înainte. Cu adevărat, ei erau mai nelegiuiți și mai crânceni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'Și cetățile [răsturnate][12] le-a nimicit', '[12] Ale căror locuitori l-au negat pe profetul Lot');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'Și le-a acoperit cu ceea ce le-a acoperit[13]', '[13] O ploaie de piatră');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Și de care dintre binefacerile Domnului tău te îndoiești?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, '[Profetul] acesta este un prevenitor dintre prevenitorii cei vechi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'Se apropie Ziua cea care este aproape,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'Nimeni, afară de Allah, nu o poate da la iveală.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Oare vă mirați voi de această recitare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'Și râdeți și nu plângeți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'Și stați voi nepăsători și semeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Prosternați-vă înaintea lui Allah și adorați-L!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Ceasul s-a apropiat și Luna s-a despicat [în două][1].', '[1] Acesta a fost un semn dat de Allah profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) atunci când cei din Qurayș l-au provocat să le arate un miracol');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'Însă când văd un semn, ei se îndepărtează și spun: „[Aceasta este] o vrăjitorie neîntreruptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'Ei învinuiesc de minciună și urmează poftelor lor și tot lucrul este hotărât.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'Le-au venit lor știri destule în care se află oprire [de la necredință].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, '[Aceasta este] o înțelepciune deplină, însă prevenitorii nu sunt de niciun folos [pentru cei care nu vor să priceapă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Deci întoarce-te de la ei [o, Mohammed]! [Așteptând] Ziua când Chemătorul[2] îi va chema [pe ei] la un lucru înspăimântător!', '[2] Considerat a fi un Înger ce anunță judecata');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 'Atunci când vor ieși din gropi, cu ochii plecați, de parcă ar fi niște lăcuste risipite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'Alergând spre Cel care cheamă, necredincioșii vor spune: „Aceasta este o Zi grea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Poporul lui Noe au respins [Mesagerul] înainte de ei și l-au socotit mincinos pe robul Nostru și au spus: „[El este] un nebun!” Și el a fost ocărât [de necredincioși].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'Și L-a chemat pe Stăpânul său, [spunând]: „Eu sunt învins! Deci ajută-mă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'Și am deschis Noi porțile Cerului pentru o apă ce a curs potop', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'Și am făcut să țâșnească izvoare din Pământ și astfel s-a întâlnit apa, după o poruncă ce a fost hotărâtă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'Și Noi l-am dus [pe Noe pe corabia] cea durată din scânduri și cuie,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'Care plutea sub ochii Noștri, [drept] răsplată pentru cel ce a fost tăgăduit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'Și am lăsat-o Noi ca un semn [de prevenire]. Dar oare se află cine să ia aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'Și cum a fost Chinul Meu și Prevenirile Mele[3].', '[3] Pentru cei de după ei, de la care se aștepta să învețe din lecțiile popoarelor anterioare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'Noi am făcut Coranul ușor, pentru îndemnare, dar oare se află cine să ia aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'A învinuit de minciună și [poporul lui]’Ad [pe profetul lor Hud]. Și cum a fost Pedeapsa Mea și Prevenirile Mele?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Noi am trimis asupra lor un vânt rece cu sunet puternic, într-o zi nefericită, fără sfârșit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'Care i-a smuls pe oameni, de parcă ar fi fost niște trunchiuri de palmieri dezrădăcinați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'Și cum a fost Chinul Meu și Prevenirile Mele?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'Noi am făcut Coranul ușor, pentru îndemnare, dar oare este cineva care să cugete?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'A socotit și Thamud mincinoase prevenirile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'Și au spus ei: „Oare să urmăm un singur om dintre noi? Atunci noi am fi în rătăcire și în sminteală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Oare să-i fi fost îndemnarea trimisă lui, dintre noi [toți]? Ba el este un mincinos plin de semeție!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Mâine vor afla ei cine este mincinosul plin de semeție!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'Noi le vom trimite cămila pentru încercare. Deci veghează-i și fii cu răbdare![4]', '[4] Acest Verset și cel care urmează sunt adresate profetului Salih');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'Și vestește-le că apa va fi împărțită între ei[5]! Fiecare va bea când va veni rândul său.', '[5] Între tribul lui Thamud și cămila, o zi de băut pentru fiecare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Însă ei l-au chemat pe tovarășul lor[6] și el a luat [sabia sa] și a ologit-o.', '[6] Pe cel mai rău dintre ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'Și cum a fost Chinul Meu și Prevenirile Mele?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Cu adevărat, Noi am trimis asupra lor un singur strigăt [din Cer] și ei au devenit asemenea surcelelor uscate de la țarcul de vite [al păstorului].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'Noi am făcut Coranul ușor, pentru îndemnare, dar oare este cineva care să ia aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'A luat și poporul lui Lot drept minciună prevenirile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'Cu adevărat, Noi am trimis asupra lor vijelie cu pietre și nu am izbăvit decât familia lui Lot, înainte de revărsatul zorilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'Ca Îndurare din partea Noastră. Astfel îl răsplătim Noi pe cel care aduce mulțumire;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'El [Lot] i-a prevenit despre pedeapsa Noastră dar ei s-au îndoit de prevenirile lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Ei i-au adus rușine în privința oaspeților săi, însă Noi le-am luat vederea lor. „Gustați Chinul Meu și Prevenirile Mele!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'Și dimineața devreme i-a lovit pe ei o pedeapsă îndelungă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'Deci gustați Chinul Meu și Prevenirile Mele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'Noi am făcut Coranul ușor, pentru îndemnare, dar oare este cineva care să ia aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'Și s-au dus prevenitorii și la clanul lui Faraon,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'Însă ei au socotit mincinoase toate semnele Noastre și i-am apucat Noi cu pedeapsa lui ''Aziz [Celui Tare], Muqtadir [Atotputernic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, 'Oare necredincioșii voștri [o, Qurayș,] sunt mai buni decât aceștia [poporul lui Noe, Lot etc] sau se află în Scripturi mântuire pentru voi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Sau ei spun: „Noi suntem o mulțime biruitoare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'Dar mulțimea lor va fi înfrântă și ei vor întoarce spatele [fugind][7].', '[7] Acest eveniment prezis a avut loc în ziua Bătăliei de la Badr');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Însă Ceasul este timpul promis lor [pentru pedepsire], iar Ceasul va fi mai groaznic și mai amar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Cu adevărat, nelegiuiții se află în rătăcire și în sminteală[8]!', '[8] Sau „în flăcările focului”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'În Ziua aceea vor fi târâți în Foc cu fețele lor în jos [și li se va spune]: „Gustați voi atingerea Iadului!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Și Noi am creat toate lucrurile bine întocmite', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'Și nu este Porunca Noastră decât una singură [un Cuvânt care se va împlini] într-o singură clipită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'Noi am nimicit cetele [asemănătoare cu] voi, dar oare este cine să ia aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'Și tot ceea ce au făcut se află [înscris] în cărți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'Orice [faptă] - mică sau mare - este înscrisă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Cu adevărat, cei care cred vor fi în Grădini și [printre] pâraie,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'Într-un loc al adevărului, lângă un Stăpânitor Atotputernic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Cel Milostiv [Ar-Rahman]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'L-a învățat [pe om] Coranul [prin Marea Sa Milă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'L-a creat pe om,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'Și l-a învățat pe el vorbirea limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Soarele și Luna urmează o rânduială precisă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'Iar ierburile [sau Stelele] și arborii se prosternează[1].', '[1] Se supun legilor lui Allah. A se vedea 22:18');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'Și Cerul El l-a înălțat și El a stabilit balanța,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'Pentru ca voi să nu fiți nedrepți la cumpănire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'Și dați greutatea după dreptate și nu scădeți la balanță.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'Iar Pământul l-a făcut întins pentru vietăți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'Pe el sunt fructe și palmieri cu ciorchini înveliți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'Și grâne cu paie și ierburi mirositoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, 'El l-a creat pe om [Adam] din lut, asemenea oalelor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'Și l-a creat pe djinn din foc curat, fără fum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, 'Stăpânul celor două răsărituri și Stăpânul celor două apusuri[2].', '[2] Punctele de răsărit în est și apus în vest, atât vara, cât și iarna');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'El a slobozit cele două mări ca să se întâlnească[3],', '[3] Cele două părți de apă: apă dulce și apă sărată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'Dar între ele este o stavilă pe care ele nu o pot trece.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Din ele ies perle și coral.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'Ale Lui sunt corăbiile care se înalță pe mare ca munții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Toți cei care sunt pe Pământ vor pieri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'Va rămâne veșnic [numai] Fața[4] Domnului tău, Cel plin de Slavă și de Cinste.', '[4] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Îl imploră [având nevoie de El] cei care sunt în Ceruri și pe Pământ și în fiecare zi El împlinește ceva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'În curând Ne vom ocupa și de judecata voastră, o, voi două poveri[5]!', '[5] Oamenii și djinnii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'O, popor al djinnilor și al oamenilor! Dacă voi puteți trece dincolo de hotarele Cerurilor și ale Pământului, treceți! Dar voi nu veți putea trece decât cu ajutorul unei Puteri [din partea lui Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'Se vor trimite asupra voastră flăcări de foc și fum[6] și nu veți fi voi ajutați.', '[6] Un alt înțeles este aramă sau cupru');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'Și când se va despica Cerul și va deveni roșu-aprins ca uleiul[7]!', '[7] Sau „ca pielea roșie”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'Și în Ziua aceea nu vor fi întrebați despre păcatele lor nici oamenii și nici djinnii[8].', '[8] După ce au fost condamnați la Foc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'Nelegiuiții vor fi cunoscuți după semnele lor [fețele întunecate] și vor fi ei apucați de smocurile de păr și de picioare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, 'Acesta este Iadul pe care-l socoteau păcătoșii minciună;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Ei se vor plimba într-un du-te-vino între el și între o apă clocotită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'Acela care s-a temut de înfățișarea dinaintea Domnului său va avea parte de două Grădini, -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'Amândouă [Grădinile] cu ramuri stufoase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'În ele se află două izvoare care curg.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'În ele sunt din toate roadele câte două soiuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, '[Ei vor sta] întinși pe așternuturi căptușite cu brocart, iar roadele celor două Grădini vor fi aproape.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'În ele sunt [hurii] cu priviri neprihănite, pe care nu le-au atins înainte de ei nici oameni, nici djinni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'Ca și când ar fi rubine și coral[9].', '[9] În puritate, culoare și frumusețe');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'Oare să fie răsplata binelui alta decât tot binele?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Și afară de cele două mai sunt alte două grădini [în Paradis].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'Și ele sunt [de culoare] verde-închis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'În ele se află două izvoare ce țâșnesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'În ele se află fructe, palmieri și rodii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'În ele se află fecioare virtuoase și frumoase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Hurii retrase în corturi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Pe care înainte de ei nu le-au atins nici oameni, nici djinni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, '[Ei] vor sta întinși pe perne verzi și pe covoare pline și frumoase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'Așadar, pe care dintre binefacerile Domnului vostru le tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Binecuvântat fie Numele Domnului tău Dhu al-jalal ua-l-''ikram [Cel Plin de Slavă și de Cinste]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Când „cea care trebuie să se întâmple” se va întâmpla,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, 'Nimeni nu va mai socoti venirea ei minciună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Ea [îi] va coborî [pe unii] și [îi] va înălța [pe alții][1].', '[1] Conform faptelor lor și nu datorită averii sau poziției sociale, așa cum se întâmplă în această viață');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Când Pământul va fi zguduit și clătinat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, 'Și munții vor fi sfărâmați în fărâme', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'Și se vor preface în pulbere risipită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, 'Atunci veți fi voi de trei feluri:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, 'Oamenii mâinii drepte - și ce sunt oamenii mâinii drepte?[2] -,', '[2] Cei care vor primi cartea faptelor în mâna dreaptă vor fi destinați Paradisului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, 'Oamenii mâinii stângi - și ce sunt oamenii mâinii stângi?[3] -,', '[3] Cei care vor primi cartea faptelor în mâna stângă vor fi destinați Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, 'Și cei ce s-au aflat în frunte se vor afla înainte[4].', '[4] Poate fi înțeles drept „cei care s-au aflat în frunte [în a face fapte bune] se vor afla înainte [la intrarea în Paradis]');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'Aceștia sunt cei mai apropiați [de Allah],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'În Grădinile plăcerilor;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'O ceată dintre primii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'Și puțini dintre ceilalți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, '[Ei se vor afla] pe paturi împletite cu aur și pietre prețioase,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'Întinși pe ele față în față.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'Și se vor plimba printre ei feciori veșnic tineri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'Cu potire, cu ulcioare și cu un pahar de la un izvor [de vin] ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'Nu vor avea dureri de cap de la el și nici nu vor fi amețiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'Și vor găsi fructe dintre cele pe care și le aleg', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'Și carne de pasăre pe care o poftesc', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'Și hurii cu ochii mari,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'Asemenea mărgăritarelor ascunse,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'Drept răsplată pentru ceea ce au împlinit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'Și nu vor auzi în ele nici vorbe deșarte, nici învinuiri de păcat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'Ci numai cuvântul „Pace! Pace!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'Și oamenii mâinii drepte - ce sunt oamenii mâinii drepte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, '[Ei se vor afla printre] jujubierii fără spini', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'Și bananierii cu ciorchini rânduiți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'Sub umbră întinsă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'Și lângă apa care curge continuu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'Și roade multe,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'Fără întrerupere și fără opreliște,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'Și paturi ridicate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'Cu adevărat, Noi le-am creat pe ele [femeile din Paradis] desăvârșite', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'Și le-am făcut pe ele neprihănite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, '[Mlădioase,] iubitoare față de soții lor și toate de-o vârstă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'Pentru oamenii mâinii drepte [care sunt]:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'O ceată numeroasă dintre primii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'Și o ceată numeroasă dintre ultimii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'Iar oamenii mâinii stângi - ce sunt oamenii mâinii stângi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, '[Ei se vor afla în mijlocul] vântului arzător și apei clocotite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'La o umbră de fum negru,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'Nici răcoros, nici plăcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Cu adevărat, ei au fost înainte de aceasta în îndestulare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'Și au stăruit în păcatul cel mare[5],', '[5] Șirk (asocierea altora cu Allah) sau necredință');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'Spunând: „Oare după ce am murit și ne-am făcut țărână și oseminte, vom mai putea fi noi readuși la viață?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'Și la fel și strămoșii noștri?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'Spune [o, Mohammed]: „Atât cei dintâi, cât și cei de pe urmă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'Vor fi adunați la termenul unei Zile cunoscute!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'Apoi, voi cei care sunteți rătăciți și tăgăduiți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'Veți mânca dintr-un pom de zaqqum', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'Și vă veți umple burțile din el', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'Și veți bea, pe deasupra, apă clocotită;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'Veți bea așa cum beau cămilele însetate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'Acesta este ospățul lor în Ziua Judecății.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'Noi v-am creat pe voi. De ce nu voiți să credeți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Ați văzut voi ce aruncați drept sămânță[6]?', '[6] Sperma care conține materialul pentru viață');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'Îl plăsmuiți voi sau Noi îl plăsmuim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Noi am hotărât pentru voi moartea și Noi nu suntem împiedicați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'Să vă înlocuim cu semenii voștri și să vă mai refacem [în Ziua de Apoi] într-un chip pe care voi nu-l știți[7].', '[7] Un alt înțeles este: „...vă vom înlocui cu alții ca voi [pe Pământ] și vă vom crea [în Viața de Apoi] într-o formă pe care voi nu o cunoașteți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Voi ați cunoscut prima creare. De ce nu vreți voi să luați aminte?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Oare vedeți voi ce semănați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'Dar oare voi faceți să crească [ceea ce semănați] sau Noi facem să crească?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Dacă am Voi Noi, am face aceasta resturi, iar voi ați rămâne mirându-vă[8];', '[8] De ceea ce s-a întâmplat. Un alt înțeles este „cu regret”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, '[Spunând:] „Noi suntem plini de datorii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'Ba noi suntem lipsiți [de cele de trebuință]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Vedeți voi apa pe care o beți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'Voi ați făcut-o să coboare din Nori sau Noi o facem să coboare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Dacă am Voi, am face Noi să fie ea sărată. De ce, dar, nu sunteți voi mulțumitori?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Vedeți voi focul pe care-l aprindeți [prin frecare]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'Voi ați făcut să crească pomul lui sau Noi l-am făcut să crească?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'Noi l-am făcut, ca o amintire[9] și ca un lucru folositor pentru cei care călătoresc[10].', '[9] A focului măreț din Iad
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Deci Laudă Numele Domnului tău Cel Măreț!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'Și nu! Eu Jur pe locurile Stelelor [de pe bolta cerească][11]! -', '[11] Allah confirmă printr-un jurământ');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'Și, cu adevărat, acesta este un jurământ mare, dacă voiți să știți!-', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Că acesta este un Coran Nobil,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'Într-o Carte bine păstrată[12],', '[12] În Tabla bine Păstrată (al-Lauh al-Mahfudh), care se află la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Pe care numai cei curățiți o ating [Îngerii].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, '[Acesta este] o revelație de la Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'Oare acest Mesaj voi îl socotiți minciună?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'Și faceți voi din înzestrarea voastră [un lucru] pe care-l tăgăduiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'Și cum va fi când [sufletul în momentul morții] va ajunge la gât?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'Și voi veți privi în vremea aceea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'Fiind Noi [Îngerii Noștri care scot sufletele] mai aproape de el decât voi, însă nu Ne veți zări.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'Dar de ce nu, dacă voi credeți că nu aveți de dat socoteală,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'Aduceți-l înapoi[13], dacă voi sunteți întru adevăr?', '[13] Înapoi în corp, însemnând că așa cum nu puteți opri moartea atunci când este decretată, tot astfel nu veți putea scăpa de recompensă atunci când este decretată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'Dacă [cel care moare] este dintre cei apropiați [de Allah],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'Atunci el va avea odihnă, Îndurare și Grădini cu plăceri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'Dacă el este dintre oamenii mâinii drepte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'Atunci [el va fi primit cu cuvintele:] „Pace ție, [tu ești] dintre oamenii mâinii drepte!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'Însă dacă el va fi dintre cei care tăgăduiesc și sunt în rătăcire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'Atunci va avea el sălaș în apa clocotită', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'Și în focul Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Acesta este Adevărul adevărat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Deci Laudă Numele Domnului tău Cel Măreț!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Tot ceea ce se află în Ceruri și pre Pământ Îi aduce Laudă lui Allah, căci El este Al-''Aziz [Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'A Lui este Împărăția Cerurilor și a Pământului. El dă viață și dă moartea și El este cu Putere peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'El este Al-Auual [Întâiul] și Al-Aakhir [Cel de pe urmă], Adh-Dhahir [Cel de Deasupra tuturor] și Al-Batin [Cel ascuns] și El este Atoateștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'El este Cel care a creat Cerurile și Pământul în șase zile și pe urmă s-a înălțat deasupra Tronului[1]. El Știe ce intră în Pământ și ce iese din el, ce coboară din Cer și ce se înalță la el; El este cu voi, oriunde v-ați afla. Și Allah Vede bine ceea ce faceți.', '[1] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'A Lui este Împărăția Cerurilor și a Pământului și la Allah se întorc [toate] lucrurile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'El face ca noaptea să intre în zi și ca ziua să intre în noapte și El este Știutorul celor dinlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'Credeți în Allah și în Trimisul Său și faceți milostenie din cele asupra cărora El v-a făcut urmași, căci aceia dintre voi care cred și care fac milostenie vor avea parte de răsplată mare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Și ce aveți voi că nu credeți în Allah, în vreme ce Trimisul vă cheamă să credeți în Domnul vostru? Iar El a făcut legământ cu voi. Dacă voi sunteți cu adevărat credincioși [credeți acum]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'El este Cel care pogoară asupra robului Său [profetul Mohammed] semne limpezi, pentru ca să vă scoată pe voi din întunecimi la lumină. Și Allah este Ra''uf [Iertător], Rahim [Îndurător] cu voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'Și ce aveți voi că nu dăruiți pe calea lui Allah, în vreme ce a Lui este moștenirea Cerurilor și a Pământului? Nu este deopotrivă cel care a dăruit dintre voi și care a luptat înainte de cucerire, căci aceștia vor avea o treaptă mai înaltă decât aceia care au dăruit și au luptat după aceea. Dar tuturor le făgăduiește Allah cea mai bună [răsplată]; și Allah este Bine Știutor a ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Cine este acela care Îi va da lui Allah un împrumut frumos, pentru ca El să i-l dea înapoi înmulțit și pentru a avea parte de răsplată generoasă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'Într-o zi îi vei vedea pe dreptcredincioși și pe dreptcredincioase cu lumina alergând în fața lor și în dreapta lor. [Și li se va spune lor]: „Iată astăzi vestea voastră cea bună: Grădini pe sub care curg râuri și în care veți sălășlui voi veșnic! Aceasta este izbânda cea mare!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'Și în Ziua aceea, ipocriții și ipocritele le vor spune dreptcredincioșilor: „Așteptați ca să luăm și noi din lumina voastră!” Dar [li] se va spune: „Întoarceți-vă înapoi[2] și căutați lumină!” Și se va ridica între ei un zid, cu o poartă. Înlăuntrul ei se va afla Îndurarea, iar în afara ei, împrejur, se va afla chinul.', '[2] În viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, 'Și ei [ipocriții] vor striga către ei [credincioșii]: „Oare nu am fost împreună cu voi?” Vor spune: „Ba da! Însă voi v-ați lăsat ispitiți și ați stat la pândă și ați stat la îndoială și v-au amăgit dorințele, până ce a venit porunca lui Allah. Și amăgitorul [Satana] v-a înșelat pe voi cu privire la Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Și astăzi nu se mai primește răscumpărare nici de la voi, nici de la aceia care au tăgăduit. Sălașul vostru va fi Focul. El va fi locul ce vi se cuvine vouă. Și ce rea soartă [este aceasta]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'Oare nu a sosit vremea pentru aceia care cred, ca inimile lor să fie smerite la pomenirea lui Allah și înaintea Adevărului care a fost trimis și ca ei să nu fie ca cei cărora li s-a dăruit Cartea mai înainte și li s-a lăsat lor timp îndelung, însă inimile lor au rămas împietrite și mulți dintre ei sunt nelegiuiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Să știți că Allah dă viață Pământului, după moartea lui! Noi v-am făcut vouă semnele limpezi, pentru ca voi să pricepeți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Cu adevărat, cei care au făcut milostenie și acelea care au făcut milostenie i-au dat lui Allah un împrumut minunat, care li se va întoarce lor înmulțit, și vor avea ei parte de răsplată generoasă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'Cei care au crezut în Allah și în Trimișii Săi - aceia sunt cei iubitori de adevăr - și martirii vor avea la Domnul lor răsplata și lumina lor, iar aceia care nu au crezut și au socotit Versetele Noastre mincinoase, aceia vor fi oaspeții Iadului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'Să știți că viața aceasta este doar o joacă, o glumă, o podoabă, goană după laudă între voi și după înmulțirea averilor și a copiilor. [Aceasta] este asemenea unei ploi, a cărei vegetație îi încântă pe lucrătorii pământului, dar apoi ea se veștejește și o vezi îngălbenită și apoi se preschimbă în niște fărâme. Iar în Viața de Apoi se află chin aspru [pentru necredincioși] și iertare de la Allah și mulțumire [pentru credincioși] . Și nu este această viață decât o plăcere înșelătoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'Grăbiți-vă, întrecându-vă, către iertarea Domnului vostru și către o Grădină într-atât de largă, precum lărgimea Cerului și a Pământului, care a fost pregătită pentru aceia care au crezut în Allah și Trimișii Săi! Aceasta este mare Mila lui Allah, pe care El o Dăruiește cui Voiește, căci Allah este Dătător de mare Îndurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Nicio nenorocire nu se îndreaptă pe Pământ și nici în sufletele voastre fără ca ea să nu se afle într-o carte[3], înainte ca Noi să o pricinuim. Acesta este un lucru ușor pentru Allah,', '[3] În Tabla bine Păstrată (al-Lauh al-Mahfudh)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'Pentru ca voi să nu fiți triști pentru ceea ce ați pierdut și nici să nu vă prea bucurați pentru ceea ce El vă Dăruiește. Și Allah nu-l Iubește pe cel trufaș și lăudăros,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'Pe cei care sunt zgârciți și le poruncesc oamenilor să fie zgârciți. Cât despre cel care întoarce spatele, Allah este Al-Ghaniyy [Cel suficient pentru Sine] [și] El este Al-Hamid [Cel Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Noi i-am trimis pe Trimișii Noștri cu semnele cele limpezi, am făcut să pogoare cu ei Scriptura și Balanța, pentru ca oamenii să fie cu dreptate, și am făcut să pogoare fierul, în care se află putere mare și foloase pentru oameni și pentru ca Allah să vădească cine Îl ajută pe El și pe Trimișii Săi fără ca ei să fie văzuți! Cu adevărat, Allah este Qauiyy [Tare] [și] ''Aziz [Puternic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Și Noi i-am trimis pe Noe și pe Avraam și le-am dăruit urmașilor lor profeția și Scriptura. Și printre ei au fost unii bine călăuziți, însă mulți dintre ei au fost ieșiți din drum și nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Apoi, Noi i-am făcut să meargă pe urmele lor pe Trimișii Noștri și l-am făcut să urmeze pe Iisus fiul Mariei, și i-am dăruit lui Evanghelia, iar în inimile celor care l-au urmat am pus milă și îndurare. Însă monahismul l-au născocit ei singuri - nu l-am prescris Noi pentru ei - căutând mulțumirea lui Dumnezeu! Dar ei nu au păzit aceasta așa cum s-ar fi cuvenit să o păzească. Noi le-am dăruit acelora dintre ei care au crezut răsplata lor, însă mulți dintre ei au fost nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'O, voi cei care credeți! Fiți cu frică de Allah și credeți în Trimisul Său [Mohammed] astfel El vă va dărui o parte dubla din Îndurarea Sa, vă va face o lumină după care să mergeți și vă va ierta pe voi, căci Allah este Ghafur [Iertător], Rahim [Îndurător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'Aceasta pentru ca oamenii Cărții să știe că ei nu vor avea nicio putere asupra Harului lui Allah[4] și că Harul se află în Mâna[5] lui Allah și El îl Dăruiește cui Voiește El, căci Allah este Dătătorul Harului cel mare.', '[4] Nu vor avea parte de Harul lui Allah atâta timp cât refuză să creadă în Mesajul Lui care a fost trimis prin profetul Mohammed
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Allah a auzit vorbele celei care discută cu tine [o, Mohammed] în privința bărbatului ei și se plânge lui Allah. Și Allah aude discuția voastră, căci Allah este Sami'' [Cel care Aude Totul] [și] Basir [Cel care Vede Totul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Aceia dintre voi care pronunță adh-dhihar[1] pentru a se despărți soțiile lor - ele nu sunt mamele lor! Mamele lor nu sunt decât cele care i-au adus pe lume. Ei spun vorbe urâte și mincinoase. Dar cu toate acestea Allah este ''Afuuu [Îndurător], Ghafur [Iertător].', '[1] Acesta are loc atunci când soțul îi spune soției: „Tu ești pentru mine precum spatele mamei mele”. Acesta era un tip de divorț practicat de arabi înainte de profeția lui Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Cei care se despart de soțiile lor cu aceste vorbe, iar apoi vor să revină asupra celor pe care le-au spus, [trebuie] să elibereze un rob înainte de a se mai atinge unul de altul. La aceasta sunteți voi îndemnați, iar Allah este bine Știutor a ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Iar cel care nu află [în posesia lui un rob] trebuie să postească două luni, una după alta[2], înainte de a se atinge [de soția sa]. Însă cel care nu poate [să o facă], trebuie să hrănească șaizeci de sărmani. Aceasta pentru ca să credeți în Allah și în Trimisul Său. Acestea sunt orânduielile impuse de Allah, iar cei care le tăgăduiesc vor avea parte de pedeapsă dureroasă.', '[2] A se vedea 4:92');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'Cu adevărat, cei care se împotrivesc lui Allah și Trimisului Său vor fi doborâți așa cum au fost doborâți și cei de dinainte de ei. Noi am pogorât Versete limpezi, iar necredincioșii vor avea parte de pedeapsă umilitoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'În Ziua când Allah îi va readuce pe ei toți la viață și le va vesti lor ceea ce au făcut. Allah le-a ținut lor socoteală, în vreme ce ei au uitat-o, căci Allah este la toate Martor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Oare tu nu vezi că Allah Știe tot ceea ce se află în Ceruri și ceea ce se află pe Pământ? Nu există discuție în taină între trei fără ca El să fie al patrulea[3], nici între cinci fără ca El să fie al șaselea, nici mai puțini de atât și nici mai mulți fără ca El să fie împreună cu ei [prin Știința Sa], oriunde s-ar afla. Apoi le vestește ceea ce au făcut, în Ziua Învierii. Cu adevărat, Allah este Atoateștiutor.', '[3] Prin Știința Lui, secretele acestora');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Oare tu nu-i vezi pe cei cărora le-a fost oprit să vorbească în taină cum se întorc la ceea ce le-a fost oprit și se sfătuiesc în șoaptă, cu păcat, dușmănie și nesupunere față de Trimis? Iar dacă vin la tine, te salută [cu vorbe] cu care nu te salută Allah[4] și zic în sinea lor: „De ce ne chinuie Allah pentru ceea ce spunem?” Iadul va fi de ajuns pentru ei și vor arde în el! Și ce loc rău [este acesta]!', '[4] Se face referire la evreii care îi salutau pe musulmani spunând: „Moartea fie asupra voastră” în loc de „Pacea fie asupra voastră”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'O, voi cei care credeți! Dacă vorbiți în taină, nu vă sfătuiți cu păcat, dușmănie și nesupunere față de Trimis, ci sfătuiți-vă cu bunătate și cu evlavie! Și fiți cu frică de Allah, la care veți fi adunați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'Vorba în taină este de la Șeitan, pentru ca cei care au crezut să se întristeze, însă el nu le poate pricinui nicio pagubă fără de Voia lui Allah. Și în Allah să se încreadă dreptcredincioșii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'O, voi cei care credeți! Când vi se spune vouă: „Faceți loc în adunări!”, atunci faceți voi loc și vă va face și Allah vouă loc [în Paradis]! Iar când se spune „Ridicați-vă!”, atunci ridicați-vă voi și Allah îi va ridica cu [câteva] trepte pe aceia care cred dintre voi și pe aceia cărora li s-a dat știința, căci Allah este bine Știutor a ceea ce faceți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'O, voi cei care credeți! Dacă voiți să stați de vorbă în taină cu Trimisul, înainte de vorba voastră faceți o milostenie, căci aceasta este mai bine pentru voi și mai curat! Dar dacă nu găsiți [nimic de oferit], Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Oare vă temeți să dați milostenie înainte de vorba voastră? Fiindcă nu ați dat și pentru că Allah v-a iertat, împliniți voi Rugăciunea [As-Salat], plătiți Dania [Az-Zakat] și fiți cu supunere față de Allah și de Trimisul Său, căci Allah este bine Știutor a ceea ce faceți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Oare nu i-ai văzut pe aceia care și-au luat ca ajutor un neam pe care Allah este mâniat? Ei nu sunt nici dintre voi, nici dintre ai lor și ei jură cu minciună și ei știu [aceasta].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Allah le-a pregătit lor chin aspru. Și ce rău [lucru este] acesta pe care îl fac ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'Și-au luat jurămintele lor drept pavăză și astfel ei au împiedicat de la calea lui Allah, dar vor avea ei parte de osândă umilitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Nu le vor fi de niciun folos averile lor și copiii lor împotriva [pedepsei] lui Allah. Aceștia vor fi oaspeții Focului și în el vor sălășlui ei veșnic.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'Într-o Zi, când Allah îi va învia pe toți, vor jura ei față de El, așa cum au jurat față de voi și vor socoti că ei se sprijină pe ceva, însă ei sunt mincinoși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Șeitan a pus stăpânire peste ei și i-a făcut pe ei să uite de pomenirea lui Allah. Aceștia sunt ceata lui Șeitan și ceata lui Șeitan sunt cei pierduți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Cei care se împotrivesc lui Allah și Trimisului Său - sunt dintre cei mai umiliți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Allah a Hotărât: „Cu adevărat, Eu voi Birui negreșit; Eu și Trimișii Mei!” Allah este cu adevărat Qauiyy [Tare] [și] ''Aziz [Puternic].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Nu vei afla niciun neam [de oameni] care cred în Allah și în Ziua de Apoi și care să-i ia ca prieteni pe cei ce se împotrivesc lui Allah și Trimisului Său, chiar dacă ar fi părinții lor, fiii lor, frații lor sau stirpea lor. În inimile acestora El a prescris credința și i-a întărit pe ei cu Duh de la Sine. Și El îi va ajuta să intre în Grădini pe sub care curg pâraie și veșnic vor avea sălaș în ele. Allah este mulțumit de ei și ei sunt mulțumiți de El. Aceștia sunt ceata lui Allah, iar ceata lui Allah sunt aceia care vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Tot ceea ce există în Ceruri și pe Pământ Îi aduc Laudă lui Allah[1], căci El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '[1] A se vedea 57:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'El este Cel care i-a scos pe cei care nu au crezut dintre oamenii Cărții[2] din căminele lor în prima pribegie. Nu ați crezut că vor ieși, iar ei și-au închipuit că cetățile lor îi vor apăra de Allah. Însă [hotărârea lui] Allah a venit la ei de acolo de unde ei nu se așteptau și a aruncat spaimă în inimile lor. Și ei au dărâmat casele lor cu propriile mâini și cu mâinile dreptcredincioșilor. Trageți învățăminte, voi cei care aveți ochi!', '[2] Referindu-se la Bani Nadir, care a încălcat tratatul cu Mesagerul lui Allah (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'Și dacă Allah n-ar fi scris pentru ei pribegia, El i-ar fi chinuit în [această] viață, iar în Viața de Apoi ei vor avea parte de chinul Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'Aceasta pentru că ei s-au împotrivit lui Allah și Trimisului Său. Iar cel care se împotrivește lui Allah [să știe că] Allah este aspru la pedeapsă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'Câți palmieri ați tăiat sau i-ați lăsat în picioare pe rădăcinile lor, [aceasta a fost] cu permisiunea lui Allah, pentru ca să-i acopere de rușine pe nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'Voi nu ați intrat în nicio luptă cu cai și nici cu cămile[3] pentru ceea ce Allah a dăruit ca pradă Trimisului Său de la ei. Însă Allah dă putere Trimișilor Săi asupra celor cărora El Voiește și Allah este cu Putere peste toate.', '[3] Însemnând că aceștia nu au trecut prin nicio greutate (război) pentru a o obține');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Ceea ce Allah a dăruit Trimisului Său ca pradă de la locuitorii cetăților, aceasta aparține lui Allah și Trimisului, rudelor apropiate, orfanilor, sărmanilor și călătorului de pe drum[4], pentru ca să nu se schimbe doar între cei bogați dintre voi. Ceea ce vă dăruiește Trimisul primiți, iar cele de la care vă oprește, opriți-vă de la ele și fiți cu frică de Allah, căci Allah este aspru la pedeapsă!', '[4] Această poruncă ce se referă la proprietățile abandonate de către dușmani fără război diferă de ceea din Surat al-Anfal, v.41, care se referă la prăzile de război în care patru cincimi sunt distribuite printre cei care au luptat pentru cauza lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, '[Și din acestea se cuvine] și emigranților săraci care au fost alungați din căminele lor și de la averile lor, căutând îndurare și mulțumire de la Allah și făcând să triumfe cauza lui Allah și a Trimisului Său. Aceștia sunt cei iubitori de Adevăr.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'Și [de asemenea] celor care s-au stabilit în case [Medina] și [au adoptat această] credință înainte de ei. Ei i-au iubit pe cei care s-au dus în pribegie la ei, nu au avut în piepturile lor nicio supărare pentru ceea ce li s-a dat lor [emigranților], ci i-au preferat pe ei înaintea lor înșiși, chiar dacă ei erau în nevoie. Iar cei care se feresc de zgârcenia propriilor suflete, aceia sunt cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Și [este o parte] și celor care au venit după ei și au spus: „Doamne, iartă-ne nouă și fraților noștri care ne-au luat-o înainte întru credință și nu ne lăsa în sufletele noastre niciun fel de pizmă față de aceia care au crezut! Doamne, Tu ești Ra''uf [Iertător], Rahim [Îndurător]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Oare nu i-ai văzut pe cei ipocriți, spunându-le fraților lor, care nu au crezut, dintre oamenii Cărții: „Dacă veți fi alungați, vom ieși împreună cu voi și nu ne vom supune nimănui împotriva voastră, iar de se va purta luptă împotriva voastră, noi vă vom ajuta"? Și Allah este Martor că ei sunt mincinoși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'Dar dacă ei sunt alungați, nu vor ieși împreună cu ei, iar dacă se va purta luptă împotriva lor, nu le vor veni în ajutor. Și dacă le-ar veni în ajutor, ei vor întoarce spatele fugind, așa încât ei nu vor primi niciun ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'Voi [o, dreptcredincioșilor, stârniți] în piepturile lor mai multă spaimă decât Allah. Aceasta pentru că ei sunt un neam [de oameni] care nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Ei nu vor lupta împreună împotriva voastră, ci numai din cetăți întărite sau din spatele unor ziduri. Dușmănia dintre ei este mare. Îi consideri a fi uniți, dar inimile lor sunt împărțite. Aceasta pentru că ei sunt un neam [de oameni] care nu au minte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, '[Ei sunt] asemenea celor care puțin înaintea lor au gustat urmarea rea a purtării lor și au avut parte de chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, '[Ipocriții sunt] asemenea lui Șeitan, când îi spune omului: „Fii fără credință!”, iar după ce el rămâne necredincios, el spune: „Eu nu am nicio vină în privința ta! Cu adevărat, eu mă tem de Allah, Stăpânul lumilor!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'Și sfârșitul amândurora va fi în Focul în care vor rămâne veșnic, căci aceasta este răsplata nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'O, voi cei care credeți, fiți cu frică de Allah! Și fiecare suflet să bage de seamă ce trimite înainte pentru Ziua de mâine! Și fiți cu frică de Allah, căci Allah este bine Știutor a tot ceea ce faceți voi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'Nu fiți ca cei care L-au uitat pe Allah și pe care El i-a făcut de aceea să uite de ei înșiși! Aceștia sunt nelegiuiții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Oaspeții Focului nu sunt egali cu oaspeții Raiului! Oaspeții Raiului sunt cei care izbândesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Dacă am fi trimis Noi acest Coran unui munte, l-ai fi văzut tu umilindu-se smerit și despicându-se de frica lui Allah. Și aceste exemple le dăm Noi oamenilor pentru ca ei să cugete.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'El este Allah, afară de care nu este alt dumnezeu, Știutorul celor nevăzute și al celor văzute[5]. El este Ar-Rahman [Cel Milostiv], Ar-Rahim [Îndurător].', '[5] A se vedea 6:73');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'El este Allah, în afară de care nu este alt dumnezeu: Al-Malik [Stăpânitorul], Al-Quddus [Cel Sfânt], As-Salam [Făcătorul de pace], Al-Mu''min [Apărătorul Credinței], Al-Muhaymin [Veghetorul], Al-''Aziz [Cel Tare], Al-Jabbar [Atotputernicul], Al-Mutakabbir [Cel Preaînalt]. Mărire lui Allah! El este mai Presus de ceea ce voi Îi asociați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'El este Allah: Al-Khaliq [Făcătorul], Al-Bari'' [Creatorul], Al-Musauuir [Dătătorul de chipuri]. Ale Lui sunt Numele cele mai Frumoase. Pe El Îl Laudă cele din Ceruri și cele de pe Pământ. El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'O, voi cei care credeți! Nu-i luați ca aliați pe dușmanul Meu și pe dușmanul vostru, arătându-le lor prietenie, în vreme ce ei au tăgăduit Adevărul ce a venit la voi! Ei îl alungă pe Trimis, precum și pe voi pentru că voi credeți în Allah, Stăpânul vostru. Dacă ați ieșit pe calea Mea și căutând mulțumirea Mea, [atunci nu-i luați pe ei aliați și nu] vorbiți cu ei pe ascuns, din cauza prieteniei, în vreme ce Eu Știu atât ceea ce tăinuiți, cât și ceea ce mărturisiți pe față. Cel dintre voi care face aceasta rătăcește de la drumul cel drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Dacă ei vor pune stăpânire peste voi, vă vor fi ei dușmani și vor întinde mâinile și limbile lor întru rău spre voi și vor voi ei să fiți tăgăduitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Nu vă vor fi de folos nici rudele voastre, nici copiii voștri. În Ziua Învierii El va judeca între voi, iar Allah Vede bine ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Ați avut voi un exemplu frumos în Avraam și în cei care au fost alături de el, atunci când ei au spus către neamul lor: „Cu adevărat, noi ne lepădăm de voi și de cele pe care voi le venerați în locul lui Allah. Ne lepădăm de voi. Dușmănia și vrajba s-au ivit între noi pentru totdeauna, până când voi veți crede numai în Unicul Allah!” – cu excepția cuvântului lui Avraam către tatăl său: „Mă voi ruga de iertare pentru tine, cu toate că eu nu voi avea nicio putere pentru tine la Allah!” Doamne, în Tine ne încredem, și la Tine ne întoarcem cu căință și la Tine este întoarcerea [în Ziua de Apoi],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'Doamne, nu ne face pe noi încercare pentru cei care nu cred și iartă-ne nouă, Doamne, căci Tu ești Al-''Aziz [Cel Puternic] [și] Al Hakim [Înțelept]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Voi ați avut în ei un exemplu, pentru cel ce nădăjduiește în Allah și în Ziua de Apoi. Dacă, însă, cineva întoarce spatele, [să se știe că] Allah este Al-Ghaniyy [Deajuns pentru Sine] [și este] Al-Hamid [Demn de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Se poate ca Allah să aducă prietenie între voi și între cei pe care voi i-ați ținut ca dușmani, căci Allah este Qadir [Atotputernic] și Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Allah nu vă oprește de la cei care nu au luptat împotriva voastră, din pricina religiei, și nu v-au alungat din căminele voastre, să fiți buni cu ei și drepți, căci Allah îi Iubește pe cei drepți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'Allah vă oprește doar să-i luați ca aliați pe cei care au luptat împotriva voastră, din pricina religiei, și v-au alungat din căminele voastre și au ajutat la alungarea voastră. Iar cei care și-i iau ca aliați sunt nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'O, voi cei care credeți! Dacă vin la voi femei credincioase în pribegie, încercați-le pe ele! Allah Știe mai bine credința lor. Și dacă aflați că ele sunt credincioase, nu le mai trimiteți înapoi la necredincioși. Ele nu mai sunt îngăduite pentru ei și nici ei nu mai sunt îngăduiți pentru ele [ca soți]. Dați-le lor înapoi ceea ce au cheltuit [ca zestre][1] și nu este niciun păcat pentru voi să vă căsătoriți cu ele, dacă le dați zestrea ce li se cuvine lor. Și nu le țineți [ca soții] pe cele politeiste! Cereți înapoi ceea ce ați cheltuit și să ceară și ei înapoi ceea ce au cheltuit! Aceasta este hotărârea cu care Allah judecă între voi, iar Allah este ''Alim [Atoateștiutor] [și] Hakim [Înțelept].', '[1] Pentru căsătorie, pentru a le compensa pierderea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'Dacă vreuna dintre soțiile voastre fuge de la voi la necredincioși [renunțând la Islam] și apoi voi sunteți victorioși împotriva lor, atunci dați-le celor ale căror soții au fugit atât cât au cheltuit ei! Și fiți cu frică de Allah, în Care voi credeți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'O, Profetule! Dacă vin la tine femei credincioase și îți fac jurământ de credință, făgăduind că nu vor asocia pe nimeni cu Allah, nu vor fura, nu vor curvi, nu-și vor omorî copiii, nu vor săvârși nicio ticăloșie cu ceea ce se află între mâinile și picioarele lor [atribuind copiii lor nelegitimi soților lor], și nu ți se vor arăta cu nesupunere față de ceea ce se cuvine, atunci primește jurământul lor de credință și roagă-L pe Allah de iertare pentru ele. Cu adevărat, Allah este Ghafur [Iertător], Rahim [Îndurător]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'O, voi cei care credeți! Nu vă aliați cu un popor [de oameni] pe care Allah este mâniat și care deznădăjduiesc în privința Vieții de Apoi, întocmai așa cum deznădăjduiesc necredincioșii în privința celor aflați în morminte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Tot ceea ce există în Ceruri și pe Pământ Îl preamăresc pe Allah, și El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'O, voi cei care credeți! De ce spuneți voi ceea ce nu faceți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'Este [o pricină de] mare mânie pentru Allah să spuneți ceea ce nu faceți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Cu adevărat, Allah îi Iubește pe cei care luptă pe calea Sa într-o linie [de luptă], de parcă ei ar fi o zidire întărită.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Și [spune, o, Mohammed,] atunci când Moise a spus către poporul său: „O, popor al meu, pentru ce mă necăjiți, când știți că eu sunt Trimisul lui Allah la voi?” Și când ei s-au abătut [de la Calea lui Allah], Allah a făcut să se abată inimile lor, fiindcă Allah nu călăuzește poporul de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'Și [spune] când Iisus, fiul Mariei, a spus: „O, Fii ai lui Israel! Cu adevărat, eu sunt Trimisul lui Allah la voi, întărind Tora de dinainte de mine și vestind un Trimis ce va veni după mine și al cărui nume este Ahmad[1]”. Și când el le-a adus semnele limpezi, ei au spus: „Aceasta este vrăjitorie învederată!”', '[1] Un alt nume al Profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'Și cine este mai nelegiuit decât acela care născocește minciună despre Allah, atunci când este chemat la Islam? Iar Allah nu călăuzește neamul de nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'Ei voiesc să stingă Lumina lui Allah cu gurile lor, însă Allah întregește Lumina Sa, chiar dacă necredincioșii nu voiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'El este Cel care l-a trimis pe Trimisul Său cu călăuzirea și religia Adevărului, ca să o facă pe ea deasupra tuturor religiilor, chiar dacă politeiștii nu voiesc.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'O, voi cei care credeți! Să vă îndrum eu către un negoț care vă va mântui pe voi de un chin dureros?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'Credeți voi în Allah și în Trimisul Său și luptați pe calea lui Allah, cu averile voastre și cu sufletele voastre, căci acest lucru este mai bun pentru voi, dacă [voiți să] știți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, '[Și] El vă va ierta păcatele voastre și vă va lăsa să intrați în Grădini pe sub care curg râuri și în locuințe bune din grădinile Edenului. Aceasta este marea izbândă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'Și [vă va da vouă și] alte [lucruri] care vă sunt dragi: ajutor de la Allah și o victorie apropiată. Spune-le, așadar dreptcredincioșilor veștile cele bune!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'O, voi cei care credeți! Fiți ajutoare pe calea lui Allah, așa cum a spus Iisus, fiul Mariei, apostolilor: „Cine sunt ajutoarele mele în chemarea la Allah?” Și i-au răspuns apostolii: „Noi suntem ajutoarele lui Allah!” Atunci o parte dintre Fiii lui Israel au crezut, în vreme ce o altă parte nu au crezut. Și Noi le-am dat ajutor acelora care au crezut, împotriva dușmanului lor, și au devenit ei biruitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Tot ceea ce există în Ceruri și pe Pământ Îl preamăresc pe Allah[1] - Al-Malik [Stăpânul], Al-Quddus [Cel Sfânt], Al- ''Aziz [Atotputernicul] [și] Al-Hakim [Înțeleptul].', '[1] A se vedea 57:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'El este Cel care le-a trimis celor fără știință de carte un Trimis dintre ei, care să le recite Versetele Sale, să-i purifice și să-i învețe Cartea [Coranul] și Înțelepciunea [Sunnah], după ce ei au fost mai înainte într-o rătăcire învederată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'Ca și altora care nu i-au prins pe ei [care vor urma]. Și El este Al-''Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'Acesta este Harul lui Allah și El îl Dăruiește cui Voiește, iar Allah este Cel cu Mare Milă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Pilda acelor cărora le-a fost încredințață Tora și apoi nu au purtat-o pe ea[2] este ca exemplul măgarului ce cară cărți[3]. Rău este exemplul poporului [de oameni] care au socotit versetele lui Allah mincinoase, iar Allah nu călăuzește poporul de nelegiuiți!', '[2] Au neglijat responsabilitatea lor față de ea prin faptul că nu i-au practicat învățăturile
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'Spune: „O, voi cei care ați primit iudaismul! Dacă voi pretindeți că sunteți dragi lui Allah (și aliații Lui), afară de ceilalți oameni, atunci doriți-vă moartea, dacă voi sunteți grăitori de adevăr!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'Dar ei nu vor dori nicicând, pentru ceea ce au făcut mai înainte mâinile lor, însă Allah este bine Știutor al nelegiuiților.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'Spune: „Cu adevărat moartea de care fugiți vă va ajunge pe voi! Apoi veți fi aduși la Cel care le Cunoaște atât pe cele nevăzute, cât și pe cele văzute și care vă va vesti vouă ceea ce ați săvârșit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'O, voi cei care credeți! Când se cheamă la Rugăciune [As-Salat], în ziua de Vineri, grăbiți-vă la Pomenirea lui Allah și lăsați negoțul! Aceasta este mai bine pentru voi, dacă [voiți să] știți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'Apoi, după ce Rugăciunea [As-Salat] a fost împlinită, răspândiți-vă pe Pământ și căutați Harul lui Allah și pomeniți-L mult pe Allah, pentru ca voi să izbândiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Și dacă văd ei un negoț sau o petrecere, atunci se îndreaptă ei înspre ea și te lasă pe tine [o, Mohammed] în picioare [în Khutbah]. Spune: „Ceea ce se află la Allah este mai bun decât petrecerea și decât negoțul, iar Allah este Cel mai bun Înzestrător!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Când vin la tine [ o, Mohammed], ipocriții spun: „Mărturisim că tu ești Trimisul lui Allah”. Însă Allah Știe că tu ești Trimisul Său și Allah mărturisește că ipocriții sunt mincinoși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Ei și-au luat jurămintele lor drept pavăză și astfel împiedică de la calea lui Allah. Cu adevărat, cât de rău este ceea ce fac ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'Aceasta este pentru că ei au crezut, iar apoi s-au lepădat de credință și inimile lor au fost pecetluite, încât ei nu mai pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Dacă-i vezi, îți plac chipurile lor. Dacă vorbesc, asculți vorba lor. Dar ei sunt ca niște butuci rezemați[1] și ei socotesc că orice strigăt este împotriva lor. Ei sunt dușmanul! Deci ferește-te de ei! Blestemați să fie de Allah! Cum s-au abătut ei!', '[1] Corpuri cu minți și inimi goale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'Și dacă li se spune lor: „Veniți, căci Trimisul lui Allah se va ruga de iertare pentru voi!”, ei întorc capetele și îi vezi cum se îndepărtează îngâmfați.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'E totuna pentru ei de te rogi de iertare pentru ei sau nu te rogi de iertare pentru ei; Allah nu le va ierta lor, căci Allah nu călăuzește neamul celor ieșiți din drum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Ei sunt cei care spun: „Nu cheltuiți pentru aceia care sunt lângă Trimisul lui Allah, până ce ei nu se vor risipi!” Însă ale lui Allah sunt comorile Cerurilor și ale Pământului, dar ipocriții nu pricep.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Ei spun: „Când ne vom întoarce la Medina, cel mai puternic de acolo îl va alunga pe cel mai umil”. Însă a lui Allah este Puterea și a Trimisului Său și a dreptcredincioșilor, dar ipocriții nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'O, voi cei care credeți! Să nu vă abată averile voastre și copiii voștri de la Pomenirea lui Allah! Cei care fac aceasta, aceia vor fi pierduți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'Și dăruiți din cele cu care v-am înzestrat Noi, înainte ca moartea să vină la unul dintre voi și să spună el: „Doamne, mai dă-mi un răgaz până la un termen apropiat, astfel încât să fac eu milostenie și să fiu dintre cei evlavioși!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Însă Allah nu va mai da răgaz niciunui suflet, dacă a venit termenul său și Allah este bine Știutor a ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'Tot ceea ce există în Ceruri și pe Pământ Îi aduc Laudă lui Allah[1]; a Lui este Împărăția și a Lui este Slava și El este cu Putere peste toate.', '[1] A se vedea 57:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'El este Cel care v-a creat. Și printre voi se află unii care nu cred și printre voi se află unii care cred, însă Allah Vede bine ceea ce faceți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, '[El] a creat Cerurile și Pământul întru adevăr și v-a dat vouă chipuri. Și a făcut chipurile voastre frumoase. Și la El este întoarcerea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, '[El] Știe ceea ce se află în Ceruri și Știe ceea ce se află pre Pământ și El Știe atât ceea ce voi țineți ascuns, cât și ceea ce voi descoperiți. Și Allah este bine Știutor al celor dinlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Oare nu v-a venit vouă veste despre cei care nu au crezut de mai înainte [de voi], care au gustat urmarea rea a faptei lor și care vor avea parte de chin dureros?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'Aceasta, pentru că au venit la ei Trimișii lor cu semne limpezi, iar ei au spus: „Oare să ne călăuzească pe noi oamenii?” Și nu au crezut ei și au întors spatele, însă Allah s-a lipsit de ei, căci Allah este Ghaniyy [Deajuns pentru Sine] [și este] Hamid [Vrednic de Laudă].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Cei care nu au crezut, au pretins că ei nu vor mai fi înviați. Spune: „Ba da! Pe Domnul meu! Veți fi voi înviați și apoi vi se va vesti vouă ceea ce ați făcut! Și acesta este un lucru ușor pentru Allah”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Așadar, fiți cu credință în Allah, în Trimisul Său și în Lumina pe care am trimis-o Noi! Iar Allah este bine Știutor a ceea ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'Ziua în care vă va aduna El pentru Ziua Adunării, aceea este Ziua marii pierderi[2]. Iar pe cel care crede în Allah și împlinește fapte bune, El îl va ierta pentru faptele sale rele și-l va lăsa să intre în Grădini pe sub care curg pâraie și vor fi veșnic sălășluitori în ele. Aceasta este marea izbândă.', '[2] At-Taghabun sugerează învingerea de către alții în achiziționarea a ceva valoros. În acea Zi, necredincioșii vor suferi pierderea Paradisului, care va fi pentru credincioși.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'Iar cei care nu cred și socotesc Versetele Noastre mincinoase, vor fi oaspeții Focului și vor fi veșnic sălășluitori în el. Și ce rea soartă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Nicio nenorocire nu-l lovește pe om decât numai cu Îngăduința lui Allah. Iar aceluia care crede în Allah, El îi va călăuzi inima. Allah este Atoateștiutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'Fiți cu supunere față de Allah și fiți cu supunere față de Trimis! Iar dacă voi întoarceți spatele, [să știți că] Trimisului Nostru îi revine doar transmiterea limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Allah! Nu există altă divinitate demnă de a fi adorată afară de El! Și în Allah [trebuie] să se încreadă dreptcredincioșii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'O, voi cei care credeți! Cu adevărat, voi aveți printre soațele voastre și printre copiii voștri un dușman [prin faptul că ei vă pot opri de la pomenirea lui Allah și supunerea față de El]! Deci, fiți cu grijă față de ei! Însă dacă voi sunteți îngăduitori și treceți peste [greșelile lor] și îi iertați pe ei, să știți că și Allah este Ghafur [Iertător], Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Averile voastre și copiii voștri sunt numai o ispită și la Allah se află o mare răsplată [Paradisul].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Deci, fiți cu frică de Allah atât cât puteți, ascultați, fiți supuși și dăruiți spre binele sufletelor voastre! Iar aceia ale căror suflete vor fi ferite de zgârcenie, aceia sunt cei care vor izbândi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'Dacă Îi veți face lui Allah un împrumut frumos [cheltuind din averea voastră întru mulțumirea Lui], El vi-l va da înapoi înmulțit și vă va ierta pe voi, căci Allah este Șakur [Mulțumitor] [și] Halim [Blând].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, 'El este Știutorul celor nevăzute și al celor văzute, Al-’Aziz [Cel Puternic] [și] Al-Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'O, Profetule! Dacă [voi, musulmanii,] divorțați de femei, atunci despărțiți-vă de ele după timpul de așteptare prescris pentru ele și socotiți timpul[1] și fiți cu frică de Allah - Stăpânul vostru! Nu le alungați din casele lor și ele să nu plece, doar dacă au săvârșit mare păcat dovedit! Acestea sunt Poruncile lui Allah, iar cel care calcă Poruncile lui Allah este nedrept față de sine însuși. Tu nu știi, s-ar putea ca Allah să facă să se întâmple după aceea un lucru[2]', '[1] A se vedea 2:228-233. O soție nu ar trebui divorțată decât după terminarea menstruației, dar înainte de actul sexual sau în timpul unei sarcini confirmate. Pronunțarea divorțului începe perioada sa de așteptare (iddah).
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Apoi când ele ajung la timpul prescris, atunci sau țineți-le, după cuviință, sau despărțiți-vă de ele, după cuviință! Și luați ca martori doi oameni drepți [musulmani] dintre voi și faceți mărturie față de Allah! Cu aceasta este îndemnat cel care crede în Allah și în Ziua de Apoi! Iar celui care este cu frică de Allah, îi va da El o ieșire [bună][3]', '[3] Ușurare de la necaz');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'Și-l va înzestra pe el de unde el nici nu se așteaptă. Iar celui care se încrede în Allah, El îi este de ajuns, căci Allah împlinește lucrul Său și Allah a stabilit un termen pentru fiecare lucru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'Și dacă aveți îndoieli în privința perioadei de așteptare pentru femeile care nu mai au menstruație, aceasta este pentru ele de trei luni și asemenea pentru cele ce nu au încă menstruație. Iar termenul pentru cele care sunt însărcinate este până ce ele nasc[4]. Iar celui care este cu frică de Allah, aceluia îi face El lucrul său ușor.', '[4] Regula cu privire la sarcină se aplică și în cazul morții soțului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'Aceasta este Porunca lui Allah, pe care El v-o trimite vouă. Iar celui care este cu frică de Allah, El îi va șterge faptele rele și îi va da lui mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Lăsați-le să locuiască[5] acolo unde locuiți voi, după mijloacele voastre, și nu le faceți nicio daună[6], ca să le faceți să trăiască strâmtorate! Iar dacă ele sunt însărcinate, atunci îngrijiți-le până nasc și dacă alăptează [copiii născuți] de la voi, atunci dați-le lor simbria lor și sfătuiți-vă între voi [în această privință], așa după cum se cuvine! Iar dacă aflați voi greutăți, atunci îl va alăpta pentru el alta [din partea tatălui][7].', '[5] În perioada lor de așteptare (referitor la soțiile al căror divorț a fost pronunțat)
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Cel care este înstărit să cheltuiască după averea sa, iar cel a cărui înzestrare este măsurată să cheltuiască din ceea ce i-a dat Allah. Allah nu silește pe nimeni decât după cum El i-a dat. Și Allah va face să vină după strâmtorare ușurare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'Și câte cetăți s-au răzvrătit împotriva Poruncii Domnului lor și împotriva Trimișilor Săi! Și Noi le-am cerut lor socoteală cu asprime și le vom pedepsi cu mare pedeapsă [în Ziua de Apoi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Și au gustat ele urmarea purtării lor și urmarea purtării lor a fost pierderea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Allah a pregătit pentru ei chin aspru. Deci, fiți cu frică de Allah, voi cei dăruiți cu înțelegere și care credeți! Allah v-a trimis vouă o Îndemnare [Coranul][8]', '[8] Unii învățați au interpretat ca fiind „dhikr” sau „amintire”, însemnând Mesagerul (pacea și binecuvântarea lui Allah fie asupra sa) deoarece acesta este menționat în următorul Verset');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, '[El a trimis] un Trimis [Mohammed], care să vă recite vouă Versetele lui Allah cele deslușite, ca să-i scoată pe cei care cred și împlinesc fapte bune din întunecimi la lumină. Și pe cel care crede în Allah și împlinește fapte bune El îl va face să intre în Grădini pe sub care curg pâraie și veșnic vor fi ei sălășluitori în ele. Și ce înzestrare frumoasă a hotărât Allah pentru el!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Allah este Cel ce a creat șapte Ceruri și tot atâtea Pământuri. Între ele coboară Porunca [Sa], pentru ca să știți că Allah este cu Putere peste toate și că Allah cuprinde toate lucrurile cu Știința [Sa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'O, Profetule! De ce îți oprești tu ceea ce Allah ți-a permis, căutând mulțumirea soțiilor tale? Allah este Ghafur [Iertător] [și] Rahim [Îndurător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Allah a orânduit pentru voi [musulmanilor] dezlegarea jurămintelor voastre[1] iar Allah este Stăpânul vostru. Și El este Al-''Alim [Atoateștiutor] [și] Al-Hakim [Înțelept].', '[1] Prin kaffarah (ispășire). Aceasta este necesară atunci când o persoană nu își poate îndeplini jurământul său sau a făcut un jurământ ce nu a fost pe placul lui Allah. A se vedea 5:89.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'Când Profetul i-a încredințat un secret uneia dintre soții, iar ea l-a povestit [altei soții] și Allah i-a vestit lui aceasta, atunci el a înștiințat despre o parte și a neglijat o altă parte. Și când el i-a spus, atunci ea a zis: „Cine te-a înștiințat despre aceasta?”. El a răspuns: „M-a înștiințat Al-’Alim [Atoateștiutorul] [și] Al-Khabir [Bineștiutorul]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'Și de vă veți întoarce, căindu-vă voi amândouă [Hafsa și Aișa] la Allah, (aceasta este mai bun pentru voi), căci inimile voastre au fost înclinate (către ceea ce nu Îi este plăcut lui Allah). Însă de vă veți susține una pe alta împotriva lui, atunci Allah este Ocrotitorul lui; iar Gavriil și dreptcredincioșii evlavioși și Îngerii îi vor fi peste aceasta ajutorare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Și dacă va divorța el de voi, s-ar putea ca Domnul lui să-i dea în locul vostru soții mai bune decât voi: musulmane, dreptcredincioase, ascultătoare, care se căiesc, adoratoare, care țin post, desfeciorite și fecioare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'O, voi cei care credeți! Păziți-vă pe voi înșivă și familiile voastre de un Foc ale cărui vreascuri sunt oamenii și pietrele și peste care sunt Îngeri neînduplecați și aspri, care nu se răzvrătesc împotriva lui Allah în ceea ce le poruncește și care fac ceea ce li se poruncește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, 'O, voi necredincioșilor! Nu vă dezvinovățiți în Ziua aceea, căci voi veți fi răsplătiți după cele pe care le-ați săvârșit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'O, voi cei care credeți! Întoarceți-vă la Allah întru căință curată! Poate că Domnul vostru vă va șterge faptele voastre cele rele și vă va face să intrați în Grădini pe sub care curg râuri, în Ziua în care Allah nu va lăsa să fie umiliți Profetul și cei care au crezut împreună cu el. Lumina lor va grăbi înaintea lor și în mâinile lor drepte. Și vor spune ei: „Doamne, întregește lumina noastră și iartă-ne pe noi, căci Tu ești cu Putere peste toate!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'O, Profetule! Luptă împotriva necredincioșilor și a fățarnicilor și fii neînduplecat cu ei! Sălașul lor va fi Iadul și ce rea soartă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Allah le-a dat drept exemplu pentru cei care nu cred pe soția lui Noe și pe soția lui Lot, care s-au aflat sub oblăduirea a doi robi evlavioși dintre robii Noștri și care i-au viclenit pe ei, iar ei doi nu le-au putut fi de niciun ajutor la Allah. Și [li] s-a spus: „Intrați în Foc [laolaltă] cu ceilalți care intră!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'Și Allah a dat-o drept exemplu pentru cei care cred pe soția lui Faraon, care a spus: „Doamne, durează-mi mie o casă lângă Tine în Rai și mântuiește-mă pe mine de Faraon și de fapta sa și mântuiește-mă pe mine de neamul de nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'Și [la fel și] pe Maria, fiica lui ''Imran, care a rămas curată și am suflat în ea prin Îngerul Nostru [Gavriil]. Și ea a crezut în Cuvintele Domnului ei și în Scripturile Sale și a fost ea dintre cei supuși cu statornicie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'Binecuvântat fie Cel care are în Mâna Lui Împărăția și este cu Putere peste toate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'Cel care a făcut moartea și viața, ca să vă încerce pe voi, [pentru a vedea] care dintre voi este mai bun întru faptă. Și El este Al-''Aziz [Puternic] [și] Al-Ghafur [Iertător].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'Cel care a creat șapte Ceruri unul peste altul, fără să vezi nicio nepotrivire în creația lui Ar-Rahman [Celui Milostiv]. Întoarce-ți privirea! Oare vezi tu vreo crăpătură?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Întoarce-ți iarăși privirea de două ori! Privirea se va întoarce la tine umilită și slabă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Noi am împodobit Cerul cel mai de jos cu candele și le-am făcut pe ele pietre pentru lovirea diavolilor[1] și am pregătit pentru ei chinul Văpăii.', '[1] Îndepărtându-i astfel de Ceruri și împiedicându-i să asculte. A se vedea 72:8-9.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'Cei care nu au crezut în Domnul lor vor avea parte de chinul Iadului. Și ce rea întoarcere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Când vor fi aruncați în el, îi vor auzi vuietul, în vreme ce el clocotește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'Aproape că plesnește de mânie. De fiecare dată când este aruncată o ceată nouă, păzitorii săi îi întreabă: „Oare nu a venit la voi un prevenitor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'Iar ei vor spune: „Ba da! A venit la noi un prevenitor, însă noi l-am învinuit de minciună și am spus: Allah nu a trimis nimic, iar voi nu sunteți decât în mare rătăcire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'Și ei vor spune: „Dacă noi am fi ascultat și am fi priceput, nu am fi printre oaspeții Văpăii!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'Și astfel ei vor mărturisi păcatele lor. Așadar, striviți să fie oaspeții Văpăii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Cei care se tem de Domnul lor, fără să-L vadă pe El, vor avea parte de iertare și de mare răsplată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Spuneți în șoaptă vorba voastră ori rostiți-o cu glas tare! El le Știe pe cele dinlăuntrul piepturilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'Oare nu le știe pe cele pe care le-a creat, cu toate că El este Al-Latif [Binevoitor] [și] Al-Khabir [Atoateștiutor]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'El este Cel care v-a făcut Pământul supus. Deci străbateți întinderile sale. Și mâncați din înzestrarea Lui. Și la El este Învierea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Sunteți voi siguri că Cel din Cer nu va lăsa să vă înghită Pământul, când iată că el se cutremură[2]?!', '[2] Într-o mișcare circulară, precum într-un cutremur');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'Sau sunteți siguri că Cel din Cer nu va trimite asupra voastră o vijelie cu pietre? Atunci veți ști cum va fi mustrarea Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'Și cei de dinaintea lor i-au învinuit de minciună [pe Trimișii lor] și cum a fost răzbunarea Mea?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Oare nu văd ei păsările de deasupra lor întinzând și strângând aripile lor? Nu le poate ține pe ele decât Ar-Rahman [Cel Milostiv]! El este Cel care le Vede pe toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'Cine este cel care să fie pentru voi oștire ce vă ajută împotriva lui Ar-Rahman [Cel Milostiv]? Necredincioșii nu sunt decât într-o amăgire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'Cine este cel care vă îngrijește pe voi, dacă El oprește Darurile Sale? Însă ei stăruie în semeția lor și în fuga lor [de Adevăr].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Oare cel care merge cu fața plecată este mai bine călăuzit sau cel care merge cu capul sus, pe un drum drept?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'Spune: „El este Cel care v-a creat și v-a dat vouă auzul și vederea și inimile! Dar voi sunteți puțin mulțumitori”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'Spune: „El este Cel care v-a răspândit pe Pământ și la El veți fi adunați!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'Ei spun: „Când va fi această făgăduință, dacă voi sunteți întru adevăr?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'Spune: „Știința despre aceasta este numai la Allah, iar eu sunt numai un prevenitor limpede.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Și când o vor vedea aproape[3], se vor întrista chipurile celor care nu au crezut. Și [li] se va spune: „Aceasta este ceea ce voi ați cerut!”[4]', '[3] Pedeapsa despre care ați fost avertizați
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'Spune [o, Mohammed]: „Ce ați zice, dacă Allah ne va face să pierim pe mine și pe cei care sunt cu mine sau dacă ar fi Îndurător cu noi, cine îi va apăra pe cei necredincioși de un chin dureros?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'Spune: „El este Ar-Rahman [Cel Milostiv]! Noi credem în El și în El ne încredem și veți afla voi cine este în rătăcire învederată!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'Spune: „Ce credeți? De se va strecura apa voastră în adânc, cine vă va aduce apă de izvor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'Nun[1]. Pe calem și pe ceea ce ei [Îngerii] scriu [faptele oamenilor]!', '[1] A se vedea 2:1');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'Tu nu ești [o, Mohammed], prin Mila Domnului tău, smintit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'Și, cu adevărat, tu vei avea parte de o răsplată neîntreruptă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'Și, cu adevărat, tu ai o fire minunată!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'Vei vedea tu și vor vedea și ei', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'Cine dintre voi este smintit [afectat de diavol].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'Cu adevărat, Domnul tău Știe mai bine cine a rătăcit de la drumul Său și El îi Cunoaște mai bine pe cei care sunt bine călăuziți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Deci, nu da ascultare celor ce socot minciună [semnele Noastre]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'Ei ar dori ca tu să fii binevoitor [să-ți compromiți religia] și să fie și ei binevoitori.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'Nu da ascultare celui care jură încontinuu și este vrednic de dispreț,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'Defăimător, care umblă cu clevetiri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'Care împiedică binele, este nelegiuit, păcătos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'Crud, și, după toate acestea, și bastard[2],', '[2] Susținând în mod fals o descendență particulară. Descrierea dată în aceste Versete este a lui al-Ualid bin al-Mughirah (a se vedea 74: 11-25) sau posibil, așa cum este susținut de Ibn Kathir a lui al-Akhnas bin Șurayq.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'Pentru că el are avere și copii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'Când i se recită lui Versetele Noastre, el spune: „Basme ale celor de demult!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'Noi îi vom face lui un semn pe nas![3]', '[3] Literar „trompă”, însemnând nasul unui elefant sau porc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Noi i-am încercat pe ei, așa cum i-am încercat pe stăpânii grădinii, când au jurat să adune roadele din ea dimineața,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'Dar fără să lase nimic necules[4],', '[4] Sau fără a spune „...dacă Allah Dorește” („in șaa'' Allah”). A se vedea 18:23-24.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'Și s-a abătut peste ea o nenorocire de la Domnul tău, în vreme ce ei dormeau,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'Iar dimineața era asemenea unui ogor cules.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'Și dimineața s-au strigat ei unii pe alții.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, '[Spunând:] „Purcedeți devreme la ogoarele voastre, ca să culegeți [roadele]!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'Și au purces ei, zicându-și unul altuia mai mult în șoaptă:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, '„Să nu intre astăzi peste voi, în ea, niciun sărman!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'Și au purces devreme, hotărâți să-i oprească, închipuindu-și că vor fi în stare de aceasta[5],', '[5] De a-și pune în aplicare planul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'Dar când au văzut-o, au spus ei: „Noi suntem cu adevărat rătăciți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'Sau, mai degrabă, noi suntem lipsiți [de roadele noastre]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'A spus cel mai drept dintre ei: „Oare nu v-am spus eu să aduceți Mărire [lui Allah]?”[6]', '[6] Spunând „dacă Allah Voiește.” Un alt înțeles este „Laudă” sau „Mulțumire” pentru Binecuvântările Sale.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, 'Au spus ei: „Mărire Domnului nostru! Noi am fost nedrepți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'Și s-au îndreptat unul către altul, aducându-și mustrări.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'Și au spus ei: „Vai de noi! Noi am fost nelegiuiți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Poate că Domnul nostru ne va da în schimb [ceva] mai bun decât ea! Noi dorim să ne apropiem de Domnul nostru!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'Așa este chinul! Iar chinul din Lumea de Apoi va fi și mai mare! Dacă ei ar ști!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'Însă cei evlavioși au la Domnul lor Grădinile plăcerii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'Oare Noi îi tratăm pe cei supuși [lui Allah] la fel ca pe cei păcătoși?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Ce-i cu voi? Cum judecați?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Sau aveți voi o Carte din care învățați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'Că veți avea tot ceea ce poftiți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Sau ați luat de la Noi jurăminte până în Ziua Învierii, prin care Ne legăm să vă dăm ceea ce hotărâți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Întreabă-i care dintre ei este pentru aceasta chezaș?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'Sau au ei asociați? Să-i aducă pe asociații lor, dacă ei sunt întru adevăr!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'Într-o Zi li se va descoperi lor Piciorul[7] și ei vor fi chemați la prosternare, însă nu vor putea.', '[7] Când cu toții se vor afla într-o mare dificultate. Conform unui hadis autentic „Piciorul” se poate referi la Cel al lui Allah, în fața Căruia fiecare credincios se va prosterna în Ziua Judecății. A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Plecați vor fi ochii lor și îi va acoperi umilința, pentru că ei au fost chemați la prosternare, când erau în pace![8]', '[8] În viața lumească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Deci lasă-Mă pe Mine și pe cei ce socotesc mincinoasă această vestire! Noi îi vom trage pe ei treptat, de unde ei nici nu știu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'Eu le dau lor un răgaz, însă Planul Meu este temeinic!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Sau le ceri lor o răsplată și ei sunt împovărați de datorii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Sau le știu ei pe cele nevăzute și [din ele] scriu ei?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Deci îndură cu răbdare hotărârea Domnului tău și nu fi ca tovarășul peștelui cel mare [Iona], care L-a chemat [pe Allah], când el era plin de mâhnire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'Dacă nu l-ar fi ajuns pe el Îndurarea de la Domnul lui, ar fi fost el aruncat pe țărmul gol și ar fi fost acoperit de rușine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'Însă l-a ales pe el Domnul său și l-a așezat pe el printre cei evlavioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Cei care nu cred aproape că te doboară cu privirile lor, când aud Îndemnarea și ei spun: „El este smintit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'Însă el nu este decât o Îndemnare pentru toate lumile!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, '„Cea adevărată [Ziua Învierii]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'Ce este „cea adevărată”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'Și de unde să știi tu ce este „cea adevărată”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'Thamud și ’Ad au socotit Ziua Judecății o minciună!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'În ceea ce-i privește, [pe cei din neamul] Thamud au fost nimiciți de vijelie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'Și în ceea ce-i privește, [pe cei din neamul] ’Ad au fost nimiciți de un vânt șuierător[1], turbat,', '[1] Sau „rece”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Pe care [Allah] l-a dezlănțuit împotriva lor [vreme de] șapte nopți și opt zile, una după alta! Și ai fi putut să vezi neamul [de oameni] doborâți, de parcă ar fi fost niște trunchiuri goale de palmieri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'Oare mai vezi să fi rămas vreo urmă din ei?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'Au urmat Faraon și cei de dinaintea lui și cetățile[2] nimicite, care au venit cu mare păcat.', '[2] Cele la care a fost trimis Lot (a se vedea 11:82-83) sau în general toate cetățile ce au fost distruse din cauza negării unui Mesager de la Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'Și astfel, ei s-au răzvrătit împotriva Trimisului Domnului lor și El i-a lovit cu pedeapsă mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Cu adevărat, când apele s-au revărsat, V-am dus pe voi pe corabie[3],', '[3] Construită de Noe');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'Pentru ca Noi să facem din aceasta pentru voi o pomenire și pentru ca urechea care o aude să o țină minte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'Și când se va sufla în Trâmbiță cu o singură suflare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'Și vor fi ridicați Pământul și munții și apoi vor fi făcuți pulbere, dintr-o singură lovitură,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'În Ziua aceea se va produce „cea care trebuie să se întâmple,”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'Iar Cerul se va despica, căci el în Ziua aceea va fi slab,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'Iar Îngerii vor fi la marginile sale și opt [dintre ei] vor purta Tronul Domnului tău de deasupra lor, în Ziua aceea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'În Ziua aceea vă veți înfățișa și nimic de la voi nu va fi ascuns[4].', '[4] Orice persoană sau secret pe care încercați să îl ascundeți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'În ce-l privește pe acela căruia i se va da cartea sa în dreapta lui, el va spune: „Țineți, citiți cartea mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'Cu adevărat, eu am crezut că [într-un final] voi primi răsplata mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'Și el va avea parte de o viață plăcută,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'Într-o Grădină înălțată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'Cu roadele ei atârnând în jos.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, '[Li se va spune] „Mâncați și beți cu plăcere pentru ceea ce ați făcut mai înainte[5], în zilele trecute!”', '[5] Anticipând răsplata din Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'În ce-l privește pe cel căruia i se va da cartea sa în stânga lui, acela va spune: „Vai mie! Mai bine de nu mi s-ar fi dat cartea mea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'Și de n-aș fi știut care este răsplata mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Mai bine dacă ar fi fost [moartea mea] nestrămutată![6]', '[6] Sfârșindu-i viața în loc să fie poarta către viața eternă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'Averea mea nu mi-a fost de niciun folos!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'Puterea mea a fost spulberată!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, '[Allah va spune] „Luați-l și puneți-l în lanțuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'Apoi lăsați-l să ardă în Iad!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'Apoi legați-l pe el cu un lanț de șaptezeci de coți măsură!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'El nu a crezut în Allah Cel Preamăreț', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'Și nu a îndemnat la hrănirea celui sărman!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, '[De aceea], el nu are în această Zi niciun prieten aici', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'Și nici mâncare, afară de puroi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'Pe care nu-l mănâncă decât păcătoșii!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'Dar nu!... Jur pe ceea ce vedeți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'Și pe ceea ce nu vedeți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'Că el [Coranul] este Cuvântul unui Trimis nobil', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'Și nu este cuvântul unui poet! Însă voi nu credeți decât prea puțin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'Și nu este cuvântul unui ghicitor! Însă voi nu vă lăsați îndemnați decât prea puțin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'Este o revelație de la Stăpânul lumilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'Și dacă ar fi născocit el [Mohammed] unele vorbe [false] împotriva Noastră,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'L-am fi apucat Noi de [mâna] dreaptă[7]', '[7] Allah s-ar fi răzbunat cu Putere și Măreție');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'Și i-am fi tăiat Noi vâna inimii[8]', '[8] Omorându-l');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'Și nimeni dintre voi nu Ne-ar fi putut opri!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Și, cu adevărat, el [Coranul] este pentru cei cu frică o îndemnare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'Și, cu adevărat, Noi Știm că unii dintre voi îl socotesc minciună.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'Și, cu adevărat, el [Coranul] este un suspin pentru cei care nu cred', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'Și, cu adevărat, el [Coranul] este Adevărul deplin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Deci Slăvește Numele Domnului tău Al-''Adhim [Preamărețul]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'Cineva care se roagă a cerut să cadă o pedeapsă neîndoielnică[1]', '[1] Necredincioșii l-au provocat pe Profet (pacea și binecuvântarea lui Allah fie asupra sa) invocându-l pe Allah să aducă pedeapsa Lui. A se vedea 8:32.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'Peste cei necredincioși, pe care nimeni nu o poate opri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, '[Și care să vină] de la Allah, Stăpânul căilor înălțării.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Îngerii și Duhul se vor înălța la El într-o Zi a cărei durată este cât cincizeci de mii de ani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Deci rabdă cu bună răbdare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Ei o văd departe,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'Însă Noi o vedem aproape.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'În Ziua aceea va fi Cerul precum arama topită,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'Iar munții vor fi asemenea lânii scărmănate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'Și nu-l va mai întreba prietenul pe prieten,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'Măcar că se vor vedea. Păcătosul va voi în Ziua aceea să se răscumpere de pedeapsă cu copiii săi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'Cu soția sa și cu fratele său', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'Și cu neamul său care-i dăruiește lui adăpost,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'Cu toți cei care se află pe Pământ, care l-ar putea salva.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'Dar nu! Va fi o Flacără [a Iadului]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'Ce-i va smulge pielea de pe cap[2]', '[2] Pielea de pe cap sau de pe corp care va fi arsă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'Și-l va chema pe cel care a întors spatele și s-a depărtat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'Și a adunat [avere] și a grămădit în vase [ascunzând-o].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Omul a fost făcut nestatornic și fricos;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'Când are parte de rău, el este abătut și nerăbdător', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'Iar când are parte de bine, el este zgârcit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'În afară de cei care fac Rugăciunea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'Care sunt stăruitori în Rugăciunea lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'Din a căror avere este un drept hotărât[3],', '[3] Însemnând zakatul obligatoriu');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'Pentru cerșetor și pentru cel în nevoie;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'Și cei care socotesc adevărată Ziua Judecății', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'Și cei care se tem de osânda Domnului lor -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'Cu adevărat, nu există nicio apărare împotriva chinului Domnului lor! -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'Și cei care își păstrează castitatea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'Mai puțin de soțiile lor sau de cele pe care le stăpânesc dreptele lor[4], căci pentru aceasta ei nu vor fi mustrați,', '[4] Sclavele lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'Iar cei care aleargă după mai mult decât aceasta sunt păcătoși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'Și cei care păzesc ceea ce li se încredințează, precum și legământul lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'Și cei care sunt drepți în mărturiile lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'Și cei care împlinesc Rugăciunea lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'Aceia vor fi cinstiți în Grădini[5].', '[5] În Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Dar ce este cu cei care nu au crezut, ei își grăbesc ochii spre tine [o, Mohammed] [pentru a te batjocori],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, '[Venind de] la dreapta și [de] la stânga, în cete?[6]', '[6] Aceștia au stat departe pentru a se opune Profetului (pacea și binecuvântarea lui Allah fie asupra sa) și a-l batjocori susținând că ei vor intra în Paradis înainte de credincioși.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Oare nădăjduiește fiecare om dintre ei să fie lăsat să intre în Grădina plăcerii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'Ba nu! Noi i-am creat din ceea ce știu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'Nu! Jur pe Stăpânul răsăriturilor și al apusurilor, că Noi cu adevărat suntem în stare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'Să-i schimbăm cu alții mai buni decât ei și de nimeni nu putem fi opriți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Deci, lasă-i să se afunde și să se joace, până ce vor întâlni Ziua lor, cu care au fost amenințați,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'Ziua în care vor ieși din morminte în grabă, ca și cum ar alerga[7] către niște pietre ridicate,', '[7] Așa cum alergau atunci când se numea un idol nou pentru a fi printre primii adoratori ai săi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'Cu ochii plecați, acoperiți de umilință! Aceasta este Ziua cu care au fost amenințați!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'Cu adevărat, Noi l-am trimis pe Noe la poporul său, [spunându-i]: „Îndeamnă poporul tău, înainte de a se abate asupra lui o osândă dureroasă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, 'El a spus: „O, popor al meu! Eu sunt pentru voi un prevenitor limpede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Adorați-L pe Allah, fiți cu frică de El și dați-mi ascultare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'El vă va ierta o parte din păcatele voastre și vă va da vouă răgaz până la un termen hotărât. Însă când va veni termenul hotărât de Allah, el nu va mai putea fi amânat, dacă voiți să știți!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'El a spus: „Doamne, eu am chemat neamul meu, noaptea și ziua [în secret],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'Însă chemarea mea nu a făcut decât să le sporească fuga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'Și de câte ori i-am chemat ca să le ierți lor, ei și-au vârât degetele în urechi[1], s-au înfășurat în veșmintele lor și au stăruit și s-au arătat cu mare trufie;', '[1] Refuzând să privească sau să asculte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Apoi i-am chemat cu glas tare [în mod deschis, public] ;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'Apoi le-am vorbit lor deschis și le-am vorbit lor în taină', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'Și le-am spus lor: „Rugați-vă de iertare Domnului vostru, căci El este Ghaffar [Iertător],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Pentru ca El să trimită asupra voastră Cerul cu ploaie din belșug', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'Și pentru ca să vă dăruiască vouă averi și copii și să vă dea vouă Grădini și să vă dea vouă pâraie!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Ce este cu voi că nu vă rugați lui Allah, așa cum se cuvine,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'După ce El v-a creat pe voi în [mai multe] faze?[2]', '[2] În faze diferite și progresive. A se vedea 22:5 și 23:12-14.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Oare nu ați văzut voi cum a creat Allah șapte Ceruri, unul peste altul[3]', '[3] A se vedea 67:3');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'Și a făcut Luna să le fie lor lumină și a făcut Soarele ca o candelă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Allah v-a făcut pe voi să răsăriți asemenea ierburilor, din pământ,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'Apoi vă va aduce pe voi înapoi în el și vă va face să ieșiți cu adevărat [în Ziua Judecății].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Și Allah v-a făcut vouă Pământul ca și un covor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'Pentru ca voi să umblați pe el, pe cărări largi!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Noe a spus: „Doamne, ei s-au arătat cu nesupunere față de mine și îl urmează pe acela ale cărui averi și ai cărui copii nu fac decât să-i sporească pierderea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'Și ei au născocit un vicleșug prea mare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'Și au spus: „Nu-i părăsiți niciodată pe zeii voștri! Nu-i părăsiți niciodată pe Uadd și pe Suua'' și pe Yaguth și pe Ya''uq și pe Nasr!”[4]', '[4] Acestea erau numele unor idoli ce erau numiți după oameni credincioși din generațiile anterioare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'Ei i-au adus pe mulți în rătăcire. [Doamne] nu le spori nelegiuiților decât rătăcirea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'Din pricina păcatelor lor ei au fost înecați și vor fi duși să intre în Foc și nu au aflat pentru ei ajutoare afară de Allah!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'Și Noe a spus: „Doamne, nu lăsa pe Pământ niciun sălășluitor într-o casă, dintre necredincioși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'Cu adevărat, dacă-i vei lăsa [în viață], ei îi vor duce în rătăcire pe robii Tăi și nu vor zămisli decât păcătoși necredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'Doamne! Iartă-mă pe mine și pe părinții mei și pe cel care intră în casa mea cu credință, ca și pe dreptcredincioși și pe dreptcredincioase, și nu le spori nelegiuiților decât pierderea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'Spune [o, Mohammed]: „Mi-a fost revelat mie că un grup de djinni au ascultat și apoi au spus: „Noi am auzit un Coran minunat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'Care călăuzește către drumul cel drept! Noi credem în el și nu-i vom face Domnului nostru niciun asociat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'Pentru că El - Preamăritul, nu Și-a luat soție și nici copil!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Și netrebnicul nostru [Iblis] a spus despre Allah minciuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'Noi am crezut că nici oamenii, nici djinnii nu vor spune împotriva lui Allah minciuni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'Însă au fost bărbați dintre oameni care au căutat apărare la bărbații dintre djinni, dar [aceștia] le-au sporit lor suferința [prin comiterea de păcate],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'Și că ei au crezut, așa cum ați crezut și voi, că Allah nu va trimite pe nimeni [ca Mesager]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'Noi am căutat [să atingem] Cerul și l-am aflat plin de păzitori aspri și de meteoriți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'Noi obișnuiam să stăm în el pe niște locuri pentru a auzi[1]. Însă cine se pune la ascultat acum găsește un bolid stând la pândă pentru el.', '[1] Înainte de profeția lui Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) djinnii obișnuiau să adune informații ascultându-i pe furiș pe Îngeri și apoi transmiteau mai departe vrăjitorilor și ghicitorilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'Noi nu știm dacă se voiește rău celor de pe Pământ sau Voiește Domnul lor [să-i călăuzească] pe calea cea dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'Printre noi se află unii drepți și [alții] mai puțin drepți; astfel și noi am fost împărțiți în felurite cete[2].', '[2] În opinie, credință și practică religioasă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'Noi credem că nu vom putea scăpa de [pedeapsa lui] Allah pe Pământ și nu vom putea scăpa de El, fugind.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'Și când am auzit noi călăuzirea [Coranul], am crezut în ea și acela care crede în Domnul său să nu se teamă nici de împuținare, nici de împovărare![3]', '[3] Cu privire la judecata sa în Viața de Apoi. Nimic din faptele bune nu va fi pierdut și nimic din faptele rele ale altora nu îi va fi pus în responsabilitatea lui.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'Unii dintre noi sunt musulmani și unii dintre noi sunt nelegiuiți. Aceia dintre noi care au îmbrățișat Islamul sunt aceia care au căutat calea cea dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'Cât despre cei nelegiuiți, ei sunt vreascuri de foc pentru Iad.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'Dar de vor merge ei pe calea cea dreaptă, le vom da Noi apă din belșug,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'Pentru ca să-i încercăm. Și cel ce se întoarce de la pomenirea Domnului său[4], pe acela îl va îndrepta El către un chin aspru.', '[4] Care va refuza să Îl asculte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Moscheile[5] sunt ale lui Allah și nu chemați pe nimeni împreună cu Allah!', '[5] Termenul „moschei” de aici include fiecare loc de adorare de pe pământ');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'Și când s-a ridicat robul lui Allah [Profetul], chemându-L pe El, aproape că ei s-au îmbulzit [Al-Djinn] către el[6].', '[6] Îmbulzindu-se unul peste celălalt la fel ca lăcustele pentru a-l auzi pe Profet (pacea și binecuvântarea lui Allah fie asupra sa). „Ei” pot fi djinii sau necredincioșii dintre arabi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'Spune [o, Mohammed]: „Eu Îl chem numai pe Domnul meu și nu-I fac Lui niciun asociat!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'Spune: „Eu nu pot nici să vă fac vouă vreun rău, nici să vă călăuzesc pe calea dreaptă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'Spune: „Nimeni nu mă va apăra de Allah și eu nu voi găsi adăpost [la altcineva] afară de El!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'Eu nu pot să aduc decât propovăduire de la Allah și Mesajele Lui. Iar cei care nu vor da ascultare lui Allah și Trimisului Său vor avea parte de focul Iadului și în el vor fi veșnic sălășluitori,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'Iar atunci când le vor vedea pe cele cu care sunt amenințați, atunci vor ști ei ale cui ajutoare sunt mai slabe și mai puține la număr.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'Spune: „Eu nu știu dacă sunt aproape cele cu care sunteți amenințați ori de le va hotărî Domnul meu un termen;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, '[Numai El este] Știutorul necunoscutului și El nu descoperă taina Sa nimănui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'În afară de cel pe care El îl alege ca Trimis și face să meargă înaintea lui și în urma lui păzitori[7],', '[7] Îngeri păzitori pentru a-l proteja pe Mesager (pacea și binecuvântarea lui Allah fie asupra sa) și Mesajul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'Pentru ca el [Mohammed] să știe[8] că ei au transmis Mesajele Domnului lor. El [Allah] doară cuprinde [cu Știința Sa] ceea ce se află la ei și socotește numărul tuturor lucrurilor!”', '[8] Un alt înțeles este „Pentru ca El [Allah] să facă evident”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'O, tu, cel învăluit [în straiele tale]![1]', '[1] Allah i se adresează Profetului (pacea și binecuvântarea lui Allah fie asupra sa) care dormea, învăluit în hainele sale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'Trezește-te noaptea [pentru Rugăciune], afară de puțin [timp] -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'Jumătate din ea sau mai scade din ea puțin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'Sau mai adaugă la ea! - și recită Coranul cu glas tărăgănat și limpede!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Cu adevărat, Noi îți vom trimite Cuvinte grele[2].', '[2] Revelația, care atunci când cobora asupra Profetului (pacea și binecuvântarea lui Allah fie asupra sa) îl copleșea cu greutatea ei. Un alt înțeles este „Ordine importante”.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Cu adevărat, trezirea [pentru Rugăciune] în timpul nopții este mai folositoare[3] și mai potrivită pentru recitare;', '[3] O altă interpretare acceptată este „Cu adevărat, trezirea [pentru Rugăciune] în timpul nopții este mai grea...” însemnând că poate fi făcută doar de credincioșii adevărați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'Cu adevărat, în timpul zilei tu ai de lucru îndelung!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'Și pomenește Numele Domnului tău și dăruiește-te Lui, cu totul!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, '[El este] Domnul Răsăritului și al Apusului! Nu există altă divinitate afară de El; deci socotește-L numai pe El Ocrotitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'Îndură ceea ce zic ei și depărtează-te de ei, plecând cuviincios!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'Și lasă-Mă pe Mine cu cei care învinuiesc de minciună, dintre cei care trăiesc în îndestulare și dă-le lor un scurt răgaz!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'Cu adevărat, Noi avem [pentru ei] fiare grele și Iadul', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'Și mâncare înecăcioasă și chin dureros,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'În Ziua când se vor cutremura Pământul și munții și se vor face munții ca o dună de nisip risipit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Noi v-am trimis un Mesager ca să fie martor pentru voi, așa cum am trimis și la Faraon un Trimis,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'Însă Faraon nu i-a dat ascultare Trimisului și Noi l-am lovit cu pedeapsă aspră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Și cum voiți voi - dacă rămâneți necredincioși - să vă apărați de o Zi care îi va face pe copii cărunți,[4]', '[4] Un alt înțeles este „cum puteți evita [pedeapsa]” în acea Zi?');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'În care Cerul se va despica[5] și făgăduința Lui se va împlini negreșit!', '[5] De teroarea acelei Zile');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Aceasta este o îndemnare și cine voiește va urma drumul către Domnul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'Cu adevărat, Domnul tău, [o, Mohammed] Știe că tu stai în picioare [pentru Rugăciune] aproape două treimi din noapte, sau jumătate din ea, sau o treime din ea, ca și o parte dintre cei care sunt cu tine. Allah hotărăște noaptea și ziua. El a Știut că voi nu veți putea petrece toată noaptea în Rugăciune și astfel El se întoarce către voi cu îngăduință. Deci recitați atât cât vă este cu putință din Coran! El a Știut că unii dintre voi vor fi bolnavi, că alții călătoresc prin lume, în căutarea Harului lui Allah, și că alții se luptă pe calea lui Allah! Deci recitați atât cât vă este cu putință din el, împliniți Rugăciunea [As-Salat], dați Dania [Az-Zakat] și faceți-I lui Allah un împrumut frumos[6], căci binele pe care îl trimiteți înainte pentru sufletele voastre îl veți afla la Allah mai bun, ca răsplată, și mai mare. Și rugați-L pe Allah de iertare, căci Allah este Ghafur [Iertător], Rahim [Îndurător]!', '[6] Sub forma milosteniilor date de dragul Lui');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'O, tu cel acoperit![1]', '[1] Referindu-se la Profet (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Ridică-te și îndeamnă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'Pe Domnul tău preamărește-L,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'Veșmintele tale curățește-le', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'Și de nelegiuire[2] stai departe', '[2] În mod specific idoli sau în general un comportament rău');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'Și nu dărui, căutând să dobândești mai mult,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'Și pentru Domnul tău îndură!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'Când se va sufla în Trâmbiță,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'Aceea va fi atunci o Zi grea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'Deloc ușoară pentru necredincioși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Lasă-Mă cu cel pe care L-am creat singur[3]', '[3] Fără avere sau copii. Referința este pentru al-Ualid bin al-Mugheerah, care, după ce a înclinat către Coran, el l-a negat public pentru a câștiga aprobarea celor din Qurayș');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'Și căruia i-am dăruit avere îndestulătoare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'Și copii care-l însoțesc tot timpul', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'Și căruia i le-am netezit pe toate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'Și care dorește ca Eu să-i dau și mai mult.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Dar nu! Căci el a tăgăduit Versetele Noastre cu încăpățânare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'Iar Eu îl voi sili să urce [As-Sa’ud, un munte în Iad].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'El a cugetat și a hotărât![4]', '[4] Despre ce ar spune cu privire la Coran și cum l-ar putea discredita pe Profet (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'Și distrus să fie! După cum a hotărât!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'Distrus să fie! După cum a hotărât!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Apoi el a mai cugetat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'Apoi s-a posomorât și s-a încruntat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'Apoi s-a întors și s-a arătat trufaș', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'Și a spus: „Aceasta nu este decât vrăjitorie care se învață.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'Aceasta nu este decât vorba unui om!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'Îl voi face să ardă în Saqar[5].', '[5] Unul dintre numele proprii ale Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'Și de unde să știi tu ce este Saqar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'El nu lasă și nu cruță,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'Arzând și înnegrind pielea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'Și peste el veghează nouăsprezece [Îngeri]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'Și nu am pus Noi ca păzitori peste Foc decât Îngeri și nu am stabilit numărul lor decât ca încercare pentru cei care nu cred și pentru cei cărora le-a fost trimisă Cartea, să fie încredințați, și pentru ca să sporească în credință aceia care cred și pentru ca aceia cărora le-a fost dăruită Cartea și dreptcredincioșii, să nu se îndoiască, și pentru ca cei care au în inimile lor boală și necredincioșii să spună: „Ce a Voit Allah cu această pildă?” Astfel îl duce Allah în rătăcire pe cel care Voiește El și îl călăuzește pe cel care Voiește El. Și nu-i cunoaște pe soldații Domnului tău decât numai El. Și aceasta nu este decât îndemnare pentru oameni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'Nu! Jur pe Lună', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'Și pe noaptea care se duce', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'Și pe zorile care se ivesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'Cu adevărat, el [Focul] este una din cele mai mari [nenorociri]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'O prevenire pentru oameni,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'Pentru acela dintre voi care voiește să meargă înainte[6] sau să rămână în urmă!', '[6] Către calea cea dreaptă prin acceptarea avertizărilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Fiecare suflet este zălog pentru ceea ce și-a agonisit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'Afară de aleșii dreptei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'Care vor întreba în Grădini', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'Despre cei nelegiuiți:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, '„Ce v-a adus pe voi în focul Iadului?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'Iar ei vor răspunde: „Noi nu am fost dintre aceia care au împlinit Rugăciunea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'Și noi nu l-am hrănit pe cel sărman', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'Și noi am ponegrit laolaltă cu bârfitorii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'Și noi am socotit drept minciună Ziua de Apoi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'Până ce ne-a venit nouă ceea ce este sigur!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Și nu le va fi lor de niciun folos mijlocirea mijlocitorilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Oare de ce se întorc ei de la Îndemnare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'De parcă ar fi niște măgari sălbatici speriați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'Ce fug de leu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Fiecare om dintre ei ar voi să i se dea niște foi întinse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Dar nu! Ei mai degrabă nu se tem de Viața de Apoi [de pedeapsa lui Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'Dar nu! El [Coranul] este cu adevărat o Îndemnare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'Și cine voiește îl pomenește [recitându-l].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'Însă nu primesc îndemnare decât dacă Allah Voiește. El este Cel de temut și El este Cel care Stăpânește Iertarea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Nu! Jur pe Ziua Învierii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'Și nu! Jur pe sufletul care singur se învinuiește[1]!', '[1] Al unui credincios care se acuză atunci când păcătuiește sau greșește');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Oare socotește omul [necredincios] că Noi nu vom aduna din nou oasele sale?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Ba da! Noi suntem în stare să potrivim la loc și vârfurile degetelor sale [amprentele]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Însă omul voiește mai degrabă să păcătuiască înainte[2].', '[2] Se referă la necredincios, care neagă Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'El întreabă: „Când va fi Ziua Învierii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'Atunci când vederea va fi orbită', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'Și Luna se va întuneca', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'Și Soarele și Luna se vor uni și vor fi deopotrivă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'În Ziua aceea, omul va spune: „Unde este scăparea?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'Nici vorbă! Nu va fi loc de scăpare!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'Numai la Domnul tău va fi în Ziua aceea întoarcerea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'În Ziua aceea, i se va vesti omului ceea ce a dat mai înainte[3] și ceea ce a lăsat pentru mai târziu[4].', '[3] Faptele sale care îl vor aștepta în Viața de Apoi
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Ba omul va fi o mărturie limpede împotriva lui însuși[5],', '[5] Așa cum este descris în 36:65 și 41:20-23');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'Chiar dacă el va aduce dezvinovățirile sale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, '[O, Mohammed] nu mișca limba ta pentru ca să-l grăbești [recitarea Coranului]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Noi suntem datori cu strângerea lui și cu recitarea lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'Iar când Noi îl vom recita [prin Gavriil], urmează recitarea sa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'Apoi, Noi suntem datori cu tâlcuirea lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Dar nu! Voi iubiți [viața] cea trecătoare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'Și sunteți nepăsători față de Viața de Apoi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'În Ziua aceea, vor fi unele chipuri luminoase,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'Care vor privi spre Domnul lor[6],', '[6] Oamenii Paradisului își vor vedea Creatorul lor în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Iar alte chipuri vor fi în Ziua aceea întunecate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'Așteptând să li se întâmple o nenorocire.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'Dar nu! Când [sufletul] va ajunge la clavicule[7]', '[7] Atunci când un om este pe punctul de a muri, iar sufletul este pregătit pentru a părăsi corpul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'Și se va spune: „Cine este tămăduitor?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'Și el va crede că aceasta este despărțirea [de viață],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'Și piciorul se va încolăci cu piciorul [gambele][8],', '[8] Din cauza dificultăților pe care o persoană le întâmpină la moarte sau datorită conștientizării subite a realităților acestei vieți și a Vieții de Apoi. Se poate referi și la învăluirea sa după moarte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'În Ziua aceea la Domnul tău vei fi condus!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'Însă el [necredinciosul] nici nu a crezut, nici nu a făcut Rugăciunea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'Ci, dimpotrivă, el a învinuit de minciună și a întors spatele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'Apoi s-a dus spre familia sa, pășind cu îngâmfare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'Vai ție, vai!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'Și încă o dată: Vai ție, vai!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Oare omul își închipuie că el va fi lăsat în voie[9]?', '[9] Fără a avea vreo responsabilitate sau fără să se întoarcă la Creator fără a fi judecat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Oare nu a fost el o picătură din sămânța vărsată?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'Apoi a fost un cheag de sânge, apoi [Allah] l-a plămădit și i-a dat chip armonios', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'Și a făcut din el doi soți - bărbat și femeie?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'Și oare Acesta [Allah] nu are Putere să-i învie pe cei morți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Oare nu a avut omul parte de o bucată de timp când el nu era ceva vrednic de a fi pomenit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Cu adevărat, Noi l-am creat pe om dintr-o picătură de amestecuri[1], ca să-l încercăm, și l-am făcut pe el cu auz și cu văz.', '[1] O combinație între spermă și ovul, în uter');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'Cu adevărat, Noi l-am călăuzit pe drum, fie că el va fi mulțumitor, fie că el va fi nemulțumitor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Cu adevărat, Noi am pregătit pentru necredincioși lanțuri, fiare și un Foc cu vâlvătăi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'Cu adevărat, cei evlavioși vor bea dintr-un pahar, al cărui amestec va fi cu camfor[2],', '[2] Un izvor frumos mirositor din Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, 'Dintr-un izvor din care beau robii [credincioși] lui Allah, făcându-l să țâșnească mereu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Ei își țin legămintele și se tem de o Zi, al cărei rău se întinde peste tot.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'Și-l hrănesc cu mâncare, în ciuda dragostei pentru ea[3], pe cel sărman și pe orfan și pe prizonier,', '[3] Se poate înțelege și „din dragostea pentru El” (Allah)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, '[Zicând]: „Noi vă hrănim pentru a dobândi Fața lui Allah și nu voim de la voi nici răsplată, nici mulțumire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Cu adevărat, Noi ne temem de o Zi posomorâtă și tristă de la Domnul nostru!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Allah îi va apăra pe ei de răul acelei Zile și-i va face pe ei să aibă parte de lumină și bucurie;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'Și îi va răsplăti pe ei pentru că au răbdat, cu o Grădină și cu [veșminte] de mătase,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Rezemându-se pe divanuri, fără să vadă în ea nici Soare arzător, nici ger.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'Și asupra lor se vor lăsa în jos umbrele ei, iar fructele ei vor atârna, [fiind la îndemâna lor].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'Și se va trece printre ei cu vase de argint și cu pocaluri cristaline,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Cristaluri de argint făcute cu măsură precisă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'Și li se va da să bea [acolo] dintr-un pocal al cărui amestec va fi cu ghimbir,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, '[Scos] acolo dintr-un izvor ce se cheamă Salsabil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Vor trece printre ei băieți veșnic tineri, care, când îi vezi, crezi că sunt mărgăritare înșirate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'Și când te vei uita acolo [în Paradis], vei afla plăcere și mare Împărăție.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'Vor purta veșminte din mătase verde și brocart și vor fi împodobiți cu brățări de argint. Și Domnul lor le va da să bea dintr-o băutură curată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, '[Li se va spune] „Cu adevărat, aceasta va fi pentru voi răsplata și râvna voastră va primi mulțumire.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'Cu adevărat, Noi ți-am trimis ție [o, Mohammed] Coranul treptat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Așadar, fii răbdător și așteaptă judecata Domnului tău și nu da ascultare vreunui păcătos sau necredincios dintre ei!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'Și pomenește Numele Domnului tău dimineața și seara', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'Și prosternează-te dinaintea Lui și o parte din noapte și laudă-L pe El și în timpul nopții îndelung!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Cu adevărat, aceștia [necredincioșii] iubesc viața trecătoare și lasă în urma lor[4] o Zi grea.', '[4] Neglijează. Înțelesul poate fi și „trimite înaintea lor”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Noi i-am creat pe ei și am întărit făptura lor, însă dacă Voim, Noi îi putem înlocui pe ei numaidecât cu alții asemenea lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Cu adevărat, aceasta este o Îndemnare și cine voiește apucă drumul către Domnul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'Însă voi nu puteți voi decât dacă Binevoiește Allah, căci Allah este Alim [Atoateștiutor] [și] Hakim [Înțelept].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'El lasă să intre pe cine Voiește sub Îndurarea Sa, iar nelegiuiților le-a pregătit chin dureros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'Pe [vânturile] cele trimise în rafale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'Și care suflă în vijelie,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'Pe cele care risipesc, trimițând [Nori],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'Și pe [Îngerii care coboară cu Versetele Coranului] care separă limpede [ceea ce este bun de ceea ce este rău]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'Și [Îngerii] care aduc un îndemn,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'În chip de dezvinovățire sau de prevenire!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'Ceea ce vi se făgăduiește se va întâmpla negreșit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Când Stelele se vor stinge', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'Și când Cerul se va despica', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'Și când munții se vor fărâmița', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'Și când Trimișilor li se va hotărî un timp!...[1]', '[1] Când sunt adunați pentru a depune mărturie pentru popoarele lor. Sfârșitul propoziției se înțelege a fi „...judecata promisă va avea loc.”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'Pentru care Zi au fost amânate?[2]', '[2] Se poate face referire fie la întâmplările menționate anterior sau la mărturia mesagerilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'Pentru Ziua Judecății!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'Și ce ți-ar putea spune ce e Ziua Judecății?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Vai[3], în Ziua aceea, pentru cei care tăgăduiesc!', '[3] Moarte și distrugere');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Oare, nu am distrus Noi popoarele anterioare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'Și nu am făcut să le urmeze lor altele?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Astfel îi tratăm Noi pe păcătoși!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Oare nu v-am creat Noi dintr-o apă umilă [sperma]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'Pe care am așezat-o într-un loc statornic și sigur [uterul mamei]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'Până la un termen știut?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Noi am Hotărât astfel și cât de bine Hotărâm Noi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Oare nu am făcut Noi Pământul un loc care-i adună', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'Pe cei vii și pe cei morți?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'Și nu am făcut pe el munți trainici, semeți și nu v-am dat vouă să beți apă dulce?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, '[Li se va spune] „Purcedeți către ceea ce voi ați tăgăduit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Purcedeți către o umbră [de fum] cu trei ramuri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'Care nu este nici umbroasă și care nici nu apără de flacără.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'Cu adevărat, ea aruncă scântei cât turnurile,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'Ca și când ar fi niște cămile galbene înnegrite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Aceasta este Ziua în care ei nu vorbesc', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'Și nu li se va îngădui lor să se dezvinovățească!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Vai, în Ziua aceea, pentru cei care învinuiesc de minciună!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'Aceasta este Ziua Judecății, în care Noi vă vom aduna laolaltă cu cei de dinainte;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'Și dacă aveți un vicleșug, atunci uneltiți împotriva Mea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'Cu adevărat, cei evlavioși se vor afla la umbră și printre izvoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'Ca și printre fructe după cum poftesc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, '[Și li se va spune] „Mâncați și beți cu plăcere, pentru ceea ce ați făcut!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Astfel îi răsplătim Noi pe binefăcători!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, '[O, necredincioșilor!] „Mâncați și bucurați-vă puțin! Cu adevărat, voi sunteți nelegiuiți!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'Și când li se spune lor „Prosternați-vă!” ei nu se prosternează.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Vai, în Ziua aceea, pentru cei care tăgăduiesc!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Și în care Cuvânt vor crede ei după el [Coranul]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, 'Despre ce întreabă întreolaltă?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, 'Despre Vestea cea mare[1],', '[1] Învierea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'În privința căreia sunt în neînțelegere!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'Ei, bine, nu! Ei o să afle cât de curând!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'Și încă o dată: Nu! Ei o să afle!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Oare nu am făcut Noi Pământul un pat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'Și munții ca țăruși?[2]', '[2] Pentru a face Pământul stabil și echilibrat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'Și v-am creat pe voi perechi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'Și v-am lăsat vouă somnul [un mijloc] pentru odihnă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'Și am făcut din noapte un veșmânt[3]', '[3] Acoperindu-vă și ascunzându-vă în întunecimea sa');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'Și am făcut ziua pentru agonisirea hranei', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'Și am durat deasupra voastră șapte [Ceruri] întărite', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'Și am făcut o lampă aprinsă [Soarele]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Și am pogorât din Nori apă din belșug,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'Pentru ca să facem să se ivească grâne și ierburi, cu ajutorul ei,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'Și grădini dese.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Cu adevărat, Ziua Judecății va fi un termen [pentru adunare]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'O Zi în care se va suna în Trâmbiță și veți veni în cete,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'Și se va deschide Cerul cu niște porți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'Și munții vor fi clintiți din loc și vor fi ca un miraj,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Cu adevărat, Gheena va fi loc de chinuri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'Și va fi adăpost pentru nelegiuiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'Pentru a petrece în ea veacuri la rând;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'Nu vor gusta în ea răcoare și nici băutură,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'Ci numai apă clocotită și puroi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'Ca răsplată dreaptă![4]', '[4] În comparație cu păcatele lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Cu adevărat, ei nu se așteaptau să dea socoteală', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'Și țin de minciună Versetele Noastre, fără întrerupere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'În vreme ce toate lucrurile sunt adunate într-o carte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, '„Gustați, așadar [pedeapsa voastră]! Și nu vă vom spori vouă decât chinul!”[5]', '[5] Li se va spune celor din Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'Însă pentru cei evlavioși va fi o izbândă[6]:', '[6] Siguranță, succes și răsplată, inclusiv scăpare de Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'Grădini și struguri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'Și [fete frumoase] cu sânii rotunjiți - toate la fel de tinere -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'Și pocale pline[7].', '[7] De vin ce nu îmbată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Nu vor auzi în ele vorbe deșarte și nici minciuni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, '[Aceasta este] răsplată de la Domnul tău și un Dar îmbelșugat[8],', '[8] Drept rezultat al faptelor lor bune și al Generozității nelimitate a lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, '[De la] Stăpânul Cerurilor și al Pământului și al celor care se află între ele, Ar-Rahman [Cel Milostiv]. Și ei nu vor cuteza să-I spună Lui o vorbă.[9]', '[9] Niciuna dintre creațiile lui Allah nu vor putea să se roage de El în Ziua Judecății, decât cu permisiunea Sa');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'O Zi în care Duhul [Gavriil] și Îngerii se vor așeza în rând și nimeni nu va vorbi, în afară de cel căruia Ar-Rahman [Cel Milostiv] îi va da îngăduință și care va spune adevărul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'Această Zi este adevărată. Deci, acela care voiește, trebuie să caute adăpost la Domnul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Cu adevărat, Noi v-am prevenit despre o pedeapsă apropiată, în Ziua când omul va vedea ce au făcut mâinile sale mai înainte[10], iar necredinciosul va zice: „Vai mie! Ce bine dacă aș fi fost țărână!”', '[10] Faptele pe care le-a făcut în această viață, care îl așteaptă pe om în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'Pe cei care smulg cu putere[1]', '[1] Îngerii care scot afară cu forță sufletele celor destinați pentru Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'Și pe cei care iau cu blândețe[2]', '[2] Îngerii care scot afară cu ușurință sufletele celor destinați pentru Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'Și pe cei care plutesc iute, în libertate[3],', '[3] Întrecându-se să execute Poruncile lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'Și pe cei care se grăbesc, întrecându-se[4],', '[4] Întrecându-se să ducă sufletele credincioșilor în Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'Și pe cei care orânduiesc lucrurile![5]', '[5] Conform destinului prescris de Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'În Ziua aceea, se va cutremura Pământul, [la prima suflare în Trâmbiță],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'Pe care îl va urma numaidecât următorul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'În Ziua aceea, vor fi inimi[6] cuprinse de spaimă,', '[6] Ale necredincioșilor care au negat Învierea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'Dar privirile lor[7] vor fi plecate.', '[7] Ale necredincioșilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Ei [sunt cei care în viața pământească] spuneau: „Oare noi vom fi întorși la viața de dinainte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Când noi vom fi niște oase putrede?”[8]', '[8] Necredincioșii au spus aceasta batjocorind avertizarea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'Ei ziceau: „Aceasta va fi, așadar, o întoarcere pierdută!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'Atunci va fi numai un sunet înfiorător', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'Și iată-i pe ei întorși la viață, din nou pe fața pământului!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Oare a ajuns până la tine povestea lui Moise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'Când l-a Chemat Domnul său în valea cea sfântă, Tova,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, '[Spunându-i]: „Du-te la Faraon, căci el se întrece [în comiterea de păcate]!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'Și spune-i: „Vrei să te curățești', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'Și să te călăuzesc către Domnul tău, pentru ca tu să fii cu frică [de El]?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'Și el i-a arătat lui minunea cea mai mare[9],', '[9] Miracolul toiagului său care s-a transformat într-un șarpe');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'Însă el [Faronul] a socotit-o minciună și nu s-a supus,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'Apoi a întors spatele și a plecat degrabă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'A adunat [oamenii] și a strigat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'Și a zis: „Eu sunt Domnul vostru cel mai înalt!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Atunci l-a lovit pe el Allah cu pedeapsa Lumii de Apoi și a acestei lumi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'Întru aceasta este o pildă pentru cel ce se teme [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'Sunteți voi mai greu de făcut sau Cerul pe care l-a înălțat El?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'El a ridicat bolta lui și l-a orânduit pe deplin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'El a făcut întunecată noaptea lui și a scos la iveală ziua lui', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'Și Pământul, după aceea, l-a întins', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'Și a făcut să iasă din el apa lui și pășunea lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'Și a întărit munții lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'Drept înzestrare pentru voi și pentru animalele voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'Iar când va veni nenorocirea cea mai mare[10],', '[10] Ziua Învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'Ziua în care omul își va aduce aminte de cele pentru care a trudit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'Și se va arăta Iadul pentru cel care vede...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'În ce-l privește pe cel care s-a întrecut', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'Și a pus mai presus viața din această lume,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Iadul va fi sălașul lui!...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'Iar în ce-l privește pe cel care se teme de Ziua când se va înfățișa Domnului[11] său și și-a oprit sufletul de la pofte,', '[11] A se vedea 55:46');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'Raiul îi va fi sălaș!...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'Te întreabă ei despre Ceas, când va fi termenul lui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Ce poți tu pomeni despre el?[12]', '[12] Mohammed nu are știință despre el, cum ar putea să îi informeze?');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'La Domnul tău este termenul lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Tu ești numai un prevenitor pentru cel care se teme de el,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'Iar în Ziua când îl[13] vor vedea, li se va părea lor că ei nu au petrecut decât numai o seară sau o dimineață.', '[13] Ceasul, Învierea');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'El [profetul Mohammed] s-a încruntat și s-a întors,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'Când orbul a venit la el[1] [întrerupându-l ca să-l întrebe].', '[1] Abdullah, fiul lui Umm Maktum');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'Și de unde să știi [ o, Mohammed]? Poate că el a voit să se curățească[2]', '[2] Ca urmare a ceea ce a învățat de la tine');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'Sau a venit să fie îndemnat și i-ar fi fost spre folos îndemnarea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'Însă în ce-l privește pe cel care crede că nu are nevoie[3],', '[3] Fără nevoie de credință sau fără nevoie de Allah. Aici se face referire la un anumit membru influent din Qurayș pe care Profetul (pacea și binecuvântarea lui Allah fie asupra sa) spera să îl aducă la Islam');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'Tu către el te îndrepți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'Fără să ai nicio vină dacă el nu se curățește[4],', '[4] Profetul (pacea și binecuvântarea lui Allah fie asupra sa) era responsabil doar pentru transmiterea Mesajului, nu pentru călăuzirea supremă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'Iar în ce-l privește pe cel care vine la tine cu râvnă [pentru cunoaștere]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'Și este cu frică [de Allah],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'Pe acela îl neglijezi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Dar nu! El [Coranul] este o Îndemnare', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'Și cine voiește se lasă îndemnat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'Înscris pe foi cinstite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'Înălțate și curate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'Purtate de mâinile unor scribi (Îngeri mesageri),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'Nobili și pioși.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Blestemat este omul! Cât de necredincios este el!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'Din ce l-a creat pe el?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Dintr-o picătură l-a creat și i-a hotărât [soarta].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'Apoi i-a făcut lui drumul ușor[5],', '[5] În această viață (nașterea). Se poate referi și la viața în sine, care a fost făcută ușoară prin călăuzirea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'Apoi l-a lăsat pe el să moară și a orânduit să fie pus în mormânt[6],', '[6] Pentru a-i ascunde corpul putrezitor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'Apoi, atunci când va Voi, îl va învia pe el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'Dar nu! [Omul] nu împlinește ceea ce El îi poruncește...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Atunci să cugete omul la hrana sa [ca să vadă cum a ajuns la el]!...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'Noi am vărsat apa din belșug,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'Apoi am crăpat Pământul, despicându-l [cu răsaduri],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'Și am făcut să crească pe el grâne,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'Viță de vie și iarbă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'Măslini și palmieri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'Grădini cu pomi (înalți) și deși,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'Fructe și ierburi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'Spre folosul vostru și al dobitoacelor voastre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'Și când va veni Zgomotul cel Asurzitor[7],', '[7] Zgomotul asurzitor al Trâmbiței care anunță Învierea. Aș-Șakhkah este, de asemenea, un nume pentru Ziua Învierii');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'În Ziua aceea va fugi omul de fratele lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'De mama lui, de tatăl lui,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'De soața lui și de copiii lui!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'În Ziua aceea, fiecare om va avea lucrul său care îi va fi de ajuns.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'În Ziua aceea, vor fi chipuri luminoase,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'Surâzătoare și vesele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'Și în Ziua aceea, vor fi chipuri cu colb pe ele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'Pe care le va acoperi întunericul, -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'Aceștia sunt necredincioșii nelegiuiți.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Când Soarele se va strânge și se va întuneca', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'Și când Stelele vor cădea și se vor risipi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'Și când munții vor fi spulberați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'Și cămilele[1] îngreunate de zece luni vor fi neîngrijite,', '[1] Acest verset face referire la distragerea oamenilor de la cele mai de preț bunuri');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'Când sălbăticiunile vor fi adunate laolaltă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'Și când mările se vor aprinde,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'Când sufletele se vor împerechea [cu cei asemenea lor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'Și când fetița îngropată de vie va fi întrebată', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'Pentru ce păcat a fost omorâtă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'Când foile[2] vor fi desfăcute și împărțite', '[2] Pe care sunt înregistrate faptele tuturor oamenilor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'Și când Cerul va fi dezgolit și îndepărtat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'Și când Iadul se va aprinde', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'Și când Raiul va fi adus aproape,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'Atunci va ști [fiecare] suflet ce a adus[3].', '[3] Toate faptele omului din această viață, ce au condus sufletul în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'Dar nu! Jur pe Stelele ce se retrag [dispărând ziua și apărând noaptea],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'Ce grăbesc să se ascundă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'Și pe noaptea slab întunecată [furișată]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'Și pe dimineața care vine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Acesta [Coranul] este Cuvântul [transmis de] un Mesager nobil [Gavriil],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'Înzestrat cu mare putere, cu vază la Stăpânul Tronului,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'Căruia i se arată supunere acolo, cinstit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'Tovarășul vostru [Mohammed] nu este nebun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'El l-a văzut în zarea limpede[4] [pe Gavriil].', '[4] În Est, unde răsare soarele. A se vedea 53:6');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'Și el [Mohammed] nu este cu necunoscutul [ce i-a fost revelat] zgârcit [ascunzându-l][5].', '[5] Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa) nu a ascuns știința despre necunoscut pe care Allah i-a revelat-o în Coran');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'Acesta nu este nici cuvântul unui șeitan alungat cu pietre!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'Deci unde [voiți să] vă duceți?[6]', '[6] Negând Coranul și acuzându-l pe Profetul Mohammed (pacea și binecuvântarea lui Allah fie asupra sa)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'El nu este decât o îndemnare pentru lumi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'Pentru acela dintre voi care voiește să meargă pe drumul cel drept.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'Dar voi nu puteți voi decât dacă Voiește Allah, Stăpânul lumilor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Când Cerul se va despica', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'Și Stelele vor cădea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'Când mările vor izbucni [în flăcări]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'Și când mormintele vor fi răsturnate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, 'Atunci va ști [fiecare] suflet ce a împlinit [ce a fost] și ce a lăsat [și ce a ajuns].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'O, omule! Ce te-a făcut pe tine să fi neglijent în privința Domnului tău Al-Karim [Cel Generos],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'Care te-a creat, te-a întregit și ți-a dat statură dreaptă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'Și te-a plăsmuit pe tine în chipul în care a Voit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'Dar nu! Voi nu credeți în Ziua Judecății!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'Însă peste voi sunt veghetori[1]', '[1] Îngeri care înregistrează faptele oamenilor în cărți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'Cinstiți, care scriu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'Ei știu ce faceți voi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Cei evlavioși vor intra în Rai,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'Iar nelegiuiții vor intra în Iad,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'Vor arde în el în Ziua Judecății,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'Fără putința de a scăpa de el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'Dar de unde să știi tu ce este Ziua Judecății?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'Și încă o dată: de unde să știi tu ce este Ziua Judecății?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'Este Ziua în care niciun suflet nu va putea [face nimic] pentru alt suflet și în Ziua aceea Porunca va fi a lui Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Vai acelora care înșeală la măsură[1],', '[1] Cei care înșeală oamenii la cântărire prin faptul că le dau mai puțin decât ceea ce au plătit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'Aceia care, dacă li se măsoară de către [alți] oameni, voiesc măsură întreagă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'Însă atunci când ei măsoară și cântăresc, dau mai puțin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Oare nu cred aceia că ei vor fi înviați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'Într-o Zi mare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'O Zi în care oamenii vor sta înaintea Stăpânului lumilor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'Dar nu! Celor nelegiuiți le este scris că se vor afla în Sijjin! -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'Dar de unde să știi tu ce este Sijjin? -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, '[Este destinația[2] înscrisă] într-o carte scrisă limpede!', '[2] Cel mai jos nivel al Iadului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Vai în Ziua aceea pentru cei care tăgăduiesc,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'Pentru cei care tăgăduiesc Ziua Judecății!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'Însă nu o tăgăduiește pe ea decât cel nelegiuit și păcătos,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'Care, atunci când i se recită lui Versetele Noastre, zice: „Povești ale celor de demult!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'Dar nu! S-au acoperit de rugină inimile lor cu cele pe care le-au agonisit![3]', '[3] Păcatele lor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'Nu! În Ziua aceea ei vor fi împiedicați de la vederea Domnului lor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Apoi ei vor fi cei care ajung și ard în Iad', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'Și atunci li se va zice [lor]: „Aceasta este ceea ce ați tăgăduit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'Dar nu! Celor drepți le este scris că ei se vor afla în Illiyyun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'Dar de unde să știi tu ce este Illiyyun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, '[Este destinația[4] înscrisă] într-o carte scrisă limpede!', '[4] Cel mai înalt nivel al Paradisului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Vor face mărturie pentru ea cei apropiați [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Cei drepți se vor afla în [Grădinile] plăcerii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'Îi vor privi de pe divanuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'Pe fețele lor vei recunoaște strălucirea binecuvântărilor (Raiului).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'Li se va da să bea dintr-un nectar pecetluit[5],', '[5] Delicios și care nu îmbată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'A cărui pecete[6] este moscul. Și întru aceasta [se cuvine] să se întreacă cei care se întrec.', '[6] Mireasma');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'Iar amestecul lui este din Tasnim[7].', '[7] Cel mai înalt izvor din Paradis și cea mai plăcută băutură de către locuitorii săi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, 'Un izvor din care beau cei apropiați [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Cei ce sunt nelegiuiți au râs de cei care cred,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'Iar când au trecut pe lângă ei, și-au făcut semne,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'Iar când s-au întors la familiile lor, s-au întors ei batjocorind,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'Iar când i-au văzut pe ei, au zis: „Aceștia sunt în rătăcire!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'Ori ei nu au fost trimiși ca păzitori asupra lor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'În Ziua aceasta[8] cei care cred vor râde de necredincioși,', '[8] În Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, 'Privind de pe divanuri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, '[Nu-i așa că] sunt răsplătiți necredincioșii pentru ceea ce au săvârșit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Când Cerul se va crăpa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'Și-I va da ascultare Stăpânului său, după cuviință[1],', '[1] Va auzi porunca lui Allah și se va grăbi să o îndeplinească');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'Când Pământul va fi întins', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'Și va arunca afară ceea ce se află în el[2] și se va deșerta', '[2] Cei morți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'Și-I va da ascultare Stăpânului său, după cuviință...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'O, omule! Tu te silești către Domnul tău din răsputeri[3] și tu Îl vei întâlni!', '[3] Luptându-se de-a lungul vieții să îl întâlnească pe Domnul lor, grăbindu-se către moarte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'În ce-l privește pe cel căruia i se va da cartea în dreapta sa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'Cu acela se va face socoteală ușoară', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'Și el se va întoarce la familia sa bucuros.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'Însă în ce-l privește pe cel căruia cartea sa i se va da prin spatele său,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'Acela se va ruga pentru pieire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'Și va arde în flăcări.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Cu adevărat, el a fost bucuros în mijlocul familiei sale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'Și și-a închipuit că nu se va întoarce niciodată.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Dar nu! Domnul lui l-a văzut pe el prea bine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Nu! Jur pe amurg', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'Și pe noapte și pe ceea ce adună ea [în întunericul ei]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'Și pe Luna care se întregește!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'Voi veți trece de la o stare la alta![4]', '[4] În diferite stări, atât în această viață cât și în Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Dar ce au ei că nu cred,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'Iar când li se citește Coranul nu se prosternează?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Însă aceia care nu cred îl socotesc mai degrabă minciună,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'Iar Allah știe mai bine ce ascund ei.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'Vestește-le lor, așadar, un chin dureros,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Afară de aceia care cred și plinesc fapte bune, căci ei vor avea parte de o răsplată neîntreruptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'Pe Cerul cu constelații', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'Și pe Ziua făgăduită!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'Pe martor [Ziua de Vineri] și pe ceea ce este mărturisit [Ziua Arafah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'Blestemați să fie cei [care] au săpat șanțul adânc[1],', '[1] Cei care au săpat șanțul adânc au fost oamenii unui rege tiranic care a refuzat să își lase oamenii să creadă în Allah. Fapta rea pe care au făcut-o în ascultarea regelui lor le-a adus blestemul lui Allah.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'Cel cu focul aprins de vreascuri [din abundență],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'În vreme ce stăteau așezați lângă el', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'Și ei erau martori la ceea ce le-au făcut credincioșilor[2],', '[2] După ce i-au aruncat pe credincioși în șanțul plin cu foc, ei au stat pe margine și s-au uitat la ei cum au ars de vii. Acest eveniment a avut loc înainte de timpul profetului Mohammed (pacea și binecuvântarea lui Allah fie asupra sa).');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'Pe care nu s-au răzbunat decât pentru că ei au crezut în Allah Al-Aziz [Cel Puternic] [și] Al-Hamid [Cel Vrednic de Laudă],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'A Căruia este Împărăția Cerurilor și a Pământului. Iar Allah este Martor peste toate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Cu adevărat, cei care i-au prigonit pe cei credincioși și pe cele credincioase, iar apoi nu s-au căit, vor avea parte de chinurile Gheenei și vor avea parte de chinurile Focului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'Însă aceia care cred și împlinesc fapte bune, vor avea parte de Grădini pe sub care curg râuri și aceasta este izbânda cea mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Răzbunarea Domnului tău este aspră.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'El este Cel care face prima oară [creația] și El este Cel care o face din nou.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'El este Al-Ghafur [Cel Iertător] [și] Al-Uadud [Cel Plin de Dragoste],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'Stăpânul Tronului, Al-Majid [Cel Glorios],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Cel care face ceea ce Voiește.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Oare a ajuns până la tine vestea despre oștenii', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'Lui Faraon și ai neamului Thamud?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Aceia care nu cred stăruie în tăgăduire,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'Însă Allah, care se află în urma lor [cunoscându-le faptele], îi cuprinde pe ei[3].', '[3] A se vedea 2:19');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Dar acesta este un Coran glorios,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'Scris pe o Tablă bine Păstrată [de Allah].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'Pe Cer și pe cel care vine noaptea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'Dar de unde să știi tu ce este cel care vine noaptea?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, '[Acesta este] luceafărul cel strălucitor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Nu este suflet care să nu aibă asupra sa un păzitor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Deci să cugete omul din ce este el creat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'El este creat dintr-o apă țâșnită,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'Ce iese dintre coaste și șira spinării!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'Cu adevărat, El are puterea să-l facă din nou,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'În Ziua în care se vor dezvălui tainele[1],', '[1] Expuse și examinate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'Și atunci nu va avea nici putere, nici ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'Pe Cerul cel cu revenirea [ploii]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'Și pe Pământul cu crăpături[2]!', '[2] Din care cresc plante');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Cu adevărat, el [Coranul] este un Cuvânt hotărâtor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'El nu este o glumă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Ei plănuiesc un vicleșug,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'Dar și Eu am un Plan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'Deci, dă-le un răgaz necredincioșilor! Dă-le lor un scurt răgaz![3]', '[3] Nu te grăbi să te răzbuni, fiindcă vei vedea cum vor ajunge ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Slăvește Numele Domnului tău Al-''A''la [Cel Preaînalt]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Care a creat și a plămădit', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'Și care a orânduit și a călăuzit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'Care a făcut să se ivească pășunea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'Iar apoi a făcut-o fân întunecat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'Noi te vom învăța [o, Mohammed] să reciți [Coranul], astfel încât tu să nu uiți,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'Decât numai ce Voiește Allah; El Cunoaște deopotrivă ceea ce se rostește și ceea ce este ascuns.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'Noi îți vom ușura către ceea ce este [mai] ușor[1]', '[1] Calea și Religia lui Allah, care este ușoară și firească sau către Paradis, prin oportunități de a face fapte bune');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'Deci îndeamnă, dacă îndemnarea este spre folos[2].', '[2] Oriunde este auzită sau înțeleasă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'Cel ce se teme [de Allah] se lasă îndemnat,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'Dar se ferește cel nelegiuit,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'Care va arde în focul cel mai mare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'În care nici nu va muri, nici nu va trăi [o viață ușoară].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Va izbândi cel ce se curățește [acceptând monoteismul]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'Și Numele Domnului său Îl pomenește și face Rugăciunea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Dar voi alegeți viața din această lume,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'Însă Viața de Apoi este mai bună și este dăinuitoare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Aceasta se află și în foile cele vechi,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'În foile lui Avraam și ale lui Moise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Oare a ajuns la tine vestea despre cea care copleșește [Ziua Învierii]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'În Ziua aceea, vor fi chipuri umilite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'Muncindu-se, istovite[1],', '[1] Au făcut fapte în această viață ce nu le-au adus niciun folos deoarece aceștia nu aveau credință sau acestea nu erau făcute pentru mulțumirea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'Arzând într-un foc fierbinte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'Și li se va da să bea dintr-un izvor clocotitor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'Și nu vor avea ca mâncare decât dari''[2],', '[2] O plantă otrăvitoare, cu spini');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'Ce nici nu îngrașă [trupul celui care mănâncă, hrănindu-l] și nici nu [îi] astâmpără foamea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'Și în Ziua aceea vor fi chipuri vesele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'Mulțumite de strădania lor [de pe pământ],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'Într-o Grădină înălțată,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'În care nu vor auzi vorbe deșarte[3].', '[3] Nicio insultă, falsitate, imoralitate sau bârfă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'În ea va fi un izvor ce curge,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'În ea vor fi divanuri ridicate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'Și pocale așezate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'Și perne rânduite', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'Și covoare așternute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Oare nu se uită ei la cămile cum au fost ele create?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'Și la Cer, cum cum a fost el înălțat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'Și la munți, cum au fost ei ridicați [și cum sunt ei fermi]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'Și la Pământ, cum a fost el întins?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Deci îndeamnă [o, Mohammed]! Tu ești numai un îndemnător,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'Tu nu ai putere asupra lor [ca să-i silești la credință],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'Însă pe cel care întoarce spatele și nu crede,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'Pe acela îl va chinui Allah cu chinul cel mai mare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'La Noi este întoarcerea lor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'Și, cu adevărat, Nouă Ne revine să le cerem lor socoteală!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'Pe zori', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'Și pe cele zece nopți![1]', '[1] Interpretate de obicei ca primele 10 nopți din luna Dhul-Hijjah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'Pe cel care are pereche și pe cel fără pereche', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'Și pe noaptea ce se scurge!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'Oare este acesta un jurământ pentru cel cu pricepere?[2]', '[2] Bazat pe următorul verset, ceea ce jură Allah este că El îi va pedepsi cu siguranță pe necredincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Oare nu ai văzut ce a făcut Domnul tău cu ’Ad,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'Cu Iram[3], [cetatea] cu corturi ridicate,', '[3] Un alt nume pentru primii oameni ai lui `Aad, la care a fost trimis profetul Hud');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'Care nu a mai fost alta creată asemenea ei printre cetăți', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'Și cu cei din neamul Thamud, care au tăiat stâncile din vale [pentru a-și construi locuințe],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'Și cu Faraon, stăpânul soldaților[4]', '[4] Prin care i-a torturat pe oameni');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'Care au fost nelegiuiți în cetățile [lor]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'Și au înmulțit stricăciunea în ele?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'Așadar, Domnul tău a vărsat asupra lor chinuri felurite!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'Cu adevărat, Domnul tău vă Observă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'Cât despre om, când Domnul său îl încearcă și îl cinstește și este Îndurător cu el, atunci el zice: „Domnul meu m-a cinstit!”[5]', '[5] El este mai degrabă mândru decât recunoscător');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'Însă când Domnul său îl încearcă și-i micșorează lui înzestrarea, atunci el zice: „Domnul meu m-a umilit!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'Dar nu[6]! Voi nu-l cinstiți pe orfan', '[6] Nu este ceea ce îți imaginezi. Dimpotrivă Allah îi încearcă pe oameni prin prosperitate și greutăți și răsplătește cu onoarea în Viața de Apoi atât recunoștința, cât și răbdarea.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'Și nu vă îndemnați la hrănirea sărmanului', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'Și mâncați moștenirea cu lăcomie[7]', '[7] Fără a vă păsa dacă este permisă sau nepermisă');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'Și iubiți averea cu o dragoste fără de margini!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'Nu! Când Pământul va fi prefăcut în pulbere', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'Și va veni Domnul tău[8], când Îngerii vor sta în rânduri', '[8] Să facă judecata. A se vedea 2:19.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'Și va fi adus în Ziua aceea Iadul, în Ziua aceea omul își amintește. Dar cum să-i mai fie lui de folos amintirea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'Și va zice el: „Ce bine ar fi fost, dacă aș fi făcut mai înainte [fapte bune] pentru viața mea!”[9]', '[9] Pentru Viața de Apoi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'Dar în Ziua aceea nimeni nu va osândi așa cum osândește El', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'Și nimeni nu va lega așa de strâns cum leagă El...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, '[Celor dreptcredincioși li se vor spune] „O, tu suflet liniștit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'Întoarce-te la Domnul tău mulțumit și împăcat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'Și intră între robii Mei', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'Și intră în Raiul Meu!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Nu! Jur pe această cetate [Mecca] -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'Și tu [o, Mohammed] ești eliberat [de păcatele] din această cetate! -', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'Și pe părinte[1] și pe ceea ce el zămislește!', '[1] Considerat a fi Adam');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Noi l-am creat pe om spre încercare [pentru a trudi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Crede el că nu va avea putere nimeni asupra lui?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'El zice: „Am irosit avere multă!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Oare crede el că nu-l vede nimeni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Oare nu i-am dat lui doi ochi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'Și o limbă și două buze', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'Și nu i-am dat lui două drumuri?[2]', '[2] Al binelui și al răului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Dar el nu a străbătut drumul cel greu![3]', '[3] Abrupt înclinat sau obstacol. Cu alte cuvinte, el nu a cheltuit pe calea lui Allah, ci doar pentru a se lăuda în fața altora.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'Dar de unde să știi tu ce este drumul cel greu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'Dezlegarea unui sclav', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'Sau hrănirea, într-o zi de foamete,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'A unui orfan dintre rude', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'Sau a unui sărman, aflat în sărăcie lucie!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'Apoi, a fost dintre cei care cred și se îndeamnă la răbdare și se îndeamnă la îndurare!...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'Aceștia sunt adepți ai dreptei[4]', '[4] Cei care își vor primi faptele în mâna dreaptă și vor intra în Paradis');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'Însă, cei care tăgăduiesc semnele Noastre sunt adepți ai stângii[5]', '[5] Cei care își vor primi faptele în mâna stângă și vor intra în Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'Și asupra lor va fi un Foc închis[6].', '[6] Acoperișul Iadului va fi sigilat și închis, cuprinzând focul și locuitorii săi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'Pe Soare și pe strălucirea lui', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'Și pe Luna care îi urmează [Soarelui]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'Pe ziua care îl face să strălucească[1]', '[1] Pământul. Poate fi interpretat și ca Soarele. La fel se aplică și următorului Verset.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'Și pe noaptea care îl acoperă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'Pe Cer și pe Cel care l-a înălțat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'Și pe Pământ și pe Cel care l-a făcut întins!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'Și pe suflet și pe Cel care l-a plăsmuit[2]', '[2] Proporționat și echilibrat');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'Și i-a insuflat lui ceea ce este rău și ceea ce este bun!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'Izbândește cel care îl curățește', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'Și pierdut este cel care îl strică [îngropându-l în nesupunere]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'A învinuit de minciună [neamul] Thamud prin trecerea măsurii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 12, 'Când s-a ridicat cel mai ticălos dintre ei [pentru a înjunghia cămila].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 13, 'Trimisul lui Allah le-a zis lor: „Este cămila lui Allah, adăpați-o!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 14, 'Însă ei l-au socotit mincinos și au junghiat-o[3]. Și Domnul lor s-a mâniat pe ei pentru păcatul lor și a trimis asupra lor [pedeapsă], cuprinzându-i pe toți,', '[3] Au înjunghiat cămila trimisă de către Allah ca semn pentru ei');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 15, 'Fără ca El să Se teamă de urmare![4]', '[4] Allah nu este întrebat despre ceea ce face, ci robii Săi vor fi întrebați. A se vedea 21:23.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 1, 'Pe noapte, când acoperă', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 2, 'Și pe zi, când se luminează', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 3, 'Și pe Cel ce a creat bărbatul și femeia!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 4, 'Cu adevărat, eforturile voastre sunt diferite [scopurile voastre sunt diferite]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 5, 'Cât despre cel care dăruiește și are frică [de Allah]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 6, 'Și crede în răsplata cea frumoasă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 7, 'Aceluia îi vom ușura Noi [calea] către bucurie.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 8, 'Cât despre cel care este zgârcit și caută să se îmbogățească (considerând că el nu este în nicio nevoie de Allah)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 9, 'Și tăgăduiește răsplata cea frumoasă,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 10, 'Aceluia îi vom ușura Noi [calea] către ceea ce este cel mai greu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'Și nu-i va fi de niciun folos averea, când el va fi aruncat[1].', '[1] Când moare sau când este distrus. Poate însemna și când cade în Focul Iadului.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Cu adevărat, Nouă Ne revine călăuzirea', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'Și ale Noastre sunt, atât Lumea de Apoi, cât și lumea aceasta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'V-am prevenit pe voi despre un Foc ce arde cu flacără,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'Unde nu va arde decât cel mișel,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 16, 'Care tăgăduiește și întoarce spatele,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 17, 'În vreme ce va fi ferit de el cel evlavios,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 18, 'Care dă averea lui [ca milostenie] și se curățește', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 19, 'Și care nimănui nu-i face un bine pentru a fi răsplătit[2],', '[2] Fără a aștepta beneficii pentru el');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 20, 'Ci numai căutând Fața Domnului său Cel Preaînalt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 21, 'Și el va fi mulțumit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 1, 'Pe ziua luminoasă [de după răsărit]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 2, 'Și pe noapte, când se întunecă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 3, 'Domnul tău nu te-a părăsit [o, Mohammed] și nici nu te urăște!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 4, 'Viața de Apoi va fi pentru tine mai bună decât prima!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 5, 'Și Domnul tău îți va dărui și vei fi tu mulțumit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 6, 'Oare nu te-a găsit El orfan și ți-a dat adăpost?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 7, 'Nu te-a găsit pe tine pierdut și te-a călăuzit?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 8, 'Nu te-a găsit pe tine sărman și te-a făcut bogat?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 9, 'Cât despre orfan, nu-l oprima!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 10, 'Cât despre cel care cere, nu-l alunga!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 11, 'Iar cât despre Binecuvântarea Domnului tău, despre ea vorbește!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 1, 'Oare nu ți-am deschis ție pieptul [o, Mohammed][1]', '[1] Ți-am umplut inima cu călăuzire');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 2, 'Și am îndepărtat de la tine povara ta[2],', '[2] Prin iertarea oricăror greșeli pe care le-ai făcut înainte. „Povara” se poate referi și la anxietatea resimțită de Profet (pacea și binecuvântarea lui Allah fie asupra sa) la începutul misiunii sale.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 3, 'Care-ți apăsa pe spinare?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 4, 'Și am înălțat pomenirea ta?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 5, 'Cu adevărat, alături de greu vine și ușorul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 6, 'Cu adevărat, alături de greu vine și ușorul!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 7, 'Iar atunci când vei termina [treburile tale], trudește [în adorare],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 8, 'Punându-ți [toată] speranța în Domnul tău!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 1, 'Pe smochini și pe măslini[1]', '[1] Făcându-se referire la locurile lor de creștere, Damasc și Ierusalim. Se poate referi și la smochini și la măslini sau la fructele în sine.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 2, 'Și pe Muntele Sinin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 3, 'Și pe această cetate sigură [Mecca]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 4, 'Noi l-am creat pe om cu cea mai frumoasă înfățișare[2],', '[2] Într-o formă simetrică și echilibrată');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 5, 'Apoi îl întoarcem pe el în locul cel mai de jos[3],', '[3] Se poate face referire la Iad sau vârstă înaintată sau imoralitate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 6, 'Fără de aceia care cred și împlinesc fapte bune, căci ei vor avea parte de răsplată neîntreruptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 7, 'După aceasta, ce te mai face să tăgăduiești Judecata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 8, 'Oare nu este Allah Cel mai Înțelept dintre judecători?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 1, 'Citește! În Numele Domnului tău care a creat [tot ceea ce există],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 2, 'Care l-a creat pe om din sânge închegat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 3, 'Citește! Domnul tău este Cel mai Nobil,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 4, 'Este Cel care l-a învățat cu calemul,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 5, 'L-a învățat pe om ceea ce el nu a știut!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 6, 'Dar nu! Omul întrece măsura,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 7, 'Când se vede el bogat!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 8, 'Însă, cu adevărat, la Domnul tău se află întoarcerea!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 9, 'Îl vezi tu pe cel care oprește [Abu Jahl]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 10, 'Un rob [Mohammed], când împlinește Rugăciunea?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 11, 'Dar dacă ar fi el [Mohammed] pe calea cea dreaptă [a lui Allah]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 12, 'Sau poruncind el evlavia?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 13, 'Și-l vezi tu când el [Abu Jahl] tăgăduiește sau întoarce spatele?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 14, 'Oare nu știe el că Allah Vede [ceea ce face]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 15, 'Dar nu! Dacă [Abu Jahl] nu va înceta, Noi îl vom apuca de smocul [de păr][1],', '[1] Poate să însemne „îl vom plesni” sau „îi vom face fața neagră”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 16, 'De smocul mincinos și păcătos!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 17, 'Să-i cheme el pe cei din preajma lui [ajutoarele sale]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 18, 'Iar Noi îi vom chema pe Îngerii Iadului.[2]', '[2] Care îi împing pe nelegiuiți în Foc');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 19, 'Nu! Nu-i da lui ascultare, ci prosternează-te și apropie-te [de Allah]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 1, 'Cu adevărat, Noi am pogorât [Coranul] în noaptea al-Qadr[1].', '[1] Noaptea „Hotărârii divine”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 2, 'Dar de unde să știi ce este noaptea al-Qadr?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 3, 'Noaptea al-Qadr este mai bună decât o mie de luni!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 4, 'În timpul ei se coboară Îngerii și Duhul [Gavriil], după Voia Domnului lor, pentru orice poruncă![2]', '[2] Ei aduc destinul pentru ceea ce este destinat să se întâmple în următorul an');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 5, 'Ea este Pace[3], până la ivirea zorilor!', '[3] Pentru credincioși');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Cei care nu au crezut dintre oamenii Cărții, ca și idolatrii, nu au încetat să nu creadă[1] până nu le-a venit lor Dovada cea limpede:', '[1] În credințele lor greșite și superstiții');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, 'Un Trimis din partea lui Allah, care să le citească foi curățite[2],', '[2] Ce nu conțin falsitate');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 3, 'În care sunt scripturi cu judecată dreaptă.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'Și nu s-au despărțit cei cărora le-a fost dată Cartea, decât după ce le-a venit lor dovada cea limpede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'Și nu li s-a poruncit decât să-L adore pe Allah, cu credință curată și statornică în religia Lui, să împlinească Rugăciunea [As-Salat] și să achite Dania [Az-Zakat]. Și aceasta este credința [comunității] celei drepte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Cu adevărat, cei care nu cred dintre oamenii Cărții, ca și idolatrii, în veci vor petrece în focul Iadului. Aceștia sunt cei mai răi dintre toate făpturile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'Cu adevărat, cei care cred și împlinesc fapte bune, sunt cei mai buni dintre toate făpturile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Răsplata lor de la Domnul lor sunt Grădinile Edenului, pe sub care curg pâraie, și în ele vor petrece veșnic, căci Allah este mulțumit de ei, iar ei sunt mulțumiți de El. Aceasta va fi pentru cel care se teme de Domnul său.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Când Pământul va fi zgâlțâit de cutremur [cel final]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 2, 'Și Pământul va scoate poverile lui[1]', '[1] A se vedea 84:4');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 3, 'Și omul va zice:[2] „Ce se întâmplă cu el?”,', '[2] De teroare');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 4, 'În ziua aceea, va spune el veștile ce le are,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 5, 'Pentru că Domnul tău îi va inspira lui.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 6, 'În Ziua aceea, oamenii vor ieși în cete, pentru ca să li se arate faptele lor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 7, 'Cel care a făcut un bine cât un grăunte de colb, îl va vedea,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 8, 'După cum, cel care a făcut un rău cât un grăunte de colb, îl va vedea.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 1, 'Pe alergătorii gâfâind[1],', '[1] Caii celor care se luptă pentru cauza lui Allah întrecându-se să atace dușmanul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 2, 'Ce scot scântei[2],', '[2] Din potcoavele lor în timp ce galopează pe pământul pietros');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 3, 'Și pornesc la atac dimineața[3],', '[3] În timp ce dușmanul nu știe');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 4, 'Stârnind colbul,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 5, 'Și pătrund cu el în mijlocul[4] mulțimii!', '[4] Spărgând rândurile dușmanului printr-un atac subit');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 6, 'Omul [necredincios] este nemulțumitor față de Domnul său!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 7, 'Și el este martor pentru aceasta[5].', '[5] Prin cuvintele și acțiunile sale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 8, 'Și iubirea lui pentru bogăție este puternică!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 9, 'Oare el nu știe că atunci când se va risipi ceea ce este în morminte [la momentul Învierii]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 10, 'Și se va dezvălui ceea ce este în piepturi[6],', '[6] Atunci când toate secretele sunt făcute cunoscute');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 11, 'Cu adevărat, atunci Domnul lor, în Ziua aceea, va fi Khabir [Bineștiutor] al lor?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 1, '„Ziua aceea care lovește” [Ora, Învierea]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 2, 'Ce este „Ziua aceea care lovește”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 3, 'Și de unde să știi tu ce este „Ziua aceea care lovește”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 4, 'În Ziua aceea, oamenii vor fi ca fluturii risipiți[1],', '[1] Astfel vor fi oamenii după ce vor fi aruncați din morminte');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 5, 'Iar munții vor fi ca lâna scărmănată![2]', '[2] Ce începe să se dezintegreze');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 6, 'Cât despre cel ale cărui balanțe vor fi grele [cu fapte bune],', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 7, 'El va avea parte de o viață plăcută,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 8, 'Iar cât despre cel ale cărui balanțe vor fi ușoare,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 9, 'Locul lui de veci va fi un abis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 10, 'Și de unde să știi tu ce este el?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 11, 'El este un Foc fierbinte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 1, 'Vă abate goana după înmulțire[1],', '[1] A bunurilor lumești');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 2, 'Până când veți vizita mormintele[2].', '[2] Veți rămâne în ele o perioadă temporară, până în Ziua Judecății');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 3, 'Nu! Voi veți ști curând!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 4, 'Și încă o dată: Nu! Voi veți ști curând!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 5, 'Nu! Dacă ați ști cu siguranță![3]', '[3] Concluzia acestui verset este „...voi nu ați fi fost distrași de la pregătirea pentru Viața de Apoi”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 6, 'Voi veți vedea Iadul!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 7, 'Încă o dată: Îl veți vedea, cu siguranță![4]', '[4] Cu proprii ochi');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 8, 'Apoi veți fi întrebați, în Ziua aceea, despre plăceri![5]', '[5] Despre confortul în viața lumească și dacă I-ați fost recunoscători lui Allah pentru binecuvântările Sale');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 1, 'Jur pe timp![1]', '[1] Un jurământ făcut de Allah pe timpul de-a lungul secolelor');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 2, 'Că omul va fi în pierdere,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 3, 'În afară de cei care cred și împlinesc fapte bune și se îndeamnă unul pe altul către Adevăr și se îndeamnă unul pe altul la răbdare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 1, 'Vai pentru tot clevetitorul și defăimătorul', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 2, 'Care strânge avere și o socotește[1],', '[1] Și nu o cheltuiește pe calea lui Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 3, 'Crezând că averea sa îl va face nemuritor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 4, 'Dar nu! El va fi aruncat în Al-Hutama[2]!', '[2] Focul Iadului, care distruge totul');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 5, 'Și de unde să știi tu ce este Al-Hutama?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 6, 'Focul aprins al lui Allah,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 7, 'Care se înalță peste inimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 8, 'El se va închide deasupra lor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 9, 'În coloane întinse[3]!', '[3] Interpretate a fi, fie coloane de foc, fie coloane de fier de care sunt legați oamenii în Iad');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 1, 'Oare n-ai văzut tu [o, Mohammed] ce a făcut Domnul tău cu oamenii elefantului?[1]', '[1] Armata sub comanda lui Abrahah al-Așram ce era însoțită de un elefant uriaș și care a venit cu intenția să distrugă Ka’bah la Mecca');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 2, 'Oare nu a făcut El vicleșugul lor să fie în deșert?[2]', '[2] I-a distrus');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 3, 'Și a trimis peste ei păsări în stoluri,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 4, 'Ca să arunce asupra lor cu pietre din lut ars!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 5, 'Și i-a făcut pe ei asemenea paielor mestecate[3].', '[3] Ca și cum ar fi fost mâncate de animale. Acest eveniment a avut loc în anul în care s-a născut Profetul (pacea și binecuvântarea lui Allah fie asupra sa).');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 1, 'Pentru obiceiul [poporului] Qurayș[1],', '[1] Allah i-a onorat făcându-i păzitorii Sfintei Ka’be, ceea ce le-a permis să călătorească fără a se teme că ar fi vătămați');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 2, 'Obiceiul lor pentru călătoria de iarnă și cea de vară[2],', '[2] Caravana comercială ce călătorea pe timpul iernii în sud și pe timpul verii în nord');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 3, 'Să-L adore ei pe Stăpânul acestei Case[3],', '[3] Ka’bah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 4, 'Care i-a hrănit pe ei, păzindu-i de foame, și i-a ferit pe ei de spaimă!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 1, 'Îl vezi tu pe cel care tăgăduiește Judecata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 2, 'El este cel care-l alungă pe orfan [cu duritate]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 3, 'Și nu încurajează hrănirea sărmanului.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 4, 'Și vai celor care fac Rugăciunea [fiind fără de grijă față de ea]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 5, 'Cei care întârzie Rugăciunea lor [până la timpul în care aceasta iese]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 6, 'Care sunt numai ipocriți[1]', '[1] Făcând Rugăciunea doar pentru a fi văzuți');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 7, 'Și opresc de la ajutor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 1, 'Cu adevărat, Noi ți-am dat ție [o, Mohammed] prisosință [al-Kawthar].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 2, 'Deci împlinește Rugăciunea pentru Domnul tău și jertfește [-I doar Lui]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 3, 'Cu adevărat, cel ce te urăște va fi fără copii[1]!', '[1] O altă interpretare este: „fără lucrurile bune în această viață și în Viața de Apoi”');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 1, 'Spune: „O, voi, necredincioșilor!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 2, 'Eu nu ador ceea ce voi adorați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 3, 'Și nici voi nu adorați ceea ce ador eu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 4, 'Și eu nu voi adora ceea ce voi adorați', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 5, 'Și nici voi nu veți adora ceea ce ador eu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 6, 'Voi aveți religia voastră, iar eu am religia mea!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 1, 'Când vine biruința lui Allah și cucerirea[1]', '[1] Orașului Mecca');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 2, 'Și-i vezi pe oameni intrând în religia lui Allah în cete,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 3, 'Atunci Slăvește-L cu Laudă pe Domnul tău și roagă-L pe El de iertare, fiindcă El este Tauuab [Iertător] [cu cel care se căiește]!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 1, 'Să piară mâinile lui Abu Lahab și să piară și el[1]!', '[1] Abu Lahab, unchiul Profetului (pacea și binecuvântarea lui Allah fie asupra sa), care era un dușman al islamului');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 2, 'Averea lui nu-i va fi de niciun folos și nici ce a agonisit!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 3, 'Va arde în Focul cu flăcări,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 4, 'Împreună cu muierea lui, aducătoarea de vreascuri[2],', '[2] Ea punea spini în calea Profetului (pacea și binecuvântarea lui Allah fie asupra sa) și îl batjocora. Cuvintele „vreascuri” erau folosite de către arabi pentru a face referire la batjocură și bârfă.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 5, 'Care va avea la gâtul ei o funie de fire [de palmier].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 1, 'Spune: „El este Allah, Cel Unic[1]!', '[1] Unul, Unic și Indivizibil');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 2, 'Allah-us-Samad[2]!', '[2] „Allah, Refugiul Etern” – care este căutat în timpuri dificile și la nevoie, de care depinde întreaga creație');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 3, 'El nu zămislește și nu este născut', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 4, 'Și El nu are pe nimeni egal!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 1, 'Spune: „Eu caut adăpost la Stăpânul revărsatului zorilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 2, 'Împotriva răului [venind] de la ceea ce El a creat', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 3, 'Și împotriva răului întunericului care se așterne', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 4, 'Și împotriva răului vrăjitoarelor care suflă în noduri[1]', '[1] Care fac magie');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 5, 'Și împotriva răului pizmuitorului, când pizmuiește.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 1, 'Spune: „Eu caut adăpost la Domnul oamenilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'Stăpânul oamenilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'Dumnezeul oamenilor', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'Împotriva răului ademenitorului fugar[1]', '[1] Un diavol care îi face sugestii rele omului, dar care dispare atunci când acesta Îl pomenește pe Allah');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'Care șoptește în piepturile oamenilor,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'Dintre djinni și oameni[2].”', '[2] Cei care fac sugestii rele pot fi și dintre oameni și dintre djinni');
